local P = LoreForeverPacks.Begin("LoreForever_Lang_deDE")
P.entries["quest:208"] = {n="Großwildjagd",s="Im Schlingendorntal steht Hemet Nesingwarys Jagd auf King Bangalash vor ihrer letzten Prüfung. Der berühmte Scharfschütze kam wegen des großen weißen Tigers in den Dschungel.",h="Im Schlingendorntal steht Hemet Nesingwarys Jagd auf King Bangalash vor ihrer letzten Prüfung.",kw={"bangalash","bhag'thera","großwildjagd","hemet nesingwary","sin'dall","schlingendorntal","tethis","weißer tiger"},ang={["class:Hunter"]="Als Jäger beweist Ihr Hemet Nesingwary mit dem Erlegen von King Bangalash Eure Meisterschaft im Fährtenlesen und in der Jagd."},sec={{t="Die Beute des Meisters",b="Ihr habt Sin'Dall, Bhag'thera und Tethis in den Prüfungen der Expeditionsjäger erlegt. Hemet Nesingwary kennt nun Euer Waffengeschick. Nur wenige haben ihm auf Lordaerons Schlachtfeldern oder tief im Dschungel größeres Können gezeigt.\n\nEine Jagd bleibt noch. Erlegt King Bangalash, den großen weißen Tiger, wegen dem Hemet zur Jagd aufbrach, und beweist, dass Eure Fähigkeiten unübertroffen sind."},{t="Eine sagenumwobene Bestie",b="King Bangalash lockte Hemet Nesingwary ins Schlingendorntal. Die gewaltige Bestie hat den Expeditionsleiter immer wieder geschlagen ins Lager zurückgetrieben. Ihr Kopf würde beweisen, dass Eure Jagdkunst unübertroffen ist."}},faq={{q="Wer vergibt diese Jagd?",a="Hemet Nesingwary vergibt diese Jagd in seinem Expeditionslager im nördlichen Schlingendorntal, nachdem Ihr die vorherigen Jagdmeisterprüfungen abgeschlossen habt.",al={"questgeber","wer startet großwildjagd","hemet nesingwary quest"}},{q="Welche Jagden müssen zuerst abgeschlossen werden?",a="Schließt zuerst alle drei Jagden für das Lager ab. Erlegt Sin'Dall in Tiger Mastery, Bhag'thera in Panther Mastery und Tethis in Raptor Mastery.",al={"voraussetzungen","welche quests kommen vor großwildjagd","bangalash voraussetzungen"}},{q="Warum will Hemet Nesingwary King Bangalash erlegen?",a="King Bangalash lockte Hemet ins Schlingendorntal. Der große weiße Tiger ist ihm wiederholt entkommen und hat den erfahrenen Scharfschützen mehr als einmal ins Lager zurückgetrieben.",al={"warum king bangalash","warum bangalash jagen","bangalash hintergrundgeschichte"}},{q="Welchen Beweis verlangt Hemet?",a="Hemet verlangt den Kopf von King Bangalash als Beweis dafür, dass Ihr den großen weißen Tiger erlegt habt.",al={"welchen gegenstand brauche ich","bangalash questziel","beweis der erlegung"}},{q="Wo hat Hemet seinen Worten nach schon Kämpfe erlebt?",a="Hemet vergleicht Euer Waffengeschick mit dem, was er auf Lordaerons Schlachtfeldern und tief im Dschungel gesehen hat. Er sagt, er habe selten Besseres gesehen.",al={"hemet kriegsgeschichte","hemet vergangenheit","lordaeron jäger"}}},fp="15,156,19.353.0,15.203.0,20.141.0,47.136.0,46.157.0,30.88.0,47.145.0"}
P.entries["quest:209"] = {n="Hauer der Skullsplitter",s="In Beutebucht hat Kebok Mühe, Bestellungen für Tigerfangzähne zu erfüllen, die für die südlichen Meere bestimmt sind. Echte Fangzähne sind zu teuer zu beschaffen, also hat er einen anderen Weg gefunden, die Nachfrage zu decken.",h="In Beutebucht hat Kebok Mühe, Bestellungen für Tigerfangzähne zu erfüllen, die für die südlichen Meere...",kw={"beutebucht","fälschung","kebok","schädelspalter","die südlichen meere","schlingendorntal","tigerfangzähne","hauer"},sec={{t="Ein lukrativer Ersatz",b="Keboks Handel mit Tigerfangzähnen für Käufer überall in den südlichen Meeren ist kostspielig geworden, und gewöhnliche Jagd liefert kaum noch genug Nachschub. Deshalb hat er einen Weg gefunden, hornartige Gegenstände zu überzeugenden Fangzähnen zu formen, ohne Spuren des Schwindels zu hinterlassen. Die Hauer der Schädelspaltertrolle kommen ihnen am nächsten. Kebok heuert Abenteurer an, dem Dschungelstamm für seine nächste Lieferung achtzehn davon abzunehmen."}},faq={{q="Warum braucht Kebok Hauer der Schädelspalter?",a="Genug echte Tiger für die Käufer in den südlichen Meeren zu jagen, ist zu teuer und schwierig geworden. Kebok kann Trollhauer zu überzeugenden Tigerfangzähnen formen, ohne Spuren zu hinterlassen, und so seine monatlichen Exportbestellungen erfüllen.",al={"warum hauer der schädelspalter","keboks plan mit den hauern","warum gefälschte tigerfangzähne"}},{q="Wer kauft die Fangzähne?",a="Handelspartner auf Inseln überall in den südlichen Meeren kaufen die gefälschten Fangzähne.",al={"wer kauft die hauer","käufer in den südlichen meeren","wohin gehen die fangzähne"}},{q="Wo steht diese Aufgabe in Keboks Questreihe?",a="Sie folgt auf Keboks frühere Bitte um Bloodscalp Ears.",al={"was kommt vor hauer der schädelspalter","voraussetzung für hauer der schädelspalter","keboks questreihenfolge"}}},fp="19,166,22.369.0,40.209.0,24.80.0,43.59.0"}
P.entries["quest:2098"] = {n="Gyromasts Rettung",s="Gelkak Gyromast braucht Eure Hilfe an der Küste der Dunkelküste. Sein mechanischer Erster Maat funktioniert nicht ohne einen Aufziehschlüssel, der an den Felsen zerbrach. Wildtiere und Murlocs haben seine drei Teile fortgetragen.",h="Gelkak Gyromast braucht Eure Hilfe an der Küste der Dunkelküste.",kw={"dunkelküste","erster maat","waldschreiter","gelkak gyromast","greymist","gyromasts rettung","pirat","riffkriecher","threshadon"},ang={["profession:Engineering"]="Als Ingenieur könnt Ihr ermessen, wie schwierig es ist, Uhrwerkapparaturen nach einem heftigen Schiffbruch im Salzwasser funktionstüchtig zu halten.",["race:Gnome"]="Als Gnom ist Euch vielleicht vertraut, dass Gelkak sich auf Uhrwerkgeräte statt auf Schiffskameraden aus Fleisch und Blut verlässt. Sein Piratenleben ist unter Euresgleichen ungewöhnlich."},sec={{t="Gestrandet an der Dunkelküste",b="An der Dunkelküste ist Gelkak Gyromast ein Gnomenpirat, der fernab der südlichen Meere gestrandet ist. Er sagt, aggressive Threshadons hätten sein Schiff direkt vor der Küste angegriffen und versenkt. Beim Schiffbruch wurde er inmitten des Treibguts an Land gespült, gestrandet und von seiner Mannschaft getrennt."},{t="Der geplünderte Schlüssel",b="Gelkaks erste Sorge gilt seinem Ersten Maat, weder Proviant noch Gold. Sein Gefährte braucht einen besonderen Schlüssel, um zu funktionieren, doch der Schlüssel zerbrach in drei Teile, als Gelkak an den felsigen Untiefen zerschellte. Riffkriecher am Strand, Waldschreiter nahe den Wäldern und Aasfresser der Greymist-Murlocs trugen die glänzenden Teile fort."},{t="Ein seltsamer Gefährte",b="Gelkak spricht mit der unerschütterlichen Treue eines Seekapitäns von seinem Ersten Maat. Er sagt, der Gefährte müsse wieder instand gesetzt werden, und der zerbrochene Schlüssel sei unerlässlich, um ihn wieder aufzuziehen."}},faq={{q="Wer ist Gelkak Gyromast?",a="Gelkak Gyromast ist ein Gnomenpirat, dessen Schiff von räuberischen Threshadons vor der Dunkelküste angegriffen und versenkt wurde.",al={"gelkak gyromast","wer ist der gnomenpirat","gnomenpirat dunkelküste"}},{q="Wozu dient der Schlüssel?",a="Der Schlüssel wird gebraucht, um Gelkaks mechanischen Ersten Maat wieder zu aktivieren und aufzuziehen, der beim Schiffbruch seinen Betrieb einstellte.",al={"warum braucht gelkak den schlüssel","gelkak schlüssel zweck","erster maat schlüssel"}},{q="Wo sind die drei Teile des Schlüssels geblieben?",a="Waldschreiter nahmen das obere Teil, Greymist-Murlocs das mittlere und Riffkriecher an der Küste das untere, nachdem der Schlüssel am Ufer zerbrochen war.",al={"wo sind die schlüsselteile","wer hat den schlüssel gestohlen","zerbrochener schlüssel dunkelküste"}},{q="Warum segelte ein Gnomenpirat nahe der Dunkelküste?",a="Gelkak segelte auf der Suche nach Beute vor der Küste des nördlichen Kalimdor, als feindselige Threshadons seine Reise beendeten.",al={"warum ist gelkak an der dunkelküste","piraten an der dunkelküste"}},{q="Was geschieht, nachdem der Schlüssel wieder zusammengesetzt wurde?",a="Mit allen drei Teilen seines Schlüssels kann Gelkak seinen Gefährten aufziehen und mit Gyromast's Revenge fortfahren.",al={"was kommt nach dem schlüssel","gyromasts rettung fortsetzung"}},{q="Wer sind die Murlocs, die das Schlüsselteil haben?",a="Greymist-Murlocs haben das mittlere Teil aufgelesen. Ihr Stamm lebt zwischen den Trümmern versunkener Schiffe entlang der Untiefen der Dunkelküste.",al={"dunkelküste murlocs","greymist-murloc schlüssel","schiffbruch murlocs"}}},fx={["460afe34"]={q="Warum möchte Gelkak Gyromast, dass sein Schlüssel repariert wird?",a="Gelkak Gyromast erlitt vor der Küste der Dunkelküste Schiffbruch, als Dreschadons sein Schiff versenkten. Gestrandet und umgeben von feindseliger Tierwelt, braucht er seinen mechanischen ersten Maat dringend wieder in funktionstüchtigem Zustand, um sich zu verteidigen und seine Rache an den Kreaturen zu üben, die seine Reise ruinierten. Ohne die drei zerbrochenen Teile des Aufziehschlüssels bleibt sein mechanischer Gefährte völlig regungslos.",al={"warum will gelkak den schlüssel","gelkak gyromast beweggrund","warum gelkak helfen"}},["234cb20d"]={q="Warum braucht Gelkak Gyromast Eure Hilfe?",a="Gelkak ist ein gestrandeter Pirat, dem keine Besatzung mehr zur Seite steht und der unter den örtlichen Nachtelfen keine Freunde hat. Er hat den Untergang seines Schiffes nur knapp überlebt und wurde übel zugerichtet an den Strand gespült, weshalb er nicht in der Verfassung ist, gegen die bösartigen Riffkriecher, Waldschreiter und Murlocs zu kämpfen, die seine zerbrochenen Schlüsselteile fortgeschleppt haben.",al={"warum wird man von gelkak gebraucht","warum kann gelkak den schlüssel nicht holen","warum man selbst gyromast helfen soll"}}},fp="20,189,21.241.0,17.309.0,20.172.1,23.101.0,25.113.0,41.142.0,46.104.0,42.104.1,42.122.0"}
P.entries["quest:21"] = {n="Scharmützel in der Echokammmine",s="Bei Echo Ridge schickt Euch Marschall McBride in eine von Kobolden überrannte Mine. Die Garnison fürchtet, dass sie ihre Stellung festigen, wenn man sie gewähren lässt.",h="Bei Echo Ridge schickt Euch Marschall McBride in eine von Kobolden überrannte Mine.",kw={"echo ridge","echokammmine","elwynn","kobold","arbeiter","marschall mcbride","mcbride","nordhain","scharmützel","armee von sturmwind"},ang={["class:Warrior"]="Als Krieger stellt Ihr Euch im Nahkampf scharenweise angreifenden Koboldarbeitern, die zu den ersten verschanzten Feinden gehören, denen Ihr begegnet.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, Minen zurückzuerobern, die Stein und Erz für den Wiederaufbau und die Befestigung menschlicher Siedlungen nach dem Krieg bergen.",["profession:Mining"]="Als Bergarbeiter helft Ihr, den sicheren Abbau wertvoller Mineraladern im gesamten Nordhaintal und das Verhütten der gewonnenen Erze zu ermöglichen.",["race:Human"]="Als Mensch ist die Säuberung von Echo Ridge Eure erste wahre Waffenprobe zur Verteidigung des Königreichs Eurer Vorfahren. Ihr beweist den Offizieren von Sturmwind Eure Tüchtigkeit."},sec={{t="Die Mine säubern",b="Kobolde graben tief in der Echokammmine, horten ihre Beute und werden immer zahlreicher. Lichtet jetzt ihre Reihen, bevor sie sich im Nordhaintal, auf seinen Höfen und an seinem geistlichen Rückzugsort ausbreiten."},{t="Eine schwache Verteidigung",b="McBride kann nur wenige Soldaten entbehren. Die Garnison bewacht die südlichen Grenzen, während Gerüchte über Unruhen in ganz Elwynn umgehen. Erweist Euch bei Echo Ridge als zuverlässig, und Ihr verdient Euch den Respekt der Armee und seid für schwierigere Aufgaben andernorts im Königreich gewappnet."}},faq={{q="Warum wird die Echokammmine von Kobolden heimgesucht?",a="Kobolde werden von mineralreichen Stollen und verlassenen Steinbrüchen angezogen. Da Sturmwinds Streitkräfte überlastet sind, dringen sie in unbewachte Orte wie Echo Ridge ein, um Baue zu graben, Gold zu horten und unterirdischen Unterschlupf zu beanspruchen.",al={"warum kobolde in der mine","echo ridge kobolde","was machen kobolde"}},{q="Wer befiehlt das Scharmützel?",a="Marschall McBride befiehlt das Scharmützel. Er befehligt die Truppen der Armee von Sturmwind in der Abtei von Nordhain und leitet mit begrenzter Mannschaftsstärke die Verteidigung des Tals.",al={"wer gibt die scharmützelquest","marschall mcbride befehle"}},{q="Welche strategische Bedeutung hat die Echokammmine?",a="Die Echokammmine birgt Stein und Erz, die für den Erhalt von Nordhain und den Wiederaufbau von Sturmwind benötigt werden. Kobolde an Nordhains nördlicher Grenze bedrohen die Abtei und die nahe gelegenen Weinberge.",al={"warum echo ridge wichtig ist","echokammmine bedeutung"}},{q="Wohin führt diese Mission als Nächstes?",a="Nachdem die ersten Koboldarbeiter aus der Mine vertrieben wurden, schickt Euch Marschall McBride nach Goldhain, um bei der Verteidigung der Region zu helfen.",al={"welche quest nach dem scharmützel","nächster schritt nach echo ridge"}},{q="Warum säubert die Armee von Sturmwind die Mine nicht selbst?",a="Sturmwinds Streitkräften fehlen Soldaten, da sie ferne Grenzen verteidigen und auf Banditenangriffe in ganz Elwynn reagieren. McBride verlässt sich bei örtlichen Bedrohungen auf neue Rekruten, während erfahrene Wachen die Verteidigungslinien halten.",al={"warum rekruten","wo sind sturmwinds soldaten"}},{q="Sind Kobolde klug genug, um eine organisierte militärische Bedrohung darzustellen?",a="Koboldarbeiter sind allein feige und einfältig, doch in großer Zahl verteidigen sie ihr Revier und werden aggressiv. Lässt man sie gewähren, graben sie gewundene Tunnel, stellen Fallen in Höhlen auf und locken größeres, besser bewaffnetes Ungeziefer an.",al={"sind kobolde klug","kobolde gefahrenstufe"}}},fx={a391cdc3={q="Warum möchte Marschall McBride, dass die Kobolde in der Echokammmine dezimiert werden?",a="Marschall McBride weiß, dass die Kobolde in der Echokammmine umso tiefer in Nordhain Fuß fassen, je länger sie ungehindert bleiben. Sie in Ruhe zu lassen lädt sie dazu ein, sich weiter zu verschanzen und das Tal zu bedrohen, was ihre spätere Vertreibung weitaus blutiger machen würde und die Sicherheit der Abtei von Nordhain selbst gefährdet.",al={"warum kobolde in der echokammmine töten","mcbride beweggrund echokammmine","warum echokammmine räumen"}}},fp="22,134,16.190.0,14.235.0,46.210.0,24.149.0,52.176.0,34.132.0,57.211.0,66.194.0"}
P.entries["quest:210"] = {n="Kochen mit Krazek",s="In Beutebucht hat Corporal Kaleb einen kaputten Topf, der repariert werden muss. Er bittet Euch, den mechanischen Kochtopf, den er einem Goblinhändler abgekauft hat, zu Krazek zu bringen.",h="In Beutebucht hat Corporal Kaleb einen kaputten Topf, der repariert werden muss.",kw={"beutebucht","corporal kaleb","kochtopf","krazek","schlingendorntal"},sec={{t="Ein kaputter Topf",b="Corporal Kaleb übernimmt den Großteil des Kochens für das Lager. Bevor er einem Goblinhändler in Beutebucht einen mechanischen Topf abkaufte, dauerte das Kochen Stunden. Der Topf ersparte ihm diese Arbeit, bis er kaputtging. Nun bittet er Euch, Krazeks Spezialtopf zu Krazek zu bringen, dem Goblin, der ihn reparieren kann."},{t="Krazek sieht nach",b="Krazek nennt den Topf ein ausgeklügeltes Werk, auch wenn eine Feder herausspringen oder ein Zahnrad durchrutschen kann. Bei der Untersuchung stellt er fest, dass der Dampflader durchgerostet ist, die Knöcheldichtung Risse hat und dem Fobulator Zähne fehlen. Krazek kann ihn wieder herrichten, aber die Reparaturen haben ihren Preis."}},faq={{q="Wer schickt Euch zu Krazek?",a="Corporal Kaleb schickt Euch zu Krazek. Kaleb übernimmt den Großteil des Kochens für das Lager, und der mechanische Topf, den er gekauft hat, ist kaputtgegangen.",al={"wer vergibt kochen mit krazek","wer startet kochen mit krazek","corporal kaleb quest"}},{q="Wo ist Krazek zu finden?",a="Krazek ist ein Goblinhändler in Beutebucht, wo er Kaleb den Topf verkauft hat.",al={"wo ist krazek","krazek standort","krazek beutebucht"}},{q="Was sollt Ihr für Corporal Kaleb zu Krazek bringen?",a="Kaleb bittet Euch, Krazeks Spezialtopf zu bringen, einen mechanischen Kochtopf, der kaputtging, nachdem er ihm viele Stunden Arbeit erspart hatte.",al={"was ist krazeks spezialtopf","was bringe ich krazek"}},{q="Warum hat Kaleb bei Krazek einen Kochtopf gekauft?",a="Kaleb übernimmt den Großteil des Kochens für das Lager, und der Topf ersparte ihm viele Stunden Arbeit, bis er kaputtging.",al={"warum mechanischer kochtopf","kaleb kochtopf"}}},fp="16,145,12.269.0,19.247.1,24.127.0,26.71.0,48.116.0,44.99.0"}
P.entries["quest:2118"] = {n="Verseuchtes Land",s="Die Tierwelt der Dunkelküste erliegt einer schleichenden Krankheit, und Tharnariun Baumwahrer sucht nach einem Weg, sie zu retten. Er bittet Euch, einen tollwütigen Distelbären mit einem verzauberten Relikt zu beruhigen und lebend zurückzubringen.",h="Die Tierwelt der Dunkelküste erliegt einer schleichenden Krankheit, und Tharnariun Baumwahrer sucht nach...",kw={"cleansing of the infected","dunkelküste","verseuchtes land","wütender distelbär","tharnariun baumwahrer","tharnariuns hoffnung","distelbär"},ang={["class:Druid"]="Als Druide teilt Ihr Tharnariuns Trauer, während die Natur der Verderbnis anheimfällt. Der tragische Verlust des Bären zeigt, wie weit sich die Krankheit im Land ausgebreitet hat.",["faction:Alliance"]="Als Reisender der Allianz im Norden Kalimdors steht Ihr einer ungezähmten Verderbnis gegenüber, die gegen die Grenzen besiedelter Gebiete drängt.",["race:NightElf"]="Als Nachtelf seht Ihr, wie die heimische Pflanzen- und Tierwelt der Dunkelküste tollwütigem Wahnsinn verfällt. Das ist ein Frevel an Cenarius und am Gleichgewicht der Natur, das Ihr zu schützen geschworen habt."},sec={{t="Eine Seuche in der Wildnis",b="Eine schleichende Krankheit verwandelt die Tiere der Dunkelküste in wahnsinnige, gewalttätige Kreaturen. Distelbären leiden am stärksten darunter, und ihre Raserei bedroht Reisende und das empfindliche Gleichgewicht der Küste. Die Schildwachen der Nachtelfen antworten mit Stahl, während Druiden versuchen, die Krankheit zu verstehen und ihre Ursache zu heilen."},{t="Tharnariuns Hoffnung",b="Tharnariun Baumwahrer will die verderbten Tiere nicht töten, ohne zuvor zu versuchen, sie zu retten. Er hat eine Falle namens Tharnariuns Hoffnung angefertigt. Auf dem Waldboden aufgestellt, beruhigt ihr besänftigendes Licht kurzzeitig einen rasenden Distelbären. Der besänftigte Bär folgt Euch zurück zu Tharnariuns Außenposten, um dort untersucht zu werden."},{t="Tragische Heilkunst",b="Wenn ein infizierter Bär das Lager erreicht, versucht Tharnariun, seine Krankheit mit wiederherstellender Magie zu vertreiben. Sein erster Versuch endet in einer Katastrophe. Die reinigenden Energien überwältigen das geschwächte Tier, und es bricht zusammen und stirbt. Der Fehlschlag zeigt, wie tief die finstere Seuche bereits Fuß gefasst hat."}},faq={{q="Wer vergibt die Quest Verseuchtes Land?",a="Tharnariun Baumwahrer, ein Nachtelfendruide in Auberdine, bittet Euch um Hilfe. Er sucht ein Heilmittel für die erkrankten Tiere der Dunkelküste.",al={"questgeber verseuchtes land","tharnariun dunkelküste quest","wer startet verseuchtes land"}},{q="Was ist das Ziel von Verseuchtes Land?",a="Benutzt Tharnariuns Hoffnung, um einen wütenden Distelbären an der Dunkelküste zu fangen und zu beruhigen, und führt ihn dann lebend zu Tharnariun zurück.",al={"verseuchtes land ziel","was ist in verseuchtes land zu tun","wie bären an der dunkelküste fangen"}},{q="Was geschieht mit dem Bären, wenn Ihr ihn zurückbringt?",a="Tharnariun versucht, den Bären mit Heilmagie zu reinigen, doch die Krankheit ist zu weit fortgeschritten. Die Belastung überwältigt ihn, und er stirbt nach der Behandlung.",al={"stirbt der bär","tharnariun bärenheilung ergebnis","bärentod verseuchtes land"}},{q="Welchen Gegenstand benutzt Ihr, um den Bären zu fangen?",a="Tharnariun stellt Euch Tharnariuns Hoffnung zur Verfügung, eine verzauberte Falle. Ihr beruhigendes Licht besänftigt den aufgebrachten Bären, sodass er Euch folgt.",al={"verseuchtes land falle","tharnariuns hoffnung gegenstand","bärenkäfig dunkelküste"}},{q="Welche Quest folgt auf Verseuchtes Land?",a="Auf Verseuchtes Land folgt Cleansing of the Infected, danach kommt Tharnariuns Hoffnung.",al={"nächste quest nach verseuchtes land","verseuchtes land questreihe","tharnariun folgequest"}},{q="Warum sind die Distelbären tollwütig?",a="Eine schleichende Seuche breitet sich an der Dunkelküste aus, vergiftet die heimische Tierwelt und treibt Distelbären zu blinder Angriffslust.",al={"warum sind bären an der dunkelküste krank","dunkelküste seuche bären","dunkelküste verderbnis"}}},fx={bbb593c2={q="Warum möchte Tharnariun Baumwahrer, dass Ihr einen tollwütigen Distelbären fangt?",a="Eine dunkle Krankheit breitet sich über die Dunkelküste aus und ergreift Geist und Körper der örtlichen Tierwelt. Die Distelbären hat es am schlimmsten getroffen; sie verwandelten sich von edlen Waldtieren in rasende Zerstörungsmaschinen. Tharnariun Baumwahrer glaubt, er könnte ein Heilmittel für das Leiden entwickelt haben, aber er braucht ein lebendes, tollwütiges Subjekt, das direkt zu ihm gebracht wird, damit er sein Heilmittel testen und die Verderbnis aufhalten kann, bevor sie alle Kreaturen des Waldes befallen hat.",al={"warum distelbären fangen","tharnariun beweggrund plagued lands","warum will tharnariun einen bären"}},["1b7f183c"]={q="Was sind tollwütige Distelbären und warum jagt Ihr sie?",a="Distelbären sind heimische Raubtiere der Dunkelküste, die normalerweise als standhafte und edle Bestien verehrt werden. Jedoch hat eine unnatürliche Ansteckung kürzlich ihre Reihen infiziert, sie in einen wahnsinnigen Rausch getrieben und ihren Verstand verzerrt. Ihr werdet nicht ausgesandt, um sie einfach abzuschlachten, sondern um ein krankes Exemplar mit Tharnariuns Falle anzulocken und zu beruhigen, damit es sicher untersucht werden kann, in der Hoffnung, ein Gegenmittel zu entwickeln.",al={"was sind tollwütige distelbären","warum tollwütige distelbären jagen","tollwütiger distelbär dunkelküste"}}},fp="13,195,26.284.0,17.281.0,15.276.1,34.128.0,39.114.0,48.154.1,41.126.0,33.80.0,32.126.0"}
P.entries["quest:213"] = {n="Feindliche Übernahme",s="In Beutebucht zieht Gelriz in Feindliche Übernahme mit seinem jüngsten Vorstoß Baron Revilgaz' Zorn auf sich. Gelriz hat von den Handelsprinzen ernannte Moguln verdrängt und geht nun gegen den berüchtigtsten aller Piraten vor. Kebok schickt Euch los, seltsame blaue Kristalle zu stehlen, die Geologen der Venture Company nahe dem Nazferitisee gefunden haben.",h="In Beutebucht zieht Gelriz in Feindliche Übernahme mit seinem jüngsten Vorstoß Baron Revilgaz' Zorn auf sich.",kw={"beutebucht","gelriz","gigglefont","kebok","der nazferitisee","revilgaz","getrommelter kristall","venture co."},sec={{t="Eine Geschäftsangelegenheit",b="Baron Revilgaz erlaubt Kebok, die Beleidigung nach eigenem Ermessen zu vergelten. Kebok entscheidet sich für Diebstahl und nimmt die seltsamen blauen Steine ins Visier, die Bergbautrupps der Venture Company ausgegraben haben."},{t="Der Vorrat der Geologen",b="Geologen der Venture Company, die rund um den Nazferitisee arbeiten, zeigen großes Interesse an den ungewöhnlichen Kristallen. Kebok möchte, dass Ihr acht Proben nach Beutebucht zurückbringt. Wie Ihr sie beschafft, kümmert ihn wenig, solange sie in seinen Händen landen."},{t="Eine getrommelte Entdeckung",b="Die zurückgebrachten Kristalle wurden getrommelt, was darauf hindeutet, dass die Venture Company sie als Brennstoff oder industriellen Katalysator verwenden will. Kebok plant, Proben zur genaueren Untersuchung an Head Chemist Gigglefont zu schicken."}},faq={{q="Wer vergibt die Quest Feindliche Übernahme?",a="Kebok in Beutebucht im Schlingendorntal erteilt Euch diesen Auftrag im Namen von Baron Revilgaz.",al={"feindliche übernahme questgeber","wer startet feindliche übernahme","kebok quest"}},{q="Warum ist Baron Revilgaz wütend auf Gelriz?",a="Gelriz hat von den Handelsprinzen ernannte Moguln verdrängt und ist nun gegen den berüchtigtsten aller Piraten vorgegangen. Baron Revilgaz wird das nicht dulden.",al={"warum revilgaz wütend","gelriz revilgaz konflikt","warum will kebok kristalle"}},{q="Wo befinden sich die Kristalle?",a="Geologen der Venture Company, die rund um den Nazferitisee arbeiten, tragen die Kristalle bei sich.",al={"wo getrommelte kristalle finden","getrommelter kristall fundort","nazferitisee kristalle"}}},fp="16,308,20.175.0,21.243.0,20.197.1,37.96.0,40.147.0,31.76.0"}
P.entries["quest:2138"] = {n="Ausrottung der Infizierten",s="An der Dunkelküste bittet Euch Tharnariun Baumwahrer, die infizierten Distelbären aufzuhalten. Sein Versuch, einen zu reinigen, schlug fehl, und er fürchtet, dass die tollwütigen Bestien anderen Kreaturen schaden und die Krankheit verbreiten werden.",h="An der Dunkelküste bittet Euch Tharnariun Baumwahrer, die infizierten Distelbären aufzuhalten.",kw={"auberdine","ausrottung","dunkelküste","infizierte","tollwütiger distelbär","tharnariun","baumwahrer"},ang={["class:Druid"]="Als Druide mag Euch Tharnariuns Befehl schmerzen. Es ist ein Akt der Gnade und der Fürsorge für den Wald, keine gewöhnliche Jagd.",["class:Hunter"]="Als Jäger wisst Ihr, dass das Töten kranker Raubtiere das gesamte Ökosystem schützen kann, selbst wenn die Ursache unbekannt bleibt.",["race:NightElf"]="Als Kaldorei tragt Ihr die Last, die Tötung verdorbener Bestien anzuordnen. Seit dem Krieg ist die Krankheit tief in Eure angestammte Heimat vorgedrungen."},sec={{t="Eine bittere Notwendigkeit",b="Tharnariun Baumwahrer hat nach einem Heilmittel gegen die Krankheit in der Tierwelt der Dunkelküste gesucht. Er versuchte, einen gefangenen Bären zu reinigen, doch die Distelbären bleiben krank und gewalttätig. Deshalb bittet er Euch, sie zu töten, bevor sie andere Kreaturen zerfleischen oder die Krankheit tiefer in die uralten Wälder tragen."},{t="Die Wildnis im Zaum",b="Tharnariun bittet Euch, zwanzig tollwütige Bären zu töten, obwohl er weiß, dass dies die Seuche nicht heilen wird. Die Tötungen verschaffen den Verteidigern von Auberdine Zeit. Bis jemand die Quelle der Verderbnis des Waldes findet und ausschaltet, kann die Siedlung die aggressiven Herden und ihre Gefahren nur so zurückhalten."}},faq={{q="Warum will Tharnariun die Distelbären töten lassen, statt sie zu heilen?",a="Tharnariun versuchte, einen gefangenen Bären zu reinigen, doch die Heilung schlug fehl und die Bestie starb. Nun bedrohen die kranken Bären andere Kreaturen, daher ist ihre Tötung sein letzter Ausweg, um die Ausbreitung der Krankheit zu verlangsamen.",al={"warum die bären töten","warum bären nicht heilen","tharnariun bärenquest"}},{q="Wer ist Tharnariun Baumwahrer?",a="Tharnariun ist ein Nachtelfenpfleger in Auberdine. Er untersucht die Leiden, die Pflanzen und Tiere der Dunkelküste befallen, und arbeitet daran, das Gleichgewicht der Natur gegen die sich ausbreitende Verderbnis zu bewahren.",al={"tharnariuns rolle","wer vergibt ausrottung der infizierten"}},{q="Beendet das Töten der tollwütigen Bären tatsächlich die Seuche?",a="Nein. Tharnariun warnt, dass das Töten der tollwütigen Bären die Seuche nicht aufhalten wird. Es verschafft dem Wald und den Bewohnern von Auberdine Zeit, indem es die Ausbreitung von Infektion und Gewalt verlangsamt.",al={"wird dadurch die dunkelküste geheilt","ist die seuche geheilt"}},{q="Was kommt nach Ausrottung der Infizierten?",a="Nachdem Ihr Bericht erstattet habt, bittet Tharnariun Euch, Euch auf weiteres Blutvergießen vorzubereiten, und bietet Tharnariuns Hoffnung an, das den Kampf gegen die befallene Tierwelt fortsetzt.",al={"nächste quest nach ausrottung","was folgt auf ausrottung der infizierten"}},{q="Wo sind die tollwütigen Distelbären zu finden?",a="Tollwütige Distelbären durchstreifen die Küstenwälder und die Wälder im Landesinneren der mittleren Dunkelküste, zwischen den nebligen Kiefern südlich und östlich von Auberdine.",al={"fundort tollwütiger distelbären","wo sind bären an der dunkelküste"}},{q="Was hat die Distelbären tollwütig gemacht?",a="Ein geheimnisvoller Makel, der sich durch die Wälder des nördlichen Kalimdor ausbreitet, hat die Bären verdorben. Er verwandelte friedliche Wildtiere in rasende, aggressive Bestien, die Tharnariuns Heilungsversuch nicht heilen kann.",al={"warum sind bären krank","bärenkrankheit dunkelküste"}}},fx={acd0862d={q="Was sind tollwütige Distelbären und warum müssen sie getötet werden?",a="Distelbären sind heimische Waldraubtiere, die normalerweise in Harmonie mit der Wildnis der Dunkelküste leben. Eine schleichende, unnatürliche Seuche jedoch, die sich durch die Wälder ausbreitet, hat viele von ihnen tollwütig und gewalttätig-wahnsinnig gemacht. In ihrem verpesteten Wahnsinn greifen diese kranken Bestien andere Tiere an, bedrohen Reisende in der Nähe von Auberdine und verwüsten die Ökologie des Waldes. Da Versuche, ihr Leiden zu heilen, fehlgeschlagen sind, ist das Töten der einzige Weg, die Verwüstung einzudämmen.",al={"tollwütige distelbären","wer sind tollwütige distelbären","warum tollwütige distelbären töten"}}},fp="25,196,18.299.0,20.306.1,67.199.0,29.187.0,53.174.0,43.165.0,40.128.0,42.197.0"}
P.entries["quest:2139"] = {n="Tharnariuns Hoffnung",s="In Auberdine nimmt Tharnariun Baumwahrers Kampf gegen die Wildtierkrankheit eine düstere Wendung. Reisende haben infizierte Bestien in der ganzen Dunkelküste getötet, und nun schickt er einen Champion der Allianz gegen die tollwütige Den Mother nordöstlich des Ortes aus.",h="In Auberdine nimmt Tharnariun Baumwahrers Kampf gegen die Wildtierkrankheit eine düstere Wendung.",kw={"auberdine","bashal'aran","cleansing of the infected","dunkelküste","den mother","tollwütiger thistle bear","tharnariun baumwahrer","tharnariuns hoffnung"},ang={["class:Druid"]="Als Druide bringt Ihr Bären durch die Lehren von Ursoc große spirituelle Achtung entgegen. Eine verderbte Den Mother zu töten, erinnert Euch an das empfindliche Gleichgewicht der Natur und die Tragödien der Verderbnis.",["class:Hunter"]="Als Jäger versteht Ihr die Tragik eines Spitzenprädators, den eine Krankheit in den Wahnsinn getrieben hat. Ihr wisst, dass das Töten einer infizierten Bestie der wahrhaftigste Akt der Gnade sein kann.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, Auberdine zu schützen und den Stützpunkt der Allianz an der Küste des nördlichen Kalimdor zu stärken. Ihr verteidigt die Gebiete der Nachtelfen gegen wachsende Bedrohungen aus der Wildnis.",["race:NightElf"]="Für Nachtelfen verletzt das Töten von Waldtieren, besonders einer Bärenmatriarchin, ihre tiefe Ehrfurcht vor der Natur. Diese Pflicht ist bitter und schmerzlich."},sec={{t="Eine tragische Notwendigkeit",b="Seit dem Dritten Krieg macht eine unnatürliche Krankheit die wilden Kreaturen der Dunkelküste tollwütig. Tharnariun Baumwahrer ist in Auberdine stationiert, wo er Reisende gebeten hat, infizierte Bestien zu töten und das Leid des Waldes zu lindern. Doch das Töten tollwütiger Thistle Bears behandelt nur ein Symptom. Tharnariun beschließt, dass der Ursprung unter den einheimischen Bären beseitigt werden muss: ihre Matriarchin, die Den Mother."},{t="Die Den Mother",b="Die Den Mother lauert in einer Höhle nordöstlich von Auberdine, nahe den uralten Ruinen von Bashal'Aran. Einst eine Beschützerin der Waldtiere, wurde sie von dem Leiden verzehrt, das sich im nördlichen Kalimdor ausbreitete. Sie brachte immer weitere Würfe tollwütiger Jungen zur Welt und zog sie auf. Helden der Allianz machten sie in ihrem Bau ausfindig, beendeten ihre Qualen und dämmten die Flut rasender Bären ein, die auf der Küstenstraße umherstreiften."},{t="Kalimdors düstere Wirklichkeit",b="Tharnariun spricht nach dem Tod der Den Mother seinen tiefen Dank aus, doch Melancholie überschattet seine Worte. Für die Kaldorei ist es eine Qual, Waffen gegen Waldkreaturen zu erheben. Finstere Mächte bedrängen ihre neue Heimat, und viele verzweifeln oder suchen Zuflucht. Die Verteidiger von Auberdine nehmen die schwere Last auf sich, ihre Wildnis zu schützen."}},faq={{q="Wer ist Tharnariun Baumwahrer?",a="Tharnariun Baumwahrer ist ein nachtelfischer Hüter, der in Auberdine stationiert ist. Die Seuche und der Wahnsinn, die die Tierwelt der Dunkelküste entstellen, erschüttern ihn zutiefst, und er leitet die Bemühungen, die leidenden Tiere zu untersuchen, aufzuspüren und schließlich von ihren Qualen zu erlösen.",al={"tharnariun","wer vergibt tharnariuns hoffnung","baumwahrer auberdine"}},{q="Wo befindet sich die Den Mother?",a="Die Den Mother lebt in einer Höhle in den Hügeln nordöstlich von Auberdine, unmittelbar östlich der Ruinen von Bashal'Aran.",al={"wo ist die den mother","höhle der den mother fundort","den mother finden"}},{q="Warum muss die Den Mother getötet statt geheilt werden?",a="Das Leiden, das die Tierwelt der Dunkelküste verheert, ergreift die Bestien und treibt sie in gewalttätige Raserei. Da keine Heilung in Sicht ist und die Den Mother tollwütigen Nachwuchs aufzieht, sieht Tharnariun in ihrem Tod den einzigen Weg, die weitere Ausbreitung der Krankheit aufzuhalten.",al={"kann die den mother gerettet werden","warum die den mother töten","den mother heilen"}},{q="Welche Quests führen zu Tharnariuns Hoffnung?",a="Drei Teile führen zu Tharnariuns Hoffnung. Die Questreihe beginnt mit 'Plagued Lands', geht mit 'Cleansing of the Infected' weiter und endet mit 'Tharnariuns Hoffnung'.",al={"voraussetzungen für tharnariuns hoffnung","questreihe tharnariun"}},{q="Was macht die Tiere der Dunkelküste krank?",a="Tharnariun nennt keine Ursache. Er weiß nur, dass sich eine Krankheit an der Dunkelküste ausbreitet und Geist und Körper aller ergreift, die sie befällt. Thistle Bears hat es am schwersten getroffen.",al={"warum sind bären an der dunkelküste tollwütig","ursache der tierseuche an der dunkelküste","was hat die bären verderbt"}},{q="Warum erwähnt Tharnariun Menschen, die in befestigte Gebiete fliehen?",a="Auberdine ist ein ungeschützter Küstenaußenposten, bedrängt von Geistern, verderbten Wildtieren und feindseligen Kreaturen. Die Zivilisation der Nachtelfen ringt nach dem Einfall der Brennenden Legion um ihren Wiederaufbau, und manche Bewohner fühlen sich überfordert und verstecken sich oder ziehen sich in sicherere Bastionen der Allianz zurück.",al={"flucht aus auberdine","befestigte gebiete der allianz"}}},fx={f873ab28={q="Wer ist die Höhlenmutter?",a="Die Höhlenmutter ist ein massiver, verderbter Bär, der in einer Höhle nordöstlich in der Nähe der Ruinen von Bashal'Aran haust. Sie ist die Quelle, die die tollwütigen Distelbären gebärt oder beherbergt, die die Region plagen. Sie zu erschlagen stoppt den Zustrom kranker Bestien, die Auberdine bedrohen.",al={"was ist die höhlenmutter","wer ist die höhlenmutter","höhlenmutter dunkelküste"}}},fp="17,235,18.381.0,14.390.1,28.324.0,29.234.0,32.107.0,51.259.0,41.159.0,45.176.0,63.268.0"}
P.entries["quest:214"] = {n="Rote Seidenkopftücher",s="In den Todesminen schickt Späherin Riell die Volksmiliz auf die Suche nach Roten Seidenkopftüchern. Ihr feines Gewebe kennzeichnet die Anführer der Defias, die den Aufstand in Westfall lenken.",h="In den Todesminen schickt Späherin Riell die Volksmiliz auf die Suche nach Roten Seidenkopftüchern.",kw={"die todesminen","bruderschaft der defias","mondbruch","volksmiliz","rote seidenkopftücher","späherin riell","van cleef","westfall"},ang={["class:Rogue"]="Als Schurke wisst Ihr, dass rote Seide erfahrene Halsabschneider und heimliche Verschwörer kennzeichnet, ganz in der Tradition der Unterweltmethoden der Defias.",["faction:Alliance"]="Als Verbündeter der Allianz bedeutet jeder in den Todesminen gefällte Offizier für Euch einen Befehlshaber der Bruderschaft weniger in Sturmwinds Kornkammer.",["profession:Tailoring"]="Als Schneider wisst Ihr, dass feine rote Seide für gewöhnliche Banditen zu teuer ist. Ihre Verwendung zeigt, wie üppig die Führung der Bruderschaft ausgestattet und finanziert ist."},sec={{t="Eine Rangordnung aus Stoff",b="Späherin Riell und die Volksmiliz haben herausgefunden, dass Stoff den Rang in der Bruderschaft der Defias kennzeichnet. In ganz Westfall binden sich gewöhnliche Beutelschneider und Wegelagerer groben roten Stoff vor das Gesicht. Hochrangige Verschwörer und Agenten des inneren Kreises tragen feine rote Seide. Ihre Kopftücher zu erbeuten, trifft die erfahrenen Offiziere, die Edwin van Cleefs Aufstand koordinieren."},{t="Ein Schlag ins Herz",b="Die hochrangigen Gesetzlosen versammeln sich tief in den Todesminen unter Mondbruch. Schildwachen und Späher außerhalb der Späherkuppe verlassen sich auf freischaffende Helden, die in die umkämpften Tunnel vordringen. Jedes erbeutete Seidenkopftuch bedeutet einen Leutnant weniger, der Hinterhalte organisiert, Waffenlager bewacht oder van Cleefs Herrschaft in ganz Westfall durchsetzt."}},faq={{q="Warum tragen die Defias rote Kopftücher?",a="Die Defias tragen rote Kopftücher, um ihre Gesichter zu verbergen und ihre Treue zu Edwin van Cleefs Rebellion zu zeigen. Der Stoff kennzeichnet ihre Bruderschaft in den Gebieten von Sturmwind.",al={"bedeutung der defiasmasken","warum rote masken","uniform der defias"}},{q="Was unterscheidet die roten Seidenkopftücher von gewöhnlichen Kopftüchern?",a="Späherin Riell sagt, dass das Gewebe den Rang innerhalb der Bruderschaft kennzeichnet. Gewöhnliche Straßenschläger tragen groben, billigen Stoff, während Veteranen, Offiziere und vertrauenswürdige Leutnants rote Seide tragen.",al={"warum rote seide","seide oder stoff bei defias","unterschied bei seidenkopftüchern"}},{q="Wer ist Späherin Riell?",a="Späherin Riell dient der Volksmiliz in Westfall. Die Agentin verfolgt die Bewegungen der Defias und schickt Abenteurer gegen deren Stützpunkte rund um die Todesminen.",al={"späherin riell westfall","wer vergibt den auftrag rote seidenkopftücher"}},{q="Wo befinden sich die Defias mit Seidenkopftüchern?",a="Defias mit Seidenkopftüchern versammeln sich in und um die Todesminen unter Mondbruch. Edwin van Cleefs hochrangige Gefolgsleute überwachen dort die Unternehmungen unter Tage.",al={"wo seidenkopftücher finden","seidenkopftücher fundort todesminen"}},{q="Was ist die Volksmiliz?",a="Die Volksmiliz ist eine freiwillige Verteidigungstruppe, die Gryan Starkmantel und die bedrängten Bauern Westfalls gegründet haben. Sie schützen ihr Land, nachdem die Armee von Sturmwind nicht genügend Garnisonen bereitgestellt hat.",al={"wer ist die volksmiliz","volksmiliz westfall"}},{q="Haben diese Kopftücher einen anderen Nutzen, als eine Tötung zu beweisen?",a="Für die Volksmiliz beweisen die Kopftücher, dass hochrangige Gesetzlose ausgeschaltet wurden. Jedes einzelne schwächt die Befehlsstruktur der Bruderschaft.",al={"kann man rote seidenkopftücher tragen","wozu dienen die kopftücher"}}},fx={["09c03d28"]={q="Warum möchte Späherin Riell, dass Rote Seidenbandanas gesammelt werden?",a="Späherin Riell versucht, im Namen der Volksmiliz einen entscheidenden Schlag gegen die Führung von The Defias Brotherhood zu führen. Die Miliz weiß, dass Seidenbandanas eher ranghohe Offiziere als bloße Schläger kennzeichnen. Indem sie diese Schlüsselfiguren eliminiert und ihre Bandanas als Beweis fordert, hofft Riell, die Kommandostruktur der Bruderschaft zu zerschlagen und Westfall endlich für seine Bewohner zurückzugewinnen.",al={"warum scout riell bandanas","späherin riell beweggrund","warum rote seidenbandanas sammeln"}},["762e9a74"]={q="Gegen wen werdet Ihr ausgesandt?",a="Ihr jagt die Eliteoffiziere und Veteranen von The Defias Brotherhood, die in und um Edwin van Cleefs Festung innerhalb der Todesminen stationiert sind. Anders als die groben Halsabschneider, die durch Westfalls Farmen streifen, bewachen diese ranghohen Mitglieder die Operationsbasis der Bruderschaft, beaufsichtigen die versteckten Arbeiten tief unter Mondbruch und leiten die Operationen des Syndikats in der gesamten Region.",al={"wen jagen wir","rotes seidenbandana ziel","wer lässt seidenbandanas fallen"}},["966e78fe"]={q="Warum fragt Späherin Riell Euch anstelle der Wachen von Sturmwind?",a="Sturmwind hat Westfall praktisch aufgegeben und bietet wenig bis gar keine militärische Unterstützung, während das Haus der Adligen die wachsende Krise ignoriert. Die örtliche Volksmiliz ist überlastet und verfügt nicht über die Zahlen, die Ausbildung und die Ressourcen, um einen Frontalangriff auf befestigte kriminelle Bastionen zu starten. Riell und ihre Mitstreiter müssen sich auf fähige Abenteurer verlassen, um die tückischen Todesminen zu infiltrieren und sich der Führung der Bruderschaft direkt zu stellen.",al={"warum nicht die armee von sturmwind","warum einen abenteurer schicken","warum brauche ich"}}},fp="17,159,20.356.0,17.317.0,36.165.0,70.169.0,19.162.0,51.151.0,29.197.0,57.146.0"}
P.entries["quest:215"] = {n="Geheimnisse im Dschungel",s="Im nördlichen Schlingendorntal erklärt Gefreiter Thorsen, warum er sich Kurzens Männern wieder angeschlossen hat, nachdem Ihr ihn aus einem Hinterhalt gerettet habt. Er schickt Euch zum Rebellenlager, damit sein Kommandant den Grund bestätigt.",h="Im nördlichen Schlingendorntal erklärt Gefreiter Thorsen, warum er sich Kurzens Männern wieder angeschlossen...",kw={"doren","kurzen","rebellenlager","schlingendorntal","thorsen","verräter","yohwa"},ang={["faction:Alliance"]="Das Rebellenlager ist auf die dringend benötigten Informationen angewiesen, die Gefreiter Thorsen von Kurzens Männern mitzubringen hofft."},sec={{t="Ein verdecktes Unterfangen",b="Gefreiter Thorsen sagt, dass die Lage düster aussieht, und bittet Euch, ihn anzuhören. Lieutenant Doren hat ihm befohlen, sich erneut bei Colonel Kurzens Männern zu verpflichten und dringend benötigte Informationen für die Rebellion zu sammeln. Thorsen hoffte, so in Kurzens Truppenlager zu gelangen, doch das Vorhaben nahm bald eine schlimme Wendung. Er schickt Euch zur Bestätigung zu Doren im Rebellenlager und fleht Euch an, die Angelegenheit geheim zu halten."},{t="Verdacht im Lager",b="Lieutenant Doren bestätigt, dass Gefreiter Thorsen auf seinen Befehl hin gehandelt hat. Die Rebellen waren Kurzen einst treu ergeben, doch Verderbnis verwandelte diese Treue in Wut. Würden Thorsens Machenschaften bekannt, würden seine eigenen Kameraden ihm die Kehle durchschneiden. Nur Doren, Sergeant Yohwa und Thorsen sollten von dem Plan wissen. Der gescheiterte Hinterhalt deutet auf einen unbekannten Verräter unter den Rebellen hin."}},faq={{q="Warum hat sich Gefreiter Thorsen mit Kurzens Truppen getroffen?",a="Lieutenant Doren hat Gefreiter Thorsen befohlen, sich erneut bei Colonel Kurzens Männern zu verpflichten und lebenswichtige militärische Informationen für die Rebellen zu sammeln.",al={"warum traf thorsen kurzen","ist thorsen ein verräter","warum war thorsen außerhalb des lagers"}},{q="Wohin schickt Euch Gefreiter Thorsen?",a="Gefreiter Thorsen schickt Euch zu Lieutenant Doren im Rebellenlager im nördlichen Schlingendorntal, wo sein Kommandant die Geschichte bestätigen kann.",al={"wohin gehen","thorsen abgabe","wo ist doren"}},{q="Warum besteht Thorsen auf Geheimhaltung?",a="Die Rebellen waren Colonel Kurzen einst treu ergeben. Wenn sie erführen, dass Thorsen mit Kurzens Männern zu tun hatte, könnten sie ihn nachts töten.",al={"warum geheim halten","warum geheime mission"}},{q="Was folgt nach dem Bericht an Lieutenant Doren?",a="Nachdem Ihr mit Lieutenant Doren gesprochen habt, führt Euch Eure Suche zu Buchmacher Herod.",al={"nächste quest","was folgt auf geheimnisse im dschungel"}}},fp="14,196,20.388.0,18.372.1,53.135.0,36.138.0,35.141.0,47.73.0"}
P.entries["quest:2158"] = {n="Ruhe und Entspannung",s="Von Nordhain folgen neue Abenteurer der Allianz der Straße nach Süden nach Goldhain, wo sie Ruhe und einen herzlichen Empfang finden. Im Gasthaus \"Zur Höhle des Löwen\" bietet Gastwirt Farley Speis, Trank und einen Platz am Herdfeuer.",h="Von Nordhain folgen neue Abenteurer der Allianz der Straße nach Süden nach Goldhain, wo sie Ruhe und einen...",kw={"taverne der allianz","wald von elwynn","goldhain","gastwirt farley","gasthaus \"zur höhle des löwen\"","nordhain","ruhe und entspannung"},ang={["faction:Alliance"]="Das Gasthaus \"Zur Höhle des Löwen\" ist eine Zuflucht und ein Treffpunkt für Reisende der Allianz im Wald von Elwynn.",["race:Human"]="Als menschlicher Rekrut verlasst Ihr das Nordhaintal und folgt der südlichen Straße nach Goldhain. Dort bietet Gastwirt Farley vertraute Gastfreundschaft nahe Sturmwind."},sec={{t="Eine Zuflucht am Weg",b="Müde Reisende verlassen Nordhain und folgen der Straße nach Süden nach Goldhain. Sie führt direkt zum Gasthaus \"Zur Höhle des Löwen\", wo Gastwirt Farley all jene willkommen heißt, die in den Wald von Elwynn aufbrechen. Für neue Abenteurer ist das Gasthaus der erste größere Außenposten jenseits der Abbey, der Schutz und warme Mahlzeiten bietet."},{t="Farleys Herdfeuer und Gastfreundschaft",b="Gastwirt Farley heißt alle willkommen, die müde sind und frieren. Erwähnt Eure Empfehlung, und Ihr könnt Euch am offenen Feuer niederlassen, eine warme Mahlzeit, kräftiges Bier und etwas Ruhe genießen, bevor Ihr durch Elwynn weiterzieht."}},faq={{q="Wo finde ich das Gasthaus \"Zur Höhle des Löwen\"?",a="Das Gasthaus \"Zur Höhle des Löwen\" liegt in Goldhain, südlich vom Nordhaintal entlang der Hauptstraße. Folgt der Straße nach Süden zur Taverne im Herzen des Ortes.",al={"wo ist das gasthaus \"zur höhle des löwen\"","wie zum gasthaus \"zur höhle des löwen\" gelangen","gasthaus \"zur höhle des löwen\" finden"}},{q="Wer ist Gastwirt Farley?",a="Gastwirt Farley führt das Gasthaus \"Zur Höhle des Löwen\" in Goldhain. Als enger Freund von Kontaktleuten in Nordhain empfängt er müde Abenteurer mit Speis, Trank und einem warmen Herdfeuer.",al={"wer ist gastwirt farley","farley gasthaus \"zur höhle des löwen\""}},{q="Was ist der Zweck von Ruhe und Entspannung?",a="Ihr reist von Nordhain nach Goldhain, wo Gastwirt Farley im Gasthaus \"Zur Höhle des Löwen\" Speis, Trank und Unterkunft bietet.",al={"was ist der zweck dieser quest","warum zum gasthaus \"zur höhle des löwen\" gehen"}},{q="Bietet Gastwirt Farley wirklich vergünstigtes Essen und Trinken an?",a="Erwähnt Eure Empfehlung bei Gastwirt Farley, und Ihr könnt nach vergünstigtem Essen und Trinken fragen, während Ihr Euch von Eurer Reise erholt.",al={"rabatt im gasthaus \"zur höhle des löwen\"","gibt es bei farley günstigeres essen"}},{q="Warum ist Ruhe für reisende Abenteurer wichtig?",a="Reisen durch Elwynn sind beschwerlich und gefährlich. In einem Gasthaus könnt Ihr Schutz vor der Wildnis finden, Euch am Feuer wärmen, Euch erholen und Eure Vorräte auffüllen, bevor Ihr erneut aufbrecht.",al={"warum brauchen abenteurer ruhe","ruhe und entspannung hintergrundgeschichte"}},{q="Wie lautet das Motto des Gasthauses \"Zur Höhle des Löwen\"?",a="Gastwirt Farley sagt, das Motto des Gasthauses \"Zur Höhle des Löwen\" lautet: „Ruhe und Entspannung für die Müden und Frierenden.“ Müde Gäste finden an seinem Herdfeuer Behaglichkeit.",al={"wie lautet das motto des gasthauses \"zur höhle des löwen\"","gasthaus \"zur höhle des löwen\" wahlspruch"}}},fp="19,187,19.287.0,31.188.0,38.145.0,24.165.0,43.120.0,61.127.0,48.176.0,42.144.0"}
P.entries["quest:2159"] = {n="Lieferung für Dolanaar",s="In Laubschattental tragen Reisende Kräuter nach Süden nach Dolanaar. Porthannius ist mit den Druiden beschäftigt, und vor jungen Abenteurern öffnet sich der Weg über die geschützte Lichtung hinaus.",h="In Laubschattental tragen Reisende Kräuter nach Süden nach Dolanaar.",kw={"lieferung","dolanaar","lieferung für dolanaar","kräuter","gastwirt keldamyr","nachtelf","porthannius","laubschattental","teldrassil"},ang={["class:Druid"]="Als Druide wisst Ihr, dass Porthannius mit den Druiden von Laubschattental sowie den spirituellen Pflichten und natürlichen Ungleichgewichten beschäftigt ist, die den Zirkel des Cenarius im Geäst von Teldrassil umtreiben.",["profession:Herbalism"]="Als Kräuterkundiger wisst Ihr, dass unverarbeitete Kräuter aus dem Boden von Laubschattental für die Heiler, Köche und Pfleger von Dolanaar von Bedeutung sind.",["race:NightElf"]="Als Nachtelf verlasst Ihr die geschützte Wiege von Aldrassil und übernehmt umfassendere Verantwortung für den Schutz von Teldrassil."},sec={{t="Ein Bote für Laubschattental",b="Porthannius bittet Reisende, die von Laubschattental nach Süden aufbrechen, frisch gesammelte Kräuter über den Waldpfad mitzunehmen. Dringende Angelegenheiten mit den Druiden, die die Lichtung hüten, hindern ihn daran, die Reise selbst anzutreten. Das Bündel reist nach Süden, während junge Abenteurer das Übungsgelände verlassen und in die weiteren Gefilde von Teldrassil aufbrechen."},{t="Der Weg nach Dolanaar",b="Die südliche Straße von Laubschattental führt nach Dolanaar, einer der bedeutendsten Nachtelfensiedlungen auf den gewaltigen Ästen von Teldrassil. Gastwirt Keldamyr sorgt für Rast, Gastfreundschaft und Vorräte für Wanderer, Schildwachen und Druiden. Als er Porthannius' Kräuter entgegennimmt, mahnt er junge Abenteurer, Geist und Seele ruhen zu lassen, bevor sie sich der Verderbnis stellen, die sich über den Weltbaum ausbreitet."}},faq={{q="Wer ist Porthannius?",a="Porthannius ist ein Nachtelf, der in Laubschattental lebt, der Lichtung für Anfänger auf Teldrassil. Er arbeitet mit den örtlichen Druiden zusammen und bittet Reisende, die die Lichtung verlassen, Vorräte für ihn nach Süden zu bringen.",al={"porthannius","wer vergibt lieferung für dolanaar","questgeber porthannius"}},{q="Warum kann Porthannius die Kräuter nicht selbst liefern?",a="Dringende Angelegenheiten mit den Druiden von Laubschattental halten Porthannius in dem geschützten Tal beschäftigt, weshalb er auf vorbeiziehende Abenteurer angewiesen ist, die Kräuter nach Süden zu bringen.",al={"warum braucht porthannius hilfe","warum kann porthannius nicht gehen"}},{q="Was ist in dem Päckchen?",a="Das Päckchen enthält Kräuter, die in Laubschattental für den Gebrauch im Gasthaus von Dolanaar gesammelt wurden.",al={"lieferung für dolanaar paketinhalt","was sind das für kräuter"}},{q="Wer ist Gastwirt Keldamyr?",a="Gastwirt Keldamyr führt das Gasthaus von Dolanaar und bietet Reisenden Gastfreundschaft, Unterkunft und Ruhesteine. Außerdem koordiniert er den Handel und den Austausch von Vorräten mit anderen Siedlungen auf Teldrassil.",al={"keldamyr","gastwirt von dolanaar","wer erhält die kräuter"}},{q="Wo liegt Dolanaar?",a="Dolanaar liegt südlich von Laubschattental. Die Hauptstraße vom Ausgang der Lichtung führt Reisende direkt ins Ortszentrum.",al={"wo ist dolanaar","lage von dolanaar","weg nach dolanaar"}},{q="Warum ist diese Lieferung für junge Abenteurer wichtig?",a="Die Lieferung führt junge Abenteurer über Laubschattental hinaus und macht sie mit dem Gasthaus, den Lehrern und den Dienstleistern von Dolanaar vertraut.",al={"bedeutung der lieferung","warum kräuter liefern"}}},fx={e1815add={q="Warum muss Porthannius dieses Paket nach Dolanaar liefern lassen?",a="Porthannius hat ein lebenswichtiges Bündel frischer Kräuter vorbereitet, die im Laubschattental gesammelt wurden und auf die Gastwirt Keldamyr unten in Dolanaar wartet. Dringende Pflichten halten Porthannius jedoch mit den örtlichen Druiden beschäftigt, was ihn daran hindert, die Reise selbst zu machen. Um sicherzustellen, dass der Gastwirt diese notwendigen Vorräte ohne Verzögerung erhält, verlässt er sich auf einen vorbeiziehenden Reisenden, der sich nach Teldrassil begibt.",al={"porthannius lieferbeweggrund","warum kräuter nach dolanaar schicken","zweck der lieferung für dolanaar"}}},fp="17,164,26.324.0,20.373.0,19.181.0,48.153.0,27.78.0,26.190.0,26.115.0,53.126.0"}
P.entries["quest:2160"] = {n="Vorräte für Tannok",s="Hands Federspross hat Gasthausvorräte für Tannok Frosthammer, doch Troggs haben den Pass unsicher gemacht. Er bittet Euch, die Kiste vom Coldridgetal zur Brauerei Donnerbräu in Kharanos zu tragen.",h="Hands Federspross hat Gasthausvorräte für Tannok Frosthammer, doch Troggs haben den Pass unsicher gemacht.",kw={"ambossar","eisklamm","hands federspross","kharanos","vorräte für tannok","tannok frosthammer","thunderbrew","troggs"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr durch die Wiederherstellung des Handels zwischen abgeschiedenen Außenposten, Eisenschmiedes Versorgungswege im Landesinneren trotz der Troggvorstöße aufrechtzuerhalten.",["race:Dwarf"]="Als Zwerg führt Euch der Transport von Vorräten aus Ambossar nach Kharanos über das geschützte Tal hinaus und in den Dienst Eisenschmiedes.",["race:Gnome"]="Als Gnom zeigt Ihr mit Eurer Hilfe für Hands Federspross die Zusammenarbeit zwischen den Gnomeregangnomen und ihren zwergischen Gastgebern in Dun Morogh."},sec={{t="Ein abgeriegeltes Tal",b="Troggs haben die Eisklamm überrannt und den Weg aus dem Coldridgetal gefährlich gemacht. Die Gebirgsjäger sind mit dem Schutz von Siedlungen und Verteidigungsanlagen überlastet, sodass sich Versorgungseskorten um Tage verzögern können. Für die Kiste des Gasthauses gibt es keinen sicheren Weg hindurch."},{t="Hands und der Gehilfe des Gastwirts",b="Hands Federspross ist ein gnomischer Tüftler, der am Pass wartet, doch er kann die Kiste selbst nicht sicher transportieren. Ihr könnt die Vorräte zu Tannok Frosthammer bringen, dem Gehilfen im Gasthaus Thunderbrew in Kharanos."},{t="Ein einladendes Herdfeuer in Kharanos",b="Tannok Frosthammer nimmt die Vorräte in Kharanos entgegen. Er sagt, dass Nachrichten aus Ambossar selten geworden sind, seit Troggs den Reiseverkehr behindern. Ohne die Lieferung bleiben die Nachrichten- und Handelsverbindungen zwischen den beiden abgeschiedenen Zwergengemeinschaften brüchig."}},faq={{q="Wer ist Hands Federspross?",a="Hands Federspross ist ein gnomischer Tüftler, der am Eingang der Eisklamm im Coldridgetal wartet. Er bittet Reisende, Waren nach Kharanos zu bringen, weil er den Pass allein nicht sicher überqueren kann.",al={"hands federspross","questgeber","wer gibt vorräte für tannok"}},{q="Wer ist Tannok Frosthammer?",a="Tannok Frosthammer ist der Gehilfe in der Brauerei Donnerbräu in Kharanos. Er nimmt Vorräte entgegen, die aus Orten wie Ambossar geschickt werden.",al={"tannok","tannok frosthammer","gehilfe des gastwirts in kharanos"}},{q="Warum kann Hands die Vorräte nicht selbst liefern?",a="Troggs haben den Pass zwischen dem Coldridgetal und Kharanos überrannt und machen das Reisen gefährlich. Auch die Begleiteskorten der Gebirgsjäger verzögern sich, weil diese mit dem Schutz von Siedlungen und Verteidigungsanlagen überlastet sind.",al={"warum kann hands es nicht liefern","warum wird ein abenteurer gebraucht","warum ist der pass gefährlich"}},{q="Wo liegt das Gasthaus in Kharanos?",a="Die Brauerei Donnerbräu liegt im Zentrum von Kharanos, an der Hauptstraße, die nach Osten Richtung Eisenschmiede führt. Tannok Frosthammer befindet sich im Inneren.",al={"wo ist tannok","standort der brauerei donnerbräu","standort des gasthauses in kharanos"}},{q="Was befindet sich in der Kiste mit Gasthausvorräten?",a="Die Kiste enthält Schankbedarf und Proviant, die in Ambossar für das Gasthaus Thunderbrew in Kharanos zusammengetragen wurden.",al={"was ist in der kiste","kiste mit gasthausvorräten"}},{q="Warum ist die Nachrichtenverbindung zwischen Ambossar und Kharanos unterbrochen?",a="Troggs aus unterirdischen Tunneln haben die Eisklamm überrannt. Ihre Anwesenheit hat den Fußverkehr und die regelmäßige Nachrichtenübermittlung zwischen dem Coldridgetal und dem übrigen Dun Morogh gestört.",al={"warum kaum nachrichten aus ambossar","troggproblem am pass"}}},fx={["6d15a4f4"]={q="Warum möchte Hands Federspross, dass die Vorräte nach Kharanos geliefert werden?",a="Hands Federspross versprach Tannok Frosthammer, dem Assistenten im Gasthaus von Kharanos, lebenswichtige Versorgungsgüter, aber Trogangriffe haben den Reiseverkehr durch den Pass aus dem Coldridgetal zum Erliegen gebracht. Da reguläre Lieferungen festsitzen und Bergsteiger-Eskorten Tage entfernt sind, bleibt Tannok wartend und besorgt mit schwindenden Vorräten zurück. Hands möchte seine Lieferung einhalten und sicherstellen, dass die geschäftige Brauerei Donnerbräu und das Gasthaus für straßenmüde Reisende bestückt bleiben.",al={"warum vorräte an tannok senden","hands federspross beweggrund","warum kiste mit gasthausvorräten liefern"}}},fp="18,195,18.238.0,35.206.0,30.232.0,28.192.0,26.136.0,45.193.0,37.129.0,41.104.0,59.178.0"}
P.entries["quest:2161"] = {n="Die Bürde eines Peons",s="Ukor wartet vor dem Tal der Prüfungen mit Vorräten, die er nicht nach Hause tragen kann. Die Rekruten im roten Canyon haben seine Nahrung abgelehnt, also bittet er Reisende, sie nach Klingenhügel zurückzubringen.",h="Ukor wartet vor dem Tal der Prüfungen mit Vorräten, die er nicht nach Hause tragen kann.",kw={"durotar","nahrung","gastwirt grosk","peon","klingenhügel","vorräte","ukor","das tal der prüfungen"},ang={["faction:Horde"]="Ihr verlasst die Proving Grounds in Richtung Klingenhügel, dem Zentrum der Verteidigung und Versorgung der Horde im Süden Durotars.",["race:Orc"]="Die Kultur der Orcs schätzt körperliche Stärke und Mut, weshalb Peons wie Ukor ganz unten in der Gesellschaft stehen. Hilfe bei seiner Lieferung zeigt, wie einfache Arbeit Durotars junge Nation am Laufen hält."},sec={{t="Eine fehlgeleitete Lieferung",b="Ukor verließ Klingenhügel mit Vorräten für die neuen Rekruten, die im roten Canyon trainieren. Er dachte, sie bräuchten die Nahrung, doch die Zuchtmeister schickten ihn fort. Sie halten die Rationen knapp, weil sie glauben, dass Entbehrungen junge Krieger der Horde Disziplin und Ausdauer lehren. Gastwirt Grosk erklärt später, dass Hunger Teil ihrer Ausbildung ist."},{t="Gefahren der roten Ödnis",b="Ukor hat den Pass erreicht, fürchtet sich aber davor, auf dem Rückweg Durotar zu durchqueren. Skorpide, giftige Spinnen und umherstreifende Eber machen den felsigen Pfad unsicher. Er hat weder Waffen noch Rüstung, und ihm fehlt der Kampfgeist, den man von einem Orc-Grunzer erwartet.\n\nAlso wartet Ukor am Wegesrand und bittet Reisende, die die Proving Grounds verlassen, seine schweren Vorräte zum Gasthaus in Klingenhügel zurückzutragen."}},faq={{q="Wer ist Ukor?",a="Ukor ist ein ängstlicher Orc-Peon, der an der Straße aus dem Tal der Prüfungen wartet. Er brach mit Vorräten von Klingenhügel auf, fürchtet die heimischen Wildtiere aber zu sehr, um den Rückweg allein anzutreten.",al={"ukor","wer ist der peon an der straße","peon beim tal der prüfungen"}},{q="Warum wollten die Ausbilder im Tal der Prüfungen die Nahrung nicht?",a="Die Zuchtmeister lassen die Rekruten hungern, weil sie glauben, dass Entbehrungen Disziplin und Ausdauer lehren. Gastwirt Grosk erklärt, dass knappe Rationen Teil ihrer Ausbildung sind, weshalb Ukors Vorräte abgelehnt wurden.",al={"warum nahrung ablehnen","warum trug ukor nahrung","gastwirt grosk hungern"}},{q="Wohin muss diese Lieferung gebracht werden?",a="Tragt die Vorräte auf Durotars Hauptstraße nach Norden bis nach Klingenhügel. Gebt sie Gastwirt Grosk in der Taverne der Siedlung.",al={"wo liegt klingenhügel","wem die nahrung geben","wo ukors bürde abliefern"}},{q="Was macht die Reise für einen Peon gefährlich?",a="Skorpide, giftige Krabbelspinnen und wilde Eber durchstreifen Durotars felsige Ödnis. Ukor ist ein ungerüsteter Arbeiter ohne Kampfausbildung, während erfahrene Rekruten mit solchem Ungeziefer fertigwerden.",al={"warum hat ukor angst","gefahren auf durotars straßen"}},{q="Welche Rolle spielen Peons in der Horde?",a="Peons stehen in der Gesellschaft der Orcs ganz unten und verrichten einfache Arbeiten, vom Schleppen von Vorräten über das Holzfällen bis zum Errichten von Befestigungen. Grunzer und Champions erhalten Lob und Ruhm, während Peons oft übersehen werden, obwohl sie die Siedlungen mit Nahrung versorgen und instand halten.",al={"hintergrund der orc-peons","stellung der peons","was sind peons"}},{q="Wer ist Gastwirt Grosk?",a="Gastwirt Grosk führt das Gasthaus in Klingenhügel und kümmert sich um dessen Unterkünfte und Vorräte. Er bietet reisenden Kriegern Speis, Trank und ein Herdfeuer und erinnert Rekruten daran, sich auszuruhen, bevor sie sich der weiten Welt stellen.",al={"gastwirt grosk","grosk klingenhügel","gastwirt in klingenhügel"}}},fx={["777a74e1"]={q="Warum möchte Ukor, dass das Essen zurück nach Klingenhügel geliefert wird?",a="Ukor meinte es aufrichtig gut, als er Vorräte aus Klingenhügel heranschaffte, in der Hoffnung, den jungen Rekruten zu helfen, die unter der harten Sonne des Tals der Prüfungen trainieren. Da er feststellen musste, dass die Ausbilder die Rationen ablehnten, kann er die Vorräte nicht einfach zurücklassen oder auf der Straße verderben lassen. Das Essen gehört zurück in die Regale der Speisekammer von Gastwirt Grosk, aber nachdem er den Treck vorbei an den Skorpionen und Spinnen der Region kaum überlebt hat, hat Ukor schreckliche Angst davor, den gefährlichen Rückweg allein anzutreten.",al={"warum das essen zurückbringen","ukor beweggrund","warum essen an grosk geben"}},fe82ef3c={q="Warum bittet Ukor Euch, die Last zu tragen, statt es selbst zu tun?",a="Ukor ist ein gewöhnlicher Peon, der Gewalt nicht gewohnt ist und der Wildnis unbewaffnet gegenübersteht. Zwar gelang es ihm, den Skorpionen und Spinnen auf der Straße aus Klingenhügel zu trotzen, doch die blanke Angst vor einer erneuten Begegnung mit diesen wilden Raubtieren hält ihn wie angewurzelt fest. Als er Euch siegreich aus dem Tal der Prüfungen kommen sieht, erkennt er in Euch einen fähigen Helden, der nichts fürchtet, und hofft, dass Ihr die Last auf Eurem Weg nach Klingenhügel bereitwillig tragt.",al={"warum kann ukor es nicht tragen","warum man selbst peon's burden übernehmen soll","warum ukor einen selbst bittet"}}},fp="15,178,20.329.0,23.361.0,12.189.0,62.212.0,36.136.0,44.168.0,39.264.0,23.197.0"}
P.entries["quest:217"] = {n="Verteidigung der Länder des Königs",s="Hauptmann Rugelfuß schickt Euch ins Splittersteintal, um die Angriffe auf die Länder des Königs zu stoppen. Späher haben Grawmug, den Häuptling der Splittersteintroggs, als ihren Urheber ausgemacht. Sein Tod könnte die Entschlossenheit des Rudels brechen und helfen, den Süden von Loch Modan zurückzuerobern.",h="Hauptmann Rugelfuß schickt Euch ins Splittersteintal, um die Angriffe auf die Länder des Königs zu stoppen.",kw={"brawler","gnasher","grawmug","länder des königs","loch modan","rugelfuß","splitterstein","trogg"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr mit der Verteidigung von Loch Modan, die Landverbindung zwischen Eisenschmiede und den östlichen Grenzgebieten zu bewahren. Außerdem helft Ihr, die Nachschublinien der Streitkräfte der Allianz zu sichern.",["race:Dwarf"]="Als Zwerg verteidigt und ehrt Ihr Eure Heimat, indem Ihr Troggs vom uralten Boden Khaz Modans vertreibt. Ihr helft, die Bergfestungen von unterirdischen Plagen freizuhalten."},sec={{t="Den Schwarm enthaupten",b="Die Späher von Hauptmann Rugelfuß haben herausgefunden, dass die Splittersteintroggs Häuptling Grawmug folgen. Ihre Angriffe bedrohen die Länder des Königs im Süden von Loch Modan. Ihr werdet in ihren Unterschlupf geschickt, um Grawmug und seine persönlichen Schläger zu töten. Den Zusammenhalt des Rudels zu brechen, könnte seinen Vormarsch aufhalten."},{t="In Stonesplinter Lair",b="Grawmug hält eine Höhle in den südöstlichen Klippen des Splittersteintals besetzt. Seine vertrauten Schläger Gnasher und Brawler stehen ihm zur Seite, wodurch die drei für einen einzelnen Soldaten gefährlich sind. Sie zu besiegen, könnte die übrigen Troggs ins Chaos stürzen. Das würde den bedrängten Gebirgsjägern Zeit verschaffen, die Straßen zu befestigen und die Bestien wieder unter die Erde zu treiben."}},faq={{q="Wer ist Grawmug?",a="Grawmug ist der Trogghäuptling, der die Splittersteintroggs im Süden von Loch Modan anführt. Zwergenspäher haben die organisierten Angriffe, die das Tal heimsuchen, auf ihn zurückgeführt. Gnasher und Brawler bewachen ihn an seiner Seite.",al={"grawmug hintergrund","wer ist der trogganführer","häuptling grawmug"}},{q="Wo befinden sich Grawmug und seine Wachen?",a="Grawmug, Gnasher und Brawler befinden sich tief in einer Höhle am südöstlichen Rand des Splittersteintals in Loch Modan.",al={"grawmug aufenthaltsort","wo ist grawmug","wo grawmug finden"}},{q="Wer ist Hauptmann Rugelfuß?",a="Hauptmann Rugelfuß ist der zwergische Offizier, der am Southern Guard Tower in Loch Modan stationiert ist. Er leitet die Verteidigung gegen die Troggeinfälle und erteilt Befehle zum Schutz der Länder des Königs.",al={"rugelfuß","hauptmann rugelfuß aufgabe","wer vergibt verteidigung der länder des königs"}},{q="Warum müssen auch Grawmugs Wachen getötet werden?",a="Gnasher und Brawler sind Grawmugs persönliche Vollstrecker und bleiben an seiner Seite. Sie müssen zusammen mit ihrem Anführer besiegt werden, um die Führung der Troggs zu zerschlagen.",al={"warum gnasher und brawler töten","gnasher und brawler","grawmugs leibwächter"}},{q="Was geschieht, nachdem Grawmug ausgeschaltet wurde?",a="Grawmugs Tod könnte Loch Modan Entlastung bringen. Ohne ihn, der ihre Überfälle koordiniert, könnten die Splittersteintroggs ihre Organisation verlieren. Das würde der örtlichen Zwergenmiliz bessere Chancen geben, die Grenzen zu halten und die Bestien unter die Erde zurückzudrängen.",al={"folgen von grawmugs tod","troggs nach grawmugs tod","haben wir loch modan gerettet"}},{q="Warum fallen Troggs in Loch Modan ein?",a="Troggs leben seit langer Zeit in unterirdischen Kammern unter Khaz Modan. Ausgrabungen und geöffnete Höhlen haben ihnen den Weg an die Oberfläche ermöglicht, wo sie Siedlungen verdrängen und Reisende auf den Straßen des Königs angreifen.",al={"warum sind troggs hier","troggeinfall loch modan","herkunft der splittersteintroggs"}}},fx={["440a3b53"]={q="Warum möchte Hauptmann Rugelfuß, dass Grawmug getötet wird?",a="Hauptmann Rugelfuß sieht in Grawmug den Drahtzieher, der die Trogg-Einfälle vorantreibt, die Loch Modan bedrohen. Die Zwergengarnisonen kämpfen damit, die unterirdischen Schwärme zurückzuhalten, und Rugelfuß glaubt, dass die Enthauptung ihrer Führung – insbesondere die Eliminierung von Grawmug zusammen mit seinen Elite-Leibwächtern – ihren Schwung brechen und den Zwergen eine echte Chance geben wird, sie zurück unter die Erde zu treiben.",al={"rugelfuß beweggrund","warum grawmug töten","zweck von in defense of the kings lands"}}},fp="30,250,22.286.0,23.351.0,15.197.0,41.112.0,25.194.0,43.148.0,41.255.1,35.209.0"}
P.entries["quest:2178"] = {n="Schreitereintopf",s="In Auberdine bietet Alanndarian Nachtweise Jägern ihr Rezept für Schreitereintopf an, wenn sie ihr Fleisch von Foreststriders bringen.",h="In Auberdine bietet Alanndarian Nachtweise Jägern ihr Rezept für Schreitereintopf an, wenn sie ihr Fleisch...",kw={"alanndarian nachtweise","auberdine","kochkunst","dunkelküste","schreitereintopf","foreststrider","schreiterfleisch"},ang={["class:Hunter"]="Als Jäger könnt Ihr auf den nebligen Pfaden der Dunkelküste das Fährtenlesen und die Jagd auf flinke Foreststriders üben.",["profession:Cooking"]="Als Koch auf Reisen durch die Dunkelküste könnt Ihr lernen, aus den dort heimischen Tieren Schreitereintopf zuzubereiten.",["race:NightElf"]="Als Nachtelf in Kalimdor wisst Ihr, wie wertvoll es ist, von dem zu leben, was das Land bietet. Schreitereintopf gehört in Auberdine zur alltäglichen Küstenküche."},sec={{t="Ein Geschmack der Wildnis",b="Auberdines Küstenbewohner nutzen die Tierwelt ihrer Umgebung. Alanndarian Nachtweise hat ihr eigenes Rezept für herzhaften Schreitereintopf aus den hochgewachsenen Foreststriders, die durch die Wälder der Dunkelküste streifen. Sie bittet Euch, die Vögel zu jagen und ihr Fleisch zurückzubringen, bevor sie ihre Kochkunst mit Euch teilt."},{t="Jagd auf Foreststriders",b="Foreststriders durchstreifen die Wälder und Strände nördlich und südlich von Auberdine. Ihre scharfen Schnäbel und ihr aufbrausendes Wesen machen sie gefährlich, wenn man sie reizt, doch ihr Fleisch ergibt einen gehaltvollen Eintopf. Bringt Alanndarian frisches Fleisch, und sie wird ihr Rezept mit Euch teilen."}},faq={{q="Wer ist Alanndarian Nachtweise?",a="Alanndarian Nachtweise lebt in Auberdine an der Dunkelküste. Sie bietet Reisenden, die ihr Jagdgeschick beweisen, an, ihnen ihr Rezept für Schreitereintopf beizubringen.",al={"alanndarian","wer ist alanndarian nachtweise","eintopf köchin auberdine"}},{q="Wo findet sich das Schreiterfleisch?",a="Jagt Foreststriders überall an der Dunkelküste, um ihr Fleisch zu erhalten. Die großen, flugunfähigen Vögel durchstreifen die Küstenstreifen und bewaldeten Haine außerhalb von Auberdine.",al={"schreiterfleisch fundort","wo sind foreststriders","wie schreiterfleisch bekommen"}},{q="Was ist der Zweck dieser Quest?",a="Ihr jagt Foreststriders und bringt Alanndarian Nachtweise fünf Stücke Fleisch. Im Gegenzug lehrt sie Euch, Schreitereintopf zuzubereiten.",al={"warum schreitereintopf abschließen","questzweck","schreitereintopf questziel"}},{q="Ist die Jagd auf Foreststriders gefährlich?",a="Foreststriders haben scharfe Schnäbel und flinke Beine und werden aggressiv, wenn man sich ihnen nähert. Seid bei der Jagd vorsichtig.",al={"sind schreiter schwer zu töten","foreststrider gefahr"}},{q="Schaltet diese Quest ein Kochrezept frei?",a="Ja. Bringt Alanndarian das gewünschte Fleisch, und sie lehrt Euch das Rezept für Schreitereintopf.",al={"gibt es ein rezept","schreitereintopf rezept","kochbelohnung"}},{q="Wo findet diese Quest statt?",a="Ihr beginnt und endet in Auberdine und jagt in der Wildnis der Dunkelküste.",al={"questgebiet","wo ist schreitereintopf"}}},fx={["624f04e5"]={q="Wofür wird Schreiterfleisch verwendet?",a="Das saftige Fleisch ist die Hauptzutat für Alanndarians schmackhaften Schreitereintopf. Wenn Ihr ihr fünf Stücke bringt, füllt das ihren leeren Kessel und beweist ihr, dass Ihr Euch das Recht verdient habt, ihr geheimes Wildnisrezept zu erlernen.",al={"was ist schreiterfleisch für","warum schreiterfleisch","nutzen schreiterfleisch"}},["64984ff6"]={q="Warum möchte Alanndarian Nachtweise, dass dies getan wird?",a="Alanndarian Nachtweise hat einen leeren Kochtopf und Appetit auf frischen Schreitereintopf. Bevor sie bereit ist, sich von ihrem Geheimrezept zu trennen, besteht sie darauf zu sehen, ob Ihr das Zeug dazu habt, die Stelzvögel selbst zu jagen und frische Stücke für ihr Kochfeuer zurückzubringen.",al={"alanndarian beweggrund","warum will alanndarian schreiterfleisch","warum schreitereintopf"}}},fp="19,120,19.288.0,26.253.0,29.143.0,33.152.0,34.129.0,41.105.0,40.94.0,33.72.0"}
P.entries["quest:218"] = {n="Das gestohlene Tagebuch",s="Grelin Weißbart braucht sein gestohlenes Tagebuch, um die Trollbedrohung im Coldridgetal abschließend einzuschätzen. Grik'nir the Cold, Anführer der Frostmane, brachte es in die Trollhöhle und nahm Grelin damit den Großteil seiner Aufzeichnungen.",h="Grelin Weißbart braucht sein gestohlenes Tagebuch, um die Trollbedrohung im Coldridgetal abschließend...",kw={"das coldridgetal","dun morogh","höhle der frostmähnen","frostmane-troll","grelin weißbart","grik'nir the cold","senir weißbart","gestohlenes tagebuch"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, die Anfängertäler von Dun Morogh vor Unruhen zu schützen. Dazu drängt Ihr den aggressiven Stamm der Frostmane zurück.",["race:Dwarf"]="Als Zwerg helft Ihr, junge Rekruten zu schützen, die ihre ersten Schritte jenseits von Ambossar wagen. Ihr zerschlagt die Führung der Frostmane im Coldridgetal.",["race:Gnome"]="Als Gnom seid Ihr auf die Sicherheit der Pässe des Coldridgetals angewiesen. Gnomische Flüchtlinge finden in Ambossar Zuflucht und sammeln sich im Gebiet der Zwerge neu."},sec={{t="Verlorene Notizen eines Gelehrten",b="Die Frostmane-Trolle sind ins Coldridgetal vorgedrungen, und Grelin Weißbarts Notizen dokumentieren ihre Bewegungen. Sie halten die Gewohnheiten der Trolle und ihre plötzliche Aggression fest. Während der Unruhen stahl ein imposanter Troll Grelins persönliches Tagebuch und floh in die Tiefen der Höhle. Das Tagebuch enthält den Großteil seiner Aufklärungsberichte, daher kann Grelin seine Einschätzung erst abschließen, wenn es zurückgeholt wurde."},{t="Konfrontation mit Grik'nir the Cold",b="Grik'nir the Cold hält im Herzen der Trollhöhle des Tals Hof. Auffällige Bemalungen zieren seinen Körper und sein Gesicht. Ein Sieg über diesen mächtigen Frostmane-Troll zerschlägt die unmittelbare Führung der Höhlentrolle und sichert Grelins Tagebuch. Sobald es zurück ist, kann Grelin seine Untersuchung abschließen, die örtliche Trollsituation als beherrschbar einstufen und seinen Bericht an seinen Bruder Senir schicken."}},faq={{q="Wer hat Grelin Weißbarts Tagebuch gestohlen?",a="Grik'nir the Cold hat Grelin Weißbarts Tagebuch gestohlen. Der große Frostmane-Troll trägt seltsame Zeichen auf Haut und Gesicht und lauert tief in der Trollhöhle.",al={"wer hat das tagebuch gestohlen","wer hat grelins tagebuch","tagebuchdieb"}},{q="Wo ist Grik'nir the Cold zu finden?",a="Grik'nir the Cold befindet sich in der Trollhöhle im Süden des Coldridgetals.",al={"wo ist griknir","grik'nir fundort","wie findet man grik'nir"}},{q="Warum ist das Tagebuch für Grelin wichtig?",a="Grelins Tagebuch enthält seine Notizen und Erkenntnisse über die Aktivitäten der Trolle im Coldridgetal. Er braucht es zurück, um einen Bericht für seinen Bruder Senir fertigzustellen.",al={"warum will grelin sein tagebuch","was steht in grelins tagebuch"}},{q="Was geschieht, nachdem Ihr das Tagebuch zurückgebracht habt?",a="Nachdem Ihr das Tagebuch zurückgeholt habt, stellt Grelin seinen Bericht über die Trollsituation im Coldridgetal fertig. Er bittet Euch, seine Erkenntnisse zu seinem Bruder Senir Weißbart in Kharanos zu bringen.",al={"was kommt nach das gestohlene tagebuch","das gestohlene tagebuch folgequest"}},{q="Sind die Frostmane-Trolle danach aus dem Coldridgetal vertrieben?",a="Grelin glaubt, dass die Trollsituation im Coldridgetal nach Grik'nirs Niederlage unter Kontrolle ist. Die Frostmane bleiben in den weiterläufigen Gebirgspässen von Dun Morogh eine Bedrohung.",al={"sind die trolle im coldridgetal besiegt","ist das coldridgetal vor trollen sicher"}},{q="Wer ist Senir Weißbart?",a="Senir Weißbart ist Grelins Bruder, ein Späher der Allianz, der außerhalb des Coldridgetals nahe Kharanos stationiert ist. Er sammelt Informationen über Bedrohungen für das Königreich.",al={"wer ist senir","grelins bruder senir"}}},fx={["78f0c4e3"]={q="Warum will Grelin Weißbart, dass dies erledigt wird?",a="Grelin stellt für seinen Bruder Senir einen offiziellen Bericht über die Bedrohung durch die Frostmähne im Coldridgetal zusammen. Ohne sein Tagebuch kann er seine Notizen nicht vervollständigen oder die Sicherheit des Tals beurteilen, was die örtlichen Anführer ohne wichtige Informationen über die Trollaktivitäten zurücklässt.",al={"warum will grelin sein tagebuch","grelin weißbart motiv","warum grelins tagebuch bergen"}},beb6a987={q="Warum muss Grelin, dass Ihr sein Tagebuch wiederbeschafft?",a="Grelin ist eher Beobachter als Frontkämpfer und das Tagebuch wurde von einem furchterregenden Trollbrut tief in die Trollhöhle im Coldridgetal verschleppt. Da er bereits Euren Erfolg im Kampf gegen die Trolle im Tal miterlebt hat, bittet er Euch, in die Höhle einzudringen und die Gefahr zu beseitigen.",al={"warum braucht grelin mich","warum einen abenteurer für das tagebuch schicken","warum kann grelin sein tagebuch nicht selbst holen"}}},fp="18,225,22.372.0,29.364.0,37.154.0,37.87.0,39.145.0,42.180.1,67.172.0,24.160.0"}
P.entries["quest:219"] = {n="Vermisst",s="Corporal Keeshan wird im Rotkammgebirge vermisst, nachdem Schwarzfelsorcs sein Regiment überrannt haben. Sie schlugen ihn bewusstlos und verschleppten ihn in eine Höhlenfestung. Nun braucht er Geleitschutz nach Seenhain, wo die Garnison seine Rückkehr erwartet.",h="Corporal Keeshan wird im Rotkammgebirge vermisst, nachdem Schwarzfelsorcs sein Regiment überrannt haben.",kw={"schwarzfelsorcs","corporal keeshan","eskorte","keeshan","seenhain","marschall marris","vermisst","rotkammgebirge"},ang={["class:Warrior"]="Als Krieger haltet Ihr die Front gegen Wellen von Schwarzfelsangreifern und beschützt Keeshan, der eine Gehirnerschütterung hat, bei seiner Flucht aus ihrem bewaffneten Lager.",["faction:Alliance"]="Als Soldat der Allianz zählt jeder gerettete Kämpfer für Seenhains schwer beanspruchte Garnison, die das Königreich gegen den Schwarzfelsklan verteidigt."},sec={{t="Ein Regiment überrannt",b="Schwarzfelsorcs steigen von den nördlichen Gipfeln herab und machen das Rotkammgebirge gefährlicher. Patrouillen der Stadtwache geraten oft in Hinterhalte, und das Regiment von Corporal Keeshan traf es am schwersten. In der Unterzahl und vom Feind überwältigt, fielen die meisten seiner Soldaten. Keeshan überlebte, weil ein wuchtiger Schlag ihn bewusstlos schlug, bevor die Orcs ihn hinrichten konnten. Sie schleppten ihn als Gefangenen in ihre Höhle."},{t="Flucht aus den Höhlen",b="Übel zugerichtet und mit einer Gehirnerschütterung wird Keeshan tief im Feindesgebiet gefangen gehalten. Er kann den Abstieg nicht allein bewältigen, also eskortiert Ihr ihn nach Seenhain, vorbei an den Kriegstrupps der Orcs auf den Bergrücken. Marschall Marris versucht herauszufinden, was mit dem vermissten Regiment geschehen ist. Er bereitet Seenhain auch auf weitere Angriffe vor, und Keeshans sichere Rückkehr bringt ihm dringend benötigte Erleichterung."}},faq={{q="Wer ist Corporal Keeshan?",a="Corporal Keeshan ist ein im Rotkammgebirge stationierter Infanterist der Allianz. Schwarzfelsorcs überwältigten sein Regiment während einer Patrouille in den felsigen Hügeln und verschleppten ihn. Er ist der einzige bekannte Überlebende.",al={"corporal keeshan","wer ist keeshan","keeshans geschichte"}},{q="Wo wurde Corporal Keeshan gefangen genommen?",a="Corporal Keeshan wird tief in einer von Orcs verseuchten Höhle in den nördlichen Hügeln des Rotkammgebirges festgehalten, umgeben von feindlichen Schwarzfelskriegern.",al={"wo ist keeshan","keeshans standort","keeshans höhle"}},{q="Was geschah mit dem Rest von Keeshans Einheit?",a="Schwarzfelsorcs lockten Keeshans Regiment in einen Hinterhalt und überwältigten es. Fast alle Männer starben im ersten Gefecht.",al={"keeshans trupp","was geschah mit dem regiment","keeshans männer"}},{q="Wer schickt Spieler los, um Keeshan zu retten?",a="Corporal Keeshan schickt Euch los, um ihn aus seiner Gefängnishöhle zu befreien. Abenteurer der Allianz entdecken ihn dort.",al={"wer startet vermisst","questgeber","wo vermisst annehmen"}},{q="Wohin geht Keeshan nach seiner Befreiung?",a="Nachdem Ihr ihn befreit habt, braucht Keeshan Geleitschutz den Berghang hinab nach Seenhain. Er meldet sich bei Marschall Marris nahe der Brücke der Stadt.",al={"vermisst abgeben","wohin läuft keeshan","keeshans ziel"}},{q="Warum sind die Schwarzfelsorcs im Rotkammgebirge?",a="Der Schwarzfelsklan stößt von seinen Festungen in der Brennenden Steppe nach Süden ins Rotkammgebirge vor. Der Klan bedroht Seenhain, das kaum Verstärkung erhält, und überfällt Patrouillen des Königreichs aus dem Hinterhalt.",al={"schwarzfelsorcs rotkammgebirge","warum orcs in seenhain","invasion des schwarzfelsklans"}}},fx={["64cb6fe2"]={q="Warum benötigt Corporal Keeshan Eure Hilfe bei der Flucht?",a="Corporal Keeshan sitzt tief im feindlichen Gebiet fest, nachdem sein gesamtes Regiment vom Clan der Schwarzfelsorcs überfallen und abgeschlachtet wurde. Nachdem er bei dem Gefecht einen schweren Schlag auf den Kopf erlitten hat, ist er schwer verletzt, orientierungslos und benötigt eine Eskorte. Ohne jemanden, der ihn durch die umgebenden Orcs führt, droht ihm in der Höhle die sichere Hinrichtung oder der Hungertod.",al={"warum keeshan helfen","keeshan motiv","warum braucht keeshan rettung"}},["1d637b84"]={q="Warum kann Keeshan nicht alleine entkommen oder auf die Wache von Seenhain warten?",a="Keeshan ist schwer verletzt und braucht Hilfe, um sich den Weg an den Plünderern der Schwarzfelsorcs vorbeizukämpfen. Währenddessen sind die Verteidiger von Seenhain bereits bis an ihre Grenzen belastet, nur um die Stadt gegen Gnolle und Orcs zu halten, sodass keine Truppen für eine tiefgehende Such- und Rettungsmission übrig sind. Als Ihr über seine Zelle stolpert, seid Ihr buchstäblich seine einzige Hoffnung, lebend zurückzukehren.",al={"warum kann keeshan nicht alleine entkommen","warum braucht mich keeshan","warum keine stadtwachen"}}},fp="17,238,18.386.0,21.379.0,24.208.0,36.129.0,44.106.0,36.101.0,40.132.0,39.178.0"}
P.entries["quest:22"] = {n="Pastete aus Geiferzahnleber",s="Auf dem Hof der Saldeans in Westfall backt Salma Saldean in schweren Zeiten Pastete. Banditen haben die Kornkammer des Königreichs verwüstet, und Siedler jagen aggressive Eber, um ihre Familien zu ernähren.",h="Auf dem Hof der Saldeans in Westfall backt Salma Saldean in schweren Zeiten Pastete.",kw={"eber","kochen","geiferzahn","leberpastete","hof der saldeans","salma saldean","westfall"},ang={["faction:Alliance"]="Wer Siedlern auf dem Land wie den Saldeans hilft, unterstützt königstreue Menschenfamilien, die ohne Sturmwinds Armee darum kämpfen, das Grenzland des Königreichs zu halten.",["profession:Cooking"]="Salmas Gericht spiegelt die ländliche Küche der Menschen wider. Gartenkräuter wie Knoblauch, Rosmarin und Dill machen die Innereien von Wild zu einer alltäglichen Mahlzeit."},sec={{t="Gastfreundschaft im Grenzland",b="Westfall versorgte Sturmwind einst als fruchtbare Kornkammer. Heute machen vernachlässigte Straßen, umherstreifende Gesetzlose und überwucherte Felder den wenigen verbliebenen Siedlern das Leben schwer. Auf dem Hof der Saldeans bemüht sich Salma Saldean, trotz der Gefahren ein Gefühl von Heimat zu bewahren. Eine traditionelle Fleischpastete bietet einen der wenigen Lichtblicke für Siedler, die ihre Lebensweise bewahren wollen."},{t="Westfalls wilde Bestien",b="Geiferzähne durchstreifen die Ebenen Westfalls in großer Zahl. Ihre zähe Haut und gefährlichen Hauer machen sie für allein arbeitende Landarbeiter gefährlich, doch ihr Fleisch ernährt Familien, die vom regelmäßigen Handel abgeschnitten sind. Salmas Rezept verlangt zerstoßenen Rosmarin, fein gehackten Knoblauch, gehackten Dill und köchelnde Bratensauce. Sorgfältig zubereitet werden die streng riechenden Innereien der Bestien zu einer reichhaltigen, herzhaften Mahlzeit."}},faq={{q="Wer ist Salma Saldean?",a="Salma Saldean ist eine zähe Siedlerin, die mit ihrem Mann, dem Bauern Saldean, auf ihrem Hof im Herzen Westfalls lebt. Ihre hausgemachten Mahlzeiten heben trotz der Gefahren durch Banditen und wilde Bestien die Stimmung.",al={"salma saldean","wer ist salma","saldeans ehefrau"}},{q="Warum braucht Salma Geiferzahnlebern?",a="Salma braucht Geiferzahnlebern für ihre berühmte herzhafte Fleischpastete, die sie für sich und ihren Mann zubereitet. Der Teig ist gebacken und die Gewürze stehen bereit; nur die Lebern fehlen noch, bevor sie die Füllung fertig köcheln lassen kann.",al={"warum geiferzahnleber","woraus besteht die pastete","zweck der leberpastete"}},{q="Wo findet man Geiferzähne gewöhnlich in Westfall?",a="Geiferzähne durchstreifen die Goldenen Ebenen und brachliegenden Äcker Westfalls, durchwühlen verlassene Felder und ziehen über unbefestigte Wege.",al={"geiferzähne fundorte","wo findet man eber","jagd nach geiferzahnleber"}},{q="Sind Geiferzähne für die örtlichen Bauern gefährlich?",a="Ja. Geiferzähne sind aggressive Wildschweine mit scharfen Hauern, die ihr Revier verteidigen. Sie bedrohen das Vieh und stellen für ungeschützte Reisende in den Ebenen eine erhebliche Gefahr dar.",al={"sind geiferzähne feindselig","gefahr durch eber in westfall"}},{q="Warum sind Lebensmittel in Westfall derzeit so knapp?",a="Lebensmittel sind knapp, weil Sturmwind kaum Unterstützung leistet und organisierte Banditen die Höfe überfallen. Viele Bauern wurden von ihrem Land vertrieben, sodass die einstige Kornkammer des Königreichs zu einem verarmten Grenzland geworden ist.",al={"hungersnot in westfall","warum kein essen in westfall","schwere zeiten in westfall"}},{q="Hilft die Erfüllung dieser Aufgabe dem Hof der Saldeans zu überleben?",a="Frisches Fleisch kann Westfalls weitreichende Krisen nicht lösen, doch es hilft, die Familie Saldean zu ernähren, und versorgt Reisende mit herzhaftem Proviant für den weiteren Weg.",al={"ist die pastete wichtig","saldeans nahrungsversorgung"}}},fx={["3baa4b09"]={q="Wofür werden Geiferzahnlebern verwendet?",a="Salma Saldean benötigt frische Geiferzahnlebern als letzte, entscheidende Zutat für ihren charakteristischen Fleischpastete aus Westfall. Sie hat bereits die gewürzte Kruste, gehackten Dill, Knoblauch, Rosmarin und köchelnde Bratensoße vorbereitet, aber es fehlt ihr das Fleisch, um das Familienessen zu vervollständigen.",al={"was ist geiferzahnleber für","warum geiferzahnleber","rezept geiferzahnleberpastete"}},ad043644={q="Warum bittet Salma einen Abenteurer, anstatt die Geiferzähne selbst zu jagen?",a="Salma ist damit beschäftigt, die Gehöfte zu führen und sich um die Küche zu kümmern, während die Saldeans um ihr Überleben kämpfen, angesichts der Härten, die Westfall heimsuchen. Da Wildschweine aggressiv außerhalb des Schutzes des Zauns streifen und die örtliche Miliz nur spärlich vorhanden ist, ist sie auf fähige Reisende angewiesen, um frisches Fleisch zu sammeln.",al={"warum ich geiferzahnleber","warum braucht mich salma","warum jagt salma nicht selbst"}}},fp="18,193,20.355.0,23.358.0,21.204.0,36.226.0,48.136.0,45.169.0,44.207.0,56.147.0"}
P.entries["quest:220"] = {n="Ruf des Wassers",s="Das von Brine zubereitete Wasser erreicht nun Islen Wasserdeuter an der Ostküste des Brachlands. Dort beginnt damit der nächste Teil der Schamanenprüfung, und es wird zur Grundlage eines Saptas, das einen Initianden Wassergeister im Silberwald sehen lässt.",h="Das von Brine zubereitete Wasser erreicht nun Islen Wasserdeuter an der Ostküste des Brachlands.",kw={"brine","ruf des wassers","islen wasserdeuter","sapta","silberwald","brachland","phiole mit reinstem wasser","water sapta","wassertotem"},ang={["class:Shaman"]="Als Schamane der Horde vollzieht Ihr die Riten des Rufs des Wassers, um mit den Geistern Zwiesprache zu halten und das Wassertotem zu erlangen, das über Heilung und Erneuerung gebietet.",["faction:Horde"]="Als Mitglied der Horde reist Ihr vom Brachland in Kalimdor in den Silberwald in Lordaeron und durchquert während Eurer Prüfung Gebiete der Verlassenen."},sec={{t="Rückkehr ans Ufer",b="Nach den Prüfungen im südlichen Brachland gibt Brine Euch eine Phiole mit reinstem Wasser. Es stammt aus reinen Quellen und wurde durch Brines Riten geweiht. Ihr tragt es zurück an die Ostküste, wo Islen Wasserdeuter Wacht hält. Das Wasser verbindet Brines Lehren mit den Riten des Totems."},{t="Der Zweck des Saptas",b="Islen erklärt, dass sterbliche Augen Wassergeister nicht ohne Weiteres sehen können. Um ihnen zu begegnen, trinkt Ihr ein Gebräu namens Sapta. Brines Wasser bildet die Grundlage dieses Tranks und öffnet Eure Sinne für das, was dem gewöhnlichen Blick verborgen bleibt. Die Geister zu sehen, ist nur ein Teil der Reise. Sie werden Euch prüfen."},{t="Überfahrt nach Lordaeron",b="Islen schickt Euch über Kalimdor hinaus, über das Meer in den Silberwald, südlich von Unterstadt. Neben einem abgelegenen Schrein trinkt Ihr das Sapta und tretet den Elementaren unmittelbar gegenüber. Erst dann könnt Ihr Euch das Recht verdienen, das Wassertotem zu manifestieren."}},faq={{q="Was enthält die Phiole mit reinstem Wasser?",a="Die Phiole mit reinstem Wasser enthält Wasser, das aus reinen Quellen geschöpft und durch Brines Riten geweiht wurde. Es bildet die Grundlage zum Brauen eines Saptas, das einem Schamanen erlaubt, mit Wassergeistern zu sprechen.",al={"phiole mit reinstem wasser","brines wasser","was hat brine mir gegeben"}},{q="Wer ist Islen Wasserdeuter?",a="Islen Wasserdeuter ist eine betagte Schamanin, die an der abgeschiedenen Südostküste des Brachlands lebt, südlich von Ratschet. Sie leitet Schamanen der Horde an, die Zwiesprache mit dem Wasser suchen und das Wassertotem erlangen wollen.",al={"islen","wer ist islen wasserdeuter","islen wasserdeuter geschichte"}},{q="Was ist ein Sapta?",a="Ein Sapta ist ein zeremonieller Trank, den schamanische Lehrmeister zubereiten. Er verändert die Wahrnehmung eines Schamanen und lässt ihn Elementargeister sehen und ihnen begegnen, die sterblichen Augen verborgen bleiben.",al={"sapta bedeutung","water sapta","was bewirkt sapta"}},{q="Warum muss ich als Nächstes in den Silberwald?",a="Der Schrein für diese Zwiesprache liegt in den Küstengewässern des Silberwalds, südlich von Unterstadt in den Östlichen Königreichen. Die dortigen Geister verlangen, dass Ihr ihnen begegnet und Euch einer letzten Prüfung stellt, bevor Ihr das Wasser beherrscht.",al={"warum silberwald","silberwald wassertotem","schrein im silberwald"}},{q="Wo lebt Brine?",a="Brine lebt in einer abgeschiedenen Hütte im südlichen Brachland, hoch in den Hügeln westlich der Straße zum Großen Aufzug und nach Tausend Nadeln.",al={"brine aufenthaltsort","wo ist brine","brine finden"}},{q="Kann ein Schamane die Herstellung des Saptas umgehen?",a="Nein. Die Riten der Zwiesprache verlangen, dass Euer Geist auf die unsichtbare Welt eingestimmt ist. Ohne ein Sapta, das diesen Weg öffnet, könnt Ihr den Wassergeistern am Schrein weder begegnen noch sie herausfordern.",al={"sapta überspringen","ist sapta erforderlich","schamanische visionssuche"}}},fx={["5a67c999"]={q="Warum schickt Euch Brine zurück zu Islen Wasserdeuter?",a="Brine hat ihren Teil getan, indem sie die Gewässer, die Ihr in ganz Kalimdor gesammelt habt, gereinigt und in ein gesegnetes Fläschchen versiegelt hat. Sie weiß, dass sie nur eine Wegweiserin auf Eurem Pfad ist, nicht die Seherin, die Euch in die tieferen Mysterien einweiht. Islen Wasserdeuter schickte Euch zu Brine, um Eure Ausdauer zu beweisen, und nun, da das reinste Wasser vorbereitet ist, besitzt allein Islen die Weisheit, Eure Sapta zu brauen und die letzte Prüfung Eurer Verbindung zu leiten.",al={"warum schickt euch brine","brine motiv ruf des wassers","warum zurück zu islen"}},["51ede7cd"]={q="Warum muss Brine, dass Ihr das Fläschchen tragt, anstatt es selbst zu überbringen?",a="Diese Pilgerreise ist Eure Prüfung als Schamane, keine lästige Besorgung. Das Fläschchen enthält Wasser, das Ihr persönlich aus dem Wasserloch unterhalb von Brines Hütte im Brachland, dem Brunnen bei Tarrens Mühle und den The Ruins of Stardust im Eschental geschöpft habt, gesegnet durch Eure eigene Arbeit. Es über die Ebenen zurück zu Islen zu tragen, vollendet Eure persönliche Verbindung zum Element, bevor Ihr versucht, mit den Geistern zu kommunizieren.",al={"warum muss ich das fläschchen liefern","warum ich brine ruf des wassers","warum kann brine es nicht nehmen"}}},fp="13,231,19.287.0,24.282.0,23.236.1,40.185.0,23.183.0,16.167.0,46.222.0,22.133.0,39.174.0"}
P.entries["quest:2205"] = {n="Aufsuchen des SI:7",s="Von Goldhain schickt Keryn Sylvius neue Schurken mit einem versiegelten Paket nach Sturmwind. Die Lieferung führt sie vor Meister Mathias Shaw, der das verdeckte Geheimdienstnetzwerk der Krone leitet.",h="Von Goldhain schickt Keryn Sylvius neue Schurken mit einem versiegelten Paket nach Sturmwind.",kw={"goldhain","keryn sylvius","mathias shaw","die altstadt","schurke","aufsuchen des si:7","si:7","sturmwind"},ang={["class:Rogue"]="Als Schurke tretet Ihr Sturmwinds führendem Geheimdienst bei und wechselt von Hinterhoftricks zur Aufklärung im Dienst der Krone.",["faction:Alliance"]="Als Mitglied der Allianz verlasst Ihr Euch auf den SI:7, um das Reich vor Bedrohungen innerhalb und außerhalb seiner Grenzen zu schützen, während König Varian Wrynn weiterhin vermisst wird."},sec={{t="Die Prüfung eines Kuriers",b="Schurkenlehrerin Keryn Sylvius bezweifelt, dass frische Rekruten wie Geheimagenten aussehen. Sie gibt ihnen eine versiegelte Lieferung für die Hauptstadt und prüft damit ihre Zuverlässigkeit als Kuriere. Dabei beurteilt sie unauffällig, ob sie dem Reich als Späher dienen könnten."},{t="Hinter verschlossenen Türen der Altstadt",b="Der SI:7, auch Sturmwind Intelligence, Section 7 genannt, operiert vom Südosten der Altstadt in Sturmwind aus. In diesem heruntergekommenen Viertel überwacht Meister Mathias Shaw die verdeckten Operationen des Königreichs. Er nimmt das Paket mit trockener Skepsis entgegen und prüft dann, ob Ihr die nötige Härte für echte Spionage besitzt."}},faq={{q="Was ist der SI:7?",a="SI:7 bedeutet Sturmwind Intelligence, Section 7. Von seinem Hauptquartier in der Altstadt aus leitet Meister Mathias Shaw dessen geheime Nachrichtendienstarbeit und verdeckte Operationen für das Königreich Sturmwind.",al={"was bedeutet si 7","was ist si7","si:7 hintergrundgeschichte"}},{q="Wer ist Keryn Sylvius?",a="Keryn Sylvius bildet im Gasthaus \"Zur Höhle des Löwen\" in Goldhain Schurken aus. Sie arbeitet mit dem SI:7 zusammen, beurteilt örtliche Rekruten und schickt vielversprechende Späher zu Meister Mathias Shaw nach Sturmwind.",al={"keryn sylvius","schurkenlehrer goldhain"}},{q="Wo befindet sich Mathias Shaw in Sturmwind?",a="Meister Mathias Shaw befindet sich im Obergeschoss des SI:7-Hauptquartiers im Südosten der Altstadt von Sturmwind, hinter den Schurkenlehrern der Stadt.",al={"wo ist shaw","mathias shaw finden","mathias shaw standort"}},{q="Was geschieht nach der Übergabe des Pakets an Shaw?",a="Nachdem Ihr Euch bei Mathias Shaw gemeldet habt, prüft er Eure Fähigkeiten als Schurke. Er schickt Euch zu Jerods Anlegestelle, um einem Hafenmeister der Defias einen Frachtplan zu stehlen.",al={"nächste quest nach aufsuchen des si:7","was will shaw"}},{q="Warum verspottet Keryn den Spieler, bevor sie die Lieferung übergibt?",a="Die Agenten des SI:7 schätzen Können und einen scharfen Instinkt. Keryn Sylvius behandelt neue Rekruten schroff, um ihr Temperament zu beurteilen und festzustellen, ob sie die Entschlossenheit besitzen, vor Meister Shaw zu treten.",al={"warum beleidigt keryn mich","käselieferung beleidigung"}}},fx={["5aa3ad9f"]={q="Warum möchte Keryn Sylvius, dass dieses Paket an Mathias Shaw geliefert wird?",a="Keryn hat sich formell dazu verpflichtet, das Paket an Meister Mathias Shaw als Teil eines offiziellen Auftrags auszuliefern. Während sie es sichtlich verschmäht, selbst einfache Botengänge zu erledigen, dient es Euch zu schicken einem doppelten Zweck: Es ehrt ihre Verpflichtung gegenüber der Agentur und stellt gleichzeitig Eure angehenden Fähigkeiten als Schurke vor ihren Vorgesetzten in Sturmwind auf die Probe.",al={"warum an mathias liefern","keryn sylvius motiv","warum paket an si:7 schicken"}},["6bd14f9c"]={q="Warum schickt Keryn einen unerprobten Schurken, anstatt das Paket selbst auszuliefern?",a="Keryn ist in Goldhain stationiert, um neue Talente auszukundschaften und zu betreuen, weshalb sie wenig Interesse daran hat, kleine Lieferungen zurück zur Altstadt zu bringen. Die Aufgabe an einen eifrigen Neuling wie Euch abzugeben, erspart ihr die Laufarbeit und dient gleichzeitig als praktisches Vorsprechen, um zu sehen, ob Ihr scharf genug seid, das Hauptquartier des Geheimdienstes von Sturmwind zu finden.",al={"warum schickt mich keryn","warum ich si:7 aufsuchen","warum liefert sie es nicht selbst"}}},fp="14,191,16.247.0,31.284.0,13.180.0,21.181.0,43.140.0,50.148.1,64.186.0"}
P.entries["quest:2206"] = {n="Schneller Eingriff",s="An Jerods Anlegestelle lässt Meister Mathias Shaw Agenten erkunden, wie die Defias ihre Vorräte transportieren. Die Bruderschaft nutzt den Flussanleger, um heimlich Waren zu verschiffen.",h="An Jerods Anlegestelle lässt Meister Mathias Shaw Agenten erkunden, wie die Defias ihre Vorräte...",kw={"kristallsee","defias","hafenmeister","goldhain","jerods anlegestelle","mathias shaw","shipping schedule","si:7","schneller eingriff"},ang={["class:Rogue"]="Als Schurke lernt Ihr den SI:7 kennen und beweist Eure Heimlichkeit und Euren Instinkt als Taschendieb. Verdient Euch Mathias Shaws Anerkennung und eine unverwechselbare Klinge.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, Vorräte der Defias an Jerods Anlegestelle abzufangen. Das schützt den Wald von Elwynn und schwächt das Verbrechersyndikat, das die Gebiete rund um Sturmwind bedroht."},sec={{t="Eine Prüfung der Spionagekunst",b="Meister Mathias Shaw prüft jene, die einen Platz unter Sturmwinds verdeckten Agenten suchen. Er verlangt Finesse und Heimlichkeit, keine rohe Gewalt. Agenten des SI:7 schalten wichtige Zielpersonen lautlos aus und beschaffen bedeutende Dokumente. Dabei vermeiden sie es, das Reich in einen offenen Skandal zu verwickeln. Jeder neue Agent muss beweisen, dass er unbemerkt arbeiten kann."},{t="Schmuggler auf dem Fluss",b="Jerods Anlegestelle liegt am Fluss im südlichen Elwynn, südlich von Goldhain und knapp östlich der Weinberge der Maclures. Die Bruderschaft der Defias besetzte den einst ruhigen Anleger und machte ihn zu einer illegalen Transportroute. Waffen, Vorräte und Schmuggelware gelangen vom Rotkammgebirge über das Wasser nach Westfall. Die königlichen Straßenpatrouillen können sie dort nicht erreichen."},{t="Glaubhafte Abstreitbarkeit",b="Meister Mathias Shaw warnt Agenten, dass sie bei Gefangennahme, Enttarnung oder Tod ohne Unterstützung der Krone dastehen. Sturmwind und seine Spionagemeister werden leugnen, dass sie je existiert haben. Der Zeitplan des Hafenmeisters der Defias liefert dem SI:7 Beweise für die Nachschublinien der Bruderschaft. Seine Beschaffung hält Sturmwinds offizielle Beteiligung verborgen."}},faq={{q="Wer vergibt die Quest Schneller Eingriff?",a="Meister Mathias Shaw, der Leiter von Sturmwinds Geheimdienst SI:7, erteilt den Auftrag vom Hauptquartier in der Altstadt aus.",al={"wer vergibt schneller eingriff","questgeber schneller eingriff"}},{q="Wo liegt Jerods Anlegestelle?",a="Jerods Anlegestelle ist ein Flussanleger im südlichen Wald von Elwynn, südlich von Goldhain und knapp östlich der Weinberge der Maclures. Die Bruderschaft der Defias kontrolliert die Anlegestege und das Hafenhaus.",al={"jerods anlegestelle lage","wo liegt jerods anlegestelle","hafenmeister standort"}},{q="Was schmuggeln die Defias über Jerods Anlegestelle?",a="Die Defias transportieren Schmuggelware und Vorräte über das Wasser zwischen dem Rotkammgebirge und Westfall, außerhalb der Reichweite königlicher Wachposten und Straßenkontrollen.",al={"was wird geschmuggelt","defias schmuggelware"}},{q="Wer trägt den Lieferzeitplan der Defias bei sich?",a="Der Hafenmeister der Defias trägt den Lieferzeitplan bei sich und bewacht das Hafenhaus an Jerods Anlegestelle.",al={"wo ist shipping schedule","wer lässt den zeitplan fallen","hafenmeister der defias"}},{q="Was geschieht, wenn ein Agent während dieser Mission gefangen genommen wird?",a="Meister Mathias Shaw warnt, dass der SI:7 jede Verbindung zu einem Agenten leugnen wird, der enttarnt oder gefangen genommen wird.",al={"was geschieht bei einem fehlschlag","vom si7 verleugnet"}},{q="Warum interessiert sich der SI:7 für diesen Lieferzeitplan?",a="Der Zeitplan beschreibt genau, wie die Bruderschaft der Defias Schmuggelware zwischen dem Rotkammgebirge und Westfall transportiert. Er ermöglicht Sturmwinds Spionagenetz, die Nachschublinien des Feindes zu erfassen, ohne das Syndikat aufzuschrecken.",al={"warum wird der zeitplan benötigt","si7 shipping schedule"}}},fx={["170a7301"]={q="Was ist der Lieferzeitplan der Defias?",a="Der Zeitplan beschreibt den Transport illegaler Waren über die Wasserwege im Wald von Elwynn. The Defias Brotherhood hat Jerods Anlegestelle beschlagnahmt, um große Mengen an Schmuggelware zwischen Rotkammgebirge und Westfall direkt unter der Nase des Reiches zu befördern. Die Wiederbeschaffung dieser Fahrpläne liefert SI:7 konkrete Informationen über die Bewegungskorridore und logistischen Routen der Defias.",al={"lieferzeitplan der defias","was ist lieferzeitplan","nutzen lieferzeitplan"}},["5dd0ffd3"]={q="Wer ist der Defias Dockmaster?",a="Der Dockmaster überwacht die verdeckten Operationen der Brotherhood an Jerods Anlegestelle, einem Hafenhaus am Fluss südlich von Goldhain. Von diesem Aussichtspunkt aus koordiniert er den Fluss geschmuggelter Vorräte, Waffen und gestohlener Fracht, die zwischen Rotkammgebirge und Westfall bewegt werden, und führt die Frachtmanifeste der Defias-Flussläufer bei sich.",al={"defias dockmaster","wer ist der dockmaster","dockmaster jerods anlegestelle"}},a07026c6={q="Warum schickt Mathias Shaw Euch anstelle von erfahrenen SI:7-Agenten?",a="Ihr wurdet als vielversprechender neuer Schurkenrekrut, der von Keryn Sylvius entdeckt wurde, zu Mathias Shaw geschickt. Das Infiltrieren von Jerods Anlegestelle dient sowohl als echter operativer Test Eurer Heimlichkeit und Diebeskunst als auch als eine abstreitbare Feldmission. Da SI:7 plant, jegliche Kenntnis von Euch abzustreiten, falls Ihr erwischt werdet, schützt die Verwendung eines grünen Agenten das führende Geheimdienstnetzwerk Sturmwinds vor öffentlicher Enthüllung.",al={"warum schickt mich das","warum rekrutieren für si:7","warum braucht euch mathias shaw"}}},fp="15,158,20.313.0,22.321.0,21.312.0,38.121.0,25.175.0,54.135.0,41.97.0,61.104.0,48.197.0"}
P.entries["quest:221"] = {n="Worgen in den Wäldern",s="Nightbane Dark Runners rücken vom Verrottenden Obstgarten im Dämmerwald auf Dunkelhain vor. Calor schickt Euch los, um ihre Reihen zu lichten, bevor das Rudel die Stadt umzingeln kann.",h="Nightbane Dark Runners rücken vom Verrottenden Obstgarten im Dämmerwald auf Dunkelhain vor.",kw={"calor","carevin","dark runner","dunkelhain","dämmerwald","night watch","nightbane","der verrottende obstgarten","worgen"},ang={["class:Hunter"]="Als Jäger steht Ihr im Verrottenden Obstgarten unnatürlichen, zweibeinigen Wölfen gegenüber. Ihre Instinkte widersprechen Azeroths natürlicher Ordnung.",["faction:Alliance"]="Der Dämmerwald hat von der Krone Sturmwinds fast keine Verstärkung erhalten. Die örtlichen Freiwilligen der Nachtwache sind auf durchreisende Helden der Allianz angewiesen, um die herandrängenden Raubtierrudel zu dezimieren."},sec={{t="Der Ring zieht sich zu",b="Calors Erkundungen haben eine größere Gefahr aufgedeckt als den einzelnen Worgen, der zuerst am Waldrand beim Wirken schattenhafter Magie gesichtet wurde. Größere und schnellere Nightbane Dark Runners haben sich im Verrottenden Obstgarten versammelt, direkt südwestlich von Dunkelhain. Sie stellen den Großteil des Rudels und haben den Obstgarten zu einem Sammelplatz in Schlagdistanz zu den Dorftoren gemacht."},{t="Eine unerschöpfliche Flut",b="Wenn Ihr einen Dark Runner fällt, verschafft das der Nachtwache nur kurz Erleichterung. Calor sieht an seiner Stelle einen anderen durch den Nebel streifen, und die Verteidiger können sich weder die Widerstandskraft noch die Zahl der Nightbane erklären. Sie wenden sich an erfahrene Monsterjäger wie Meister Jonathan Treuwein, um herauszufinden, welcher finstere Auslöser diese fremdartigen Schrecken in den Dämmerwald gerufen hat."}},faq={{q="Was sind Nightbane Dark Runners?",a="Nightbane Dark Runners sind größere, furchteinflößende Worgen, die im Dämmerwald die Hauptstreitmacht des Rudels an vorderster Front bilden. Anders als die mystischen Shadow Weavers verlassen sie sich auf Schnelligkeit, Klauen und raubtierhafte Wildheit.",al={"dark runners","was sind dark runners","nightbane dark runner"}},{q="Wo liegt der Verrottende Obstgarten?",a="Der Verrottende Obstgarten liegt direkt südwestlich von Dunkelhain. Einst fruchtbares Ackerland, ist er heute eine verderbte Lichtung, die das Rudel der Nightbane als Stützpunkt nahe der Stadt besetzt hat.",al={"lage des verrottenden obstgartens","wo ist der verrottende obstgarten"}},{q="Wer ist Calor?",a="Calor ist ein Waldläufer in Dunkelhain, der Meister Jonathan Treuwein dient. Er erkundet die Außenbezirke der Siedlung und verfolgt die Worgenrudel, die das Überleben der Stadt bedrohen.",al={"wer ist calor","calor dämmerwald","calor questgeber"}},{q="Warum scheint die Zahl der Worgen den Verteidigern endlos?",a="Die Verteidiger können sich die übernatürliche Präsenz der Worgen nicht erklären. Sie glauben, dass eine böse Macht die Bestien in den Dämmerwald beschwört oder lockt, sodass neue Wellen ebenso schnell auftauchen, wie andere erschlagen werden.",al={"warum so viele worgen","unerschöpfliche worgen","woher kommen worgen"}},{q="Wer ist Meister Carevin?",a="Meister Jonathan Treuwein führt von Dunkelhain aus den Kampf seiner Familie gegen die Untoten und andere Übel des Dämmerwalds. Calor vertraut auf seine Fachkenntnis, um die Ursache für die Ungeheuerplagen zu finden, die der Region zusetzen.",al={"meister carevin","jonathan treuwein","wer ist carevin"}},{q="Wie trägt diese Aufgabe zur Verteidigung von Dunkelhain bei?",a="Dunkelhain ist abgeschnitten, seine Vorräte schwinden, und Sturmwind hat keine Hilfe geschickt. Den Verrottenden Obstgarten zu räumen, hindert die Nightbane daran, von dort aus unmittelbar überwältigende Überfälle auf den südwestlichen Stadtrand zu führen.",al={"warum dark runners töten","verteidigung von dunkelhain"}}},fx={e2dcc78b={q="Warum will Calor, dass die Nightbane-Finsterläufer erlegt werden?",a="Calor verfolgt die tierischen Übergriffe um Dunkelhain und weiß, dass die Finsterläufer den Großteil der Worgen-Streitkräfte ausmachen, die im Wald umherstreifen. Schlimmer noch, sie haben den verlassenen Obstgarten südwestlich der Stadt komplett überrannt. Ein solch großes und wildes Rudel so nahe an Dunkelhain ungehindert zu lassen, führt zum Desaster, also muss er ihre Anzahl verringern, bevor die Siedlung überwältigt wird.",al={"calor motiv","warum finsterläufer töten","warum will calor dass dies erledigt wird"}},["99fe833d"]={q="Warum verlässt sich Calor auf Euch, anstatt den Obstgarten selbst zu säubern?",a="Calor ist ein Kundschafter und Waldläufer, dessen Hauptaufgabe darin besteht, den Wald im Auge zu behalten, Tierbewegungen zu verfolgen und Bedrohungen an Dunkelhain zu melden. Die Nightbane-Worgen sind aggressiv, zäh und scheinbar unerschöpflich, was die Verteidiger der Stadt bis an ihre Grenzen belastet. Da Dunkelhain von allen Seiten von Schrecken belagert wird, sind Waldläufer wie Calor auf fähige Abenteurer angewiesen, um den Kampf direkt in die befallenen Haine wie den verlassenen Obstgarten zu tragen.",al={"warum ich","warum macht calor es nicht","warum braucht calor hilfe"}}},fp="19,158,22.351.0,21.333.1,32.192.0,37.164.0,13.164.0,56.200.0,22.208.0,53.204.0"}
P.entries["quest:2218"] = {n="Straße der Rettung",s="Hogral Bakkan schickt Euch zu Hulfdan Blackbeard in Eisenschmiede. Hulfdan prüft, ob Ihr Euch für einen Schurken haltet, der würdig ist, sich seinen wenigen Auserwählten anzuschließen.",h="Hogral Bakkan schickt Euch zu Hulfdan Blackbeard in Eisenschmiede.",kw={"wenige auserwählte","hidden circle","hulfdan blackbeard","eisenschmiede","road to salvation","schurke"},sec={{t="Hulfdans Prüfung",b="Hulfdan Blackbeard in Eisenschmiede möchte wissen, ob Ihr Euch als Schurken seht. Er zieht Euch für einen Platz unter den wenigen Auserwählten des Hidden Circle in Betracht. Seine Antwort hängt davon ab, wie viel Ihr von Euch selbst haltet."}},faq={{q="Wer bittet darum, mit mir zu sprechen?",a="Hogral Bakkan schickt Euch nach Eisenschmiede, um mit Hulfdan Blackbeard zu sprechen.",al={"wer ist hulfdan","hulfdan blackbeard"}},{q="Was ist der Hidden Circle?",a="Der Hidden Circle ist eine Organisation mit auserwählten Mitgliedern und Offizieren. Hulfdan Blackbeard sucht Schurken, die seinen wenigen Auserwählten beitreten sollen.",al={"hidden circle","welcher kreis"}},{q="Warum nennt Hulfdan mich einen Schurken?",a="Hulfdan fragt, ob Ihr Euch für einen Schurken haltet, der würdig ist, den wenigen Auserwählten des Hidden Circle beizutreten.",al={"hulfdan schurke","warum schurke"}},{q="Was will Hulfdan von mir?",a="Hulfdan möchte mit Euch darüber sprechen, einer der wenigen Auserwählten des Hidden Circle zu werden.",al={"was hulfdan will","blackbeard rekrutierung"}}},fp="17,140,14.214.0,31.70.0,26.139.0,37.95.0,31.85.0"}
P.entries["quest:222"] = {n="Worgen in den Wäldern",s="Calor schickt Euch gegen das Rudel der Nachtheuler im südlichen Dämmerwald aus. Ihre Höhlen und Minen bringen die Worgenbedrohung nahe an Dunkelhain heran.",h="Calor schickt Euch gegen das Rudel der Nachtheuler im südlichen Dämmerwald aus.",kw={"calor","carevin","dunkelhain","dämmerwald","nachtheuler","besudelter","übelfang","worgen"},ang={["class:Hunter"]="Als Jäger steht Ihr mit dem listigen Rudel der Nachtheuler einer ungewöhnlichen Beute gegenüber. Bleibt nahe ihren dunklen Höhlen wachsam.",["faction:Alliance"]="Als Reisender der Allianz helft Ihr, Dunkelhains Versorgungswege und die verbliebenen Gehöfte im Dämmerwald zu schützen, indem Ihr die südlichen Höhlen säubert."},sec={{t="Ein wildes Bollwerk",b="Südlich von Dunkelhain befestigen die Nachtheuler Höhlen und verlassene Minenschächte als Lager. Calor beobachtet ihre Lagerfeuer und fürchtet, was ihr wachsender Einfluss für die Stadt bedeutet. Die Übelfänge und Besudelten sind die wildesten Züchtungen des Rudels. Ihre Wildheit und Zähigkeit bedrohen Dunkelhains äußere Verteidigung."},{t="Calors Empfehlung",b="Calor wacht über Dunkelhains Front und weiß, wie gefährlich die Worgen sind. Die Übelfänge und Besudelten zu besiegen, stellt jeden Helden auf die Probe. Wer sie bezwingt, verdient sich seinen Respekt und eine persönliche Empfehlung an Meister Carevin, der den umfassenderen Kampf gegen die Worgen koordiniert."}},faq={{q="Wo sind die Übelfänge und Besudelten zu finden?",a="Die Übelfänge und Besudelten sammeln sich bei Höhlen und der Mine im südlichen Dämmerwald, oft nahe den Lagerfeuern.",al={"wo sind die besudelten","wo sind die übelfänge","worgen fundorte dämmerwald"}},{q="Wer ist Calor?",a="Calor lebt in Dunkelhain und behält die Worgenbedrohung in den Wäldern im Auge. Er wirbt fähige Abenteurer an, um ihren Vormarsch aufzuhalten.",al={"calor dunkelhain","wer vergibt worgen in den wäldern drei"}},{q="Wer ist Meister Carevin?",a="Meister Carevin ist Jonathan Treuwein aus Dunkelhain. Seine Familie bekämpft das Böse in der Region, und er koordiniert die Bemühungen, die Worgen in der Umgebung auszurotten.",al={"meister carevin","carevin dämmerwald"}},{q="Warum haben die Worgen Lagerfeuer?",a="Die Nachtheuler sammeln sich in organisierten Lagern, nutzen Feuer und halten befestigte Stellungen wie Minen. Ihre Lager offenbaren eine beunruhigende Intelligenz hinter ihrem monströsen, wolfsähnlichen Äußeren.",al={"warum machen worgen feuer","nachtheuler lagerfeuer"}},{q="Was geschieht nach Abschluss dieser Jagd?",a="Wenn Ihr Calor beeindruckt, erhaltet Ihr ein Empfehlungsschreiben für Meister Carevin. Dann könnt Ihr ihm in der nächsten Phase der Jagd helfen.",al={"nächste quest nach worgen in den wäldern drei","worgen in den wäldern folgequest"}},{q="Warum ist Dunkelhain wegen dieser Worgen so besorgt?",a="Die Übelfänge und Besudelten gehören zu den tödlichsten und aggressivsten Mitgliedern des Rudels. Wenn sie bei den südlichen Minen nicht aufgehalten werden, könnten sie die umliegenden Straßen überrennen.",al={"warum nachtheuler übelfang","übelfang gefahr"}}},fx={["0c2f2969"]={q="Warum will Calor, dass diese Worgen getötet werden?",a="Calor arbeitet daran, Dunkelhain zu beschützen und Meister Treuweins laufenden Kreuzzug gegen die lupine Bedrohung zu unterstützen. Das Nightbane-Rudel hat sich im Süden verschanzt, Lagerfeuer entzündet und Stützpunkte in Höhlen und Minen errichtet. Indem er Euch schickt, um ihre tödlichsten Kämpfer auszumerzen, hofft Calor, die Stärke des Rudels zu schwächen, bevor sie die wenigen verbliebenen Verteidigungskräfte im Dämmerwald überwältigen.",al={"warum die worgen töten","calor motiv","warum will calor das"}},["5cfb2401"]={q="Was sind die Vile Fangs und Tainted Ones, die Ihr jagt?",a="Sie gehören zu den tödlichsten und grausamsten Mitgliedern des Nightbane-Rudels. Im Gegensatz zu den niedereren Bestien, die durch die Wildnis streifen, haben diese Worgen Lager in der Nähe von Rolands Verdammnis und anderen südlichen Höhlen errichtet, brennende Feuer entfacht und eine gerissene, koordinierte Präsenz gezeigt, die ganz Dunkelhain bedroht.",al={"wer sind die vile fangs","tainted ones dämmerwald","ziel worgen"}},["5e6f00dd"]={q="Warum rekrutiert Calor Euch, anstatt die Bestien selbst zu erledigen?",a="Die Verteidiger von Dunkelhain, The Nachtwache, sind bei der Bewachung des Stadtperimeters gegen Untote, Spinnen und bösartige Bestien bis an ihre Grenzen belastet. Den Kampf tief in das Worgen-Gebiet zu tragen erfordert erfahrene Recken, die dunkler Magie und roher Wildheit standhalten können, und Eure vergangenen Erfolge haben Calor bewiesen, dass Ihr die Fähigkeiten zum Überleben habt.",al={"warum braucht mich calor","warum schickt man mich","warum kümmert sich die night watch nicht darum"}}},fp="19,131,16.308.0,19.276.1,50.107.0,13.122.0,22.147.0,32.194.0,40.125.0,58.175.0"}
P.entries["quest:223"] = {n="Worgen in den Wäldern",s="In Worgen in den Wäldern schickt Calor Euch mit einem Brief für Jonathan Treuwein nach Dunkelhain. Eure Jagden auf die Worgen im Dämmerwald haben Euch sein Vertrauen eingebracht, und er glaubt, dass Euer Können Treuwein helfen kann.",h="In Worgen in den Wäldern schickt Calor Euch mit einem Brief für Jonathan Treuwein nach Dunkelhain.",kw={"calor","calors notiz","dunkelhain","dämmerwald","jonathan treuwein","night watch","worgen in den wäldern"},ang={["class:Paladin"]="Als Paladin heißt Treuwein bewährte Verbündete im Namen des Heiligen Lichts willkommen und sucht heilige Streiter gegen die unheiligen Übel des Dämmerwalds.",["class:Priest"]="Als Priester hört Ihr Treuweins Abschiedssegen: „Ruhm unter dem Licht.“ Er zeugt vom Glauben der Verteidiger inmitten der endlosen Verderbnis Dunkelhains.",["faction:Alliance"]="Da das Königreich Sturmwind keine Soldaten für die Grenzlande des Dämmerwalds entbehren kann, sind unabhängige Abenteurer der Allianz und Selbstjustiz übende Bürger wie Treuwein die einzige Verteidigung der Stadt."},sec={{t="Eine seltene Empfehlung",b="Ihr habt das Rudel der Nachtheuler aus Rolands Verdammnis und den schattigen Lichtungen vertrieben und Euch damit Calors Respekt verdient. Er dient an der finsteren Grenze des Waldes und spricht nur selten Lob oder förmliche Empfehlungen aus. Nun gibt er Euch ein verblichenes Stück Pergament für Jonathan Treuwein in Dunkelhain. Calor glaubt, dass mehr Kämpfer Eures Schlags seiner kleinen Truppe helfen könnten, die bedrängte Nachtwache der Stadt in den Schatten zu stellen."},{t="Treuweins Wacht",b="Jonathan Treuwein arbeitet in Dunkelhain unter großem Druck. Worgen, rastlose Untote, dämonische Mächte und Kultisten, die der Verderbnis von innen heraus helfen, bedrohen die Stadt. Obwohl er Fremden misstraut und wenig Zeit hat, vertraut Treuwein auf Calors Empfehlung. Er sieht in Euch einen verlässlichen Kämpfer, der helfen kann, das Licht gegen die Schrecken des Dämmerwalds zu bewahren."}},faq={{q="Wer schickt mich auf diese Mission?",a="Calor schickt Euch los, um Jonathan Treuwein ein verblichenes Empfehlungsschreiben zu überbringen. Eure Erfolge gegen die Worgenrudel im gesamten Dämmerwald haben Euch seinen Respekt eingebracht.",al={"questgeber","wer beginnt die quest","calor"}},{q="Wer ist Jonathan Treuwein?",a="Jonathan Treuwein lebt in Dunkelhain und koordiniert die Verteidigung der Stadt gegen übernatürliche Bedrohungen. Er misstraut Fremden und arbeitet mit vertrauten Verbündeten wie Calor gegen Untote, Dämonen und deren Helfer.",al={"treuwein","wer ist treuwein","meister treuwein"}},{q="Warum hält Calor so wenig von der Nachtwache?",a="Calor glaubt, dass die Nachtwache Mühe hat, den vielen Gefahren des Dämmerwalds zu begegnen. Er meint, ein paar fähige Kämpfer könnten mehr ausrichten als die kleine Truppe der Stadt.",al={"calor night watch","die night watch zahlenmäßig übertreffen","warum mit der night watch konkurrieren"}},{q="Vor welchen Bedrohungen warnt Treuwein bei der Übergabe?",a="Treuwein steht Worgen, rastlosen Untoten, dämonischen Mächten und Kultisten gegenüber, die der Verderbnis von innen heraus helfen. Von allen Seiten wird die Stadt bedroht.",al={"treuweins feinde","was sagt treuwein","was bekämpfen wir"}},{q="Erfordert diese Quest Kämpfe?",a="Nein. Ihr müsst nur Calors Brief zu Treuwein in Dunkelhain bringen. Eure früheren Jagden auf die Nachtheulerworgen liegen bereits hinter Euch.",al={"kämpfe nötig","muss etwas getötet werden","nur überbringen"}},{q="Wo finde ich Jonathan Treuwein?",a="Jonathan Treuwein ist in Dunkelhain und kümmert sich um die Verteidigung der Stadt.",al={"treuweins standort","wo ist treuwein","wo abgeben"}}},fx={f56a577c={q="Warum schickt Euch Calor zu Jonathan Treuwein?",a="Calor glaubt, dass Ihr Euren Mut in den Wäldern bewiesen habt, und möchte Euch formell seinem Vorgesetzten, Meister Jonathan Treuwein, vorstellen. Sein kleiner Orden operiert im Schatten von Dämmerwald abseits der schwer bedrängten The Nachtwache, und er hofft, dass es ihre geheimen Bemühungen gegen die dunkleren Bedrohungen, die die Region plagen, stärkt, kompetente Kämpfer wie Euch in ihren Kreis aufzunehmen.",al={"warum zu carevin schicken","calor motiv","warum notiz zu carevin bringen"}},["47a08b52"]={q="Warum verlässt sich Calor auf Euch und nicht auf die The Nachtwache?",a="Calor hat wenig Vertrauen in die herkömmliche Stadtwache und hält die The Nachtwache für unzureichend für die düstere, spezialisierte Arbeit, die sein Orden verrichtet. Da Ihr Eure Fähigkeiten unter Beweis gestellt habt, indem Ihr Euch direkt mit der Worgenbedrohung auseinandergesetzt habt, wo andere versagten, sieht er Euch als jemanden, der wirklich in der Lage ist, ihren geheimen Kreuzzug gegen die dunkleren Schrecken des Dämmerwalds zu unterstützen.",al={"warum nicht night watch","warum vertrauen mir die wachen nicht","warum braucht calor mich"}}},fp="19,197,21.382.0,15.339.0,29.158.0,24.210.0,46.153.0,51.150.0,35.137.0,34.66.0"}
P.entries["quest:224"] = {n="Verteidigung der Länder des Königs",s="Am südlichen Wachturm ruft Gebirgsjäger Cobbleflint um Hilfe, während Splittersteintroggs zum Tal der Könige vordringen. Eisenschmiedes Streitkräfte dienen an fernen Fronten.",h="Am südlichen Wachturm ruft Gebirgsjäger Cobbleflint um Hilfe, während Splittersteintroggs zum Tal der Könige...",kw={"cobbleflint","gravelgaw","eisenschmiede","loch modan","gebirgsjäger","splitterstein","trogg","tal der könige"},ang={["class:Hunter"]="Als Jäger könnt Ihr die Felsklippen und Vorsprünge des Splittersteintals nutzen, um Troggwachposten und Späher von erhöhten Positionen aus ins Visier zu nehmen.",["faction:Alliance"]="Als Abenteurer der Allianz folgt Ihr Eisenschmiedes Ruf, indem Ihr helft, das Tal der Könige zu sichern, während zwergische Truppen an fernen Fronten der Verbündeten dienen.",["race:Dwarf"]="Als Zwerg helft Ihr mit Eurer Antwort auf Cobbleflints Ruf, König Magnis angestammte Täler gegen unterirdisches Ungeziefer zu verteidigen, während das Heer andernorts kämpft."},sec={{t="Schwache Verteidigung im Tal der Könige",b="Cobbleflint und die Wachen sind zu wenige, um die wachsende Trogginvasion unter den gewaltigen Zwergenmonumenten aufzuhalten. König Magni Bronzebart hat einen Großteil seines regulären Heeres ins Ausland entsandt, um die Allianz zu unterstützen. Örtliche Patrouillen und angeheuerte Klingen müssen verhindern, dass die Provinz überrannt wird."},{t="Der Vorstoß der Splittersteintroggs",b="Das Splittersteintal durchschneidet die südlichen Gipfel von Loch Modan, wo sich Troggs aus der Tiefe emporgegraben haben. Ihre Späher erkunden die Straßen, während Krieger Lager auf dem Talboden errichten. Wenn ihnen niemand Einhalt gebietet, bedrohen ihre Trupps die Straßen zu den südlichen Pässen. Die Gebirgsjäger müssen sie ohne Unterlass bekämpfen."}},faq={{q="Warum ist die Garnison in Loch Modan so schwach besetzt?",a="König Magni Bronzebart hat einen Großteil von Eisenschmiedes Streitkräften auf ferne Schlachtfelder der Allianz und zu Außenposten in ganz Azeroth entsandt. Loch Modan und andere Heimatgebiete verlassen sich hauptsächlich auf kleine Gebirgsjägerpatrouillen, die Reisende um Hilfe bitten, um regionale Invasionen zurückzuschlagen.",al={"warum so wenige wachen","wo sind eisenschmiedes soldaten","warum unterbesetzt"}},{q="Wer ist Gebirgsjäger Cobbleflint?",a="Gebirgsjäger Cobbleflint ist ein zwergischer Wachposten am südlichen Wachturm im Tal der Könige. Er koordiniert die Sicherung der südlichen Grenze von Loch Modan und leitet Angriffe gegen die Troggstämme.",al={"cobbleflint","wer vergibt die quest","questgeber"}},{q="Wo liegt das Splittersteintal?",a="Das Splittersteintal liegt südlich von Thelsamar. Sein Eingang liegt nahe der Hauptstraße vor den gewaltigen Zwergenstatuen im Tal der Könige, und die Troggs unterhalten mehrere Lager auf seinem felsigen Talboden.",al={"splitterstein standort","wo sind troggs","splittersteintal finden"}},{q="Was macht Troggs zu einer so ernsten Bedrohung für die Zwerge?",a="Troggs graben sich durch massiven Fels und können Mauern und Befestigungen an der Oberfläche umgehen. Sie können unter Straßen, Siedlungen und Minen hervorbrechen und so Eisenschmiedes Sicherheit gefährden.",al={"bedrohung durch troggs","warum troggs bekämpfen","sind troggs gefährlich"}},{q="Mit wem spreche ich, nachdem ich Cobbleflint geholfen habe?",a="Nachdem Ihr die Reihen der Splittersteintroggs und ihrer Späher gelichtet habt, schickt Cobbleflint Euch zu Gebirgsjäger Gravelgaw. Er befindet sich gleich im angrenzenden Wachturm und leitet die nächste Patrouille entlang der Talfront.",al={"nächste quest","wohin danach","gravelgaw"}},{q="Sind die Splittersteintroggs organisiert?",a="Der Splittersteinclan entsendet spezialisierte Späher, um die Straßen zu erkunden, während Fußsoldaten Verteidigungslager in der gesamten Schlucht halten.",al={"troggspäher","sind troggs klug","splitterstein organisation"}}},fx={abec66b9={q="Warum will Gebirgsjäger Cobbleflint, dass die Troggs dezimiert werden?",a="Gebirgsjäger Cobbleflint betrachtet den Troggbefall als die größte Bedrohung für Loch Modan und Eisenschmiede selbst. Die Kreaturen haben sich aus jeder Spalte nach oben gegraben und bedrohen das Tal der Könige und die umliegenden Ländereien. Da die reguläre Zwergenarmee an entfernten Fronten eingesetzt ist, muss sich Cobbleflint auf mutige Freiwillige verlassen, um ihre schwärmenden Zahlen zu verringern, bevor die örtlichen Türme und Siedlungen völlig überrannt werden.",al={"warum troggs töten","cobbleflint motiv","warum muss cobbleflint troggs töten lassen"}},["515fdd78"]={q="Was machen die Splittersteintroggs in Loch Modan?",a="Die Splittersteintroggs sind wilde unterirdische Mutanten, die sich in den südlichen Teil des Lochs gegraben und Lager im gesamten Splittersteintal errichtet haben. Ihre Späher erkunden ständig das Zwergengebiet und suchen nach Schwachstellen entlang der Talstraßen und in der Nähe des südlichen Wachturms. Wenn man sie nicht aufhält, droht ihr rasches Auftauchen die Reiserouten zu unterbrechen und die Region zu überrennen.",al={"wer sind die troggs","warum sind splittersteintroggs hier","splittersteintroggs ziel"}}},fp="30,170,34.273.0,27.321.0,49.266.0,31.204.0,38.197.0,54.178.0,44.193.0,39.136.0"}
P.entries["quest:2242"] = {n="Das Schicksal ruft",s="Nahe der Lichtung des Orakels bittet Syurna Euch, herauszufinden, was Sethir der Uralte über Teldrassils Verderbnis weiß. Der Satyr hat Gewalt und Diplomatie gleichermaßen abgewehrt.",h="Nahe der Lichtung des Orakels bittet Syurna Euch, herauszufinden, was Sethir der Uralte über Teldrassils...",kw={"dunkelküste","darnassus","das schicksal ruft","tagebuch","die lichtung des orakels","satyr","sethir der uralte","syurna","teldrassil"},ang={["class:Rogue"]="Als Schurke stellt Ihr Euer Können auf die Probe, indem Ihr im Auftrag der Schurkenlehrer von Darnassus einem gefährlichen Satyr unter der Nase vertrauliche Informationen entwendet.",["faction:Alliance"]="Als Verteidiger der Allianz erfahrt Ihr, dass die Verderbnis in Teldrassils Wäldern über die Insel hinaus bis in die nördlichen Gebiete Kalimdors reicht.",["race:NightElf"]="Als Verteidiger der Kaldorei erfahrt Ihr, dass der uralte Fluch der Dunkelküste das Meer nach Teldrassil überquert hat und Eure heilige Zuflucht bedroht."},sec={{t="Eine stille Erkundung",b="Teldrassils wachsende Krankheit beunruhigt die Anführer der Nachtelfen in Darnassus. Syurna, die Schurkenlehrerin, braucht jemanden, der leise vorgeht, denn bewaffnete Patrouillen sind beim Versuch gestorben, Sethir den Uralten zu erreichen. Der Satyr haust auf einem abgelegenen Ast nahe der Lichtung des Orakels. Er hat Gewalt und Diplomatie gleichermaßen abgewehrt. Um herauszufinden, was er weiß, müsst Ihr in seinen Unterschlupf eindringen und seine persönlichen Besitztümer an Euch nehmen."},{t="Ein drohender Schatten von der Dunkelküste",b="Das Tagebuch von Sethir dem Uralten verbindet Teldrassils Verderbnis mit der Fäulnis, die jenseits des nebligen Meeres die Wälder und Gewässer der Dunkelküste verzehrt. Die Krankheit reicht über den Boden unter dem Weltbaum hinaus. Ihre Ausbreitung deutet auf eine gezielte Bosheit hin, die das Kernland der Kaldorei bedroht."}},faq={{q="Wer ist Sethir der Uralte?",a="Sethir der Uralte ist ein Satyr, der sich auf einem Ast nahe dem nördlichen Rand der Lichtung des Orakels auf Teldrassil versteckt. Er hat bewaffnete Angreifer besiegt und friedliche Anfragen jener abgewehrt, die erfahren wollten, was er über die Verderbnis der Insel weiß.",al={"sethir","wer ist sethir","satyr auf der lichtung des orakels"}},{q="Warum will Syurna Sethirs Tagebuch?",a="Syurna glaubt, dass Sethirs Tagebuch Hinweise auf die unnatürliche Krankheit enthält, die sich in Teldrassil ausbreitet. Seine Seiten beschreiben seine Aktivitäten und die dunkle Verderbnis.",al={"warum sethirs tagebuch","syurnas ziel","was steht im tagebuch"}},{q="Was enthüllt das Tagebuch bei Abschluss?",a="Sethirs Tagebuch verbindet die Krankheit in Teldrassils Ästen mit der dämonischen Verderbnis, die jenseits der Meerenge die uralten Wälder und Küsten der Dunkelküste erfasst.",al={"hintergrundgeschichte zum tagebuch","was hat sethir gefunden","verbindung zur dunkelküste"}},{q="Wo erhält man diese Quest?",a="Syurna, die Schurkenlehrerin in Darnassus, gibt Euch diesen Auftrag nach einer ersten Einschätzung Eurer Fähigkeiten.",al={"wo gibt es das schicksal ruft","questgeber für das schicksal ruft","wer vergibt das schicksal ruft"}},{q="Wohin sollten Abenteurer nach Abschluss dieser Mission gehen?",a="Syurna sagt, dass hier in dieser Angelegenheit nichts weiter getan werden kann. Sie belohnt Euch mit einer Klinge für Euren Dienst an Teldrassil.",al={"what comes next","nächster schritt nach das schicksal ruft","nach sethir"}},{q="Warum kümmert sich eine Schurkenlehrerin statt der Druiden um die Verderbnis des Waldes?",a="Gewalt und druidische Diplomatie sind beide an Sethir gescheitert, mit tödlichen Folgen. Syurna setzt auf Heimlichkeit und Infiltration, nachdem offene Bemühungen in Blutvergießen endeten.",al={"warum schurkenquest","warum syurna","warum nicht der zirkel des cenarius"}}},fp="13,158,23.375.0,31.268.1,26.231.0,38.154.0,45.152.1,29.106.0,58.120.1,68.159.0"}
P.entries["quest:2258"] = {n="Reagenzien-Suche im Ödland",s="In Kargath braucht Jarkal Mossmeld Reagenzien aus dem Ödland, um seine Vorräte aufzufüllen. Er bietet Euch Münzen, wenn Ihr sie ihm bringt.",h="In Kargath braucht Jarkal Mossmeld Reagenzien aus dem Ödland, um seine Vorräte aufzufüllen.",kw={"alchemie","ödland","bussardmagen","reißzahn eines klippenkoyoten","jarkal mossmeld","kargath","splitter eines felselementars","uldaman"},sec={{t="Die Regale füllen",b="Jarkal Mossmeld braucht Mägen von fünf Bussarden, Reißzähne von zehn Klippenkoyoten und Splitter von fünf Felselementaren. Beschafft alles direkt von den Kreaturen. Wenn Ihr nicht kämpft, sucht Euch Freunde, die es tun. Jarkal zahlt Euch Münzen, wenn Ihr ihm die Reagenzien bringt."},{t="Nach der Ausbeute",b="Jarkal ist mit Eurer Ausbeute zufrieden und sagt, dass sie eine kleine Weile reichen sollte. Doch er braucht weitere Reagenzien aus den Tiefen der Ausgrabung von Uldaman, wo sie nur schwer zu beschaffen sein werden. Er deutet an, dass der Lohn mehr wert sein könnte als glänzende Münzen."}},faq={{q="Wer benötigt diese Reagenzien?",a="Jarkal Mossmeld, ein durchaus namhafter Alchemist in Kargath, braucht Reagenzien, um seine Vorräte aufzufüllen.",al={"wer vergibt reagenzien-suche im ödland","jarkal mossmeld","wer ist jarkal mossmeld"}},{q="Welche Zutaten braucht Jarkal?",a="Jarkal braucht Mägen von fünf Bussarden, Reißzähne von zehn Klippenkoyoten und Splitter von fünf Felselementaren. Beschafft sie direkt von den Kreaturen.",al={"welche gegenstände werden benötigt","reagenzien aus dem ödland liste","benötigte reagenzien"}},{q="Wo befindet sich Jarkal Mossmeld?",a="Jarkal Mossmeld befindet sich im Außenposten Kargath im Ödland.",al={"jarkal mossmeld standort","wo ist der alchemist von kargath","wo reagenzien-suche im ödland abgeben"}},{q="Was bietet Jarkal im Tausch gegen die Zutaten?",a="Jarkal bietet Euch Münzen, wenn Ihr ihm die Reagenzien nach Kargath bringt. Vorher zahlt er nichts.",al={"reagenzien-suche im ödland belohnung","was gibt es als belohnung"}}},fp="20,116,20.253.0,14.243.1,33.94.0,34.149.0,33.62.0,55.94.0"}
P.entries["quest:2259"] = {n="Erion Schattenflüsterer",s="Vielversprechende Schurken werden aus den Wäldern von Teldrassil nach Darnassus geschickt. In der Enklave des Cenarius weist Erion Schattenflüsterer ihnen den Weg zu Aufgaben jenseits der Wälder.",h="Vielversprechende Schurken werden aus den Wäldern von Teldrassil nach Darnassus geschickt.",kw={"die enklave des cenarius","darnassus","erion schattenflüsterer","erion's behest","jannok windsang","schurkenvorquest","syurna"},ang={["class:Rogue"]="Als Schurke lasst Ihr die Anfängeraufgaben auf Teldrassil hinter Euch und meldet Euch bei Erion Schattenflüsterer. Er hat Aufgaben jenseits der ersten Wälder, die Fingerspitzengefühl verlangen.",["faction:Alliance"]="Als Agent der Allianz im nördlichen Kalimdor stimmt Ihr Euch mit den Einsatzleitern in Darnassus ab, bevor Ihr Euch in umkämpftes Gebiet wagt.",["race:NightElf"]="Als nachtelfischer Schattenpirscher meldet Ihr Euch bei Erion in Darnassus. Eure Pflichten reichen nun über örtliche Schutzaufgaben hinaus und erstrecken sich über den ganzen Kontinent."},sec={{t="Ein Ruf zur Enklave",b="Jannok Windsang schickt Euch von Teldrassil nach Darnassus, um Erion Schattenflüsterer aufzusuchen. Ihr müsst nicht fürchten, zur anspruchsvollen Ausbilderin Syurna gerufen zu werden. Erion wartet in der Enklave des Cenarius, wo er sich um Aufgaben kümmert, die ein leiseres Vorgehen verlangen."},{t="Den Horizont im Blick",b="Für Schurken in den Landen der Nachtelfen reichen die Pflichten inzwischen über Teldrassils Wälder hinaus. Erion Schattenflüsterer schickt fähige Kräfte in eine größere, gefährlichere Welt. Ihre Aufgaben liegen jenseits des Meeres."}},faq={{q="Wer schickt Euch zu Erion Schattenflüsterer?",a="Jannok Windsang schickt Euch von Teldrassil nach Darnassus, um mit Erion Schattenflüsterer in der Enklave des Cenarius zu sprechen.",al={"questgeber","wer startet erion schattenflüsterer","jannok windsang quest"}},{q="Wo befindet sich Erion Schattenflüsterer?",a="Erion Schattenflüsterer befindet sich in der Enklave des Cenarius in Darnassus, zwischen den Bäumen auf den oberen Ebenen der Enklave.",al={"erion standort","wo ist erion","wo ist erion schattenflüsterer zu finden"}},{q="Warum erwähnt Jannok Syurna?",a="Syurna ist eine bedeutende Schurkenausbilderin in Darnassus, bekannt für ihren strengen und anspruchsvollen Unterricht. Jannok beruhigt Euch mit einer scherzhaften Bemerkung: Ihr steckt weder in Schwierigkeiten, noch werdet Ihr zur Ausbildung zu ihr geschickt.",al={"wer ist syurna","warum nicht syurna","jannoks bemerkung über syurna"}},{q="Was geschieht, nachdem Ihr Euch bei Erion gemeldet habt?",a="Nach Eurem Bericht gibt Erion Euch Eure nächste Aufgabe, Erion's Behest. Er schickt Euch über Teldrassil hinaus, damit Ihr Euren Wirkungskreis in Kalimdor erweitert.",al={"was kommt als nächstes","erion folgequest","quest nach erion schattenflüsterer"}},{q="Welche Aufgaben beaufsichtigt Erion?",a="Erion leitet neue Schurken in Darnassus an und verbindet örtliche Agenten mit überregionalen Einsätzen der Allianz.",al={"ist erion ein schurkenausbilder","erion schattenflüsterer rolle","was macht erion"}},{q="Warum ist ein Einsatzleiter für Schurken in der Enklave des Cenarius stationiert?",a="Die Enklave des Cenarius ist für Druiden und Naturverehrung bekannt. Ihre Bäume bieten verstohl慕enen Agenten abgeschiedene Orte, um sich fern vom Tempel des Mondes zu treffen und ihren Geschäften nachzugehen.",al={"enklave des cenarius schurke","warum druidengebiet für schurken"}}},fx={["8fe8a3c2"]={q="Warum schickt Euch Jannok Windsang zu Erion?",a="Jannok Windsang überträgt Euch keine eigene Aufgabe, sondern fungiert als Bote. Erion Shadewhisper hat ausdrücklich um Eure Anwesenheit in der Enklave des Cenarius gebeten, um Eure Fähigkeiten zu testen und Euch mit fortschreitender Ausbildung über Teldrassil hinaus zu entsenden.",al={"warum schickt jannok mich","jannok windsang motiv","warum zu erion shadewhisper"}}},fp="18,159,24.243.0,19.194.0,41.114.0,36.105.0,31.197.0,38.131.0,37.95.0,57.175.0"}
P.entries["quest:226"] = {n="Wölfe sind uns auf den Fersen",s="Im westlichen Dämmerwald steht Lars hungrigen, tollwütigen Schreckenswölfen gegenüber. Die Jagd auf sie verschafft ihm Freiraum zur Nahrungssuche, während er und Sven Yorgen ihre Blutrache gegen den Nekromanten Morbent Fel verfolgen.",h="Im westlichen Dämmerwald steht Lars hungrigen, tollwütigen Schreckenswölfen gegenüber.",kw={"schreckenswolf","dämmerwald","flash bundles","lars","morbent fel","tollwütiger schreckenswolf","verhungernder schreckenswolf","sven","sven's camp"},ang={["class:Hunter"]="Als Jäger braucht Ihr wache Sinne, um die entstellten Wildtiere des Dämmerwalds zu zähmen oder ihre Zahl zu verringern. Diese Schreckenswölfe sind verzweifelter und bösartiger als gewöhnliche Waldtiere.",["faction:Alliance"]="Als Reisender der Allianz helft Ihr, Lars' abgelegenes Lager zu festigen und einen verbündeten Stützpunkt gegen die untoten Streitkräfte zu sichern, die den westlichen Dämmerwald heimsuchen."},sec={{t="Ein gefährdetes Lager",b="Sven Yorgen und Lars unterhalten ein abgelegenes Lager in den westlichen Hügeln des Dämmerwalds, nahe der Grenze zu Westfall. Fern von Dunkelhain sind sie zum Überleben auf Jagd und Nahrungssuche angewiesen. Während Lars frisches Wild durch die dunklen Wälder trägt, streifen ausgehungerte Raubtiere an den Flussufern und im Unterholz umher."},{t="Die Wälder sichern",b="Verhungernde, tollwütige Schreckenswölfe streifen nördlich und östlich des Lagers in Richtung des Flusses umher. Die rasenden Bestien zu töten macht Lars' Jagd sicherer. Wenn die tägliche Nahrungssuche weniger gefährlich ist, können Sven und Lars sich auf Morbent Fel konzentrieren, den Nekromanten weiter östlich."}},faq={{q="Wer ist Lars?",a="Lars hilft Sven Yorgen in ihrem kleinen Lager in den Hügeln des westlichen Dämmerwalds. Er jagt und sammelt Nahrung für ihren täglichen Bedarf, während Sven nur an Rache an den dunklen Mächten denkt, die die Region bedrohen.",al={"lars","wer vergibt wölfe sind uns auf den fersen","questgeber lars"}},{q="Wo streifen die Wölfe umher?",a="Schreckenswölfe durchstreifen die Wälder nördlich und östlich von Sven's Camp, besonders entlang der Flussufer, die den Dämmerwald von den Gebieten im Norden trennen.",al={"fundort der wölfe","wo sind tollwütige schreckenswölfe","wo sind verhungernde schreckenswölfe"}},{q="Warum sind die Schreckenswölfe so aggressiv?",a="Die Wildnis des Dämmerwalds ist unter einem vordringenden Schatten rauer geworden. Da Wild knapp ist, stehen die Schreckenswölfe kurz vor dem Verhungern. Krankheit oder dunkle Verderbnis hat viele tollwütig gemacht, sodass sie sich blindlings auf jeden stürzen, der frisches Fleisch trägt.",al={"warum greifen wölfe an","tollwütige wölfe dämmerwald"}},{q="Wer ist Morbent Fel?",a="Morbent Fel ist ein mächtiger Nekromant, der auf dem Friedhof und den Grabhügeln im Osten dunkle Künste ausübt. Sven und Lars hegen einen bitteren Groll gegen ihn und bereiten sich darauf vor, ihn zu stürzen, sobald ihre Grundbedürfnisse gedeckt sind.",al={"morbent fel","der nekromant","wer ist der nekromant im osten"}},{q="Was sind die Flash Bundles, die Lars als Belohnung gibt?",a="Flash Bundles sind von den Bewohnern Dunkelhains gefertigte Blendvorrichtungen. Mitfühlende Einwohner spendeten sie für Svens Lager, um seinen Kampf gegen die Untoten und Bestien zu unterstützen, die die Wälder heimsuchen.",al={"flash bundles","lars belohnung","was ist flash bundle"}},{q="Warum leben Sven und Lars nicht in Dunkelhain?",a="Svens Familie erlitt eine Tragödie, die ihn zu einem verbitterten, rastlosen Rächer machte. Sven und Lars leben in der Wildnis statt unter dem Schutz der Nachtwache in Dunkelhain, um die Übel der Wälder selbst aufzuspüren.",al={"warum in einem lager leben","sven's camp standort","warum nicht in der stadt"}}},fx={e2641657={q="Warum will Lars, dass die Schattenwölfe getötet werden?",a="Sven und Lars leben isoliert im westlichen Dämmerwald und müssen ihr eigenes Wild jagen, um zu überleben. Jedes Mal, wenn Lars versucht, Fleisch zurück ins Lager zu schaffen, überfallen ihn Rudel ausgehungerter Schattenwölfe. Das Beseitigen der Raubtiere sichert die Lebensmittelversorgung ihres Lagers und gibt ihnen die Freiheit, sich auf die drohende Bedrohung durch den Nekromanten Morbent Fel zu konzentrieren.",al={"warum wölfe töten","lars wölfe motiv","warum braucht lars wolfskills"}},["8ad2a450"]={q="Welche Schattenwölfe streifen durch den westlichen Dämmerwald?",a="Diese bösartigen Bestien streifen durch die Wälder und Flussufer nördlich und östlich von Sven's Camp. Angetrieben von extremer Hungersnot und sich ausbreitender Krankheit sind die hungernden und tollwütigen Schattenwölfe zu rücksichtslosen Aasfressern geworden, die sofort von frischem Fleisch angelockt werden und eine tödliche Gefahr für jeden darstellen, der die westliche Wildnis durchquert.",al={"was sind das für wölfe","hungernde schattenwölfe dämmerwald","tollwütige schattenwölfe"}},["6ca73ecd"]={q="Warum kann Lars sich nicht selbst um die Wölfe kümmern?",a="Lars und Sven sind am äußersten Rand des Gebiets auf sich allein gestellt, weit abseits der Reichweite der The Nachtwache oder der Wachen von Sturmwind. Da sie bereits damit beschäftigt sind, sich auf ihren Kampf gegen Morbent Fel vorzubereiten, und kaum die tägliche Jagd bewältigen können, kann es sich Lars einfach nicht leisten, ohne die Hilfe eines Abenteurers gegen ganze Rudel bösartiger Wölfe zu kämpfen.",al={"warum tötet lars die wölfe nicht","warum fragst du mich wegen der wölfe","warum nicht lars"}}},fp="19,185,17.272.0,18.254.0,12.199.0,30.140.0,38.228.0,19.203.0,50.188.0,42.229.0"}
P.entries["quest:2260"] = {n="Erions Befehl",s="In Darnassus schickt Erion Shadewhisper vielversprechende Nachtelfenschurken über das große Meer. Er erkennt ihre wachsende Kunst der Verstohlenheit und schickt sie nach Sturmwind, um sich beim Geheimdienst von Sturmwind zu melden.",h="In Darnassus schickt Erion Shadewhisper vielversprechende Nachtelfenschurken über das große Meer.",kw={"darnassus","erion shadewhisper","erions befehl","die altstadt","renzik das messer","schurke","si:7","sturmwind"},ang={["class:Rogue"]="Als Schurke lasst Ihr die örtlichen Scharmützel Kalimdors hinter Euch, um Euch unter dem SI:7 kontinentaler Spionage und einer Ausbildung in tödlichen Künsten zu widmen.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr beobachten, wie der SI:7 verdeckte Einsätze bündelt und talentierte Späher aus allen Mitgliedsvölkern dort einsetzt, wo die Krone sie braucht.",["race:NightElf"]="Als Nachtelf kann es Euch einen heftigen Kulturschock versetzen, Darnassus und Teldrassil zu verlassen, um in Sturmwinds steinernen Gassen dem Geheimdienst der Menschen zu dienen."},sec={{t="Ein Ruf übers Meer",b="Nachtelfenschurken üben im Schatten Teldrassils unter Mentoren wie Erion Shadewhisper. Zeigt einer außergewöhnliches Talent, spricht sich das bis jenseits des Weltbaums herum. Durch Erion lädt Euch der Geheimdienst von Sturmwind, auch SI:7 genannt, über das große Meer in die Hauptstadt der Menschen ein."},{t="Im Dienst des SI:7",b="Vom Norden Kalimdors reist Ihr über die Docks an der Dunkelküste oder im Sumpfland nach Sturmwind. In der Hauptstadt begebt Ihr Euch zum Hauptquartier des SI:7 in der Altstadt und meldet Euch bei Renzik \"Das Messer\". Er beurteilt Neuankömmlinge und eröffnet ihnen den Weg zu fortgeschrittener Spionage, der Meisterschaft im Umgang mit Giften und verdeckten Einsätzen für die Allianz."}},faq={{q="Wer schickt mich auf diese Mission?",a="Erion Shadewhisper, der Schurkenlehrer in Darnassus, schickt Euch, nachdem Eure ersten Taten die Aufmerksamkeit der Geheimdienstnetzwerke jenseits des Meeres erregt haben.",al={"questgeber","erion shadewhisper","wer gab mir das"}},{q="Warum kontaktiert der Geheimdienst von Sturmwind einen Nachtelfen?",a="Die Allianz verlässt sich neben den eigenen Traditionen der Nachtelfen in der Verstohlenheit auf den SI:7, um geheime Aufklärung und Sabotage zu koordinieren. Der Geheimdienst von Sturmwind sucht fähige Schurken aus allen Völkern der Allianz für seine Reihen.",al={"warum si:7","warum sturmwind","warum interessiert das die menschen"}},{q="Wo finde ich Renzik 'Das Messer'?",a="Renzik \"Das Messer\" befindet sich im Hauptquartier des SI:7 in der Altstadt von Sturmwind.",al={"renziks standort","wo ist das messer","renzik finden"}},{q="Ist diese Quest nur für Schurken?",a="Ja. Dieser Auftrag der Allianz führt Schurken von Kalimdor nach Sturmwind, dem Zentrum der Geheimdienstausbildung der Allianz.",al={"nur für schurken","können andere klassen das machen","ist das eine schurkenquest"}},{q="Was geschieht nach dem Treffen mit Renzik?",a="Wenn Ihr Euch bei Renzik meldet, werdet Ihr Teil der Ausbildungsarbeit des SI:7 in den Östlichen Königreichen. Spezialisierte Ausbildung und verdeckte Aufträge erwarten Euch überall in den Landen der Menschen.",al={"nächste quest","was bekomme ich","nach renzik"}},{q="Wie gelangt ein Nachtelf zu diesem Zeitpunkt nach Sturmwind?",a="Ihr könnt von Auberdine an der Dunkelküste direkt über das Meer zum Hafen von Sturmwind segeln.",al={"wie nach sturmwind gelangen","reise nach sturmwind","weg nach sturmwind"}}},fx={["4c3449b0"]={q="Warum schickt Euch Erion Shadewhisper nach Sturmwind?",a="Erion Shadewhisper handelt auf eine formelle Vorladung des Geheimdienstes von Sturmwind. Euer wachsender Ruf als Schurke hat menschliche Ohren jenseits Das große Meer erreicht und der SI:7 hat ausdrücklich nach Euch gefragt. Erion erkennt, dass die geheime Gilde in Die Altstadt spezialisierte Ausbildung und Ressourcen bietet, die weit über das hinausgehen, was die stillen Schatten von Teldrassil bieten, und drängt Euch, die Gelegenheit zu ergreifen, anstatt isoliert in Darnassus zu bleiben.",al={"warum nach sturmwind schicken","erion shadewhisper motiv","warum erions behest"}}},fp="14,198,24.270.0,28.321.0,29.144.0,53.208.0,34.75.0,30.117.0,34.165.0,57.85.0"}
P.entries["quest:2281"] = {n="Rendezvous im Rotkammgebirge",s="In Seenhain üben vielversprechende Schurken der Allianz unter erfahrenen Agenten für gefährliche Einsätze. Der SI:7 schickt sie vom Geheimdiensthauptquartier in Sturmwind nach Osten, um sie auf den Einsatz vorzubereiten.",h="In Seenhain üben vielversprechende Schurken der Allianz unter erfahrenen Agenten für gefährliche Einsätze.",kw={"seenhain","lucius","rendezvous im rotkammgebirge","renzik das messer","schurkenquest","si:7","sturmwind"},ang={["class:Rogue"]="Als Schurke beginnt Ihr hier mit der regulären Feldarbeit für den SI:7. Ihr wechselt von Diebstählen in Hintergassen zu planvoller Staatsspionage.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie Sturmwinds geheimer Arm bis in entlegene Siedlungen wie Seenhain reicht, wo unauffällige Agenten stationiert sind."},sec={{t="Ein Maßstab fürs Überleben",b="Renzik „das Messer“, stellvertretender Befehlshaber des SI:7 in Sturmwind, weiß, dass unausgebildete Schurken gefährliche Einsätze selten überleben. Unerfahrene Rekruten in feindliches Gebiet zu schicken, bringt Verluste statt Erkenntnisse. Deshalb schickt der SI:7 vielversprechende Agenten nach Osten ins Rotkammgebirge. Dort bildet Lucius sie an den Docks von Seenhain aus."},{t="Augen in Seenhain",b="Seenhain bietet Lucius ein gutes Gelände für die geheime Ausbildung. Gnolle und Schwarzfelsorcs bedrohen die Grenzstadt. An ihren Stegen kann er die Heimlichkeit, die Reflexe und das Schlösserknacken eines Schurken prüfen, ohne die Aufmerksamkeit der Stadtbewohner oder Wachen zu erregen."}},faq={{q="Wer vergibt die Quest Rendezvous im Rotkammgebirge?",a="Renzik „das Messer“, ein Goblin und Meisterspion in der Altstadt von Sturmwind, vergibt den Auftrag im SI:7-Hauptquartier an Schurken, die sich beim Geheimdienstkommando melden.",al={"wer startet rendezvous im rotkammgebirge","rendezvous im rotkammgebirge questgeber","wer vergibt die quest"}},{q="Wo befindet sich Lucius?",a="Lucius wartet an den hölzernen Docks von Seenhain im Rotkammgebirge, zwischen örtlichen Müßiggängern und Fischern am Wasser.",al={"wo ist lucius","lucius standort","lucius finden"}},{q="Warum schickt der SI:7 Schurken ins Rotkammgebirge?",a="Renzik hält unerfahrene Schurken für ungeeignet für gefährliche Geheimdienstarbeit. In Seenhain gibt Lucius ihnen den letzten Schliff und prüft Fähigkeiten wie Taschendiebstahl und Schlösserknacken unter den Bedingungen des Grenzlands.",al={"warum seenhain","zweck von rendezvous im rotkammgebirge","warum rotkammgebirge"}},{q="Was folgt nach dem Abschluss von Rendezvous im Rotkammgebirge?",a="Wer sich bei Lucius meldet, erhält Ausbildungsübungen bei Althers Mühle, wo der Agent Heimlichkeit und Fingerfertigkeit erprobt.",al={"nächste quest","rendezvous im rotkammgebirge folgequest","nach rendezvous im rotkammgebirge"}},{q="Ist diese Quest auch für andere Klassen als Schurken verfügbar?",a="Nein. Rendezvous im Rotkammgebirge ist für Schurken der Allianz bestimmt und gehört zu ihrer Feldausbildung beim SI:7.",al={"können krieger rendezvous im rotkammgebirge machen","ist das nur für schurken","klassenanforderung"}},{q="Warum arbeitet Renzik für den Geheimdienst von Sturmwind?",a="Obwohl er ein Goblin ist, ist Renzik „das Messer“ ein vertrauter Stellvertreter von Meisterspion Mathias Shaw. Vom Stützpunkt des SI:7 aus beaufsichtigt er die Aufnahme und Ausbildung von Agenten.",al={"warum ist ein goblin beim si7","renzik hintergrundgeschichte","goblin in sturmwind"}}},fx={da1ebf68={q="Warum braucht Renzik mich für diesen Auftrag?",a="Der SI:7 braucht frische Agenten, die in der Lage sind, gefährliche verdeckte Arbeit zu leisten, aber Renzik weiß, dass es im Grunde ein Todesurteil ist, einen ungeschliffenen Schurken direkt in aktive Feldeinsätze zu schicken. Anstatt vielversprechendes Talent zu verschwenden, entsendet er speziell Euch, damit Ihr Euer Handwerk unter Lucius schärfen könnt, bevor Ihr Missionen angeht, die Euer Leben kosten könnten.",al={"warum ich renzik","warum wählt man mich rotkammgebirge","warum zu lucius schicken"}}},fp="19,183,21.327.0,17.237.0,40.154.0,24.120.0,38.206.0,48.117.0,53.85.0,48.160.0"}
P.entries["quest:2282"] = {n="Althers Mühle",s="Lucius schickt Schurken der Allianz zu Althers Mühle, um ihr Können zu prüfen. Sie liegt nordöstlich entlang der Straße von Seenhain, wo sich nun Schwarzfelsorcs nähern.",h="Lucius schickt Schurken der Allianz zu Althers Mühle, um ihr Können zu prüfen.",kw={"althers mühle","schwarzfelsorcs","seenhain","schlösserknacken","lucius","rotkammgebirge","si:7","diebeswerkzeug","marke der diebeskunst"},ang={["class:Rogue"]="Als Schurke erhaltet Ihr Euer Werkzeug zum Schlösserknacken und Euren Befähigungsnachweis für den Einsatz, während Ihr nahe den Schwarzfelsorcs Eure Geduld und Heimlichkeit erprobt.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr bei der Ausbildung von Dieben und Spionen nahe Seenhain, während Ihr die Bewegungen der Schwarzfelsorcs beobachtet."},sec={{t="Anmut und Fingerspitzengefühl",b="Lucius schickt Euch mit Eurem ersten Diebeswerkzeug von Seenhain aus entlang der Straße nach Nordosten zu Althers Mühle. Dort stellt eine verschlossene Truhe Euer Können auf die Probe. Öffnet Lucius' persönliche Schatulle und bringt das Zeichen darin zurück, um Euer Zertifikat der Diebeskunst zu verdienen."},{t="Schatten zwischen den Sägen",b="Althers Mühle diente einst als Holzfällerposten. Nun dringen Schwarzfelsorcs ins Rotkammgebirge vor und sind nahe herangerückt, weshalb Lucius ihre Anwesenheit zum Teil der Prüfung macht. Der SI:7 erwartet von seinen Agenten, unbemerkt Schlösser zu knacken, während sie sich durch feindlich besetztes Gebiet bewegen."}},faq={{q="Welchem Zweck dient die Mission zu Althers Mühle?",a="Lucius prüft Eure Fähigkeiten im Schlösserknacken im Einsatz. Er gibt Euch Diebeswerkzeug und bittet Euch, als Beweis Eures Könnens ein Zeichen aus einer verschlossenen Truhe zu holen.",al={"warum zu althers mühle","zweck der quest","was bewirkt diese quest"}},{q="Wer ist Lucius?",a="Lucius bildet Schurken in Seenhain im Rotkammgebirge aus. Er unterweist Rekruten, die von Kontaktpersonen aus der gesamten Allianz geschickt werden, und prüft ihre Heimlichkeit und ihr Fingerspitzengefühl.",al={"wer ist lucius","lucius seenhain","wer vergibt diese quest"}},{q="Wo liegt Althers Mühle?",a="Althers Mühle liegt etwas abseits der Straße nordöstlich und östlich von Seenhain, an den Ausläufern vor den höheren Gebirgspässen.",al={"wo ist die mühle","althers mühle standort","wie althers mühle finden"}},{q="Warum sind Orcs bei Althers Mühle?",a="Orcs des Schwarzfelsklans sind von Steinwacht und den brennenden Höhen darüber herabgekommen. Sie überfallen menschliche Siedlungen und errichten vorgeschobene Stützpunkte im gesamten Rotkammgebirge, auch rings um die verlassene Mühle.",al={"warum sind hier orcs","schwarzfelsorcs rotkammgebirge","wer kontrolliert althers mühle"}},{q="Welche Belohnung gewährt Lucius nach Abschluss der Aufgabe?",a="Lucius verleiht Euch das Zertifikat der Diebeskunst. Es bescheinigt Euer Verständnis von Zuhaltungen und Dietrichen und Eure Bereitschaft, als geprüfter Schurke im Felde zu dienen.",al={"was ist die belohnung","zertifikat der diebeskunst","belohnung für questabschluss"}},{q="Wie fügt sich diese Quest in die Schurkenausbildung innerhalb der Allianz ein?",a="Kontaktpersonen wie Mathias Shaws SI:7-Führungsoffiziere in Sturmwind schicken Schurken aus allen Gebieten der Allianz zu Lucius nach Seenhain. Die Prüfung bei Althers Mühle ist die letzte praktische Bewährungsprobe ihrer Grundausbildung für den Einsatz.",al={"schurkenquestreihe","verbindung zum si7","folgequest von rendezvous im rotkammgebirge"}}},fx={bca91f0e={q="Warum schickt Euch Lucius zu Althers Mühle?",a="Lucius bildet angehende Schurken für die Allianz aus und möchte Eure praktische Finesse unter Druck testen. Indem er eine verschlossene Truhe direkt in der Nähe von Althers Mühle platziert – einem Gebiet, das von Schwarzfelsorks bedrängt wird –, zwingt er Euch, echtes Schlösserknacken in einer feindseligen Umgebung zu demonstrieren, anstatt in einem gemütlichen Klassenzimmer.",al={"lucius motiv","warum will lucius das erledigt haben","warum nach althers mühle schicken"}},["7e02fd2a"]={q="Wofür ist die Marke der Diebeskunst?",a="Die Marke der Diebeskunst ist ein Beweis Eurer Handwerkskunst. Sicher in Lucius' Truhe verschlossen, dient sie als physischer Beweis dafür, dass es Euch gelungen ist, in Althers Mühle einzudringen, das Schloss zu knacken und unentdeckt zu entkommen. Wenn Ihr sie zurückbringt, erhaltet Ihr Lucius' offizielles Zertifikat der Diebeskunst.",al={"nutzen marke der diebeskunst","was ist die marke der diebeskunst","zweck der marke der diebeskunst"}}},fp="13,151,27.269.0,23.241.0,52.148.0,14.159.0,31.126.0,40.198.0,55.153.0,64.218.0"}
P.entries["quest:2283"] = {n="Necklace Recovery",s="Dran Droffers in Orgrimmar sucht eine wertvolle Halskette vom Ausgrabungsort Uldaman. Sie könnte beschädigt sein, aber er möchte, dass Ihr sie zurückbringt.",h="Dran Droffers in Orgrimmar sucht eine wertvolle Halskette vom Ausgrabungsort Uldaman.",kw={"beschädigte halskette","ausgrabungsort","dran droffers","halskette","halskettenrückholung","orgrimmar","uldaman"},sec={{t="Eine Suche in Uldaman",b="Am Ausgrabungsort Uldaman sucht Ihr nach der Halskette, die Dran Droffers nach Orgrimmar zurückhaben möchte. Ihr Wert ist ihm wichtig, auch wenn sie beschädigt sein könnte, wenn Ihr sie findet."}},faq={{q="Wer möchte die Halskette?",a="Dran Droffers in Orgrimmar möchte, dass Ihr ihm die Halskette zurückbringt.",al={"wer hat danach gefragt","halskette für wen"}},{q="Wo sollte ich nach der Halskette suchen?",a="Die Halskette wird auf dem Ausgrabungsort Uldaman gesucht.",al={"fundort der halskette","wo halskette"}},{q="Muss die Halskette unbeschädigt sein?",a="Die Halskette könnte beschädigt sein.",al={"beschädigte halskette in ordnung","zustand der halskette"}},{q="Warum will Dran sie?",a="Im Text wird sie als wertvoll bezeichnet, aber es wird kein weiterer Grund genannt.",al={"warum wird die halskette gesucht","wofür ist die halskette"}},{q="Wo ist Dran Droffers?",a="Dran Droffers ist in Orgrimmar.",al={"drans aufenthaltsort","wo ist dran"}}},fp="17,128,19.167.0,23.66.0,37.51.0,39.28.0,22.68.0,23.30.0"}
P.entries["quest:23"] = {n="Ursangus' Tatze",s="Die Jagd im Eschental hat Euch Ursangus' Tatze eingebracht. Bringt sie zu Senani Donnerherz am Splitterholzposten und erringt Ehre unter den Fährtenlesern der Horde.",h="Die Jagd im Eschental hat Euch Ursangus' Tatze eingebracht.",kw={"eschental","jagd im eschental","bär","sichelemblem","tatze","senani donnerherz","splitterholzposten","ursangous"},ang={["class:Hunter"]="Als Jäger stellt Ihr beim Aufspüren und Besiegen eines der ältesten und tödlichsten Raubtiere des Eschentals Eure Fertigkeiten in der Wildnis, Eure Überlebenskunst und Euer Kampfgeschick auf die Probe.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr am Splitterholzposten Ehre erringen, indem Ihr den gefährlichen Ursangous besiegt.",["race:Tauren"]="Als Taurenjäger ehrt Ihr die Bestie, indem Ihr Ursangous die Tatze abnehmt. Sie zeigt Eure Entschlossenheit im Kampf und Eure Achtung vor den Geistern der Jagd."},sec={{t="Eine Trophäe der großen Jagd",b="Fährtenleser vom Splitterholzposten jagen die uralten Bestien, die das Blätterdach des Eschentals beherrschen. Ursangous zählt zu den wildesten. Er tötet Reisende und Krieger, die seinen Weg kreuzen, daher beweist seine Tatze, dass die mächtige Bestie Eurer Jagd zum Opfer gefallen ist."},{t="Die Verbindung zu den Nachtelfen",b="Auf Ursangus' Tatze ist ein viertelsichelförmiges Zeichen zu sehen, eingeritzt oder hineingedrückt. Senani Donnerherz erkennt darin den Einfluss der Kaldorei. Nachtelfen richten mächtige Waldbestien ab und gehen Bindungen mit ihnen ein, um ihre heiligen Grenzen zu bewachen. Ursangous könnte diese Grenzen bewacht oder der Allianz als Waffe gedient haben."}},faq={{q="Was ist Ursangous?",a="Ursangous ist ein außergewöhnlich gewaltiger und tödlicher Bär, der das Eschental durchstreift. Jäger und Wanderer fürchten ihn. Er forderte zahllose Leben, bevor die Horde ihn auf ihrer Jagd zur Strecke brachte.",al={"wer ist ursangous","ursangous bär","ursangous hintergrundgeschichte"}},{q="Was bedeutet das Sichelemblem auf der Tatze?",a="Das viertelsichelförmige Zeichen auf Ursangus' Tatze ist ein Rätsel, wenn Ihr die Trophäe untersucht. Senani Donnerherz kann es untersuchen, wenn Ihr ihr die Tatze bringt.",al={"sichelzeichen auf tatze","tatzenemblem","warum ist dort eine sichel"}},{q="Wem bringe ich Ursangus' Tatze?",a="Bringt Ursangus' Tatze zu Senani Donnerherz, der Taurenjägerin am Splitterholzposten im östlichen Eschental.",al={"wo tatze abgeben","wer will ursangus' tatze","senani donnerherz aufenthaltsort"}},{q="Wie fügt sich das in die Jagd im Eschental ein?",a="Ursangous ist neben Shadumbra und Sharptalon eine von drei großen Bestien, die im Eschental gejagt werden. Besiegt alle drei und legt ihre Trophäen vor, um den Ritus zu vollenden.",al={"jagd im eschental questreihe","was ist die jagd","jagdquestreihe"}},{q="Warum jagt die Horde die großen Bestien des Eschentals?",a="Jäger der Horde am Splitterholzposten, vor allem Tauren und Orcs, jagen diese tödlichen Bestien, um ihr Kampfgeschick zu erproben. Sie dämmen auch Gefahren nahe verwundbaren Versorgungslinien und Lagern ein.",al={"warum bären jagen","splitterholzposten jagd hintergrundgeschichte"}},{q="Was geschieht nach der Abgabe der Tatze?",a="Sobald Ihr Ursangous' Trophäe und die der anderen vorgesehenen Jagdbeuten gesammelt habt, wird Senani Donnerherz Euren Triumph in der abschließenden Prüfung The Hunt Completed anerkennen.",al={"nächste quest nach der tatze","was folgt auf ursangous"}}},fp="15,147,26.230.0,24.306.1,18.173.0,46.149.0,34.108.0,42.161.0,55.188.0,38.173.0"}
P.entries["quest:230"] = {n="Svens Lager",s="In den westlichen Hügeln des Dämmerwalds trauert Sven Yorgen noch immer um seine ermordete Familie und sucht Antworten. Ein Tagebuch, das auf seinem verwüsteten Hof vergraben liegt, könnte verraten, wer das Massaker mitangesehen hat.",h="In den westlichen Hügeln des Dämmerwalds trauert Sven Yorgen noch immer um seine ermordete Familie und sucht...",kw={"dunkle reiter","dämmerwald","haufen lockerer erde","shadowy figure","sven yorgen","hof der yorgens"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr helfen, das Massaker an den Yorgens zu untersuchen, während die Allianz die dunklen Mächte zu verstehen versucht, die in den Dämmerwald vordringen."},sec={{t="Ein Hinweis im Erdreich",b="Ihr findet ein kleines, schmutzbeflecktes Buch unter frisch aufgeworfener Erde auf dem verwüsteten Hof der Yorgens. Dunkle Reiter schlugen zu, während Sven Yorgen fort war, und hinterließen seine Familie tot und den Hof in Trümmern. Trauer und Rachedurst trieben seine Verbündeten dazu, die Trümmer zu durchsuchen. Jemand hatte das Buch dort hastig versteckt."},{t="Ein stummer Zeuge",b="In seinem Lager in den westlichen Hügeln erfährt Sven, was im Tagebuch steht. Seine Einträge zeigen, dass eine unbekannte Gestalt das Massaker an seiner Familie beobachtet hat. Die Entdeckung bringt ihm keinen Frieden. Sven sucht nun den Beobachter und verlangt Antworten."}},faq={{q="Was ist das für ein Buch aus dem Erdhaufen?",a="Das Buch ist ein kleines, unbetiteltes, schmutzbeflecktes Tagebuch, das auf dem Hof der Yorgens vergraben lag. Seine Einträge zeigen, dass ein unbekannter Beobachter das Massaker an Sven Yorgens Familie mitangesehen hat.",al={"was ist das für ein buch","buch von svens hof","was habe ich ausgegraben"}},{q="Wohin führt diese Quest als Nächstes?",a="Wenn Ihr Sven Yorgen das Buch bringt, beginnt die Suche nach dem geheimnisvollen Zeugen und führt zu Shadowy Figure.",al={"what comes next","nächste quest nach svens lager","wer ist shadowy figure"}},{q="Wo befindet sich Sven Yorgen?",a="Sven hat in einem Lager in den nordwestlichen Hügeln des Dämmerwalds Zuflucht gefunden. Er trauert um seine Familie und plant Vergeltung.",al={"wo ist sven","sven yorgen aufenthaltsort","wo wird das abgegeben"}},{q="Warum war das Buch auf dem Hof vergraben?",a="Das Buch lag in lockerer Erde inmitten der verwüsteten Heimstätte verborgen. Der Beobachter vor Ort könnte es in aller Eile weggeworfen oder versteckt haben.",al={"warum vergraben","wer hat das buch versteckt","haufen lockerer erde"}},{q="Wer hat Svens Familie getötet?",a="Dunkle Reiter vom Gebirgspass der Totenwinde schlachteten Svens Familie ab, während er nicht auf dem Hof war.",al={"wer hat den hof angegriffen","wer hat svens familie getötet","mörder von svens familie"}},{q="Welche Fraktion kann diese Quest abschließen?",a="Nur Mitglieder der Allianz können Sven Yorgen helfen, der bei den Verteidigern des Dämmerwalds und der Allianz Hilfe sucht.",al={"ist das nur für die allianz","kann die horde svens lager abschließen"}}},fp="11,161,18.288.0,16.220.1,44.171.0,32.112.0,29.114.0,36.131.0,25.89.0,37.101.0"}
P.entries["quest:2300"] = {n="Der SI:7",s="Aus Goldhain werden vielversprechende junge Schurken zu Renzik \"Das Messer\" nach Sturmwind geschickt. Dort tretet Ihr in den Dienst von Meister Mathias Shaw, wo verdeckte Einsätze auf Euch warten.",h="Aus Goldhain werden vielversprechende junge Schurken zu Renzik \"Das Messer\" nach Sturmwind geschickt.",kw={"keryn sylvius","mathias shaw","die altstadt","renzik das messer","schurke","späherkuppe","si:7","sturmwind"},ang={["class:Rogue"]="Als Schurke führt Euch dieser Ruf von örtlichen Aufgaben in den Dienst als Agent für Sturmwinds offiziellen Geheimdienst.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr Euch für gefährliche Spionage außerhalb der Reichweite regulärer Marschälle und Infanteristen an den SI:7 wenden."},sec={{t="Ein Ruf in die Altstadt",b="Im Gasthaus \"Zur Höhle des Löwen\" behält Keryn Sylvius die Rekruten aus Goldhain im Auge. Ihr beweist Schläue und Geschick gegen die wachsende Bedrohung durch die Defias, und Sylvius übermittelt eine Nachricht aus dem Hauptquartier. Meldet Euch unverzüglich bei Renzik \"Das Messer\". Ihr verlasst die Felder von Elwynn und reiht Euch in Sturmwinds verdeckte Truppen ein."},{t="Sturmwinds verborgene Augen",b="Hinter einer unscheinbaren Kaserne in der Altstadt unterhält Sturmwinds geheimer Dienst sein Hauptquartier. Meister Mathias Shaw leitet seine Arbeit im gesamten Königreich und darüber hinaus. Der Dienst übernimmt verdeckte Operationen, Aufklärung und Attentate.\n\nRenzik \"Das Messer\" ist Shaws scharfzüngiger Stellvertreter. Er beurteilt vielversprechende Agenten und schickt sie dann auf gefährliche Einsätze außerhalb der Reichweite des regulären Militärs des Königreichs."}},faq={{q="Wer schickt mich zum SI:7?",a="Keryn Sylvius, der Schurkenlehrer im Gasthaus \"Zur Höhle des Löwen\" in Goldhain, schickt Euch zum SI:7. Nachdem Ihr Euer Können im Einsatz bewiesen habt, erteilt Sylvius Euch den Befehl, Euch im Hauptquartier in Sturmwind zu melden.",al={"wer vergibt die quest","questgeber","keryn sylvius"}},{q="Wer ist Renzik \"Das Messer\"?",a="Renzik \"Das Messer\" ist ein Goblinagent und der Stellvertreter von Meister Mathias Shaw beim SI:7. Vom Hauptquartier in der Altstadt aus beurteilt er Außendienstagenten und koordiniert verdeckte Geheimdienstaufträge.",al={"renzik das messer","wer ist renzik","renzik"}},{q="Was ist der SI:7?",a="Der SI:7, auch Sturmwind Intelligence genannt, übernimmt verdeckte Spionage, Aufklärung und Attentate für das Königreich Sturmwind. Unter der Leitung von Mathias Shaw sammeln seine Agenten Informationen über Bedrohungen, gegen die die Wachen und Soldaten des Königreichs nichts ausrichten können.",al={"was ist si7","was macht si7","stormwind intelligence"}},{q="Wo liegt das Hauptquartier des SI:7?",a="Das Hauptquartier des SI:7 liegt im Osten der Altstadt von Sturmwind. Der Dienst arbeitet von einer befestigten Gildenhalle und einer Ausbildungskaserne abseits der Hauptstraßen aus.",al={"wo ist si7","si7 standort","wo ist renzik"}},{q="Was geschieht, nachdem ich mich bei Renzik gemeldet habe?",a="Nachdem Ihr Euch bei Renzik gemeldet habt, prüft er Eure Einsatzbereitschaft. Dann schickt er Euch jenseits der Stadtmauern zu einem Agenten, der im Rotkammgebirge stationiert ist.",al={"nächste quest","was kommt danach","redridge rendezvous"}},{q="Warum nennt Keryn Sylvius mich „Fisch“?",a="„Fisch“ ist ein umgangssprachlicher Ausdruck für einen unerprobten Anfänger oder neuen Rekruten. Die Agenten des Dienstes verwenden bildhafte, schroffe Spitznamen, damit Neulinge auf dem Boden bleiben, bis sie sich bei echten Aufträgen bewähren.",al={"warum fisch genannt","fisch bedeutung"}}},fx={d2c94cb8={q="Warum schickt mich Keryn Sylvius zum SI:7?",a="Keryn Sylvius handelt auf Befehle von ganz oben. Renzik \"Das Messer\" hat ausdrücklich Nachricht geschickt, dass er nach Euch sucht, und Keryn weiß, dass es besser ist, eine Vorladung von Mathias Shaws Stellvertreter nicht zu ignorieren. In der verdeckten Hierarchie des Geheimdienstes von Sturmwind geben Vermittler wie Keryn den Befehl sofort weiter, wenn Renzik nach einem Agenten verlangt, ohne das Hauptquartier warten zu lassen.",al={"warum schickt keryn mich","keryn sylvius motiv","warum an si7 melden"}},fe886311={q="Warum braucht der SI:7 mich anstelle ihrer eigenen Agenten?",a="Renzik \"Das Messer\" hat ausdrücklich namentlich nach Euch gefragt. Als aufstrebender Schurke, der innerhalb des Netzwerks der Allianz arbeitet, stellt Ihr frisches Talent dar, das außerhalb des unmittelbaren Blickfelds lokaler Gegner agiert. Meister Shaw und Renzik verlassen sich häufig auf fähige, neu bewährte Feldagenten, um diskrete Aufträge im ganzen Königreich zu übernehmen, bei denen erfahrene, bekannte Gesichter unerwünschte Aufmerksamkeit erregen könnten.",al={"warum ich si7","warum will renzik mich","warum nach mir rufen"}}},fp="4,166,21.292.0,23.413.0,31.202.0,25.204.0,13.239.0,39.159.0,39.136.1,38.183.0"}
P.entries["quest:231"] = {n="A Daughter's Love",s="Sarah Ladimore bittet Euch, ihren Ring zu Morgan Ladimores Grab zu bringen. Die Begegnung dort wirkt sich auf Morgans ruhelose Seele aus.",h="Sarah Ladimore bittet Euch, ihren Ring zu Morgan Ladimores Grab zu bringen.",kw={"a daughter's love","archeus","grab","lys","morgan ladimore","ring","sarah ladimore"},ang={["class:Paladin"]="Morgan sagt, Archeus sei geschmiedet worden, um Gutes zu tun, und bittet Euch, mit ihm das Licht weiterzutragen."},sec={{t="Am Grab",b="Eine Stimme im Wind antwortet, als Ihr Sarah Ladimores Ring zu Morgan Ladimores Grab bringt. Morgan fragt sich, ob Sarah noch lebt, und sagt, der Ring nehme ihm eine Last von den Schultern. Er vertraut Euch sein Schwert Archeus an und bittet Euch, den Ring zu behalten, während er zu Lys, seiner Liebsten, spricht."}},faq={{q="Was geschieht, wenn ich Sarahs Ring zu Morgans Grab bringe?",a="Eine Stimme im Wind antwortet. Morgan fragt sich, ob Sarah noch lebt, und sagt, der Ring nehme ihm eine Last von den Schultern.",al={"sarah ring grab","morgan ladimore ring","a daughter's love ende"}},{q="Wessen Stimme ist am Grab zu hören?",a="Morgan Ladimore spricht als geisterhafte Stimme im Wind.",al={"geisterstimme","wer spricht am grab","morgan geist"}},{q="Was gibt Morgan mir?",a="Morgan gibt Euch sein Schwert Archeus.",al={"morgan schwert","archeus schwert","archeus nehmen"}},{q="Was soll ich auf Morgans Bitte hin behalten?",a="Morgan bittet Euch, Sarahs Ring zu behalten.",al={"ring behalten","morgans ring","ring am grab"}},{q="Wer ist Lys?",a="Morgan nennt Lys seine Liebste.",al={"lys morgan","morgans liebste","lys ladimore"}}},fp="17,124,12.293.1,60.121.0,30.54.0,25.36.0,32.39.0,11.26.0"}
P.entries["quest:233"] = {n="Postbeförderung im Eisklammtal",s="In Ambossar schickt Sten Starkarm Euch mit Post für die Späher jenseits des gefrorenen Sees nach Westen. Schnee und Troggs in der Nähe können die Verteidiger des Tals abschneiden, sodass wichtige Nachrichten nicht zugestellt werden.",h="In Ambossar schickt Sten Starkarm Euch mit Post für die Späher jenseits des gefrorenen Sees nach Westen.",kw={"ambossar","das coldridgetal","dun morogh","grelin weißbart","postbeförderung","sten starkarm","talin keeneye"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, die Außenposten des Coldridgetals miteinander in Verbindung zu halten, was für die Koordinierung der Verteidigung Dun Moroghs wichtig ist.",["race:Dwarf"]="Als Zwerg helft Ihr durch die Überbringung von Nachrichten zwischen den Außenposten, Eisenschmiedes weit verstreute Späher im Tal mit ihren Clans in Verbindung zu halten.",["race:Gnome"]="Als Gnom, der nach Gnomeregans Fall unter Verbündeten in Dun Morogh lebt, helft Ihr durch die Überbringung von Nachrichten, Vertrauen bei den örtlichen zwergischen Verteidigern aufzubauen."},sec={{t="Ein Kurier im Schnee",b="Post aus ganz Dun Morogh erreicht Ambossar über den Gebirgspass, wo Winterkuriere sie ablegen und sich ansammeln lassen. Sten Starkarm kümmert sich um Versorgung und Sicherheit, also tragen Rekruten die Bündel die westliche Straße hinab. Ohne Eure Hilfe bleiben wichtige Nachrichten in der Halle liegen."},{t="Außenposten an der Grenze",b="Talin Keeneye hält am gefrorenen See westlich von Ambossar nach Troggbewegungen und gefährlichen Wildtieren Ausschau. Selbst an einem kalten Außenposten sind Nachrichten aus Eisenschmiede und den umliegenden Lagern wichtig. Die rauen Bedingungen im Gebirge erschweren das Sortieren der Post, sodass Briefe für verschiedene Späher zusammen in einem Bündel landen können."}},faq={{q="Wer beginnt die Postbeförderung?",a="Sten Starkarm gibt Euch den Zustellauftrag vor Ambossar. Gerade sind Briefe über den Gebirgspass eingetroffen, doch seine Pflichten hindern ihn daran, sie selbst zu überbringen.",al={"questgeber","wer vergibt postbeförderung im eisklammtal","sten starkarm quest"}},{q="Wo befindet sich Talin Keeneye?",a="Talin Keeneye lagert westlich von Ambossar, neben der Straße beim gefrorenen See im Coldridgetal.",al={"wo ist talin keeneye","talin keeneye standort","talin keeneye finden"}},{q="Sind wirklich alle Briefe im Stapel für Talin?",a="Nein. Talin findet einen Brief für Grelin Weißbart, der ganz in der Nähe im Tal stationiert ist.",al={"ist die ganze post für talin","grelin weißbart brief","fehlgeleitete post"}},{q="Warum braucht Sten einen Abenteurer, um die Post auszutragen?",a="Troggangriffe und örtliche Bedrohungen halten Sten und die anderen zwergischen Verteidiger mit Versorgung und Sicherheit auf Trab. Reisende und Rekruten können Briefe zu den abgelegenen Posten bringen.",al={"warum post austragen","warum stellt sten die post nicht selbst zu","postbeförderungsauftrag"}},{q="Führt diese Quest zu weiteren Aufgaben?",a="Ja. Nach der Zustellung bittet Talin Euch, den fehlgeleiteten Brief zu Grelin Weißbart zu bringen und damit die Postbeförderung fortzusetzen.",al={"nächste quest","postquestreihe","folgequest der postbeförderung"}},{q="Woher kamen die Briefe ursprünglich?",a="Die Briefe kamen aus den übrigen Gebieten von Dun Morogh und aus Eisenschmiede durch den Pass ins Coldridgetal.",al={"woher kam die post","herkunft der briefe"}}},fx={bf556c8e={q="Warum will Sten Starkarm, dass die Briefe zugestellt werden?",a="Ein frisches Bündel Korrespondenz ist gerade über den Gebirgspass eingetroffen, aber Sten ist in Ambossar an seine eigenen Pflichten gebunden und kann nicht weggehen, um sie selbst auszutragen. Anstatt wichtige Nachrichten und Depeschen verstauben zu lassen, während Gebirgsjäger draußen im Feld auf Nachricht warten, verlässt er sich darauf, dass ein hilfreicher Reisender sie sicher die Straße hinunterbringt.",al={"warum briefe zustellen","sten starkarm motiv","warum post schicken"}}},fp="30,181,21.258.0,17.299.0,29.159.0,31.99.0,52.86.1,49.173.0,36.124.1,43.108.0"}
P.entries["quest:234"] = {n="Postbeförderung im Eisklammtal",s="Im Coldridgetal reist eine Depesche von Talin Keeneyes Posten zu Grelin Weißbarts Lager. Ihr tragt sie die südöstliche Straße hinab und haltet so die Gebirgsjäger mit Eisenschmiede in Verbindung.",h="Im Coldridgetal reist eine Depesche von Talin Keeneyes Posten zu Grelin Weißbarts Lager.",kw={"das coldridgetal","kurier","dun morogh","grelin weißbart","eisenschmiede","postzustellung","talin keeneye"},ang={["faction:Alliance"]="Als Mitglied der Allianz seid Ihr auf Kurierwege durch verschneite Pässe angewiesen, über die Befehle und wichtige Informationen zu abgelegenen Kundschaftern gelangen.",["race:Dwarf"]="Als Zwerg seid Ihr auf Depeschen vom Sitz König Magnis in Eisenschmiede angewiesen, um die Verteidigung Dun Moroghs abzustimmen."},sec={{t="Verbindung zum Berg",b="Ambossar ist das Herrschaftszentrum des Coldridgetals. Von dort tragen Kundschafter und Wachposten Depeschen über die Pfade zwischen den Hochpässen und Eisenschmiede."},{t="Nachricht für Weißbart",b="Grelin Weißbart unterhält ein kleines Lager südöstlich von Talin Keeneyes Posten. Erfahrene Gebirgsjäger an diesen abgelegenen Wachposten trotzen eisigen Schneewehen und ständigen Angriffen der Troggs. Regelmäßige Briefe halten sie über die Geschehnisse in ganz Dun Morogh und im übrigen Königreich auf dem Laufenden."}},faq={{q="Wer ist Grelin Weißbart?",a="Grelin Weißbart ist ein zwergischer Veteran an einem Außenposten entlang der südöstlichen Straße des Coldridgetals. Er überwacht die Straßen und schützt sie vor Troggs und wilden Tieren.",al={"grelin","grelin weißbart infos","wer ist grelin"}},{q="Woher stammt dieser Brief?",a="Der Brief kam aus Eisenschmiede, der Hauptstadt der Zwerge. Örtliche Boten und Wachposten trugen ihn durch das Coldridgetal und die Gebirgspässe hinab zu seinem Empfänger.",al={"woher kommt der brief","brief aus eisenschmiede","absender des briefes"}},{q="Warum wird die Post hier zu Fuß zugestellt?",a="Fußkuriere tragen die Post durch das Coldridgetal, weil die umliegenden Gipfel es von den Hauptstraßen Dun Moroghs abschneiden. Vertrauenswürdige Reisende und Gebirgsjäger bringen Depeschen persönlich zu den Feldlagern.",al={"warum fußkuriere","warum post zu fuß","keine briefkästen im coldridgetal"}},{q="Wo liegt Grelin Weißbarts Lager?",a="Grelin Weißbarts Lager liegt weiter unten an der südöstlichen Straße durch das Coldridgetal, hinter den Jagd- und Erkundungsgebieten des oberen Passes.",al={"wo ist grelins lager","grelin weißbart standort","grelin finden"}},{q="Wer hat den Brief zur Zustellung an Grelin übergeben?",a="Talin Keeneye, ein am Pass stationierter Jäger und Kundschafter, hat Euch den Brief übergeben. Er kam von den Sammelplätzen nahe Ambossar.",al={"wer gab den brief","talin keeneyes rolle","wer startet die quest"}},{q="Was geschieht, nachdem Grelin seine Post erhält?",a="Nachdem Grelin Neuigkeiten aus Eisenschmiede erhalten hat, wendet er sich den Gefahren im Tal zu. Oft schickt er Rekruten gegen Frostmane-Trolle und Troggs aus.",al={"was folgt nach der post","grelins nächste quest","nach der postzustellung"}}},fx={c573251b={q="Warum will Talin Keeneye, dass dies erledigt wird?",a="Talin Keeneye ist draußen in der Kälte entlang der Straße stationiert und weiß, dass Grelin Weißbart ohne Nachrichten in seinem Lager gewartet hat. Nachdem er die Depesche aus Ambossar entgegengenommen hat, möchte Talin sicherstellen, dass sein Zwergenkamerad endlich seine Korrespondenz aus Eisenschmiede erhält, anstatt ihn gestrandet und uninformiert im Tal zurückzulassen.",al={"warum muss talin das zugestellt haben","talin keeneye motiv","warum brief an grelin schicken"}},d47c3713={q="Warum bittet Euch Talin Keeneye, den Brief zuzustellen, anstatt ihn selbst mitzunehmen?",a="Talin Keeneye ist auf der Wache entlang der Straße von Das Coldridgetal stationiert und behält die Pfade und die lokale Tierwelt im Auge. Wenn er seinen Posten verlassen würde, um den ganzen Weg hinunter zu Grelin Weißbarts Lager zu wandern, bliebe der Pass unbewacht, was einen vorbeireisenden Reisenden wie Euch zur natürlichen Wahl macht, um den Brief den Rest des Weges zu tragen.",al={"warum braucht talin mich","warum kann talin den brief nicht zustellen","warum ich talin"}}},fp="30,185,22.157.0,19.257.0,25.155.0,32.162.0,35.200.0,42.147.0,47.130.0,44.144.0"}
P.entries["quest:2342"] = {n="Reclaimed Treasures",s="Patrick Garrett bittet Euch, seinen Familienschatz aus Uldaman zu bergen. Er wartet in Unterstadt darauf.",h="Patrick Garrett bittet Euch, seinen Familienschatz aus Uldaman zu bergen.",kw={"familientruhe","familienschatz","patrick garrett","reclaimed treasures","south common hall","uldaman","unterstadt"},sec={{t="Eine Familientruhe",b="Die Familientruhe befindet sich in der South Common Hall von Uldaman. Patrick Garrett wartet in Unterstadt auf den Schatz, der darin verwahrt wird."}},faq={{q="Wer bittet um den Schatz?",a="Patrick Garrett bittet Euch, ihm seinen Familienschatz nach Unterstadt zu bringen.",al={"patrick garrett","wer will ihn"}},{q="Wo ist die Familientruhe?",a="Die Familientruhe befindet sich in der South Common Hall von Uldaman.",al={"standort der truhe","wo ist der schatz"}},{q="Wohin bringe ich den Schatz?",a="Bringt Patrick Garrett seinen Familienschatz nach Unterstadt.",al={"wohin bringen","schatz in unterstadt"}}},fp="19,108,14.120.0,31.75.0,26.56.0,30.64.0"}
P.entries["quest:235"] = {n="Die Jagd im Eschental",s="Kriegsrufer Gorlach schickt die Horde nach Norden ins Eschental, wo ihre Grenze in einen uralten Wald vordringt. Ihr sollt Euch bei Senani Donnerherz am Splitterholzposten melden und Euch der Jagd anschließen.",h="Kriegsrufer Gorlach schickt die Horde nach Norden ins Eschental, wo ihre Grenze in einen uralten Wald...",kw={"eschental","brachland","gorlach","jagd","orgrimmar","senani","splitterholz","donnerherz"},ang={["class:Hunter"]="Als Jäger findet Ihr unter dem dichten Blätterdach des Eschentals und unter seinen gefährlichen Bestien ein Bewährungsfeld, wenn Ihr Senani Donnerherz' Ruf folgt.",["faction:Horde"]="Als Mitglied der Horde dehnt Ihr ihren Einfluss über Durotar hinaus in rohstoffreiche, aber feindselige fremde Länder aus.",["race:Tauren"]="Als Tauren bringt Ihr unter Senani Donnerherz' Führung Eure tiefe Ehrfurcht vor der großen Jagd in den ungezähmten Wald."},sec={{t="Ruf der Wildnis",b="Orgrimmar braucht Holz, Fleisch und sichere Handelswege, um weiter zu wachsen. Kriegsrufer Gorlach überbringt Befehle des Oberkommandos der Horde und schickt erfahrene Wanderer und neue Abenteurer in laufende Feldzüge. Für jene, die in Durotar und im Brachland erwachsen werden, ist das Eschental die nächste Bewährungsprobe für Geschick und Überleben."},{t="Eine tückische Grenze",b="Nördlich des Brachlands hält die Horde zwei befestigte Stellungen im Eschental. Der Splitterholzposten liegt in den östlichen Wäldern, während der Außenposten von Zoram'gar an der Westküste steht. Senani Donnerherz koordiniert die Einsätze vom Splitterholzposten aus. Sie organisiert Fährtenleser und Jäger gegen die Bestien unter dem Blätterdach und die Nachtelfenschildwachen, die der Horde ihre Ansprüche streitig machen."}},faq={{q="Wer vergibt diese Quest und wo ist diese Person zu finden?",a="Kriegsrufer Gorlach erteilt den Befehl in Orgrimmar, der Hauptstadt der Horde. Er schickt fähige Abenteurer auf Feldzüge jenseits von Durotar.",al={"questgeber","wo ist gorlach","wer vergibt ashenvale hunt"}},{q="Wo liegt der Splitterholzposten?",a="Der Splitterholzposten liegt nördlich des Brachlands im östlichen Eschental, an der Hauptstraße durch den Wald nach Osten in Richtung Azshara.",al={"splitterholz standort","wo ist der splitterholzposten","weg zum splitterholzposten"}},{q="Wer ist Senani Donnerherz?",a="Senani Donnerherz ist eine erfahrene Taurenfährtenleserin am Splitterholzposten. Sie leitet die Jagd im gesamten Eschental und beurteilt Abenteurer, die sich den örtlichen Prüfungen stellen wollen.",al={"wer ist senani","senani donnerherz standort","questabgabe npc"}},{q="Welchem Zweck dient die Jagd im Eschental?",a="Die Jagd im Eschental sichert Wildbret und wertvolle Häute. Außerdem beseitigt sie die gefährlichsten Raubtiere, die Patrouillen nahe dem Splitterholzposten und die umliegenden Holzfällerbetriebe bedrohen.",al={"warum im eschental jagen","ashenvale hunt geschichte","ziel der horde im eschental"}},{q="Welche weiteren Außenposten hält die Horde im Eschental?",a="Die Horde hält auch den Außenposten von Zoram'gar am äußersten Westrand des Eschentals, entlang des Zoramstrands.",al={"stützpunkte der horde im eschental","zoramstrand posten","außenposten im eschental"}},{q="Gibt es bei dieser Quest Kämpfe?",a="Nein. Ihr reist von Orgrimmar durch das Brachland, um Euch bei Senani Donnerherz zu melden. Die Reise selbst erfordert keine Kämpfe.",al={"gibt es kämpfe bei dieser quest","muss etwas bekämpft werden","einfache questabgabe"}}},fx={["70907bc1"]={q="Warum will Kriegsrufer Gorlach, dass Abenteurer ins Eschental geschickt werden?",a="Kriegsrufer Gorlach fungiert als Herold und Rekrutierer in Orgrimmar und ruft eifrige Krieger dazu auf, die Grenzkampagnen der Horde zu unterstützen. Die Horde hat sich mit dem Splitterholzposten und dem Außenposten am Zoramstrand einen Stützpunkt im Eschental geschaffen, aber die Aufrechterhaltung und Verteidigung dieser Präsenz erfordert einen stetigen Strom fähiger Kämpfer. Indem er Euch zur Jagd von Senani Donnerherz schickt, stärkt Gorlach die Nordgrenze und gibt gleichzeitig erprobten Rekruten ein Übungsgelände, um Ehre und Ruhm für die Horde zu gewinnen.",al={"kriegsrufer gorlach motiv","warum ins eschental schicken","warum gorlachs jagd"}}},fp="18,185,17.300.0,22.367.0,48.124.0,27.113.0,27.165.0,42.163.0,53.95.0,35.123.0"}
P.entries["quest:2359"] = {n="Klavens Turm",s="Von einem Lager in Westfall aus beobachtet Agentin Kearnen Klavens Turm. Seltsame Lieferungen und veränderte Wachen deuten auf eine Gefahr innerhalb der Bruderschaft der Defias hin.",h="Von einem Lager in Westfall aus beobachtet Agentin Kearnen Klavens Turm.",kw={"agentin kearnen","bruderschaft der defias","dämmerwaldtruhe","klaven mortwake","klavens turm","mathias shaw","gifte","si:7","westfall","zanzil"},ang={["class:Rogue"]="Als Schurke der Allianz steht Ihr vor einer verdeckten Infiltration, die Verstohlenheit, Taschendiebstahl, Schlossknacken und das Aufspüren körperlicher Schwachstellen eines Feindes erfordert.",["faction:Alliance"]="Die Defias in Klavens Turm haben sich mit Dschungeltrollen und dunkler Alchemie verbündet, um das Königreich zu bedrohen. Sie sind mehr als verbitterte Steinmetze.",["race:Human"]="Als menschlicher Verteidiger Sturmwinds könntet Ihr mit Entsetzen feststellen, dass ehemalige Landsleute in Westfall zu willenlosen untoten Drohnen gemacht wurden."},sec={{t="Ein Beobachtungsposten in Westfall",b="Am südöstlichen Rand von Westfall fließt der Fluss unterhalb von Klavens Turm, nördlich der Dolchhügel. Die Bruderschaft der Defias hält den steinernen Turm besetzt, doch ihre menschlichen Diebe und Banditen sind überall auf den Ebenen anzutreffen. Agentin Kearnen beobachtet den Turm seit Wochen allein. In letzter Zeit hat sie Seltsames gesehen: Eine bizarre Lieferung kam direkt aus den schattigen Wäldern des Dämmerwalds, eskortiert von monströsen, entstellten Wachen, die gewöhnlichen Wegelagerern nicht ähnelten."},{t="Der Turm und die stachelbewehrte Wache",b="Klaven Mortwake befehligt den Turm, in dem veränderte Wachen rau und mühsam nach Luft ringen. Unter den schlurfenden Wachen trägt ein massiger Zombie den Turmschlüssel der Defias bei sich. Ihn zu entwenden erfordert Lautlosigkeit und Finesse. Mit dem Schlüssel kann ein Agent die Verteidigung am Boden umgehen, die oberen Ebenen der Festung erreichen und die mit einem Vorhängeschloss gesicherte Dämmerwaldtruhe öffnen."},{t="Zanzils Gebräu",b="Klaven Mortwakes persönliches Tagebuch verbindet die Defias, die Venture Company und die Dschungeltrolle des Schlingendorntals miteinander. Darin steht, dass der Hexendoktor Zanzil ein alchemistisches Gift entdeckt hat, das gedankenlose, gehorsame untote Drohnen erweckt. Für Meister Mathias Shaw und den SI:7 offenbart diese Entdeckung die wachsenden Ambitionen der Defias. Ihre Agenten brauchen fundierte Kenntnisse über Gifte."}},faq={{q="Wo liegt Klavens Turm?",a="Klavens Turm erhebt sich nahe dem Fluss am südöstlichen Rand von Westfall, nördlich der Dolchhügel. Die Bruderschaft der Defias hält den befestigten Turm besetzt.",al={"klavens turm standort","wo ist klavens turm","defias turm standort westfall"}},{q="Wer ist Agentin Kearnen?",a="Agentin Kearnen dient Sturmwinds Geheimdienst, dem SI:7. Seit Wochen beobachtet sie Klavens Turm heimlich von einem nahe gelegenen Lager aus, verfolgt seltsame Lieferungen und plant eine Infiltration.",al={"agentin kearnen","wer vergibt die quest für klavens turm","wer ist die schurkin in westfall"}},{q="Was ist an den Wachen von Klavens Turm ungewöhnlich?",a="Die Wachen des Turms sind veränderte Untote, anders als die üblichen menschlichen Banditen der Defias. Ein exotisches alchemistisches Gebräu, das nach Westfall geliefert wurde, machte sie zu willenlosen Arbeitern.",al={"warum sind die wachen zombies","klavens turm wachen","was sind die turmwachen"}},{q="Wie kommen die Defias zu untoten Dienern?",a="Die Defias beschafften sich ein besonderes giftiges Gebräu von Zanzil, einem Hexendoktor der Dschungeltrolle im Schlingendorntal. Das Gift gelangte durch Geschäfte mit der Venture Company zu ihnen und verwandelt lebende Versuchsobjekte in gehorsame Drohnen.",al={"wie kamen die defias an zombies","warum haben die defias untote","zanzil defias verbindung"}},{q="Wer ist Klaven Mortwake?",a="Klaven Mortwake ist ein hochrangiger Aufseher der Defias im Turm. Er überwachte finstere Lieferungen aus dem Dämmerwald und führte ein privates Tagebuch über ihre unheilvolle Alchemie.",al={"klaven mortwake geschichte","wer ist klaven mortwake","klaven"}},{q="Warum interessiert sich Mathias Shaw für das geborgene Tagebuch?",a="Meister Mathias Shaw braucht nützliche Informationen über Bündnisse der Defias und gefährliche ausländische Agenten. Die Nachricht, dass Zanzils Trolle mit Gift Untote erschaffen können, warnt den SI:7 vor einer ernsten Bedrohung für Sturmwind. Deshalb muss der Geheimdienst seine Agenten in der Giftkunde ausbilden.",al={"warum will mathias shaw das tagebuch","si7 zanzil gift","mathias shaw klaven"}}},fx={af44437f={q="Warum will Agentin Kearnen, dass dies erledigt wird?",a="Agentin Kearnen beobachtet Klaven's Tower seit Wochen, um die Defias-Aktivitäten zu verfolgen. Als eine unheimliche Lieferung aus dem Dämmerwald unter der Bewachung unmenschlicher Kreaturen eintraf, wusste sie, dass die Bruderschaft etwas Gefährliches verbarg. Ihre Pflicht gegenüber dem SI:7 ist die Überwachung und Informationsbeschaffung; herauszufinden, was in dieser Truhe verschlossen ist, wird offenlegen, welches finstere Vorhaben die Defias direkt unter der Nase von Sturmwind aushecken.",al={"kearnen motiv","warum braucht agentin kearnen das","kearnen grund"}},["043ff283"]={q="Wofür ist der Turmschlüssel der Defias?",a="Der Turmschlüssel der Defias gewährt Zugang zur schwer befestigten Festung und der darin bewachten Dämmerwaldtruhe. Der Schlüssel, der von einer der grotesken, stacheligen Monstrositäten getragen wird, die den Umkreis patrouillieren, ist Eure einzige Möglichkeit, die Schlösser der Defias zu umgehen und zu untersuchen, was ihre seltsamen Verbündeten nach Westfall geschmuggelt haben.",al={"turmschlüssel der defias","was öffnet klaven's tower","nutzen turmschlüssel"}},d5d17d25={q="Was ist Klaven Jagdrufs Tagebuch?",a="Dieses Tagebuch, das in der Dämmerwaldtruhe oben im Turm verschlossen ist, enthält die Aufzeichnungen und Geheimnisse von Klaven Jagdruf. Es beschreibt, wie die The Defias Brotherhood mit externen Kräften zusammenarbeitete, um abscheuliche Gebräue zu brauen, und enthüllt, dass seltsame Tränke von Zanzils Trollen einen Zustand des lebendigen Todes hervorrufen können, um willenslose Drohnen zu erschaffen.",al={"klaven jagdrufs tagebuch","klavens tagebuch","was steht im tagebuch"}},["738a266c"]={q="Warum schickt Agentin Kearnen Euch an ihrer statt?",a="Agentin Kearnen ist eine Späherin des SI:7, deren Hauptaufgabe langfristige Aufklärung ist. Ihre Tarnung aufzugeben, um einen befestigten Außenposten voller unnatürlicher Wachen zu stürmen, würde ihre Stellung gefährden und die Defias warnen, bevor das SI:7 von deren Plänen erfährt. Sie braucht einen fähigen Agenten, der an den Wachen vorbeischlüpft, die Informationen sichert und sie direkt an Mathias Shaw liefert.",al={"warum ich klaven turm","warum infiltriert kearnen nicht","warum schickt ihr mich"}}},fp="14,146,22.434.0,30.342.1,19.366.2,32.145.0,21.189.0,48.164.1,41.214.1,23.160.0,55.252.1"}
P.entries["quest:2360"] = {n="Mathias und die Defias",s="In Westfall hat SI:7 ungewöhnlich rege Aktivitäten der Defias festgestellt. Ihr werdet zu Agentin Kearnen nahe einem verlassenen Wachturm der Allianz geschickt, um ihren Bericht entgegenzunehmen.",h="In Westfall hat SI:7 ungewöhnlich rege Aktivitäten der Defias festgestellt.",kw={"agentin kearnen","defias","mathias","rotkammgebirge","späherkuppe","si:7","wachturm","westfall"},ang={["faction:Alliance"]="Die Defias haben einen verlassenen Wachturm der Allianz in Westfall eingenommen und nutzen ihn als Stützpunkt für den Schmuggel."},sec={{t="Der Wachturm",b="Die Defias haben einen verlassenen Wachturm der Allianz südöstlich der Späherkuppe eingenommen. SI:7 berichtet, dass sie ihn als Stützpunkt nutzen, um Waren von der Nachschubroute aus dem Rotkammgebirge zu schmuggeln. Ihr werdet nach Westfall geschickt, um Agentin Kearnen zu finden, die sich nahe dem Turm versteckt hält, und ihren Bericht anzuhören."}},faq={{q="Was geschieht in Westfall?",a="SI:7 meldet ungewöhnlich rege Aktivitäten der Defias in Westfall. Die Defias haben einen verlassenen Wachturm der Allianz eingenommen und nutzen ihn, um Waren von der Nachschubroute aus dem Rotkammgebirge zu schmuggeln.",al={"defias in westfall","defias-aktivitäten in westfall"}},{q="Wo liegt der Stützpunkt der Defias?",a="Der Stützpunkt der Defias ist ein verlassener Wachturm der Allianz südöstlich der Späherkuppe.",al={"defias-turm","wo ist ihr stützpunkt"}},{q="Wer ist Agentin Kearnen?",a="Agentin Kearnen ist die Agentin von SI:7, die Ihr nahe dem Turm finden sollt, um ihren Bericht entgegenzunehmen.",al={"kearnen","wer ist kearnen"}},{q="Was soll ich für SI:7 tun?",a="SI:7 schickt Euch nach Westfall, um Agentin Kearnen zu finden, die sich nahe dem Turm versteckt hält, und ihren Bericht entgegenzunehmen.",al={"si7-auftrag","kearnen finden"}},{q="Was schmuggeln die Defias?",a="Die Defias schmuggeln Waren von der Nachschubroute aus dem Rotkammgebirge.",al={"defias-waren","nachschub aus dem rotkammgebirge"}}},fp="22,143,15.264.0,30.173.0,25.80.0,21.85.0,29.98.0,30.62.0"}
P.entries["quest:237"] = {n="Verteidigung der Länder des Königs",s="Im südlichen Loch Modan ruft Gebirgsjäger Gravelgaw um Hilfe gegen die Splittersteintrogge. Da die Streitkräfte der Zwerge an der Allianzfront gebunden sind, müssen örtliche Außenposten auf Freiwillige vertrauen, um die Stellung zu halten.",h="Im südlichen Loch Modan ruft Gebirgsjäger Gravelgaw um Hilfe gegen die Splittersteintrogge.",kw={"gravelgaw","eisenschmiede","loch modan","gebirgsjäger","seher","schädelbrecher","splitterstein","trogge","tal der könige"},ang={["faction:Alliance"]="Diese Mission zeigt den Preis des weitreichenden Krieges der Allianz. Während ihre Streitkräfte ferne Länder sichern, bleiben die Heimatländer ihrer eigenen Mitglieder örtlichen Bedrohungen schutzlos ausgeliefert.",["race:Dwarf"]="Als Zwerg ist die Verteidigung des Tals der Könige für Euch eine persönliche Angelegenheit. Es ehrt die größten Herrscher von Eisenschmiede, und Trogge entweihen diesen Boden, während Eure Verwandten auf fernen Schlachtfeldern bluten. Das ist eine bittere Pille."},sec={{t="Eine dünne Verteidigung",b="Die Gebirgsjäger, die den südlichen Pass nach Dun Morogh bewachen, sind dünn gesät. König Magni Bronzebart hat einen Großteil der Streitkräfte von Eisenschmiede an die weitläufige Allianzfront entsandt, sodass den Türmen im Tal der Könige reguläre Infanterie fehlt. Deshalb ruft Gebirgsjäger Gravelgaw Freiwillige auf, im Splittersteintal zuzuschlagen und die Trogge in Schach zu halten. Vielleicht trifft niemals Verstärkung ein."},{t="Schamanen und Raufbolde der Splittersteintrogge",b="Die Splittersteintrogge sind weder geistlos noch ziellos. Ihre Kriegstrupps kämpfen mit roher Gewalt und primitiver Elementarmagie. Gravelgaw will ihre erfahrenen Schädelbrecher und ihre Seher, die mit mystischer Macht führen, aus dem Kampf drängen. Ohne diese Anführer verlieren die südlichen Lager des Stammes ihre Ordnung und können sich nicht gegen die Straße nach Eisenschmiede sammeln."},{t="Grim Tidings von der Front",b="Wenn Ihr Bericht erstattet, hat Gravelgaw düstere Neuigkeiten. Die versprochene zwergische Verstärkung wird nicht kommen. Schwere Verluste an der fernen Allianzfront haben die Reserven von Eisenschmiede aufgezehrt, sodass örtliche Gebirgsjäger und durchreisende Söldner Loch Modan verteidigen müssen."}},faq={{q="Wo befindet sich Gebirgsjäger Gravelgaw?",a="Gebirgsjäger Gravelgaw steht am südlichen Wachturm an der Straße durch das Tal der Könige. Er bewacht den Pass zwischen Loch Modan und Dun Morogh.",al={"gravelgaw standort","wo ist gravelgaw","bei gravelgaw abgeben"}},{q="Warum haben die Gebirgsjäger der Zwerge so wenig Personal?",a="König Magni Bronzebart hat den Großteil des stehenden Heeres von Eisenschmiede an die weitläufige Allianzfront entsandt. Während dort die Verluste steigen, bleiben den Grenzposten von Loch Modan nur Rumpfbesatzungen, die auf durchreisende Freiwillige angewiesen sind.",al={"warum keine zwergischen wachen","wo bleibt die verstärkung","eisenschmiede armee loch modan"}},{q="Wo sind die Schädelbrecher und Seher der Splittersteintrogge zu finden?",a="Die Schädelbrecher und Seher der Splittersteintrogge sammeln sich hauptsächlich in den südlichen Lagern des Splittersteintals, östlich des Tals der Könige. Einige treiben sich auch auf der nördlichsten Insel im Loch herum.",al={"splitterstein schädelbrecher standort","splitterstein seher standort","wo sind die trogge"}},{q="Warum gezielt Schädelbrecher und Seher angreifen?",a="Schädelbrecher sind die Stoßtruppen der Splittersteintrogge, während Seher primitive Magie wirken und die niederen Trogge befehligen. Beide zu besiegen raubt dem Stamm seine Schlagkraft und Koordination.",al={"warum seher töten","warum schädelbrecher","troggziele"}},{q="Wohin schickt Euch Gravelgaw als Nächstes?",a="Gravelgaw schickt Euch zu Gebirgsjäger Wallbang im südlichen Wachturm des Tals der Könige, um bei der Verteidigung des Tals zu helfen.",al={"nächste quest gravelgaw","wer ist wallbang","nach verteidigung der länder des königs"}}},fx={c78d8208={q="Warum will Gebirgsjäger Gravelgaw, dass dies erledigt wird?",a="Gebirgsjäger Gravelgaw versucht, den Verteidigern von Loch Modan kostbare Zeit zu verschaffen. Die Troggs der Steinbeißer dringen unaufhörlich in das südliche Tal vor, während Zwergentruppen auf fernen Schlachtfeldern der Allianz dringend benötigt werden. Indem er die Invasionsstreitkräfte dezimiert, hofft er, die südlichen Pässe zu sichern, bis Verstärkung aus Eisenschmiede eintreffen kann.",al={"warum troggs töten","gravelgaw beweggrund","in defense of the kings lands beweggrund"}}},fp="30,199,14.366.0,34.347.0,27.248.1,39.150.0,48.213.0,61.184.0,48.179.0,35.130.1"}
P.entries["quest:2378"] = {n="Suche nach der Zerschmetterten Hand",s="Ein Schurke der Verlassenen aus Tirisfal reist nach Orgrimmar, wo die Shattered Hand wartet. Die Todespirscher schicken den vielversprechenden Anwärter über das Meer nach Durotar, um die spezialisierten Künste des Clans zu erlernen.",h="Ein Schurke der Verlassenen aus Tirisfal reist nach Orgrimmar, wo die Shattered Hand wartet.",kw={"die kluft der schatten","deathstalkers","mennet carkad","orgrimmar","schurkenquest","shattered hand","shenthul"},ang={["class:Rogue"]="Als Schurke führt Euch Euer Weg von der örtlichen Ausbildung in das größere Netzwerk der Horde aus Verbrechern und Geheimagenten. In Kalimdor begegnet Ihr den Ausbildern der Unterwelt.",["faction:Horde"]="Als Mitglied der Horde erlebt Ihr die Zusammenarbeit zwischen den Geheimdiensten von Orgrimmar und Unterstadt, jenseits der Grunzer und Schamanen an der Front.",["race:Undead"]="Als junger Schurke der Verlassenen lasst Ihr die Überreste der Geißel in Lordaeron hinter Euch und zieht ins Kernland der Horde in Durotar."},sec={{t="Ein Bund der Schatten",b="Mennet Carkad hat gesehen, wie ein Schurke in Tirisfal seinen Wert bewiesen hat. Die Verlassenen bilden ihren eigenen Geheimorden aus, die Todespirscher. Ihr Bündnis mit der Horde eröffnet einen Weg zu dunkleren Künsten. Daher schickt Mennet vielversprechende Schurken zur Shattered Hand in Orgrimmar und verbindet so Lordaerons untote Agenten mit Kalimdors orcischen Meuchelmördern."},{t="In die Kluft der Schatten",b="Die Reise endet unter Orgrimmar in der Kluft der Schatten. Dort wirken Hexenmeister, Schurken und Dämonenbinder im Verborgenen. Shenthul, ein Ausbilder der Shattered Hand, erwartet den neu eingetroffenen untoten Agenten. Der schroffe Troll begrüßt den Gesandten mit harscher Skepsis. Ein guter Ruf allein genügt ihm nicht; er will sehen, ob der Gesandte echte Schläue besitzt oder die Überfahrt über das große Meer vergeudet hat."}},faq={{q="Wer vergibt die Quest „Suche nach der Zerschmetterten Hand“?",a="Mennet Carkad, ein Ausbilder der Todespirscher im Schurkenviertel von Unterstadt, schickt Euch los, nachdem Ihr Eure grundlegenden Fertigkeiten in Tirisfal bewiesen habt.",al={"wer startet suche nach der zerschmetterten hand","mennet carkad quest","wer schickt nach orgrimmar"}},{q="Wo befindet sich Shenthul?",a="Shenthul befindet sich in der Kluft der Schatten, dem dunklen Abgrund unter Orgrimmars zentralen Wegen.",al={"shenthul finden","shenthul standort","wo ist shenthul in orgrimmar"}},{q="Welche Beziehung besteht zwischen den Todespirschern und der Shattered Hand?",a="Die Todespirscher sind das Spionagenetzwerk und die Meuchelmördergilde der Verlassenen. Die Shattered Hand erfüllt eine ähnliche Rolle für die Horde in Orgrimmar. Die beiden Orden sind offizielle Verbündete, die innerhalb der Horde fortgeschrittene Ausbildung und geheime Aufträge miteinander teilen.",al={"deathstalkers und shattered hand","schurken der verlassenen orcschurken","warum nach orgrimmar geschickt"}},{q="Warum findet Shenthul mich wenig beeindruckend?",a="Shenthul findet Euch wenig beeindruckend, weil die Shattered Hand körperliche Widerstandskraft und rücksichtslose Schläue schätzt. Er beleidigt Neuankömmlinge, um ihren Stolz zu brechen und zu prüfen, ob sie eine harte Ausbildung zum Meuchelmörder durchstehen können.",al={"shenthul dialog","warum ist shenthul gemein","shenthul abschlusstext"}},{q="Was geschieht, nachdem man Shenthul erreicht hat?",a="Shenthul lässt Euch mit Zando'zan zusammenarbeiten und schickt Euch dann nach Süden in Richtung Ratschet zu Einsätzen im Brachland.",al={"was folgt auf suche nach der zerschmetterten hand","nächste quest nach shenthul","shattered hand questreihe"}},{q="Können auch Schurken, die keine Verlassenen sind, diese Quest erhalten?",a="Nein. Die Todespirscher vergeben diese Version an Schurken der Verlassenen. Orc- und Trollschurken in Durotar erhalten einen entsprechenden Übergang namens „To Orgrimmar!“.",al={"orcschurke suche nach der zerschmetterten hand","trollversion","to orgrimmar alternative"}}},fx={aa6bb2de={q="Warum möchte Mennet Carkad, dass ich nach Orgrimmar gehe?",a="Mennet Carkad erkennt an, dass Ihr den Todespirschern zwar gut gedient und Talent in Heimlichkeit und Täuschung bewiesen habt, Eure Entwicklung innerhalb der Unterstadt jedoch vorerst ihre Grenzen erreicht hat. Um Euer tödliches Handwerk weiter zu verfeinern, möchte er, dass Ihr Euch hinaus in die weite Horde wagt. Indem er Euch zum Shattered Hand in Orgrimmar schickt, nutzt Mennet ein Bündnis zwischen den beiden Fraktionen von Assassinen, um sicherzustellen, dass Ihr fortgeschrittene Unterweisung von erfahrenen orkischen Schurken erhaltet, die Euch Techniken lehren können, die in den Schatten von Lordaeron nicht zu finden sind.",al={"warum nach orgrimmar schicken","mennet carkads beweggrund","warum das shattered hand finden"}}},fp="23,206,19.336.0,24.387.0,44.142.0,26.88.0,74.255.0,38.209.0,37.114.0,39.148.0"}
P.entries["quest:2379"] = {n="Zando'zan",s="In Orgrimmars Kluft der Schatten schickt Shenthul einen vielversprechenden Schurken zu Zando'zan. Dort beginnt die Ausbildung für die geheimen Ränge der Shattered Hand.",h="In Orgrimmars Kluft der Schatten schickt Shenthul einen vielversprechenden Schurken zu Zando'zan.",kw={"die kluft der schatten","schlösserknacken","orgrimmar","schurke","shattered hand","shenthul","heimlichkeit","wrenix","zando'zan"},ang={["class:Rogue"]="Als Schurke tretet Ihr in die geheimen Ränge der Shattered Hand ein. Ihr beginnt als unausgebildeter Messerkämpfer und lasst Euch zu einem anerkannten Agenten der Horde ausbilden.",["faction:Horde"]="Die Shattered Hand übernimmt die Spionage und verdeckten Einsätze der Horde und schützt sie vor verborgenen Bedrohungen. Der Kriegshäuptling spricht von Ehre und Frontalangriff."},sec={{t="Ein Gang in die Schatten",b="Orgrimmars Herrscher wissen, dass Stärke allein nicht jeden Krieg gewinnen kann. Unter der Stadt beherbergt die Kluft der Schatten die Shattered Hand, eine geheime Gilde, die der Horde durch Spionage, Sabotage und Diebstahl dient. Wenn Schurkenlehrer Shenthul in einem Neuling Potenzial erkennt, schickt er ihn zur Ausbildung als Agent zu Zando'zan."},{t="Den eigenen Wert beweisen",b="Zando'zan prüft jeden unerfahrenen Schurken, der die Höhle betritt, bevor er ihm Respekt zollt. Mit der Begegnung beginnt die formelle Ausbildung in Heimlichkeit, Täuschung und Dieberei. Seine Lektionen schlagen die Brücke zwischen ungeschliffenen Straßentaschendieben und organisierten Geheimdienstagenten. Von dort aus bereiten sich Schurken auf Einsätze jenseits der schützenden roten Schluchtwände der Hauptstadt vor."}},faq={{q="Wer ist Zando'zan?",a="Zando'zan bildet in Orgrimmars Kluft der Schatten Schurken aus und betreut Rekruten der Shattered Hand. Er prüft Neuankömmlinge und lehrt Heimlichkeit, Einbruch und die Arbeit eines Agenten.",al={"zandozan","wer ist zando'zan","zando'zan kluft der schatten"}},{q="Warum schickt Shenthul Schurken zu Zando'zan?",a="Shenthul schickt vielversprechende Schurken zur Spezialausbildung der Shattered Hand zu Zando'zan. Zando'zan lehrt Einbruch und das Manipulieren von Schlössern für verdeckte Einsätze.",al={"warum mit zando'zan sprechen","shenthul zando'zan","zweck der quest"}},{q="Was ist die Shattered Hand in Orgrimmar?",a="Die Shattered Hand entstand als brutaler Orcklan aus Draenor, der für rituelle Selbstverstümmelung bekannt war. Sie wurde zum geheimen Arm der Horde für nachrichtendienstliche Arbeit und Meuchelmord. Aus Orgrimmars Schatten heraus widmen sich ihre Mitglieder der Spionage, dem Einsatz von Giften und der Erkundung.",al={"was ist die shattered hand","shattered hand orgrimmar","hordenschurken shattered hand"}},{q="Wohin führt diese Ausbildungsreihe als Nächstes?",a="Nachdem Ihr Euch bei Zando'zan gemeldet habt, schickt er Euch nach Ratschet an der Küste des Brachlands. Dort beratet Ihr Euch mit Wrenix, einem Goblinkontakt, und beginnt mit praktischen Übungen im Schlösserknacken vor Ort.",al={"nächste quest","was kommt nach zando'zan","wrenix aus ratschet"}},{q="Wo kann ich Zando'zan finden?",a="Zando'zan arbeitet in der Kluft der Schatten, einem Höhlennetz tief unter Orgrimmars Zentrum. Hexenmeister, Schattenpriester und Schurken im Geheimdienst versammeln sich dort, fern vom hellen Tageslicht.",al={"zando'zan standort","wo ist zando'zan","zando'zan finden"}},{q="Warum entschuldigt sich Zando'zan bei unserer Begegnung?",a="Zando'zan hat vor Eurer Ankunft womöglich an Eurem Mut gezweifelt. Als er sieht, dass Ihr zur Ausbildung bereit seid, erkennt er Eure Entschlossenheit an und nimmt seine anfänglichen Zweifel zurück.",al={"warum entschuldigt sich zandozan","abschlussdialog zando'zan"}}},fx={["1d4b3aab"]={q="Warum vertraut Shenthul dieses Training Euch anstatt einem anderen Schurken?",a="Shenthul erkennt Eure rohe Entschlossenheit an, weiß aber, dass bloßer Eifer nicht ausreicht, um die verdeckten Schlachten zu überleben, denen die Horde gegenübersteht. Ihr habt Euch als würdig erwiesen, über grundlegende Straßentricks hinauszugehen, aber um The Shattered Hand wirklich zu dienen, müsst Ihr formell zu einem engagierten Agenten geformt werden. Shenthul schickt Euch gezielt, weil Euer Pfad und Euer Potenzial die wachsamen Augen der Gilde auf Euch gezogen haben.",al={"warum ich shenthul","warum schickt mich zandozan","warum bin ich auserwählt"}}},fp="9,145,23.316.0,19.351.0,17.182.0,47.156.0,40.245.0,41.164.1,27.176.0,45.149.0"}
P.entries["quest:2380"] = {n="Nach Orgrimmar!",s="Kaplak schickt einen jungen Schurken von Klingenhügel nach Norden nach Orgrimmar. Ihr sollt Shenthul in der Kluft der Schatten finden und Euch dem Netzwerk der Shattered Hand anschließen.",h="Kaplak schickt einen jungen Schurken von Klingenhügel nach Norden nach Orgrimmar.",kw={"die kluft der schatten","kaplak","klingenhügel","schurke","shattered hand","shenthul","nach orgrimmar"},ang={["class:Rogue"]="Als Schurke tretet Ihr unter Shenthuls Aufsicht in das geheime Netzwerk der Hauptstadt ein. Nach den Scharmützeln im Grenzland dreht sich Eure Arbeit nun um Gifte, Diebstahl und Täuschung.",["faction:Horde"]="Als Mitglied der Horde hört Ihr von den Spannungen zwischen Thralls ehrenhaftem neuen Weg und den älteren Clanorganisationen, die unter Orgrimmar fortbestehen."},sec={{t="Ein Ruf in die Schatten",b="Kaplak schickt Euch von Klingenhügel nach Norden nach Orgrimmar. Euer wachsendes Können hat die Aufmerksamkeit höherrangiger Auftraggeber geweckt, auch wenn Eure Fertigkeiten noch ungeschliffen sind. Ihr lasst Durotars rote Felsen hinter Euch und brecht zur Hauptstadt auf."},{t="Unter Thralls wachsamem Auge",b="Shenthul empfängt Euch in der Kluft der Schatten unter Orgrimmar. Er beobachtet die politischen Reformen von Kriegshäuptling Thrall mit Unbehagen. Die Shattered Hand kann ihre Interessen nicht allein durch Gewalt oder offenen Trotz wahren. Geduld, Heimtücke und Täuschung helfen ihr, zu überleben und ihren Einfluss zu bewahren."}},faq={{q="Wer schickt mich auf diese Quest?",a="Kaplak, der Schurkenlehrer in Klingenhügel, schickt Euch nach Norden, nachdem Eure Fähigkeiten die Aufmerksamkeit höherrangiger Auftraggeber in Orgrimmar geweckt haben.",al={"questgeber","wer vergibt nach orgrimmar","kaplak quest"}},{q="Wo finde ich Shenthul?",a="Ihr findet Shenthul in der Kluft der Schatten, einem unterirdischen Viertel unter Orgrimmar, in dem sich Schurken, Hexenmeister und andere Ausgestoßene versammeln.",al={"shenthul standort","wo ist shenthul","kluft der schatten shenthul"}},{q="Welche Ziele verfolgt die Shattered Hand in Orgrimmar?",a="Die Shattered Hand ist eine Spionage- und Meuchelmördergilde innerhalb der Horde. Shenthul beobachtet Thralls ehrenhafte Reformen mit Unbehagen, und die Gilde setzt auf Heimlichkeit, um zu überleben und ihren Einfluss zu bewahren.",al={"shattered hand beweggründe","warum shattered hand in orgrimmar","shattered hand thrall"}},{q="Warum werde ich gerade jetzt entsandt?",a="Eure ersten Erkundungen und Scharmützel haben Euer Können bewiesen, daher tretet Ihr nun in den geregelten Gildendienst ein. Er beginnt mit dem Knacken von Schlössern und verdeckten Einsätzen in der Hauptstadt.",al={"schurkenquest stufe sechzehn","warum jetzt nach orgrimmar","vorladung zur schurkenausbildung"}},{q="Unterscheidet sich diese Quest von „Find the Shattered Hand“?",a="Beide Wege führen Schurken zu Shenthul in Orgrimmar. Welche Quest Ihr erhaltet, hängt davon ab, wo Ihr lernt oder Befehle entgegennehmt, und beide führen dieselbe Ausbildungskette fort.",al={"find the shattered hand oder nach orgrimmar","alternative einleitungsquest"}},{q="Was geschieht, nachdem ich mich bei Shenthul gemeldet habe?",a="Shenthul prüft Euer Können und schickt Euch auf der Questreihe weiter. Ihr trefft Kontaktpersonen wie Zando'zan und übernehmt dann verdeckte Aufträge mit Goblinkontakten in Ratschet.",al={"nächste quest nach nach orgrimmar","was gibt shenthul"}}},fx={a9995c5c={q="Warum will Kaplak, dass ich nach Orgrimmar gehe?",a="Kaplak handelt unter direktem Befehl von oben. Während er anerkennt, dass Ihr weit davon entfernt seid, ein wahrer Meister der Heimlichkeit zu sein, haben Eure aufkeimenden Talente die Aufmerksamkeit von Shenthul selbst erregt. The Shattered Hand benötigt gerissene Agenten, die für ihre verdeckte Agenda ausgebildet sind, und Kaplaks Pflicht ist es, vielversprechende Schurken wie Euch in die tieferen Schatten der Hauptstadt zu leiten, wo Eure wahre Ausbildung beginnen kann.",al={"warum schickt mich kaplak","kaplak beweggrund","warum nach orgrimmar"}}},fp="13,150,24.224.0,27.282.1,27.128.0,25.134.0,49.207.0,47.179.0,54.156.0,41.164.0"}
P.entries["quest:2381"] = {n="Das Ausplündern der Plünderer",s="Nahe Ratschet schickt Wrenix der Jämmerliche neue Schurken der Shattered Hand gegen die Südmeerfreibeuter. An Bord der Tide Razor erwarten sie Piraten, verschlossene Kassetten und ein gefährlicher Wächter, bevor sie den Schatz der Südmeerfreibeuter erbeuten.",h="Nahe Ratschet schickt Wrenix der Jämmerliche neue Schurken der Shattered Hand gegen die Südmeerfreibeuter.",kw={"r.c.v.k.","schlossknacken","das ausplündern der plünderer","polly","ratschet","southsea freebooters","schatz der südmeerfreibeuter","disteltee","tide razor","wrenix der jämmerliche"},ang={["class:Rogue"]="Als Schurke lernt Ihr, unter Druck Schlösser zu knacken, und erhaltet Disteltee, ein begehrtes Gebräu für Agenten im Dienst der Horde.",["faction:Horde"]="Die Shattered Hand setzt Goblinkontakte in Ratschet ein, um angehende Agenten gegen die Südmeerfreibeuter zu prüfen, die die Küste des Brachlands bedrohen.",["profession:Cooking"]="Als Schurke mit Interesse am Kochen könnt Ihr Euch Disteltee verdienen, ein Kräutertonikum, das für seine energiesteigernde Wirkung geschätzt wird."},sec={{t="Eine Prüfung von List und Stahl",b="Wrenix der Jämmerliche prüft angehende Agenten der Shattered Hand in Ratschet. Er schickt Schurken entlang der Küste des Brachlands nach Süden zu einer Bucht, in der die Tide Razor vor Anker liegt. Die Südmeerfreibeuter stellen die Schiffsbesatzung. Schurken müssen unbemerkt an Bord gelangen und das Piratenversteck betreten, in dem Beutelschneider ausgebildet werden. Dann knacken sie die Kassetten im Laderaum und bringen die Beute zurück."},{t="Polly und die Apparatur",b="Wrenix warnt, dass frühere Diebe in Stücken zu ihm zurückkehrten. Ein wilder Papagei namens Polly bewacht den untersten Laderaum des Schiffes. Damit ein Schurke dem Vogel entgegentreten kann, stellt Wrenix ein experimentelles R.C.V.K. bereit. Schleudert das Gerät nach dem Knacken der Piratenkassette auf Polly. Es verwirrt und schwächt den Vogel, sodass der Kampf zu gewinnen ist."}},faq={{q="Wer ist Wrenix der Jämmerliche?",a="Wrenix der Jämmerliche ist ein Goblin und Kontaktmann für Schurken in Ratschet. Er arbeitet mit Agenten zusammen, die mit der Shattered Hand in Orgrimmar verbunden sind, und schickt neue Diebe ins Piratengebiet, um Schlossknacken zu üben und gestohlene Beute zurückzuholen.",al={"wrenix","wer ist wrenix","ratschet goblin schurkenquest"}},{q="Wo liegt die Tide Razor?",a="Die Tide Razor liegt südlich von Ratschet an der Ostküste des Brachlands in einer Bucht der Südmeerfreibeuter vor Anker. Das Schiff dient den Piraten als Stützpunkt und Ausbildungsstätte.",al={"tide razor standort","wo ist das piratenschiff","wo sind die southsea-piraten"}},{q="Was ist ein R.C.V.K. und wie benutze ich es?",a="Das R.C.V.K. ist ein experimentelles Goblingerät, das Wrenix’ Gizmotronic Apparatus ausgibt. Setzt es gegen Polly ein, den riesigen Papagei, der den Schatz der Südmeerfreibeuter im Laderaum der Tide Razor bewacht. Es schwächt den Vogel, sodass er besiegt werden kann.",al={"rcvk","was ist rcvk","wie polly besiegen"}},{q="Warum ist der Übungsbereich zum Schlossknacken auf dem Schiff bedeutsam?",a="Das zweite Deck der Tide Razor ist der Ausbildungsraum der Southsea-Piraten. An den Schließkassetten können Schurken im Einsatz Schlossknacken üben, bevor sie sich an der Kassette weiter unten versuchen.",al={"schlossknacken üben","beutelschneider ausbildungsschiff","kassetten knacken brachland"}},{q="Warum ist diese Mission für Schurken so wichtig?",a="Der Raubzug beweist den Wert eines Schurken für das Netzwerk der Shattered Hand. Wrenix gibt Euch als Euren Anteil Disteltee, ein Gebräu, das die Kampfenergie eines Schurken rasch wiederherstellt.",al={"schurkenquest disteltee","warum das ausplündern der plünderer machen","schurkenquest belohnung"}},{q="Wer ist Polly?",a="Polly ist ein bösartiger Papagei, der für die Südmeerfreibeuter den unteren Laderaum der Tide Razor bewacht. Ohne Goblintechnik, die den Vogel schwächt, ist Polly für unerfahrene Eindringlinge tödlich.",al={"polly","riesiger papagei","tide razor boss"}}},fx={d00111f9={q="Warum will Wrenix der Jämmerliche den Schatz der Südmeerfreibeuter?",a="Wrenix ist ein gerissener Goblin-Dieb und Problemlöser, der von Ratschet aus operiert und es auf den illegalen Hort der Südmeerfreibeuter als große Auszahlung abgesehen hat. Frühere Versuche, das Schiff der Piraten zu plündern, endeten katastrophal und hinterließen fünf andere tote und zerstückelte Schurken. Indem er Euch schickt, um das Schiff zu stürmen und die Beute zu bergen, sichert Wrenix einen lukrativen Preis, während er Euren Mut gegen Halsabschneider testet, die sie zuerst gestohlen haben.",al={"wrenix beweggrund","warum schatz der südmeerfreibeuter stehlen","warum will wrenix das erledigt haben"}},abe44597={q="Warum braucht Wrenix Euch, anstatt Wachen anzuheuern oder selbst zu gehen?",a="Der Diebstahl bei den Südmeerfreibeutern ist heikle, illegale Arbeit, die nicht mit roher Gewalt oder den neutralen Wachen von Ratschet erledigt werden kann. Die Piraten bilden ihre eigenen Diebe an Bord der Tide Razor aus, was jemanden erfordert, der in Heimlichkeit und Schlossknacken geschult ist, um unentdeckt in den Laderaum zu schlüpfen. Als ein Goblin, der außerhalb der üblichen Handelsabkommen operiert, zieht Wrenix es vor, einen entbehrlichen, fähigen Agenten anzuheuern, anstatt seine eigene Haut zu riskieren.",al={"warum ich wrenix","warum einen schurken schicken","warum holt wrenix den schatz nicht"}}},fp="25,225,27.350.0,19.321.1,27.216.0,32.160.0,40.233.0,52.168.0,40.165.0,13.187.0"}
P.entries["quest:2382"] = {n="Wrenix aus Ratschet",s="In Orgrimmar führt Wrenix aus Ratschet Schurken der Horde zu einem Goblinhafen weit im Süden. Zando'zan schickt Euch zu Wrenix dem Jämmerlichen, einem zwielichtigen Goblin in Ratschet, um ihm beizustehen.",h="In Orgrimmar führt Wrenix aus Ratschet Schurken der Horde zu einem Goblinhafen weit im Süden.",kw={"ratschet","schurke","shattered hand","brachland","thrall","wrenix","zando'zan"},ang={["class:Rogue"]="Als Schurke der Horde verlasst Ihr die Sicherheit Orgrimmars und betretet neutrales Piratengebiet. Dies ist ein wesentlicher Schritt in Eurer Ausbildung.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass die Shattered Hand Augen und Ohren jenseits von Durotars Grenzen hat. Der Orden verlässt sich bei heiklen Aufträgen oft auf neutrale Häfen wie Ratschet."},sec={{t="Ein Prophet im Schatten",b="In der Kluft der Schatten wirkt Orgrimmars Schurkengilde aus gewundenen Felsspalten heraus, meist ungesehen. Zando'zan ist ein Troll, der Agenten mit wirrem Gefasel und düsteren Vorzeichen begrüßt. Er spricht davon, wie Kriegshäuptling Thrall durch Gift und Klinge niedergestreckt wird. Dann lässt er die Vision unerklärt und schickt Agenten nach Süden, nach Ratschet, einer Hafenstadt im Brachland."},{t="Ratschets Problemlöser",b="Ratschet liegt an der Küste des Brachlands, östlich vom Wegekreuz. Halunken, Söldner und Tüftler versammeln sich in diesem neutralen Hafen, in dem Wrenix der Jämmerliche lebt. Wrenix hat wenig Geduld mit Zando'zans seltsamen Eigenarten. Er sagt, die früheren Rekruten des Trolls hätten in der Bucht unter ihren hungrigen Raubtieren ein grausiges Ende gefunden."}},faq={{q="Wer schickt Euch nach Ratschet?",a="Zando'zan, ein Troll der Shattered Hand in Orgrimmars Kluft der Schatten, schickt Euch nach Süden, nachdem er von seltsamen Visionen gesprochen hat.",al={"wer vergibt den auftrag","auftraggeber","zandozan"}},{q="Wer ist Wrenix der Jämmerliche?",a="Wrenix der Jämmerliche ist ein Goblin und Kontaktmann in Ratschet. Er kümmert sich um verdeckte Aufträge und mechanische Ausrüstung für Schurken im ganzen Brachland.",al={"wer ist wrenix","wrenix ratschet","wrenix identität"}},{q="Was ist mit den Agenten geschehen, die vor mir geschickt wurden?",a="Wrenix sagt, die fünf Agenten, die Zando'zan vor Euch geschickt hat, hätten ihre Aufträge nicht erfüllt und seien vor Ratschets Küste zu Haifutter geworden.",al={"frühere schurken","haifutter","andere rekruten"}},{q="Was hat Zando'zan über Thrall erzählt?",a="Zando'zan sagt, er habe gesehen, wie Thrall durch einen vergifteten Dolch im Rücken niedergestreckt wurde. Dann bricht er ab und wechselt das Thema.",al={"thrall prophezeiung","thrall vergiftet","zandozan thrall vision"}},{q="Wo liegt Ratschet?",a="Ratschet liegt an der Ostküste des Brachlands, direkt östlich vom Wegekreuz. Straßen, die vom Südstrom nach Süden führen, verbinden die Stadt mit Durotar.",al={"wo ist ratschet","ratschet finden","ratschet lage"}},{q="Was kommt nach dem Treffen mit Wrenix?",a="Wenn Ihr Wrenix begrüßt, gibt er Euch 'Plundering the Plunderers', einen Auftrag, bei dem Ihr die Südmeerfreibeuter an der Küste südlich von Ratschet unterwandern sollt.",al={"nächster auftrag","nach wrenix","ratschet folgeauftrag"}}},fx={["17a3bd65"]={q="Warum schickt Zando'zan Euch zu Wrenix?",a="Zando'zan ist aufgeschreckt durch hektische Visionen des Untergangs und sieht Gift sowie einen verräterischen Dolch, der auf den Rücken von Kriegshäuptling Thrall gerichtet ist. In seiner Verzweiflung, diesen ungesehenen Bedrohungen in den Schatten entgegenzuwirken, verlässt sich der exzentrische Troll auf externe Kontakte wie Wrenix der Jämmerliche in Ratschet, um verdeckte Operationen durchzuführen und spezialisierte Ausrüstung zu beschaffen.",al={"warum zu wrenix schicken","zandozan beweggrund","warum wrenix besuchen"}},["2311cb82"]={q="Warum schickt Zando'zan Euch, anstatt es selbst zu erledigen?",a="Zando'zan bleibt in den Schatten der Kluft der Schatten von Orgrimmar gefangen, wo er dunkle Vorzeichen beobachtet und über seine Verschwörungsvisionen murmelt. Sein erratisches Auftreten und seine Angst davor, 'zu viel gesagt' zu haben, halten ihn davon ab, offen im Feld zu operieren, also verlässt er sich auf fähige Schurken, die als seine diskreten Hände außerhalb der Stadtmauern dienen.",al={"warum schickt ihr mich","warum braucht mich zandozan","warum geht er nicht selbst"}}},fp="17,171,24.337.0,24.316.0,25.123.0,27.129.0,47.121.0,50.124.0,25.150.0,37.153.1"}
P.entries["quest:2383"] = {n="Einfaches Pergament",s="Im Tal der Prüfungen wartet eine Nachricht auf Euch, die während Eurer Abwesenheit geschickt wurde. Frang, Euer Klassenausbilder, ist draußen vor dem Den.",h="Im Tal der Prüfungen wartet eine Nachricht auf Euch, die während Eurer Abwesenheit geschickt wurde.",kw={"klassenausbilder","den","frang","pergament","einfaches pergament","das tal der prüfungen"},sec={{t="Eine Nachricht von Frang",b="Das Pergament bittet Euch, seine Worte zu lesen und mit Frang zu sprechen. Euer Klassenausbilder wartet draußen vor dem Den im Tal der Prüfungen."}},faq={{q="Wer hat das Pergament geschickt?",a="Das Pergament scheint von Frang, Eurem Klassenausbilder, zu stammen.",al={"absender des pergaments","wer hat es geschrieben"}},{q="Wo kann ich Frang finden?",a="Frang wartet draußen vor dem Den im Tal der Prüfungen.",al={"wo ist frang","frangs standort"}},{q="Was will Frang?",a="Frang möchte mit Euch sprechen, wenn Ihr bereit seid.",al={"warum frang mich sprechen will","nachricht auf dem pergament"}},{q="Was soll ich mit dem Pergament tun?",a="Lest das Pergament und sprecht dann mit Frang im Tal der Prüfungen.",al={"pergament lesen","einfaches pergament"}}},fp="16,121,20.128.0,23.66.0,23.52.0,21.43.0,36.66.0"}
P.entries["quest:239"] = {n="Hilfe für die Weststromgarnison",s="In der Weststromgarnison stehen Stellvertreter Rainer und seine Wachen mit wenigen verfügbaren Soldaten unter wachsendem Druck. Marschall Dughan schickt verfügbare Abenteurer nach Westen zum Vorposten an der Grenze des Walds von Elwynn zu Westfall. Sturmwinds Armee ist im ganzen Königreich im Einsatz und überlastet, sodass die Garnison ohne regelmäßige Verstärkung gegen Flusssetzergnolle und umherziehende Diebe bestehen muss.",h="In der Weststromgarnison stehen Stellvertreter Rainer und seine Wachen mit wenigen verfügbaren Soldaten unter...",kw={"stellvertreter rainer","wald von elwynn","gnolle","goldhain","marschall dughan","flusssetzer","weststromgarnison"},ang={["faction:Alliance"]="Als Freiwilliger der Allianz übernehmt Ihr die Arbeit regulärer Soldaten und helft, die Kerngebiete vor dem völligen Chaos zu bewahren.",["race:Human"]="Als Mensch aus Sturmwind seht Ihr ein beunruhigendes Zeichen dafür, wie sehr das Königreich vernachlässigt wird. Seit dem Verschwinden des Königs sind die Verteidigungskräfte der Krone geschwächt."},sec={{t="Eine überlastete Grenze",b="Die Weststromgarnison bewacht den westlichen Rand des Walds von Elwynn, wo besiedeltes Waldland auf die unruhigen Ebenen von Westfall trifft. Gnollkriegstrupps und Banditen werden entlang der Wasserwege und westlichen Straßen immer dreister, weshalb die kleine Garnison um mehr Männer gebeten hat. Marschall Dughan und die Verwaltung von Goldhain haben keine Soldaten aus Sturmwind übrig. Die örtlichen Befehlshaber müssen reisende Söldner und umherziehende Abenteurer anheuern."},{t="Die Bedrohung jenseits des Bachs",b="Stellvertreter Rainer und seine Männer stehen Flusssetzergnollen gegenüber, die Reisende und nahe gelegene Gehöfte bedrängen. Das Rudel durchstreift die Grenzlande zwischen Elwynn und Westfall. Sturmwind ist durch politische und militärische Schwierigkeiten abgelenkt, und die Gnolle dringen tiefer in bewohntes Gebiet vor. Die Weststromgarnison verhindert ihren ungehinderten Vormarsch ins Herz des Waldes."}},faq={{q="Warum kann Sturmwind keine regulären Soldaten zur Weststromgarnison schicken?",a="Sturmwinds stehendes Heer ist an mehreren Grenzen im Einsatz und überlastet. Da König Varian Wrynn verschwunden ist und innere Konflikte das Reich erschüttern, hat das Oberkommando reguläre Soldaten für ländliche Vorposten verweigert oder nicht entsenden können. Ortsmarschälle wie Dughan müssen sich auf unabhängige Freiwillige verlassen.",al={"warum keine truppen aus sturmwind","warum abenteurer schicken","wo ist sturmwinds armee"}},{q="Wo liegt die Weststromgarnison?",a="Die Weststromgarnison liegt am westlichen Rand des Walds von Elwynn. Folgt der Hauptstraße von Goldhain nach Westen, am kleinen Bach vorbei. Der befestigte Turm steht zu Eurer Rechten, kurz vor der Grenze zu Westfall.",al={"lage der weststromgarnison","wie nach westbrook gelangen","wo ist stellvertreter rainer"}},{q="Welche Bedrohungen machen der Garnison zu schaffen?",a="Stellvertreter Rainer sieht sich wiederholten Überfällen durch Flusssetzergnolle sowie zunehmenden Aktivitäten von Dieben und Banditen im Grenzgebiet zwischen Westfall und dem Wald von Elwynn gegenüber.",al={"was greift westbrook an","warum braucht rainer hilfe","wer greift die weststromgarnison an"}},{q="Wer ist Stellvertreter Rainer?",a="Stellvertreter Rainer ist der Offizier aus Sturmwind, der die Weststromgarnison befehligt. Er muss die westliche Grenze halten und sich auf zivile Freiwillige und Söldner verlassen, da offizielle militärische Verstärkung knapp ist.",al={"rainers geschichte","stellvertreter rainer","wer ist rainer"}},{q="Was geschieht, nachdem man sich bei Stellvertreter Rainer gemeldet hat?",a="Stellvertreter Rainer bittet Euch um Hilfe gegen die örtlichen Flusssetzergnolle. Er setzt eine Prämie auf ihre Halsbänder aus, um ihre Zahl zu verringern und die Grenzstraße zu schützen.",al={"what comes next","westbrook questreihe","rainer quest"}},{q="Warum dringen die Gnolle in den Wald von Elwynn vor?",a="Die Flusssetzergnolle haben Lager entlang der Flüsse, die Elwynn und Westfall trennen. Da weniger Soldaten an der Grenze stehen, sind sie dreist genug geworden, Handelswege zu überfallen und zu den Höfen im Inneren Elwynns vorzudringen.",al={"flusssetzergnolle elwynn","warum sind gnolle hier","gnollproblem"}}},fx={["76645dec"]={q="Warum will Marschall Dughan, dass Ihr zur Weststromgarnison geht?",a="Marschall Dughan ist dafür verantwortlich, im Wald von Elwynn von Goldhain aus für Ordnung und Sicherheit zu sorgen, aber seine Ressourcen sind bis zum Äußersten erschöpft. Die Weststromgarnison bewacht die westliche Grenze des Königreichs, und Stellvertreter Rainer hat dringende Nachrichten über zunehmendes Banditentum und eindringende Gnolle gesendet. Ohne reguläre Truppen, die er als Verstärkung entsenden könnte, muss Dughan sich auf unabhängige Abenteurer verlassen, die auf den Hilferuf des Außenpostens antworten, bevor die westliche Grenze vollständig zusammenbricht.",al={"warum zur weststromgarnison schicken","marschall dughan beweggrund","warum braucht weststromgarnison hilfe"}}},fp="30,367,25.395.0,27.357.0,64.289.0,36.195.0,40.157.0,21.205.0,46.153.0,46.211.0"}
P.entries["quest:2399"] = {n="Die sprießenden Wedel",s="In Denalans Garten am Al'Amethsee hat der eingepflanzte Wedel Wurzeln geschlagen und ausgetrieben. Seine neuen Triebe sind nun zwischen den Gartenbeeten zu sehen.",h="In Denalans Garten am Al'Amethsee hat der eingepflanzte Wedel Wurzeln geschlagen und ausgetrieben.",kw={"denalan","kräuterkunde","pflanzkübel","samen","schimmernder wedel","sprießende wedel","teldrassil","quellsee"},ang={["class:Druid"]="Als Druide könnt Ihr in Denalans Pflanzkübel sehen, wie das Leben unter aufmerksamer Pflege gedeiht, während Teldrassil wachsenden Gefahren gegenübersteht.",["profession:Herbalism"]="Denalans Forschung zeigt die Arbeit, die das Sammeln und Untersuchen von Teldrassils Pflanzen erfordert. Sie zeigt auch, wie schnell sich heimische Samen an gepflegte Erde anpassen.",["race:NightElf"]="Als Kaldorei helft Ihr, das Leben zu behüten und zu pflegen, das überall auf Eurem jungen Weltbaum Wurzeln schlägt."},sec={{t="Ein Garten am Al'Amethsee",b="Ihr findet Denalans Garten nahe dem Al'Amethsee. Dort erforscht der Botaniker Teldrassils eigentümliche Pflanzen. Nachdem ein Schimmernder Wedel eingepflanzt wurde, wachsen neue Wedel aus der Erde seines Pflanzkübels, bereit, gesammelt und untersucht zu werden."},{t="Die seltsame Flora des Weltbaums",b="Das junge Teldrassil ist gewaltig, und seine Pflanzen wachsen schnell. Nachtelfische Kräuterkundige finden dieses Wachstum faszinierend und beunruhigend. Die Schimmernden Wedel und ihre Ableger zeigen, wie schnell das Leben auf den Ästen des Weltbaums Fuß fasst. Doch seine Lebenskraft lässt sich nur schwer vorhersagen."}},faq={{q="Was sind die sprießenden Wedel?",a="Es sind die Pflanzen, die austrieben, nachdem Denalan einen Schimmernden Wedel in seinem Lager am Al'Amethsee eingepflanzt hatte. Die eigentümlichen Wedel zittern, wenn sie bereit sind, gesammelt zu werden.",al={"sprießende wedel","was sind diese pflanzen","denalans wedel"}},{q="Wo liegt Denalans Garten?",a="Denalans Garten und Forschungslager liegen am östlichen Ufer des Al'Amethsees, südöstlich von Dolanaar in Teldrassil.",al={"denalans standort","wo ist denalan","garten am quellsee"}},{q="Warum pflanzt Denalan diese Wedel ein?",a="Denalan erforscht das ungewöhnliche, rasche Wachstum von Teldrassils Pflanzen. Er pflanzt Samen in vorbereitete Erde, um mehr über sie zu erfahren und sie auf nützliche stärkende oder heilkundliche Eigenschaften zu prüfen.",al={"warum wedel einpflanzen","denalans experiment","zweck der wedel"}},{q="Sind die sprießenden Wedel gefährlich?",a="Nein. Diese sprießenden Wedel sind harmlose Pflanzen, die darauf warten, gepflückt zu werden, anders als manche verderbten oder feindseligen Pflanzen andernorts auf Teldrassils Ästen.",al={"sind wedel gefährlich","greifen wedel an","ist die pflanze schädlich"}},{q="Was kommt vor dieser Quest?",a="Abenteurer finden zuerst einen Schimmernden Wedel in Teldrassils Wildnis und bringen ihn zu Denalan. Er pflanzt ihn in seinen Pflanzkübel im Garten und hofft, dass er Wurzeln schlägt.",al={"voraussetzung für die sprießenden wedel","welche quest kommt zuerst"}},{q="Warum zittern die Wedel?",a="Die Wedel zittern, während sie darauf warten, gepflückt zu werden. Was diese Bewegung verursacht, ist unbekannt.",al={"zitternde wedel","warum zittern sie"}}},fp="19,132,25.216.0,35.263.0,29.168.0,34.120.0,36.172.0,34.141.0,29.150.0,26.78.0"}
P.entries["quest:24"] = {n="Schattumbras Kopf",s="Am Splitterholzposten beweist Schattumbras Kopf, dass ein gefürchtetes Raubtier gefallen ist. Ihn Senani Donnerherz zu bringen, schließt eine Prüfung der Jagd im Eschental ab und hilft, die westlichen Straßen zum Zoramstrand zu sichern.",h="Am Splitterholzposten beweist Schattumbras Kopf, dass ein gefürchtetes Raubtier gefallen ist.",kw={"jagd im eschental","nachtsäbler","senani donnerherz","shadumbra","splitterholzposten","trophäe","der zoramstrand"},ang={["class:Hunter"]="Als Jäger stellt Ihr Eure Treffsicherheit, Geduld und Überlebenskunst im Wald auf die Probe, während Ihr eine schwer fassbare Nachtsäblerin wie Shadumbra verfolgt.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Versorgungslinien vom abgelegenen Splitterholzposten zum Zoramstrand offen zu halten, indem Ihr Bedrohungen wie Shadumbra beseitigt.",["race:Tauren"]="Als Tauren ehrt Ihr die natürliche Ordnung der Earth Mother, indem Ihr Euer Können an einem Spitzenraubtier messt und Eure Stammesbrüder auf der Straße beschützt."},sec={{t="Bedrohung der westlichen Straße",b="Shadumbra jagte in den Wäldern westlich des Splitterholzpostens. Späher und Kuriere der Horde nutzten diese Pfade, um den Zoramstrand zu erreichen. Ihre Schnelligkeit und Heimlichkeit machten jede Reise gefährlich, und jede Patrouille nach Westen hielt die Verteidiger des Postens in Alarmbereitschaft."},{t="Beweis der Jagd",b="Senani Donnerherz, eine Taurenjägerin, fordert die Champions der Horde heraus, die großen Bestien des Eschentals aufzuspüren und zu erlegen. Schattumbras Kopf beweist, dass der Jäger eines der tödlichsten einheimischen Raubtiere Kalimdors erlegt hat. Nun können Reisende die Straßen mit weniger Gefahr nutzen."}},faq={{q="Wer war Shadumbra?",a="Shadumbra war eine wilde Nachtsäblerin, die durch die Wälder westlich des Splitterholzpostens streifte. Sie überfiel Reisende auf dem Weg zur Küste und zählte zu den gefährlichsten heimischen Bestien des Eschentals.",al={"was ist shadumbra","shadumbras geschichte","wer ist die katze"}},{q="Warum will Senani Donnerherz den Kopf?",a="Senani Donnerherz leitet die Jagd im Eschental am Splitterholzposten. Schattumbras Kopf würdigt eine schwierige Jagd und bestätigt, dass Reisende auf dem Weg nach Westen dieser Bedrohung nicht länger ausgesetzt sind.",al={"warum den kopf bringen","senani donnerherz trophäe","jagd im eschental beweis"}},{q="Wie fügt sich das in die Jagd im Eschental ein?",a="Shadumbra ist eine der Hauptprüfungen der Jagd im Eschental. Sie zusammen mit großen Waldbestien wie Ursangous und Sharptalon zu erlegen, bringt die abschließende Anerkennung und The Hunt Completed.",al={"was ist die jagd im eschental","jagd questreihe","nächste jagdquest"}},{q="Warum ist es für die Horde wichtig, diese Bestie zu beseitigen?",a="Späher und Läufer reisen vom Splitterholzposten nach Westen zum Lager der Horde beim Außenposten von Zoram'gar am Zoramstrand. Shadumbra bedrohte jene, die die ungezähmten Wälder zu Fuß durchquerten.",al={"warum interessiert es die horde","zoramstrand straßengefahr","splitterholzposten sicherheit"}},{q="Wo ist Shadumbra zu finden?",a="Shadumbra streift durch die Wälder westlich des Splitterholzpostens. Sie jagt zwischen den Bäumen, zwischen der Straße und den uralten Nachtelfenruinen, die im mittleren und westlichen Eschental verstreut liegen.",al={"shadumbra fundort","wo ist shadumbra","shadumbra finden"}},{q="Ist Shadumbra mit den Nachtelfen verbündet?",a="Nein. Shadumbra ist eine wilde, ungezähmte Nachtsäblerin, die jeden bedroht, der ihr Revier durchquert. Nachtelfen zähmen und verehren häufig Nachtsäbler, doch Shadumbra folgt ihrem Raubtierinstinkt.",al={"ist shadumbra ein begleiter","begleiter einer schildwache","shadumbra nachtelf"}}},fp="16,210,28.231.0,17.250.0,18.190.0,43.175.0,44.180.0,50.182.0,29.181.0,41.175.0"}
P.entries["quest:240"] = {n="Rückkehr zu Bibbers",s="In Rabenflucht bringt Ihr Bibbers eine Mahlzeit von Küchenchef Grual. Die Küchlein lindern seinen Hunger, doch die Angst hält ihn weiter dort fest.",h="In Rabenflucht bringt Ihr Bibbers eine Mahlzeit von Küchenchef Grual.",kw={"küchenchef grual","dunkelhain","dämmerwald","schwärzliche krebsküchlein","knurrender magen","bibbers","scarlet raven tavern"},ang={["faction:Alliance"]="Dunkelhains karge, ungewöhnliche Kost zeigt, wie sehr die Stadt von den Lieferungen aus Sturmwind abgeschnitten ist. Die Einheimischen sind auf alles angewiesen, was in den Schatten kriecht.",["profession:Cooking"]="Küchenchef Grual verwandelt schleimige Beine von Giftweber-Spinnen in schmackhafte Küchlein und zeigt damit, wie die Küche nutzt, was das Grenzland hergibt."},sec={{t="Eine zweifelhafte Delikatesse",b="Küchenchef Grual kocht in der Scarlet Raven Tavern in Dunkelhain. Da es im Dämmerwald kaum Vieh oder Meereslebewesen gibt, nutzt er, was der verderbte Wald hergibt. Seine Schwärzlichen Krebsküchlein enthalten kein Krebsfleisch. Stattdessen bilden schleimige Beine von Giftweber-Spinnen die Grundlage seiner Spezialität. Grual nennt das einfallsreiche Küche, doch empfindliche Mägen mögen anderer Meinung sein."},{t="Bibbers' Nerven beruhigen",b="In Rabenflucht kauert Bibbers voller Angst und kann sich den Schrecken nicht stellen, die ihn aus dem Wald vertrieben haben. Entsetzen hält ihn vom Jagen und Sammeln ab, und der Hunger verschlimmert seine Not nur noch. Die warmen Küchlein verschaffen ihm einen seltenen Moment der Erleichterung. Verzweifelt vor Hunger isst er, ohne zu fragen, welche Art Krebs Grual verwendet hat."}},faq={{q="Was steckt in den Schwärzlichen Krebsküchlein?",a="Schwärzliche Krebsküchlein enthalten kein Krebsfleisch. Küchenchef Grual verwendet schleimige Beine heimischer Giftweber-Spinnen und würzt sie so, dass sie wie traditionelle Meeresfrüchteküchlein schmecken.",al={"krebsküchlein zutaten","woraus bestehen schwärzliche krebsküchlein","enthalten sie echtes krebsfleisch"}},{q="Weiß Bibbers, dass die Küchlein aus Spinnenschleim bestehen?",a="Küchenchef Grual behält das Rezept für sich. Ausgehungert und verängstigt verschlingt Bibbers die Küchlein, ohne zu fragen, was darin steckt.",al={"weiß bibbers bescheid","weiß bibbers von den spinnen"}},{q="Warum konnte Bibbers sich nicht selbst Nahrung beschaffen?",a="Nach seinen Erlebnissen in den wilden Wäldern des Dämmerwalds ist Bibbers von Angst überwältigt. Panik hält ihn in der Nähe von Rabenflucht, wo er für seine Nahrung auf mitfühlende Reisende angewiesen ist.",al={"warum hungert bibbers","warum jagt bibbers nicht"}},{q="Wer ist Küchenchef Grual?",a="Küchenchef Grual kocht in der Scarlet Raven Tavern in Dunkelhain. Da Schatten und Bestien die Stadt von der Außenwelt abschneiden, versorgt er die Gäste der Taverne mit ungewöhnlichen Zutaten, die Sammler ihm bringen.",al={"küchenchef grual rolle","koch in dunkelhain"}},{q="Wo beginnt diese Questreihe?",a="In Rabenflucht bittet Bibbers in „Bibbers' knurrender Magen“ um Hilfe gegen seinen Hunger. Ihr jagt Giftweber-Spinnen für Küchenchef Grual und kehrt dann mit der fertigen Mahlzeit zurück.",al={"wie beginnt bibbers' nahrungsquest","bibbers questreihe anfang"}},{q="Erholt sich Bibbers nach dem Essen?",a="Die Mahlzeit stillt Bibbers' Hunger, und er dankt Euch von Herzen. Essen kann sein tiefes Entsetzen nicht lindern; er bleibt verängstigt und wird von den dunklen Geheimnissen des Waldes heimgesucht.",al={"ist bibbers geheilt","hilft essen bibbers"}}},fx={deba9bdd={q="Warum will Küchenchef Grual, dass die Krabbenküchlein an Bibbers geliefert werden?",a="Küchenchef Grual leitet die Küche in der Scarlet Raven Tavern in Dunkelhain und ist stolz darauf, Bestellungen auszuführen, selbst bizarre, die aus örtlichen Spinneneingeweiden gekocht werden. Bibbers hungert in der gefährlichen Düsternis von Raven Hill und ist zu verängstigt, um die Reise in die Stadt selbst zu machen. Nachdem er seine speziellen 'Krabben'-Küchlein à la Grual zubereitet hat, vertraut der Koch sie Euch an, um die Bestellung von Bibbers zu erfüllen und sicherzustellen, dass der arme Kerl etwas zu essen bekommt.",al={"warum krabbenküchlein liefern","grual beweggrund bibbers","warum essen an bibbers schicken"}}},fp="17,118,18.340.0,24.300.0,32.142.0,51.125.0,38.167.0,18.189.0,34.156.0,34.172.0"}
P.entries["quest:243"] = {n="Auf ins Feld",s="In Tanaris testet Ihr Wüstenkreaturen mit dem Feldtestset von Apothekerin Zinge. Seine Energiequelle muss von den Goblins von Gadgetzan stammen, also schickt Zinge Euch zu Chefingenieur Bilgewhizzle.",h="In Tanaris testet Ihr Wüstenkreaturen mit dem Feldtestset von Apothekerin Zinge.",kw={"apothekerin","basilisk","bilgewhizzle","gadgetzan","hyäne","energiequelle","skorpid","tanaris","testset","zinge"},sec={{t="Gewebe in der Wüste",b="Apothekerin Zinge muss wissen, ob das Gewebe von Basilisken, Skorpids und Hyänen aus Tanaris von gleichbleibender Beschaffenheit ist. Ihr sammelt Proben und testet sie mit dem Feldtestset. Viele werden unbrauchbar sein, deshalb braucht Zinge acht brauchbare Proben von jeder Art. Kehrt erst zurück, wenn Ihr sie habt."},{t="Eine Energiequelle in Gadgetzan",b="Das modifizierte Set braucht eine Energiequelle, wie sie die Goblins von Gadgetzan besitzen. Zinge schickt Euch zu Chefingenieur Bilgewhizzle nach Gadgetzan, um eine zu beschaffen."},{t="Nichts ist umsonst",b="Chefingenieur Bilgewhizzle kennt die Energiequellen des Modells 4711-FTZ gut. Normalerweise betreiben sie die Wasserbrunnen, und die niederträchtigen Nomaden haben gerade reichlich davon zurückgelassen. Bilgewhizzle wird eine für welches Experiment auch immer besorgen, das Ihr zu verbergen versucht. Aber nicht umsonst. In Gadgetzan ist nichts umsonst."}},faq={{q="Wer schickt Euch für diese Forschung nach Tanaris?",a="Apothekerin Zinge schickt Euch mit einem Feldtestset nach Tanaris. Zinge möchte, dass Ihr Gewebe von Wüstenkreaturen testet.",al={"wer startet auf ins feld","wer vergibt auf ins feld","auf ins feld questgeber"}},{q="Warum müsst Ihr Chefingenieur Bilgewhizzle aufsuchen?",a="Das modifizierte Testset braucht eine Energiequelle, wie sie die Goblins von Gadgetzan besitzen. Chefingenieur Bilgewhizzle kann eine besorgen.",al={"bilgewhizzles rolle","warum bilgewhizzle aufsuchen","energiequelle für das testset"}},{q="Welche Tiere sollen getestet werden?",a="Ihr testet Basilisken, Skorpids und Hyänen aus Tanaris. Zinge braucht acht brauchbare Proben von jeder Art.",al={"zu testende tiere","auf ins feld kreaturenarten","gewebeproben tanaris"}}},fp="14,188,20.267.0,27.151.0,15.282.1,43.119.0,51.132.0,38.94.0"}
P.entries["quest:2438"] = {n="Der smaragdgrüne Traumfänger",s="In Dolanaar bittet Tallonkai Flinkwurzel Euch, den smaragdgrünen Traumfänger aus seinem verlassenen Zuhause in Sternenhauch zu bergen. Gaerolas Talvethren gab ihm das Erbstück, doch verdorbene Gnarlpine-Furbolgs vertrieben ihn aus dem Dorf, bevor er es mitnehmen konnte. Seine sanfte Magie wartet noch immer dort.",h="In Dolanaar bittet Tallonkai Flinkwurzel Euch, den smaragdgrünen Traumfänger aus seinem verlassenen Zuhause...",kw={"grabhügel von ban'ethil","dolanaar","smaragdgrüner traum","smaragdgrüner traumfänger","furbolg","gaerolas talvethren","gnarlpine","sternenhauch","tallonkai flinkwurzel","teldrassil"},ang={["class:Druid"]="Als Druide kennt Ihr Gaerolas Talvethren als den Wächter, der Eure schlafenden Angehörigen im Grabhügel von Ban'ethil umsorgt. Den Traumfänger zu bergen, den er Tallonkai gab, ist eine Frage der druidischen Ehre.",["faction:Alliance"]="Indem Ihr den vertriebenen Kaldorei von Dolanaar beisteht, helft Ihr, die örtliche Stabilität zu sichern, während sich Verderbnis unter Teldrassils Furbolgstämmen ausbreitet.",["race:NightElf"]="Sternenhauch war einst eine friedliche Zuflucht für Euer Volk. Helft Ihr Tallonkai, sein Erbe zurückzuerlangen, versetzt Ihr dem Wahnsinn, der Teldrassils Tierwelt erfasst, einen kleinen Schlag."},sec={{t="Ein druidischer Talisman",b="Gaerolas Talvethren gab Tallonkai einen seltenen druidischen Talisman. Der Wächter hütet die schlafenden Druiden im Grabhügel von Ban'ethil. Das Amulett kanalisiert die ruhigen Strömungen des Smaragdgrünen Traums und schenkt seinem Träger Frieden und Glück. Solche Geschenke erhalten nur wenige Vertraute, deren Leben der Bewahrung des Waldes gewidmet ist."},{t="Flucht aus Sternenhauch",b="Sternenhauch war friedlich, bis die Gnarlpine-Furbolgs einem gewalttätigen Wahnsinn verfielen. Sie vertrieben die Dorfbewohner aus ihren angestammten Häusern. Bei der angsterfüllten Flucht ließ Tallonkai seinen kostbarsten Besitz in seiner Kommode im südöstlichen Viertel des Dorfes versteckt zurück. Allein konnte er ihn nicht zurückholen."},{t="Die drohende Verderbnis",b="Der smaragdgrüne Traumfänger birgt die Macht des Traums, und die Gnarlpine sind dunklen Einflüssen verfallen. Diese Magie könnte verderbt oder zum Schaden anderer eingesetzt werden. Die Rückgabe des Amuletts an Tallonkai bewahrt seine verbliebene Macht vor den Furbolgs und anderen finsteren Bewohnern. Sie gibt ihm auch ein Stück von Sternenhauchs Erbe zurück."}},faq={{q="Was ist der smaragdgrüne Traumfänger?",a="Gaerolas Talvethren gab Tallonkai ein seltenes Amulett, das Energie aus dem Smaragdgrünen Traum schöpft. Der Wächter umsorgt die schlafenden Druiden im Grabhügel von Ban'ethil. Seine Magie schenkt seinem Träger Glück und geistige Harmonie.",al={"was ist der traumfänger","geschichte des traumfängers","smaragdgrüner traumfänger"}},{q="Warum blieb der Traumfänger in Sternenhauch zurück?",a="Die Gnarlpine-Furbolgs überrannten Sternenhauch in gewalttätiger Raserei. Tallonkai Flinkwurzel floh nach Dolanaar und ließ das Erbstück in seiner Schlafzimmerkommode versteckt zurück.",al={"warum zurückgelassen","sternenhauch kommode","tallonkais kommode"}},{q="Wer ist Tallonkai Flinkwurzel?",a="Tallonkai Flinkwurzel ist ein nachtelfischer Flüchtling in Dolanaar. Er entkam aus Sternenhauch und sucht mutige Reisende, die seine Familienerbstücke und druidischen Relikte aus den besetzten Ruinen bergen.",al={"wer ist tallonkai","tallonkai flinkwurzel"}},{q="Wer hat den Traumfänger gefertigt?",a="Tallonkai sagt, Gaerolas Talvethren habe ihm den Traumfänger gegeben. Gaerolas hütet die schlafenden Druiden im Grabhügel von Ban'ethil, doch niemand sagt, wer das Amulett gefertigt hat.",al={"wer hat ihn gefertigt","gaerolas talvethren traumfänger","gaerolas"}},{q="Wo in Sternenhauch befindet sich der Traumfänger?",a="Der Traumfänger liegt in Tallonkais Kommode im äußersten südöstlichen Haus von Sternenhauch. Im Haus streifen nun zahlreiche Gnarlpine-Furbolgs umher.",al={"wo ist die kommode","sternenhauch standort der kommode","traumfänger finden"}},{q="Was geschieht nach der Rückgabe des Traumfängers?",a="Als Tallonkai das zurückgebrachte Amulett untersucht, stellt er fest, dass sein Smaragd fehlt. Ferocitas the Dream Eater, der Anführer der Gnarlpine, hat ihn gestohlen, und die Jagd auf ihn beginnt.",al={"questfortsetzung","nächste quest nach dem traumfänger"}}},fx={["1ded4259"]={q="Warum will Tallonkai Flinkwurzel den Smaragdgrüner Traumfänger zurückhaben?",a="Der Smaragdgrüner Traumfänger ist ein seltener und zutiefst persönlicher Schatz. Er wurde Tallonkai von Gaerolas Talvethren, dem Wächter der Druiden im Grabhügel von Ban'ethil, geschenkt und trägt mächtige Magie aus dem Smaragdgrünen Traum in sich, um Glück zu bringen. Als Sternenhauch an die verderbten Gnarlpine-Furbolgs fiel, war Tallonkai gezwungen, ihn zurückzulassen. Er befürchtet, dass das heilige Relikt geschändet oder zerstört wird, wenn es in seinem verlassenen Zuhause bleibt.",al={"warum will tallonkai den traumfänger","tallonkai beweggrund","warum smaragdgrüner traumfänger bergen"}}},fp="24,289,18.312.0,26.299.0,24.312.1,33.219.0,59.160.0,27.187.0,26.165.0,56.146.0,48.167.1"}
P.entries["quest:244"] = {n="Eindringende Gnolle",s="Gnolle drängen zur westlichen Straße im Rotkammgebirge, und Seenhain fürchtet, abgeschnitten zu werden. Wache Parker entdeckt Lager nahe der Grenze und schickt Stellvertreter Feldon eine Nachricht. Die Warnung bestätigt die Sorge der Stadt, dass die Tiermenschen das Rotkammgebirge isolieren könnten.",h="Gnolle drängen zur westlichen Straße im Rotkammgebirge, und Seenhain fürchtet, abgeschnitten zu werden.",kw={"assessing the threat","stellvertreter feldon","grenze zu elwynn","eindringende gnolle","wache parker","seenhain","rotkammgebirge"},ang={["faction:Alliance"]="Als Reisender der Allianz wisst Ihr, dass Seenhains Isolation die östliche Front bedroht. Nachrichten von der Grenze sind für Reisende und Versorgungskonvois von Bedeutung.",["race:Human"]="Als Mensch könnt Ihr sehen, wie der Vormarsch der Tiermenschen nahe dem Wald von Elwynn das Herz des Königreichs verwundbar macht, während der König vermisst wird."},sec={{t="Augen auf die Grenze",b="Wache Parker bewacht den westlichen Grenzpfad, wo die Straße vom Wald von Elwynn ins Rotkammgebirge führt. Sturmwinds Streitkräfte sind ausgedünnt, sodass nur wenige Verteidiger entlang der Strecke bleiben. Parker hält die Schotterstraße für Versorgungswagen offen, doch seine Späher melden Kriegstrupps der Gnolle, die von den Felsen im Norden und Osten vorrücken. Ihre Lager liegen beunruhigend nahe an der Straße."},{t="Eine Stadt unter Belagerung",b="Nahe der Brücke von Seenhain erhält Stellvertreter Feldon die Warnung und erkennt die Gefahr für die Stadt. Gnolle aus dem Rotkammgebirge plündern nahe Seenhain, während ihre Lager nahe der Grenze zu Elwynn ihnen ermöglichen könnten, die Stadt einzukesseln und ins Kernland des Königreichs vorzustoßen. Sturmwind hat Bitten um Verstärkung ignoriert, sodass Seenhains Wache auf Bedrohungen von beiden Seiten nicht vorbereitet ist."}},faq={{q="Wer vergibt diese Quest?",a="Wache Parker übergibt Euch die Warnung an der Straße im westlichen Rotkammgebirge, nahe dem Grenzübergang zum Wald von Elwynn.",al={"questgeber","wo beginnen","wache parker fundort"}},{q="Wo finde ich Stellvertreter Feldon?",a="Stellvertreter Feldon patrouilliert in Seenhain, direkt südlich der großen Steinbrücke der Stadt.",al={"feldon fundort","wer ist stellvertreter feldon","abgabeort"}},{q="Warum sind die Gnolle auf der Straße ein Problem?",a="Die Straße zum Wald von Elwynn ist Seenhains einziger sicherer Landweg in den Rest des Königreichs. Wenn Gnolle die westlichen Hänge einnehmen, könnte die Stadt ihre Versorgung und ihren Fluchtweg verlieren.",al={"warum gnolle wichtig sind","gnollproblem im rotkammgebirge","gefahr auf der straße"}},{q="Warum schickt Sturmwind Seenhain keine Hilfe?",a="König Varian Wrynn wird vermisst, und Unruhen belasten das Reich. Highlord Bolvar und der Hof haben sich geweigert, königliche Truppen ins Rotkammgebirge zu entsenden, sodass Seenhain für seine Verteidigung auf örtliche Stellvertreter und Freiwillige angewiesen ist.",al={"wo sind sturmwinds wachen","keine verstärkung","verteidigung von seenhain"}},{q="Was geschieht, nachdem die Gnolle gemeldet wurden?",a="Stellvertreter Feldon bittet Euch in Assessing the Threat, die Lager der Gnolle genauer auszukundschaften, um herauszufinden, wie viele Gnolle sich versammelt haben.",al={"nächste quest","fortsetzung der questreihe"}},{q="Welche Gnollrudel dringen hier vor?",a="Gnolle aus dem Rotkammgebirge sammeln sich als Redridge Gnoll Pack in den Hügeln. Während die Kontrolle der Menschen über die Region schwindet, sind sie kühner geworden und stimmen ihre Angriffe besser aufeinander ab.",al={"welche gnolle","gnollclans im rotkammgebirge"}}},fx={e50462f9={q="Warum will Wache Parker, dass dies erledigt wird?",a="Wache Parker ist damit beauftragt, diesen Straßenabschnitt, der in das Rotkammgebirge führt, zu sichern, aber er hat feindliche Gnoll-Lager gesichtet, die sich direkt im Norden und Osten sammeln. Da er einen unmittelbar bevorstehenden Vorstoß befürchtet, der seine Patrouille überwältigen und den Pass abschneiden könnte, muss er dringend die Behörden in Seenhain informieren, bevor die Gnolle die Straße angreifen oder Richtung Wald von Elwynn vorstoßen.",al={"wache parker beweggrund","warum warnung an seenhain","warum schickt euch parker"}},be5d12a2={q="Warum schickt Wache Parker Euch, anstatt selbst zu gehen?",a="Parker hat strenge Befehle, Wache zu halten und die Straße zwischen dem Wald von Elwynn und Rotkammgebirge zu verteidigen. Wenn er seinen Posten verlässt, um zurück in die Stadt zu laufen, bleibt die Grenze völlig unbewacht gegenüber den lauernden Rudeln. Ein rüstiger Reisender, der in Richtung Seenhain unterwegs ist, ist seine beste Chance, die Warnung schnell zu überbringen, ohne seine Pflicht zu vernachlässigen.",al={"warum schickt ihr mich","warum geht parker nicht","warum kann wache parker nicht melden"}}},fp="18,234,18.369.0,18.363.0,22.120.0,31.94.0,40.176.0,45.206.0,40.125.0,39.148.0"}
P.entries["quest:245"] = {n="Gefahr auf acht Beinen",s="Im Dämmerwald drängen Giftnetzspinnen an die Westgrenze, und Behüter Dodds fürchtet um die Nachtwache. Er bittet Reisende, ihre Zahl zu verringern, bevor weitere Wachen in ihre Netze geraten.",h="Im Dämmerwald drängen Giftnetzspinnen an die Westgrenze, und Behüter Dodds fürchtet um die Nachtwache.",kw={"dunkelhain","dämmerwald","gefahr auf acht beinen","night watch","zwerggiftnetzspinne","spinnen","behüter dodds"},ang={["class:Hunter"]="Als Jäger stellt Ihr Euch im Dämmerwald bösartigen Giftnetzspinnen. Bedachte Schritte und ein Vorrat an Gegengift helfen Euch bei der Jagd auf sie.",["faction:Alliance"]="Die Nachtwache erhält keine Hilfe vom House of Nobles. Die Unterstützung durch Reisende der Allianz hilft, die Straßen offen zu halten."},sec={{t="Eine Grenze unter Belagerung",b="Zwerggiftnetzspinnen wimmeln im Unterholz neben der westlichen Straße von Westfall in den Dämmerwald. Unter dem dichten Blätterdach ersticken ihre Netze das Dickicht. Reisende und die ohnehin brüchigen Verteidigungslinien der Nachtwache sind in Gefahr."},{t="Die Last der Night Watch",b="Behüter Dodds unterhält fern von Dunkelhain ein kleines Lager und hat zu wenige Truppen, um die Grenze zu halten. Kommandantin Althea Schwarzhaupt kann keine Hilfe schicken, solange Untote und Worgen die Ortschaft bedrängen. Dodds hat Kameraden an die Spinnen verloren. Er fand sie kopfüber im Blätterdach hängend, vom Gift gelähmt, während es ihr Fleisch verflüssigte."}},faq={{q="Wer bietet diese Quest an?",a="Behüter Dodds, ein Mitglied der Nachtwache in einem kleinen Lager im Dämmerwald, bittet Reisende, die Spinnen zu beseitigen.",al={"questgeber","wer vergibt gefahr auf acht beinen","behüter dodds"}},{q="Warum kann sich die Nachtwache nicht selbst um die Spinnen kümmern?",a="Kommandantin Althea Schwarzhaupt hält ihre kleine Garnison nahe Dunkelhain, um die unerbittlichen Angriffe der Untoten abzuwehren. Dodds hat zu wenige Truppen, um die Nester an der Grenze anzugreifen und seinen Posten zu halten.",al={"warum hilfe nötig","warum abenteurer rufen","milizmangel dunkelhain"}},{q="Wo befinden sich diese Spinnen?",a="Zwerggiftnetzspinnen wimmeln in den westlichen Wäldern des Dämmerwalds, im Unterholz direkt neben der Hauptstraße von Westfall.",al={"spinnenstandort","wo sind zwerggiftnetzspinnen","spinnenwälder"}},{q="Was macht diese Spinnen für die Wache so gefährlich?",a="Die Spinnen sind zahlreich, und ihr Gift lähmt und löst Fleisch auf. Mitglieder der Nachtwache, die sich in ihren Netzen verfangen, hängen hilflos in den Ästen und sind leichte Beute.",al={"spinnengift","spinnenopfer"}},{q="Sind das die einzigen Spinnen im Dämmerwald?",a="Nein. Zwerggiftnetzspinnen sind die kleineren Jungtiere. Viel größere und tödlichere Spinnen leben tiefer in den Wäldern, wo sie Reisende bedrohen.",al={"andere spinnen im dämmerwald","spinnenarten","giftnetzspinnen"}},{q="Warum ist die Zahl der Insekten und Spinnen so stark gestiegen?",a="Magische Verderbnis liegt über dem Dämmerwald und hat seine heimische Tierwelt entstellt. Die Kreaturen sind aggressiver, größer und tödlicher geworden.",al={"warum so viele spinnen","dämmerwald verderbnis natur","ursprung der spinnen"}}},fx={["19037cd1"]={q="Warum will Behüter Dodds, dass die Spinnen dezimiert werden?",a="Pygmäengiftnetzspinnen haben die westliche Grenze von Dämmerwald übernommen, und The Nachtwache hat zu wenig Männer, um mit ihnen fertig zu werden. Behüter Dodds hat bereits mehrere seiner Männer an ihr Gift und ihre Netze verloren, und Kommandant Schwarzhaupt kann keine Soldaten so weit von Dunkelhain entbehren.",al={"warum pygmäengiftnetzspinnen töten","dodds spinnen beweggrund","warum will dodds das erledigt haben"}},["3807547d"]={q="Was sind die Pygmäengiftnetzspinnen?",a="Pygmäengiftnetzspinnen sind aggressiv territoriale Spinnentiere, die die westlichen Grenzgebiete von Dämmerwald befallen. Obwohl sie kleiner sind als die ausgewachsenen monströsen Spinnen tiefer im Wald, jagen sie in Schwärmen, verstricken unvorsichtige Reisende in Netznestern und produzieren ein starkes Gift, das in der Lage ist, das Fleisch ihrer Beute von innen heraus zu schmelzen.",al={"pygmäengiftnetzspinnen","wen jagen wir","spinnen westlicher dämmerwald"}}},fp="20,182,20.221.0,29.325.0,22.106.0,56.174.0,32.106.0,51.148.0,39.145.0,63.137.0"}
P.entries["quest:2458"] = {n="Undercover",s="Shenthul schickt einen vielversprechenden Schurken der Horde ins Schlickermoor, um einen Agenten bei der Venture Company zu treffen. Die Shattered Hand hat ein Jahr darauf verwendet, Zuchtmeister Fizzule auf ihrem Bohrgelände einzuschleusen, wo er ihre Pläne überwacht.",h="Shenthul schickt einen vielversprechenden Schurken der Horde ins Schlickermoor, um einen Agenten bei der...",kw={"brachland schurke","undercover","signalpistole","shattered hand","shenthul","das schlickermoor","zuchtmeister fizzule","venture company"},ang={["class:Rogue"]="Als Schurke der Horde geht Ihr von der Erkundung der Straßen zu vertrauensvollen Einsätzen im Feld über, bei denen Ihr Euch im Geheimen abstimmt.",["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie die Holzfällarbeiten und Bohrungen der Venture Company die Ländereien und Rohstoffe der Horde im Brachland bedrohen."},sec={{t="Ein Spion unter Profiteuren",b="Die Shattered Hand schützt Orgrimmars Interessen durch geheime Aufklärung und Meuchelmord. Ein Jahr lang arbeiteten ihre Mitglieder daran, einen Agenten bei der Venture Company einzuschleusen. Zuchtmeister Fizzule erlangte einen Posten an ihrem Bohraußenposten nördlich des Schlickermoors, unter den Söldnern des Unternehmens."},{t="Zeichen und Signale",b="Fizzule muss seinen Ruf der Härte wahren, um die Aufseher der Venture Company zufriedenzustellen. Ein unerwarteter Besucher könnte einen Angriff auslösen. Wenn Ihr seinen Turm erreicht, feuert in Sichtweite zwei Leuchtsignale aus der Signalpistole ab, nähert Euch leise und entbietet den geheimen Gruß der Shattered Hand. Dann kann Fizzule berichten, was er über die wachsenden Machenschaften des Unternehmens erfahren hat."}},faq={{q="Wer ist Zuchtmeister Fizzule?",a="Zuchtmeister Fizzule ist ein Agent der Shattered Hand, der nördlich des Schlickermoors bei der Venture Company eingeschleust wurde. Er verbrachte ein Jahr damit, unter ihren Söldnern Autorität zu gewinnen, während er ihre Arbeit überwachte und Informationen nach Orgrimmar schickte.",al={"fizzule","wer ist fizzule","zuchtmeister fizzule identität"}},{q="Warum greift Fizzule an, wenn Ihr ihm nicht die richtigen Signale gebt?",a="Fizzule wahrt das harte Auftreten, das von einem Zuchtmeister der Venture Company erwartet wird. Ohne das Signal aus zwei Leuchtsignalen und den Gruß der Shattered Hand hält er einen herannahenden Fremden für einen feindlichen Eindringling oder rivalisierenden Agenten und greift an, um seine Tarnung zu schützen.",al={"warum greift fizzule an","fizzule feindselig","fizzule tötet mich"}},{q="Wo befindet sich der Turm der Venture Company?",a="Der Turm der Venture Company überblickt ihr Bohrgelände nördlich des Schlickermoors, im nördlichen Brachland.",al={"fizzule standort","turm standort","wo ist der turm beim schlickermoor"}},{q="Warum spioniert die Horde die Venture Company aus?",a="Die Shattered Hand spioniert die Venture Company aus, weil deren rücksichtsloser Rohstoffabbau, Ausbeutung und Gewalt Kalimdor bedrohen. Jüngste Erkenntnisse deuteten auf ein großes Vorhaben im Brachland hin, also wandte sich Shenthul an seinen Kontaktmann.",al={"warum die venture company ausspionieren","venture company bedrohung"}},{q="Was geschieht nach der Kontaktaufnahme mit Fizzule?",a="Nachdem Ihr Kontakt aufgenommen habt, weist Fizzule Euch an, den nahen Turm der Venture Company zu betreten, seine Bewohner einschließlich Grand Foreman Puzik Gallywix zu töten und Zanzil's Altered Mixture an Euch zu nehmen, um Euch der Gilde gegenüber zu beweisen.",al={"wie weiter nach undercover","nach fizzule"}},{q="Was ist die Shattered Hand?",a="Die Shattered Hand ist ein Netzwerk aus Schurken, Spionen und Meuchelmördern mit Sitz in Orgrimmars Kluft der Schatten. Einst ein berüchtigter Klan auf Draenor, sammelt sie heute im Verborgenen Informationen für die Horde.",al={"shattered hand","wer ist die shattered hand"}}},fx={aa88dce8={q="Warum schickt Shenthul Euch, um Kontakt aufzunehmen, anstatt selbst zu gehen?",a="Shenthul ist ein Ausbilder, der Schurkenoperationen aus den Schatten von Orgrimmar koordiniert, während Zuchtmeister Fizzule tief im feindlichen Territorium im Schlickermoor eingebettet ist. Das Eindringen in eine aktive Basis von The Venture Co. erfordert einen wendigen Feldagenten, der an Wachen vorbeischlüpfen und einen Undercover-Agenten unbemerkt signalisieren kann, ohne die Aufmerksamkeit von Unternehmens-Söldnern zu erregen oder den gesamten Ring von The Shattered Hand zu gefährden.",al={"warum schickt ihr mich","warum braucht mich shenthul","warum geht er nicht selbst"}}},fp="10,218,22.282.0,17.353.0,26.220.0,58.236.0,43.102.0,47.223.0,47.216.1,27.190.0"}
P.entries["quest:2459"] = {n="Ferocitas der Traumfresser",s="In Dolanaar schickt Euch Tallonkai Flinkwurzel nach Norden, um einen von Gnarlpinefurbolgs gestohlenen Smaragd zurückzuholen. Ihr Anführer, Ferocitas der Traumfresser, trägt ihn um den Hals.",h="In Dolanaar schickt Euch Tallonkai Flinkwurzel nach Norden, um einen von Gnarlpinefurbolgs gestohlenen...",kw={"dolanaar","traumfresser","smaragdgrüner traumfänger","ferocitas","gnarlpinemystiker","sternenhauch","tallonkai flinkwurzel","tallonkais juwel","teldrassil"},ang={["class:Druid"]="Als Druide wisst Ihr, dass Traumfänger mächtige Instrumente sind, die mit dem Smaragdgrünen Traum verbunden sind. Ein verderbter Furbolg hat einen davon geschändet, und die Natur verlangt rasche Vergeltung.",["race:NightElf"]="Als Nachtelf, der Teldrassil verteidigt, erkennt Ihr die Tragik in der Verderbnis der Gnarlpinemystiker und ihrem Diebstahl heiliger Talismane. Die Gnarlpine waren einst Verbündete der Kaldorei."},sec={{t="Ein geschändetes Erbstück",b="Tallonkai Flinkwurzel war erleichtert, als sein Traumfänger aus der verdorbenen Wildnis zurückkehrte. Dann sah er dessen verheerenden Zustand. Das heilige Artefakt war geschändet und sein Smaragd aus der Mitte des geflochtenen Rahmens herausgebrochen worden.\n\nNachtelfen berichteten von Gnarlpinemystikern nördlich von Sternenhauch, die unter den Einfluss ihres Anführers, Ferocitas des Traumfressers, geraten waren. Er trug einen strahlend grünen Stein um den Hals. In Ferocitas' Klauen war das Juwel nutzlos und entweiht, also sandte Tallonkai Verteidiger aus, um es zurückzuholen."},{t="Die Läuterung der Mystiker",b="Die Gnarlpinefurbolgs im Norden Teldrassils waren einst friedliche Nachbarn. Verderbnis aus dem Weltbaum trieb sie in Raserei und Wahnsinn. Ihre Mystiker vollführten einst harmonische Naturrituale, doch nun schöpfen sie aus verzerrten magischen Energien. Ihr könnt Ferocitas erreichen, indem Ihr Euch durch die Mystiker kämpft, die seine Enklave im Wald bewachen. Bringt das Juwel zu Tallonkai zurück, damit er seinen Traumfänger vervollständigen und das Gleichgewicht der Wälder wiederherstellen kann."}},faq={{q="Wo finde ich Ferocitas den Traumfresser?",a="Ferocitas der Traumfresser wartet im Wald nördlich von Sternenhauch auf Teldrassil, inmitten verdorbener Gnarlpinemystiker und anderer Gefahren des Waldes.",al={"ferocitas standort","wo ist ferocitas","traumfresser finden"}},{q="Wer ist Ferocitas?",a="Ferocitas führt die Gnarlpinefurbolgs an und befehligt verdorbene Mystiker nördlich von Sternenhauch. Er nahm den Smaragd aus Tallonkai Flinkwurzels Traumfänger und machte daraus eine grobe Halskette.",al={"wer ist ferocitas","ferocitas geschichte","was ist der traumfresser"}},{q="Warum will Tallonkai Flinkwurzel das Juwel zurück?",a="Tallonkai Flinkwurzel will den Smaragd zurück, weil er die zentrale Kraftquelle seines Traumfängers ist. Ohne ihn lässt sich der Talisman weder reparieren, noch kann er die schützenden Energien des Smaragdgrünen Traums kanalisieren.",al={"warum will tallonkai das juwel","tallonkai juwel zweck"}},{q="Können die Gnarlpine die Magie des Smaragds überhaupt nutzen?",a="Nein. Tallonkai Flinkwurzel sagt, dass die Magie des Smaragds für Ferocitas und die Gnarlpinemystiker nutzlos ist. Sie begehrten ihn nur als leuchtendes Schmuckstück.",al={"können gnarlpine den traumfänger nutzen","nutzt ferocitas den smaragd"}},{q="Was geschieht nach dieser Quest?",a="Dies ist das letzte Kapitel einer zweiteiligen Questreihe, die mit „Smaragdgrüner Traumfänger“ begann. Bringt das Juwel zu Tallonkai in Dolanaar, dann kann er sein Erbstück reparieren.",al={"quest nach ferocitas","nächste quest traumfänger"}},{q="Warum sind die Gnarlpinemystiker feindselig?",a="Eine seltsame Verderbnis in den Ästen des neu gepflanzten Weltbaums hat große Teile von Teldrassils Tierwelt und seinen Furbolgstämmen befallen. Sie verdrehte den Gnarlpine den Verstand und machte sie angriffslustig.",al={"warum sind furbolgs wahnsinnig","gnarlpine corruption"}}},fx={["80c83c66"]={q="Wofür ist Tallonkais Juwel?",a="Der fehlende Smaragd ist der lebenswichtige Fokus des beschädigten Traumfängers von Tallonkai Flinkwurzel. Ohne ihn kann der Talisman nicht funktionieren, und er braucht den Stein intakt zurück, damit er den heiligen Schutz endlich reparieren kann.",al={"was ist tallonkais juwel","zweck tallonkais juwel","nutzen fehlender smaragd"}}},fp="25,167,18.501.0,19.429.0,42.150.0,17.193.0,49.195.0,51.141.0,30.163.0,38.188.0"}
P.entries["quest:246"] = {n="Einschätzung der Gefahr",s="Bei Seenhain muss Stellvertreter Feldon herausfinden, wie groß die Bedrohung durch die Gnolle geworden ist. Da die Garnison überlastet ist und Sturmwind Verstärkung zurückhält, bezahlt er Reisende dafür, die Rudel auszudünnen und ihre Stärke einzuschätzen.",h="Bei Seenhain muss Stellvertreter Feldon herausfinden, wie groß die Bedrohung durch die Gnolle geworden ist.",kw={"einschätzung","feldon","gnolle","seenhain","bastard","wilderer","aufklärung","rotkammgebirge","bedrohung"},ang={["class:Warrior"]="Stellvertreter Feldon fordert bewaffnete Aufklärung. Als Krieger dringt Ihr in befestigte Lager ein und zerschlagt die Vorhut der Gnolle.",["faction:Alliance"]="Das Rotkammgebirge zeigt, unter welchem Druck das Kernland der Allianz steht. Vernachlässigte Grenzsiedlungen heuern Helden an, um zu überleben, während die Hauptstadt wegsieht.",["race:Human"]="Als menschlicher Verteidiger liegt Euch der Schutz Seenhains persönlich am Herzen. Die Familien an der Grenze tragen die Folgen des politischen Stillstands in Burg Sturmwind."},sec={{t="Eine bedrängte Grenzregion",b="Kriegstrupps der Schwarzfelsorcs bedrohen Seenhain von den Höhen aus, während aggressive Gnolle durch die Täler streifen. Der Ort hat zu wenige Verteidiger für gewöhnliche Aufklärungspatrouillen. Als Berichte zeigten, dass Gnolle zur Grenze vordrangen, rief Stellvertreter Feldon Reisende zu Hilfe. Er bezahlt sie dafür, den Feind in der Wildnis auf die Probe zu stellen, und schont so Wachen, die der Ort nicht entbehren kann."},{t="Aufklärung mit Waffengewalt",b="Ihr erkundet die südliche Straße des Rotkammgebirges und greift die Lager der Bastarde der Rotkammgnolle und der Wilderer der Rotkammgnolle an. Jeder Kampf dezimiert die vorgeschobenen Späher der Gnolle und stört ihre Nachschublinien. Die Zusammenstöße zeigen, ob die Rudel verstreute Aasfresser sind oder eine organisierte Streitmacht, die Seenhain bedroht. Feldon kann Eure Erkenntnisse nutzen, um die Verteidigung des bedrängten Ortes zu planen."}},faq={{q="Warum entsendet Stellvertreter Feldon Abenteurer statt Stadtwachen?",a="Seenhains Garnison ist stark unterbesetzt. Sturmwind schickt keine Verstärkung, und feindliche Kräfte drängen aus mehreren Richtungen heran. Die Wachen können keine Soldaten für lange Patrouillen entlang der südlichen Straße entbehren.",al={"warum abenteurer anheuern","wo sind die wachen","wachenmangel in seenhain"}},{q="Wo befinden sich die Gnolle für diesen Auftrag?",a="Bastarde der Rotkammgnolle und Wilderer der Rotkammgnolle lagern entlang der südlichen Straße und in den niedrigen Ausläufern des Rotkammgebirges, südlich von Seenhain und nahe den Grenzpässen.",al={"wo sind bastarde der rotkammgnolle","gnollstandorte im rotkammgebirge","gnolle an der südlichen straße"}},{q="Welchen strategischen Zweck hat es, diese Gnolle zu dezimieren?",a="Die Kämpfe drängen Gnolle zurück, die zur Straße vorrücken, und stören ihre Nachschublinien. Außerdem erhält Feldon dadurch Erkenntnisse aus erster Hand über Größe, Bewaffnung und Disziplin der Rudel.",al={"warum gnolle töten","ziel der gefahreneinschätzung","verteidigung von seenhain"}},{q="Hilft Sturmwind gegen die Bedrohung durch die Gnolle?",a="Nein. Sturmwinds House of Nobles und der Regentschaftsrat verweigern abgelegenen Regionen wie dem Rotkammgebirge reguläre militärische Unterstützung. Örtliche Anführer, darunter Magistrat Solomon und Stellvertreter Feldon, sind auf bezahlte Söldner angewiesen.",al={"verstärkung aus sturmwind","warum hilft sturmwind nicht","sturmwinds armee in seenhain"}},{q="Was macht Stellvertreter Feldon mit Eurem Bericht?",a="Stellvertreter Feldon beurteilt die Stärke und Zähigkeit der Rudel. Er bestätigt, dass die südlichen Gnolle eine ernste militärische Gefahr darstellen und keine vereinzelte Bedrohung durch wilde Tiere. Dann weist er Euch an, anderen Anführern des Ortes beim Ausbau ihrer Verteidigung zu helfen.",al={"feldons reaktion","was folgt auf einschätzung der gefahr","bericht abgeben"}},{q="Wie hängt diese Aufgabe mit der vorherigen Quest zusammen?",a="Diese Aufgabe folgt auf Encroaching Gnolls. Nachdem Ihr die Garnison auf die Bewegungen der Gnolle aufmerksam gemacht hattet, schickte Feldon Euch auf eine Kampfpatrouille, um das Ausmaß des Einfalls zu ermitteln.",al={"zusammenhang der questreihe","folgequest von encroaching gnolls","vorausgesetzte quest"}}},fx={["6de7b21c"]={q="Wer sind die Gnolle aus dem Rotkammgebirge, die Ihr ausdünnen sollt?",a="Ihr werdet gegen die Bastarde der Rotkammgnolle und die Wilderer der Rotkammgnolle ausgesandt, die entlang der südlichen Straße ihr Lager aufgeschlagen haben. Diese wilden Gnolle sammeln sich direkt an der Lebensader der Stadt, belästigen Reisende, unterbinden Versorgungswege und rücken gefährlich nahe an Seenhain heran, während die Verteidigung der Stadt bereits bis an ihre Grenzen strapaziert ist.",al={"bastarde der rotkammgnolle wilderer","wer sind die gnolle im rotkammgebirge","bedrohung durch rotkammgnolle"}}},fp="20,219,19.344.0,23.347.0,63.207.0,46.158.0,54.175.0,47.214.0,44.228.0,46.160.0"}
P.entries["quest:2460"] = {n="Der Gruß der Zerschmetterten Hand",s="In Orgrimmars Kluft der Schatten lehrt Shenthul neu aufgenommene Schurken ein lautloses Zeichen. Die Shattered Hand nutzt es, um ihre Agenten im Einsatz sicher zu erkennen.",h="In Orgrimmars Kluft der Schatten lehrt Shenthul neu aufgenommene Schurken ein lautloses Zeichen.",kw={"die kluft der schatten","verdeckt","deep cover","orgrimmar","schurke","shattered hand","gruß der zerschmetterten hand","shenthul"},ang={["class:Rogue"]="Als Schurke der Horde lernt Ihr die geheimen Signale der Shattered Hand und werdet vom gewöhnlichen Beutelschneider zum vertrauenswürdigen Agenten von Orgrimmars Geheimdienstnetzwerk.",["faction:Horde"]="Als Mitglied der Horde dient Ihr unter Kriegshäuptling Thrall, der mit Ehre führt. Die Horde verlässt sich auch auf die geheimen Methoden der Shattered Hand, um Bedrohungen aufzuhalten, bevor sie die Oberfläche erreichen."},sec={{t="Zeichen und Schatten",b="Die Shattered Hand wirkt im Verborgenen von Orgrimmars Kluft der Schatten aus als Geheimdienst und Attentatsarm von Thralls Horde. Bei gefährlichen Geheimaufträgen können ihre Agenten keine militärischen Zeichen verwenden. Deshalb lehrt Shenthul neu aufgenommene Schurken den Gruß der Zerschmetterten Hand, eine lautlose Geste, an der Verbündete einander erkennen."},{t="Vorbereitung auf den Einsatz",b="Für Shenthuls Schurken ist das Erlernen des Grußes lebenswichtiges Agentenhandwerk, keine Zeremonie. Agenten, die in Gefahr entsandt werden oder rivalisierende Fraktionen unterwandern sollen, müssen Kontakte überprüfen, ohne Umstehende oder Zielpersonen zu alarmieren. Bevor Shenthul einem Agenten verdeckte Einsätze anvertraut, erwartet er, dass dieser die Geste ohne Zögern erkennt und erwidert."}},faq={{q="Welchen Zweck hat der Gruß der Zerschmetterten Hand?",a="Durch den Gruß der Zerschmetterten Hand erkennen Agenten der Shattered Hand einander bei verdeckten Einsätzen oder in feindlichem Gebiet, ohne Außenstehenden ihre Zugehörigkeit zu offenbaren.",al={"warum brauche ich den gruß","zweck des grußes der zerschmetterten hand","was bewirkt der gruß"}},{q="Wer lehrt den Gruß der Zerschmetterten Hand?",a="Shenthul lehrt den Gruß. Er ist ein Schurkenlehrer, der tief in Orgrimmars Kluft der Schatten stationiert ist.",al={"wer vergibt die quest","wer ist shenthul","wo lerne ich den gruß"}},{q="Welche Organisation verwendet diese Geste?",a="Die Shattered Hand verwendet die Geste. Die orkischen Schurken, Spione und Attentäter des Ordens dienen Thralls Horde aus den Schatten Orgrimmars heraus.",al={"shattered hand clan","wer sind die shattered hand","welche gilde verwendet das"}},{q="Warum muss der Gruß vor dem ersten Einsatz erlernt werden?",a="Agenten auf Infiltrationsmissionen nutzen den Gruß, um verdeckt arbeitende Verbündete zu kontaktieren, ohne deren Tarnung aufzudecken oder einen Feind für einen Verbündeten zu halten.",al={"warum den gruß üben","ist der gruß erforderlich"}},{q="Wo findet diese Ausbildung statt?",a="Die Ausbildung findet in der Kluft der Schatten statt, einem unterirdischen Viertel unter Orgrimmar, wo Schurken, Hexenmeister und andere Anwender verbotener Künste sich fern öffentlicher Beobachtung versammeln.",al={"ort des grußes","wo befindet sich shenthul"}},{q="Welcher Auftrag folgt, nachdem der Gruß gemeistert wurde?",a="Sobald Shenthul mit der Beherrschung des Grußes durch einen Agenten zufrieden ist, teilt er ihn für verdeckte Operationen ein. Der Auftrag prüft seine Fähigkeit, mithilfe des Signals Agenten im Einsatz zu kontaktieren.",al={"what comes next","nächste quest nach dem gruß","deep cover quest"}}},fp="20,157,17.315.0,25.325.0,44.147.0,33.101.0,36.132.0,65.138.0,36.186.0,51.179.0"}
P.entries["quest:247"] = {n="Die Jagd ist abgeschlossen",s="In Eschental stellt sich ein Champion der Horde drei legendären Raubtieren. Ursangous, Shadumbra und Sharptalon prüfen Stärke, Hartnäckigkeit und das Geschick eines Jägers in der Wildnis.",h="In Eschental stellt sich ein Champion der Horde drei legendären Raubtieren.",kw={"eschental","bestien","jagd","raubtier","senani","shadumbra","sharptalon","thunderheart","trophäe","ursangous"},ang={["class:Hunter"]="Als Jäger erprobt Ihr Eure Fährtenkunde und Treffsicherheit an drei der größten Raubtiere Eschentals. Eure Instinkte müssen denen der wilden Bestien ebenbürtig sein.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, den Stützpunkt Eures Volkes in Eschental zu sichern, einem gefährlichen Wald voller Raubtiere und Schildwachen der Allianz.",["race:Tauren"]="Als Tauren ehrt Ihr eine althergebrachte Prüfung des Respekts, des Gleichgewichts und des Ahnenstolzes, indem Ihr Ursangous, Shadumbra und Sharptalon jagt."},sec={{t="Der Beweis eines Jägers",b="Senani Donnerherz prüft Reisende bei den Streitkräften der Horde in Eschental. Ihre Jagd prüft die Treue zum Kriegshäuptling und verlangt, dass ein Jäger das Überleben in der Wildnis versteht. Drei legendäre Raubtiere sind ihre Beute: Ursangous der Bär, Shadumbra die Katze und Sharptalon der wilde Hippogryph. Ein Jäger muss alle drei erlegen und ihre Trophäen sichern, um zu beweisen, dass wahres Jägerblut in seinen Adern fließt."},{t="Die Ahnen ehren",b="Für die Tauren ist die Jagd heilig. Sie ehrt Gleichgewicht und Respekt, selbst an einer aktiven Kriegsfront. Indem ein Jäger Eschentals größte Schrecken bezwingt, ehrt er die Geister des Landes und verdient sich Thunderhearts Ahnensegen. Eine förmliche Belobigung und ein Zeichen der Gunst markieren das Ende der Jagd, und der Ruf des Champions verbreitet sich im Wald."}},faq={{q="Wer vergibt diese Quest und wo ist diese Person zu finden?",a="Senani Donnerherz, eine Jägerin der Tauren, bietet die Jagd bei den Streitkräften der Horde in Eschental an.",al={"questgeber","wo abgeben","senani donnerherz standort"}},{q="Welche Anforderungen müssen erfüllt werden, um die Jagd abzuschließen?",a="Ihr müsst drei mächtige Raubtiere erlegen und Beweise für ihren Tod bringen: Ursangous's Paw, Shadumbra's Head und Sharptalon's Claw.",al={"welche bestien töten","voraussetzungen","welche tiere"}},{q="Warum will Senani Donnerherz diese Bestien töten lassen?",a="Die Jagd prüft Stärke und Hartnäckigkeit. Wer solch furchterregende Bestien erlegt, beweist, dass er das Herz und die Instinkte eines Raubtiers besitzt, das in Eschentals gefährlicher Wildnis überleben kann.",al={"warum sie jagen","senanis beweggrund","zweck der jagd"}},{q="Welche kulturelle Bedeutung hat die Jagd für die Horde?",a="Für Tauren wie Senani Donnerherz ist es eine ehrenvolle Tradition, sich mit mächtigen Bestien zu messen. Sie ehrt die Geister und Ahnen und zeigt die Beherrschung der Wildnis, ohne durch Leichtsinn Schande auf sich zu laden.",al={"hintergrund der taurenjagd","kulturelle bedeutung","warum jagen tauren bestien"}},{q="Wird diese Prüfung von der gesamten Horde anerkannt?",a="Ja. Mit dem Abschluss der Jagd geltet Ihr unter den Streitkräften der Horde in Eschental als bewährter Jäger. Ihr verdient Euch den Segen der Ahnen und den Respekt Eurer Gefährten.",al={"anerkennung der horde","ist es offiziell","belobigung der horde"}},{q="Welche drei Bestien sind das Ziel der Jagd in Eschental?",a="Die drei Ziele sind Ursangous der große Bär, Shadumbra der Nachtsäbler und Sharptalon der Hippogryph.",al={"die drei bestien","jagdziele","tiere mit namen"}}},fx={ded238b8={q="Welche Bestien musstet Ihr für die The Eschental Hunt erlegen?",a="Die Prüfung verlangte von Euch, drei der grausamsten Raubtiere vom Eschental aufzuspüren und zu erlegen: den uralten Bären Ursangous, den schwer fassbaren Nachtsäbler Shadumbra und den wilden Hippogryphen Scharfklaue. Diese wilden Bestien beherrschten das Blätterdach und das Dickicht des Waldes, stellten eine ernste Bedrohung für Reisende dar und dienten als ultimativer Test für Stärke, Geduld und Jagdgeschick in der ungezähmten Wildnis.",al={"welche bestien habe ich getötet","ziele ashenvale hunt","welche bestien jagd abgeschlossen"}}},fp="18,159,16.377.0,22.343.0,49.90.0,47.126.0,53.178.0,59.204.0,45.153.0,54.104.0"}
P.entries["quest:2478"] = {n="Mission: möglich, aber nicht sehr wahrscheinlich",s="Im nördlichen Brachland infiltrieren Schurken der Horde einen Außenposten der Venture Company, um ein starkes Gebräu für die Shattered Hand zu stehlen. Ihr Auftrag stellt Heimlichkeit, Diebeskunst und Kampffertigkeiten auf die Probe.",h="Im nördlichen Brachland infiltrieren Schurken der Horde einen Außenposten der Venture Company, um ein starkes...",kw={"brachland","fizzule","schlösserknacken","gifte","puzik gallywix","shattered hand","shenthul","silixiz","das schlickermoor","zanzil"},ang={["class:Rogue"]="Als Schurke lernt Ihr im Einsatz, Schlösser zu knacken, Taschen zu bestehlen und Schwachstellen auszunutzen. Diese Fertigkeiten eröffnen Euch den Weg zum tödlichen Handwerk und den Giften der Shattered Hand.",["faction:Horde"]="Die Shattered Hand wirkt in Orgrimmars Schatten und beobachtet gefährliche Eindringlinge wie die Venture Company, während diese das Brachland ausbeuten."},sec={{t="Infiltration der Venture Co.",b="Nördlich der Bohrinseln im Schlickermoor unterhält die Venture Company einen abgelegenen Bohrturm. Zuchtmeister Fizzule, ein Agent der Shattered Hand, der sich als Aufseher der Venture Company ausgibt, schickt Schurken los, Unterweltmethoden anzuwenden, statt offen anzugreifen. Er bittet sie, Foreman Silixiz den Schlüssel aus der Tasche zu stehlen und ihn für ihn aufzubewahren. Dann steigen sie an Arbeitern und Wachen vorbei hinauf, die durch die Experimente im Turm verändert wurden."},{t="Eine chemische Katastrophe",b="Zanzils veränderte Mischung hat die Bewohner des Turms verändert. Ihr Gift schwächt die Wachen und macht sie anfällig für schnelle Schläge, blutende Wunden und plötzliche Hinterhalte. Die Substanz hat die Anlage außerdem instabil gemacht. Ganz oben bewacht Grand Foreman Puzik Gallywix eine Schließkassette mit dem Gebräu."},{t="Der Preis der Pflicht",b="Die Dämpfe der veränderten Mischung entweichen, wenn Ihr Gallywixs Schließkassette öffnet. Sie brechen Eure Verstohlenheit, rauben Euch Lebenskraft und hinterlassen ein schwächendes Leiden, das lange anhält. Zurück in Orgrimmar nimmt Shenthul, der Mentor der Shattered Hand, Gallywixs Kopf und die chemische Probe entgegen. Er beklagt Fizzules enttarnte Stellung und schickt den sterbenden Agenten los, ein Heilmittel zu suchen."}},faq={{q="Wo steht der Turm der Venture Co.?",a="Der Turm der Venture Company steht im nördlichen Brachland, gleich nördlich der Bohranlage im Schlickermoor. Feindselige Arbeiter der Venture Company umgeben ihn, und Zuchtmeister Fizzule versteckt sich bei einem Baum gleich östlich davon.",al={"venture co. turm standort","wo steht gallywixs turm","schlickermoor turm"}},{q="Wie erhaltet Ihr den Schlüssel zum Turm?",a="Foreman Silixiz trägt den Turmschlüssel bei sich und streift draußen am Fuß des Turms umher. Stehlt ihn ihm aus der Tasche, während Ihr verborgen seid. Ihn zu töten bringt Euch den Schlüssel nicht ein.",al={"silixiz turmschlüssel","wie den turmschlüssel bekommen","wo ist der schlüssel"}},{q="Was ist Zanzils veränderte Mischung?",a="Zanzils veränderte Mischung ist ein alchemistisches Gebräu nach den Rezepturen des berüchtigten Trollhexendoktors Zanzil. Die Venture Company beschaffte es, und seine instabilen Dämpfe vergifteten die Belegschaft des Turms. Sie machten die Arbeiter kränklich, mutiert und anfällig für die Kampfkünste der Schurken.",al={"zanzils mischung","was ist das gift","veränderte mischung"}},{q="Warum kann ich mich nach dem Öffnen der Schließkassette nicht mehr verstohlen bewegen?",a="Beim Öffnen von Gallywixs Schließkassette werden konzentrierte Dämpfe der veränderten Mischung freigesetzt. Die Vergiftung hält tagelang an, schwächt Eure Attribute und bricht Eure Verstohlenheit, bis ein erfahrener Apotheker sie heilt.",al={"touch of zanzil","vergiftet nach truhe","keine verstohlenheit schurkenquest","sieben tage gift"}},{q="Wer ist Zuchtmeister Fizzule?",a="Zuchtmeister Fizzule ist ein tief eingeschleuster Agent der Shattered Hand, der Schurkengilde der Horde. Der Zwerg der Dark Iron gibt sich im Brachland als skrupelloser Zuchtmeister der Venture Company aus. Er weist Rekruten an, die Einrichtungen der Gesellschaft zu sabotieren, ohne sich selbst zu enttarnen.",al={"fizzule","wer gab diese quest","fizzules geschichte"}},{q="Wer ist Grand Foreman Puzik Gallywix?",a="Grand Foreman Puzik Gallywix ist der Goblinaufseher, der den Turm der Venture Company nahe dem Schlickermoor befehligt. Er bewacht den gestohlenen Vorrat von Zanzils Gebräu, bis Agenten der Shattered Hand ihn töten.",al={"puzik gallywix","ist gallywix im brachland","foreman gallywix"}}},fx={["2a5cd36a"]={q="Warum will Zuchtmeister Fizzule, dass der Turm von The Venture Co. zerstört wird?",a="Während er tief undercover für The Shattered Hand arbeitet, hat Zuchtmeister Fizzule beobachtet, wie The Venture Company mit einem flüchtigen, mutierenden Gift experimentiert. Jetzt, da die vergiftete Mischung jeden im Turm korrumpiert und geschwächt hat, sieht Fizzule eine Gelegenheit, die gesamte Operation zu eliminieren, die Führung von Obervorarbeiter Gallywix zu zerschlagen und die tödliche Verbindung für Orgrimmar zu sichern, bevor sie sich unkontrolliert ausbreitet.",al={"fizzule beweggrund","warum gallywix fizzule töten","warum venture co turm angreifen"}},["53be2ad7"]={q="Wozu wird Silixiz' Turmschlüssel verwendet?",a="Vorarbeiter Silixiz trägt den Schlüssel außerhalb des Turms. Fizzule bittet Euch, ihn zu stehlen und aufzubewahren, da er ihn möglicherweise später benötigt; ihn zu bergen ist eines der Missionsziele.",al={"silixiz turmschlüssel","zweck des turmschlüssels","warum turmschlüssel stehlen"}},["78e0c22c"]={q="Wozu dient der Behälter mit Zanzils veränderter Mixtur?",a="Eingeschlossen auf der Spitze des Turms in Gallywix' persönlicher Truhe enthält dieser verbleibende Vorrat das seltsame, schwächende Gebräu, das aus Zanzils Formeln stammt. The Shattered Hand verlangt, dass Ihr die Mixtur bergt, damit ihre toxischen und mutierenden Eigenschaften von den Schurkenmeistern in Orgrimmar untersucht – und sicher eingedämmt – werden können.",al={"behälter mit zanzils veränderter mixtur","zanzil mixtur behälter","warum mixtur nehmen"}},["07291131"]={q="Warum werdet Ihr gegen Großvorarbeiter Puzik Gallywix und die Turmarbeiter ausgesandt?",a="Ihr wurdet ausgesandt, um das korrumpierte Personal der Venture Company zu säubern, das den Turm im nördlichen Brachland bewohnt. Unter Großvorarbeiter Puzik Gallywix hat diese Mannschaft Zanzils toxische Verbindung falsch gehandhabt, wodurch die Drohnen in mutierte Monstrositäten verwandelt wurden und die Region gefährdeten. Durch die Eliminierung der Wachposten, Patrouillen, Drohnen und Gallywix selbst beseitigt Ihr ihren vordringenden industriellen Stützpunkt.",al={"gegen wen kämpft ihr im turm","venture co turm ziele","warum gallywix töten"}},fa60081f={q="Warum braucht Fizzule Euch, anstatt sich selbst um den Turm zu kümmern?",a="Fizzule wahrt eine heikle Identität als tief eingeschleuster Aufseher der Venture Company. Würde er dabei erwischt, wie er offen in den Turm eindringt, Aufseher erschlägt oder Gallywix' Schließfach plündert, würde seine Tarnung sofort auffliegen. Als externer Agent von The Shattered Hand besitzt Ihr die tödliche Heimlichkeit, die erforderlich ist, um die Anlage zu säubern, ohne seine Rolle preiszugeben.",al={"warum ich fizzule","warum braucht fizzule hilfe","warum säubert fizzule den turm nicht selbst"}},f260e633={q="Warum will Shenthul Gallywixs Kopf?",a="Das Abtrennen des Kopfes von Grand Foreman Puzik Gallywix dient als unwiderlegbarer Beweis für seinen Tod und die Zerschlagung der Turmhierarchie der Venture Company. Ihn Shenthul in der Kluft der Schatten vorzulegen, bestätigt, dass der oberste Aufseher hinter den regionalen Machenschaften endgültig ausgeschaltet wurde.",al={"gallywixs kopf zweck","warum gallywixs kopf nehmen","wozu dient gallywixs kopf"}}},fp="34,166,31.391.0,22.298.1,17.370.2,39.210.0,39.156.0,33.280.0,53.210.1,26.259.0,36.199.0"}
P.entries["quest:2479"] = {n="Hinotts Hilfe",s="In Orgrimmar suchen vergiftete Schurken Hilfe, bevor Zanzils Mixtur ihnen das Leben nimmt. Das Gift stammt von einer Infiltration im Brachland. Serge Hinott in Tarrens Mühle kann ein Heilmittel bereitstellen und Schurken lehren, Gifte zu brauen.",h="In Orgrimmar suchen vergiftete Schurken Hilfe, bevor Zanzils Mixtur ihnen das Leben nimmt.",kw={"vorgebirge des hügellands","hinotts hilfe","schurken giftquest","serge hinott","shenthul","tarrens mühle","unterstadt zeppelin","zanzil","zanzils mixtur"},ang={["class:Rogue"]="Als Schurke stellt Ihr Euch einem Übergangsritus, der Eure Ausdauer prüft und Euch den Weg zur Herstellung eigener Gifte eröffnet.",["faction:Horde"]="Als Mitglied der Horde erlebt Ihr die praktische Zusammenarbeit zwischen den Schurken der Orcs und Trolle aus Kalimdor und den alchemiekundigen Verlassenen in Lordaeron."},sec={{t="Eine giftige Notlage",b="Bei Eurer Infiltration des Turms der Venture Company nördlich vom Schlickermoor wurdet Ihr durch Zanzils veränderte Mixtur vergiftet. Sie trübt Eure Reflexe und bedroht Euer Leben. Shenthul, der Schurkenlehrer in Orgrimmar, weiß, dass örtliche Heilmittel nicht helfen können. Deshalb schickt er Euch zur Behandlung über das Meer in die Östlichen Königreiche."},{t="Reise nach Tarrens Mühle",b="Eure Suche nach einem Heilmittel führt nach Süden durch Lordaeron nach Tarrens Mühle, einem Dorf im Vorgebirge des Hügellands. Serge Hinott lebt dort als Apotheker und ist von hochgiftigen Gebräuen fasziniert. Gewöhnliche Heiler schrecken vor Zanzils Gift zurück, doch Hinott begegnet der tödlichen Verbindung mit fachlicher Begeisterung. Er kann das üble Gemisch analysieren und würdige Schurken lehren, ihre eigenen Gifte zu brauen."}},faq={{q="Warum muss ich Serge Hinott aufsuchen?",a="Serge Hinott ist ein Apotheker in Tarrens Mühle, der sich auf seltene Gifte und ihre Gegenmittel spezialisiert hat. Gewöhnliche Heiler können Zanzils veränderte Mixtur nicht aus Eurem Körper entfernen, doch Hinott kann sie analysieren, Euer Leben retten und Euch die Giftmischerei lehren.",al={"warum hinott","wer heilt die vergiftung","serge hinotts rolle"}},{q="Wo liegt Tarrens Mühle?",a="Tarrens Mühle ist eine Siedlung der Verlassenen im nördlichen Vorgebirge des Hügellands. Nehmt von Orgrimmar aus den Zeppelin nach Unterstadt in Tirisfal, reist nach Süden durch den Silberwald und folgt dann der Straße nach Osten nach Hillsbrad.",al={"tarrens mühle lage","weg nach tarrens mühle","wo ist hinott"}},{q="Wie wurde ich überhaupt vergiftet?",a="Ihr wurdet während Mission: Possible But Not Probable am Turm der Venture Company nördlich vom Schlickermoor im Brachland infiziert. Beim Öffnen der Hochsicherheitstruhe wurdet Ihr Zanzils veränderter Mixtur ausgesetzt und habt Euch ein anhaltendes, schwächendes Leiden zugezogen.",al={"wie zanzils gift bekommen","mission possible gift","warum vergiftet"}},{q="Was geschieht, nachdem Serge Hinott die Probe erhalten hat?",a="Nachdem Serge Hinott die Probe erhalten hat, untersucht er ihre Eigenschaften und bereitet ein Gegengift vor, um Euren Körper zu entgiften. Sobald er das Gift neutralisiert hat, gibt er sein Wissen weiter, damit Schurken lernen können, ihre eigenen Gifte zu brauen und anzuwenden.",al={"hinott folgequest","wird die vergiftung geheilt","nach hinotts hilfe"}},{q="Wer ist Shenthul und warum hat er mich fortgeschickt?",a="Shenthul ist der Schurkenlehrer der Shattered Hand in der Kluft der Schatten in Orgrimmar. Er beaufsichtigte Eure Geschicklichkeitsprüfung im Brachland und erkannte, dass Zanzils Gebräu die Heilkundigen von Orgrimmar überforderte. Deshalb schickte er Euch zu einem Spezialisten in Hillsbrad.",al={"wer ist shenthul","shenthul orgrimmar","warum vom lehrer fortgeschickt"}},{q="Kann eine andere Klasse diese Quest abschließen?",a="Nein. Diese Ausbildung gehört zur Tradition der Schurken und vermittelt die Grundlagen des Brauens von Giften und Heilmitteln.",al={"quest nur für schurken","können krieger hinotts hilfe abschließen"}}},fp="19,214,19.312.0,22.372.0,34.221.0,29.226.0,42.256.0,52.221.1,44.250.0,40.108.0"}
P.entries["quest:248"] = {n="Weitere Beobachtungen",s="Theocritus beobachtet das östliche Rotkammgebirge von Elwynn aus durch eine verzauberte Verbindung. Er sucht den Grund für den Konflikt zwischen Morganth und den Schwarzfelsorcs in der Burg Steinwacht und schickt Euch, die Glyphe von Azora im nahen Wachturm anzubringen.",h="Theocritus beobachtet das östliche Rotkammgebirge von Elwynn aus durch eine verzauberte Verbindung.",kw={"leerer krug","glyphe von azora","weitere beobachtungen","morganth","old lion statue","steinwacht","burg steinwacht","theocritus","der turm von ilgalar"},ang={["class:Mage"]="Theocritus nutzt die Glyphe von Azora für Spähmagie über große Entfernungen und zeigt damit, wie der Magier von Azora feindliche Gebiete durch Magie überwacht.",["faction:Alliance"]="Die Burg Steinwacht bleibt die wichtigste Festung des Schwarzfelsklans im Rotkammgebirge. Mehr über seinen Konflikt mit Morganth zu erfahren, ist entscheidend für die Verteidigung von Seenhain."},sec={{t="Zwist im Rotkammgebirge",b="Von seinem Sanktum im Wald von Elwynn aus beobachtet Theocritus das östliche Rotkammgebirge mit Spähmagie. Als er den Turm von Ilgalar untersucht, entdeckt er einen Konflikt zwischen Morganth, einem abtrünnigen menschlichen Hexenmeister, und den Schwarzfelsorcs, die sich in der Burg Steinwacht verschanzt haben. Beide feindseligen Fraktionen sollten vereint gegen das Königreich Sturmwind stehen, doch sie kämpfen um eine unbekannte Beute. Theocritus greift ein, bevor ihr Konflikt das Gleichgewicht verschiebt."},{t="Das Auge auf Steinwacht",b="Theocritus benötigt einen zweiten magischen Ankerpunkt, um die Verteidigung der Burg Steinwacht zu durchdringen. Deshalb schickt er Euch, den intakten Wachturm neben der zerstörten Festung zu erklimmen. Zwischen dem Gerümpel der Garnison bietet ein leerer Krug, den orkische Wachen weggeworfen haben, ein alltägliches Versteck. Befestigt die Glyphe von Azora darin, und Theocritus kann telepathisch die Gedanken in Steinwacht durchsuchen, um zu erfahren, was Morganth und die Schwarzfelsorcs entzweit hat."}},faq={{q="Wer schickt mich auf diese Mission?",a="Theocritus, der Magier von Azora, spricht durch die Old Lion Statue im Rotkammgebirge zu Euch, nachdem Ihr seine vorherige Aufgabe abgeschlossen habt.",al={"wer gibt die quest","questgeber","old lion statue"}},{q="Warum späht Theocritus die Burg Steinwacht aus?",a="Theocritus hat offene Feindseligkeiten zwischen Morganth, dem abtrünnigen dunklen Zauberer im Turm von Ilgalar, und den Schwarzfelsorcs entdeckt, die die Burg Steinwacht besetzen. Er will herausfinden, was ihren Konflikt ausgelöst hat.",al={"warum orcs ausspähen","theocritus absicht","warum steinwacht"}},{q="Wo befindet sich der Behälter?",a="Der leere Krug steht auf Fässern ganz oben im intakten Wachturm neben dem Haupteingang der Burg Steinwacht.",al={"leerer krug fundort","wo glyphe anbringen","wo ist der wachturm"}},{q="Was bewirkt die Glyphe von Azora?",a="Die Glyphe von Azora ist ein magischer Fokus für Spähmagie und Weissagung. Sie lässt Theocritus die Umgebung aus der Ferne überwachen und in die Gedanken der Schwarzfelsorcs im Inneren der Burg eindringen.",al={"glyphe von azora zweck","was bewirkt die glyphe"}},{q="Was folgt nach dem Anbringen der Glyphe?",a="Sobald Theocritus den Ursprung des Konflikts durch Weissagung ergründet hat, schickt er Euch, Morganth im Turm von Ilgalar zu jagen und seinen Schattenanhänger zu holen.",al={"nächste quest","was passiert danach","weitere beobachtungen folgequest"}},{q="Warum einen leeren Krug verwenden?",a="Eine magische Spionagerune braucht ein unauffälliges Gefäß, damit Wachen sie nicht entdecken oder zerstören. Der übel riechende Schnapskrug, der auf den Fässern zurückgelassen wurde, bietet ein ideales Versteck.",al={"warum der krug","leerer krug hintergrund"}}},fx={["3912e7be"]={q="Wen bespioniere ich in Burg Steinwacht?",a="Ihr spioniert die Schwarzfelsorks aus, die Burg Steinwacht besetzt haben. Von seinem Aussichtspunkt aus hat der Magier Theocritus Zwietracht zwischen diesen feindseligen Orks und dem dunklen Zauberer Morganth im Turm von Ilgalar ausgemacht. Das Platzieren der Glyphe erlaubt es dem Magier, die Gedanken innerhalb von Burg Steinwacht zu erforschen, um die wahre Ursache dieser Reibereien aufzudecken.",al={"wer ist in burg steinwacht","burg steinwacht ziel","looking further ziel"}},["6347ef38"]={q="Warum benötigt Theocritus einen Abenteurer, um die Glyphe zu platzieren?",a="Theocritus ist an den Turm von Azora gebunden und kanalisiert seine Magie durch verzauberte Relikte wie die Statue des alten Löwen, um Bedrohungen im gesamten Rotkammgebirge zu überwachen. Burg Steinwacht wimmelt von gefährlichen Schwarzfelsorks, und das Eindringen in die Festung erfordert jemanden, der sich unsichtbar zum Turm durchkämpfen kann, anstatt einen einsamen, verletzlichen Magier, der seinen Posten verlässt.",al={"warum werde ich geschickt looking further","warum tut theocritus es nicht","warum ich burg steinwacht"}}},fp="15,241,18.418.0,21.425.1,29.133.0,44.201.0,31.114.0,32.182.0,38.141.1,21.170.0"}
P.entries["quest:2480"] = {n="Hinotts Hilfe",s="In Tarrens Mühle untersucht Serge Hinott das Gift, das den Geist eines Horde-Schurken trübt, und bereitet ein Heilmittel vor.",h="In Tarrens Mühle untersucht Serge Hinott das Gift, das den Geist eines Horde-Schurken trübt, und bereitet ein...",kw={"gegengift","heilmittel","hillsbrad","hinott","gifte","schurkenquest","serge hinott","tarrens mühle","zanzil"},ang={["class:Rogue"]="Als Schurke werdet Ihr von dem Leiden aus Eurer Aufnahmeprüfung geheilt und lernt, taktische Gifte herzustellen.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr von der Alchemie der Verlassenen lernen, die Dschungeltrolltoxine in Wissen für den Einsatz verwandelt.",["race:Undead"]="Als Untoter erlebt Ihr Apotheker Hinotts nüchterne Bewunderung für kunstfertig hergestelltes Gift, ganz gleich, woher es stammt."},sec={{t="Ein giftiges Meisterwerk",b="Eure Schwierigkeiten begannen mit einem Auftrag im Brachland. Nun werdet Ihr nach Norden nach Tarrens Mühle geschickt, während ein Toxin Euren Geist trübt. Serge Hinott, ein Chemiker der Verlassenen, untersucht das Gift von Zanzil, einem verbannten Dschungeltroll. Die Identität und die Sippe des Trolls bedeuten Hinott wenig. Er bewundert die bösartige Wirkung des Gebräus und will dessen Wirkungsweise verstehen, bevor er ein Gegengift herstellt."},{t="Gegengift und Handwerk",b="Serge Hinott braucht Zeit, um die Wirkstoffe des Gifts zu isolieren. Sein Heilmittel hält den schleichenden Wahnsinn auf, doch wie er sagt, bleibt der Gestank. Sobald das Gift Euch nicht mehr schwächt, teilt Hinott mit Euch, was er aus Zanzils Werk gelernt hat. Mit diesem Wissen könnt Ihr eigene taktische Gifte herstellen."}},faq={{q="Was geschieht während Hinotts Hilfe?",a="Wartet einige Augenblicke in Tarrens Mühle, während Serge Hinott das Gegengift zubereitet. Sobald es fertig ist, sprecht mit ihm, um das Heilmittel einzunehmen und Zanzils Gift zu beseitigen.",al={"was ist hier zu tun","hinotts hilfe anleitung","wie die quest abschließen"}},{q="Wer ist Serge Hinott?",a="Serge Hinott ist ein Alchemist und Giftexperte der Verlassenen in Tarrens Mühle im Vorgebirge des Hügellands. Er hilft Horde-Schurken, ungewöhnliche Leiden zu heilen und die Herstellung von Gift zu erlernen.",al={"serge hinott hintergrund","wer ist hinott","tarrens mühle apotheker"}},{q="Warum ist Serge Hinott von dem Gift beeindruckt?",a="Hinott bewundert die Kunstfertigkeit hinter Zanzils Rezeptur, die schleichenden Wahnsinn und körperliche Schwäche hervorruft. Er arbeitet daran, ihre Wirkung aufzuhalten, lobt jedoch das Können hinter dem zerstörerischen Gebräu.",al={"zanzils gift reaktion","warum gefällt hinott das gift"}},{q="Was hat es mit dem anhaltenden Geruch auf sich, den Hinott erwähnt?",a="Zanzils Mischung hinterlässt einen stechenden, widerlichen Geruch in den Poren des Opfers. Hinotts Gegengift hält das Gift auf und klärt den Geist, doch der Gestank bleibt noch eine Weile.",al={"warum stinke ich","wahnsinn geruch","quest geruch"}},{q="Welche Belohnung gibt es für den Abschluss dieser Quest?",a="Das Heilmittel beseitigt das anhaltende Leiden aus Eurer Schurkenausbildung und ermöglicht Euch, Rogue Poisons zu erlernen, damit Ihr schwächende Beschichtungen brauen könnt.",al={"was bekommen schurken","hinotts hilfe belohnung"}},{q="Wo wird diese Quest abgegeben?",a="Ihr trefft Serge Hinott in Tarrens Mühle im nördlichen Vorgebirge des Hügellands. Dort beginnt und vollendet er die Arbeit.",al={"wo ist hinott","abgabeort"}}},fp="19,100,19.369.0,26.295.1,40.154.0,20.172.0,44.181.0,44.166.0,45.147.0,30.113.0"}
P.entries["quest:249"] = {n="Morganth",s="Im Rotkammgebirge jagt Morganth der Sichel von Elune nach, während Theocritus ihn aus der Ferne beobachtet.",h="Im Rotkammgebirge jagt Morganth der Sichel von Elune nach, während Theocritus ihn aus der Ferne beobachtet.",kw={"elwynn","morganth","schattenanhänger","rotkammgebirge","sichel von elune","theocritus","turm von azora","der turm von ilgalar"},ang={["class:Mage"]="Als Magier folgt Ihr der gewissenhaften, gelehrten Tradition von Theocritus. Menschliche Magier halten von hohen Türmen aus Wache, um das Reich vor abtrünnigen Zauberwirkern zu schützen.",["class:Warlock"]="Als Hexenmeister kennt Ihr die Gefahr ungezügelten Strebens nach Teufels- und Schattenmacht. Wer nach Relikten wie der Sichel von Elune greift, beschwört rasche Vernichtung herauf.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, Sturmwinds ungeschützte Ostgrenzen zu verteidigen. Morganth zu besiegen, bewahrt das Rotkammgebirge davor, dunkler Zauberei anheimzufallen.",["race:NightElf"]="Als Nachtelf sollten Euch Gerüchte über die Sichel von Elune in Menschenhand beunruhigen. Ihr Name berührt heilige und unberechenbare Mysterien der kaldorei."},sec={{t="Ein Beobachter jenseits der Grenze",b="Vom Turm von Azora im östlichen Wald von Elwynn beobachtet Theocritus mit Fernsichtzaubern die zerklüfteten Felsen des Rotkammgebirges. Dort sieht er Morganth, einen Hexenmeister im Turm von Ilgalar, der nach der Sichel von Elune sucht. Aus Furcht, Morganth könnte sie bald an sich bringen, bittet Theocritus Champions der Allianz, ihn aufzuhalten, bevor Sturmwind bedroht wird."},{t="Sturm auf den Turm",b="Der Turm von Ilgalar erhebt sich über dem Becken des Rotkammgebirges, wo Gnolle umherstreifen und arkane Energien seine Hallen verzerren. Morganth wartet an der Spitze des Turms, setzt Shadow Magic ein und bewacht seine Forschungen. Ihr steigt durch feindliches Gebiet hinauf, um ihm direkt gegenüberzutreten. Bringt seinen Schattenanhänger als Beweis zurück, dass der Turm gefallen und die Bedrohung gebannt ist."},{t="Der bleibende Schatten der Sichel",b="Morganths Niederlage beseitigt eine unmittelbare Bedrohung für Sturmwind, doch seine Suche nach der Sichel von Elune zeigt, wie weit die düstere Legende des Artefakts reicht. Theocritus ist erleichtert, als er den Schattenanhänger erhält. Der Verbleib der uralten Sichel und das Unheil, das sie bringen könnte, bleiben in den umliegenden Provinzen unbekannt."}},faq={{q="Wer ist Morganth?",a="Morganth ist ein mächtiger abtrünniger Hexenmeister, der an der Spitze des Turms von Ilgalar im Rotkammgebirge lebt. Er erforscht die dunklen Künste und sucht die Sichel von Elune, ein Artefakt, das verheerende Magie entfesseln kann.",al={"morganths identität","wer ist morganth","morganths vorgeschichte"}},{q="Wo steht der Turm von Ilgalar?",a="Der Turm von Ilgalar steht im östlichen Rotkammgebirge, jenseits der Burg Steinwacht. Shadowhide-Gnolle lagern an seinem Fuß.",al={"standort des turms von ilgalar","wo steht morganths turm","turm im rotkammgebirge"}},{q="Warum will Theocritus Morganth tot sehen?",a="Durch Fernsichtzauber erfuhr Theocritus, dass Morganth nach der Sichel von Elune suchte, und fürchtete, er könnte sie bald finden. Die Macht, nach der Morganth strebte, bedrohte das Rotkammgebirge und das benachbarte Königreich Sturmwind.",al={"theocritus' beweggrund","warum morganth töten","grund für theocritus' quest"}},{q="Was ist die Sichel von Elune?",a="Die Sichel von Elune ist ein geheimnisumwobenes Artefakt. Theocritus erklärt ihre Kräfte nicht, fürchtet aber, dass das Rotkammgebirge und Sturmwind die dunkle Macht des Hexenmeisters spüren werden, falls Morganth sie findet.",al={"geschichte der sichel von elune","was ist die sichel","warum ist die sichel gefährlich"}},{q="Was ist der Schattenanhänger?",a="Der Schattenanhänger ist Morganths magischer Talisman. Er bündelt seine dunklen Künste, und ihn zu Theocritus im Turm von Azora zu bringen, beweist Morganths Niederlage.",al={"schattenanhänger","morganths anhänger","beweis für morganths tod"}},{q="Welche Questreihe führt hierher?",a="Die Reihe beginnt mit Theocritus' Retrieval im Wald von Elwynn, gefolgt von A Watchful Eye und Looking Further. Bei diesen Schritten werden Hilfsmittel zurückgeholt und Fernsichtzauber vorbereitet, um Morganths Turm zu beobachten. Dies ist der letzte Teil der Reihe.",al={"morganths questreihe","voraussetzungen für morganth","wie morganth freischalten"}}},fx={["23819dbd"]={q="Warum schickt Theocritus Euch, um Morganth gegenüberzutreten, anstatt selbst zu gehen?",a="Theocritus gibt ganz offen zu, dass er nicht bereit ist, seine eigene magische Macht direkt gegen Morganth einzusetzen. Während er von Turm von Azora aus über die Grenzen wacht und die Verteidigung gegen Shadow Magic koordiniert, erfordert ein Angriff auf den Turm von Ilgalar selbst einen mutigen, fähigen Abenteurer, der bereit ist, die Festung des Hexenmeisters zu stürmen, bevor Morganths dunkle Ambitionen ganz Sturmwind bedrohen können.",al={"warum werdet ihr geschickt","warum kämpft theocritus nicht gegen morganth","warum nicht theocritus"}}},fp="8,87,27.327.0,18.335.0,29.330.1,16.217.0,30.126.0,39.210.0,28.191.0,30.166.0,34.214.0"}
P.entries["quest:2498"] = {n="Rückkehr zu Denalan",s="Am Al'Amethsee überbringt Ihr Rellian Greenspyres beunruhigende Nachricht an Denalan, den Botaniker, der die Verderbnis in Teldrassil erforscht. Nachdem Ihr die moosigen Tumore an Timberlingen untersucht habt, zieht Ihr nach Süden, um Denalan bei seiner Entdeckung zu helfen.",h="Am Al'Amethsee überbringt Ihr Rellian Greenspyres beunruhigende Nachricht an Denalan, den Botaniker, der die...",kw={"denalan","dolanaar","al'amethsee","oakenscowl","rellian greenspyre","teldrassil","timberlinge","tumors"},ang={["class:Druid"]="Als Druide wisst Ihr, dass die Untersuchung unnatürlicher Tumore an Waldgeistern der Cenarion-Pflicht dient, die Natur im Gleichgewicht zu halten und Verderbnis zu tilgen.",["race:NightElf"]="Als Nachtelf kennt Ihr Timberlinge als lebendige Zeichen von Teldrassils Lebenskraft. Denalan zu helfen, gehört zu Eurer Pflicht, die Verderbnis zu heilen, die die neue Heimat Eures Volkes bedroht."},sec={{t="Eine Botschaft durch die Wipfel",b="Rellian Greenspyre untersucht die moosigen Tumore, die Teldrassils Timberlinge befallen, als ihn eine dringende Nachricht seines Kollegen Denalan erreicht. In seinem Lager am Al'Amethsee hat Denalan endlich die Ursache dieser unnatürlichen Wucherungen an den Naturgeistern des Waldes eingegrenzt. Rellian erkennt die Tragweite dieser Entdeckung und schickt Euch sofort nach Süden, um zu helfen."},{t="Die Bedrohung am See",b="Am Al'Amethsee stellt sich Denalan verderbten Wesen, die Teldrassils Geäst vergiften. Seine Arbeit beginnt mit verdorbenen Pflanzen und erkrankten Timberlingen und führt ihn dann in einen direkten Konflikt mit dem verdorbenen Timberling Oakenscowl."}},faq={{q="Wer ist Denalan?",a="Denalan ist ein Nachtelf und als Forscher und Naturkundler am Al'Amethsee im Süden Teldrassils tätig. Er untersucht die Pflanzen der Insel, seltsame Mutationen an Sämlingen und die unnatürlichen Leiden, die sich unter den dortigen Timberlingen ausbreiten.",al={"denalan hintergrund","wer ist denalan","denalan al'amethsee"}},{q="Warum schickt Rellian Greenspyre Euch zurück zum Al'Amethsee?",a="Rellian erhält Nachricht, dass Denalan die wahrscheinliche Ursache der Tumore gefunden hat, die Timberlinge verderben. Die Entdeckung nimmt rasch Gestalt an und bedroht den Wald, weshalb Rellian Euch sofort zur Hilfe vor Ort schickt.",al={"warum zu denalan gehen","rellian greenspyres auftrag"}},{q="Was sind die Tumore, die die Timberlinge befallen?",a="Timberlinge sind friedliche Naturgeister, die aus der Pflanzenwelt der Insel entstehen, doch die in Teldrassil wurzelnde Verderbnis lässt bizarre moosige Wucherungen an ihnen sprießen. Diese Tumore machen die Geschöpfe feindselig und wahnsinnig.",al={"timberlingtumore","warum haben timberlinge tumore","moosige tumore"}},{q="Wo kann ich Denalan finden?",a="Denalan hat ein Lager am Ufer des Al'Amethsees, gleich südlich von Dolanaar in den südlichen Wäldern Teldrassils.",al={"denalans standort","wo ist denalan"}},{q="Was geschieht, nachdem Ihr Denalan erreicht habt?",a="Denalan begrüßt Eure Hilfe und sagt, er habe etwas Beunruhigendes entdeckt. Wenn Ihr sein Lager erreicht, erklärt er, wie es weitergeht.",al={"what comes next","oakenscowl fortsetzung"}},{q="Wie verbindet dieser Auftrag Rellian und Denalan?",a="Rellian Greenspyre untersucht Timberlinge in Darnassus, während Denalan von seinem Lager am Al'Amethsee aus arbeitet. Rellians Forschungen zu den Tumoren erreichen Denalan, dessen neue Entdeckung ihre Ursache betrifft.",al={"warum schickt rellian mich zu denalan","rückkehr zu denalan zweck"}}},fp="17,222,27.349.0,22.223.1,15.214.0,59.211.0,47.214.0,25.109.0,37.129.1,49.198.0"}
P.entries["quest:2499"] = {n="Grimmeiche",s="Am Al'Amethsee geht Fäulnis von Oakenscowl aus, einem einstigen Hüter Teldrassils. Denalan bittet Euch, der Bedrohung ein Ende zu setzen. Der wahnsinnig gewordene Holzling haust in einer Höhle am Südufer des Sees.",h="Am Al'Amethsee geht Fäulnis von Oakenscowl aus, einem einstigen Hüter Teldrassils.",kw={"verderbnis","denalan","riesengroßer tumor","al'amethsee","moosbewachsene tumore","oakenscowl","teldrassil","holzling"},ang={["class:Druid"]="Als Druide seht Ihr einen Holzling, einst ein Hüter, der von seltsamen Wucherungen entstellt wurde. Teldrassils junges Ökosystem ist schwer krank.",["profession:Herbalism"]="Als Kräuterkundiger seht Ihr, wie unsichtbare Fäulnis die Pflanzenwelt zu bösartigen, moosbewachsenen Fäulnisgebilden verformt, während Ihr Denalan helft.",["race:NightElf"]="Als Nachtelf seht Ihr, wie Oakenscowls Fall den Al'Amethsee bedroht, südlich von Dolanaar und nahe dem Herzen Eures Volkes."},sec={{t="Ein gefallener Hüter",b="Holzlinge pflegen Teldrassils Zweige, und Oakenscowl führte sie einst an. Nun erfasst die Verderbnis die einfachen Wildtiere des Weltbaums ebenso wie seine uralten Beschützer. Eine gewaltige Wucherung schwillt auf Oakenscowls Rinde an und treibt den Holzling in den Wahnsinn. Einst war es seine Pflicht, den Wald zu beschützen. Nun greift die Fäulnis um sich."},{t="Die Reinigung des Al'Amethsees",b="Oakenscowl verbirgt sich in einer Höhle am Südufer des Al'Amethsees. Von dort aus vergiftet er das Wasser und die Waldtiere in der Nähe. Denalan kann dem Geschöpf nicht allein entgegentreten und will es deshalb vernichten lassen. Er hofft, die Verderbnis einzudämmen und die seltsame Wucherung zu untersuchen, die die Geister des Sees befällt."}},faq={{q="Was ist Oakenscowl?",a="Oakenscowl ist ein gewaltiger Holzling, ein Waldgeist, der mit Teldrassils Pflanzenwelt verbunden ist. Einst führte er seinesgleichen an, bevor eine bösartige Wucherung von ihm Besitz ergriff.",al={"wer ist oakenscowl","oakenscowl hintergrundgeschichte","was für ein geschöpf ist oakenscowl"}},{q="Warum muss Oakenscowl vernichtet werden?",a="Oakenscowls gewaltige Wucherung hat seinen Verstand verzerrt und ihn äußerst gewalttätig gemacht. Von seiner Höhle am Al'Amethsee aus verbreitet er Fäulnis unter den Holzlingen und Wildtieren in der Nähe.",al={"warum oakenscowl töten","oakenscowl feindselig"}},{q="Wo lebt Oakenscowl?",a="Oakenscowl haust in einer Höhle am Südufer des Al'Amethsees im Süden Teldrassils.",al={"oakenscowl aufenthaltsort","wo ist oakenscowls höhle"}},{q="Wer ist Denalan und warum untersucht er den Tumor?",a="Denalan ist ein Kräuterkundiger und Naturforscher, der am Ostufer des Al'Amethsees lebt. Er erforscht die Pflanzen und Tiere des Weltbaums, um die seltsame Fäulnis zu verstehen und zu heilen, die die örtlichen Holzlinge befällt.",al={"wer vergibt die oakenscowl-quest","denalan oakenscowl"}},{q="Was hat den Tumor an Oakenscowl verursacht?",a="Oakenscowls Tumor deutet auf eine tiefere Krankheit hin, die sich durch Teldrassils Boden und Wurzeln ausbreitet. Sie verdirbt die Naturgeister von innen heraus.",al={"warum haben holzlinge tumore","quelle der verderbnis"}},{q="Ist Oakenscowl nicht mehr zu retten?",a="Wenn Abenteurer Oakenscowl finden, ist sein Leiden bereits zu weit fortgeschritten. Die Wucherung hat den Holzling völlig entstellt, und Denalan bittet darum, ihn von seinem Leid zu erlösen.",al={"kann oakenscowl geheilt werden","oakenscowl heilen"}}},fx={a853a20e={q="Wofür benötigt Denalan den Riesengroßer Tumor?",a="Denalan benötigt den Riesengroßer Tumor, um das unnatürliche Leiden zu untersuchen, das Teldrassils Holzschinder vergiftet. Als Naturforscher, der am Al'Amethsee lebt, hat er beobachtet, wie die Kreaturen dem Wahnsinn und der Verderbnis anheimfielen. Da Oakenscowl das größte Geschwür trug, das er je gesehen hat, bietet die Untersuchung eines solch extremen Exemplars Denalan die beste Chance, die Krankheit zu verstehen, die die lokale Tierwelt in Aufruhr versetzt.",al={"warum riesengroßer tumor","zweck des riesengroßen tumors","nutzung riesengroßer tumor"}},["47d0c5c8"]={q="Warum benötigt Denalan Eure Hilfe gegen Oakenscowl?",a="Denalan ist ein isolierter Forscher und Kräuterkundiger, kein Krieger, der fähig ist, einen massiven, korrumpierten Holzschinder in seiner Höhle zu bekämpfen. Er gab zu, dass er es nicht einmal wagte, sich dem Biest zu nähern, als er das südliche Ufer erkundete. Da Ihr Eure Fähigkeiten bereits beim Sammeln von moosigen Tumoren und bei der Unterstützung seiner Arbeit unter Beweis gestellt habt, vertraut er Euch die Beseitigung der Bedrohung an, die sein Zuhause am See gefährdet.",al={"warum ich denalan","warum einen abenteurer schicken oakenscowl","warum kann denalan oakenscowl nicht bekämpfen"}}},fp="10,186,17.294.0,21.284.0,19.142.0,33.168.0,29.92.0,48.206.0,36.133.0,28.158.0"}
P.entries["quest:25"] = {n="Und dann langsam abkühlen lassen",s="Am Mystralsee haben beschmutzte Wassergeister Nachschubtransporte der Horde ins Steinkrallengebirge aufgehalten. Mastok Wutfauch am Splitterholzposten schickt Euch aus, um die feindseligen Elementare zu beseitigen und einen Nachtelfenpavillon mit Blick auf die Silberwindzuflucht auszukundschaften.",h="Am Mystralsee haben beschmutzte Wassergeister Nachschubtransporte der Horde ins Steinkrallengebirge...",kw={"beschmutzter wasserelementar","pavillon","mastok wutfauch","mystralsee","splitterholzposten","und dann langsam abkühlen lassen","der steinkrallenpfad","tideress"},ang={["class:Shaman"]="Als Schamane erkennt Ihr den entstellten Zustand der Wasserelementare als Zeichen einer tiefen Disharmonie der Elemente in Eschentals uralten Wäldern.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass der Splitterholzposten auf offene Nachschubrouten angewiesen ist. Den Steinkrallenpfad freizuhalten sichert die Verständigung und den Handel mit dem Steinkrallengebirge.",["race:Orc"]="Als Orc wisst Ihr, dass die Horde auf Eschentals Holz und Pfade angewiesen ist, um ihre Siedlungen zu versorgen. Eine Unterbrechung der Nachschublinien im Gebirge kann nicht geduldet werden."},sec={{t="Eine versperrte Nachschubroute",b="Die Horde braucht Holz, Vorräte und Boten, die zwischen Eschental und dem Steinkrallengebirge verkehren. Der Steinkrallenpfad führt am Westufer des Mystralsees vorbei, wo feindselige Wasserelementare den Reiseverkehr zum Erliegen gebracht und Nachschubkarawanen schwer zugesetzt haben. Mastok Wutfauch fordert zum Handeln auf, bevor die Nachschublinien der Horde zusammenbrechen."},{t="Die verderbten Gewässer",b="Die Wasserelementare im Mystralsee sind beschmutzt, aggressiv und unberechenbar geworden. Sie greifen Reisende auf den nahen Pfaden an, weshalb Ihr ausgesandt werdet, um ihre Zahl zu verringern und den mächtigeren Geist Tideress zu besiegen. Was die Geister des Sees verdorben hat, bleibt inmitten der Unruhen in Eschentals heiligen Hainen unbekannt."},{t="Augen über dem Wasser",b="Auf der mittleren Insel des Mystralsees steht ein Nachtelfenpavillon mit freiem Blick über das Wasser auf die Silberwindzuflucht. Späher der Horde werden ausgesandt, um zu prüfen, ob er als vorgeschobener Beobachtungsposten dienen könnte. Von dort aus könnten die Befehlshaber von Splintertree unentdeckt die Bewegungen der Allianz in der Nähe beobachten."}},faq={{q="Was verursacht den Stillstand nahe dem Steinkrallengebirge?",a="Beschmutzte Wasserelementare im Mystralsee sind gewalttätig geworden und greifen Reisende auf dem nahen Steinkrallenpfad an. Ihre Angriffe haben die Nachschubtransporte zwischen Eschental und dem Steinkrallengebirge zum Erliegen gebracht.",al={"warum stehen die transporte still","steinkrallenpfad blockiert","was hat die nachschubroute lahmgelegt"}},{q="Wer befiehlt, die Elementare zu beseitigen?",a="Mastok Wutfauch, ein Orc am Splitterholzposten im östlichen Eschental, befiehlt Euch, die Elementare zu beseitigen und die Stellung der Allianz auszukundschaften.",al={"wer vergibt und dann langsam abkühlen lassen","mastok wutfauch quest","wer ist mastok"}},{q="Warum soll der Pavillon in der Mitte des Mystralsees ausgekundschaftet werden?",a="Der Pavillon auf der mittleren Insel des Mystralsees bietet einen Blick über das Wasser zur nahen Nachtelfensiedlung Silberwindzuflucht. Mastok will prüfen lassen, ob er als verborgener Beobachtungsposten zur Überwachung feindlicher Bewegungen geeignet ist.",al={"warum den pavillon auskundschaften","zweck des pavillons im mystralsee","pavillon als beobachtungsposten"}},{q="Was ist der Steinkrallenpfad?",a="Der Steinkrallenpfad ist der Gebirgspfad, der das südwestliche Eschental mit dem Steinkrallengebirge verbindet. Er führt am Westufer des Mystralsees vorbei.",al={"lage des steinkrallenpfads","pfad ins steinkrallengebirge","straße im steinkrallengebirge"}},{q="Warum sind die Wasserelementare im Mystralsee beschmutzt?",a="Die Ursache für die Verderbnis der Wasserelementare ist unbekannt. Die Unruhen in Eschental haben den See aus dem Gleichgewicht gebracht, sodass seine Geister Außenstehenden feindselig begegnen.",al={"warum sind die elementare verderbt","wasser im mystralsee verderbt","ursprung der beschmutzten elementare"}},{q="Welcher Außenposten der Allianz wird vom Pavillon aus beobachtet?",a="Der Pavillon bietet einen Blick auf die Silberwindzuflucht, eine Nachtelfensiedlung unmittelbar nördlich des Sees. Die Sentinels dort verteidigen Eschental gegen die Holzfällarbeiten der Horde.",al={"welcher allianzstützpunkt liegt nahe dem mystralsee","allianzaußenposten in eschental"}}},fx={["46f9d708"]={q="Was bekämpft Ihr am Mystralsee?",a="Ihr werdet ausgesandt, um die befleckten Wasserelementare zu vernichten, die den Mystralsee bewohnen, sowie Tideress. Die Wasser des Sees sind zum Leben erwacht und greifen jeden aggressiv an, der auf der nahegelegenen Straße reist.",al={"mystralsee ziel","gegen wen werdet ihr ausgesandt","was tötet ihr stonetalon standstill"}}},fp="21,237,21.322.0,20.296.0,21.289.0,47.204.0,34.135.0,51.221.0,27.148.0,54.146.0,56.171.0"}
P.entries["quest:250"] = {n="Eine dunkle Bedrohung",s="Chefingenieur Hinderweir VII. fürchtet, dass Dunkeleisenpioniere nahe der östlichen Rampe den Steinwerkdamm bedrohen. Da ein Großteil seiner Garnison an die Front der Allianz entsandt wurde, untersucht Ihr die Gefahr.",h="Chefingenieur Hinderweir VII.",kw={"dunkeleisen","dun modr","hinderweir","loch modan","pioniere","der steinwerkdamm","verdächtiges fass","thandol-übergang"},ang={["faction:Alliance"]="Als Rekrut der Allianz helft Ihr, lebenswichtige Versorgungsknotenpunkte und regionale Bauwerke zu bewachen, während die Fronttruppen über den ganzen Kontinent verstreut kaum ausreichen.",["profession:Engineering"]="Als Ingenieur erkennt Ihr die gewaltigen Ausmaße des Damms und die Gefahr durch Pioniere, die leicht flüchtige chemische Sprengstoffe gegen seine tragenden Fundamente einsetzen.",["race:Dwarf"]="Als Zwerg kennt Ihr den Steinwerkdamm als Meisterwerk zwergischer Handwerkskunst und als Stolz Eures Volkes. Verwandte aus dem Dunkeleisenclan bedrohen ihn, und Ihr verteidigt Eure Heimat."},sec={{t="Ein verwundbares Wunderwerk",b="Der Steinwerkdamm hält die Wassermassen von Loch Modan zurück. Ingenieure aus Eisenschmiede errichteten ihn als großes Bauwerk, doch ein Großteil seiner Wachmannschaft ist an die Front der Allianz gezogen. Chefingenieur Hinderweir VII. und seine kleine Mannschaft haben nun kaum Schutz, falls ein Angriff erfolgt."},{t="Widerhall aus dem Norden",b="Dunkeleisenzwerge griffen den Thandol-Übergang an und plünderten Dun Modr im Sumpfland. Nun lauern bekannte Pioniere nahe der östlichen Rampe des Damms. Hinderweir fürchtet, dass der Clan nun die Lebensader von Loch Modan ins Visier genommen hat und sie sprengen will."},{t="Das verdächtige Fass",b="Ein verdächtiges Fass liegt zwischen den Felsen, wo sich die Pioniere versammelt hatten. Darin befindet sich ein leicht flüchtiges Pulver mit einem seltsamen Geruch. Das Fass deutet auf Vorbereitungen hin, das Fundament des Steinwerkdamms zu sprengen."}},faq={{q="Warum sorgt sich Chefingenieur Hinderweir um den Damm?",a="Dunkeleisentruppen griffen den Thandol-Übergang an und plünderten Dun Modr im Sumpfland. Als Hinderweir ihre Pioniere nahe der östlichen Rampe des Steinwerkdamms sah, fürchtete er, der Damm sei ihr nächstes Ziel.",al={"warum ist hinderweir besorgt","bedrohung für den steinwerkdamm","warum den damm angreifen"}},{q="Wohin ist die Garnison des Damms gezogen?",a="Die meisten Wachtruppen des Steinwerkdamms wurden an die Front der Allianz versetzt. Hinderweirs oberster Inspektor zog mit ihnen, sodass der Damm nur schwach verteidigt blieb.",al={"warum gibt es keine wachen am damm","wachmannschaft des damms","wo sind die soldaten"}},{q="Was findet Ihr an der östlichen Rampe?",a="Nahe der östlichen Rampe findet Ihr ein verdächtiges Fass voller seltsam riechenden Pulvers. Seine Anwesenheit bestätigt, dass die Dunkeleisenzwerge die Sabotage des Damms vorbereiten.",al={"was ist der hinweis","verdächtiges fass als hinweis","was tun die pioniere"}},{q="Welche strategische Bedeutung hat der Steinwerkdamm?",a="Der Steinwerkdamm reguliert den Stausee von Loch Modan. Sollte er brechen, würde die Flut das Sumpfland verwüsten und das Herz des Zwergengebiets trockenlegen.",al={"warum den damm zerstören","was passiert wenn der damm bricht","geschichte des damms"}},{q="Was war der Angriff auf Dun Modr, den Hinderweir erwähnte?",a="Dun Modr war ein befestigter Außenposten der Zwerge im nördlichen Sumpfland, nahe dem Thandol-Übergang. Eindringlinge der Dunkeleisenzwerge überwältigten die Stadt und griffen den Übergang an, wodurch sie wichtige Versorgungswege über Land abschnitten.",al={"angriff auf dun modr","was geschah in dun modr","zerstörung des thandol-übergangs"}},{q="Wer sind die Dunkeleisenzwerge, die Loch Modan ins Visier nehmen?",a="Der Dunkeleisenclan und die Bronzebeard-Zwerge sind schon lange erbitterte Rivalen, seit dem War of the Three Hammers. Vom Schwarzfels und der Sengenden Schlucht aus sabotieren sie häufig die Infrastruktur und Grenzbefestigungen der Bronzebeard-Zwerge.",al={"wer sind die dunkeleisenzwerge","motiv der dunkeleisenpioniere","warum hassen die dunkeleisenzwerge eisenschmiede"}}},fx={f99be494={q="Warum sind Dunkeleisensappere am Steinwerkdamm?",a="Nach ihren Angriffen auf The Thandol Span und die Stadt Dun Modr im Norden sind Dunkeleisenzwerge nach Süden in Loch Modan eingedrungen. Chefingenieur Hinderweir hat ihre Sappere dabei beobachtet, wie sie sich um die östliche Rampe des Steinwerkdamms schlichen, und vermutet, dass sie als Nächstes die massive Struktur sabotieren wollen.",al={"dunkeleisensappere damm","warum sind dunkeleisen am damm","dunkeleisensappere loch modan"}}},fp="19,196,19.267.0,21.221.0,19.194.1,55.196.0,32.161.0,37.160.1,59.148.0,56.196.0,51.230.0"}
P.entries["quest:251"] = {n="Übersetzung von Calvinius' Notiz",s="In Dunkelhain wird den Stadtoberhäuptern ein seltsamer Brief zur Übersetzung vorgelegt. Bürgermeister Ello Schwarzhaupt wendet sich an Sirra Von'Indi, den Gelehrten, der sich mit obskuren Schriften auskennt.",h="In Dunkelhain wird den Stadtoberhäuptern ein seltsamer Brief zur Übersetzung vorgelegt.",kw={"calvinius","chiffre","dunkelhain","dämmerwald","ello schwarzhaupt","einsiedler","sirra von'indi","übersetzung"},ang={["class:Mage"]="Als Magier erkennt Ihr vielleicht die Arbeit, die Sirra Von'Indi verrichtet, während er Dunkelhains obskure Schriften studiert.",["faction:Alliance"]="Als Champion der Allianz, der dem Dämmerwald hilft, seht Ihr, wie verletzlich und isoliert sich Dunkelhains Stadtoberhäupter inmitten der umgebenden Dunkelheit fühlen."},sec={{t="Eine unentzifferbare Nachricht",b="Calvinius schickt Bürgermeister Ello Schwarzhaupt von seinem Zuhause aus einen versiegelten Brief. Schwarzhaupt erwartet eine exzentrische Bitte oder bitteres Geschwafel des Einsiedlers vom Friedhof, doch das Pergament trägt seltsame Schriftzeichen, die gewöhnliches Common nicht erklären kann. Der Bürgermeister kann weder alte noch obskure Sprachen lesen, also will er das Schreiben nicht einfach abtun. Selbst ein verrückter Einsiedler kann im Dämmerwald eine Gefahr darstellen."},{t="Der Gelehrte von Dunkelhain",b="Schwarzhaupt schickt Euch über den Platz zu Sirra Von'Indi, Dunkelhains Gelehrtem für esoterisches Wissen. Sirra kennt alte Künste und vergessene Sprachen. Er spottet über Calvinius' Geisteszustand und meint, jeder, der neben einem heimgesuchten Friedhof lebt, müsse ein verrottetes Gehirn haben. Dennoch nimmt er das Pergament ernst und beginnt mit der langwierigen Übertragung."},{t="Einblick in den Geist des Einsiedlers",b="Calvinius' verschlüsselter Brief offenbart einen Verstand, der hinter dem gebrechlichen, zurückgezogenen alten Mann, der um Vorräte und Schutz vor Ghulen bittet, nicht zu vermuten wäre. Seine Botschaft kündigt eine Abrechnung an, und Dunkelhain ist schlecht darauf vorbereitet."}},faq={{q="Warum kann Bürgermeister Schwarzhaupt die Notiz nicht selbst lesen?",a="Bürgermeister Ello Schwarzhaupt kann die seltsame Schrift der Notiz nicht lesen, also schickt er sie zu Sirra Von'Indi, Dunkelhains Gelehrtem für obskure Schriften.",al={"warum kann ello die notiz nicht lesen","schwarzhaupt brief übersetzen","warum übersetzer nötig"}},{q="Wer ist Sirra Von'Indi?",a="Sirra Von'Indi ist Dunkelhains Gelehrter, bekannt für sein Wissen über obskure Sprachen, Geschichte und alte Künste. Er untersucht geheimnisvolle Texte und Relikte aus den umliegenden Wäldern.",al={"wer ist sirra von indi","wer ist der übersetzer","dunkelhain gelehrter"}},{q="Wo lebt Calvinius?",a="Calvinius lebt in einer baufälligen Hütte unmittelbar nordöstlich des Friedhofs von Rabenflucht im westlichen Dämmerwald, umgeben von rastlosen Untoten und Raubtieren.",al={"wo ist calvinius","einsiedler aufenthaltsort","calvinius dämmerwald"}},{q="Wie reagiert Sirra auf Calvinius' Notiz?",a="Sirra zweifelt an Calvinius' Verstand und meint, jeder, der neben einem Friedhof lebt, müsse ein verrottetes Gehirn haben. Dennoch untersucht er den Brief und beginnt, dessen obskure Schrift zu übersetzen.",al={"was denkt sirra über calvinius","sirra von indi dialog"}},{q="Was geschieht, nachdem die Notiz Sirra übergeben wurde?",a="Sirra Von'Indi bittet Euch zu warten, während er den Brief überträgt. Sobald er fertig ist, bringt Ihr die Übersetzung zu Lord Ello Schwarzhaupt zurück.",al={"nächste quest nach übersetzung der notiz","was folgt auf übersetzung von calvinius' notiz"}},{q="Warum schrieb Calvinius an Bürgermeister Schwarzhaupt?",a="Calvinius schrieb Bürgermeister Schwarzhaupt in einer Schrift, die Ello nicht lesen kann. Sirra Von'Indis Übersetzung enthüllt, was der Einsiedler geschrieben hat.",al={"warum schickte calvinius einen brief","einsiedler notiz zweck"}}},fp="28,164,25.356.0,24.337.0,32.205.1,48.134.0,22.179.0,28.142.0,47.176.0,44.137.1,45.126.1"}
P.entries["quest:2518"] = {n="Tränen des Mondes",s="Im Tempel des Mondes trauert Priesterin A'moora um Lady Sathrah. Einst von Elune gesegnet, ist die Spinne nun eine Gefahr, und die Sisterhood will ihr Leid lindern und ihre heiligen Spinndrüsen bergen.",h="Im Tempel des Mondes trauert Priesterin A'moora um Lady Sathrah.",kw={"darnassus","elune","lady sathrah","priesterin a'moora","silbrige spinndrüsen","tränen des mondes","teldrassil","tempel des mondes","quellsee"},ang={["class:Druid"]="Als Druide seht Ihr in Sathrahs plötzlicher Wildheit und ihren Qualen ein weiteres beunruhigendes Zeichen für Teldrassils Ungleichgewicht. Ihr Geist muss geheilt werden, damit die Wildnis gesunden kann.",["class:Priest"]="Als Priester der Sisterhood of Elune wisst Ihr, dass Gnade einen schmerzlichen Schlag und eine rituelle Opfergabe verlangen kann, um eine verderbte Seele in die Umarmung der Göttin zurückzuführen.",["race:NightElf"]="Als Kaldorei wisst Ihr, dass die Verderbnis in Teldrassils Wildnis weder einfache Tiere noch Elunes heilige Gefährten verschont."},sec={{t="Der Fall eines geliebten Geschöpfs",b="Im Tempel des Mondes in Darnassus trauert Priesterin A'moora um Lady Sathrah. Elune segnete die Spinne einst. Unter dem Nachthimmel spann Sathrah silberne Netze zwischen Teldrassils Ästen, auf denen sich Abendnebel sammelte. Die Sisterhood of Elune sammelte den schimmernden Tau wegen seiner Heilkraft für ihre heiligen Riten."},{t="Gnade für Sathrah",b="Lady Sathrah ist dem Wahnsinn verfallen, wie ein Großteil der Tierwelt auf dem jungen Weltenbaum. Nahe dem Quellsee im Norden bedroht ihre Raserei Reisende und ihre eigene, noch ungeschlüpfte Brut. Die Sisterhood kann sie in ihrer gewalttätigen Raserei nicht läutern und hat daher beschlossen, ihr Leid aus Gnade zu beenden.\n\nDie Priesterinnen wollen Sathrahs silbrige Spinndrüsen bergen und ihre Überreste an Elunes Altar weihen. Sie beten, dass die Mondgöttin ihr Frieden und eine reine Wiedergeburt gewährt."}},faq={{q="Wer ist Lady Sathrah?",a="Lady Sathrah ist eine uralte, auf Teldrassil heimische Spinne, die einst von Elune geliebt wurde. Ihre silbrigen Netze fingen den Nachtnebel ein, dessen Tau Heilkraft besaß.",al={"lady sathrah hintergrund","wer ist lady sathrah","sathrah vorgeschichte","sathrah spinne"}},{q="Warum muss Lady Sathrah getötet werden?",a="Lady Sathrah ist einem Wahnsinn verfallen, der sich unter Teldrassils Tieren ausgebreitet hat. Sie ist gewalttätig und gefährdet ihre Nachkommen und andere, weshalb die Sisterhood sie aus Gnade töten will.",al={"warum sathrah töten","kann sathrah gerettet werden","warum ist sathrah aggressiv"}},{q="Wo ist Lady Sathrah zu finden?",a="Lady Sathrah ist im Norden Teldrassils nahe dem Ufer des Quellsees zu finden.",al={"lady sathrah fundort","wo ist sathrah","sathrah finden"}},{q="Wofür wurden Lady Sathrahs Netze verwendet?",a="Lady Sathrahs Netze fingen den Abendnebel ein, aus dem silbriger Tau mit Heilkräften entstand. Die Sisterhood of Elune bewahrte ihn im Tempel des Mondes auf.",al={"tränen des mondes bedeutung","sathrah netze verwendung","silbriger tau hintergrund"}},{q="Wer vergibt die Quest Tränen des Mondes?",a="Priesterin A'moora erteilt vertrauenswürdigen Abenteurern der Allianz diesen Auftrag im Tempel des Mondes in Darnassus.",al={"wer vergibt tränen des mondes","tränen des mondes questgeber","priesterin amoora"}},{q="Was werden die Priesterinnen mit Sathrahs Spinndrüsen tun?",a="Die Priesterinnen wollen Sathrahs Spinndrüsen Elune am Tempelaltar darbringen. Sie bitten die Göttin, Sathrahs Geist anzunehmen, sie zu segnen und ihr eine friedliche Wiedergeburt zu gewähren.",al={"was geschieht mit den spinndrüsen","spinndrüsen zweck","opfergabe an elune"}}},fp="17,205,25.317.0,17.497.1,20.148.0,40.199.0,28.81.0,39.144.0,38.105.0,55.174.0"}
P.entries["quest:2519"] = {n="Der Tempel des Mondes",s="In Darnassus bittet Schwester Aquinne um Hilfe für ein leidendes uraltes Geschöpf in Teldrassil. Die Sisterhood of Elune kann sich nicht allein darum kümmern, und der Hilferuf leitet ein feierliches Ritual der Gnade ein.",h="In Darnassus bittet Schwester Aquinne um Hilfe für ein leidendes uraltes Geschöpf in Teldrassil.",kw={"darnassus","elune","priesterin a'moora","sathrah","schwester aquinne","sisterhood of elune","die tempelgärten","tempel des mondes"},ang={["class:Druid"]="Als Druide liegt es Euch sehr am Herzen, wenn ein großes Geschöpf der Wildnis in Not ist. Der Ruf aus den Tempelgärten bittet Euch, die natürliche Harmonie wiederherzustellen.",["class:Priest"]="Als Priester fühlt Ihr Euch vielleicht zur Arbeit der Schwesternschaft in Darnassus hingezogen. Ihr helft anderen Dienern des Göttlichen bei Riten der Heilung und Gnade.",["race:NightElf"]="Als Nachtelf helft Ihr, Teldrassils heiliges Ökosystem zu schützen und der Führung von Elunes Priesterschaft zu folgen, wenn Ihr Schwester Aquinnes Ruf folgt."},sec={{t="Eine Bitte in den Gärten",b="In den Tempelgärten von Darnassus bittet Schwester Aquinne Euch, einem ehrwürdigen Waldgeschöpf zu helfen, das Schmerzen leidet. Sie dient Elune und spricht für ihren Orden. Die Schwestern können sich nicht allein um das Geschöpf kümmern."},{t="In den Tempel des Mondes",b="Schwester Aquinne schickt Euch nach Südosten zum Tempel des Mondes. Dort koordiniert Priesterin A'moora Rituale und praktische Aufgaben für die leidende Tierwelt Teldrassils. Sie bereitet Verbündete auf einen traurigen Akt der Gnade vor."}},faq={{q="Wer vergibt die Quest „Der Tempel des Mondes“?",a="Schwester Aquinne richtet den ersten Hilferuf aus dem Viertel der Tempelgärten von Darnassus an Euch.",al={"questgeber tempel des mondes","wo gibt es die quest tempel des mondes","wer vergibt der tempel des mondes"}},{q="Wo befindet sich Priesterin A'moora?",a="Priesterin A'moora befindet sich im Tempel des Mondes, gleich südöstlich der Tempelgärten in Darnassus.",al={"wo ist priesterin amoora","amoora finden","priesterin a'moora standort"}},{q="Welches Geschöpf braucht Hilfe?",a="Das Geschöpf ist Sathrah, eine verehrte Spinne aus Teldrassil. Ihre Not führt zu einem Ritual der Gnade unter der Aufsicht der Priesterschaft.",al={"welches geschöpf braucht hilfe","wer ist das waldgeschöpf","worum geht es in dieser questreihe"}},{q="Ist diese Quest erforderlich, um die Questreihe fortzusetzen?",a="Nein. „Der Tempel des Mondes“ ist ein optionaler erster Hilferuf. Ihr könnt direkt mit Priesterin A'moora im Tempel sprechen und die rituellen Aufgaben übernehmen, ohne zuvor Schwester Aquinne aufzusuchen.",al={"ist tempel des mondes erforderlich","tempel des mondes überspringen","tempel des mondes hinführungsquest"}},{q="Welche Quest folgt auf diese?",a="Priesterin A'moora bietet „Tears of the Moon“ an. Sie bittet Euch, Lady Sathrahs Leiden zu beenden und ihre silbrigen Spinndrüsen zurückzubringen.",al={"nächste quest nach tempel des mondes","tempel des mondes folgequest","what comes next"}},{q="Warum bittet die Sisterhood of Elune Außenstehende um Hilfe?",a="Verderbnis hält sich in Teldrassils Pflanzen- und Tierwelt und bringt die Schwesternschaft an ihre Grenzen. Die Priesterinnen suchen fähige Reisende, die die Natur und die Göttin achten.",al={"warum außenstehende bitten","warum braucht die priesterschaft hilfe","schwester aquinnes beweggrund"}}},fx={e3d31678={q="Warum schickt Schwester Aquinne Euch zu Priesterin A'moora?",a="Schwester Aquinne erkennt, dass eine ehrwürdige Kreatur der Wälder von Teldrassil leidet und dringend Hilfe benötigt, aber die Angelegenheit erfordert die direkte Anleitung der Priesterschaft. Da sie weiß, dass eine heikle, schwierige Aufgabe bevorsteht, weist sie fähige Reisende an Priesterin A'moora im Tempel des Mondes hin, damit diese ordnungsgemäße Anweisungen erhalten, wie sie eingreifen können.",al={"warum will schwester aquinne das","tempel des mondes warum entsendung","zweck schwester aquinne"}}},fp="22,184,21.189.0,20.213.0,44.81.0,35.102.0,37.122.0,46.186.0,34.127.0,57.158.0"}
P.entries["quest:252"] = {n="Übersetzung für Ello",s="Im Dämmerwald bringt Ihr Sirra Von'Indis Übersetzung zu Lord Ello Schwarzhaupt in Dunkelhain. Sie gehört zur Geschichte um Calvinius, und der Brief enthält Neuigkeiten über die Schriften des Eremiten.",h="Im Dämmerwald bringt Ihr Sirra Von'Indis Übersetzung zu Lord Ello Schwarzhaupt in Dunkelhain.",kw={"calvinius","dunkelhain","ello schwarzhaupt","rabenflucht","sirra von'indi","übersetzung für ello"},ang={["faction:Alliance"]="Als Streiter der Allianz erfahrt Ihr im Dämmerwald schmerzlich, wie tückisch er ist: Fehlgeleitetes Vertrauen in den Wäldern kann eine ganze Siedlung unschuldiger Bürger gefährden."},sec={{t="Eine späte Erkenntnis",b="Calvinius' Bitten schickten Reisende tagelang quer durch den Dämmerwald. Der betagte Eremit bat um Faden, konservierte Reagenzien und persönliche Gegenstände und behauptete, er brauche sie zum Überleben. Sirra Von'Indi entzifferte schließlich sein privates Pergament und enthüllte die Wahrheit: Der freundliche alte Mann ist ein geistesgestörter Einbalsamierer. Die gesammelten Komponenten wurden zu einer furchterregenden Waffe der Rache, die gegen Dunkelhain gerichtet ist."},{t="Der Weg nach Dunkelhain",b="Als der übersetzte Brief Lord Ello Schwarzhaupt erreicht, weicht jede Farbe aus dem Gesicht des Bürgermeisters. Welche edlen Beweggründe Euch auch zum Helfen bewogen haben mögen, die Lieferung jener letzten Vorräte ermöglichte es Calvinius, seine monströse Schöpfung Kleiner fertigzustellen. Die Übergabe des Briefes setzt den Koloss in Bewegung, der vom Friedhof von Rabenflucht aus auf der Straße nach Osten marschiert. Jede Patrouille der Nachtwache auf seinem Weg wird niedergemetzelt."}},faq={{q="Was steht in dem übersetzten Brief?",a="Sirra befürchtet, dass Calvinius etwas Unaussprechliches getan hat. Bringt den übersetzten Brief unverzüglich zu Lord Ello Schwarzhaupt, der die Gefahr für Dunkelhain einschätzen kann.",al={"was steht im brief","calvinius brieftext","was wurde übersetzt"}},{q="Wer ist Sirra Von'Indi?",a="Sirra Von'Indi ist ein Gelehrter, der in Dunkelhain lebt. Seine Sprachkenntnisse und sein analytisches Geschick lassen ihn Calvinius' kryptische Notizen und Briefe entziffern, wenn andere die Schrift nicht lesen können.",al={"wer ist sirra","sirra von indi hintergrundgeschichte"}},{q="Warum gibt Lord Ello dem Spieler die Schuld?",a="Lord Ellos Reaktion erfolgt, als er den übersetzten Brief liest. Bringt ihm die Warnung so schnell wie möglich.",al={"warum ist ello wütend","habe ich kleiner erschaffen","ellos reaktion"}},{q="Was geschieht unmittelbar nach Abschluss dieser Quest?",a="Bringt den übersetzten Brief zu Lord Ello Schwarzhaupt in Dunkelhain. Seine Reaktion und die im Brief beschriebene Gefahr werden deutlich, sobald er ihn liest.",al={"was löst kleiner aus","erscheint kleiner","kleiner ereignis"}},{q="Wohin geht Kleiner danach?",a="Kleiner ist mit der Straße zwischen dem Friedhof von Rabenflucht und Dunkelhain verbunden. Seine Rolle in Calvinius' Plan wird im Laufe der Ermittlungen deutlich.",al={"kleiners weg","wohin marschiert kleiner"}},{q="Welche Quest kommt als Nächstes?",a="Nachdem Ihr den Brief überbracht habt, schickt Lord Ello Abenteurer weiter zu „Bride of the Embalmer“.",al={"nächste quest","nach übersetzung für ello"}}},fx={["203575b3"]={q="Warum möchte Sirra Von'Indi, dass der Brief an Ello überbracht wird?",a="Nachdem Sirra den Brief entziffert hatte, wurde ihm klar, dass Calvinius etwas Unaussprechliches begangen und ein monströses Verderben entfesselt hat, das bereits auf Dunkelhain zusteuert. Er schickt Euch, um Lord Ello Schwarzhaupt sofort zu warnen, damit die Stadtführung sich auf die bevorstehende Katastrophe vorbereiten kann, bevor sie ihre Tore erreicht.",al={"warum brief an ello schicken","sirra von indi motiv","warum übersetzte notiz überbringen"}},["4e225af8"]={q="Warum schickt Sirra Euch, um Lord Ello zu warnen, anstatt selbst zu gehen?",a="Ihr wart die Person, die ursprünglich von Lord Ello damit beauftragt wurde, Calvinius' verdächtige Schriften zu entziffern, und Ihr habt den seltsamen Brief überhaupt erst zu Sirra gebracht. Da eine monströse Bedrohung bereits unterwegs ist und jede Sekunde zählt, ist es der schnellste Weg, die Warnung in die Hände des Bürgermeisters zu bekommen, wenn er den fähigen Abenteurer schickt, der direkt vor ihm steht.",al={"warum ich translation to ello","warum geht sirra nicht zu ello","warum spieler zu ello schicken"}}},fp="19,177,21.388.1,21.368.1,41.154.0,22.179.0,36.109.0,53.137.1,34.137.2,22.90.1"}
P.entries["quest:2520"] = {n="Sathrahs Opferung",s="Im Tempel des Mondes gewährt Sathrahs Opferung Lady Sathrah einen letzten Ritus. Ihr bringt ihre Spinndrüsen zu Elunes heiligen Wassern, wo die Priesterschaft ihre Seele von Verderbnis zu reinigen sucht.",h="Im Tempel des Mondes gewährt Sathrahs Opferung Lady Sathrah einen letzten Ritus.",kw={"a'moora","darnassus","elune","brunnen","lady sathrah","reinigung","sathrah","spinndrüsen","teldrassil","tempel des mondes"},ang={["class:Druid"]="Als Druide könnt Ihr Trost darin finden, dass gefallene Tiere durch Reinigung in den natürlichen Kreislauf zurückkehren können, selbst während Krankheit Teldrassil heimsucht.",["class:Priest"]="Als Priester seht Ihr, wie Elunes heiliges Licht und ihre heiligen Wasser von Wahnsinn und Verderbnis geplagte Geister heilen können.",["race:NightElf"]="Als Nachtelf ehrt Ihr mit diesem feierlichen Ritus Kalimdors Pflanzen- und Tierwelt. Selbst wenn eine Kreatur getötet werden muss, ehrt und reinigt Elune's Grace ihren Geist."},sec={{t="Reinigung in heiligen Wassern",b="Priesterin A'moora bittet Euch, nach Lady Sathrahs Tod einen letzten Ritus für sie zu vollziehen. Der dunkle Wahnsinn, der sich über Teldrassil ausbreitet, verwandelte das friedliche Wesen der großen Spinne in blinde Angriffslust. Die Priesterschaft der Elune sucht ihre gefallene Essenz zu erlösen, statt ihren Tod als bloße Bestandsverringerung zu betrachten. Ihr legt ihre silbrigen Spinndrüsen in den Brunnen im Herzen des Tempels des Mondes. Seine geweihten Wasser waschen die Verderbnis fort und schenken ihr Erlösung."},{t="Sathrahs Erneuerung",b="Lady Sathrahs friedlicher Geist erhebt sich, als ihre Spinndrüsen das mondbeschienene Becken berühren. Gereinigt von dem Leiden, das sie in den Wahnsinn trieb, gilt sie der Sisterhood of Elune als gerettet. Der Verlust der großen Kreatur schmerzt zutiefst, doch nach dem Glauben der Nachtelfen kann heilige Reinigung ihr eines Tages die Wiedergeburt mit unverdorbenem Geist ermöglichen."}},faq={{q="Wer war Lady Sathrah?",a="Lady Sathrah war eine große Spinne, die auf Teldrassil lebte und der Verderbnis erlag, die sich unter den Wildtieren des Weltbaums ausbreitete. Die Verderbnis trieb sie in den Wahnsinn, und sie musste getötet werden, damit ihre Überreste geweiht werden konnten.",al={"lady sathrah","wer ist sathrah","was ist sathrah"}},{q="Wo wird das Opfer dargebracht?",a="Ihr bringt das Opfer im heiligen Brunnen in der Mitte des Tempels des Mondes dar, dem zentralen Heiligtum der Sisterhood of Elune in Darnassus.",al={"wo das opfer ablegen","standort des brunnens","tempelbrunnen"}},{q="Was geschieht, wenn Ihr die Spinndrüsen in den Brunnen legt?",a="Wenn Ihr die silbrigen Spinndrüsen in die gesegneten Wasser legt, erscheint Sathrahs gereinigter Geist kurz im Becken und wandelt frei und friedlich umher. Dies zeigt, dass Elune das Opfer annimmt.",al={"was geschieht am brunnen","sathrahs geist im brunnen"}},{q="Warum musste Lady Sathrah sterben?",a="Die Verderbnis in Lady Sathrahs Geist saß zu tief, um sie zu Lebzeiten zu heilen. Priesterin A'moora und die Sisterhood glaubten, ihre Seele nur retten zu können, indem sie ihr Leiden beendeten und ihre Überreste in Elunes heiligen Wassern reinigten.",al={"warum sathrah töten","konnte sathrah gerettet werden","sathrahs wahnsinn"}},{q="Wer vergibt die Quest Sathrahs Opferung?",a="Priesterin A'moora vergibt und beendet Sathrahs Opferung im Tempel des Mondes in Darnassus, von wo aus sie die zentrale Kammer überblickt.",al={"questgeber","wo abgeben","amooras standort"}},{q="Welcher Glaube der Nachtelfen liegt diesem Ritual zugrunde?",a="Nachtelfen glauben, dass von Mother Moon gereinigte Seelen in der natürlichen Welt wiedergeboren werden können, erneuert und frei von Verderbnis.",al={"wiedergeburt der nachtelfen","elunes reinigung","hintergrund zur wiedergeburt"}}},fx={f4be164d={q="Warum möchte Priesterin A'moora, dass dies getan wird?",a="Priesterin A'moora versucht, Lady Sathrah friedlich zur Ruhe zu betten und die Verderbnis zu tilgen, die die einst edle Kreatur quälte. Indem Sathrahs Spinndrüsen in die heiligen Wasser des Tempel des Mondes gelegt werden, kann Elune's Grace den verbliebenen Makel reinigen, der die große Spinne in den Wahnsinn trieb, was es ihrem Geist ermöglicht, erlöst und schließlich erneuert wiedergeboren zu werden.",al={"amoora motiv","warum das opfer darbringen","warum will amoora sathrah opfer"}}},fp="19,193,28.462.0,22.335.1,21.212.0,31.143.0,59.180.1,33.225.0,40.130.0,54.123.0"}
P.entries["quest:253"] = {n="Braut des Einbalsamierers",s="In Dunkelhain schickt Lord Ello Schwarzhaupt Euch auf die Suche nach Elizas Grab. Die Stadt weiß nun, dass es den Einbalsamierer wirklich gibt, und Ihr sollt sein lebendiges Herz aus ihren verfluchten Überresten nehmen und ihn seiner Macht berauben.",h="In Dunkelhain schickt Lord Ello Schwarzhaupt Euch auf die Suche nach Elizas Grab.",kw={"alchemist","braut des einbalsamierers","dunkelhain","dämmerwald","eliza","ello schwarzhaupt","herz des einbalsamierers","grab","der einbalsamierer"},ang={["class:Paladin"]="Als Paladin könnt Ihr Elizas unheilige Wiedererweckung als Frevel gegen das Licht und die natürliche Ordnung sehen. Ihr könnt den fleischfressenden Schrecken läutern und die lästerliche Lebensader des Nekromanten durchtrennen.",["class:Priest"]="Als Priester könnt Ihr die Tragödie des trauernden Witwers erkennen. Dennoch muss Elizas nach Fleisch hungernder Hohn auf das Leben mit heiliger Endgültigkeit zur Ruhe gebettet werden.",["faction:Alliance"]="Da die Nachtwache im Kampf gegen die wilden Schrecken des Dämmerwalds kaum noch Kräfte übrig hat, müsst Ihr als Streiter der Allianz Dunkelhain vor diesem uralten, schleichenden Wahnsinn verteidigen."},sec={{t="Eine Gutenachtgeschichte wird wahr",b="Die Kinder des Dämmerwalds wuchsen mit Geschichten über den Einbalsamierer auf. Es hieß, er sei ein gütiger Alchemist gewesen, den der Tod seiner geliebten Frau Eliza in den Wahnsinn getrieben hatte. Verzweifelt bemüht, den Tod zu überlisten, wandte er sich der Zauberei zu, schnitt sein eigenes schlagendes Herz heraus und setzte es in ihre Brust. Lord Ello Schwarzhaupt tat die Geschichte einst als Dorffolklore ab. Jüngste Entdeckungen beweisen, dass der Einbalsamierer unter den Lebenden wandelt und sein Werk unter der Friedhofserde schwärt."},{t="Die wiedererweckte Braut",b="Eliza kehrte zu einem schrecklichen Preis ins Leben zurück. Der gestohlene Lebensfunke erweckte sie als unersättliche Abscheulichkeit, die für immer nach lebendem Menschenfleisch hungert. Entsetzt über seine Schöpfung und nicht gewillt, sie zu vernichten, verbarg der Einbalsamierer seine Braut in einem einsamen Grab. Er besuchte sie heimlich, während er weitere Gräueltaten plante.\n\nNun schickt Lord Schwarzhaupt Euch aus, Elizas Grab freizulegen und den nach Fleisch hungernden Schrecken zu töten. Nehmt das noch schlagende Herz an Euch, das die dunkle Kunst des Einbalsamierers aufrechterhält."},{t="Dunkelhains Ägide",b="Als Ihr Elizas schlagendes Herz nach Dunkelhain bringt, ist Lord Schwarzhaupt erleichtert. Der Bürgermeister hat nicht vor, es zu zerstören. Er plant, das Handwerk des Alchemisten gegen ihn zu wenden und die unheimliche Magie des Herzens als schützenden Talisman über Dunkelhain zu nutzen.\n\nEr hofft, dass es die bedrängte Stadt vor jeglichem Zorn bewahrt, den der geschwächte Einbalsamierer aus Rache noch heraufbeschwören kann."}},faq={{q="Wer ist der Einbalsamierer?",a="Der Einbalsamierer war ein Alchemist im Dämmerwald, der nach dem Tod seiner Frau Eliza dem Wahnsinn verfiel. Er wandte sich der Nekromantie zu und schnitt sein lebendiges Herz heraus. Als er es in ihren Leichnam einsetzte, erweckte er sie wieder zum Leben und wurde selbst zu einem schwer fassbaren Ungeheuer.",al={"geschichte des einbalsamierers","wer ist der einbalsamierer","vorgeschichte des einbalsamierers"}},{q="Warum wurde Eliza begraben, wenn sie wieder zum Leben erweckt wurde?",a="Der Alchemist erweckte Eliza mit seinem eigenen Herzen wieder zum Leben, doch dunkle Magie ließ sie unersättlich nach lebendem Menschenfleisch hungern. Da er sie weder gefahrlos in die Gesellschaft zurückbringen noch ihren wilden Hunger stillen konnte, verbarg er sie auf einem Friedhof.",al={"warum ist eliza begraben","elizas grab","warum eliza in einem grab verbergen"}},{q="Warum will Lord Schwarzhaupt das Herz des Einbalsamierers?",a="Ello glaubt, dass das Herz des Einbalsamierers die Quelle seiner Macht ist. Er bittet Euch, es aus Elizas Grab zu holen, solange es noch schlägt, in der Hoffnung, die Macht des Alchemisten zu brechen.",al={"warum das herz holen","zweck des herzens des einbalsamierers"}},{q="Wo beginnt diese Questreihe?",a="Die Reihe schließt direkt an „Translation to Ello“ an. Die alten Briefe und Forschungsunterlagen, die Lord Ello Schwarzhaupt überbracht wurden, beweisen, dass der Einbalsamierer aus den örtlichen Kindergeschichten aktiv und gefährlich ist.",al={"questvoraussetzung","wie braut des einbalsamierers erhalten","vorquest des einbalsamierers"}},{q="Wird der Einbalsamierer endgültig besiegt, wenn das Herz geborgen wird?",a="Ello glaubt, dass die Macht des Einbalsamierers gebrochen wird, wenn ihm das Herz genommen wird. Was darauf folgt, wird klar, wenn Ihr nach Dunkelhain zurückkehrt.",al={"ist der einbalsamierer tot","tötet das den einbalsamierer"}},{q="Wer vergibt diese Quest?",a="Lord Ello Schwarzhaupt, Bürgermeister und Oberhaupt von Dunkelhain, erteilt Euch diesen Auftrag im Rathaus von Dunkelhain. Er hat die Wahrheit hinter den Volkserzählungen der Stadt erfahren.",al={"questgeber","wer startet braut des einbalsamierers"}}},fx={a9aedc81={q="Warum möchte Lord Ello Schwarzhaupt, dass Elizas Grab gestört wird?",a="Lord Ello Schwarzhaupt will die Macht des Einbalsamierers brechen, bevor der wahnsinnige Alchemist Dunkelhain ins Verderben stürzt. Der Einbalsamierer goss seine eigene dunkle Magie und sein Herz in die Wiederbelebung seiner verstorbenen Frau Eliza. Indem er das Herz zurückgewinnt, während es noch schlägt, beabsichtigt Schwarzhaupt, die übernatürliche Stärke des Monsters zu schwächen und seine verbleibende Schutzmagie in einen Schutzschild für die Stadt zu verwandeln.",al={"warum will ello das erledigt haben","ebonlocke motiv bride of the embalmer","warum elizas grab finden"}},b836fb1b={q="Was ist Eliza und warum ist sie in Raven Hill begraben?",a="Eliza ist die wiederbelebte Bride of the Embalmer, die in einem vernachlässigten Grab auf dem Friedhof von Raven Hill ruht. Getrieben vom Wahnsinn vor Trauer legte ihr Ehemann sein eigenes Herz in ihre Leiche, um sie wiederzuerwecken. Das Ritual war erfolgreich, aber es verfluchte sie mit einem unersättlichen Hunger nach lebendem menschlichen Fleisch, was ihn zwang, sie begraben zu halten, bis er einen Weg finden konnte, sie zu erhalten.",al={"wer ist eliza","bride of the embalmer ziel","warum ist eliza begraben"}}},fp="21,196,26.429.0,21.461.1,17.361.2,20.207.0,53.198.0,50.165.0,34.190.0,58.120.1,21.153.0"}
P.entries["quest:254"] = {n="Graben in der Erde",s="Auf dem Friedhof von Rabenflucht sucht Ihr nach dem verschwundenen Herzen des Einbalsamierers. Ein mit Elizas Namen markierter Erdhügel könnte die Antwort bergen, unter der Erde begraben.",h="Auf dem Friedhof von Rabenflucht sucht Ihr nach dem verschwundenen Herzen des Einbalsamierers.",kw={"calvinius","bride of the embalmer","sarg","graben in der erde","dämmerwald","eliza","elizas graberde","herz des einbalsamierers","friedhof von rabenflucht"},ang={["class:Paladin"]="Ein frisches Grab zu stören, verstößt gegen die Bestattungsriten des Heiligen Lichts. Den widernatürlichen Unhold darin freizulassen und zu vernichten, reinigt das Grab.",["class:Priest"]="Scharren und Zähneknirschen unter geweihter Erde verletzen die friedliche Ruhe, die das Licht den Toten des Dämmerwalds verspricht.",["faction:Alliance"]="Die Nachtwache kämpft gegen den Schrecken, der sich von Rabenflucht ausbreitet. Die Gräuel zu finden, die der Einbalsamierer begraben hat, ist für Dunkelhains Sicherheit entscheidend."},sec={{t="Ein gestörtes Grab",b="Auf dem Friedhof von Rabenflucht trägt eine Stelle mit lockerer Erde den Namen Eliza. Andere Gräber im Dämmerwald liegen offen und sind Aasfressern oder wilden Ghulen ausgeliefert, doch diese Erde wurde sorgsam aufgeschüttet. Grabt Ihr unter der obersten Erdschicht, findet Ihr gesplitterte Sargbretter. Sie bedecken den Überrest, den der Einbalsamierer vor dem Tageslicht verbergen wollte."},{t="Das Scharren im Innern",b="Eliza liegt unter gesplitterten Sargbrettern, doch sie ruht nicht. Der Deckel erzittert, während bekrallte Finger scharren und verrottende Kiefer klappern. Calvinius' Experiment regt sich in ihrem Kiefernholzsarg. Das verschwundene Herz des Einbalsamierers schlägt in ihrer Brust, während sie darauf wartet, dass unvorsichtige Hände das Grab öffnen."}},faq={{q="Was liegt in Elizas Grab begraben?",a="Unter der Erde liegt ein Sarg mit Eliza, einer untoten Kreatur, die der Einbalsamierer erschaffen hat. Sein Herz ruht in ihrer Brust.",al={"was ist im grab","wer ist eliza","elizas grabinhalt"}},{q="Wo befindet sich dieses Grab?",a="Elizas Grab liegt auf dem Friedhof von Rabenflucht im westlichen Dämmerwald, zwischen verwunschenen Gruften und umherstreifenden Untoten.",al={"wo ist elizas grab","elizas grab fundort","graberde fundort"}},{q="Warum müsst Ihr Euch bis zum Sarg durchgraben?",a="Ihr grabt Euch in das Grab, um Eliza entgegenzutreten und das Herz des Einbalsamierers zurückzuholen. Damit endet die Suche nach seinen finsteren Machenschaften.",al={"warum das grab ausheben","zweck des grabens","warum den sarg öffnen"}},{q="Was geschieht, wenn der Sarg geöffnet wird?",a="Wenn Ihr den Sarg öffnet, bricht Eliza aus. Ihr müsst den um sich krallenden Ghul vernichten, um das Herz zurückzuholen, das mit ihr darin eingeschlossen wurde.",al={"was geschieht als nächstes","sarg geöffnet","elizas sarg öffnen"}},{q="Wer hat Eliza begraben?",a="Der Einbalsamierer begrub Eliza auf dem Friedhof von Rabenflucht und verbarg seine Schöpfung und sein kostbares Herz zwischen dessen Gräbern.",al={"wer hat eliza begraben","wer hat sie dort begraben"}},{q="Ist Eliza ein gewöhnlicher Ghul?",a="Eliza war die Frau des Einbalsamierers, durch seine dunkle Magie erweckt, mit seinem Herzen in ihrer Brust. Sie ist zäher und handelt zielgerichteter als die geistlosen Ghule, die auf den Straßen des Dämmerwalds umherstreifen.",al={"was für ein monster ist eliza","ist eliza ein ghul"}}},fp="24,137,17.297.0,21.292.1,32.118.1,28.105.0,39.115.1,39.124.1,28.104.1,27.175.1"}
P.entries["quest:2541"] = {n="Der schlafende Druide",s="Im Grabhügel von Ban'ethil schläft Oben Zornklaue, während sein Geist im Smaragdgrünen Traum gefangen ist. Gnarlpineschamanen haben ihn aus seinem Körper gezogen und sein Fleisch dazu gebracht, durch den Grabhügel zu wandeln.",h="Im Grabhügel von Ban'ethil schläft Oben Zornklaue, während sein Geist im Smaragdgrünen Traum gefangen ist.",kw={"grabhügel von ban'ethil","grabhügel","smaragdgrüner traum","gnarlpine","oben zornklaue","voodooglücksbringer des schamanen","teldrassil","der schlafende druide"},ang={["class:Druid"]="Als Druide könnt Ihr Obens Notlage als einen wachen Albtraum begreifen. Wenn Euch der Körper entrissen wird, während Ihr mit dem Smaragdgrünen Traum in Verbindung steht, verletzt das den Kern des druidischen Schlummers.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass die Entweihung des Grabhügels von Ban'ethil durch die Gnarlpinefurbolgs zeigt, wie weit sie sich von ihrer uralten Verbundenheit mit den Kaldorei entfernt haben."},sec={{t="Ein gestörter Schlummer",b="Nachtelfendruiden schlafen in Grabhügeln in ganz Kalimdor, während ihre Geister durch den Smaragdgrünen Traum wandern. Ihre Körper ruhen während ihres jahrhundertelangen Schlummers in Steinnischen. Teldrassils Verderbnis hat die Gnarlpinefurbolgs zu verzweifelter Wildheit getrieben. Im Grabhügel von Ban'ethil haben Gnarlpineschamanen Oben Zornklaues geheiligte Ruhe gestört und seinen lebenden Geist aus seinem schlafenden Körper gezogen."},{t="Voodoo und Verderbnis",b="Ein Voodooglücksbringer des Schamanen ermöglicht es Gnarlpineschamanen, Obens leeren Körper zu beleben. Sein Geist ist im Smaragdgrünen Traum gefangen und sieht zu, wie sein Fleisch durch die Gänge des Grabhügels streift und blindlings jeden Eindringling angreift. Obens Geist bittet Euch, einen Gnarlpine-Glücksbringer zu beschaffen, damit er ihn untersuchen und einen Weg suchen kann, die Verzauberung aufzuheben und seinen Körper wiederherzustellen."}},faq={{q="Wer ist Oben Zornklaue?",a="Oben Zornklaue ist ein Nachtelfendruide, der im Grabhügel von Ban'ethil in geheiligten Schlummer fiel, um mit dem Smaragdgrünen Traum in Verbindung zu treten. Feindselige Gnarlpinefurbolgs übernahmen die Kontrolle über seinen Körper und verdrängten seinen Geist.",al={"oben zornklaue","wer ist der schlafende druide","schlafender nachtelf im grabhügel"}},{q="Warum greift Obens Körper Leute an?",a="Gnarlpineschamanen trennten Obens Geist von seinem Fleisch und belebten seinen leeren Körper mit dunkler Magie. Nun bewacht er die Tiefen des Grabhügels von Ban'ethil.",al={"warum ist oben feindselig","warum greift oben an","oben zornklaues körper greift an"}},{q="Was ist der Voodooglücksbringer des Schamanen?",a="Der Voodooglücksbringer des Schamanen ist ein verzauberter Fokus, den Gnarlpineschamanen im Grabhügel von Ban'ethil bei sich tragen. Mit seiner dunklen Macht ziehen sie die Geister schlafender Druiden aus deren Körpern und beleben ihre körperlichen Hüllen.",al={"schamanenglücksbringer","voodooglücksbringer teldrassil","was ist der voodooglücksbringer des schamanen"}},{q="Wo befindet sich Obens wahrer Geist während der Quest?",a="Obens Geist ist im Smaragdgrünen Traum gefangen und kann nicht in seinen Körper zurückkehren. Nahe seiner Ruhestätte kann er als schimmernder Geist mit der wachen Welt kommunizieren.",al={"wo ist oben","obens geist aufenthaltsort","smaragdgrüner traum oben"}},{q="Warum sind die Furbolgs im Grabhügel von Ban'ethil feindselig?",a="Teldrassils zunehmende Verderbnis und der um sich greifende Wahnsinn haben den Gnarlpinestamm gegen seine einstigen Verbündeten, die Nachtelfen, aufgebracht. Die Gnarlpinefurbolgs haben heilige Stätten der Druiden entweiht.",al={"warum sind die gnarlpine wahnsinnig","furbolgs verderbnis teldrassil","warum sind furbolgs aggressiv"}},{q="Kann Obens Körper gerettet werden, ohne ihn zu töten?",a="Oben hofft, den Voodooglücksbringer des Schamanen erforschen und die Verzauberungen untersuchen zu können, die sein Fleisch binden. Er hofft, die Magie zu verstehen und einen Weg zu finden, die Krise zu lösen.",al={"oben zornklaue retten","kann oben gerettet werden","oben heilen"}}},fx={["08a1a718"]={q="Warum möchte Oben Zornklaue das Amulett?",a="Gnarlpine-Furbolgschamanen haben es geschafft, Oben Zornklaues Geist von seiner schlafenden physischen Form zu trennen. Sein umherwandernder Körper wurde durch ihre dunkle Magie animiert, um jeden gewaltsam anzugreifen, der den Grabhügel von Ban'ethil betritt, während sein wahres Bewusstsein im Smaragdgrünen Traum gefangen bleibt. Oben möchte ein Amulett, damit er dessen üble Verzauberung untersuchen und nach einem Weg suchen kann, die Kontrolle der Furbolgs über seinen Körper zu brechen.",al={"oben zornklaue motiv","warum will oben das amulett","warum oben zornklaue helfen"}},["21a70b6c"]={q="Warum sind die Gnarlpine-Schamanen im Grabhügel von Ban'ethil?",a="Der Gnarlpine-Stamm hat den heiligen Grabhügel von Ban'ethil überrannt und die Verwundbarkeit schlafender Nachtelfdruiden ausgenutzt. Ihre Schamanen haben begonnen, abscheuliche Rituale durchzuführen, um die Geister der Druiden von ihrem Fleisch zu trennen, und die Kontrolle über die physischen Körper übernommen, um sie als gewaltsame Wächter zur Bewachung ihres neu besetzten unterirdischen Reiches einzusetzen.",al={"warum gnarlpine schamanen hier","gnarlpine im grabhügel","wer sind gnarlpine schamanen"}},["2131a103"]={q="Warum benötigt Oben Euch, um das Amulett zu bergen?",a="Oben ist völlig unfähig, selbst zu handeln. Sein Geist ist von der wachen Welt abgeschnitten und im Smaragdgrünen Traum gefangen, während sein physischer Körper eine animierte Marionette ist, die von den Gnarlpine-Schamanen kontrolliert wird. Ohne physische Form oder Handlungsfähigkeit ist er vollständig auf einen externen Abenteurer angewiesen, der sich den Furbolgs stellt und das Amulett zu seinem Geist bringt.",al={"warum braucht oben mich","warum kann oben das amulett nicht selbst holen","warum ich oben quest"}}},fp="18,187,19.382.0,21.336.1,21.205.0,36.151.0,32.208.0,45.162.0,53.169.0,44.162.0"}
P.entries["quest:255"] = {n="Söldner",s="In Thelsamar heuert Magistrat Bluntnose durchreisende Kämpfer an, während Oger der Mo'grosh ins nordöstliche Loch Modan vordringen. Eisenschmiede hat Soldaten zur Verteidigung des Tals zugesagt, doch ihre Ankunft liegt noch Monate entfernt. Siedlungen, Ausgrabungen und der Steinwerkdamm bleiben schutzlos.",h="In Thelsamar heuert Magistrat Bluntnose durchreisende Kämpfer an, während Oger der Mo'grosh ins nordöstliche...",kw={"loch modan","magistrat bluntnose","mercenaries","mo'grosh","oger","der steinwerkdamm","thelsamar"},ang={["faction:Alliance"]="Als Reisender der Allianz wisst Ihr, dass Loch Modan ein wichtiger Korridor zwischen Khaz Modan und den nördlichen Königreichen ist. Ogerüberfälle, die dort Chaos stiften, bedrohen die Versorgungslinien der Allianz in den gesamten Östlichen Königreichen.",["race:Dwarf"]="Als Zwerg ist der Steinwerkdamm für Euch ein Kronjuwel zwergischer Ingenieurskunst. Dass er wegen Eisenschmiedes Bürokratie unbewacht bleibt, macht Bluntnoses Ruf zu den Waffen für Euch persönlich, ob als Gebirgsjäger oder Reisender aus der Hauptstadt."},sec={{t="Eisenschmiedes langsame Mühlen",b="Eisenschmiede brauchte zwei Monate, um eine Handvoll Soldaten für die örtliche Verteidigung von Loch Modan zuzusagen. Bis sie eintreffen, werden weitere zwei Monate vergehen. Thelsamars Wachen sind überlastet, während sich jenseits des Tals feindliche Streitkräfte sammeln. Magistrat Bluntnose kann nicht auf Verstärkung warten."},{t="Die Bedrohung in den Hügeln",b="Oger der Mo'grosh haben ein Lager in den Hügeln nordöstlich des Lochs befestigt. Ihre wachsende Präsenz bedroht Thelsamar, die Ironband Excavation Site und den Steinwerkdamm. Sollte der Damm angegriffen oder beschädigt werden, wären die Verwüstungen flussabwärts katastrophal.\n\nOhne offizielle Gebirgsjägerabteilungen heuert Bluntnose unabhängige Kämpfer an, um die Reihen der Oger zu lichten. Er hofft, dem Tal Zeit gegen Oger und Troggs zu verschaffen."}},faq={{q="Warum heuert Magistrat Bluntnose Söldner an, statt Wachen einzusetzen?",a="Eisenschmiede reagiert nur langsam auf die Hilferufe aus Loch Modan. Zwei Monate vergingen, bevor der Senat auch nur eine Handvoll Soldaten zur Verteidigung des Tals bewilligte, und bis zu ihrer Ankunft vergehen weitere zwei Monate. Da Thelsamar, der Damm und die örtlichen Ausgrabungsstätten unmittelbar bedroht sind, heuert Bluntnose unabhängige Kämpfer an.",al={"warum söldner anheuern","thelsamars wachen","hilfe aus eisenschmiede"}},{q="Wo befinden sich die Oger der Mo'grosh?",a="Die Oger der Mo'grosh befinden sich in der Festung Mo'grosh in den zerklüfteten Felsen und Hügeln nordöstlich des großen Sees von Loch Modan.",al={"standort der oger","wo sind mogrosh","lager der mogrosh"}},{q="Warum gilt der Steinwerkdamm als gefährdet?",a="Der Steinwerkdamm reguliert den gesamten See und ist ein architektonisches Juwel der Zwerge. Er hat fast keine militärische Verteidigung, und ein Lager der Mo'grosh liegt ganz in der Nähe. Bluntnose fürchtet, ein organisierter Angriff könnte das Bauwerk beschädigen oder sabotieren und katastrophale Überschwemmungen auslösen.",al={"warum den damm schützen","oger und der damm"}},{q="Welche weiteren Bedrohungen gibt es für Thelsamar neben den Ogern?",a="Überall am Loch sind Troggs aus unterirdischen Ruinen und Ausgrabungen hervorgebrochen. Bluntnose sieht in ihnen eine gewaltige Bedrohung, doch die nahe Ogerfestung zwingt ihn, Kämpfer anzuheuern, um die Mo'grosh zurückzudrängen. Dann kann sich die örtliche Wache auf die Vorstöße der Troggs konzentrieren.",al={"weitere bedrohungen in loch modan","bedrohung durch troggs"}}},fx={bfea2c9c={q="Warum will Magistrat Bluntnose, dass die Mo'grosh-Oger getötet werden?",a="Magistrat Bluntnose fürchtet um das Überleben von Thelsamar und der umliegenden Region. Die Mo'grosh-Oger haben ein starkes Lager nordöstlich des Sees errichtet, wodurch die Stadt, die örtliche Ausgrabungsstätte und der Steinwerkdamm anfällig für katastrophale Angriffe sind, während die Eisenschmiede die Entsendung von Verteidigungstruppen hinauszögert. Indem er die Oger zurückdrängt, hofft er, eine unmittelbare Bedrohung zu beseitigen und lokale Ressourcen frei zu machen, um mit den grassierenden Trogg-Invasionen fertig zu werden.",al={"motiv von magistrat bluntnose","warum mogrosh oger töten","bluntnose warum mercenaries"}},["5f9f9ec0"]={q="Wer sind die Mo'grosh-Oger, die Loch Modan bedrohen?",a="Die Mo'grosh sind ein brutaler Ogerclan, der in das nordöstliche Loch Modan eingedrungen ist und die rauen Hügel jenseits des Sees beansprucht. Ihre Vollstrecker und Bruten entfalten ihre gewaltige körperliche Stärke direkt neben verwundbarem Zwergenterritorium. Ihre wachsende Präsenz stellt eine unmittelbare physische Bedrohung für Reisende, den Steinwerkdamm und nahegelegene Zwergensiedlungen dar, wobei sie die überdehnten Verteidigungslinien der Region ausnutzen.",al={"wer sind die mogrosh","mogrosh oger loch modan","was sind die mogrosh oger"}}},fp="11,262,23.274.0,23.420.0,71.330.0,37.118.0,49.268.0,59.258.0"}
P.entries["quest:256"] = {n="GESUCHT: Chok'sul",s="Im Nordosten von Loch Modan bedrohen Chok'suls Oger die Siedlungen und die Bauwerke, die das Tal versorgen. Magistrat Bluntnose will den Kriegsherrn tot sehen, bevor weitere Leben verloren gehen.",h="Im Nordosten von Loch Modan bedrohen Chok'suls Oger die Siedlungen und die Bauwerke, die das Tal versorgen.",kw={"bluntnose","kopfgeld","chok'sul","choksul","loch modan","oger","der steinwerkdamm","thelsamar"},ang={["faction:Alliance"]="Als Mitglied der Allianz seid Ihr auf Loch Modan als Route für Agrargüter und Nachschub nach Dun Morogh angewiesen. Die Sicherheit von Thelsamar ist für die militärischen Unternehmungen der Allianz von Bedeutung.",["profession:Engineering"]="Als Ingenieur wisst Ihr, dass der Steinwerkdamm zu den größten Leistungen zwergischer Baukunst zählt. Zuzulassen, dass Oger ihn beschädigen, ist undenkbar.",["race:Dwarf"]="Als Zwerg seht Ihr, wie Angriffe auf den Steinwerkdamm und die nahegelegenen archäologischen Ausgrabungen den Stolz und das Erbe Eures Volkes sowie die Sicherheit der Ländereien von Eisenschmiede bedrohen."},sec={{t="Eine Bedrohung für den Loch",b="Oger bedrohen nun den Nordosten von Loch Modan, wo Troggs und wilde Tiere schon lange die Grenzen des Tals auf die Probe stellen. Sie haben in den zerklüfteten Hügeln Lager errichtet und begnügen sich nicht mehr damit, Verwertbares zusammenzusuchen. Örtliche Späher und die Stadtbehörden berichten von gezielten, anhaltenden und gefährlichen Überfällen."},{t="Das Kopfgeld auf Chok'suls Kopf",b="Magistrat Bluntnose glaubt, dass Chok'sul die Angriffe auf Thelsamar, eine nahegelegene zwergische Ausgrabungsstätte und den Steinwerkdamm lenkt. Aus Sorge um die Zivilbevölkerung und das große Ingenieursbauwerk des Tals setzt er ein Kopfgeld auf den Ogerhäuptling aus, der mit jedem Mittel getötet werden soll. Chok'suls abgetrennter Kopf wird als Beweis verlangt."}},faq={{q="Wer hat das Kopfgeld auf Chok'sul ausgesetzt?",a="Magistrat Bluntnose, der oberste Verwaltungsbeamte von Thelsamar, hat das Kopfgeld im Namen der Stadt ausgesetzt, um die Region vor organisierten Überfällen zu schützen.",al={"wer will choksul tot sehen","wer hat das kopfgeld auf choksul ausgesetzt","steckbrief thelsamar"}},{q="Warum hat die Jagd auf Chok'sul so hohe Priorität?",a="Chok'sul soll die Ogerangriffe auf Thelsamar, die archäologischen Ausgrabungen von Eisenschmiede und den Steinwerkdamm lenken und damit Zwergenleben und lebenswichtige Bauwerke des Königreichs gefährden.",al={"warum choksul töten","was hat choksul getan","bedrohung durch choksul"}},{q="Wo ist Chok'sul zu finden?",a="Chok'sul ist in einem Ogerlager zwischen den zerklüfteten Hügeln im äußersten Nordosten von Loch Modan zu finden.",al={"choksul aufenthaltsort","wo ist choksul","ogerlager loch modan"}},{q="Welchen Beweis verlangt Magistrat Bluntnose?",a="Magistrat Bluntnose verlangt Chok'suls abgetrennten Kopf als Beweis, um das Kopfgeld und Eisenschmiedes Dankbarkeit zu gewähren. Bringt ihn direkt zu ihm nach Thelsamar.",al={"chok'suls kopf","beweis für das kopfgeld","choksul abgeben"}},{q="Warum sollten Oger den Steinwerkdamm angreifen?",a="Der Steinwerkdamm staut den gewaltigen See von Loch Modan und ist ein Meisterwerk zwergischer Ingenieurskunst. Sabotage könnte die Feuchtgebiete überfluten und die Nachschubwege der Zwerge verwüsten, was ihn zu einem lohnenden Ziel für feindliche Streitkräfte macht.",al={"warum den damm angreifen","steinwerkdamm unter beschuss"}},{q="Arbeiten noch andere Oger mit Chok'sul zusammen?",a="Ja. Chok'sul befehligt ein Ogerlager in den nordöstlichen Hügeln und lenkt Überfälle im gesamten umliegenden Gebiet.",al={"choksuls klan","oger in loch modan","choksuls anhänger"}}},fx={["761222eb"]={q="Wer ist Chok'sul?",a="Chok'sul ist ein Ogerbrut, der das Kommando über das Ogerlager im nordöstlichen Loch Modan übernommen hat. Man hält ihn für den gerissenen Koordinator hinter den koordinierten Überfällen auf Thelsamar, den Steinwerkdamm und die örtliche Ausgrabungsstätte der Zwerge; er stellt die größte organisierte Bedrohung für die Sicherheit des Tals dar.",al={"wer ist choksul","ziel choksul","über choksul"}}},fp="16,180,20.280.0,28.306.0,34.138.0,55.180.0,28.103.0,45.143.0,44.216.0,44.123.0"}
P.entries["quest:2561"] = {n="Druide der Klaue",s="Unter Teldrassil wartet Oben Zornklaues Geist auf Erlösung. Die verderbten Furbolgs der Gnarlpine banden seinen Körper mit einer dunklen Verzauberung, und Ihr könnt ihn befreien, indem Ihr seine seelenlose Hülle zerstört.",h="Unter Teldrassil wartet Oben Zornklaues Geist auf Erlösung.",kw={"ban'ethil","druide der klaue","smaragdgrüner traum","gnarlpine","oben zornklaue","teldrassil","der schlafende druide","voodooglücksbringer"},ang={["class:Druid"]="Als Druide erkennt Ihr die Gefahr, wenn verderbte Furbolgs einen schlafenden Druiden der Klaue entweihen. Der Körper bleibt zurück, während sein Geist mit dem Smaragdgrünen Traum Zwiesprache hält.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass Teldrassil Eure Zuflucht sein sollte. Die Verderbnis der Furbolgs der Gnarlpine bedroht nun selbst die heiligen Grabhügel."},sec={{t="Ein entrissener Geist",b="Oben Zornklaue schlief in den Grabhügeln unter Teldrassil. Dann belegten die verderbten Furbolgs der Gnarlpine seinen Körper mit einer Voodooverzauberung. Die Magie riss seinen Geist aus seinem sterblichen Fleisch und sperrte ihn im Smaragdgrünen Traum ein. Nun verweilt Obens Geist ganz in der Nähe, unfähig zu ruhen oder seinen Körper wieder in Besitz zu nehmen."},{t="Gnade für das Fleisch",b="Oben Zornklaues körperliche Hülle steht weiterhin unter der Kontrolle der Furbolgs. Zerstört die geistlose, feindselige Hülle in der nahen Kammer. Setzt dann den Glücksbringer der Furbolgs über seinen Überresten ein, um die Magie zu zerschlagen, die seine Seele bindet."}},faq={{q="Warum muss ich Oben Zornklaue töten?",a="Die Furbolgs der Gnarlpine verzauberten Oben im Schlaf und verwandelten seinen Körper in eine seelenlose Marionette. Sein Fleisch steht weiterhin unter ihrer Kontrolle, daher lässt sich die Verzauberung nur durch dessen Zerstörung brechen und sein Geist befreien.",al={"warum oben töten","schlafenden druiden töten","oben zornklaues körper"}},{q="Wozu dient der Voodooglücksbringer?",a="Der Glücksbringer bricht die Verzauberung, die Oben beherrscht. Nachdem Ihr seinen seelenlosen Körper zerstört habt, setzt den Glücksbringer über seinen Überresten ein, um die Magie zu lösen, die seinen Geist festhält.",al={"voodooglücksbringer verwendung","wie voodooglücksbringer benutzen","gnarlpine glücksbringer oben"}},{q="Wohin geht Oben nach dieser Quest?",a="Sobald Oben Zornklaues Körper zerstört und die Verzauberung gebannt ist, kann sein Geist die sterbliche Welt verlassen und zur Ruhe in den Smaragdgrünen Traum ziehen.",al={"obens schicksal","was geschieht mit oben zornklaue","überlebt oben"}},{q="Warum nutzen die Gnarlpine Voodoomagie?",a="Die Furbolgs der Gnarlpine sind der Verderbnis und dem Wahnsinn verfallen. Sie haben sich von ihrer althergebrachten Harmonie abgewandt und nutzen nun finstere Zauberei und dunkle Magie, um nahe Kreaturen und schlafende Druiden zu unterwerfen.",al={"furbolg voodoo","gnarlpine voodoomagie","warum haben furbolgs glücksbringer"}},{q="Wer war Oben Zornklaue?",a="Oben war ein Nachtelf und Druide der Klaue, der in Teldrassils Grabhügeln in heiligen Schlummer fiel, um mit dem Smaragdgrünen Traum Zwiesprache zu halten. Die Furbolgs der Gnarlpine störten seine Ruhe und versklavten seinen Körper.",al={"wer ist oben","obens geschichte","oben zornklaue hintergrund"}},{q="Spricht Obens Geist noch mit mir, während sein Körper lebt?",a="Ja. Die Verzauberung riss Obens Geist aus seinem Fleisch. Sein Geist erschien nahe dem Kammereingang, unfähig, die verzauberte, leere Hülle im Inneren zu kontrollieren oder wieder in sie einzukehren.",al={"obens geist und körper","zwei obens","warum ist oben an zwei orten"}}},fx={bff893ba={q="Wer ist das Ziel, gegen das ich im Grabhügel von Ban'ethil ausgesandt werde?",a="Ihr werdet ausgesandt, um den seelenlosen physischen Körper von Oben Zornklaue selbst zu vernichten. Während sein Geist außerhalb verweilt, ist seine schlafende sterbliche Hülle in den Bann eines mächtigen Zaubers der Gnarlpine-Furbolgs innerhalb des Grabhügels von Ban'ethil gefallen. Ohne seine Seele handelt die Hülle nun unter ihrer korrupten Herrschaft.",al={"wen töte ich","ziel oben","körperloser oben"}},["6e4ee394"]={q="Warum braucht Oben Zornklaue mich, anstatt dies selbst zu tun?",a="Oben ist derzeit ein ätherischer Geist, vollständig von seiner sterblichen Form getrennt. Als Erscheinung außerhalb der Grabkammer gefangen, fehlt ihm die physische Substanz, um sich seiner verzauberten Hülle entgegenzustellen oder den Voodooglücksbringer zu führen, der benötigt wird, um die Magie zu brechen. Tief im Inneren des Grabhügels, weit außerhalb der Reichweite der Nachtelfen-Wächterinnen, seid Ihr der Einzige, der eingreifen kann.",al={"warum braucht oben mich","warum kann oben seinen körper nicht töten","warum ich oben zornklaue"}}},fp="17,189,16.290.0,19.213.1,36.214.0,34.159.0,36.153.1,41.201.0,22.193.0,61.168.0"}
P.entries["quest:257"] = {n="Das Prahlen eines Jägers",s="In der Weitschreiter-Lodge stellt Euch Daryl der Jüngling eine Jagd auf Zeit in Loch Modan: Erlegt sechs Berggeier innerhalb von fünfzehn Minuten.",h="In der Weitschreiter-Lodge stellt Euch Daryl der Jüngling eine Jagd auf Zeit in Loch Modan: Erlegt sechs...",kw={"das prahlen eines jägers","daryl der kühne","daryl der jüngling","die weitschreiter-lodge","jagdherausforderung","loch modan","berggeier","quest auf zeit"},ang={["class:Hunter"]="Als Jäger könnt Ihr einen prahlerischen Anfänger auf seinem eigenen Jagdgrund übertreffen und einen zuverlässigen Bogen oder ein Gewehr erringen.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr in der Weitschreiter-Lodge, einem Außenposten an den südöstlichen Straßen von Loch Modan, Zuflucht finden und zu Jagden durch die zerklüfteten Täler aufbrechen.",["race:Dwarf"]="Als Zwerg kennt Ihr die erfahrenen Jäger der Lodge und könnt der leeren Prahlerei dieses jungen Menschen mit stillem Können begegnen."},sec={{t="Die Arroganz eines jungen Schützen",b="Daryl nennt sich Daryl den Kühnen und tut Reisende als Grünschnäbel ab, die seiner Jagdkunst nicht gewachsen sind. Dann verweist er Euch auf die Berggeier, die an den nahen Felsen und Hängen rund um die Lodge nach Aas suchen."},{t="Die Aasfresser dezimieren",b="Die Jagd stellt Eure Schnelligkeit, Geduld und Treffsicherheit gegen den schnellen Flug der Geier auf die Probe. Erlegt alle sechs, bevor die Zeit abläuft, und Daryl rückt widerwillig eine seiner Fernkampfwaffen heraus. Er bietet Euch auch weitere Jagdmutproben an."}},faq={{q="Wo findet diese Jagdherausforderung statt?",a="Die Herausforderung beginnt in der Weitschreiter-Lodge im Südosten von Loch Modan. Berggeier streifen um die nahen Felsen und über offene Bergrücken im gesamten Gebiet.",al={"questort","wo ist daryl","wo sind geier"}},{q="Wer ist Daryl der Jüngling?",a="Daryl der Jüngling ist ein prahlerischer junger Mensch, der sich in der Weitschreiter-Lodge aufhält. Er nennt sich Daryl den Kühnen und verspottet Reisende mit Jagden auf Zeit, um seine eingebildete Überlegenheit zu beweisen.",al={"wer ist daryl","geschichte von daryl dem kühnen","daryl farstrider"}},{q="Warum gibt es bei der Jagd ein Zeitlimit?",a="Das Zeitlimit von fünfzehn Minuten gehört zu Daryls Wette. Er glaubt, dass ein gewöhnlicher Reisender unter Zeitdruck keine wilden Geier erlegen kann.",al={"warum fünfzehn minuten","zeitlimit bei der quest","prüfung auf zeit"}},{q="Was geschieht, nachdem Ihr Daryls Herausforderung gemeistert habt?",a="Daryl ist schockiert, wenn Ihr Erfolg habt, weigert sich aber, seine Niederlage einzugestehen. Er löst seinen Wetteinsatz mit einer Waffe ein und bietet Euch dann eine weitere Jagd auf größeres Wild an: Die Herausforderung eines Jägers.",al={"what comes next","folgequest zum prahlen","jägerquestreihe"}},{q="Warum werden ausgerechnet Berggeier gejagt?",a="Berggeier sammeln sich an den felsigen Hängen von Loch Modan. Ihr schneller Flug stellt die Disziplin eines Bogen- oder Gewehrschützen im Gelände auf die Probe.",al={"warum geier","zweck der geier","geier in loch modan"}},{q="Hängt diese Quest mit den übrigen Aufgaben der Weitschreiter-Lodge zusammen?",a="Daryls Jagden führen in eine umfangreichere Aufgabenreihe für die Lodge. Sie endet mit einer Jagd auf Ol' Sooty, den Bären, der Daryl seine Narben zufügte, als Teil von Vyrin Swiftwinds Racheplan gegen ihn.",al={"verbindung zu vyrin","geschichte der lodge","farstrider handlungsstrang"}}},fx={["4c8cb4f1"]={q="Warum fordert Euch Daryl der Jüngling heraus, Geier zu jagen?",a="Daryl hält große Stücke auf seine eigenen Fähigkeiten und will angeben. Er nennt sich selbst 'Daryl der Kühne', blickt auf Reisende herab, die durch die Weitschreiter-Lodge ziehen, und erwartet, dass Ihr scheitert. Er setzt seine eigene Jagdwaffe auf eine knappe fünfzehnminütige Wette, nur um zu beweisen, dass ein Außenstehender seiner Meisterschaft nicht das Wasser reichen kann.",al={"warum will daryl das erledigt haben","motiv daryl","warum herausforderung daryl"}},["3b45bb0a"]={q="Warum jagt Daryl die Geier nicht selbst?",a="Daryl bittet nicht um Unterstützung und versucht auch nicht, die Geier zur Sicherheit zu dezimieren; er bietet eine prahlerische Sportwette an. Er hält die Aufgabe für unter seiner Würde und geht davon aus, dass ein unerprobter Abenteurer nicht sechs Vögel innerhalb von fünfzehn Minuten erlegen kann, was es ihm erlaubt zu prahlen, wenn Ihr zwangsläufig scheitert.",al={"warum ich daryl","warum jagt daryl keine geier","warum fragt daryl mich"}}},fp="16,134,28.214.0,23.220.0,45.141.0,27.179.0,38.131.0,45.163.1,40.127.0,62.171.1"}
P.entries["quest:258"] = {n="Die Herausforderung eines Jägers",s="In der Weitschreiter-Lodge fordert Daryl der Jüngling Euch heraus, binnen zwölf Minuten fünf uralte Gebirgsbergeber zu erlegen. Er erwartet, dass Ihr am rauen Hochland und der gefährlichen Tierwelt von Loch Modan scheitert.",h="In der Weitschreiter-Lodge fordert Daryl der Jüngling Euch heraus, binnen zwölf Minuten fünf uralte...",kw={"eber","coldridgetal","daryl","uralter gebirgsbergeber","die weitschreiter-lodge","jagd","loch modan","jüngling"},ang={["class:Hunter"]="Als Jäger stellt Ihr Euer Geschick im Umgang mit der Jagdbeute auf die Probe, indem Ihr fünf uralte Gebirgsbergeber im Hochlandgestrüpp aufspürt und innerhalb einer strengen Frist erlegt.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr die Weitschreiter-Lodge als Stützpunkt für Waldläufer betrachten, die Loch Modans Ostgrenze vor wilden Bestien und Gefahren aus dem Hochland schützen.",["race:Dwarf"]="Als Zwerg, der im Coldridgetal seine ersten Schritte gemacht hat, werdet Ihr Daryls Vergleich verstehen, auch wenn seine herablassende Art schwerer zu ertragen sein mag."},sec={{t="Die Prahlerei eines Jünglings",b="Daryl der Jüngling lebt unter den erfahrenen Waidmännern der Weitschreiter-Lodge, doch ihm fehlt ihre ruhige Geduld. Er überspielt seine Jugend mit Prahlerei und langen Jagdgeschichten, darunter ausschweifende Erzählungen darüber, wie er zu seiner „berühmten“ Narbe kam. Er weigert sich, das Können anderer anzuerkennen. Außerdem verwechselt er ständig die Namen seiner Mitjäger und stellt Neuankömmlingen strenge Prüfungen, um sie zu demütigen und sein Ansehen unter den Bewohnern der Lodge wiederherzustellen."},{t="Die Jagd im Hochland",b="Uralte Gebirgsbergeber streifen durch die Felsen und Hänge von Loch Modan. Sie sind gewaltig und dickhäutig und werden gefährlich, wenn man sie reizt. Daryl gibt Euch zwölf Minuten, um fünf zu finden und zu erlegen. Schafft Ihr es rechtzeitig, macht der großmäulige Jüngling einen verlegenen Rückzieher und behauptet, nichts von der überzogenen Wette zu wissen, die er so leichtfertig eingegangen ist."}},faq={{q="Wer ist Daryl der Jüngling?",a="Daryl ist ein junger, prahlerischer menschlicher Waidmann in der Weitschreiter-Lodge im südöstlichen Loch Modan. Weil er unbedingt ebenso eindrucksvoll wirken will wie die älteren Veteranen um ihn herum, prahlt er mit seinem Können, erfindet großartige Geschichten und fordert vorbeiziehende Abenteurer zu schwierigen Jagden heraus.",al={"wer ist daryl","daryl der jüngling hintergrund","weitschreiter-lodge daryl"}},{q="Wo sind die uralten Gebirgsbergeber zu finden?",a="Uralte Gebirgsbergeber streifen durch die Ausläufer, Wiesen und Höhenzüge rund um die Weitschreiter-Lodge sowie durch den Süden und Osten von Loch Modan. Sie grasen auf den Anhöhen zwischen der Lodge und dem See in der Mitte.",al={"uralte gebirgsbergeber fundort","wo eber finden","eberjagd gebiet"}},{q="Warum ist diese Jagd zeitlich begrenzt?",a="Daryl gibt Euch nur zwölf Minuten, weil er erwartet, dass Ihr scheitert. Die Frist ist knapp, und er hofft, Euch damit bloßzustellen und zu beweisen, dass Eure früheren Jagderfolge Anfängerglück waren.",al={"warum zwölf minuten","warum zeitlich begrenzt","jägerherausforderung zeitlimit"}},{q="Welche Wette ist Daryl eingegangen?",a="Daryl setzt sein letztes Hemd darauf, dass Ihr nicht rechtzeitig fünf uralte Gebirgsbergeber erlegt. Als Ihr siegreich zurückkehrt, behauptet er rasch, sich nicht mehr an die Wette erinnern zu können.",al={"daryls wette","sein letztes hemd","was hat daryl gewettet"}},{q="Wie unterscheiden sie sich von den Ebern im Coldridgetal?",a="Die uralten Gebirgsbergeber von Loch Modan sind zäher und angriffslustiger als die kleineren Eber, die unerfahrene Zwerge im Coldridgetal jagen. Ihre Häute sind dicker, und ihre gefährlichen Hauer sind am Granit des Hochlands geschärft.",al={"eber im coldridgetal gegen gebirgsbergeber","coldridgetal vergleich"}},{q="Wohin führt diese Jagdreihe als Nächstes?",a="Nachdem Ihr Daryls Herausforderung gemeistert und seine Prahlerei zum Verstummen gebracht habt, wendet man sich in der Lodge ernsteren Angelegenheiten zu: einer Konfrontation mit dem gefährlichen alten Bären Ol' Sooty in Vyrin's Revenge.",al={"welche quest kommt als nächstes","nach die herausforderung eines jägers","jagdquestreihe"}}},fx={["4ae04a68"]={q="Was sind die Älteren Gebirgseber?",a="Ältere Gebirgseber sind kampferprobte, zähe Bestien, die in den Felsen und Hügeln um Loch Modan heimisch sind. Im Gegensatz zu den kleineren Ebern, die an Orten wie dem Coldridgetal umherstreifen, sind diese Kreaturen weitaus widerstandsfähiger und gefährlicher, wenn man sie in die Enge treibt. Daryl wählt sie gezielt aus, um Eure Spür- und Kampffertigkeiten bis an ihre Grenzen zu testen, in der Erwartung, dass Ihr unter dem knappen Zeitlimit scheitert.",al={"ältere gebirgseber loch modan","warum ältere eber","wer sind die eber"}},["33153764"]={q="Warum schickt Daryl Euch auf diese Jagd, anstatt selbst zu jagen?",a="Daryl der Jüngling zieht es vor, in der Weitschreiter-Lodge Hof zu halten und großspurige Geschichten darüber zu erzählen, wie er zu seiner berühmten Narbe kam, anstatt durch die Wildnis zu stapfen. Überzeugt von seinem eigenen überlegenen Können, stellt er diese eskalierenden Prüfungen nur auf, um Euch zu demütigen und sein selbst ernanntes Ansehen unter den Jägern zu wahren.",al={"warum jagt daryl nicht","warum braucht daryl mich"}}},fp="20,188,15.446.0,17.327.0,27.255.0,43.198.0,23.188.0,24.165.0,48.217.0,40.191.1"}
P.entries["quest:26"] = {n="Eine wertvolle Lektion",s="In Darnassus schickt Mathrengyl Bärenfährte junge Druiden zur Mondlichtung, um die Wege des Wassers zu erlernen. Dort begleitet ein Ältester des Zirkels des Cenarius ihre ersten Schritte auf dem Weg zur Aquatic Form.",h="In Darnassus schickt Mathrengyl Bärenfährte junge Druiden zur Mondlichtung, um die Wege des Wassers zu...",kw={"eine wertvolle lektion","aquatic form","darnassus","dendrite sternenschauer","druidenquest","mathrengyl bärenfährte","mondlichtung","nachthafen"},ang={["class:Druid"]="Als Druide erreicht Ihr einen Meilenstein Eurer Ausbildung und erschließt Euch den Weg, unter den Wellen mit Cenarius' Gaben in Zwiesprache zu treten.",["race:NightElf"]="Als Kaldorei aus Darnassus ehrt Ihr die Tradition, indem Ihr dem Ruf des Zirkels des Cenarius in die Mondlichtung folgt und Euch mit Euren uralten Lehrern verbindet."},sec={{t="Der Ruf der Wildnis",b="Mathrengyl Bärenfährte leitet junge Nachtelfendruiden an, die im Geäst von Darnassus üben. Wenn ein Initiand eine feste Bindung zur Natur zeigt und für größere Verantwortung bereit ist, schickt Mathrengyl ihn aus, die Gewässer zu meistern. Cenarius' Gaben verlangen Konzentration. Um die Tiefen zu durchqueren, ohne zu ertrinken, brauchen junge Druiden die Führung der Ältesten des Zirkels des Cenarius."},{t="Reise nach Nachthafen",b="Ihr verlasst Darnassus und reist zur Mondlichtung, einer uralten Zuflucht unterhalb des Hyjal. In Nachthafen wartet Dendrite Sternenschauer als erfahrener Mentor des Zirkels des Cenarius. Sternenschauer beurteilt, ob junge Gestaltwandler für die Prüfungen bereit sind, die zur Aquatic Form führen. Das Wasser zu meistern erfordert körperliche Widerstandskraft und geistige Entschlossenheit."}},faq={{q="Wer schickt mich auf diese Quest?",a="Mathrengyl Bärenfährte, ein Druidenlehrer in der Enklave des Cenarius in Darnassus, schickt Euch los, sobald Eure anfängliche Druidenausbildung weit genug fortgeschritten ist.",al={"questgeber","wer vergibt eine wertvolle lektion","wer startet das"}},{q="Was ist das Ziel dieser Quest?",a="Ihr beginnt den Weg zur Aquatic Form, indem Ihr zur Mondlichtung reist, um Euch vom Ältesten Dendrite Sternenschauer unterweisen und prüfen zu lassen.",al={"warum diese quest machen","einstieg in aquatic form","was bekomme ich"}},{q="Wo befindet sich Dendrite Sternenschauer?",a="Dendrite Sternenschauer lebt in Nachthafen, am Nordufer des Sees von Elune'ara in der Mondlichtung.",al={"dendrites standort","wo ist dendrite sternenschauer","dendrite finden"}},{q="Wie erreichen Druiden die Mondlichtung für diese Quest?",a="Ihr könnt Teleport: Mondlichtung nutzen, um geleitet von Eurer spirituellen Verbundenheit direkt zum heiligen Hain zu reisen.",al={"wie zur mondlichtung gelangen","nach nachthafen gelangen"}},{q="Was folgt nach dem Gespräch mit Dendrite Sternenschauer?",a="Nachdem Ihr mit Dendrite Sternenschauer gesprochen habt, schickt er Euch zur Trial of the Lake. Dort werden Eure Ausdauer und geistige Klarheit unter Wasser auf die Probe gestellt.",al={"nächste quest","was kommt als nächstes","nach eine wertvolle lektion"}}},fx={["67389e7a"]={q="Warum schickt Euch Mathrengyl Bärenfährte nach Mondlichtung?",a="Mathrengyl Bärenfährte hat Euer Heranwachsen beobachtet und glaubt, dass Ihr bereit seid, Eure Verbindung zur Wildnis zu vertiefen. Die von Cenarius verliehenen Tieraspekte erfordern eine gründlichere Unterweisung, als eine gewöhnliche Ausbildung bieten kann. Um die Geheimnisse der aquatischen Meisterschaft zu erlernen, weist er Euch den Weg zu Dendrite Sternenschauer und dem Zirkel des Cenarius in Nachthafen, wo uralte druidische Prüfungen beaufsichtigt werden.",al={"warum mathrengyl euch schickt","mathrengyl bärenfährte beweggrund","warum nach mondlichtung reisen"}}},fp="17,180,20.365.0,21.318.0,27.137.0,34.126.0,36.94.0,45.108.0,48.147.0"}
P.entries["quest:2605"] = {n="Der durstige Goblin",s="In Gadgetzan sehnt sich Marin Noggenfogger nach einem Getränk, das seinen endlosen Durst stillen kann. Er hat gehört, dass die Tautropfensammler im Kaktusgarten südwestlich der Stadt Wasser in speziellen Drüsen speichern, und hofft, dass eine davon solch ein Getränk möglich macht.",h="In Gadgetzan sehnt sich Marin Noggenfogger nach einem Getränk, das seinen endlosen Durst stillen kann.",kw={"kaktusgarten","tautropfensammler","taudrüse","gadgetzan","marin noggenfogger","tanaris","disteltal"},sec={{t="Eine Drüse zum Trinken",b="Marin Noggenfogger hat von Tautropfensammlern im Kaktusgarten südwestlich von Gadgetzan gehört. Sie speichern Wasser in speziellen Drüsen, und er glaubt, eine volle Drüse könnte die Grundlage für ein Getränk sein, das seinen Durst endgültig stillt. Er bittet Euch, ihren Garten zu finden und eine mitzubringen."}},faq={{q="Wer schickt Euch auf die Suche nach der Taudrüse?",a="Marin Noggenfogger in Gadgetzan bittet Euch, eine volle Taudrüse zu finden, in der Hoffnung, dass sie seinen schrecklichen Durst stillt.",al={"der durstige goblin questgeber","wer startet der durstige goblin","marin noggenfogger"}},{q="Wo befinden sich die Tautropfensammler?",a="Die Tautropfensammler leben im Kaktusgarten des Disteltals, südwestlich von Gadgetzan in Tanaris.",al={"tautropfensammler fundort","wo taudrüse finden","kaktusgarten fundort"}},{q="Welche Kreatur trägt die prall gefüllte Taudrüse?",a="Die Disteltausammler tragen die Drüsen, die angeblich Wasser speichern.",al={"wer lässt prall gefüllte taudrüse fallen","tautropfensammler gegner"}},{q="Wie geht die Questreihe weiter?",a="Die Questreihe wird mit In Good Taste fortgesetzt.",al={"der durstige goblin folgequest","nächste quest nach der durstige goblin"}}},fp="18,232,22.259.0,40.107.0,37.103.0,42.76.0,29.39.0"}
P.entries["quest:2606"] = {n="Dem guten Geschmacke",s="Marin Noggenfogger findet Disteltau scheußlich, arbeitet aber weiter an dem Gebräu. Er schickt Euch mit dem Tau zu Sprinkle in Gadgetzan.",h="Marin Noggenfogger findet Disteltau scheußlich, arbeitet aber weiter an dem Gebräu.",kw={"gadgetzan","dem guten geschmacke","marin noggenfogger","sprinkle","tanaris","disteltau"},sec={{t="Eine Köchin für ein schlechtes Gebräu",b="Marin Noggenfogger probiert den Tau und findet ihn scheußlich. Trotzdem arbeitet er weiter an dem Getränk. Er schickt Euch zu Sprinkle, seiner Freundin in Gadgetzan und einer hervorragenden Köchin. Ihr bringt den Tau zu ihr und erklärt, dass das Getränk leichter die Kehle hinuntergehen muss. Marin möchte außerdem, dass es etwas Biss hat."}},faq={{q="Wo gehört dieser Schritt in die Questreihe?",a="Er folgt auf The Thirsty Goblin, und danach kommt Sprinkle's Secret Ingredient.",al={"welche quest kommt davor","was kommt als nächstes in der questreihe","questverlauf"}},{q="Warum möchte Marin Noggenfogger den Tau zu Sprinkle bringen lassen?",a="Marin Noggenfogger findet den Tau scheußlich. Er hofft, dass Sprinkle, die er als hervorragende Köchin bezeichnet, ihn leichter trinkbar machen und ihm etwas Biss verleihen kann.",al={"warum sprinkle","was will marin von sprinkle","wer ist sprinkle"}},{q="Wo ist Sprinkle zu finden?",a="Sprinkle ist in Gadgetzan, derselben Stadt wie Marin Noggenfogger.",al={"sprinkles standort","wo ist sprinkle","sprinkle finden"}}},fp="13,143,21.278.0,38.75.0,59.155.0,28.62.0"}
P.entries["quest:2608"] = {n="The Touch of Zanzil",s="Doc Mixilpixil untersucht Euch und sucht nach der Ursache für Euren besorgniserregenden Zustand. Er bittet darum, Euch Blut abzunehmen, bevor er sich mit seinen Kollegen über ein Heilmittel berät.",h="Doc Mixilpixil untersucht Euch und sucht nach der Ursache für Euren besorgniserregenden Zustand.",kw={"blut","heilmittel","doc mixilpixil","dr. montgomery","untersuchung","mr. noarm","the touch of zanzil","zanzil"},sec={{t="Die Untersuchung",b="Doc Mixilpixil findet, dass Ihr schlimmer ausseht als der Tod, und sagt, er brauche eine Blutprobe, um Euch zu helfen. Ihr könnt Euch für seine Untersuchung hinlegen, doch seine Warnung deutet darauf hin, dass die Behandlung wehtun könnte. Sobald er Euch untersucht hat, ruft er Dr. Montgomery und Mr. Noarm, um sich über Euren Fall zu beraten."}},faq={{q="Wer untersucht mich?",a="Doc Mixilpixil untersucht Euch und bittet darum, Euch Blut abzunehmen, damit er nach der Ursache für Euren Zustand suchen kann.",al={"doc mixilpixil","wer ist der arzt","mixilpixil"}},{q="Warum will Doc Mixilpixil mein Blut?",a="Doc Mixilpixil sagt, er brauche eine Blutprobe, um die Ursache zu finden und Euch zu helfen.",al={"blutprobe","warum blut","blut abnehmen"}},{q="Wer sind Dr. Montgomery und Mr. Noarm?",a="Dr. Montgomery und Mr. Noarm sind die Kollegen von Doc Mixilpixil, die er ruft, um sich über Euren Fall zu beraten.",al={"montgomery und noarm","kollegen von doc","noarm"}},{q="Was geschieht nach der Untersuchung?",a="Nachdem er Euch untersucht hat, ruft Doc Mixilpixil Dr. Montgomery und Mr. Noarm, um sich zu beraten.",al={"nach der untersuchung","was als nächstes","ärzteberatung"}}},fp="19,143,15.274.0,20.98.0,38.75.0,37.102.0,35.81.0"}
P.entries["quest:2609"] = {n="The Touch of Zanzil",s="Doc Mixilpixil bittet Euch, Vorräte gegen die 'itis' zu besorgen. Er sagt, das Leiden werde nicht von selbst heilen.",h="Doc Mixilpixil bittet Euch, Vorräte gegen die 'itis' zu besorgen.",kw={"bronze tube","doc mixilpixil","itis","leaded vial","light chartreuse silk thread","simple wildflowers","zanzil"},sec={{t="Die Bitte eines Arztes",b="Doc Mixilpixil braucht Eure Hilfe: Ihr sollt ihm Simple Wildflowers, ein Leaded Vial, eine Bronze Tube und eine Spool of Light Chartreuse Silk Thread bringen. Er sagt, die 'itis' müsse geheilt werden, und bittet Euch, diese Vorräte zu bringen."}},faq={{q="Wer bittet um diese Vorräte?",a="Doc Mixilpixil bittet Euch, die Vorräte zu bringen.",al={"wer will sie","doc mixilpixils bitte"}},{q="Was braucht Doc Mixilpixil?",a="Er braucht Simple Wildflowers, ein Leaded Vial, eine Bronze Tube und eine Spool of Light Chartreuse Silk Thread.",al={"welche gegenstände","vorratsliste"}},{q="Was ist die 'itis'?",a="Doc Mixilpixil nennt das Leiden die 'itis'.",al={"welche krankheit","itis"}}},fp="19,100,18.214.0,33.46.0,30.103.0,19.44.0"}
P.entries["quest:261"] = {n="Auf dem Scharlachroten Pfad",s="An der Nijelspitze fordert Bruder Anton Euch auf, Eure Treue zum Scharlachroten Kreuzzug zu beweisen.",h="An der Nijelspitze fordert Bruder Anton Euch auf, Eure Treue zum Scharlachroten Kreuzzug zu beweisen.",kw={"bruder anton","desolace","auf dem scharlachroten pfad","die nijelspitze","scharlachroter kreuzzug","geißel","untoter verheerer","tal der knochen"},sec={{t="Beweis der Treue",b="Bruder Anton sagt, die Geißel müsse aufgehalten werden, bevor sie das Land verschlingt und die Welt in Dunkelheit stürzt. Der Scharlachrote Kreuzzug hat sich diesem Kampf verschrieben. Um Euren Mut und Eure Treue zu beweisen, vernichtet dreißig untote Verheerer im Tal der Knochen, südlich von Anton. Wenn Ihr Erfolg habt, wird der Kreuzzug Euch willkommen heißen."}},faq={{q="Wer fordert Euch auf, die untoten Verheerer zu vernichten?",a="Bruder Anton vom Scharlachroten Kreuzzug fordert Euch an der Nijelspitze dazu auf.",al={"wer vergibt auf dem scharlachroten pfad","bruder anton quest","scharlachroter kreuzzug desolace npc"}},{q="Wo sind die untoten Verheerer zu finden?",a="Die untoten Verheerer befinden sich im Tal der Knochen, südlich der Nijelspitze in Desolace.",al={"fundort untoter verheerer","wo ist das tal der knochen","verheerer in desolace"}},{q="Warum will Bruder Anton die Verheerer vernichtet sehen?",a="Bruder Anton sagt, der Kreuzzug bekämpfe die Geißel, die Menschen verdirbt und das Land verseucht. Er bittet Euch, Eure Treue zu beweisen.",al={"warum untote verheerer töten","bruder antons beweggrund","grund des scharlachroten kreuzzugs"}},{q="Wie viele Verheerer müssen vernichtet werden?",a="Ihr müsst dreißig Verheerer vernichten.",al={"wie viele verheerer","anzahl der verheerer"}},{q="Was kommt davor?",a="Ihr begegnet zuerst Bruder Anton.",al={"vorherige quest","voraussetzung für auf dem scharlachroten pfad"}}},fp="21,93,19.315.0,44.63.0,36.83.0,51.132.0,36.33.0,23.29.0"}
P.entries["quest:262"] = {n="Die Schattengestalt",s="Bei seinem zerstörten Hof sucht Sven Yorgen den Fremden, der seine Familie sterben sah. Er gibt Euch ein seltsames Buch aus den Trümmern und bittet Euch herauszufinden, wer es zurückgelassen hat.",h="Bei seinem zerstörten Hof sucht Sven Yorgen den Fremden, der seine Familie sterben sah.",kw={"buch","dunkelhain","dämmerwald","madame eva","schattengestalt","sven yorgen","sven's camp"},ang={["class:Priest"]="Als Priester erkennt Ihr, wie spirituelle Hellsicht, Shadow Magic und die Eindrücke, die an gewöhnlichen Gegenständen haften, einander berühren können.",["faction:Alliance"]="Dunkelhain erhält wenig Unterstützung aus Sturmwind. Seine traumatisierten Grenzlandbewohner und örtlichen Seher verlassen sich auf umherziehende Champions der Allianz, um tödliche Gräueltaten im Dämmerwald zu untersuchen."},sec={{t="Nachhall eines Gemetzels",b="In den westlichen Hügeln des Dämmerwalds trauert Sven Yorgen noch immer um seine ermordete Familie. Einst gab er den schwarzen Reitern die Schuld, die die Wälder terrorisieren. Doch er erinnert sich an eine Schattengestalt, die in der Nacht des Massakers in der Nähe war. Sven gibt Euch das seltsame Buch, das auf seinem verwüsteten Hof gefunden wurde, den einzigen greifbaren Hinweis in den Trümmern."},{t="Wahrsagung in der Stadt",b="Ohne klare Spur durch die gefährliche Wildnis zieht Ihr ostwärts nach Dunkelhain. Sven hofft, dass einer der abergläubischen Stadtbewohner das sonderbare Buch wiedererkennt. Madame Eva ist eine von ihnen, und ihre okkulten Sinne reichen über das gewöhnliche Sehvermögen hinaus. Ihre Wahrsagungen könnten Eindrücke offenbaren, die auf geheimnisvollen Relikten zurückgeblieben sind."},{t="Fäden aus der Fremde",b="Madame Eva liest schwache Eindrücke aus dem Buch. Svens jüngstes Verlangen nach Rache hat seine Seiten geprägt. Unter dieser Prägung liegt eine andere Präsenz. Eva spürt, dass der erste Besitzer von außerhalb Dunkelhains und des Dämmerwalds kam und den Hof besucht hatte, bevor das Blutvergießen begann."}},faq={{q="Wer ist Sven Yorgen?",a="Sven Yorgen ist ein gebrochener Bauer, der im Exil in den westlichen Hügeln des Dämmerwalds lebt. Nachdem dunkle Reiter seine Familie auf ihrem Hof niedergemetzelt hatten, trieb ihn die Trauer in die Wildnis. Dort sucht er Rache an den Verantwortlichen.",al={"wer ist sven","svens vorgeschichte","sven yorgen"}},{q="Was ist das Buch von Svens Hof?",a="Das Buch ist ein greifbares Artefakt, das aus dem Schmutz und den Trümmern von Svens zerstörtem Hof geborgen wurde. Ein schwer zu fassender Beobachter ließ es zurück, nachdem er während des Angriffs auf Svens Familie in den Schatten gelauert hatte.",al={"was ist das für ein buch","buch von svens hof","geheimnisvolles buch"}},{q="Warum das Buch zu Madame Eva bringen?",a="Madame Eva ist die ansässige Seherin und Wahrsagerin von Dunkelhain. Gewöhnliche Stadtbewohner können einem Band ohne Kennzeichnung wenig entnehmen, doch ihre Hellsicht lässt sie Eindrücke derer lesen, die ihn zuvor besessen oder getragen haben.",al={"warum madame eva","wer liest das buch","mystikerin von dunkelhain"}},{q="Was erfährt Madame Eva aus dem Buch?",a="Madame Eva spürt, dass Svens jüngster Umgang mit dem Buch einen mächtigen Abdruck seiner Rachegelüste hinterlassen hat. Darunter erkennt sie schwache Spuren, die zeigen, dass der erste Besitzer von außerhalb Dunkelhains kam.",al={"was sagt eva","identität des buchbesitzers","ergebnis der wahrsagung"}},{q="Wohin führt diese Untersuchung als Nächstes?",a="Madame Eva erfährt, dass der Besitzer des Buches von außerhalb Dunkelhains kam. Sie schickt Euch los, die Stadtaufzeichnungen und vertraute Orte nach jemandem zu durchsuchen, der sich an einen unbekannten Reisenden wie diese Gestalt erinnert.",al={"was kommt als nächstes","nächste quest nach dem buch","wer ist die schattengestalt"}}},fx={d371091b={q="Warum will Sven Yorgen, dass dies erledigt wird?",a="Sven ist von Trauer und einem verzweifelten Bedürfnis nach Antworten verzehrt. In der Nacht, als seine Familie auf seinem Hof abgeschlachtet wurde, sah er eine geheimnisvolle Gestalt im Schatten lauern. Er glaubt, dass die Identität dieses Schleichers zu entdecken seine einzige Chance ist, die Wahrheit hinter dem Massaker zu erfahren und Gerechtigkeit zu sehen.",al={"warum will sven, dass die schattenhafte gestalt gefunden wird","motiv sven yorgen","warum besitzer des buches finden"}},["35559963"]={q="Warum bittet Sven Yorgen Euch und nicht die The Nachtwache?",a="Sven ist ein isolierter, traumatisierter Einsiedler, der sich in der Wildnis von Dämmerwald versteckt, weit weg von Dunkelhain. Ihr habt Eure Findigkeit bereits bewiesen, indem Ihr das zerstörte Tagebuch auf seinem verwüsteten Gehöft entdeckt habt, was ihn davon überzeugt hat, dass Ihr den nötigen Schneid und die nötige Gerissenheit besitzt, um das Geheimnis zu lüften, wenn es sonst niemand tut.",al={"warum fragt sven nicht die the night watch","warum braucht sven meine hilfe","warum ich sven yorgen"}}},fp="18,172,21.313.0,26.302.0,15.275.1,19.232.0,38.201.0,32.213.0,41.191.1,40.199.1"}
P.entries["quest:2622"] = {n="Die fehlenden Befehle",s="Zentralen-Kommandant Ruag schickt Euch zu Bengor, nachdem die Befehle verschwunden sind.",h="Zentralen-Kommandant Ruag schickt Euch zu Bengor, nachdem die Befehle verschwunden sind.",kw={"hinterhalt","bengor","zentralen-kommandant ruag","fehlende befehle","murloc","sümpfe des elends"},sec={{t="Ruags Bericht",b="Zentralen-Kommandant Ruag reagiert gereizt, als Ihr nach den verschwundenen Befehlen fragt. Er sagt, sie seien mit den Soldaten verschwunden, die sie überbringen sollten. Murlocs haben die Soldaten überfallen und brutal zusammengeschlagen, und nur einer hat überlebt. Bengor kann kaum sprechen, kann nicht gehen und wird durch einen Schlauch ernährt. Ruag schickt Euch los, um ihn in der Nähe zu finden, und warnt Euch dann, darauf zu achten, worin Ihr Eure Nase steckt."},{t="Bengors stockende Worte",b="Bengor bringt nur abgehackte Sprachfetzen hervor. Darunter versteht Ihr die Worte swamp talker."}},faq={{q="Wer gab die Befehle, die verloren gingen?",a="Zentralen-Kommandant Ruag sagt, die Befehle seien mit den ausgesandten Soldaten verschwunden. Er reagiert abwehrend, als Ihr fragt, was aus ihnen geworden ist.",al={"wer gab die verschwundenen befehle","wer verlor die befehle"}},{q="Was geschah mit den Soldaten, die die Befehle überbringen sollten?",a="Zentralen-Kommandant Ruag sagt, Murlocs hätten die Soldaten, die die Befehle überbringen sollten, überfallen und brutal zusammengeschlagen. Nur einer hat überlebt.",al={"was geschah mit den kurieren","wie gingen die befehle verloren"}},{q="Wer ist Bengor?",a="Bengor ist der einzige Überlebende des Überfalls. Er kann kaum sprechen, kann nicht gehen und wird durch einen Schlauch ernährt.",al={"wer ist der überlebende","bengor lore"}},{q="Wo kann Bengor gefunden werden?",a="Zentralen-Kommandant Ruag sagt, Bengor sei irgendwo in der Nähe.",al={"bengor aufenthaltsort","wo ist bengor"}}},fp="18,77,14.352.0,22.93.1,38.125.0,50.116.0,14.103.0,26.56.0"}
P.entries["quest:2623"] = {n="Der Sumpfredner",s="Befehle für die Verwüsteten Lande verschwinden bei einem Murloc-Hinterhalt. Bengor erzählt Euch, was geschah, bevor er das Bewusstsein verliert.",h="Befehle für die Verwüsteten Lande verschwinden bei einem Murloc-Hinterhalt.",kw={"bengor","verwüstete lande","gefallener held der horde","murloc","sümpfe des elends","sumpfredner","kriegshäuptlingsbefehle"},sec={{t="Bengors bruchstückhafter Bericht",b="Bengor sagt, der Kommandeur der Depeschen habe die Befehle ausgegeben. Seine Gruppe war auf dem Weg in die Verwüsteten Lande, als viele Murlocs über sie herfielen. Einer von ihnen, der Sumpfredner, entriss Bengor die Befehle, als ein Speer Bengors Schädel traf. Bevor er das Bewusstsein verliert, spricht Bengor von einer Höhle im Osten. Beschafft die Befehle wieder und bringt sie zum Gefallenen Helden der Horde."},{t="Die Abrechnung des Gefallenen Helden",b="Der Gefallene Held der Horde erkennt, dass der Preis höher ist als gedacht. Neunzehn Männern des Helden wären vielleicht Qualen erspart geblieben, wenn der Held nicht so unbesonnen gehandelt hätte. Da der Held ihnen selbst nicht helfen kann, bittet er Euch, diesen Männern beizustehen."}},faq={{q="Wer hat die Kriegshäuptlingsbefehle gestohlen?",a="Während des Hinterhalts nahm ein Murloc namens Sumpfredner die Befehle aus Bengors Händen.",al={"wer nahm die befehle","wer ist der sumpfredner","wer stahl die befehle"}},{q="Wohin ist der Sumpfredner gegangen?",a="Als Bengor das Bewusstsein schwindet, spricht er von einer Höhle im Osten.",al={"wo ist der sumpfredner","sumpfredner aufenthaltsort","wo ist die murloc-höhle"}},{q="Wohin waren Bengor und seine Einheit unterwegs?",a="Bengor und seine Einheit brachten Befehle vom Kommandeur der Depeschen in die Verwüsteten Lande, als Murlocs sie aus dem Hinterhalt überfielen.",al={"bengors ziel","wohin war bengor unterwegs","ziel von bengors einheit"}},{q="Wem sollen die Befehle zurückgebracht werden?",a="Bringt die Befehle zum Gefallenen Helden der Horde.",al={"wer bekommt die kriegshäuptlingsbefehle","wo die befehle abgeben","sumpfredner-quest abgeben"}}},fp="16,123,23.342.0,27.223.1,32.83.0,30.49.0,39.117.0,38.48.0"}
P.entries["quest:263"] = {n="Verteidigung der Länder des Königs",s="Am südlichen Wachturm ruft Gebirgsjäger Wallbang Reisende auf, Loch Modan gegen die Splittersteintroggs zu verteidigen. Da Eisenschmiedes Reserven an ferne Fronten entsandt wurden, ist der südliche Pass nur schwach besetzt. Wallbang schickt erfahrene Rekruten ins Splittersteintal, um gegen die Schamanen und Knochenknacker des Klans zu kämpfen.",h="Am südlichen Wachturm ruft Gebirgsjäger Wallbang Reisende auf, Loch Modan gegen die Splittersteintroggs zu...",kw={"knochenknacker","eisenschmiede","loch modan","magni","gebirgsjäger","schamane","splitterstein","trogg","wallbang"},ang={["class:Shaman"]="Als Schamane erlebt Ihr im Kampf gegen die Zauberwirker der Splittersteintroggs primitive Erdmagie, die von wilden Instinkten geformt wird.",["faction:Alliance"]="Als Reisender der Allianz schützt Ihr durch Eure Hilfe am südlichen Wachturm wichtige Handels- und Reisewege, die Dun Morogh mit den östlichen Feuchtgebieten und Sturmwind verbinden.",["race:Dwarf"]="Als Zwerg verteidigt Ihr mit Eurer Antwort auf Wallbangs Ruf die Gehöfte Loch Modans, während die stehenden Heere Eures Volkes in die Ferne entsandt werden."},sec={{t="Eine dünne Verteidigungslinie",b="Loch Modans Verteidigung ist bis an ihre Grenzen beansprucht. Eisenschmiedes reguläre Reserven wurden an ferne Fronten in ganz Azeroth gerufen, weshalb dem südlichen Wachturm die nötigen Kräfte fehlen. Gebirgsjäger Wallbang und seine wenigen Kameraden stehen unter ständigem Druck des Splittersteinklans. Sie sind auf durchreisende Angehörige der Allianz angewiesen, um den südlichen Pass zu halten."},{t="Die Splittersteinvorhut im Visier",b="Der Kampf richtet sich nicht mehr nur gegen vereinzelte Späher, sondern gegen die Schlagkraft des Splittersteinklans. Seine Knochenknacker setzen auf brutale Gewalt, während seine Schamanen mit Erdmagie ihresgleichen sammeln. Zwanzig dieser Feinde zu töten, schwächt die Vorstöße des Klans ins Tiefland. Es dient auch König Magni Bronzebarts Verteidigung des Reiches."}},faq={{q="Wer ist Gebirgsjäger Wallbang?",a="Gebirgsjäger Wallbang ist ein Zwerg aus Eisenschmiede, der am südlichen Wachturm in Loch Modan stationiert ist. Er hält nach Troggs Ausschau, die aus den Bergen strömen, und koordiniert die Miliz, um die südliche Hauptstraße zu sichern.",al={"wallbang","wer ist wallbang","geschichte von gebirgsjäger wallbang"}},{q="Warum bitten die Gebirgsjäger Reisende um Hilfe?",a="Eisenschmiedes militärische Reserven wurden an Fronten im ganzen Königreich und darüber hinaus gerufen. Grenzposten wie die südlichen Wachtürme Loch Modans sind im Kampf gegen örtliche Bedrohungen stark unterbesetzt.",al={"warum brauchen zwerge hilfe","wo sind eisenschmiedes wachen","warum keine reserven"}},{q="Wo befinden sich diese Troggs?",a="Die Splittersteintroggs sammeln sich im Splittersteintal, in den zerklüfteten Hügeln südwestlich des Lochs. Kleinere Gruppen von Schamanen und Knochenknackern treiben sich auch auf den nördlichen Inseln im See herum.",al={"wo sind splittersteintroggs","fundort der splittersteinschamanen","wo ist das splittersteintal"}},{q="Was macht den Splittersteinklan zu einer Bedrohung?",a="Troggs vermehren sich rasch und können besiedelte Gebiete in unterirdischen Schwärmen überrennen. Splittersteinschamanen wirken primitive Elementarmagie, während Knochenknacker zwergische Späher angreifen. Nahe gelegene Siedlungen und Handelswege sind in Gefahr.",al={"warum sind troggs gefährlich","bedrohung durch die splittersteine"}},{q="Was tut Gebirgsjäger Wallbang nach dieser Aufgabe?",a="Wallbang ist zufrieden, dass Ihr Euch als Kämpfer im Dienste König Magnis bewiesen habt. Er schickt Euch zu Hauptmann Rugelfuß, um Bericht zu erstatten und weitere Befehle zur Verteidigung Loch Modans entgegenzunehmen.",al={"was kommt nach wallbang","wer ist der hauptmann"}},{q="Wer herrscht während dieser Krise über Eisenschmiede?",a="König Magni Bronzebart regiert das Zwergenreich vom High Seat in Eisenschmiede aus. Die Bemühungen zum Schutz Loch Modans erfolgen in seinem Namen und zur Verteidigung seiner Ländereien.",al={"wer ist der zwergenkönig","könig von eisenschmiede"}}},fx={["20cd043f"]={q="Warum will Gebirgsjäger Wallbang, dass diese Troggs getötet werden?",a="Das Trogg-Problem in ganz Loch Modan verschlimmert sich weiter und bedroht die Sicherheit des Hoheitsgebiets der Eisenschmiede. Da die Reserven der Gebirgsjäger an weit entfernte Fronten abgezogen wurden, sitzen Wallbang und seine Kameraden am südlichen Wachturm ohne Verstärkung fest. Er muss die Trogg-Reihen ausdünnen, um das Tal zu schützen und die Stellung im Namen des Königs zu halten.",al={"warum steinbeißer troggs töten","motiv wallbang","warum will wallbang troggs tot sehen"}},c0ccff20={q="Wer sind die Steinbeißer-Schamanen und Knochenbrecher?",a="Sie sind die spezialisierten Vorhut des Steinbeißer-Troggclans, die in Loch Modan eindringen. Die Knochenbrecher dienen als brutale, schwer zuschlagende Vollstrecker des Clans, während ihre Schamanen rohe, urtümliche Magie kanalisieren. Gemeinsam bilden sie die Kernstärke, die die Troggs aus den Tiefen und in die Zwergenlande treibt.",al={"steinbeißer schamane","steinbeißer knochenbrecher","wer sind die trogg ziele"}}},fp="30,305,19.346.0,36.308.0,28.214.0,51.201.0,31.186.0,43.218.0,50.174.0,39.159.0"}
P.entries["quest:264"] = {n="Bis dass der Tod uns scheidet",s="Im Silberwald schickt Clarice Foster ihr Erinnerungsstück zu Yurivs Grab. Von den Teichen der Visionen unter Donnerfels aus bittet die Verlassene Euch, es auf das Grab ihres Mannes zu legen, der sie und ihre Kinder verließ.",h="Im Silberwald schickt Clarice Foster ihr Erinnerungsstück zu Yurivs Grab.",kw={"clarice foster","kreuzzug","verlassene","anhänger","das grabmal","silberwald","grab","yuriv"},ang={["class:Priest"]="Als Priester könnt Ihr erkennen, wie die Hingabe an das Licht Familien auseinanderreißen und bei den Zurückgelassenen bleibende Bitterkeit hinterlassen kann.",["faction:Horde"]="Als Mitglied der Horde erhaltet Ihr einen Einblick in die persönlichen Tragödien und den anhaltenden Groll, die die Verlassenen im Silberwald verbinden.",["race:Undead"]="Als Verlassener könnt Ihr in Clarices Leid die Heuchelei der Lebenden erkennen. Heilige Krieger ließen ihre Familien in religiösem Eifer zugrunde gehen, während ihre verwandelten Hinterbliebenen die Last der Erinnerung tragen."},sec={{t="Ein bitteres Erinnerungsstück",b="Clarice Foster erinnert sich voller Bitterkeit an ihre Ehe zu Lebzeiten. Als Lordaeron zerfiel, verließ Yuriv sie und ihre Kinder, um sich einem Kreuzzug gegen die aufkommenden Untoten anzuschließen. Er erklärte den Dienst am Heiligen Licht zur höchsten Pflicht. Seine Hingabe rettete weder seine Familie noch ihn selbst. Clarice wurde zum Untod erweckt, während Yuriv unter einem geschändeten Grabstein liegt. Sie will die letzte greifbare Erinnerung an seine gebrochenen Versprechen loswerden."},{t="Das vernachlässigte Grab",b="Yurivs Grab liegt auf dem Friedhof rund um das Grabmal, gezeichnet von Kerben, Müll und Unkraut. Legt Clarices Anhänger auf das Relief seiner gemeißelten Hände. Darauf folgen weder große Magie noch Seelenfrieden. Der Edelstein wird matt, und ein kalter, lautloser Windstoß zieht über die Gräber. Der alte Groll von Lordaerons gefallenem Volk bleibt bestehen."}},faq={{q="Wer war Yuriv?",a="Yuriv war Clarice Fosters Ehemann zu Lebzeiten. Er verließ sie und ihre Kinder, um im Namen des Heiligen Lichts gegen die Geißel zu kämpfen, und stellte seinen Kreuzzug über seine Familie.",al={"wer ist yuriv","yurivs geschichte","clarices ehemann"}},{q="Warum hasst Clarice ihren verstorbenen Mann so sehr?",a="Clarice wartete Nacht für Nacht, während Yuriv seine religiösen Pflichten an erste Stelle setzte. Sein Kreuzzug konnte sie nicht schützen. Er starb in einem vernachlässigten Grab, und sie wurde als eine jener Untoten erweckt, die er bekämpft hatte.",al={"warum ist clarice wütend","clarice fosters vorgeschichte"}},{q="Was geschieht, wenn Ihr den Anhänger zurückbringt?",a="Wenn der Anhänger auf den steinernen Händen ruht, die in Yurivs Grab gemeißelt sind, wird sein Edelstein matt. Eine kräftige, kühle Brise weht über das Grabmal, wo das geschändete Grab in Stille liegt.",al={"anhänger auf dem grab","ende von bis dass der tod uns scheidet"}},{q="Wo befindet sich Yurivs Grab?",a="Yurivs Grab liegt auf dem Friedhof beim Grabmal, einer Festung der Verlassenen im nördlichen Silberwald.",al={"wo ist yurivs grab","yurivs grab fundort"}},{q="Warum ist Yurivs Grab so beschädigt?",a="Das Grab ist voller Kerben, mit Müll übersät und von Unkraut überwuchert. Die Verlassenen beim Grabmal empfinden weder Mitgefühl noch Ehrfurcht für einen Kreuzfahrer, der im Kampf gegen ihresgleichen starb.",al={"warum ist das grab geschändet","geschändetes grab"}},{q="Haben Clarices Kinder überlebt?",a="Clarice sagt, Yuriv habe sie und seine Kinder verlassen, verliert aber kein Wort über deren Schicksal. Angesichts der Verwüstung Lordaerons könnten sie ein tragisches Ende gefunden haben.",al={"was geschah mit den kindern","clarices kinder"}}},fp="22,220,17.409.0,19.328.0,14.166.0,47.191.0,41.178.1,30.104.0,32.174.0,31.149.0"}
P.entries["quest:2641"] = {n="Sprinkles Geheimzutat",s="In Gadgetzan bietet Sprinkle an, Marin Noggenfoggers übles Gebräu mit einem Violetten Tragan trinkbar zu machen. Der Pilz wächst unter Wasser in einem kleinen See im Hinterland.",h="In Gadgetzan bietet Sprinkle an, Marin Noggenfoggers übles Gebräu mit einem Violetten Tragan trinkbar zu...",kw={"gadgetzan","hinterland","pilz","noggenfogger","sprinkle","tanaris","violetter tragan"},sec={{t="Das Geheimnis einer Köchin",b="Als Sprinkle ein Kind war, übernahm ihre Schwester das gesamte Kochen, und das Essen war kaum genießbar. Sprinkle fand einen Pilz namens Violetter Tragan und machte ihn zu ihrer Geheimzutat. Sie sagt, damit habe jedes Gericht wunderbar geschmeckt. Jetzt will sie damit Marins scheußliches Gebräu trinkbar machen."},{t="Unter Wasser",b="Der Violette Tragan wächst unter Wasser in einem kleinen See im Hinterland. Der Valorwindsee liegt direkt südlich der Straße, die das Gebiet durchquert. Taucht unter die Oberfläche, um den Pilz zu sammeln, und kehrt dann zu Sprinkle in Gadgetzan zurück."}},faq={{q="Wer ist Sprinkle?",a="Sprinkle ist eine Köchin in Gadgetzan und eine Freundin von Marin Noggenfogger. Marin hat Euch mit einem schlecht schmeckenden Gebräu zu ihr geschickt.",al={"wer ist sprinkle","sprinkle gadgetzan","sprinkles geheimzutat questgeber"}},{q="Was ist der Violette Tragan?",a="Der Violette Tragan ist ein Pilz, den Sprinkle als Kind fand und ihre Geheimzutat nennt. Sie sagt, damit schmecke alles großartig.",al={"violetter tragan","was ist violetter tragan","geheimzutat pilz"}},{q="Wo ist der Violette Tragan zu finden?",a="Der Violette Tragan wächst unter Wasser in einem kleinen See im Hinterland. Der Valorwindsee liegt direkt südlich der Straße, die das Gebiet durchquert.",al={"wo ist violetter tragan","wo geheimzutat finden","violetter tragan fundort"}},{q="Was hat das mit Marin Noggenfogger zu tun?",a="Marins Gebräu schmeckte schrecklich, deshalb will Sprinkle es mit dem Violetten Tragan trinkbar machen.",al={"warum braucht sprinkle das","marin noggenfogger zusammenhang","noggenfogger questreihe"}}},fp="28,172,15.274.0,15.223.0,16.114.0,26.130.0,37.130.0,44.87.0"}
P.entries["quest:265"] = {n="Die Schattensuche geht weiter",s="Im Dämmerwald verfolgt Ihr die Spur des Tagebuchs von Madame Eva zu Amtmann Daltry in Dunkelhain. Es stammte aus den Ruinen von Sven Yorgens geplündertem Gehöft.",h="Im Dämmerwald verfolgt Ihr die Spur des Tagebuchs von Madame Eva zu Amtmann Daltry in Dunkelhain.",kw={"buch","amtmann daltry","dunkelhain","dämmerwald","tagebuch","madame eva","schemenhafte gestalt","sven yorgen"},ang={["class:Rogue"]="Als Schurke wisst Ihr, dass Kaufbelege und die Erinnerung eines Händlers helfen können, eine nervöse Zielperson durch die Stadt zu verfolgen.",["faction:Alliance"]="Für die Allianz ist es wichtig, die Lieferanten und Helfer der Nekromanten im Dämmerwald aufzuspüren, um Dunkelhain zu schützen und den ermordeten Grenzlandsiedlern Gerechtigkeit zu verschaffen."},sec={{t="Die Spur des Einbands",b="Madame Eva fand heraus, dass der Verfasser des Tagebuchs ein Fremder war, sein Einband jedoch aus Dunkelhain stammte. Amtmann Daltry verkauft unbeschriebene Geschäftsbücher und Wälzer an reisende Gelehrte, Zauberwirker und Schriftführer. Also geht Ihr diesen örtlichen Verkäufen nach, um einen Hinweis auf den finsteren Eindringling in den Hainen des Dämmerwalds zu finden."},{t="Ein nervöser Käufer",b="Amtmann Daltry erinnert sich an den Verkauf, obwohl viele Unterlagen durch das Rathaus von Dunkelhain gehen. Vor etwa einem Monat kaufte ein nervöser Reisender das unbeschriebene Buch und nannte keinen Namen. Der verstohlene Käufer blickte ständig über die Schulter und hinterließ beim Amtmann einen bleibenden Eindruck. Die schemenhafte Gestalt, die Sven gesehen hatte, war offen unter Dunkelhains Bürgern umhergegangen."}},faq={{q="Woher stammte das geheimnisvolle Buch?",a="Madame Eva sagt, der Verfasser sei ein Fremder gewesen, doch das Buch wurde in Dunkelhain gekauft. Amtmann Daltry verkauft unbeschriebene Bücher und erinnert sich vielleicht daran, wer es gekauft hat.",al={"herkunft des buches","wer verkaufte das buch","quelle des buches"}},{q="Warum schickt Madame Eva Euch zu Amtmann Daltry?",a="Madame Eva fand heraus, dass der Einband und die Materialien des Buches von einem örtlichen Kauf stammten. Amtmann Daltry verkauft unbeschriebene Geschäftsbücher und Tagebücher an Einheimische und reisende Gelehrte.",al={"warum daltry","verbindung zwischen eva und daltry","wer fertigte das buch"}},{q="Woran erinnert sich Amtmann Daltry über den Käufer?",a="Daltry erinnert sich an einen nervösen Reisenden ohne Namen, der das unbeschriebene Buch vor etwa einem Monat kaufte.",al={"wer kaufte das buch","beschreibung des käufers","aussehen der schemenhaften gestalt"}},{q="Wie hängt das mit Svens Bauernhof zusammen?",a="Das Buch wurde aus Sven Yorgens zerstörtem Bauernhof im südlichen Dämmerwald geborgen. Es war nach einem mörderischen Überfall zurückgeblieben, bei dem seine gesamte Familie getötet wurde.",al={"verbindung zu sven","warum suchen wir","sven yorgen"}},{q="Wohin führt die Untersuchung als Nächstes?",a="Die Suche geht in der Scarlet Raven Tavern in Dunkelhain weiter. Dort weiß vielleicht jemand, wo der nervöse Fremde übernachtete oder mit wem er sprach.",al={"was kommt als nächstes","nach daltry","nächster hinweis"}},{q="Ist Amtmann Daltry in Gefahr?",a="Daltry hilft dabei, einen Käufer aus seinem gewöhnlichen Buchhandel zu identifizieren. Nichts in dem Gespräch deutet darauf hin, dass er persönlich bedroht wird.",al={"amtmann daltry in gefahr","daltry in sicherheit"}}},fx={["9bf6b406"]={q="Warum hilft Madame Eva bei der Suche?",a="Madame Eva dient Dunkelhain als Seherin und Beraterin und wacht über die schattenhaften Omen, die den Dämmerwald heimsuchen. Als Ihr ihr das schmutzverschmierte Buch von Svens zerstörter Farm brachtet, spürte sie, dass jemand, der von Rache getrieben war, es vor kurzem berührt hatte, während die schwachen Eindrücke seines ursprünglichen Besitzers ihn als einen Fremden in Dunkelhain auswiesen. Sie konnte zudem erkennen, dass das Buch selbst im Ort gekauft worden war, weshalb sie Euch ausschickt, um die Stadtbewohner zu befragen, in der Hoffnung, dass diese das Buch mit seinem Besitzer in Verbindung bringen können.",al={"warum madame eva hilft","madame eva beweggrund","warum madame eva das buch wichtig ist"}}},fp="28,143,19.295.0,15.332.1,40.144.0,45.164.0,48.90.0,37.143.0,39.139.1,26.126.0"}
P.entries["quest:266"] = {n="Nachforschungen im Gasthaus",s="Amtmann Daltry schickt Euch mit einem Tagebuch von Sven Yorgens zerstörtem Hof aus Dunkelhain zur Scarlet Raven Tavern. Er hofft, dass dort jemand weiß, wem es gehörte.",h="Amtmann Daltry schickt Euch mit einem Tagebuch von Sven Yorgens zerstörtem Hof aus Dunkelhain zur Scarlet...",kw={"amtmann daltry","dunkelhain","dämmerwald","nachforschungen im gasthaus","rabenflucht","scarlet raven","schattenhafte gestalt","sven yorgen","schankwart smitts"},ang={["class:Rogue"]="Als Schurke könnt Ihr durch sorgfältige Nachforschungen der Spur eines Flüchtigen von Wirtshausgesprächen bis zu verlassenen Ruinen folgen.",["faction:Alliance"]="Als Abenteurer der Allianz helft Ihr, Dunkelhain, eine abgelegene Grenzsiedlung im Süden der Östlichen Königreiche, zu schützen, indem Ihr Bedrohungen innerhalb ihrer Mauern untersucht."},sec={{t="Eine Spur im Scarlet Raven",b="Amtmann Daltry hat die Untersuchung des zerfledderten Buches von Sven Yorgens Hof abgeschlossen. Er glaubt, dass jeder Fremde, der nach Dunkelhain kam, auch die örtliche Taverne besucht hätte. Die Scarlet Raven Tavern steht am anderen Ende der Stadt und ist Dunkelhains einzige Versammlungshalle und Herberge. Dort könnt Ihr erfahren, wer durchreiste und wohin die Reisenden gingen."},{t="Der paranoide Gast",b="Schankwart Smitts erkennt das Tagebuch, als Ihr es ihm zeigt. Sein Besitzer mietete für mehrere Tage ein Zimmer und verbrachte seine Abende damit, am Tresen zu kritzeln. Dann floh der Gast voller Entsetzen aus Dunkelhain, überzeugt davon, dass ein unsichtbarer Verfolger ihn jagte. Der Fremde nahm die Straße nach Westen in Richtung Rabenflucht."}},faq={{q="Wer schickt Euch zum Gasthaus?",a="Amtmann Daltry, Dunkelhains Stadtarchivar, schickt Euch zur Scarlet Raven Tavern, nachdem er das Tagebuch untersucht hat. Er hofft, dass dort jemand dessen Besitzer erkennt.",al={"wer vergibt diese quest","questgeber","wo beginnt nachforschungen im gasthaus"}},{q="Was ist das für ein Buch, das Ihr bei Euch tragt?",a="Das abgenutzte Tagebuch stammt von Sven Yorgens zerstörtem Gehöft im südlichen Dämmerwald. Es gehört vermutlich der schattenhaften Gestalt, die man in der Nähe umherschleichen sah.",al={"was ist das buch","buch von svens hof","tagebuch"}},{q="Wer betreibt die Scarlet Raven Tavern?",a="Schankwart Smitts betreibt die Scarlet Raven Tavern. Er schenkt Getränke aus und vermietet Zimmer an Reisende, die sich in den Dämmerwald wagen.",al={"wer ist der schankwart","gastwirt dunkelhain","wer ist smitts"}},{q="Was verrät Schankwart Smitts über den Gast?",a="Der Besitzer des Tagebuchs mietete für mehrere Tage ein Zimmer und verbrachte seine Abende schreibend am Tresen. Dann floh er voller Entsetzen aus Dunkelhain, überzeugt davon, dass ein unsichtbarer Verfolger ihn jagte.",al={"was hat smitts gesagt","was geschah mit der schattenhaften gestalt","was weiß der gastwirt"}},{q="Wohin floh die schattenhafte Gestalt?",a="Der Fremde floh von Dunkelhain aus auf der Straße nach Westen in Richtung Rabenflucht.",al={"wohin ging er","wo ist die schattenhafte gestalt","wohin als nächstes"}},{q="Welche Quest folgt auf Nachforschungen im Gasthaus?",a="Schankwart Smitts weist Euch nach Westen, um in Finding the Shadowy Figure der Spur des Fremden zu folgen.",al={"nächste quest","was kommt nach nachforschungen im gasthaus","folgequest"}}},fx={["5b964541"]={q="Warum möchte Amtmann Daltry, dass Ihr im Gasthaus nachfragt?",a="Amtmann Daltry führt die Ortschroniken von Dunkelhain, doch seine Register können geheimnisvolle Wanderer, die durch die Schatten schlüpfen, nicht erfassen. Da er weiß, dass Ihr der schwer fassbaren Gestalt auf der Spur seid, die mit den düsteren Geschehnissen auf Svens Farm in Verbindung steht, verweist er Euch an die Scarlet Raven Tavern. In einer wachsame Stadt wie Dunkelhain wäre jeder Fremde, der auf einen Schluck oder ein Bett einkehrte, dem Wirt ins Auge gefallen.",al={"warum amtmann daltry euch zum gasthaus schickt","amtmann daltry gasthaus beweggrund","warum in der scarlet raven tavern nachfragen"}}},fp="18,155,27.320.0,18.289.1,25.161.0,34.148.0,34.121.0,51.172.0,34.71.0,38.95.0"}
P.entries["quest:2661"] = {n="Lieferung für Marin",s="In Gadgetzan schickt Sprinkle Violettes Pulver zu Marin Noggenfogger und erinnert sie an den Gefallen, den Marin ihr schuldet.",h="In Gadgetzan schickt Sprinkle Violettes Pulver zu Marin Noggenfogger und erinnert sie an den Gefallen, den...",kw={"gadgetzan","marin noggenfogger","noggenfogger elixier","sprinkle","tanaris","violettes pulver"},sec={{t="Eine Lieferung in der Stadt",b="In Gadgetzan gibt Sprinkle Euch Violettes Pulver, nachdem Ihr ihr den Violetten Tragan gebracht habt. Marin Noggenfogger ist in derselben Stadt, und Sprinkle bittet Euch, Marin daran zu erinnern, dass sie ihr einen Gefallen schuldet."}},faq={{q="Wer schickt Euch zu Marin Noggenfogger?",a="Sprinkle schickt Euch mit Violettem Pulver zu Marin Noggenfogger, nachdem Ihr ihr den Violetten Tragan gebracht habt.",al={"wer gibt lieferung für marin","lieferung für marin questgeber","sprinkle lieferung"}},{q="Welchen Gegenstand liefert Ihr?",a="Sprinkle gibt Euch Violettes Pulver, das Ihr zu Marin Noggenfogger bringen sollt.",al={"was wird marin gebracht","marin liefergegenstand","welches pulver ist es"}},{q="Wo befindet sich Marin Noggenfogger?",a="Marin Noggenfogger ist in Gadgetzan, in derselben Stadt wie Sprinkle.",al={"marin noggenfogger standort","wo ist marin","marin noggenfogger finden"}},{q="Welche Nachricht möchte Sprinkle Marin ausrichten lassen?",a="Sprinkle bittet Euch, Marin Noggenfogger zu sagen, dass Marin ihr einen Gefallen schuldet.",al={"sprinkle nachricht","was sagt sprinkle zu marin","sprinkle gefallen"}}},fp="18,105,15.186.0,36.98.0,29.66.0,36.62.0,48.73.0"}
P.entries["quest:2662"] = {n="Noggenfogger-Elixier",s="In Gadgetzan mischt Marin Noggenfogger Violettes Pulver in den Tau. Er bittet Euch, gleich wiederzukommen, wenn sein fabelhaftes Elixier fertig sein sollte.",h="In Gadgetzan mischt Marin Noggenfogger Violettes Pulver in den Tau.",kw={"tau","gadgetzan","goblin","marin noggenfogger","noggenfogger-elixier","pulver","sprinkle","tanaris"},sec={{t="Das Elixier mischen",b="Marin hat den Tau und das Pulver. Er beginnt, beides zu vermischen, und das Noggenfogger-Elixier sollte nach kurzer Wartezeit fertig sein. Sprecht ihn dann erneut an."},{t="Marins Urteil",b="Als Marin fertig ist, drängt er Euch ein Getränk auf und nennt es wunderbar. Er prahlt mit den Millionen, die es einbringen wird, und bittet Euch dann, beiseitezutreten, damit Ihr das Geschäft nicht behindert. Sprinkle behauptet, Marin schulde einen Gefallen, doch Marin tut das lachend als Scherz ab."}},faq={{q="Wer bietet diese Quest an?",a="Marin Noggenfogger bietet sie in Gadgetzan an.",al={"noggenfogger questgeber","wer vergibt noggenfogger-elixier","marin noggenfogger quest"}},{q="Was ging diesem Schritt voraus?",a="Dieser Schritt folgt auf Delivery for Marin. Davor kamen The Thirsty Goblin, In Good Taste und Sprinkle's Secret Ingredient.",al={"voraussetzung noggenfogger-elixier","vorherige quest für marin","was kommt vor noggenfogger-elixier"}},{q="Welche Zutaten vermischt Marin hier?",a="Marin mischt Sprinkles Violettes Pulver in den Tau.",al={"noggenfogger zutaten","was mischt marin","was ist im elixier"}}},fp="19,143,17.145.0,15.244.1,22.42.0,27.117.0,41.50.0"}
P.entries["quest:267"] = {n="Die Bedrohung durch die Troggs",s="Am Südtor von Loch Modan fehlen Hauptmann Rugelfuß Verteidiger gegen die wachsende Bedrohung durch die Troggs. Die Eisenschmiede-Reserve wurde an die Schlachtfronten der Allianz abberufen, sodass er den Pass halten muss, während Troggs die nahen Hügel bedrohen.",h="Am Südtor von Loch Modan fehlen Hauptmann Rugelfuß Verteidiger gegen die wachsende Bedrohung durch die Troggs.",kw={"hauptmann rugelfuß","eisenschmiede-reserve","khaz modan","loch modan","magni bronzebart","südtor","trogg","troggsteinzahn"},ang={["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie Verpflichtungen in fernen Ländern örtlichen Garnisonen wie der in Loch Modan ihre Verteidigungsreserven genommen haben.",["race:Dwarf"]="Als Zwerg ist es Eure unmittelbare Pflicht gegenüber Khaz Modan, die Reihen der Troggs nahe dem Südtor zu lichten. König Magni Bronzebart selbst wird Euch dafür loben."},sec={{t="Eine geschwächte Grenzverteidigung",b="Zwergengebirgsjäger und die Eisenschmiede-Reserve sind ausgerückt, um die Schlachtfronten der Allianz zu verstärken. Hauptmann Rugelfuß verfügt nun nur noch über eine kleine Garnison. Strenge Befehle halten ihn am Tor fest, sodass er keinen Angriff ins Hochland führen kann. Siedler und Reisende dort bleiben Hinterhalten ausgesetzt."},{t="Die Flut eindämmen",b="Troggs in den nahen Felsen bedrohen Khaz Modan. Ungehindert wächst ihre Zahl rasch an, und sie könnten die Zwergenaußenposten überrennen. Rugelfuß bittet um Hilfe, um Zeit zu gewinnen und ihre Reihen zu lichten. Greift die Troggs in ihren Bauten an den Hängen an und bringt anschließend ihre Steinzähne als Beweis zurück."}},faq={{q="Wer ist Hauptmann Rugelfuß?",a="Hauptmann Rugelfuß ist ein zwergischer Offizier im Wachturm am Südtor von Loch Modan. Mit nur einer kleinen Garnison muss er den Pass gegen Eindringlinge sichern.",al={"hauptmann rugelfuß","wer vergibt die bedrohung durch die troggs","rugelfuß"}},{q="Warum ist das Südtor unterbesetzt?",a="Die Eisenschmiede-Reserve wurde zum Kampf an ferne Schlachtfronten der Allianz entsandt. Nur eine kleine Truppe bleibt am Tor zurück, an ihren Verteidigungsposten gebunden und außerstande, zurückzuschlagen.",al={"warum gibt es keine wachen","eisenschmiede-reserve abwesend","wo sind die zwergensoldaten"}},{q="Was sind Steinzähne?",a="Steinzähne sind die von Natur aus versteinerten, steinartigen Zähne der Troggs, ein Zeichen ihres unterirdischen, erdverbundenen Erbes. Rugelfuß verlangt sie als Beweis dafür, dass Troggs erschlagen wurden.",al={"troggsteinzahn","steinzähne","warum troggzähne"}},{q="Wo befinden sich die Troggs?",a="Troggs leben in den felsigen Hügeln, Schluchten und Ausgrabungsstätten neben der Straße nahe dem Südtor von Loch Modan.",al={"wo troggs finden","troggfundorte loch modan","wo sind troggs für diese quest"}},{q="Warum sind die Troggs gerade jetzt eine solche Bedrohung?",a="Troggs vermehren sich schnell und greifen erbittert an, um ihr Gebiet zu verteidigen. Da die Truppen andernorts eingesetzt werden, können sie bewohnte Gebiete überrennen und die Pässe bedrohen, die Loch Modan mit benachbarten Gebieten verbinden.",al={"warum sind troggs gefährlich","troggproblem","was wollen troggs"}},{q="Wie hilft der Abschluss dieser Quest König Magni Bronzebart?",a="König Magni Bronzebart ist für die Sicherheit von ganz Khaz Modan verantwortlich. Die Reihen der Troggs zu lichten, während Eisenschmiedes Armeen in der Ferne kämpfen, hilft, die heimischen Nachschubwege und gefährdete Grenzsiedlungen zu schützen.",al={"verbindung zu magni bronzebart","kümmert es magni","warum eisenschmiede helfen"}}},fx={["5b5ee45d"]={q="Warum will Hauptmann Rugelfuß, dass dies erledigt wird?",a="Da die Reserve der Eisenschmiede an die Front der Allianz verlegt wurde, fehlt es Hauptmann Rugelfuß an Arbeitskräften, um die Region zu sichern. Sein Regiment ist damit beschäftigt, den südlichen Wachturm gegen eine potenzielle Invasion zu halten. Wenn die Troggs, die sich in den nahegelegenen Hügeln sammeln, unbeaufsichtigt bleiben, könnten sie den Außenposten leicht überwältigen und Loch Modan überrennen.",al={"motiv rugelfuß","warum troggs bekämpfen","zweck hauptmann rugelfuß"}},ba878bae={q="Warum befallen die Troggs die Hügel in der Nähe des Südtores?",a="Die Troggs sind in den Zwergenländern aufgetaucht und dringen aggressiv in Siedlungen und auf Reisewege ein. Da sie die umliegenden Felsen als reif für eine Invasion empfinden, streifen sie auf den Bergrücken in der Nähe des Südtores umher und warten darauf, die verwundbaren Verteidigungsanlagen anzugreifen, die durch den anhaltenden Truppenmangel geschwächt sind.",al={"wer sind die troggs","trogg ziele","warum sind troggs hier"}}},fp="16,241,19.279.0,17.283.0,25.170.0,38.173.0,27.184.0,29.111.0,43.196.0,58.204.0"}
P.entries["quest:268"] = {n="Rückkehr zu Sven",s="Ihr bringt Bibbers' vollendetes Tagebuch zu Sven Yorgens Lager nahe Westfall. Seine Seiten könnten die Fragen beantworten, die ihn seit dem Mord an seiner Familie quälen.",h="Ihr bringt Bibbers' vollendetes Tagebuch zu Sven Yorgens Lager nahe Westfall.",kw={"dunkle reiter","dämmerwald","das verlassene gut","bibbers","bibbers' vollendetes tagebuch","morbent fel","sven yorgen","yorgens bauernhof"},ang={["class:Paladin"]="Als Paladin helft Ihr Sven, die Mächte hinter dem Mord an seiner Familie aufzudecken. Eure heilige Pflicht ruft Euch dazu auf, die Unschuldigen zu schützen und Gerechtigkeit zu suchen.",["faction:Alliance"]="Die Zerstörung von Yorgens Bauernhof zeigt, dass Sturmwind beim Schutz der Grenzsiedlungen des Dämmerwalds vor den vordringenden Schatten versagt hat."},sec={{t="Das Geständnis eines Feiglings",b="Als Sven Yorgens Bauernhof angegriffen wurde, floh Bibbers in die Wälder und ließ ein unvollständiges Tagebuch zurück. Aus Angst vor Svens Zorn und verfolgt von dem, was er gesehen hatte, versteckte er sich tief im Dämmerwald. Als Ihr ihn findet, übergibt er Euch bereitwillig sein vollendetes Tagebuch. Er hofft, der vollständige Bericht erspart es ihm, Sven persönlich gegenüberzutreten."},{t="Die Dunklen Reiter entlarven",b="Bibbers' vollendeter Bericht erklärt, warum die Dunklen Reiter Svens Familie töteten. Sie suchten ein Artefakt; es war kein wahlloser Ansturm von Untoten und kein Angriff wilder Bestien. Sven erinnert sich auch daran, wie dieselben vermummten Gestalten sich nahe dem Verlassenen Gut heimlich mit dem Nekromanten Morbent Fel trafen. Nun ist seine blinde Trauer einer Jagd nach Vergeltung an Morbent Fel gewichen."}},faq={{q="Warum hat Bibbers solche Angst vor Sven Yorgen?",a="Bibbers floh von Svens Bauernhof und fürchtet den Zorn des trauernden Bauern. Er bittet Euch, Sven sein Tagebuch zu bringen, damit dieser den Bericht lesen kann.",al={"warum hat bibbers angst","bibbers angst vor sven","was hat bibbers getan"}},{q="Was steht in Bibbers' vollendetem Tagebuch?",a="Bibbers' vollendetes Tagebuch enthält seinen vollständigen Bericht über die Ereignisse auf Svens Bauernhof. Sven muss es lesen, um zu verstehen, was seiner Familie widerfahren ist.",al={"was steht im tagebuch","bibbers' vollendetes tagebuch hintergrund"}},{q="Wer sind die Dunklen Reiter, die Sven erwähnt?",a="Die Dunklen Reiter sind geheimnisvolle, vermummte Gestalten, die durch den Dämmerwald streifen. Sie suchen nach mächtigen magischen Relikten und hinterlassen Tod und Verwüstung.",al={"wer sind die dunklen reiter","reiter im dämmerwald","schwarze reiter"}},{q="Wie hängt Morbent Fel mit dem Angriff auf Svens Bauernhof zusammen?",a="Morbent Fel ist ein mächtiger Nekromant im westlichen Dämmerwald. Svens Nachforschungen und Bibbers' Tagebuch offenbaren seine Verbindung zu dem Angriff.",al={"morbent fel verbindung","warum morbent fel","wer ist morbent fel"}},{q="Wo ist Sven Yorgen zu finden?",a="Sven hat seinen zerstörten Bauernhof verlassen und ein kleines Lager in den nordwestlichen Hügeln des Dämmerwalds nahe dem Grenzübergang nach Westfall aufgeschlagen.",al={"wo ist sven","sven yorgen aufenthaltsort","svens lager"}},{q="Was geschieht, nachdem Sven das Tagebuch erhalten hat?",a="Nachdem Sven Bibbers' Bericht gelesen hat, bittet er Euch, Eure Kampffähigkeiten in Proving Your Worth unter Beweis zu stellen.",al={"nächste quest nach rückkehr zu sven","svens questreihe fortsetzung"}}},fx={ba46c9da={q="Warum muss Bibbers Euch das Tagebuch überbringen lassen, anstatt es selbst zu bringen?",a="Bibbers ist völlig von Angst verzehrt. Er versteckte sich unbemerkt in Svens Scheune, während Svens Familie abgeschlachtet wurde, und floh dann, wobei er sein halbfertiges Tagebuch zurückließ. Anstatt zu riskieren, Svens Zorn persönlich gegenüberzutreten, überreicht er Euch bereitwillig sein vervollständigtes Tagebuch, um die Wahrheit über das, was tatsächlich geschehen ist, zu übermitteln.",al={"warum schickt mich jitters","warum kann jitters nicht mit sven sprechen","warum jitters tagebuch abliefern"}}},fp="14,156,21.321.0,25.373.1,43.139.0,38.146.1,42.137.0,58.137.1,31.125.0,43.99.1"}
P.entries["quest:269"] = {n="Auf der Suche nach Weisheit",s="In Sturmwind bittet Sven Yorgen Bischof Heller um heiligen Rat für den Dämmerwald. Er schickt Bibbers' vollendetes Tagebuch und hofft, dass der Bischof offenbaren kann, wie sich Morbent Fels Schild brechen lässt.",h="In Sturmwind bittet Sven Yorgen Bischof Heller um heiligen Rat für den Dämmerwald.",kw={"bischof heller","kathedrale des lichts","dunkelhain","dämmerwald","bibbers","morbent fel","auf der suche nach weisheit","sturmwind","sven yorgen"},ang={["class:Paladin"]="Für Euch als Paladin stellt das Überbringen von Bitten um heiligen Beistand aus den verlassenen Grenzlanden zur Kathedrale des Lichts die Pflicht der Silver Hand auf die Probe, die Vergessenen zu schützen und die Nekromantie auszumerzen.",["class:Priest"]="Für Euch als Priester bietet Bischof Heller Aufklärung darüber, wie dunkle Schutzzauber Leib und Seele verderben. Schattenzauberei verlangt neben der Klinge auch nach gezielter Heiligung.",["faction:Alliance"]="Als Reisender der Allianz offenbart Euch die Reise die Kluft zwischen Sturmwinds bewachten Marmorhallen und den verlassenen Ortschaften des Dämmerwalds. Diese Ortschaften erhalten keine Unterstützung durch Garnisonen."},sec={{t="Eine Bitte aus den Schatten",b="Der Dämmerwald leidet unter alten Flüchen und unersättlichen Untoten. Sturmwinds Königshof ist gleichgültig geworden, und Sven Yorgen weiß, dass gewöhnliche Stärke Morbent Fels Schutzzauber nicht durchdringen kann. Mit gebrochenem Herzen sucht er in einem Lager nahe den Grenzen Zuflucht und bittet Euch, Bibbers' zusammengestelltes Tagebuch zur Kirche zu bringen. Die Straße nach Norden führt zur Kathedrale des Lichts."},{t="Rat in der Kathedrale",b="In Sturmwinds Kathedrale des Lichts hört Bischof Heller die Hilferufe aus dem Dämmerwald. Bibbers' Bericht bestätigt Morbent Fels Macht: Niederträchtige Zauberei schützt den Nekromanten vor gewöhnlichen Schlägen. Mut allein kann diese Schutzzauber nicht überwinden. Um ihn zu besiegen, muss ein verzaubertes heiliges Instrument gefunden werden."}},faq={{q="Warum schickt Sven Euch zu Bischof Heller statt zu König Anduin?",a="Sven vertraut Bischof Heller, einem mitfühlenden und gelehrten Mann des Heiligen Lichts, der finstere Magie versteht. Sturmwinds Adel und Armee haben Dunkelhain und die umliegenden Ländereien inmitten politischer Lähmung weitgehend sich selbst überlassen, deshalb erwartet Sven auf offiziellem Wege keine Soldaten.",al={"warum heller","warum nicht sturmwinds adel","sturmwind ignorierte den dämmerwald"}},{q="Was ist Bibbers' Tagebuch und warum braucht der Bischof es?",a="Bibbers hielt fest, was sich rund um den Angriff auf Svens Hof ereignete. Sven schickt den vollständigen Bericht an Bischof Heller, damit dieser Euch bei Euren Vorbereitungen auf den Kampf gegen Morbent Fel beraten kann.",al={"was ist bibbers' tagebuch","warum bibbers' tagebuch","bibbers' vollendetes tagebuch"}},{q="Wer ist Morbent Fel?",a="Morbent Fel ist ein mächtiger Nekromant, der beim Verlassenen Gut im Dämmerwald gesichtet wurde. Er befehligt Horden von Skelettdienern und schützt sich mit mächtigen Schutzzaubern, die gewöhnliche Waffen abwehren.",al={"wer ist morbent fel","morbent fels geschichte"}},{q="Wo befindet sich Bischof Heller?",a="Bischof Heller weilt in der Kathedrale des Lichts, der prächtigen Menschenkathedrale im Stadtviertel Kathedralenplatz von Sturmwind.",al={"wo ist heller","hellers aufenthaltsort","bischof heller karte"}},{q="Was geschieht, nachdem Bischof Heller das Tagebuch gelesen hat?",a="Bischof Heller erklärt, dass gewöhnliche Schläge Morbent Fel nichts anhaben können. Er weist Euch auf eine geweihte Reliquie hin, die die Schutzzauber des Nekromanten bannen kann, und leitet damit die Suche nach der Doomed Fleet ein.",al={"was folgt auf auf der suche nach weisheit","auf der suche nach weisheit folgequest","nach auf der suche nach weisheit"}},{q="Wo hält sich Sven Yorgen im Dämmerwald auf?",a="Sven Yorgen sucht in einem kleinen Lager im Nordwesten des Dämmerwalds nahe der Flussgrenze Zuflucht. Es liegt südlich des Waldes von Elwynn und westlich des von Geistern heimgesuchten Friedhofs von Rabenflucht.",al={"wo ist sven","sven yorgens aufenthaltsort","sven's camp"}}},fx={["12ed4f38"]={q="Warum muss Sven Yorgen Euch bitten, das Tagebuch auszuliefern?",a="Sven hält allein im Dämmerwald die Stellung, verzehrt von Rache und Trauer, während er in einem Lager voller Schrecken ums Überleben kämpft. Sturmwind hat Dunkelhain und die umliegenden Lande ihrem Schicksal überlassen und schickt keine königlichen Wachen, um ihm beizustehen. Sven kann den Dämmerwald nicht unbewacht lassen und besitzt auch nicht die Mittel, um Morbent Fels dunkle Zauberei allein zu brechen. Da Ihr Euch gegen die örtlichen Bedrohungen bewährt habt, seid Ihr seine einzige verlässliche Hoffnung, die Wahrheit über Bibbers zu jemandem zu bringen, der die Weisheit und die heilige Macht besitzt, zu helfen.",al={"warum ich sven","warum spieler zu bischof farthing schicken","warum geht sven nicht nach sturmwind"}}},fp="14,177,23.345.0,24.281.1,65.291.0,57.173.0,19.184.0,33.123.0,53.193.1,40.161.0"}
P.entries["quest:27"] = {n="Eine wertvolle Lektion",s="In Donnerfels schickt Turak Runentotem junge Taurendruiden nach Norden, um die Gewässer zu erkunden. Ihr Weg führt nach Nachthafen in der Mondlichtung, wo der Zirkel des Cenarius ihre Ausbildung leitet.",h="In Donnerfels schickt Turak Runentotem junge Taurendruiden nach Norden, um die Gewässer zu erkunden.",kw={"aquatic form","zirkel des cenarius","dendrite sternenschauer","die anhöhe der ältesten","wertvolle lektion","mondlichtung","nachthafen","donnerfels","turak runentotem"},ang={["class:Druid"]="Als Druide lasst Ihr das Überleben an Land hinter Euch und beginnt zu lernen, unter Wasser zu atmen und Euch zu bewegen.",["faction:Horde"]="Als Mitglied der Horde achtet Ihr die heilige Neutralität der Mondlichtung und wandelt an der Seite von Nachtelfen unter dem gemeinsamen Blätterdach von Cenarius.",["race:Tauren"]="Als Tauren schließt Ihr Euch mit den Druiden von Donnerfels der größeren cenarischen Bruderschaft der Mondlichtung an."},sec={{t="Meisterschaft der Tiefen",b="Ihr habt die Bärengestalt und ihre Stärke kennengelernt. Nun lehrt Turak Runentotem seine Schüler Anpassungsfähigkeit. Azeroths Wasserwege bergen Gefahren, die Reisenden zu schaffen machen, die ans Land gebunden sind. Deshalb schickt er jene, die sich der Natur verschrieben haben, nach Norden, um die Aquatic Form zu erlernen."},{t="Der Weg nach Nachthafen",b="Turak Runentotem schickt Euch über Mulgore hinaus, damit Ihr lernt, Eure Gestalt den Gewässern anzupassen. Ihr reist in die Mondlichtung, die Zuflucht am Fuße des Hyjal, und erreicht Nachthafen. Dort heißen nachtelfische Mentoren des Zirkels des Cenarius Schüler der Tauren willkommen. Sie lassen die Streitigkeiten der Fraktionen ruhen, um die gemeinsamen Lehren von Cenarius zu bewahren."},{t="Die beiden Prüfungen",b="Dendrite Sternenschauer erwartet Euch in Nachthafen, wo Eure Ausbildung beginnt. Der nachtelfische Älteste sagt, die Beherrschung der Gewässer müsse verdient werden. Zwei Prüfungen erwarten Euch. Eine stellt Eure Ausdauer und Gelassenheit unter Wasser auf die Probe. Die andere verlangt ein tiefes spirituelles Verständnis des aquatischen Aspekts."}},faq={{q="Wer vergibt die Quest Eine wertvolle Lektion?",a="Turak Runentotem vergibt sie auf der Anhöhe der Ältesten in Donnerfels, wo er Druiden ausbildet. Sobald Ihr genügend Erfahrung habt, schickt er Euch zur weiterführenden Ausbildung.",al={"wer startet eine wertvolle lektion","wo gibt es eine wertvolle lektion","turak runentotem quest"}},{q="Wohin muss ich gehen, um diese Quest abzuschließen?",a="Ihr reist nach Nachthafen in der Mondlichtung und sprecht mit Dendrite Sternenschauer vom Zirkel des Cenarius.",al={"wo eine wertvolle lektion abgeben","dendrite sternenschauer standort","wo ist nachthafen"}},{q="Zu welcher Fähigkeit führt diese Questreihe?",a="Dieser Weg führt zur Aquatic Form. Sie lässt Euch schnell unter Wasser schwimmen und unbegrenzt unter der Oberfläche atmen.",al={"welche gestalt gibt es dafür","aquatic form quest","warum diese quest machen"}},{q="Warum gehen Taurendruiden zur Ausbildung zu einem Nachtelfen?",a="Der Zirkel des Cenarius ist eine neutrale Bruderschaft, die sich Cenarius und der Bewahrung der Natur verschrieben hat. In der Mondlichtung lassen Nachtelfen und Tauren die Spannungen zwischen Horde und Allianz ruhen, um gemeinsam die heiligen Künste zu erlernen.",al={"warum mondlichtung","warum dendrite sternenschauer","zirkel des cenarius tauren"}},{q="Von welchen Prüfungen spricht Dendrite Sternenschauer?",a="Dendrite Sternenschauer erzählt Euch von zwei Prüfungen. Eine stellt Eure Gelassenheit unter Druck unter Wasser auf die Probe. Die andere prüft Eure spirituelle Entschlossenheit, den aquatischen Aspekt zu verstehen.",al={"was sind die beiden prüfungen","dendrites prüfungen","aquatische prüfungen"}},{q="Wie erreicht ein Druide zu diesem Zeitpunkt die Mondlichtung?",a="Druiden können Teleport: Mondlichtung nutzen, einen Zauber, der ihrer spirituellen Bindung entspringt, um von überall in Azeroth direkt nach Nachthafen zu reisen.",al={"wie zur mondlichtung gelangen","teleport zur mondlichtung","nach nachthafen gelangen"}}},fx={b1c6f6a1={q="Warum schickt Turak Runentotem mich nach Mondlichtung?",a="Turak Runentotem hat Euer Heranwachsen als Beschützer der Natur beobachtet und glaubt, dass Ihr bereit seid, auf Eurem druidischen Pfad voranzuschreiten. Er schickt Euch nach Mondlichtung, damit Ihr mit dem Zirkel des Cenarius Zwiesprache halten und jenen von Cenarius verliehenen Tieraspekt erlernen könnt, der die Meisterschaft über das Wasser gebietet.",al={"warum schickt turak mich","turak runentotem beweggrund","warum a lesson to learn"}},["055244fc"]={q="Warum muss ich diese Ausbildung selbst durchlaufen?",a="Die Gestaltwandlung ist kein Mantel, der einem einfach verliehen oder von einem anderen getragen werden kann. Jeder Druide muss seinen eigenen Geist und seine körperliche Ausdauer direkt vor dem Zirkel des Cenarius unter Beweis stellen, um sich mit dem Segen von Cenarius in Einklang zu bringen und den aquatischen Aspekt zu erlangen.",al={"warum muss ich die prüfungen ablegen","warum mich nach mondlichtung schicken","warum ich a lesson to learn"}}},fp="17,180,21.253.0,22.320.0,15.288.0,38.155.0,39.95.0,43.113.0,52.206.0,45.168.0,47.132.0"}
P.entries["quest:270"] = {n="Die Verlorene Flotte",s="Bischof Heller schickt Euch von Sturmwind nach Norden, um einen Weg durch Morbent Fels Schutzzauber zu finden. Eure Spur führt durch Khaz Modan und endet bei den Wracks der Third Fleet von Kul Tiras vor dem Sumpfland.",h="Bischof Heller schickt Euch von Sturmwind nach Norden, um einen Weg durch Morbent Fels Schutzzauber zu finden.",kw={"bischof heller","die verlorene flotte","glorin stahlbraue","kul tiras","lightforge iron","hafen von menethil","morbent fel","third fleet","sumpfland"},ang={["class:Paladin"]="Als Paladin sucht Ihr heiliges Metall, um einen unheiligen Nekromanten niederzustrecken. Ihr führt vom Licht geweihte Waffen, um die Dunkelheit zu tilgen.",["class:Priest"]="Als Priester folgt Ihr Bischof Hellers Führung und dem alten Wissen der Kirche über gesegnete Relikte und geweihte Erze.",["faction:Alliance"]="Als Reisender der Allianz verbindet Ihr die abgeschiedenen Menschenstädte des Südens mit zwergischen Häfen und alten Seewegen.",["profession:Blacksmithing"]="Als Schmied erfahrt Ihr von seltenem Lightforge Iron, einem Metall, das von Glauben erfüllt und durch meisterliche Handwerkskunst geformt wird."},sec={{t="Eine Waffe heiliger Wahrheit",b="Morbent Fels Schutzzauber lassen gewöhnlichen Stahl an seinem Rückzugsort auf dem Verlassenen Gut abprallen. Bischof Heller schickt Euch auf die Suche nach einer Waffe, die an das Heilige Licht gebunden ist. Ihr Schlüssel ist Lightforge Iron, ein seltenes, geweihtes Metall, dessen Hiebe heilige Wahrheit tragen und magische Schutzzauber durchdringen."},{t="Das Wrack der Third Fleet",b="Im Dämmerwald ist kein Lightforge Iron verfügbar. Bischof Heller erinnert sich, dass die Third Fleet von Kul Tiras vor Jahren an der gefährlichen Küste des Sumpflands nördlich von Eisenschmiede sank. Eine Galeone führte eine Ladung des kostbaren Erzes mit sich. Ihr reist zum Hafen von Menethil, um Glorin Stahlbraue zu treffen, einen zwergischen Kontaktmann, der die Sümpfe und ihre Wracks kennt."}},faq={{q="Warum muss ich den ganzen Weg ins Sumpfland reisen?",a="Morbent Fels dunkle Verzauberungen wehren gewöhnliche Angriffe ab. Laut Bischof Heller kann nur eine aus heiligem Lightforge Iron geschmiedete Waffe seine Schutzzauber durchbrechen. Die bekannte Lieferung liegt inmitten der Wracks der Third Fleet von Kul Tiras vor dem Hafen von Menethil.",al={"warum ins sumpfland","warum zum hafen von menethil","reise ins sumpfland"}},{q="Wer ist Morbent Fel?",a="Morbent Fel ist ein Nekromant, der auf dem Verlassenen Gut im Dämmerwald lebt. Seine Zauberei hat den Aufstand der Untoten, der die Region bedroht, maßgeblich angeheizt. Dunkelhains Überleben hängt davon ab, ihn zu besiegen.",al={"wer ist morbent fel","wer ist der nekromant","nekromant im dämmerwald"}},{q="Wer ist Glorin Stahlbraue?",a="Glorin Stahlbraue ist ein Zwerg im Hafen von Menethil im Sumpfland. Er ist ein Verbündeter der Kirche des Heiligen Lichts und kennt die Küste, die Schiffswracks und die Bergungsarbeiten im Sumpf.",al={"wer ist stahlbraue","stahlbraues rolle"}},{q="Was ist Lightforge Iron?",a="Lightforge Iron ist ein besonders geweihtes Metall, das die Priesterschaft schätzt. Daraus geschmiedete Waffen tragen heilige Macht, die dunkle Schilde und nekromantische Flüche durchdringen kann, denen gewöhnliches Eisen nichts anhaben kann.",al={"was bewirkt lightforge iron","lightforge-metall","gesegnetes eisen"}},{q="Was geschah mit der Third Fleet von Kul Tiras?",a="Vor Jahren sank die Third Fleet von Kul Tiras an der rauen, sumpfigen Küste des Sumpflands. Ihre Schiffsrümpfe liegen noch immer unter Wasser, mit verlorener Fracht, ertrunkenen Seeleuten und im Wasser lebenden Raubtieren zwischen den Wracks.",al={"schicksal der third fleet","kul tiras schiffe sumpfland","wie sanken die schiffe"}},{q="Kommt es bei dieser Quest sofort zu Kämpfen?",a="Ihr reist als Kurier vom Dämmerwald durch das Königreich Sturmwind und Khaz Modan zum Hafen von Menethil. Dort nehmt Ihr Kontakt mit Glorin Stahlbraue auf.",al={"gibt es kämpfe","reine reisequest"}}},fx={ade8f412={q="Warum schickt Bischof Heller Euch auf diese Quest?",a="Bischof Heller weiß, dass der Nekromant Morbent Fel eine tödliche Bedrohung für den Dämmerwald darstellt und nicht mit gewöhnlichen Mitteln besiegt werden kann. Um eine solch dunkle Macht zu besiegen, benötigt Ihr eine Waffe, die mit heiliger Macht gesegnet ist und aus heiligem Lightforge Iron geschmiedet wurde. Da dieses Eisen mit der Third Fleet von Kul Tiras im Meer verloren ging, schickt Heller Euch nach Norden zum Hafen von Menethil, um seinen zwergischen Mitarbeiter Glorin Stahlbraue zu konsultieren, in der Hoffnung, das versunkene Metall zu bergen.",al={"warum will bischof farthing lightforge iron","farthing motiv doomed fleet","warum die doomed fleet finden"}},a631378f={q="Warum können Bischof Heller oder The Nachtwache nicht selbst mit Morbent Fel fertig werden?",a="The Nachtwache ist gefährlich dünn besetzt und hat schon alle Hände voll zu tun, die Grenzen des Dämmerwalds vor dem Ansturm gedankenloser Untoter, Worgen und Spinnen zu schützen. Bischof Heller muss seinen Pflichten in der Kathedrale des Lichts in Sturmwind nachkommen, und weder er noch die örtliche Miliz können die Zeit oder das Personal für einen langen Marsch über den Kontinent bis in das Sumpfland entbehren. Als unabhängiger Reisender habt Ihr die Freiheit und die Entschlossenheit, nach dem verlorenen Eisen zu suchen und dem Nekromanten direkt entgegenzutreten.",al={"warum mich zur doomed fleet schicken","warum geht the night watch nicht","warum braucht bischof farthing mich"}}},fp="16,186,22.267.0,28.330.0,52.242.0,19.194.0,24.176.0,24.197.0,46.191.0,48.142.0"}
P.entries["quest:271"] = {n="Vyrin's Revenge",s="In der Weitschreiter-Lodge bittet Euch ein Jäger, eine alte Rechnung mit Ol' Sooty zu begleichen. Der Bär fügte Daryl dem Jüngling vor einem Jahr bei einer Jagd eine Narbe zu.",h="In der Weitschreiter-Lodge bittet Euch ein Jäger, eine alte Rechnung mit Ol' Sooty zu begleichen.",kw={"bär","daryl der jüngling","die weitschreiter-lodge","ol' sooty","narbe","thelsamar","vyrin's revenge"},ang={["class:Hunter"]="Als Jäger werdet Ihr gebeten, dem Bären entgegenzutreten, der den Jägern der Weitschreiter-Lodge entkam und Daryl eine Narbe zufügte."},sec={{t="Eine alte Narbe",b="Ein Jäger in der Weitschreiter-Lodge bittet Euch, Ol' Sooty entgegenzutreten, dem Bären, der Daryl dem Jüngling eine Narbe zufügte. Die Jäger der Lodge hatten ihn nicht erlegen können, und Daryl versuchte vor einem Jahr sein Glück. Sein Versuch hinterließ die Narbe über seinem Auge. Ol' Sooty hält sich bei seiner Höhle in den Hügeln oberhalb von Thelsamar auf."},{t="In der Lodge",b="In der Weitschreiter-Lodge bringt Ihr Daryl dem Jüngling einen Beweis für Ol' Sootys Ende. Er erkennt den Bärenkopf und berührt seine Narbe. Dann beginnt er zu zittern und fleht Euch an, ihn fortzubringen."}},faq={{q="Wer ist Ol' Sooty?",a="Ol' Sooty ist der Bär, der Daryl dem Jüngling vor einem Jahr bei einer Jagd eine Narbe zufügte.",al={"ol sooty bär","sooty","bär fügte daryl narbe zu"}},{q="Wer ist Daryl der Jüngling?",a="Daryl der Jüngling ist ein geschickter Jäger in der Weitschreiter-Lodge. Ol' Sooty hinterließ ihm eine Narbe über seinem Auge.",al={"daryls vorgeschichte","wer ist daryl","daryls narbe"}},{q="Wo lebt Ol' Sooty?",a="Ol' Sooty ist in der Umgebung seiner Höhle in den Hügeln oberhalb von Thelsamar zu finden.",al={"wo ist ol sooty","sooty fundort","bärenhöhle"}},{q="Warum will der Jäger Ol' Sooty töten lassen?",a="Ol' Sooty fügte Daryl vor einem Jahr bei einer Jagd eine Narbe zu, und ein Jäger in der Weitschreiter-Lodge will Vergeltung.",al={"warum sooty töten","vyrin rache warum","daryls rache"}}},fp="15,140,11.292.0,12.182.1,17.80.0,27.105.0,26.68.0,42.97.0"}
P.entries["quest:272"] = {n="Prüfung des Seelöwen",s="Druiden in der Mondlichtung suchen durch einen heiligen Ritus den Geist des Seelöwen. Sie bergen zwei verstreute Anhängerhälften für Beweglichkeit und Belastbarkeit und vereinen sie dann am Schrein von Remulos, um sich auf die Aquatic Form vorzubereiten.",h="Druiden in der Mondlichtung suchen durch einen heiligen Ritus den Geist des Seelöwen.",kw={"aquatic form","dendrite sternenschauer","halber anhänger der wasser-beweglichkeit","halber anhänger der wasser-belastbarkeit","mondlichtung","nachthafen","anhänger des seelöwen","schrein von remulos","prüfung des seelöwen"},ang={["class:Druid"]="Dieser Ritus ist Druiden vorbehalten. Er prüft ihre spirituelle Reife und Ausgeglichenheit, bevor sie mit Wassergeistern Zwiesprache halten und die Gestalt des Seelöwen annehmen dürfen.",["race:NightElf"]="Als langjährige Hüter der Mondlichtung und des Zirkels des Cenarius verehren Nachtelfendruiden Dendrite Sternenschauers Lehren und den heiligen Boden um den Schrein von Remulos.",["race:Tauren"]="Für Taurendruiden, die erst kürzlich im Zirkel des Cenarius willkommen geheißen wurden, stärkt die Prüfung in der Mondlichtung ihre Verbindung zu den Naturgeistern und vertieft ihre Bindung zu ihren Nachtelfenmentoren."},sec={{t="Der Weg zur Aquatic Form",b="Druideninitianden in der Mondlichtung durchlaufen Prüfungen der Einstimmung, während sie sich darauf vorbereiten, Azeroths tiefe Gewässer zu durchqueren. Die Prüfung des Seelöwen folgt auf frühere Vorbereitungen in ihrer spirituellen Ausbildung. Dendrite Sternenschauer beaufsichtigt sie in Nachthafen, wo Initianden lernen, die anmutige Schnelligkeit des Seelöwen mit seiner zähen Ausdauer ins Gleichgewicht zu bringen. Beides ist nötig, um seine Gestalt anzunehmen und den Meerestiefen standzuhalten."},{t="Beweglichkeit und Belastbarkeit",b="Im Mittelpunkt der Prüfung steht die Wiedervereinigung der beiden Hälften des Anhängers des Seelöwen. Eine verkörpert die Beweglichkeit des Seelöwen, wenn er durch reißende Strömungen gleitet. Die andere verkörpert seine Belastbarkeit, die Standhaftigkeit, lange in eiskaltem Wasser zu tauchen, ohne zu erlahmen. Initianden suchen Rat bei den Bewohnern der Mondlichtung, während sie überall auf der Welt nach den verstreuten Relikten suchen."},{t="Der Schrein von Remulos",b="Sobald beide Hälften gefunden sind, bringt der Initiand sie in die Nähe des Schreins von Remulos, wo sie zu einem Talisman vereint werden können. Die Energien des Schreins verbinden Beweglichkeit und Belastbarkeit in Harmonie. Anschließend überreicht der Initiand Dendrite Sternenschauer in Nachthafen den wiederhergestellten Anhänger. Mit dem Anhänger zeigt der Druide seine Bereitschaft, den Seelöwenaspekt anzunehmen und die Aquatic Form zu erwecken."}},faq={{q="Was ist die Prüfung des Seelöwen?",a="Druiden in der Mondlichtung bergen zwei Anhängerhälften und vereinen sie am Schrein von Remulos. Die Hälften verkörpern Beweglichkeit und Belastbarkeit, und der wiederhergestellte Anhänger wird Dendrite Sternenschauer als Teil des Weges zur Aquatic Form überreicht.",al={"prüfung des seelöwen quest","was ist die prüfung des seelöwen","seelöwenprüfung"}},{q="Wer vergibt die Quest Prüfung des Seelöwen?",a="Warden Tajarri am Schrein von Remulos in der Mondlichtung vergibt die Prüfung. Initianden suchen Rat bei den Bewohnern, vereinen die Anhängerhälften nahe dem Schrein und bringen den fertigen Anhänger dann zu Dendrite Sternenschauer in Nachthafen.",al={"wer vergibt die prüfung des seelöwen","wo beginnt die prüfung des seelöwen","prüfung des seelöwen questgeber"}},{q="Was verkörpern die beiden Anhängerhälften?",a="Die Hälften verkörpern die Beweglichkeit und Belastbarkeit des Seelöwen. Eine steht für die Anmut und Schnelligkeit, durch tiefes Wasser zu gleiten; die andere für die Ausdauer und Widerstandskraft auf langen Reisen unter Wasser. Druiden müssen beide Eigenschaften gleichermaßen achten und verkörpern, um ihre Gestaltwandlungskünste zu meistern.",al={"was sind die anhängerhälften","bedeutung der anhängerhälften","hälften für beweglichkeit und belastbarkeit"}},{q="Wo befinden sich die Anhängerhälften?",a="Initianden erfahren in Gesprächen mit den Bewohnern der Mondlichtung, wo der Halbe Anhänger der Wasser-Beweglichkeit und der Halbe Anhänger der Wasser-Belastbarkeit verborgen sind. Einheimische Druiden und Dorfbewohner geben Hinweise auf die fernen Gewässer, in denen die jeweilige Hälfte verloren ging oder versteckt wurde.",al={"wie anhängerhälften finden","wo die anhängerhälften finden","anhänger des seelöwen fundorte der hälften"}},{q="Wo setzt Ihr den Anhänger des Seelöwen zusammen?",a="Die Hälften müssen nahe dem Schrein von Remulos in der Mondlichtung vereint werden. Die heilige Aura des Schreins hilft dabei, Beweglichkeit und Belastbarkeit in einem Talisman zu vereinen.",al={"wie anhängerhälften verbinden","wo anhängerhälften vereinen","wo ist der schrein von remulos anhänger"}},{q="Warum müssen Druiden Beweglichkeit und Belastbarkeit ins Gleichgewicht bringen?",a="Dendrite Sternenschauer lehrt, dass Beweglichkeit und Belastbarkeit unter Wasser im Gleichgewicht sein müssen. Schnelligkeit ohne Ausdauer führt zur Erschöpfung, während Belastbarkeit ohne Schnelligkeit einen Schwimmer starken Strömungen hilflos ausliefert. Druiden brauchen beide Eigenschaften, um den Geist des Seelöwen zu verkörpern.",al={"warum beweglichkeit und belastbarkeit","seelöweneigenschaften druide","bedeutung der prüfung des seelöwen"}},{q="Was bringt der Abschluss der Prüfung?",a="Der Abschluss der Prüfung bringt den wiederhergestellten Anhänger des Seelöwen ein und erfüllt eine wichtige Voraussetzung für das Erlangen der Aquatic Form. Die Beherrschung von Beweglichkeit und Belastbarkeit gibt dem Initianden eine spirituelle Grundlage, um eine Gestalt anzunehmen, die unter Wasser atmen und schnell schwimmen kann.",al={"was bringt die prüfung des seelöwen","seelöwenprüfung belohnung","gewährt dies aquatic form"}}},fp="21,210,24.398.0,21.373.0,21.372.0,34.228.0,42.224.0,41.281.0,37.254.0,50.144.0,46.274.0,39.259.0"}
P.entries["quest:273"] = {n="Nachschub für die Ausgrabungsstätte",s="Jern Hornhelm schickt Euch von Thelsamar einem langsamen Wagen mit Sprengpulver für Eisenbands Ausgrabungsstätte hinterher. Die drei Zwerge, die ihn führen, ziehen am Ufer des Lochs entlang nach Süden.",h="Jern Hornhelm schickt Euch von Thelsamar einem langsamen Wagen mit Sprengpulver für Eisenbands...",kw={"sprengpulver","huldar","eisenband","jern hornhelm","loch modan","miran","nachschub für die ausgrabungsstätte","saean","thelsamar"},ang={["profession:Mining"]="Ihr kennt die Gefahr, explosives Sprengpulver über unwegsames Gelände zu transportieren. Die Lieferung ist für die Ausgräber im Süden unerlässlich.",["race:Dwarf"]="Als Bronzebartzwerg helft Ihr, Eisenbands Arbeit mit Nachschub zu versorgen, indem Ihr die Sprengpulverlieferung auf den gefährlichen Straßen von Loch Modan schützt."},sec={{t="Schwere Fracht am Ufer",b="Im südlichen Loch Modan braucht Eisenbands Ausgrabungsstätte Sprengpulver, um harten Fels zu durchbrechen. Das Pulver gelangt zuerst nach Thelsamar, wo Jern Hornhelm Huldar, Miran und Saean damit beauftragt, drei explosive Fässer nach Süden zu transportieren. Die schwere Last verlangsamt ihr Packgespann auf der Uferstraße, sodass Ihr Zeit habt, sie einzuholen und unterwegs zu helfen."},{t="Verrat in den Schatten",b="Huldars Wagen wurde auf der südlichen Straße überfallen. Dunkeleisenzwerge griffen an, um die archäologischen Arbeiten der Bronzebart-Expedition zu sabotieren. Saean hatte fast ein Jahr lang an Huldars Seite gearbeitet, half jedoch als Sympathisant der Dunkeleisenzwerge dabei, den Hinterhalt zu organisieren."}},faq={{q="Wer vergibt die Quest Nachschub für die Ausgrabungsstätte?",a="Jern Hornhelm schickt Euch von Thelsamar los, nachdem Ihr ihm das Sprengpulver gebracht habt. Er bittet Euch, der Straße am Loch entlang nach Süden zu folgen und die Nachschubgruppe einzuholen.",al={"wer vergibt nachschub für die ausgrabungsstätte","questgeber nachschub für die ausgrabungsstätte","wo beginnt nachschub für die ausgrabungsstätte"}},{q="Wo sind Huldar und der Wagen zu finden?",a="Huldar und der Wagen befinden sich südlich von Thelsamar, an der Straße entlang des West- und Südufers des Lochs in Richtung Eisenbands Ausgrabungsstätte.",al={"huldar finden","huldar fundort","wo ist der wagen in loch modan"}},{q="Warum wird Sprengpulver zu Eisenband geschickt?",a="Ausgrabungsleiter Eisenband und sein Team graben an der südlichen Ausgrabungsstätte nach uralten Relikten. Sie brauchen Sprengpulver, um massiven Stein zu zertrümmern und unterirdische Schichten zu durchbrechen.",al={"warum braucht eisenband pulver","eisenband sprengpulver","warum sprengpulver zur ausgrabungsstätte"}},{q="Wer hat Huldars Wagen überfallen?",a="Jern erwartet Huldars Gruppe auf der üblichen Straße südlich von Thelsamar, die am Loch entlangführt. Ihr erfahrt, wer den Wagen angegriffen hat, wenn Ihr Huldar erreicht.",al={"wer hat den wagen angegriffen","wagenüberfall loch modan","wer hat huldar angegriffen"}},{q="Welche Rolle spielte Saean bei dem Angriff?",a="Saean reist mit Huldar und Miran, um die schweren Sprengpulverfässer zu transportieren. Ihr erfahrt von seiner Rolle bei dem Angriff, wenn Ihr die Gruppe einholt.",al={"wer ist saean","saeans verrat","was hat saean getan"}},{q="Welche Quest folgt, nachdem Huldar gefunden wurde?",a="Das Gespräch mit Huldar schließt diesen Teil der Reise ab. Sein Bericht über die Lieferung weist Euch den Weg zum nächsten Schritt.",al={"nächste quest nach nachschub für die ausgrabungsstätte","quest nach huldar"}}},fx={["72005fbc"]={q="Warum schickt Jern Hornhelm Euch hinter Huldar her?",a="Jern Hornhelm erkennt, dass Ihr kurz nach dem Aufbruch von Huldar und seiner Mannschaft mit dem schweren Wagen in Richtung Ironband's Excavation eingetroffen seid, um Sprengpulver abzuliefern. Da der Wagen schwer mit Fässern beladen ist, weiß Jern, dass sie nur langsam auf der südlichen Straße entlang des Lochs vorankommen werden. Er schickt Euch voraus, damit Ihr sie einholen und bei der lebenswichtigen Lieferung behilflich sein könnt.",al={"jern hornhelm motiv","warum huldar einholen","warum schickt jern euch"}}},fp="26,172,29.342.0,24.247.1,48.162.0,40.143.0,42.169.0,28.140.1,39.141.1,43.119.1"}
P.entries["quest:274"] = {n="Eine dunkle Bedrohung",s="Am Steinwerkdamm gefährdet seltsames Pulver Loch Modan und Eisenschmiede. Ashlan Schmunzelstein in Dun Modr identifiziert es als instabiles Seaforium, das bei Kontakt mit Wasser explodieren kann.",h="Am Steinwerkdamm gefährdet seltsames Pulver Loch Modan und Eisenschmiede.",kw={"ashlan schmunzelstein","sprengpulver","chefingenieur hinderweir vii.","eine dunkle bedrohung","entschärfungspaste","eisenschmiede","seaforium","sumpfland"},ang={["faction:Alliance"]="Die Verteidiger der Allianz müssen rasch handeln, um Chefingenieur Hinderweir VII. zu helfen und die Niederungen zu sichern, bevor feindliche Saboteure strategische Infrastruktur zerstören.",["profession:Engineering"]="Ingenieure werden Seaforium als äußerst starke, instabile Verbindung erkennen. Es erfordert behutsamen Umgang und präzise chemische Gegenmaßnahmen, um gewaltige Druckwellen zu verhindern.",["race:Dwarf"]="Für die Zwerge von Khaz Modan ist instabiles Seaforium nahe dem Zugang zu Dun Morogh und Eisenschmiede in den Händen von Sprengstoffsaboteuren eine existenzielle Bedrohung."},sec={{t="Ein brisanter Fund",b="Ashlan Schmunzelstein erkennt die silbernen Kristalle und den stechenden Geruch in Proben vom Steinwerkdamm. Das Pulver ist Seaforium. Solange es trocken bleibt, ist es reaktionsträge, doch Feuchtigkeit lässt es heftig reagieren. Eine unkontrollierte Explosion könnte Eisenschmiede aus dem Berg sprengen, warnt Ashlan."},{t="Wettlauf gegen die Zeit",b="Ashlan Schmunzelstein stellt eine Entschärfungspaste her, um dem Sprengstoff entgegenzuwirken. Um das Seaforium zu neutralisieren, benötigt Ihr die Paste, Lauerergift, zerstoßenen Kristall der Mo'grosh und eine Krokiliskenträne. Chefingenieur Hinderweir VII. muss sofort gewarnt werden, bevor Feuchtigkeit die Katastrophe auslöst."}},faq={{q="Was für ein Sprengstoff wurde am Damm gefunden?",a="Ashlan Schmunzelstein identifiziert das Pulver vom Damm als Seaforium, erkennbar an silbernen Kristallen und einem stechenden chemischen Geruch.",al={"was ist das für ein pulver","was ist das pulver","seaforiumpulver"}},{q="Warum ist Seaforium hier so gefährlich?",a="Seaforium ist im trockenen Zustand relativ harmlos, explodiert aber bei Kontakt mit Wasser mit verheerender Wirkung. Am Steinwerkdamm, der die Wassermassen von Loch Modan zurückhält, stellt es eine außergewöhnliche Gefahr dar.",al={"warum ist seaforium gefährlich","was bringt seaforium zur explosion"}},{q="Wer ist Ashlan Schmunzelstein?",a="Ashlan Schmunzelstein ist ein zwergischer Spezialist der Allianz, der im Sumpfland lebt. Seine Kenntnisse in Ingenieurskunst und Chemie ermöglichen es ihm, geheimnisvolle Pulver zu untersuchen und Neutralisierungsmittel herzustellen.",al={"wer ist ashlan","ashlan schmunzelstein identität"}},{q="Wer ist Chefingenieur Hinderweir VII.?",a="Chefingenieur Hinderweir VII. überwacht vom Steinwerkdamm in Loch Modan aus die Ingenieursarbeiten und die Verteidigung der Region. Der Ingenieur schützt die Infrastruktur der Zwerge.",al={"wer ist hinderweir","chefingenieur hinderweir"}},{q="Wie lässt sich das Seaforium neutralisieren?",a="Ashlans Entschärfungspaste muss mit Lauerergift, zerstoßenem Kristall der Mo'grosh und einer Krokiliskenträne vermischt werden, um die chemische Reaktion zu entschärfen.",al={"wie seaforium entschärfen","rezept zur seaforiumentschärfung","rezept für entschärfungspaste"}},{q="Welche Gefahr droht Eisenschmiede?",a="Ashlan warnt, dass eine unkontrollierte Detonation die umliegenden Gebirgssysteme durch Erschütterungen zum Einsturz bringen und Eisenschmiede aus dem Berg sprengen könnte.",al={"ist eisenschmiede in gefahr","wie wird eisenschmiede bedroht"}}},fx={["7e9e3f07"]={q="Warum will Ashlan Schmunzelstein, dass dies erledigt wird?",a="Ashlan erkannte, dass es sich bei der mysteriösen Substanz nicht um gewöhnliches Sprengpulver, sondern um instabiles Seaforyum handelt. Sobald Seaforyum mit Wasser in Berührung kommt, könnte seine Explosionskraft ganze Berge zum Einsturz bringen. Ashlan muss Chefingenieur Hinderweir VII. unverzüglich warnen, damit die zwergischen Ingenieure eine neutralisierende Lösung vorbereiten können, bevor die instabile Verbindung detoniert.",al={"warum schickt ashlan euch","ashlan motiv","warum hinderweir warnen"}}},fp="19,182,20.262.0,16.280.1,44.120.0,35.189.0,25.175.0,37.161.0,37.142.0,32.148.0"}
P.entries["quest:2741"] = {n="Der Super-Ei-o-Mat",s="Am Bedienfeld stottert Curgle Cranklehops neueste Erfindung wild, während Hippogryphen-Eier in die Maschine gelangen.",h="Am Bedienfeld stottert Curgle Cranklehops neueste Erfindung wild, während Hippogryphen-Eier in die Maschine...",kw={"curgle cranklehop","ei-o-mat","eggometer","feralas","hippogryphen-ei","tanaris"},sec={{t="Eine Maschine von Curgle Cranklehop",b="An ihrem Bedienfeld stottert Curgle Cranklehops neueste Erfindung wild. Sie nimmt ein Hippogryphen-Ei auf, das in den Bergen des südlichen Feralas rund um die Ruinen von Isildien zu finden ist."},{t="Was die Maschine tut",b="Legt ein Hippogryphen-Ei hinein, und Pieptöne und seltsame mechanische Geräusche antworten. Das Eggometer wiegt und misst das Ei und verpackt es dann in wenigen Augenblicken. Heraus kommt eine Eierkiste, die ein Ei irgendeiner Art enthält."}},faq={{q="Wer hat den Super-Ei-o-Mat gebaut?",a="Curgle Cranklehop hat den Super-Ei-o-Mat als ihre neueste Erfindung gebaut.",al={"wer hat den ei-o-mat gebaut","ei-o-mat erfinderin","curgle cranklehop erfindung"}},{q="Was braucht die Maschine zum Betrieb?",a="Die Maschine braucht ein Hippogryphen-Ei, das hineingelegt wird.",al={"was braucht der ei-o-mat","ei-o-mat benötigter gegenstand","hippogryphen-ei maschine"}},{q="Wo findet Ihr Hippogryphen-Eier?",a="Ihr findet Hippogryphen-Eier in den Bergen des südlichen Feralas, rund um die Ruinen von Isildien.",al={"hippogryphen-ei fundort","wo hippogryphen-eier finden","wo sind die eier in feralas"}}},fp="21,114,30.175.0,21.210.1,32.70.0,38.49.0,34.92.0"}
P.entries["quest:2742"] = {n="Rin'ji steckt in der Falle!",s="In der Quel'Danil-Hütte hat Rin'ji eine Axt verloren und wird gefangen gehalten. Rin'ji bittet einen Vorbeikommenden um Hilfe bei der Flucht, bietet eine Gegenleistung an und spricht von einem Geheimnis an den Overlook Cliffs.",h="In der Quel'Danil-Hütte hat Rin'ji eine Axt verloren und wird gefangen gehalten.",kw={"gefangener","eskorte","hinterland","overlook cliffs","quel'danil","rin'ji","tafel"},sec={{t="Eine Bitte um Fluchthilfe",b="In der Quel'Danil-Hütte hat Rin'ji Angst und wird gefangen gehalten. Die Axt ist fort, also fleht Rin'ji einen Vorbeikommenden um Hilfe bei der Flucht an. Viele mögen Rin'jis Art nicht. Dennoch bietet Rin'ji einer gütigen Seele, die hilft, etwas an und sagt, dass an den Overlook Cliffs ein Geheimnis verborgen liegt."},{t="Am Ende der Flucht",b="Eine Trolltafel trägt seltsame Zeichen. Niemand kann entziffern, was dort geschrieben steht."}},faq={{q="Wer ist Rin'ji?",a="Rin'ji ist ein Troll, der eine Axt verloren hat und in der Quel'Danil-Hütte im Hinterland gefangen genommen wurde. Rin'ji spricht von sich in der dritten Person und fleht einen Vorbeikommenden um Hilfe bei der Flucht an.",al={"rinji","wer ist der troll in quel'danil","wer ist rin'ji"}},{q="Wo wird Rin'ji gefangen gehalten?",a="Rin'ji wird in der Quel'Danil-Hütte im Hinterland gefangen gehalten.",al={"wo ist rin'ji","rinji fundort","quel'danil käfig"}},{q="Was bietet Rin'ji für Hilfe an?",a="Rin'ji bietet denen, die helfen, etwas an und sagt, dass an den Overlook Cliffs ein Geheimnis verborgen liegt.",al={"was ist rin'jis geheimnis","rinji belohnung","was ist an den overlook cliffs"}}},fp="18,182,17.257.0,24.81.1,14.176.0,29.62.0,32.93.0"}
P.entries["quest:2745"] = {n="Eindringen ins Schloss",s="In Burg Sturmwind schickt Elling Trias Euch zu seinem Mitstreiter Tyrion. Tyrion beobachtet Lord Gregor Lescovar seit Wochen von den königlichen Gärten aus.",h="In Burg Sturmwind schickt Elling Trias Euch zu seinem Mitstreiter Tyrion.",kw={"käseladen","defias","elling trias","eindringen ins schloss","lescovar","burg sturmwind","tyrion"},ang={["class:Rogue"]="Als Schurke helft Ihr zwei erfahrenen Untergrundagenten, den Sitz des menschlichen Adels zu infiltrieren. Ihre Arbeit zeigt, welches lautlose, tödliche Geschick nötig ist, um Sturmwind vor Bedrohungen am eigenen Hof zu schützen.",["faction:Alliance"]="Solange König Varian vermisst wird, kann sich das Königreich keinen Verrat in der höchsten gesetzgebenden Kammer der Burg leisten. Als Mitglied der Allianz helft Ihr, Verschwörer aufzuspüren, um die Stabilität des Reiches zu bewahren.",["race:Gnome"]="Als Gnom erlebt Ihr, wie Tyrion in Burg Sturmwind über lange Zeit verdeckte Überwachung betreibt. Seine Arbeit zeigt, wie gnomischer Einfallsreichtum sowohl der Spionage als auch dem Maschinenbau dient."},sec={{t="Eine Sache außerhalb des Gesetzes",b="In seinem Käseladen im Handelsdistrikt erkennt Elling Trias, dass die Bedrohung durch die Defias bis in die Führung des Königreichs reicht. Mit gewöhnlichen rechtlichen Mitteln lässt sich ein so gut geschützter und fest verwurzelter Adliger wie Lord Gregor Lescovar weder entlarven noch bestrafen. Deshalb schlägt Trias einen gefährlichen Weg vor: innerhalb von Burg Sturmwind außerhalb des Gesetzes Gerechtigkeit üben und die Verschwörung endgültig zerschlagen."},{t="Augen im Gebüsch",b="Elling Trias hat einen Agenten in den hohen Hallen: Tyrion, einen klugen Gnom, der sich geschickt zu verbergen weiß. Seit Wochen beobachtet Tyrion die Innenhöfe und königlichen Gärten der Burg. Er hat Lescovars Bewegungen verfolgt, beobachtet, wer dessen Gemächer betritt und wann der Verräter sich heimlich mit Kontaktleuten der Defias trifft. Ihr müsst Tyrion erreichen, ohne das Misstrauen der königlichen Wache zu wecken."},{t="Verrat am Hof",b="Lord Lescovars Bündnis mit dem Defias-Attentäter Marzon the Silent Blade zeigt, wie tief Sturmwinds Hof während der Abwesenheit von König Varian Wrynn verkommen ist. Adlige am Hof schmieden im Königreich Intrigen, während Gesetzlose von Westfall und dem Rotkammgebirge aus gegen seine Grenzen vordringen. Der Schlag gegen Lescovar soll die Korruption ausmerzen, bevor das Königreich zerbricht."}},faq={{q="Warum will Elling Trias die Sache außerhalb des Gesetzes regeln?",a="Lord Lescovar verfügt im House of Nobles über großen Einfluss und Reichtum. Ohne unwiderlegbare Beweise könnten Anschuldigungen gegen einen hochrangigen Lord eine politische Katastrophe auslösen, zur Unterdrückung von Beweisen und zur Hinrichtung von Hinweisgebern führen. Trias glaubt, dass nur geheimes, direktes Handeln die Bedrohung zuverlässig aufhalten kann.",al={"warum außerhalb des gesetzes","trias illegale gerechtigkeit","warum selbstjustiz"}},{q="Wo versteckt sich Tyrion?",a="Tyrion versteckt sich in den königlichen Gärten von Burg Sturmwind, gleich links neben dem Innenhof, nachdem Ihr die Haupttore durchschritten habt. Vom Gebüsch aus beobachtet er Lord Lescovars Gemächer, ohne die Wachen aufmerksam zu machen.",al={"wo ist tyrion","tyrion finden","tyrions standort"}},{q="Wer ist Tyrion?",a="Tyrion ist ein Geheimagent und Vertrauter von Elling Trias. Seit mehreren Wochen beobachtet er Burg Sturmwind, um Lord Gregor Lescovar zu verfolgen und dessen geheime Verbindungen zu den Defias aufzudecken.",al={"wer ist tyrion","tyrion gnom","trias freund"}},{q="Wer ist Lord Lescovar?",a="Lord Gregor Lescovar ist ein angesehener Adliger aus Sturmwind, der als Insider am königlichen Hof heimlich mit der Bruderschaft der Defias zusammenarbeitet. Er hilft ihnen, das Königreich von innen heraus zu sabotieren.",al={"lord lescovar","wer ist lescovar","lescovar defias"}},{q="Wer ist Marzon?",a="Marzon, bekannt als Silent Blade, ist ein Eliteattentäter der Defias. Er arbeitet direkt mit Lord Lescovar zusammen, um Angriffe und Attentate für die Bruderschaft zu koordinieren.",al={"marzon","marzon the silent blade","silent blade"}},{q="Warum sorgt sich Tyrion um seinen Ruf?",a="Tyrion befürchtet, dass Ihr während seiner geheimen Überwachung seine Tarnung auffliegen lasst. Außerdem beklagt er sich, dass schwer bewaffnete Abenteurer, die unter den Augen der Burgwachen neben ihm im königlichen Gebüsch herumlungern, verdächtig und unschicklich wirken.",al={"tyrion versteck im gebüsch","ruf im gebüsch"}}},fx={ae2213ef={q="Hinter wem seid Ihr in Burg Sturmwind her?",a="Elling Trias schickt Euch, um Euch um Lord Gregor Lescovar und seinen Komplizen Marzon zu kümmern. Lescovar ist ein Adliger, der direkt in der Burg Sturmwind agiert und wegen Hochverrats verdächtigt wird, während Marzon die gefährlichen Verschwörer außerhalb der Burgmauern vertritt. Trias und sein Kontakt Tyrion wollen beide Männer ausschalten, bevor ihre Umtriebe das Reich bedrohen können.",al={"wen zielen wir ab","wer ist das ziel bei infiltrating the castle","wer sind lescovar und marzon"}},["7d59c2b3"]={q="Warum schickt Elling Trias Euch, anstatt die Stadtwache von Sturmwind zu benutzen?",a="Lord Lescovar ist ein hochrangiger Adliger in der Burg Sturmwind, was eine offizielle Anschuldigung ohne unbestreitbare Beweise politisch unmöglich macht. Die Stadtwache untersteht dem Hof, wo der Adel das Sagen hat, und die Einschaltung offizieller Kanäle würde Lescovar wahrscheinlich warnen oder die Angelegenheit im bürokratischen Dschungel begraben. Trias verlässt sich auf einen unabhängigen Abenteurer, der sich einschleichen, sich mit Tyrion treffen und entschlossen Gerechtigkeit üben kann, ohne die Verschwörer zu warnen.",al={"warum mich schicken","warum nicht die wachen informieren","warum nicht sturmwindwachen"}}},fp="23,152,24.337.0,21.349.0,20.354.1,56.312.0,23.203.0,14.185.0,21.183.0,14.162.1,43.223.0"}
P.entries["quest:2746"] = {n="Nicht unwichtige Gegenstände",s="Tyrion braucht Seide und Äpfel, um Spybot heimlich zu Lord Lescovar in Burg Sturmwind zu schicken. Der mechanische Spion muss an den königlichen Wachen vorbeikommen und den Adligen belauschen.",h="Tyrion braucht Seide und Äpfel, um Spybot heimlich zu Lord Lescovar in Burg Sturmwind zu schicken.",kw={"clara","elling trias","infiltrating the castle","lord lescovar","seidenstoff","spybot","burg sturmwind","the attack","tyrion"},ang={["class:Rogue"]="Als Schurke erkennt Ihr, wie Agenten wie Tyrion und Elling Trias ungewöhnliche Überwachungsmethoden einsetzen und direkt unter den Augen der Adligen nachrichtendienstliche Arbeit im Inland betreiben.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, den jungen König Anduin und Hochlord Bolvar Fordragon zu schützen, indem Ihr korrupte Adlige entlarvt, die in Burg Sturmwind mit Gesetzlosen konspirieren.",["profession:Tailoring"]="Als Schneider wisst Ihr, dass feine Seide ebenso bei verdeckten Machenschaften helfen kann, wie sie sich für festliche Gewänder eignet."},sec={{t="Ein strafferer Zeitplan",b="Elling Trias, der Käsehändler, hat die Operation gegen Lord Gregor Lescovar vorgezogen. Er vermutet, dass Lescovars Machenschaften in Burg Sturmwind das Reich bedrohen. Tyrion stimmt dem strafferen Zeitplan in den Burggärten zu, doch Spybots Verkleidung muss sorgfältig vorbereitet werden."},{t="Die Kunst der Verkleidung",b="Tyrion will Spybot, eine kleine mechanische Vorrichtung, an den Burgwachen vorbeischicken, um Lescovar im Inneren der Burg zu erreichen. Seine seltsame Verkleidung als Frau soll jeden Verdacht zerstreuen. Ihr sammelt Äpfel passender Größe aus Claras Obstgarten direkt vor den Stadtmauern sowie Seidenballen für die Kleidung der Puppe."},{t="Verrat aufdecken",b="Tyrion überwachte Lord Lescovar zunächst wegen verdächtiger Hinweise, die den Adligen mit dem Schattenhammerkult in Verbindung brachten. Nun enthüllt er, dass Lescovar auch mit Verschwörern der Defias unter einer Decke steckt. Da dieser Verrat aufgedeckt ist, kann Lescovar nicht länger am königlichen Hof bleiben. Tyrions Überwachung wird zu einer Falle im Herzen des Königreichs."}},faq={{q="Warum braucht Tyrion Äpfel und Seidenstoff?",a="Tyrion braucht Äpfel und Seide, um Spybot als Frau zu verkleiden, damit er an den königlichen Wachen in Burg Sturmwind vorbeikommt. Die Seide wird zu Kleidung, und die Äpfel geben der Verkleidung ihre Form.",al={"warum äpfel","wofür sind die äpfel","tyrion verkleidungsmaterialien","spybot verkleidung"}},{q="Für wen arbeitet Tyrion?",a="Tyrion arbeitet mit Elling Trias zusammen, einem Käsehändler im Handelsdistrikt, der sein eigenes Netzwerk von Freunden in Sturmwind unterhält. Laut Trias erweist die Operation Mathias Shaw und SI:7 nur indirekt einen Gefallen.",al={"wem erstattet tyrion bericht","tyrions loyalität","elling trias tyrion"}},{q="Wo finde ich Claras Äpfel?",a="Claras Obstgarten liegt direkt vor den Stadttoren von Sturmwind im nördlichen Wald von Elwynn. Ihr könnt rund um den Hof frische Äpfel sammeln.",al={"claras hof standort","wo sind claras äpfel","frische äpfel sturmwind"}},{q="Was hat Tyrion Lord Lescovar ursprünglich verdächtigt zu tun?",a="Tyrion und Trias vermuteten zunächst, dass Lord Lescovar Verbindungen zum Schattenhammerkult hatte. Später deckten sie seine Zusammenarbeit mit der Bruderschaft der Defias auf, einen noch schwereren Verrat und eine unmittelbare Bedrohung für die Krone.",al={"lescovar schattenhammer","warum wurde gegen lescovar ermittelt","tyrion lescovar vorgeschichte"}},{q="Was ist der nächste Schritt nach der Ablieferung dieser Gegenstände?",a="Nachdem Spybot ausgestattet und in die Burg geschickt wurde, erhaltet Ihr in „The Attack!“ den Auftrag, die Verschwörer zu stellen und auszuschalten.",al={"was passiert als nächstes","nach nicht unwichtige gegenstände","nächste quest nach nicht unwichtige gegenstände"}},{q="Warum einen mechanischen Spion einsetzen, statt sich persönlich hineinzuschleichen?",a="Die königlichen Wachen von Burg Sturmwind prüfen jeden genau, der den Thronsaal und die privaten Innenhöfe betritt. Als Priesterin verkleidet kann Spybot an ihnen vorbeikommen, mit Lescovar sprechen und ihn für ein Treffen mit Marzon in den Garten locken, wo kein bekannter Agent nahe genug herankäme.",al={"warum spybot einsetzen","warum nicht selbst hineinschleichen","burg sturmwind sicherheit"}}},fx={["7ec9a91a"]={q="Warum will Tyrion Lord Lescovar zu Fall bringen?",a="Tyrion und sein Mitarbeiter Elling Trias verfolgen Lord Lescovar seit Wochen, da der Verdacht auf subversive Verbindungen besteht. Während sie ursprünglich mögliche Verbindungen zum Kultisten des Schattenhammers untersuchten, macht die Entdeckung, dass Lescovar aktiv mit The Defias Brotherhood konspiriert, ihn zu einer unmittelbaren und ernsten Gefahr für Sturmwind. Tyrion beabsichtigt, ihn zu entlarven und zu neutralisieren, bevor sein Verrat die Stadt zerreißen kann.",al={"warum lescovar stoppen","tyrion motiv","warum lescovar untersuchen"}},["73f45f0b"]={q="Warum braucht Tyrion die Hilfe eines Außenstehenden anstelle der Stadtwachen?",a="Lord Lescovar ist ein Adliger innerhalb der Burg Sturmwind, was eine offene Anschuldigung oder einen direkten Eingriff der Wache ohne unbestreitbare Beweise unmöglich macht. Die Behörden von Sturmwind sind nicht in der Lage, aufgrund von Vermutungen gegen einen hochrangigen Adligen vorzugehen. Tyrion operiert im Schatten im Auftrag von Meister Trias und benötigt einen unabhängigen Agenten, der bereit ist, geheime Vorräte zu sammeln und schließlich die gefährliche, verdeckte Konfrontation persönlich zu führen.",al={"warum nicht stadtwachen","warum braucht tyrion mich","warum auf abenteurer verlassen"}}},fp="25,175,21.275.0,23.313.0,18.324.1,43.180.0,26.195.0,31.126.0,58.208.1,51.132.1,62.252.0"}
P.entries["quest:2747"] = {n="Ein außergewöhnliches Ei",s="In Tanaris sucht Curgle Cranklehop ein außergewöhnliches Ei aus Feralas.",h="In Tanaris sucht Curgle Cranklehop ein außergewöhnliches Ei aus Feralas.",kw={"curgle cranklehop","außergewöhnliches ei","feralas","super egg-o-matic","tanaris"},sec={{t="Eine Rarität aus Feralas",b="Curgle Cranklehop sagt, dass nur wenige Eier aus Feralas in außergewöhnlichem Zustand ankommen. Solche Eier sind die seltensten von allen. Curgle sucht ein solches Ei."}},faq={{q="Wer sucht ein außergewöhnliches Ei?",a="Curgle Cranklehop, Erfinder des Super Egg-O-Matic, sucht ein außergewöhnliches Ei.",al={"wer startet ein außergewöhnliches ei","wer vergibt die quest ein außergewöhnliches ei","curgle cranklehop ei"}},{q="Woher kommen diese außergewöhnlichen Eier?",a="Diese außergewöhnlichen Eier kommen aus Feralas, doch nur wenige kommen in außergewöhnlichem Zustand an.",al={"außergewöhnliches ei fundort","wo außergewöhnliches ei finden","ei aus feralas"}},{q="Was kommt vor diesem Auftrag?",a="Dieser Auftrag folgt auf The Super Egg-O-Matic.",al={"voraussetzung für außergewöhnliches ei","ein außergewöhnliches ei questreihe","vorherige quest für außergewöhnliches ei"}}},fp="20,70,21.134.0,40.81.0,44.85.0,31.43.0"}
P.entries["quest:2748"] = {n="Ein gutes Ei",s="Curgle Cranklehop spricht von einem Ei, das frei von den bösen Beschwörungen der Gordunnioger schlüpfen könnte.",h="Curgle Cranklehop spricht von einem Ei, das frei von den bösen Beschwörungen der Gordunnioger schlüpfen...",kw={"curgle cranklehop","darnassus","gutes ei","gordunni","ogerbeschwörungen","super egg-o-matic","tanaris"},sec={{t="Was es gut macht",b="Curgle Cranklehop sagt, ein Ei habe gute Chancen, unberührt von den unheilvollen Gesängen der Gordunnioger zu schlüpfen, wenn die Bedingungen ideal sind."},{t="Was Curgle als Nächstes tut",b="Curgle nimmt das Ei an sich und plant, es nach Darnassus zu schicken. Dort wird es hoffentlich bald schlüpfen."}},faq={{q="Was macht ein Ei zu einem guten Ei?",a="Unter idealen Bedingungen kann ein Ei frei von dem Bösen schlüpfen, das die Beschwörungen der Gordunnioger mit sich bringen.",al={"was ist ein gutes ei","geschichte des guten eis","warum gutes ei"}},{q="Was kam vor diesem Schritt?",a="The Super Egg-O-Matic kam vor diesem Schritt.",al={"voraussetzung für gutes ei","vorherige quest gutes ei"}}},fp="10,98,18.136.0,21.89.1,40.96.0,27.44.0"}
P.entries["quest:2749"] = {n="Ein gewöhnliches Ei",s="Curgle Cranklehop pflegt gewöhnliche Hippogrypheneier, doch nur etwa die Hälfte davon schlüpft.",h="Curgle Cranklehop pflegt gewöhnliche Hippogrypheneier, doch nur etwa die Hälfte davon schlüpft.",kw={"curgle cranklehop","feralas","hippogryph","gewöhnliches ei","tanaris","super egg-o-matic"},sec={{t="Eine halbe Chance",b="Nur etwa die Hälfte der gewöhnlichen Hippogrypheneier schlüpft. Curgle Cranklehop gibt sich alle Mühe, jedes einzelne zu hegen, und hofft, dass es mit etwas Glück schlüpft."}},faq={{q="Wer ist Curgle Cranklehop?",a="Curgle Cranklehop hat den Super Egg-O-Matic erfunden und arbeitet mit Hippogrypheneiern aus Feralas.",al={"wer ist curgle","curgle cranklehop"}},{q="Was geschieht mit dem gewöhnlichen Hippogryphenei?",a="Curgle pflegt das gewöhnliche Hippogryphenei und hofft auf Glück. Nur etwa die Hälfte solcher Eier schlüpft.",al={"was macht curgle mit dem ei","schlüpfchance"}},{q="Woher stammen diese Eier?",a="Die Eier stammen aus Feralas.",al={"wo ist das ei zu finden","gewöhnliches ei fundort"}},{q="Was kam vor diesem Schritt?",a="Der Schritt davor ist der Super Egg-O-Matic.",al={"vorausgesetzte quest","was ist die vorherige quest"}}},fp="15,79,13.136.0,25.93.0,44.96.0,30.27.0,27.50.0"}
P.entries["quest:275"] = {n="Schwärendes Land",s="Im östlichen Sumpfland spürt Rethiel, wie sich eine Krankheit im Sumpf ausbreitet. Der Sumpfbestienhüter bittet Reisende, Fen Creepers zu vernichten, in der Hoffnung, das steigende Fieber des Landes zu lindern.",h="Im östlichen Sumpfland spürt Rethiel, wie sich eine Krankheit im Sumpf ausbreitet.",kw={"schwärendes land","fen creepers","sumpfhüter","marschen","rethiel","moore im sumpfland","sumpfland"},ang={["class:Druid"]="Rethiels Arbeit spiegelt die Pflicht eines Druiden wider, die Natur zu heilen und aufgewühlte elementare Verderbnis zu besänftigen, damit die Erde ihr Gleichgewicht wiederfindet.",["class:Shaman"]="Fen Creepers verzerren Erde und Wasser, weshalb ihre Vernichtung hilft, die entzweiten Elementargeister zu besänftigen.",["race:NightElf"]="Als Nachtelf könnt Ihr in den Östlichen Königreichen einem einsamen Sumpfbestienhüter begegnen, der mit Sturmwind verbündet ist. Selbst die Geister des Landes suchen Hilfe, um verwundetes Land zu heilen."},sec={{t="Schwärende Marschen",b="Rethiel der Sumpfhüter wacht von einem Hain inmitten der Marschen aus über das Sumpfland. Der Morast war schon immer unwirtlich, doch nun breitet sich eine unnatürliche Krankheit darin aus. Rethiel spürt Fieber in der Erde. Es verzerrt die wilde Natur zu geistlosen, schlurfenden Schrecken."},{t="Den Sumpf reinigen",b="Fen Creepers sind verrottende Massen aus Sumpfpflanzen, die durch die Wasserwege streifen. Rethiel nennt sie kranke Geschwüre, die auf dem Land anschwellen. Ihre gequälte Gegenwart wühlt den Sumpf auf, weshalb Rethiel vorbeiziehende Verbündete bittet, sie zu vernichten. Ihre verworrenen Überreste können dann in den Schlamm sinken."}},faq={{q="Wer ist Rethiel der Sumpfhüter?",a="Rethiel der Sumpfhüter ist eine Sumpfbestie, die in Greenwarden's Grove im östlichen Sumpfland lebt. Rethiel wahrt das natürliche Gleichgewicht des Sumpfes und bemüht sich, seine Leiden zu lindern und verderbtes elementares Wachstum einzudämmen.",al={"wer ist rethiel","rethiel sumpfhüter hintergrundgeschichte","wer vergibt schwärendes land"}},{q="Was sind Fen Creepers?",a="Fen Creepers sind feindselige Pflanzen- und Sumpfelementare, die durch die Wasserwege des Sumpflands streifen. Sie sind massige, schlurfende Gebilde aus belebten Ranken, Schlamm und verrottenden Sumpfpflanzen.",al={"fen creepers","was ist ein fen creeper","creepers sumpfland"}},{q="Warum will Rethiel die Fen Creepers vernichten lassen?",a="Rethiel sieht die Fen Creepers als fiebrige Anzeichen der zunehmenden Krankheit des Sumpfes. Rethiel glaubt, dass ihre Vernichtung ihre Körper in der Erde aufgehen lässt und das aufgewühlte Land beruhigt.",al={"warum fen creepers töten","warum schwärendes land"}},{q="Was verursacht das Schwären im Sumpfland?",a="Rethiel weiß nicht, was das Schwären im Sumpfland verursacht. Rethiel spürt die Qualen des Landes und besänftigt elementare Unruhe, wo immer sie aufkommt.",al={"warum ist das sumpfland krank","ursache der krankheit im sumpfland"}},{q="Wo im Sumpfland sind Fen Creepers zu finden?",a="Fen Creepers durchstreifen die feuchten Wasserwege, schlammigen Ufer und zentralen Kanäle des Sumpflands, besonders nahe den tieferen Mooren westlich von Greenwarden's Grove.",al={"fen creeper fundorte","wo sind fen creepers zu finden"}},{q="Hängt diese Quest mit anderen Aufgaben für Rethiel zusammen?",a="Ja. Rethiels Sorge darüber, dass die Mosshide-Gnolle Bäume im Sumpfland verbrennen, führte zu Fire Taboo. Rethiel arbeitet weiterhin daran, das Gleichgewicht des Sumpfes zu schützen.",al={"sumpfhüter questreihe","rethiel quests"}}},fp="20,184,19.253.0,17.279.0,31.211.0,22.169.0,49.184.0,42.149.0,45.143.0,51.148.0"}
P.entries["quest:2750"] = {n="Ein schlechtes Ei",s="Curgle Cranklehop kümmert sich darum, wenn ein Hippogryphenei nicht mehr zu retten ist.",h="Curgle Cranklehop kümmert sich darum, wenn ein Hippogryphenei nicht mehr zu retten ist.",kw={"schlechtes ei","curgle cranklehop","feralas","super egg-o-matic","tanaris"},sec={{t="Ein unrettbares Ei",b="Manche Hippogrypheneier sind nicht zu retten. Curgle Cranklehop kümmert sich um jene, aus denen niemals etwas schlüpfen wird."},{t="Was daraus wird",b="Curgle bringt das Ei zur ordnungsgemäßen Entsorgung fort. Nicht jedes Ei ist zu retten, sagt Curgle. Ihr könnt es mit einem anderen Ei aus Feralas erneut versuchen."}},faq={{q="Wer nimmt das schlechte Ei an?",a="Curgle Cranklehop nimmt das schlechte Ei an.",al={"wem das schlechte ei geben","curgle cranklehop ei","wer nimmt das schlechte ei"}},{q="Kann das Ei gerettet werden?",a="Nein. Ein schlechtes Ei ist nicht zu retten, und daraus wird niemals etwas schlüpfen.",al={"kann aus dem schlechten ei etwas schlüpfen","wird aus dem schlechten ei etwas schlüpfen","schlechtes ei retten"}},{q="Was kam davor?",a="Es folgt auf The Super Egg-O-Matic.",al={"vorherige quest","voraussetzung","schlechtes ei voraussetzung"}}},fp="9,69,20.92.0,18.136.1,24.38.0,21.51.0,22.33.0"}
P.entries["quest:2751"] = {n="Barbarische Waffenschmiedekunst",s="In Orgrimmar sucht Orokk Omosh einen Lehrling, der die Schmiedekunst seiner Familie fortführt. Da er keine Erben hat, soll ein angehender Schmied zunächst eine sichere Hand im Umgang mit Bronze beweisen, bevor er sein Wissen weitergibt.",h="In Orgrimmar sucht Orokk Omosh einen Lehrling, der die Schmiedekunst seiner Familie fortführt.",kw={"barbarische waffenschmiedekunst","schmiedekunst","bronze","vermächtnis","omosh","orgrimmar","orokk omosh"},ang={["faction:Horde"]="Als Mitglied der Horde teilt Ihr die Überzeugung der Omosh, dass Metallarbeiten im Kampf erprobt und mit dem Blut der Feinde befleckt werden sollten.",["profession:Blacksmithing"]="Als Schmied der Horde erreicht Ihr einen Meilenstein auf dem Weg von einfachen Bronze- und Kupferarbeiten zu fortgeschritteneren Rüstungstraditionen."},sec={{t="Das Ende der Omosh-Linie",b="Orokk Omosh arbeitet an den Ambossen von Orgrimmar, während die Vergangenheit seiner Familie schwer auf ihm lastet. Seit zwanzig Generationen formt die Omosh-Linie Erz zu Waffen und Rüstungen für die Horde. Orokk hat keine Verwandten und kann keine Kinder zeugen, weshalb er sich als Versager seiner Linie betrachtet. Da das Familienhandwerk bedroht ist, stellt er seinen Stolz auf die Blutlinie zurück und sucht einen Lehrling, der ihre Schmiedetraditionen fortführt."},{t="Eine Prüfung mit Metall und Zahn",b="Orokk gibt seine Geheimnisse keinem ungeprüften Schmied preis. Er verlangt zwei gemusterte Bronzearmschienen, zwei Bronzegroßschwerter und zwei scharfe Bestienklauen als Beweis für das Können am Amboss. Für ihn ist Schmiedekunst kein müßiger Luxus. Ihre höchste Ehre sind Rüstung und Stahl, die mit Feindesblut befleckt sind. Erfüllt Ihr seine Forderungen, glaubt er vielleicht, dass ein Lehrling das Omosh-Vermächtnis bewahren kann, und gibt Euch die Gelegenheit, mehr über das Handwerk zu lernen."}},faq={{q="Wer ist Orokk Omosh?",a="Orokk Omosh ist ein Schmiedemeister in Orgrimmar und gehört zur zwanzigsten Generation der Omosh-Linie. Da er weder Verwandte noch Erben hat, sucht er einen Außenstehenden, der das Schmiedewissen des Klans bewahrt.",al={"orokk omosh","wer ist orokk","omosh schmied"}},{q="Warum braucht Orokk jemand anderen, den er unterrichten kann?",a="Orokk hat keine lebenden Verwandten mehr und kann keine Kinder bekommen. Er braucht einen Lehrling, der die Baupläne und Techniken seiner Werkstatt erbt, sonst endet mit ihm das Schmiedewissen von zwanzig Generationen.",al={"warum ein lehrling","orokks erbe","warum stirbt das omosh-vermächtnis aus"}},{q="Welche Gegenstände werden benötigt, um Orokk das eigene Können zu beweisen?",a="Orokk verlangt zwei gemusterte Bronzearmschienen, zwei Bronzegroßschwerter und zwei scharfe Klauen von wilden Raubbestien.",al={"was wird für barbarische waffenschmiedekunst benötigt","gegenstände für barbarische waffenschmiedekunst","barbarische waffenschmiedekunst abgeben"}},{q="Was kommt nach dem Abschluss von Barbarische Waffenschmiedekunst?",a="Nachdem Ihr Euer grundlegendes Können im Umgang mit Bronze bewiesen habt, setzt Orokk Eure Ausbildung mit On Iron Pauldrons fort. Dort geht Ihr zu schwereren Schmiedearbeiten mit Eisen und komplexen Plattenrüstungen über.",al={"nächste quest","questreihe nach barbarische waffenschmiedekunst","was folgt danach"}}},fx={["2a7cea14"]={q="Warum benötigt Orokk die Musterverzierten Bronzearmschienen, die Bronzegroßschwerter und die Scharfen Klauen?",a="Orokk Omosh sucht einen würdigen Lehrling, der das heilige Schmiede-Erbe seiner Familie fortführen kann. Anstatt die Waffen in Dienst zu stellen, verlangt er die Musterverzierten Bronzearmschienen, Bronzegroßschwerter und Scharfen Klauen als Geschicklichkeitstest. Ihm diese fein gearbeiteten Bronzeartikel zusammen mit rohen Bestientrophäen zu bringen, beweist, dass Ihr über die Disziplin, das technische Können und die raue Stärke verfügt, die erforderlich sind, um die geheimen Rezepte des Clans Omosh zu erlernen.",al={"wofür sind die gegenstände","warum musterverzierte bronzearmschienen","warum bronzegroßschwerter scharfe klauen"}}},fp="20,185,25.390.0,25.413.0,19.183.0,42.191.0,53.124.0,49.167.0"}
P.entries["quest:2753"] = {n="In den Boden getrampelt",s="In Orgrimmars Tal der Ehre prüft Orokk Omosh Schmiede mit harter Arbeit. Rüstungen aus grünem Eisen stellen ihre Ausdauer auf die Probe und lehren sie, schwere Eisenstiefel zu fertigen, während die Techniken der Omosh-Blutlinie auf dem Spiel stehen.",h="In Orgrimmars Tal der Ehre prüft Orokk Omosh Schmiede mit harter Arbeit.",kw={"rüstungsschmiedekunst","schmiedekunst","gorokk","grünes eisen","orgrimmar","orokk omosh","in den boden getrampelt","tal der ehre"},ang={["faction:Horde"]="Orokks Lektionen vermitteln Entwürfe für widerstandsfähige Eisenrüstungen, die auf die brutale Kampfweise an den Kriegsfronten der Horde zugeschnitten sind.",["profession:Blacksmithing"]="Für einen Rüstungsschmied der Horde ist diese Prüfung ein bedeutender Schritt. Sie verlangt umfangreiches Eisenschmelzen und die Vorbereitung grüner Farbe, um exklusive Stiefelpläne zu verdienen."},sec={{t="Die Prüfungen der Omosh",b="Orokk Omosh bildet Rüstungsschmiede in Orgrimmar mit Prüfungen aus, die harte körperliche Arbeit verlangen. Für ihn ist Metallbearbeitung mehr als das Erhitzen und Formen von Erz. Sie ehrt seinen angestammten Clan und prüft die Ausdauer eines Schmieds. Dies ist die dritte Prüfung seiner Aufgabenkette, und das wiederholte Schmieden gehärteter Rüstungen aus grünem Eisen stärkt Muskeln und Disziplin."},{t="Das Erbe von Häuptling Gorokk",b="Schmiede, die Orokk die verlangten Rüstungsteile aus grünem Eisen bringen, ernten seltenes Lob vom schroffen Rüstungsschmied. Er vergleicht einen Handwerker, der diese Arbeit durchsteht, mit seinem Großvater, Häuptling Gorokk der Omosh. Für die Rüstung lehrt Orokk den überlieferten Entwurf für robuste Eisenstiefel. Krieger der Horde tragen sie, um ihre Feinde unter ihren Fersen zu zermalmen."}},faq={{q="Wer vergibt die Quest In den Boden getrampelt?",a="Orokk Omosh, ein orkischer Rüstungsschmied in Orgrimmars Tal der Ehre, vergibt die Prüfung.",al={"questgeber","wer vergibt in den boden getrampelt","orokk omosh standort"}},{q="Was verlangt Orokk Omosh für diese Prüfung?",a="Orokk verlangt vier Green Iron Helms, vier Grüne Eisenarmschienen und zwei Grüne Eisengamaschen. Diese Stücke prüfen und beweisen, wie meisterhaft ein Schmied grünes Eisen verarbeitet.",al={"in den boden getrampelt abgeben","welche gegenstände werden benötigt","benötigte materialien"}},{q="Welche Geschichte steckt hinter der Omosh-Ausbildungsreihe?",a="Orokk Omosh unterzieht junge Schmiede zermürbender körperlicher Arbeit, um das kriegerische Erbe seiner Vorfahren zu bewahren. Er glaubt, dass mühsames Rüstungsschmieden die Kraft aufbaut, Ausrüstung zu fertigen, die brutaler Kriegsführung standhält.",al={"warum lässt orokk rüstungen schmieden","geschichte des omosh-clans"}},{q="Wer ist Häuptling Gorokk der Omosh?",a="Häuptling Gorokk der Omosh ist Orokk Omoshs Großvater. Orokk ehrt die Kampfkunst seines Großvaters und vergleicht Schmiede, die seine Prüfungen mit schwerer Eisenarbeit durchstehen, mit dem Häuptling.",al={"häuptling gorokk","orokks großvater"}},{q="Welche Quest geht In den Boden getrampelt voraus?",a="On Iron Pauldrons kommt in Orokks Reihe von Herausforderungen für Rüstungsschmiede vor dieser Prüfung.",al={"vorausgesetzte quest","vorherige quest der reihe"}},{q="Welche Quest folgt nach dem Abschluss von In den Boden getrampelt?",a="Nach dieser Prüfung bietet Orokk Omosh Horns of Frenzy an. Joys of Omosh beendet die Reihe nach den beiden verbleibenden Lektionen.",al={"nächste quest","was folgt auf in den boden getrampelt"}}},fx={["454b7030"]={q="Warum will Orokk Omosh diese grünen Eisenteile geschmiedet haben?",a="Orokk Omosh bildet Euch in den brutalen Schmiedetraditionen seiner Blutlinie aus. Er glaubt, dass wahre Krieger und Schmiede qualvolle Arbeit ertragen müssen, um Ausrüstung zu schmieden, die den Namen Omosh verdient. Indem er Euch mehrere Helme, Armschienen und Gamaschen aus schwerem grünem Eisen hämmern lässt, testet er sowohl Eure körperliche Ausdauer als auch Euer Handwerk und bereitet Euch darauf vor, das Wissen über das Schmieden kampferprobter Stiefel freizuschalten.",al={"orokk omosh motiv","warum grünes eisen schmieden","warum will orokk das"}},["9ced7653"]={q="Wofür ist der Grüne Eisenhelm?",a="Die Grüne Eisengamaschen dienen als ein Teil von Orokks zermürbendem Test für Handwerkskunst und Ausdauer. Von Eurer eigenen Hand geschmolzen und gehämmert, beweisen sie dem Schmied, dass Ihr die präzise Metallurgie und die rohe körperliche Ausdauer besitzt, die erforderlich sind, um schwere Schutzausrüstung für die Omosh-Tradition herzustellen.",al={"grüner eisenhelm zweck","warum grüner eisenhelm","nutzen von grünem eisenhelm"}},ae72eea8={q="Wofür sind die Grünen Eisenarmschienen?",a="Diese Armschienen beweisen Eure Fähigkeit, unter der strengen Anleitung von Orokk Omosh stabilen und zuverlässigen Gliedmaßenschutz zu schmieden. Die Abgabe von vier ordnungsgemäß gefertigten Paaren beweist, dass Eure Schmiedekünste zuverlässig Krieger für die bevorstehenden wilden Schlachten ausrüsten können.",al={"grüne eisenarmschienen zweck","warum grüne eisenarmschienen","nutzen von grünen eisenarmschienen"}},["9872ef5a"]={q="Wofür sind die Grünen Eisengamaschen?",a="Die Gamaschen erfordern große Mengen an bearbeitetem Eisen und diszipliniertes Schmiedehandwerk. Die Bereitstellung von zwei gut gefertigten Paaren beweist Orokk, dass Ihr es wert seid, die Geheimnisse der Herstellung mächtiger gepanzerter Stiefel zu erben und in die Fußstapfen seines Vorfahren Chef Gorokk zu treten.",al={"grüne eisengamaschen zweck","warum grüne eisengamaschen","nutzen von grünen eisengamaschen"}},f314d286={q="Warum braucht Orokk Omosh Euch, anstatt das Schmieden selbst zu erledigen?",a="Orokk sucht keine Lieferung von Rüstung für sich selbst; er testet und unterweist Euch. Als Ausbilder der alten Techniken seines Clans verlangt er, dass Eure eigenen Muskeln über dem Amboss schmerzen, um Eure Hingabe zu beweisen, bevor er die Entwürfe der Omosh teilt.",al={"warum ich orokk","warum braucht orokk mich","warum nicht selbst schmieden"}}},fp="19,226,19.322.0,22.324.0,41.80.0,45.164.0,49.208.0,29.173.0,40.88.0,60.116.0"}
P.entries["quest:2755"] = {n="Freude der Omoshs",s="Nach Eurer großen Hilfe teilt Orokk Omosh in Orgrimmar eine Familientradition mit Euch. Der erfahrene Schmied wischt seine Tränen fort, die er auf Ruß schiebt, und tanzt dann vor Freude, um ein ungewöhnliches Familienerbe weiterzugeben.",h="Nach Eurer großen Hilfe teilt Orokk Omosh in Orgrimmar eine Familientradition mit Euch.",kw={"schmied","freudentanz","freude der omoshs","orgrimmar","orokk omosh","ruß im auge","tal der ehre"},ang={["faction:Horde"]="Im Tal der Ehre in Orgrimmar trifft kriegerischer Stolz inmitten klirrenden Stahls auf Orokk Omoshs tränenreiche Freude und seinen schwungvollen Tanz.",["profession:Blacksmithing"]="Orokk Omoshs gefühlvoller Familientanz gewährt einen humorvollen, zärtlichen Einblick in das Leben eines erfahrenen Schmieds jenseits der Schmiede."},sec={{t="Eine rußbefleckte Träne",b="An Orgrimmars Schmiede ist Orokk Omosh für wuchtige Hammerschläge bekannt, nicht für Tränen. Eure große Hilfe hat den stämmigen Schmied tief berührt. Doch er gibt stur einem Rußpartikel in seinem Auge die Schuld, statt zuzugeben, dass er weint."},{t="Die Tradition der Omoshs",b="Bevor sich Eure Wege trennen, sagt Orokk Omosh, er müsse noch ein letztes Familiengeheimnis mit Euch teilen. Er führt seinem Lehrling den schwungvollen, kräftezehrenden Omosh-Freudentanz vor. Dann lehrt er den Lehrling, mit eiserner Faust zuzuschlagen."}},faq={{q="Wer ist Orokk Omosh?",a="Orokk Omosh ist ein orkischer Schmied im Tal der Ehre in Orgrimmar. Er ist überaus stolz auf das Handwerk und die Abstammung seiner Familie und pflegt neben seiner Schmiedekunst lebhafte Traditionen.",al={"wer ist orokk","orokk omosh hintergrundgeschichte","orokk schmied"}},{q="Warum weint Orokk?",a="Orokk Omosh gibt Schmiederuß in seinem Auge die Schuld, doch Eure Hilfe hat ihn tief bewegt. Er hat jemanden gefunden, der würdig ist, die Traditionen seiner Familie mit ihm zu teilen.",al={"warum weint orokk","ist orokk traurig","ruß im auge"}},{q="Was ist der Omosh-Freudentanz?",a="Der Omosh-Freudentanz ist eine schwungvolle Tanzfolge, die in Orokk Omoshs Familie weitergegeben wird. Er erschöpft ihn sehr, und er hat ihn schon lange nicht mehr geübt.",al={"omosh-tanz","freudentanz","was ist der tanz"}},{q="Wo spielt diese Quest?",a="Die Geschichte spielt in Orgrimmar, an der Schmiede im Tal der Ehre, wo Orokk Omosh Metall bearbeitet.",al={"questschauplatz","wo ist freude der omoshs","orgrimmar schmiede"}},{q="Was lehrt Euch Orokk?",a="Orokk Omosh lehrt Euch den Omosh-Freudentanz und verspricht, das Wissen um die eiserne Faust weiterzugeben, was Schmied und Abenteurer verbindet.",al={"omosh belohnung","was lernt man","eiserne faust"}},{q="Können Spieler der Allianz an dieser Quest teilnehmen?",a="Nein. Orokk Omosh ist mit der Horde verbündet und lebt innerhalb der befestigten Mauern Orgrimmars, sodass ihn dort nur Abenteurer der Horde treffen können.",al={"allianz freude der omoshs","nur für die horde"}}},fx={["371650ab"]={q="Warum will Orokk Omosh Euch den Tanz der Freude lehren?",a="Orokk ist überwältigt von Dankbarkeit für Eure Hilfe und möchte die letzte, streng gehütete Tradition seiner Blutlinie weitergeben. Indem er Euch den Omosh-Tanz der Freude lehrt, fühlt er, dass sein Vermächtnis geehrt wird und dass er endlich als glücklicher Orc sterben kann.",al={"warum tanz lehren","orokk omosh motiv","warum will orokk das"}}},fp="13,195,19.219.0,19.207.0,19.170.0,20.154.0,31.163.0,33.91.0,26.135.0,47.132.0"}
P.entries["quest:276"] = {n="Stapfende Pfoten",s="In Greenwardens Hain im Sumpfland sieht Rethiel, wie die Zahl der Mosshide nahe dem Tor von Algaz wächst. Ihre Feuer und ihr Getrampel bedrohen das Moor, weshalb Rethiel Reisende bittet, ihre Reihen zu lichten.",h="In Greenwardens Hain im Sumpfland sieht Rethiel, wie die Zahl der Mosshide nahe dem Tor von Algaz wächst.",kw={"algaz","gnolle","greenwarden","mischlinge","mosshide","rethiel","stapfende pfoten","sumpfland"},ang={["class:Druid"]="Als Druide teilt Ihr die Cenarion-Pflicht, die Natur im Gleichgewicht zu halten. Einen unnatürlichen Bevölkerungsanstieg einzudämmen, kann helfen, den Zusammenbruch des Moors zu verhindern.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Gnolle unmittelbar vor dem Tor von Algaz wimmeln. Ihre Reihen zu lichten, schützt das Moor und sichert die lebenswichtige Straße zwischen Eisenschmiede und dem Hafen von Menethil.",["race:NightElf"]="Als Nachtelf teilt Ihr uralte Bande mit den wilden Geistern der Natur. Rethiel bei der Heilung des Moors zu helfen, ist eine vertraute und ehrenvolle Pflicht."},sec={{t="Wachsende Bedrohung im Moor",b="Die Mosshide-Gnolle lebten viele Jahre im Sumpfland, ohne die natürliche Ordnung zu überfordern. Nun sind ihre Reihen im Süden zum Pass von Dun Algaz hin stark angewachsen. Ihre schweren Stiefel und Pfoten zertrampeln seltene Moorpflanzen, und ihr Holzeinschlag entwaldet Haine für ihre Lagerfeuer. Wenn die Rudel weiter wachsen, wird das empfindliche Moor darunter leiden."},{t="Das Urteil des Greenwarden",b="Rethiel der Sumpfhüter beobachtet das Moor auf Anzeichen eines Ungleichgewichts. Die Existenz der Gnolle ist nicht das Problem; ihre Zahl übersteigt inzwischen das, was das Sumpfland verkraften kann. Die Reihen der Mosshide-Gnolle und Mischlinge zu lichten, hilft, das Moor zu bewahren, und kann die Anerkennung seines uralten Wächters einbringen."}},faq={{q="Wer ist Rethiel der Sumpfhüter?",a="Rethiel ist eine Moorbestie, die im Sumpfland an der Straße zwischen den Grenzen von Eisenschmiede und Arathi lebt. Rethiel widmet sich dem Erhalt des Moors, wacht über die Gesundheit des Landes und bittet Reisende, zerstörerische Populationen in Schach zu halten.",al={"rethiel hintergrundgeschichte","wer vergibt stapfende pfoten","greenwarden sumpfland"}},{q="Warum sind die Mosshide-Gnolle jetzt ein Problem?",a="Die Mosshide-Gnolle lebten einst im Einklang mit dem Moor, ohne bleibende Schäden anzurichten, doch ihr jüngster Bevölkerungsboom führte zu starkem Holzeinschlag für Brennholz und großflächigem Zertrampeln empfindlicher Moorpflanzen.",al={"warum gnolle im sumpfland töten","bedrohung durch mosshide-gnolle"}},{q="Wo richten die Gnolle diesen Schaden an?",a="Mosshide-Gnolle und Mischlinge sammeln sich in großer Zahl im südlichen Sumpfland, besonders nahe dem zwergischen Pass von Dun Algaz.",al={"wo sind mosshide-gnolle","stapfende pfoten ort"}},{q="Was folgt auf das Dezimieren der Gnolle?",a="Nachdem die Rudel dezimiert wurden, untersucht Rethiel den Grund für ihre ungewöhnlichen Aktivitäten und ihren Brennstoffverbrauch und schickt Reisende dann zu Fire Taboo.",al={"nächste aufgabe nach stapfende pfoten","stapfende pfoten folgeaufgabe"}},{q="Warum erwähnt Rethiel, dass sein Vertrauen auf die Probe gestellt wurde?",a="Rethiel sagt, sein Vertrauen in Euer Volk sei in der Vergangenheit strapaziert worden, und bleibt gegenüber Sterblichen und ihrer raschen Ausbreitung misstrauisch. Beim Schutz des wilden Moors zu helfen, zeigt, dass Sterbliche für die Natur sorgen können, statt sie auszubeuten.",al={"rethiel dialog","vertrauen in der vergangenheit strapaziert"}}},fx={["24db34f0"]={q="Wer sind die Mosshide-Gnolle, auf deren Jagd Ihr geschickt werdet?",a="Die Mosshide sind ein Gnollclan, der im Sumpfland beheimatet ist. Obwohl sie hier seit Generationen friedlich im Einklang mit der Natur lebten, entblößt ihre wachsende Population nun das Marschland. Ihre schweren Pfoten zertrampeln die empfindliche Flora der Moore, während ihre Äxte übermäßig viel Holz für Kochstellen und Lagerfeuer fällen, wodurch das lokale Ökosystem völlig aus dem Gleichgewicht gerät.",al={"mosshide gnolle","wer sind mosshide","mosshide-bastarde"}}},fp="13,193,21.318.0,26.286.0,31.233.0,42.194.0,41.125.0,36.135.1,49.215.0"}
P.entries["quest:2766"] = {n="Findet OOX-22/FE!",s="Ein Peilroboter ist in Feralas abgestürzt, und Oglethorpe Obnoticus ruft durch ein seltsames Metallei um Hilfe. Bringt dessen Leuchtfeuer zu einer Höhle nahe dem Wildschrammtal.",h="Ein Peilroboter ist in Feralas abgestürzt, und Oglethorpe Obnoticus ruft durch ein seltsames Metallei um...",kw={"notfall-leuchtfeuer","wildschrammtal","feralas","peilroboter","mechanisches huhn","oglethorpe obnoticus","oox-22/fe"},sec={{t="Eine Stimme im Ei",b="Dreht am Knopf des Metalleis, und es öffnet sich zu einer gnomischen Vorrichtung. Oglethorpe Obnoticus spricht aus dem Inneren. Sein Peilroboter ist abgestürzt, und er verspricht Euch eine Belohnung, wenn Ihr ihn bergt. Er hat ermittelt, dass die Maschine in einer Höhle nahe dem Wildschrammtal liegt. Bringt das Leuchtfeuer dorthin."},{t="Was die Höhle birgt",b="Ein Roboterhuhn liegt als Wrack in der Höhle. Oglethorpe Obnoticus bestätigt, dass es sein Peilroboter ist. Er muss überbrückt werden, bevor er für Reparaturen nach Beutebucht fliegen kann. Setzt das Leuchtfeuer ein, und der Roboter erwacht surrend zum Leben. Dann ertönt Oglethorpes Stimme aus dem Roboter selbst."}},faq={{q="Wer spricht durch das Notfall-Leuchtfeuer?",a="Oglethorpe Obnoticus spricht durch das Leuchtfeuer. Sein Peilroboter ist abgestürzt, und er bittet Euch, das Leuchtfeuer zu ihm zu bringen.",al={"wer hat das leuchtfeuer gebaut","wer spricht","wer ist oglethorpe"}},{q="Wohin weist Euch das Leuchtfeuer?",a="Das Leuchtfeuer weist auf eine Höhle nahe dem Wildschrammtal in Feralas. Oglethorpe hat die Koordinaten des Roboters ermittelt.",al={"wo ist der roboter","standort des peilroboters","wohin das leuchtfeuer bringen"}},{q="Was ist das Leuchtfeuer?",a="Das Leuchtfeuer ist ein seltsames eiförmiges Gerät aus Metall. Dreht an seinem Knopf, und es öffnet sich zu einer gnomischen Vorrichtung mit einer Stimme im Inneren.",al={"was ist das ei","was ist oox-22/fe","notfall-leuchtfeuer"}},{q="Was kommt nach diesem Schritt?",a="Danach folgt Rescue OOX-22/FE!.",al={"nächste quest","was folgt auf findet oox-22/fe","nach der höhle"}}},fp="15,156,18.282.0,19.270.1,44.120.0,38.111.0,19.124.0,27.26.0"}
P.entries["quest:2767"] = {n="Die Rettung von OOX-22/FE",s="Im Wildschrammtal wartet OOX-22/FE! auf Eure Hilfe auf dem Weg zum Dock an der Vergessenen Küste. Sobald er dort ankommt, möchte Oglethorpe Obnoticus in Beutebucht mit Euch sprechen.",h="Im Wildschrammtal wartet OOX-22/FE!",kw={"beutebucht","wildschrammtal","feralas","die vergessene küste","peilroboter","oglethorpe obnoticus","oox-22/fe","roboterhuhn"},sec={{t="Ein sicherer Ort zum Abheben",b="OOX-22/FE braucht einen offenen, sicheren Ort für seinen langwierigen Start. Die Stimme des Gnoms knistert aus dem Roboter, während er erklärt, dass dessen eingebaute Tarnung Zeit braucht, bis sie wieder funktioniert. Auch Oglethorpe Obnoticus braucht Zeit, um sie zum Laufen zu bringen. Er schlägt das Dock an der Vergessenen Küste vor, wo sich alles in Betrieb nehmen lässt. Ihr eskortiert den Roboter von seinem Standort dorthin."},{t="Danach nach Beutebucht",b="Sobald OOX-22/FE das Dock sicher erreicht, möchte Oglethorpe Obnoticus, dass Ihr in Beutebucht mit ihm sprecht."}},faq={{q="Wohin muss OOX-22/FE gelangen?",a="OOX-22/FE muss das Dock an der Vergessenen Küste erreichen. Ihr eskortiert ihn vom Wildschrammtal aus, wo Ihr ihn gefunden habt.",al={"wohin das huhn bringen","oox-22/fe ziel","feralas huhn eskortroute"}},{q="Wer ist Oglethorpe Obnoticus?",a="Oglethorpe Obnoticus ist ein Meistererfinder, zu dessen Peilroboterserie auch OOX-22/FE gehört. Er spricht durch den Roboter und ist in Beutebucht zu finden.",al={"wer hat das roboterhuhn gebaut","wer ist oglethorpe obnoticus","erfinder des huhns"}},{q="Warum muss der Roboter das Dock erreichen?",a="Das Dock bietet einen offenen, sicheren Ort für den langwierigen Start, und laut Oglethorpe ist dort genug Platz, um alles in Betrieb zu nehmen. Die eingebaute Tarnung des Roboters braucht Zeit, bis sie wieder funktioniert.",al={"warum oox-22 eskortieren","warum zum dock gehen"}},{q="Wo melde ich mich danach?",a="Sobald OOX-22/FE das Dock sicher erreicht, sprecht mit Oglethorpe Obnoticus in Beutebucht.",al={"wo ist oglethorpe","abgabeort","mit wem danach sprechen"}}},fp="17,166,24.363.0,21.102.0,32.116.0,28.146.0,42.192.0,29.83.0"}
P.entries["quest:277"] = {n="Feuer-Tabu",s="Im Sumpfland setzt Rethiel seine Sorge um den Wald in Taten um. Die Sumpfbestie bittet Reisende, den Mosshide-Gnollen die kunstlosen Feuersteine abzunehmen, mit denen sie lebende Bäume verbrennen, und hofft, die uralten Äste zu verschonen.",h="Im Sumpfland setzt Rethiel seine Sorge um den Wald in Taten um.",kw={"kunstloser feuerstein","feuer-tabu","gnolle","greenwarden","lebendes holz","mosshide","rethiel","sumpfland"},ang={["class:Druid"]="Als Druide teilt Ihr Rethiels Ehrfurcht vor der Wildnis und versteht die Schmerzen, die lebende Bäume in den Feuergruben der Gnolle erleiden.",["faction:Alliance"]="Als Reisender der Allianz wisst Ihr, dass die Mosshide-Gnollen jene bedrohen, die das Sumpfland durchqueren. Den örtlichen Geistern zu helfen schützt die Handelswege zwischen Dun Morogh und Arathi.",["race:NightElf"]="Als Nachtelf erkennt Ihr in Rethiel vielleicht einen weiteren Beschützer lebender Bäume, eine Sumpfbestie, die das Leid des Sumpflands spürt."},sec={{t="Die Qual eines Greenwarden",b="Rethiel der Sumpfhüter empfindet die Bäume des Sumpflands als Verwandte. Fäulnis und Erneuerung gehören zum Sumpf, doch die Mosshide-Gnollen fällen lebende Bäume und nähren damit ihre Herdfeuer. Das Ächzen dieser Äste lastet auf Rethiel. Der Greenwarden kann nicht länger schweigend zusehen, wie die Bäume leiden."},{t="Den Mosshide das Feuer nehmen",b="Mosshide-Gnollen fällen lebende Bäume für Wärme und Territorium, statt Totholz zu sammeln. Rethiel hofft, ihre Ausbreitung ohne einen langen Krieg einzudämmen, und so bittet Euch die Sumpfbestie, den stärkeren Gnollen ihre kunstlosen Feuersteine abzunehmen. Ohne diese Werkzeuge kann das Rudel das gefällte Holz nicht verbrennen.\n\nRethiel zerschmettert jeden Stein und wirft seinen Staub ins Meer. Dort kann er den Wald nie wieder entzünden."}},faq={{q="Wer ist Rethiel der Sumpfhüter?",a="Rethiel der Sumpfhüter ist eine Sumpfbestie, die im Sumpfland lebt. Mit dem Leben seiner Bäume und Pflanzen verbunden, will Rethiel den verwundeten Sumpf vor den Mosshide-Gnollen schützen.",al={"wer ist rethiel","geschichte von rethiel dem sumpfhüter","wer vergibt feuer-tabu"}},{q="Warum will Rethiel kunstlose Feuersteine, statt die Anführer der Gnolle zu töten?",a="Rethiel sieht im Verbrennen lebenden Holzes einen unverzeihlichen Frevel. Die Feuersteine zu entwenden hindert die Gnolle daran, die Bäume des Sumpflands in Brand zu setzen, und beendet die Zerstörung lebenden Holzes.",al={"warum feuersteine","warum feuersteine wegnehmen","zweck kunstloser feuersteine"}},{q="Was geschieht mit den Feuersteinen, nachdem sie abgegeben wurden?",a="Rethiel zerschmettert die Feuersteine und wirft ihre Überreste ins Meer, wo sie nie wieder lebendes Holz entzünden können.",al={"was macht sie mit feuersteinen","zerstörung der feuersteine"}},{q="Welche Gnolle tragen die Feuersteine bei sich?",a="Die stärkeren Mosshide-Gnollen tragen die kunstlosen Feuersteine bei sich. Kleineren Mosshide und schwächeren Mischlingen werden keine Werkzeuge zum Feuermachen anvertraut, und sie tragen auch keine bei sich.",al={"wer lässt feuersteine fallen","welche gnolle haben kunstlose feuersteine"}},{q="Warum fällen die Mosshide Bäume?",a="Die Mosshide-Gnollen fällen lebende Bäume, um ihre Lagerfeuer zu nähren und sich im feuchten Sumpf warm zu halten. Sie verwenden frisches Holz statt trockenen, herabgefallenen Holzes.",al={"warum fällen gnolle bäume","mosshide holzfällen"}},{q="Wie geht es nach dem Sammeln der Feuersteine weiter?",a="Nachdem Ihr die Feuersteine genommen und den Gnollen das Feuer entzogen habt, schickt Rethiel Euch los, um ein weiteres Übel in den Sümpfen zu bekämpfen. Es heißt Blisters on The Land.",al={"welche quest folgt auf feuer-tabu","nächste quest nach feuersteinen"}}},fx={e3ab03fe={q="Warum will Rethiel der Sumpfhüter, dass dies erledigt wird?",a="Als Beschützer, der mit dem Land und der Natur verbunden ist, spürt Rethiel das Leiden des Sumpflands auf schmerzhafte Weise. Die Mosshide-Gnolle fällen lebende Bäume und verbrennen sie, um sich zu wärmen, was der Wildnis Qualen zufügt. Indem er den Gnollen ihre Feuersteine wegnimmt, hofft Rethiel, die Zerstörung des Waldes zu stoppen und sicherzustellen, dass die Gnolle kein lebendes Holz mehr verbrennen können.",al={"rethiel motiv","warum feuersteine nehmen","warum hasst rethiel feuer"}},["25034295"]={q="Wer sind die Mosshides, gegen die Ihr ausgesandt werdet?",a="Ihr werdet gegen die Mosshidegnolle ausgesandt, ein bösartiger Clan von Hyänenmenschen, die das Sumpfland befallen haben. Sie haben sich im gesamten Sumpf ausgebreitet, Lager errichtet und fällen aggressiv uralte Bäume, um Feuer zu machen und Territorium zu beanspruchen, was dem natürlichen Gleichgewicht, das Rethiel beschützt, Ruin und Elend bringt.",al={"mosshides sumpfland","wer sind die gnolle","mosshide-gnolle"}},b6cb9238={q="Wofür ist der Kunstlose Feuerstein gedacht?",a="Die Mooshidegnolle tragen kunstlose Feuersteine als primitive Werkzeuge, um Funken zu schlagen und Feuer zu entfachen. Ohne sie können sie das lebende Holz, das sie im Sumpfland fällen, nicht verbrennen. Rethiel verlangt, dass Ihr diese Feuersteine sammelt, damit er sie zerschmettern und die Überreste ins Meer werfen kann, um ihnen die Fähigkeit zu nehmen, Brände zu entfachen.",al={"verwendung von kunstlosem feuerstein","was sind kunstlose feuersteine?","warum haben gnolle feuerstein?"}}},fp="10,198,23.280.0,27.389.0,31.177.0,72.191.0,51.120.0,30.149.0,41.144.0,43.162.1"}
P.entries["quest:2770"] = {n="Gahz'rilla",s="Wizzel Kupferbolz bittet Euch, ihm Gahz'rilla's Electrified Scale in die Schimmernde Ebene zu bringen. Die Schuppe ist es, die er von Gahz'rilla haben möchte.",h="Wizzel Kupferbolz bittet Euch, ihm Gahz'rilla's Electrified Scale in die Schimmernde Ebene zu bringen.",kw={"elektrisierte schuppe","gahz'rilla","die schimmernde ebene","wizzel kupferbolz"},sec={{t="Wizzels Bitte",b="In der Schimmernden Ebene wartet Wizzel Kupferbolz auf Gahz'rilla's Electrified Scale. Ihr sollt ihm die Schuppe bringen, denn seine Bitte hängt davon ab, was Ihr von Gahz'rilla zurückbringen könnt."}},faq={{q="Was möchte Wizzel von Gahz'rilla?",a="Wizzel Kupferbolz möchte, dass Ihr ihm Gahz'rilla's Electrified Scale in die Schimmernde Ebene bringt.",al={"gahz'rillas schuppe","wizzel schuppe","was wizzel bringen"}},{q="Wer bittet um die Schuppe?",a="Wizzel Kupferbolz bittet Euch, ihm Gahz'rilla's Electrified Scale zu bringen.",al={"wer möchte sie","wizzel kupferbolz","wer hat gefragt"}},{q="Wohin soll ich die Schuppe bringen?",a="Bringt Gahz'rilla's Electrified Scale zu Wizzel Kupferbolz in die Schimmernde Ebene.",al={"wohin damit","wo ist wizzel","fundort der schuppe"}}},fp="10,142,16.196.0,38.94.0,28.71.0,27.82.0"}
P.entries["quest:278"] = {n="Eine dunkle Bedrohung",s="Sprengstoff der Dunkeleisen bedroht den Steinwerkdamm, und Chefingenieur Hinderweir VII. braucht Eure Hilfe. Er bittet Euch, seltene Reagenzien aus Loch Modan zu sammeln, damit er ein Gemisch herstellen kann, um ihn zu neutralisieren.",h="Sprengstoff der Dunkeleisen bedroht den Steinwerkdamm, und Chefingenieur Hinderweir VII.",kw={"krokiliskenträne","dunkeleisen","hinderweir","loch modan","lauerergift","kristall der mo'grosh","der steinwerkdamm"},ang={["faction:Alliance"]="Als Reisender der Allianz wisst Ihr, dass die Zerstörung des Damms wichtige Versorgungswege über Land zwischen Eisenschmiede und den nördlichen Königreichen unterbrechen würde.",["profession:Engineering"]="Als Ingenieur wisst Ihr Hinderweirs Einfallsreichtum zu schätzen, ein chemisches Gegenmittel herzustellen, um unbeständige Sprengladungen vor Ort zu stabilisieren.",["race:Dwarf"]="Als Zwerg aus Khaz Modan habt Ihr die wichtige Pflicht, die Sabotage der Dunkeleisen am Steinwerkdamm zu verhindern und Eure angestammte Heimat samt ihren großen Bauwerken zu schützen."},sec={{t="Ein unbeständiges Rezept",b="Chefingenieur Hinderweir VII. braucht drei Zutaten für sein Gemisch. Lauerergift, eine Krokiliskenträne aus dem Loch und ein Kristall der Mo'grosh lösen jeweils eine andere Reaktion aus. Zusammen können sie die Sprengladungen der Zwerge unschädlich machen."},{t="Gefährliche Beschaffung",b="Die Zutaten liegen in gefährlichen Teilen von Loch Modan. Lauererspinnen und Krokilisken bedrohen Reisende, während die Mo'grosh-Oger ihre abgebauten Kristalle in einer Festung im Nordosten bewachen. Um die Kristalle zu erreichen, muss man sich den Ogern in ihren Lagern stellen."}},faq={{q="Warum braucht Ingenieur Hinderweir gerade diese Reagenzien?",a="Chefingenieur Hinderweir VII. braucht die Reagenzien, um ein Gemisch herzustellen, das den Sprengstoff der Dunkeleisen entschärfen kann. Lauerergift, Krokiliskensekrete und Kristalle der Mo'grosh ermöglichen die nötigen Reaktionen, um die Sprengladungen der Saboteure unschädlich zu machen.",al={"warum spinnengift","warum krokiliskenträne","reagenzien für entschärfungsgemisch"}},{q="Woher stammen die Kristalle der Mo'grosh?",a="Die Mo'grosh-Oger bauen die Kristalle in den nordöstlichen Hügeln von Loch Modan ab und horten sie dort. Um einen zu erreichen, muss man ihr schwer bewachtes Gebiet betreten.",al={"wo sind kristalle","kristall der mo'grosh fundort","wer hat den kristall"}},{q="Welche dunkle Bedrohung gefährdet Loch Modan?",a="Eingeschleuste Dunkeleisenzwerge wollen den Steinwerkdamm zerstören. Seine Zerstörung würde das tiefer gelegene Sumpfland überfluten, die Versorgungslinien der Allianz unterbrechen und die Region verwüsten.",al={"welche dunkle bedrohung","wer greift den damm an","eine dunkle bedrohung geschichte"}},{q="Wer ist Chefingenieur Hinderweir VII.?",a="Chefingenieur Hinderweir VII. ist der zwergische Ingenieur, der den Betrieb und die bauliche Unversehrtheit des Steinwerkdamms überwacht. Er leitet dessen Instandhaltung und die örtlichen Schutzmaßnahmen gegen Sabotage.",al={"wer ist hinderweir","chefingenieur hinderweir"}},{q="Wo sind die einheimischen Kreaturen zu finden?",a="Lauererspinnen streifen durch die bewaldete Wildnis rings um das Tal. Krokilisken leben im Loch und an seinen Ufern.",al={"wo sind lauererspinnen","krokilisk fundort","wo spinnen finden"}},{q="Warum sammeln die Wachen von Eisenschmiede diese Gegenstände nicht selbst?",a="Gebirgsjäger und örtliche Wachen sind mit der Verteidigung von Orten wie Thelsamar und der Suche nach Spähern der Dunkeleisen bereits ausgelastet. Gezielte Suchaktionen und Vorstöße ins Gebiet der Oger fallen fähigen Reisenden zu.",al={"warum hinderweir helfen","wo sind die wachen von eisenschmiede"}}},fx={["0370975a"]={q="Warum möchte Chefingenieur Hinderweir VII., dass diese Gegenstände gesammelt werden?",a="Chefingenieur Hinderweir VII. fürchtet einen unmittelbar bevorstehenden Angriff der Dunkeleisenzwerge auf den Steinwerkdamm. Um jeglichen Sprengungsversuchen entgegenzuwirken, benötigt er Euch, um flüchtige und spezialisierte Reagenzien zu sammeln – Lauerergift, eine Krokiliskenträne und einen seltenen Kristall der Mo'grosh –, damit er eine Neutralisierungsmischung brauen kann, um die Sprengstoffe des Feindes zu entschärfen, bevor das Loch Modan verwüstet wird.",al={"warum will hinderweir das erledigt haben","warum reagenzien sammeln hinderweir","hinderweir motiv dunkle bedrohung"}}},fp="19,207,17.245.0,18.259.0,58.232.0,37.145.0,44.167.0,37.179.0,44.116.0,61.193.0"}
P.entries["quest:2781"] = {n="GESUCHT: Kalif Skorpidstich",s="In Gadgetzan und am Dampfdruckpier suchen Aushänge nach Kalif Skorpidstich, dem Anführer der Gesetzlosen der Wastewander. Die Gadgetzan Water Company verlangt einen Beweis für seinen Tod in Gadgetzan.",h="In Gadgetzan und am Dampfdruckpier suchen Aushänge nach Kalif Skorpidstich, dem Anführer der Gesetzlosen der...",kw={"kopfgeld","kalif skorpidstich","chefingenieur bilgewhizzle","gadgetzan","gadgetzan water company","dampfdruckpier","tanaris","wastewander"},sec={{t="Die Anschuldigungen der Gesellschaft",b="In Gadgetzan und am Dampfdruckpier setzt die Gadgetzan Water Company ein hohes Kopfgeld auf Kalif Skorpidstich aus. Die Aushänge beschuldigen ihn, Mitarbeiter der Gesellschaft ermordet, ihre Ressourcen gestohlen und ihr Eigentum an sich gerissen zu haben. Bringt Chefingenieur Bilgewhizzle in Gadgetzan einen Beweis für seinen Tod."},{t="Worauf die Wassergesellschaft hofft",b="Chefingenieur Bilgewhizzle nennt Skorpidstichs Tod Gerechtigkeit und einen gewaltigen Schlag gegen die Wastewander. Er bezeichnet sie als niederträchtige Nomaden und Hausbesetzer. Der Ingenieur hofft, dass das im Namen der Gesellschaft ausgezahlte Kopfgeld sie endlich von Gadgetzans Wasserbrunnen vertreiben wird."}},faq={{q="Wer ist Kalif Skorpidstich?",a="Kalif Skorpidstich führt die Gesetzlosen der Wastewander an und wird von der Gadgetzan Water Company gesucht.",al={"kalif skorpidstich hintergrundgeschichte","wer führt die wastewander an","skorpidstich"}},{q="Warum will die Gadgetzan Water Company seinen Tod?",a="Die Gesellschaft beschuldigt ihn, ihre Mitarbeiter ermordet, ihre Ressourcen gestohlen und ihr Eigentum an sich gerissen zu haben.",al={"warum kopfgeld auf skorpidstich","kalif skorpidstich verbrechen","feind der gadgetzan water company"}},{q="Wer zahlt das Kopfgeld auf Kalif Skorpidstich?",a="Die Gadgetzan Water Company zahlt das Kopfgeld. Chefingenieur Bilgewhizzle in Gadgetzan nimmt den Beweis für Skorpidstichs Tod entgegen.",al={"wer liefert skorpidstich aus","wo den kopf des kalifen abgeben","bilgewhizzle kopfgeld"}},{q="Wo hängen die Steckbriefe?",a="Die Steckbriefe hängen in Gadgetzan und am Dampfdruckpier.",al={"kalif steckbrief fundort","wo den kopfgeldauftrag für den kalifen annehmen","skorpidstich aushang"}}},fp="27,179,21.282.0,32.254.1,27.95.0,51.100.0,44.122.0,37.61.0"}
P.entries["quest:2782"] = {n="Rin'jis Geheimnis",s="Nachdem Ihr Rin'ji geholfen habt, tragt Ihr Rin'jis Geheimnis bei Euch, eine Tafel mit Witherbark-Schriftzeichen, die noch niemand gelesen hat. Oran Snakewrithe erforscht die Witherbark und könnte sie entziffern. Er lebt bekanntermaßen im Magieviertel von Unterstadt.",h="Nachdem Ihr Rin'ji geholfen habt, tragt Ihr Rin'jis Geheimnis bei Euch, eine Tafel mit...",kw={"hinterlands","magieviertel","oran snakewrithe","rin'ji","tafel","unterstadt","witherbark"},sec={{t="Eine unlesbare Tafel",b="Schriftzeichen der Witherbark-Trolle bedecken die Tafel, doch was Rin'jis Geheimnis ist, bleibt ein Rätsel. Sie könnte sehr viel wert sein oder gar nichts. Ein Witherbark-Troll in Schwierigkeiten könnte alles versuchen, um ihnen zu entkommen."},{t="Ein Gelehrter in Unterstadt",b="Oran Snakewrithe ist ein bekannter Gelehrter, der die Witherbark-Trolle erforscht. Er lebt bekanntermaßen im Magieviertel von Unterstadt und könnte die Tafel lesen."}},faq={{q="Woher stammt diese Tafel?",a="Die Tafel ist das Geheimnis, das Rin'ji bei den Overlook Cliffs versteckt hat. Ihr habt sie gefunden, nachdem Ihr Rin'ji zur Flucht aus der Quel'Danil-Hütte verholfen habt.",al={"rinji tafel herkunft","wie bekommt man die tafel"}},{q="Wer kann die Schriftzeichen auf der Tafel lesen?",a="Oran Snakewrithe kennt die Witherbark-Trolle gut und könnte die Schriftzeichen entziffern.",al={"wer kann die tafel entziffern","wer liest witherbark-schriftzeichen"}},{q="Wo befindet sich Oran Snakewrithe?",a="Oran Snakewrithe lebt bekanntermaßen im Magieviertel von Unterstadt.",al={"oran snakewrithe aufenthaltsort","wo ist oran"}},{q="Ist die Tafel wertvoll?",a="Das kann niemand sagen. Die Tafel könnte sehr viel wert sein oder gar nichts, denn ein Witherbark-Troll in Not könnte alles versuchen, um Schwierigkeiten zu entkommen.",al={"was ist rinjis geheimnis","tafel bedeutung"}}},fp="15,227,24.201.0,26.160.0,32.123.0,40.91.0,34.72.0,23.146.0"}
P.entries["quest:28"] = {n="Trial of the Lake",s="Tajarri erwartet das Ergebnis einer Prüfung am Schrein von Remulos in der Mondlichtung. Ein Schrein-Schmuckstück aus dem See von Elune'ara steht dabei im Mittelpunkt.",h="Tajarri erwartet das Ergebnis einer Prüfung am Schrein von Remulos in der Mondlichtung.",kw={"see von elune'ara","mondlichtung","schrein-schmuckstück","schrein von remulos","tajarri","trial of the lake"},sec={{t="Am Schrein",b="Am Schrein von Remulos im Nordwesten der Mondlichtung bittet Tajarri Euch, eine Prüfung zu bestehen. Findet ein Schrein-Schmuckstück im See von Elune'ara und bringt es zum Schrein. Benutzt es dort und sprecht dann mit Tajarri, um die Prüfung abzuschließen."}},faq={{q="Was soll ich für Tajarri tun?",a="Tajarri bittet Euch, ein Schrein-Schmuckstück im See von Elune'ara zu finden, es am Schrein von Remulos zu benutzen und dann mit Tajarri zu sprechen.",al={"tajarri prüfung","was brauche ich","prüfung am see"}},{q="Wo ist der Schrein von Remulos?",a="Der Schrein von Remulos liegt im Nordwesten der Mondlichtung.",al={"schrein von remulos standort","wo ist der schrein","schrein standort"}},{q="Wo finde ich das Schrein-Schmuckstück?",a="Das Schrein-Schmuckstück befindet sich im See von Elune'ara.",al={"schmuckstück fundort","schmuckstück finden","see schmuckstück"}},{q="Was mache ich mit dem Schrein-Schmuckstück?",a="Bringt das Schrein-Schmuckstück zum Schrein von Remulos und benutzt es dort.",al={"schmuckstück benutzen","schmuckstück am schrein","schrein-schmuckstück"}},{q="Mit wem spreche ich, nachdem ich das Schmuckstück benutzt habe?",a="Sprecht mit Tajarri am Schrein, nachdem Ihr das Schrein-Schmuckstück benutzt habt.",al={"mit tajarri sprechen","nach dem schrein","prüfung abschließen"}}},fp="17,128,13.217.0,31.117.0,31.51.0,34.39.0,36.65.0,43.63.0"}
P.entries["quest:280"] = {n="Eine dunkle Bedrohung",s="Saboteure der Dunkeleisenzwerge bedrohen den Steinwerkdamm in Loch Modan. Chefingenieur Hinderweir VII. braucht die Ladung entschärft, bevor der Loch das Tiefland überflutet.",h="Saboteure der Dunkeleisenzwerge bedrohen den Steinwerkdamm in Loch Modan.",kw={"damm","dunkeleisen","entschärfung","sprengstoff","hinderweir","aufständische","fass","seaforium","steinwerk"},ang={["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass der Steinwerkdamm lebenswichtige Wege schützt, die Khaz Modan mit den nördlichen Gebieten der Allianz verbinden.",["profession:Engineering"]="Als Ingenieur erkennt Ihr, wie Seaforium und Entschärfungschemikalien die Sprengtechnik und die Chemie der Sprengstoffentschärfung an ihre gefährlichsten Grenzen bringen.",["race:Dwarf"]="Als Zwerg kennt Ihr den Steinwerkdamm als Denkmal zwergischer Fertigkeit und zwergischen Stolzes. Ihn vor dem Verrat der Dunkeleisenzwerge zu schützen, ist für Eisenschmiede von Bedeutung.",["race:Gnome"]="Als Gnom könnt Ihr die Chemie von Hinderweirs Neutralisierungsmittel und die Verwüstung begreifen, die ein durch Seaforium verursachter Dammbruch für die Ingenieurskunst der Zwerge bedeuten könnte."},sec={{t="Sabotage unter der Oberfläche",b="Chefingenieur Hinderweir VII. sah Dunkeleisenaufständische mit einem Fass explosivem Seaforium auf den Steinwerkdamm zuschwimmen. Keine Gebirgsjäger waren in der Nähe, um sie aufzuhalten. Die Eindringlinge befestigten das Fass am Unterwasserfundament des Damms. Wenn der Damm bricht, wird der Loch das Tiefland überfluten und Handel und Reiseverkehr der Zwerge lahmlegen."},{t="Ein flüchtiges Neutralisierungsmittel",b="Chefingenieur Hinderweir VII. hat reaktive Zutaten zu einer Entschärfungslösung vermischt und schickt einen Taucher zum versenkten Fass. Der Taucher muss es aufschrauben und die Lösung in das Sprengpulver einrühren. Die Mischung stoppt den Countdown mit einem leisen Zischen unter Wasser und stabilisiert die Ladung, bevor sie den Damm zerreißen kann."}},faq={{q="Was ist das Ziel dieser Quest?",a="Ihr taucht in Loch Modan zum Fundament des Steinwerkdamms hinab. Dort findet Ihr das angebrachte Fass Seaforium und rührt die Mixtur von Chefingenieur Hinderweir VII. hinein, um die Explosion zu verhindern.",al={"questziel","was ist hier zu tun","eine dunkle bedrohung 6 ziel"}},{q="Wer hat das Sprengstofffass angebracht?",a="Dunkeleisenaufständische haben das Fass angebracht. Sie schlichen sich früher am Tag in die Gewässer von Loch Modan, als die örtlichen Gebirgsjäger abwesend waren, und befestigten die Ladung an der Unterwasserseite des Damms.",al={"wer hat die bombe hier platziert","wer hat das seaforium angebracht","eine dunkle bedrohung täter"}},{q="Was geschieht, wenn der Damm zerstört wird?",a="Der Steinwerkdamm hält die Wassermassen von Loch Modan zurück. Wenn er zerbricht, wird das Wasser das Sumpfland und die nahen Täler überfluten und Straßen, Ortschaften und Leben fortreißen.",al={"warum den damm retten","was passiert wenn die bombe explodiert","folgen der dammexplosion"}},{q="Wer hat die Entschärfungsmixtur gebraut?",a="Chefingenieur Hinderweir VII. hat das chemische Neutralisierungsmittel aus gesammelten Reagenzien hergestellt. Es kann das Seaforium neutralisieren, ohne versehentlich eine Explosion auszulösen.",al={"wer hat die mixtur hergestellt","hinderweirs rolle","wer hat die chemikalie hergestellt"}},{q="Wo befindet sich das Sprengstofffass?",a="Das Fass liegt unter Wasser am tiefen Fundament des Steinwerkdamms, auf dessen südlicher, dem See zugewandter Seite.",al={"wo ist die bombe","standort des fasses","pulverfass unter wasser"}},{q="Welcher Sprengstoff wurde verwendet?",a="Die Saboteure verwendeten Seaforium, einen flüchtigen Sprengstoff, der in ein versiegeltes, wasserdichtes Fass gepackt wurde.",al={"woraus besteht die bombe","bombentyp","welcher sprengstoff"}}},fx={["8859d649"]={q="Warum möchte Chefingenieur Hinderweir VII., dass dies erledigt wird?",a="Als Chefingenieur, der den Steinwerkdamm beaufsichtigt, übernimmt Hinderweir die persönliche Verantwortung für dessen strukturelle Integrität. Dunkeleisenaufständische haben direkt am Fundament einen starken Seaforyumsprengstoff platziert. Sollte der Damm brechen, würde die katastrophale Flut aus dem Loch die Täler darunter überfluten und eines der größten architektonischen Wunder der Zwerge zerstören.",al={"warum kümmert sich hinderweir","hinderweir motivation","warum die explosion stoppen"}},["34eba16d"]={q="Warum braucht Chefingenieur Hinderweir VII. Euch anstelle der Gebirgsschützen?",a="Als sich die Dunkeleisensaboteure näherten, waren keine Gebirgsschützen in der Nähe, um sie abzufangen, und die Zeit drängt verzweifelt. Die Ladung könnte jeden Moment detonieren und Hinderweir musste zurückbleiben, um dringend die Entschärfungsmixtur aus den Rohkomponenten zu brauen. Ihr seid die einzige fähige Hand vor Ort, die unter Wasser tauchen und den Sprengstoff sofort neutralisieren kann.",al={"warum können die wachen das nicht tun","warum ich hinderweir","wo sind die gebirgsschützen"}}},fp="19,165,28.339.0,22.330.1,31.185.0,30.196.0,37.151.0,36.155.0,35.103.0,32.98.0"}
P.entries["quest:282"] = {n="Senirs Beobachtungen",s="Grelin Weißbart schickt Euch mit seinem Bericht für seinen Bruder Senir nach Osten, nach Kharanos. Troggs haben den Tunnel aus dem Coldridgetal überrannt, wo Gebirgsjäger Thalos den Weg bewacht.",h="Grelin Weißbart schickt Euch mit seinem Bericht für seinen Bruder Senir nach Osten, nach Kharanos.",kw={"ambossar","das coldridgetal","grelin weißbart","grelins bericht","kharanos","gebirgsjäger thalos","senir weißbart","troggs","tunnel"},ang={["faction:Alliance"]="Ihr helft, den Weg zwischen den Zwergentälern zu sichern, und schützt dabei Eisenschmiede und die Kuriere der Allianz.",["race:Dwarf"]="Als zwergischer Gebirgsjäger oder Rekrut durchquert Ihr den östlichen Tunnel auf Eurem ersten offiziellen Einsatz jenseits des Ausbildungsgeländes im Coldridgetal.",["race:Gnome"]="Als gnomischer Flüchtling unter den Bronzebeards könnt Ihr diese Depesche aus Eurer ersten Zuflucht zu den Unruhen tragen, die Dun Morogh erfasst haben."},sec={{t="Ein Kurier für die Whitebeards",b="Grelin Weißbarts Bericht handelt von den Aktivitäten der Frostmane-Trolle rund um das Coldridgetal. Die Trolle stahlen sein Tagebuch, und Ihr habt es zurückgeholt. Grelin hielt die Erkenntnisse für zu wichtig, um sie einem unerfahrenen Lehrling mitzugeben. Deshalb vertraut er Euch den Bericht an, damit Ihr ihn direkt zu seinem Bruder Senir in Kharanos bringt."},{t="Der versperrte Pass nach Kharanos",b="Troggs haben den östlichen Tunnel aus dem Coldridgetal in den Rest von Dun Morogh überrannt. Gebirgsjäger Thalos bewacht den Eingang, um Zivilisten vor Gefahren zu schützen. Er lässt Reisende nur hindurch, wenn sie in dringenden offiziellen Angelegenheiten unterwegs sind."}},faq={{q="An wen schickt Grelin diesen Bericht?",a="Grelin Weißbart schickt seinen Bericht an seinen Bruder Senir Weißbart in Kharanos, wo Senir die Probleme der Region beurteilt.",al={"wer bekommt den bericht","senir weißbart","berichtsempfänger"}},{q="Warum kann Grelins Lehrling den Bericht nicht überbringen?",a="Grelin wollte seinen Lehrling schicken, doch Frostmane-Trolle stahlen sein Tagebuch. Die Erkenntnisse waren zu wichtig, um sie unerfahrenen Händen anzuvertrauen.",al={"warum nicht der lehrling","grelins lehrling"}},{q="Warum wird der Tunnel aus dem Coldridgetal bewacht?",a="Troggs haben den Tunnel aus dem Coldridgetal nach Dun Morogh überrannt. Gebirgsjäger Thalos bewacht den Eingang, um Zivilisten zu schützen, bis der Weg frei ist.",al={"warum hält thalos wache","tunnel versperrt","warum ist der tunnel geschlossen"}},{q="Wo befindet sich Gebirgsjäger Thalos?",a="Gebirgsjäger Thalos hält östlich von Ambossar Wache, nahe dem Eingang zum Tunnel aus dem Coldridgetal in Richtung Kharanos.",al={"thalos standort","wo ist thalos","gebirgsjäger thalos finden"}},{q="Was erlaubt Euch, den von Troggs befallenen Tunnel zu durchqueren?",a="Gebirgsjäger Thalos lässt Euch hindurch, weil Ihr Grelin Weißbarts dringende Depesche bei Euch tragt.",al={"tunnel durchqueren","erlaubnis für den tunnel"}},{q="Was geschieht nach dem Gespräch mit Gebirgsjäger Thalos?",a="Gebirgsjäger Thalos warnt Euch vor dem gefährlichen Tunnel und gibt Euch Hinweise, bevor er Euch weiter nach Osten in Richtung Kharanos ziehen lässt.",al={"nächster schritt","was kommt nach thalos"}}},fx={ba85e128={q="Warum möchte Grelin Weißbart, dass dieser Bericht überbracht wird?",a="Grelin Weißbart hat die wachsende Aktivität und die Bedrohungen der Frostmähnentrolle im Coldridgetal dokumentiert. Sein Bruder, Senir Weißbart, ist in Kharanos stationiert und sammelt Informationen über umfassendere Probleme in ganz Dun Morogh. Diesen Bericht sicher zu Senir zu bringen, ist entscheidend für die Koordination der Verteidigung der Region, besonders jetzt, da die Frostmähnen näher an die zwergischen Siedlungen heranrücken.",al={"warum grelin bericht senden","grelin weißbart motiv","warum senirs beobachtungen abliefern"}}},fp="20,178,29.308.0,28.232.0,37.123.0,49.145.0,50.153.0,36.108.0,58.90.0,52.120.0"}
P.entries["quest:2821"] = {n="Das Zeichen der Qualität",s="In der Mondfederfeste sucht Pratt McGrubben zehn dicke Yetibälge und bietet Lederwaren zur Auswahl.",h="In der Mondfederfeste sucht Pratt McGrubben zehn dicke Yetibälge und bietet Lederwaren zur Auswahl.",kw={"mondfederfeste","wildschrammtal","feralas","die vergessene küste","pratt mcgrubben","das zeichen der qualität","dicker yetibalg","yetis"},sec={{t="Pratts Philosophie",b="Pratt McGrubben, ein Lederer in der Mondfederfeste, besteht auf bester Arbeit. Auf der Suche nach edlen Materialien entdeckte er dicke Yetibälge. Yetis sind in Feralas heimisch, und viele leben rund um das Wildschrammtal, direkt landeinwärts der Vergessenen Küste."},{t="Das Angebot",b="Bringt Pratt einen Stapel mit zehn Bälgen zur Mondfederfeste. Im Gegenzug dürft Ihr eine seiner selbst gefertigten Lederwaren auswählen."},{t="Pratts Gedanken zu den Bälgen",b="Pratt McGrubben fragt, ob Ihr die Beschaffenheit der Bälge erfühlt habt. Richtig behandelt könnten sie sich als zäher als Eisen erweisen, und nur wenige Leute wissen von ihnen. Pratt kennt viele Gerbmittel. Er hofft, aus den Bälgen Stücke zu fertigen, die eines wahren Zeichens der Qualität würdig sind."}},faq={{q="Wer bittet um die Bälge?",a="Pratt McGrubben, der Lederer in der Mondfederfeste, bittet um die Bälge.",al={"questgeber","pratt mcgrubben","wer vergibt das zeichen der qualität"}},{q="Wo sind die Yetis zu finden?",a="Rund um das Wildschrammtal, direkt landeinwärts der Vergessenen Küste, wo viele der in Feralas heimischen Yetis leben.",al={"yeti fundort","wo sind yetis","wildschrammtal"}},{q="Wie viele Bälge möchte Pratt?",a="Pratt möchte zehn Bälge in einem Stapel.",al={"wie viele yetibälge","anzahl der bälge"}},{q="Was bekomme ich für die Bälge?",a="Pratt lässt Euch im Tausch gegen den Stapel eine seiner selbst gefertigten Lederwaren auswählen.",al={"was gibt pratt","das zeichen der qualität belohnung"}}},fp="19,107,18.246.0,9.126.0,29.253.1,28.81.0,29.102.0,31.35.0,28.94.0"}
P.entries["quest:2822"] = {n="Das Zeichen der Qualität",s="In Camp Mojache sucht Jangdor Swiftstrider zehn dicke Yetibälge und macht bei der Qualität keine Kompromisse.",h="In Camp Mojache sucht Jangdor Swiftstrider zehn dicke Yetibälge und macht bei der Qualität keine Kompromisse.",kw={"camp mojache","wildschrammtal","feralas","die vergessene küste","jangdor swiftstrider","lederverarbeitung","dicker yetibalg","yeti"},sec={{t="Eine Frage des Stolzes",b="Jangdor Swiftstrider ist stolz auf feine Lederarbeiten. Er hat dicke Yetibälge in Feralas gefunden, wo die Yetis beheimatet sind. Viele streifen westlich von Camp Mojache im Wildschrammtal umher, gleich hinter der Vergessenen Küste im Landesinneren."},{t="Das Angebot",b="Bringt Jangdor einen Stapel von zehn Bälgen nach Camp Mojache. Dafür lässt er Euch eine der Lederwaren auswählen, die er hergestellt hat."},{t="Jangdors Gedanken zu den Bälgen",b="Jangdor sagt, eine besondere Behandlung könne die Bälge so widerstandsfähig wie Eisen machen. Die richtige Gerbmischung zu finden, wird viele Versuche erfordern. Er glaubt, dass diese Bälge seinen Qualitätsmaßstab höher als je zuvor setzen können."}},faq={{q="Wer verlangt die Bälge?",a="Jangdor Swiftstrider, der Lederer in Camp Mojache in Feralas, verlangt die Bälge.",al={"wer gibt die quest","questgeber zeichen der qualität","wo ist jangdor"}},{q="Wo sind die Yetis zu finden?",a="Yetis sind in Feralas beheimatet. Viele streifen westlich von Camp Mojache im Wildschrammtal umher, gleich hinter der Vergessenen Küste im Landesinneren.",al={"wo sind die yetis","yetibalg fundort","wo ist das wildschrammtal"}},{q="Wie viele Bälge werden benötigt?",a="Zehn Bälge, die in einem Stapel gebracht werden.",al={"wie viele yetibälge","yetibälge anzahl","zeichen der qualität voraussetzung"}},{q="Was bekomme ich für die Bälge?",a="Jangdor bietet Euch im Austausch für den Stapel eine Auswahl aus den Lederwaren, die er hergestellt hat.",al={"was gibt jangdor","zeichen der qualität belohnung"}}},fp="19,100,17.215.0,9.123.0,31.203.1,28.92.0,29.120.0,28.32.0,28.87.0"}
P.entries["quest:283"] = {n="Eine dunkle Bedrohung",s="Chefingenieur Hinderweir VII. braucht Euch am Steinwerkdamm, wo Saboteure der Dunkeleisenzwerge eine Sprengladung angebracht haben. Entschärft sie, bevor das Tal unterhalb in Gefahr gerät.",h="Chefingenieur Hinderweir VII.",kw={"dunkeleisen","entschärfungsmixtur","sprengladung","hinderweir","loch modan","sabotage","der steinwerkdamm"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, wichtige Landverbindungen zwischen Eisenschmiede und den nördlichen Gebieten von Arathi und Lordaeron zu erhalten.",["profession:Engineering"]="Als Ingenieur wisst Ihr, wie wichtig Gegenmaßnahmen und die Theorie der Sprengstoffe sind, wenn Ihr einen instabilen Sprengsatz im Inneren eines gewaltigen Bauwerks entschärft.",["race:Dwarf"]="Als Zwerg könnt Ihr stolz auf den Steinwerkdamm sein, ein großes Werk zwergischer Steinmetzkunst. Ihn zu schützen bedeutet, Eisenschmiedes Stolz gegen die Bosheit der Dunkeleisenzwerge zu bewahren."},sec={{t="Die Sprengladung im Damm",b="Der Steinwerkdamm hält die Wasser des Lochs über dem Tiefland des Sumpflands zurück. Nun liegt eine Sprengladung in seinem Inneren, ein hochexplosives Fass, das Dunkeleisenzwerge dort zurückgelassen haben. Wenn es explodiert, werden das Tal unterhalb und die Menschen flussabwärts dafür bezahlen. Es liegt an Euch, die Entschärfungsmixtur anzuwenden, bevor das geschieht, und dann Chefingenieur Hinderweir VII. Bericht zu erstatten."},{t="Hinderweirs Erleichterung",b="Ihr wendet die Entschärfungsmixtur an, und das hochexplosive Fass verpufft harmlos. Die unmittelbare Gefahr für den Damm und die Menschen flussabwärts ist gebannt. Chefingenieur Hinderweir VII. nimmt Euren Bericht erleichtert entgegen. Er nennt Euer Eingreifen einen Sieg für das Königreich Eisenschmiede und die Allianz. Eindringlinge der Dunkeleisenzwerge sind tief nach Khaz Modan vorgedrungen, und ihre verbitterten Vettern bleiben entschlossen, Eisenschmiedes Errungenschaften zu vernichten."}},faq={{q="Was war das Ziel dieser Questreihe?",a="Die Questreihe soll einen Plan der Dunkeleisenzwerge aufdecken und vereiteln, Sprengladungen zu zünden und den Steinwerkdamm zu zerstören.",al={"eine dunkle bedrohung zusammenfassung","steinwerkdamm questziel","warum bombe entschärfen"}},{q="Wer hat die Sprengladung angebracht?",a="Saboteure der Dunkeleisenzwerge haben das explosive Fass im Inneren des Steinwerkdamms platziert, um ihn zu zerstören.",al={"wer hat die bombe hier platziert","wer hat den damm angegriffen","dunkeleisenzwerge damm"}},{q="Wer ist Chefingenieur Hinderweir VII.?",a="Chefingenieur Hinderweir VII. ist der zwergische Aufseher, der für Wartung, Betrieb und Verteidigung des Steinwerkdamms in Loch Modan verantwortlich ist.",al={"wer ist hinderweir","hinderweir geschichte","ingenieur am damm"}},{q="Was wäre geschehen, wenn der Damm gebrochen wäre?",a="Wäre der Steinwerkdamm gebrochen, hätte sich der Stausee von Loch Modan mit gewaltiger Wucht entleert und das flussabwärts gelegene Sumpfland überflutet, wobei Straßen, Siedlungen und wichtige Verkehrswege fortgerissen worden wären.",al={"was wenn der damm zerstört wird","folgen eines dammbruchs","dammexplosion"}},{q="Wie wurde die Sprengladung entschärft?",a="Ihr gießt eine eigens hergestellte Entschärfungsmixtur über die Sprengladung, und das Pulverfass verpufft harmlos, bevor es explodieren kann.",al={"wie wurde die bombe aufgehalten","entschärfungsmixtur","wie wird die sprengladung entschärft"}},{q="Ist der Steinwerkdamm jetzt sicher?",a="Die unmittelbar drohende Explosion wurde verhindert und der Damm gerettet. Hinderweir sagt, seine Verteidigung sei nur vorerst gesichert, da Agenten der Dunkeleisenzwerge die Region weiterhin bedrohen.",al={"ist der damm gesichert","sind die dunkeleisenzwerge fort","damm für immer sicher"}}},fp="19,157,21.377.0,19.433.1,38.115.0,33.96.0,37.143.0,42.169.0,31.137.1,33.176.1"}
P.entries["quest:284"] = {n="Die Suche geht weiter",s="Die Suche nach der Statuette von Menethil geht in den nahen Murloc-Behausungen weiter. Diese Unterstände bergen keine Spur von ihr, also wendet Ihr Euch zwei weiteren zu.",h="Die Suche nach der Statuette von Menethil geht in den nahen Murloc-Behausungen weiter.",kw={"fass","käse","behausungen","statuette von menethil","murloc","suche"},sec={{t="Leere Behausungen",b="Ihr durchsucht diese Gruppe von Murloc-Behausungen, findet aber keine Spur der Statuette von Menethil. Zwei nahe Unterstände im Norden und Nordosten könnten Hinweise bergen."}},faq={{q="Wonach suche ich?",a="Ihr sucht nach der Statuette von Menethil.",al={"suche nach der statuette","menethil-statue","welche statuette"}},{q="Was finde ich in diesen Behausungen?",a="Ihr findet in dieser Gruppe von Murloc-Behausungen keine Spur der Statuette von Menethil.",al={"murloc-behausungen","leere behausungen","etwas hier"}},{q="Wo sollte ich als Nächstes suchen?",a="Sucht in den nahen Behausungen im Norden und Nordosten nach weiteren Hinweisen.",al={"nächste behausungen","wo suchen","hütten im norden"}},{q="Was ist in dem Fass?",a="Das Fass enthält feuchten, streng riechenden Käse, der noch immer gut schmeckt.",al={"fassinhalt","käsefass","was ist im fass"}}},fp="20,135,12.149.0,24.45.0,31.77.0,25.68.0,22.58.0"}
P.entries["quest:2844"] = {n="Der Riesenwächter",s="Felsbeißer sucht nach Shay, dem Nachtelfenmädchen, auf das er aufpassen sollte. Besorgt bittet er Euch, nach ihr zu suchen.",h="Felsbeißer sucht nach Shay, dem Nachtelfenmädchen, auf das er aufpassen sollte.",kw={"feralas","riesenwächter","verirrtes mädchen","felsbeißer","ruinen","shay","shay leafrunner"},sec={{t="Verschwunden, als er sich umdrehte",b="Felsbeißer sah Shay zuletzt, als sie durch die Ruinen direkt nördlich seines Standorts gingen. Dann drehte er sich um, und sie war verschwunden. Unsicher, was er tun soll, bittet er Euch, nach seiner kleinen Freundin zu suchen. Eure Beine können Euch viel schneller tragen als seine."},{t="Wenn Ihr sie findet",b="Shay ist froh, dass Ihr sie gefunden habt. Sie hat sich ein wenig verlaufen, kann aber dennoch nicht umhin zu bemerken, was für ein wunderschöner Ort dies ist."}},faq={{q="Wen sucht Felsbeißer?",a="Felsbeißer sucht nach Shay, einem kleinen Nachtelfenmädchen und seiner Freundin. Er sollte auf sie aufpassen.",al={"wer ist shay","wer ist das vermisste mädchen","wer hat sich verlaufen"}},{q="Wo wurde Shay zuletzt gesehen?",a="Felsbeißer sah Shay zuletzt, als sie durch die Ruinen direkt nördlich seines Standorts gingen.",al={"wohin ist shay gegangen","zuletzt gesehener ort","wo sind die ruinen"}},{q="Warum bittet Felsbeißer jemand anderen zu suchen?",a="Felsbeißer ist besorgt und weiß nicht, was er tun soll. Er glaubt, dass Eure Beine Euch viel schneller tragen können als seine.",al={"warum kann felsbeißer nicht suchen","warum einen abenteurer schicken"}}},fp="18,113,30.241.0,17.109.1,29.102.0,25.87.0,46.99.0"}
P.entries["quest:2845"] = {n="Streunende Shay",s="Shay Leafrunner lässt sich unterwegs von allem ablenken, während sie zu ihrem Freund Felsbeißer zurückkehren will.",h="Shay Leafrunner lässt sich unterwegs von allem ablenken, während sie zu ihrem Freund Felsbeißer zurückkehren...",kw={"eskorte","feralas","giant guardian","felsbeißer","shay leafrunner","shays glocke"},sec={{t="Ein leicht abgelenktes Mädchen",b="Felsbeißer sollte auf Shay aufpassen. Sie möchte zu ihm zurückkehren, doch die vielen Dinge um sie herum erregen ihre Aufmerksamkeit und bringen sie vom Weg ab."},{t="Die Glocke in der Kiste",b="Eine Glocke in der Kiste neben Shay erregt immer ihre Aufmerksamkeit, und sie liebt ihren Klang. Wenn sie davonläuft, läutet die Glocke, und sie verspricht, zurückgelaufen zu kommen. Ihr könnt die Glocke zu Felsbeißers Lager tragen, wohin Shay gebracht werden möchte."}},faq={{q="Zu wem möchte Shay Leafrunner zurückkehren?",a="Shay möchte zu ihrem Freund Felsbeißer zurückkehren, der auf sie aufpassen sollte. Ihr könnt sie zu seinem Lager bringen.",al={"wer ist felsbeißer","shays freund","wohin geht shay"}},{q="Warum läuft Shay davon?",a="Die vielen Dinge, die es zu sehen gibt, lenken Shay ab, sodass sie davonläuft.",al={"warum hat sich shay verirrt","wie hat sich shay verirrt","warum ist shay davongelaufen"}},{q="Wie halte ich Shay davon ab, vom Weg abzukommen?",a="Shays Glocke liegt in einer Kiste neben ihr, und sie liebt ihren Klang. Sie verspricht, dass das Läuten sie zurückgelaufen kommen lässt, falls sie davonläuft.",al={"shay unter kontrolle halten","shays glocke","was bewirkt die glocke"}},{q="Was kommt davor?",a="The Giant Guardian kommt davor. Felsbeißer schickt Euch dort los, um nach Shay zu suchen.",al={"vorherige quest","giant guardian","was führt zu streunende shay"}}},fp="14,106,24.136.0,21.231.0,45.109.0,25.57.0,33.143.0,23.81.0"}
P.entries["quest:285"] = {n="Suche in weiteren Hütten",s="In den Murloc-Hütten habt Ihr keine Spur der Statuette von Menethil gefunden. Also dringt Ihr weiter nach Norden vor und sucht nach dem nächsten Hinweis.",h="In den Murloc-Hütten habt Ihr keine Spur der Statuette von Menethil gefunden.",kw={"fass","statuette von menethil","murloc-hütten","hütten im norden","weitere hütten durchsuchen"},sec={{t="Suche im Norden",b="Ihr glaubt, dass die Statuette von Menethil in einer der Hütten im Norden liegt. Also setzt Ihr Eure Suche zwischen den Murloc-Behausungen fort."}},faq={{q="Wonach suche ich?",a="Ihr durchsucht die Murloc-Hütten nach der Statuette von Menethil.",al={"suche nach der statuette","menethil-statue","wonach suche ich"}},{q="War die Statuette in diesen Hütten?",a="Eine gründliche Durchsuchung dieser Hüttengruppe ergibt nichts.",al={"leere hütten","hier etwas gefunden","was ergab die durchsuchung der hütten"}},{q="Wo könnte die Statuette sein?",a="Ihr glaubt, dass eine der Murloc-Hütten weiter nördlich die Statuette von Menethil bergen könnte.",al={"wo ist die statuette","hütten im norden","fundort der statuette"}}},fp="18,125,16.130.0,24.63.0,36.58.0,29.83.0"}
P.entries["quest:286"] = {n="Rückgabe der Statuette",s="Karl Boran im Hafen von Menethil braucht die Statuette von Menethil zurück. Sie wurde in einem Fass gefunden, das aus dem Schlamm gezogen wurde, und ihre Rückkehr wird den Kapitän der Blind Princess beruhigen.",h="Karl Boran im Hafen von Menethil braucht die Statuette von Menethil zurück.",kw={"fass","blind princess","karl boran","hafen von menethil","statuette von menethil","paladin","statuette"},sec={{t="Die kleine Figur",b="Die Statuette lag in feinem Stroh verpackt im Fass. Sie zeigt einen jungen, langhaarigen Paladin, der einen Hammer erhebt. Karl Boran im Hafen von Menethil wartet auf sie. Der Kapitän der Blind Princess wird erleichtert sein zu erfahren, dass die Ladung sicher ist."}},faq={{q="Was ist die Statuette von Menethil?",a="Die Statuette von Menethil ist eine silbrige Figur, die einen jungen, langhaarigen Paladin mit erhobenem Hammer zeigt.",al={"statuette","menethil figur","was ist im fass"}},{q="Wo wurde die Statuette gefunden?",a="Die Statuette war in feinem Stroh verpackt und lag in einem Fass, das aus dem Schlamm gezogen wurde.",al={"fass statuette","wo war sie","stroh fass"}},{q="Wer wartet auf die Statuette?",a="Karl Boran im Hafen von Menethil wartet auf die Statuette von Menethil.",al={"wer bekommt die statuette","statuette zurückbringen","karl boran"}},{q="Wer wird erleichtert sein, wenn sie zurückgebracht wird?",a="Der Kapitän der Blind Princess wird erleichtert sein, dass die kostbare Ladung geborgen wurde.",al={"kapitän erleichtert","blind princess ladung","wem gehört die ladung"}},{q="Was stellt die Statuette dar?",a="Die Statuette stellt einen jungen, langhaarigen Paladin mit erhobenem Hammer dar.",al={"wer ist auf der statuette","paladin figur","hammer statuette"}}},fp="20,178,12.235.0,31.103.0,30.76.0,33.68.0,41.94.0,31.72.0"}
P.entries["quest:2862"] = {n="Krieg gegen die Waldpfoten",s="In Camp Mojache bittet Hadoken Swiftstrider Euch, die wachsende Zahl der Waldpfoten-Gnolle zu verringern. Ihre Angriffe sind immer hitziger geworden, und zehn Woodpaw Gnoll Manes sollen seine Bitte erfüllen.",h="In Camp Mojache bittet Hadoken Swiftstrider Euch, die wachsende Zahl der Waldpfoten-Gnolle zu verringern.",kw={"alpha strike","camp mojache","feralas","gnolle","hadoken swiftstrider","mähnen","waldpfoten"},sec={{t="Eine Bedrohung für das Lager",b="Hadoken Swiftstrider sagt, das Überleben des Lagers sei wichtiger als der Anspruch der Gnolle auf Feralas. Wenn Camp Mojache nicht standhaft bleibt, warnt er, könnten die Gnolle das Lager aus der gesamten Region vertreiben. Ihre Angriffe sind immer hitziger geworden, weshalb er ihre Zahl verringert sehen möchte. Für zehn Mähnen von Waldpfoten-Gnollen bietet er eine großzügige Bezahlung."},{t="Hadokens Antwort",b="Hadoken Swiftstrider nennt die Mähnen einen guten Anfang. Er hat dieselbe Bitte an andere gerichtet, die schon zuvor gegen die Gnolle gekämpft haben, und ihre Bemühungen hielten sie einst zurück. In letzter Zeit sind die Gnolle weitaus häufiger nach Norden in das Gebiet vorgedrungen, über das Camp Mojache herrscht. Ihre Angriffe sind wild, beinahe verzweifelt geworden. Hadoken sagt, er habe einen Plan, der die Angelegenheit klären könnte."}},faq={{q="Wer bietet dieses Kopfgeld in Feralas an?",a="Hadoken Swiftstrider bietet das Kopfgeld in Camp Mojache an.",al={"wer vergibt krieg gegen die waldpfoten","wo krieg gegen die waldpfoten abgeben","questgeber krieg gegen die waldpfoten"}},{q="Warum geht Camp Mojache gegen die Waldpfoten-Gnolle vor?",a="Hadoken betrachtet die Waldpfoten-Gnolle als ständige Gefahr für Camp Mojache. Ihre Angriffe sind immer hitziger geworden, und er fürchtet, dass das Lager aus der gesamten Region vertrieben wird, wenn es nicht standhaft bleibt.",al={"warum gegen die waldpfoten kämpfen","waldpfotenproblem","warum greifen die gnolle an"}},{q="Welchen Beweis verlangt Hadoken Swiftstrider?",a="Hadoken Swiftstrider verlangt zehn Woodpaw Gnoll Manes.",al={"welche gegenstände für krieg gegen die waldpfoten","waldpfoten questgegenstände","was hadoken bringen"}}},fp="18,182,20.314.0,18.368.1,34.55.0,49.193.0,45.54.0"}
P.entries["quest:2863"] = {n="Schlag gegen die Alphas",s="Die Pattsituation der Horde mit den Woodpaw-Gnollen könnte durch rasche Schläge gegen ihre Anführer beendet werden. Hadoken Swiftstrider bittet Euch, innerhalb einer Stunde fünf Alphas niederzustrecken.",h="Die Pattsituation der Horde mit den Woodpaw-Gnollen könnte durch rasche Schläge gegen ihre Anführer beendet...",kw={"schlag gegen die alphas","feralas","gnolle","hadoken swiftstrider","woodpaw","woodpaw-alpha"},sec={{t="Fünf Alphas in einer Stunde",b="Hadoken Swiftstrider glaubt, dass die Reihen der Woodpaw ins Chaos stürzen, wenn ihre Alphas einer nach dem anderen sterben. Die Schläge könnten den Gnollen auch zeigen, dass die Horde sie vernichten kann. Er bittet Euch, den Plan auszuführen. Fünf Alphas müssen innerhalb einer Stunde fallen, sonst besteht die Pattsituation fort."},{t="Danach",b="Hadoken Swiftstrider erwartet, dass die getöteten Anführer und gelichteten Reihen die Gnolle zögern lassen, bevor sie das Lager stürmen. Er muss noch herausfinden, was sie in eine solche Raserei getrieben hat. Er hofft, es zu erfahren, bevor sie sich neu formieren."}},faq={{q="Wer vergibt diese Quest?",a="Hadoken Swiftstrider gibt Euch diesen Auftrag angesichts der Pattsituation zwischen der Horde und den Woodpaw-Gnollen.",al={"wer vergibt schlag gegen die alphas","hadoken swiftstrider","questgeber"}},{q="Warum das Zeitlimit von einer Stunde?",a="Der Plan beruht darauf, dass die Alphas in rascher Folge fallen, um die Reihen der Gnolle ins Chaos zu stürzen. Fünf müssen innerhalb einer Stunde fallen.",al={"warum eine stunde","warum rasche abfolge","schlag gegen die alphas zeitlimit"}},{q="Was sind die Alphas?",a="Die Alphas sind Anführer unter den Woodpaw-Gnollen, die sich selbst Alphas nennen.",al={"woodpaw-alphas","gnoll-alphas","wer sind die ziele"}},{q="Wie viele Alphas muss ich töten?",a="Ihr müsst innerhalb einer Stunde fünf Alphas töten und dann zu Hadoken Swiftstrider zurückkehren.",al={"wie viele alphas","anzahl der alphas"}}},fp="12,179,22.277.0,10.225.1,21.102.0,23.127.0,20.76.0,28.79.0"}
P.entries["quest:2866"] = {n="Die Ruinen von Solarsal",s="Südlich von Shandris Mondfeder drängen sich Naga der Hatecrest in den Ruinen von Solarsal. Sie schickt Euch zwischen die alten Steine, um nach etwas Ungewöhnlichem zu suchen.",h="Südlich von Shandris Mondfeder drängen sich Naga der Hatecrest in den Ruinen von Solarsal.",kw={"mondfederfeste","feralas","pavillon","glyphen","hatecrest","naga","shandris mondfeder","solarsal"},sec={{t="Naga zwischen alten Steinen",b="Shandris Mondfeder sagt, dass Forscher die Ruinen vor langer Zeit durchsucht und nichts Bemerkenswertes gefunden haben. Deshalb ließ man die alten Steine unberührt. Nun haben Naga der Hatecrest sie in beunruhigender Zahl besetzt. Ihre Anwesenheit schien zunächst einen Angriff anzukündigen, und diese Gefahr besteht weiterhin. Doch Shandris vermutet, dass noch etwas anderes vor sich gehen könnte. Sie bittet Euch, durch die Ruinen zu gehen und auf alles Ungewöhnliche zu achten."},{t="Was ins Auge fällt",b="Ein Pavillon unterscheidet sich vom umgebenden Mauerwerk und ist eindeutig neuer. Kleine Glyphen wiederholen sich an seinen Seiten, doch niemand weiß, woher sie stammen oder was sie bedeuten. Der Stein fühlt sich warm an."}},faq={{q="Wo liegen die Ruinen von Solarsal?",a="Die Ruinen liegen südlich von Shandris Mondfeder.",al={"ruinen von solarsal lage","wo liegt solarsal","wo solarsal finden"}},{q="Warum ist Shandris Mondfeder wegen der Ruinen besorgt?",a="Naga der Hatecrest haben die Ruinen in beunruhigender Zahl besetzt. Ihre Anwesenheit wirkte zunächst wie die Vorbereitung auf einen Angriff, und das bleibt weiterhin möglich. Shandris vermutet, dass noch etwas anderes vor sich gehen könnte.",al={"warum nach solarsal geschickt","shandris mondfeder solarsal grund","warum solarsal untersuchen"}},{q="Was waren die Ruinen von Solarsal, bevor die Naga kamen?",a="Die Ruinen stammen aus einer Zeit vor der modernen Ära. Shandris sagt, dass sie vor langer Zeit erkundet wurden, doch man fand nichts Bemerkenswertes und ließ sie deshalb unberührt.",al={"solarsal geschichte","was ist solarsal"}},{q="Welche Naga befinden sich in den Ruinen?",a="Naga der Hatecrest befinden sich in den Ruinen.",al={"wer ist in solarsal","solarsal feinde","nagastamm in solarsal"}}},fp="21,151,22.386.0,15.198.1,32.44.0,54.197.0,56.131.0,28.32.0"}
P.entries["quest:2867"] = {n="Kehrt zur Mondfederfeste zurück",s="Ihr kehrt mit Kunde von einem seltsamen Pavillon im Herzen der Ruinen von Solarsal zur Mondfederfeste zurück. Generalin Shandris Mondfeder erwartet Euren Bericht.",h="Ihr kehrt mit Kunde von einem seltsamen Pavillon im Herzen der Ruinen von Solarsal zur Mondfederfeste zurück.",kw={"mondfederfeste","feralas","hatecrest","naga","ruinen von solarsal","shandris mondfeder","pavillon von solarsal"},sec={{t="Den Bericht heimbringen",b="In der Mondfederfeste erwartet Generalin Shandris Mondfeder Eure Neuigkeiten über den seltsamen Pavillon. Ihr bringt Eure Erkenntnisse aus dem Herzen der Ruinen zurück, damit sie erfährt, was Ihr gesehen habt."},{t="Bei Eurer Rückkehr",b="Shandris findet Euren Bericht über den Pavillon beunruhigend. Die Naga hatten vielleicht keinen Angriff beabsichtigt, doch ihre anhaltende Anwesenheit verheißt nichts Gutes für den Vorstoß nach Feralas. Die Mondfederfeste braucht mehr Hilfe gegen die Hatecrest-Naga, und Shandris bietet Euch weitere Arbeit an, wenn Ihr dazu bereit seid."}},faq={{q="Wem erstatte ich nach den Ruinen Bericht?",a="Erstattet Generalin Shandris Mondfeder in der Mondfederfeste Bericht.",al={"bei wem abgeben","wer will den bericht","wo return to feathermoon stronghold abgeben"}},{q="Was soll ich berichten?",a="Berichtet Generalin Shandris Mondfeder von dem seltsamen Pavillon im Zentrum der Ruinen von Solarsal.",al={"was shandris berichten","was wurde in solarsal gefunden"}},{q="Was kommt davor?",a="„Die Ruinen von Solarsal“ kommt vor Eurer Rückkehr. Shandris schickte Euch los, um die Ruinen zu erkunden und die Naga dort zu untersuchen.",al={"vorherige quest","was führt hierher"}}},fp="32,154,24.182.0,14.281.1,35.65.0,21.98.0,23.118.0"}
P.entries["quest:2869"] = {n="Gegen die Hasskämme",s="In der Mondfederfeste will Latronicus Moonspear den Naga der Hatecrest entgegentreten, bevor sie handeln. Er bittet Euch, ihm zehn Hatecrest-Schuppen in gutem Zustand zu bringen.",h="In der Mondfederfeste will Latronicus Moonspear den Naga der Hatecrest entgegentreten, bevor sie handeln.",kw={"gegen die hasskämme","mondfederfeste","feralas","hatecrest","hatecrest naga schuppe","latronicus moonspear","naga","insel sardor"},sec={{t="Handeln, bevor es zu spät ist",b="Latronicus Moonspear erwartet, dass die Naga eines Tages versuchen werden, die Insel für sich zu beanspruchen. Er will ihnen zuvorkommen und bittet Euch deshalb, zehn Hatecrest-Schuppen in gutem Zustand zu bringen. Wie Ihr sie beschafft, müsst Ihr selbst herausfinden. Er hofft, dass das Sammeln der Schuppen die Präsenz der Naga auf der Insel Sardor schwächt und Euch erste Erfahrungen im Kampf gegen Naga verschafft."},{t="Frieden und Pflicht",b="Latronicus sagt, dass Nachtelfen Frieden und Harmonie schätzen, keinen Krieg. Dennoch wird er ihre Interessen nicht ungeschützt lassen. Sie zu schützen ist seine Pflicht gegenüber General Feathermoon und der Feste."},{t="Danach",b="Latronicus findet die Schuppen mehr als zufriedenstellend. Er plant, sie zu Pratt zu schicken, falls sich daraus etwas Nützliches herstellen lässt. Außerdem hat er eine weitere Aufgabe für Euch."}},faq={{q="Wer vergibt diese Quest und wo?",a="Latronicus Moonspear bittet um die Schuppen und nimmt sie in der Mondfederfeste entgegen.",al={"wer vergibt gegen die hasskämme","latronicus moonspear standort","wo gegen die hasskämme abgeben"}},{q="Warum will Latronicus Moonspear Hatecrest-Schuppen?",a="Latronicus erwartet, dass die Naga eines Tages versuchen werden, die Insel Sardor zu sichern, und will ihnen deshalb zuvorkommen. Das Sammeln der Schuppen könnte ihre Präsenz dort schwächen.",al={"warum hatecrest töten","hatecrest-schuppen zweck","warum naga-schuppen sammeln"}},{q="Wie viele Schuppen werden benötigt?",a="Ihr benötigt zehn Hatecrest-Schuppen in gutem Zustand.",al={"wie viele schuppen","schuppenanzahl"}},{q="Wo sind die Naga der Hatecrest zu finden?",a="Latronicus spricht von einer Präsenz der Naga auf der Insel Sardor.",al={"hatecrest standort","wo hatecrest finden","insel sardor naga"}}},fp="21,174,28.344.0,14.186.0,10.166.1,31.85.0,52.141.0,27.48.0,35.52.0"}
P.entries["quest:287"] = {n="Höhle der Frostmähnen",s="Über dem Eiswellensee bewachen Frostmanetrolle eine Höhlenfestung in den westlichen Gipfeln. Senir Weißbart, ein Gebirgsjäger und Späher in Kharanos, schickt Euch los, um ihre Tiefen zu erkunden und Informationen für seine Berichte zurückzubringen.",h="Über dem Eiswellensee bewachen Frostmanetrolle eine Höhlenfestung in den westlichen Gipfeln.",kw={"bräuhall","dun morogh","frostmaneheadhunter","höhle der frostmähnen","eistrolle","eiswellensee","kharanos","senir weißbart","the reports"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, Dun Morogh zu sichern und die Bergstraßen zwischen Eisenschmiede und den benachbarten Königreichen von Hinterhalten feindseliger Stämme freizuhalten.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Frostmanetrolle Eisenschmiede die Herrschaft über die verschneiten Gipfel von Dun Morogh streitig machen. Die Erkundung ihrer Haupthöhlenfestung hilft, das Reich zu verteidigen.",["race:Gnome"]="Als Gnom wisst Ihr, dass sich nach dem Fall von Gnomeregan Gnome in ganz Dun Morogh und Kharanos niederließen. Die Angriffe der Frostmane einzudämmen hilft, die Versorgungswege der Flüchtlinge zu sichern."},sec={{t="Ein Späher im Verzug",b="Senir verfolgte die angriffslustigen Stämme bis zu ihrer Haupthöhle südwestlich von Bräuhall. Bewaffnete Trolle drängen sich am Eingang. Da Senir mit seinen offiziellen Berichten im Verzug ist und die Höhle nicht allein betreten will, heuert er Euch an, die eisige Höhle an seiner statt auszukundschaften."},{t="Vorstoß in die Höhle",b="Über dem Eiswellensee ist die Festung in die westlichen Gipfel geschlagen und voller feindseliger Eistrolle. Ihr kämpft Euch durch unterirdische Tunnel, tötet die auf den Felsvorsprüngen postierten Frostmaneheadhunter und kartiert das Innere. Eure Erkenntnisse liefern Senir die Informationen, die er braucht, um seinen Bericht für die militärischen Befehlshaber von Eisenschmiede fertigzustellen."}},faq={{q="Wo liegt die Höhle der Frostmähnen?",a="Die Höhle der Frostmähnen liegt südwestlich von Bräuhall, in einer Höhle am äußersten Westrand von Dun Morogh. Folgt von Kharanos aus der Straße nach Norden bis zur Brücke, dann dem zugefrorenen Fluss nach Westen am Eiswellensee vorbei nach Bräuhall und steigt nach Südwesten ins Gebirge hinauf.",al={"höhle der frostmähnen finden","wo ist die höhle","lage der höhle der frostmähnen"}},{q="Wer ist Senir Weißbart?",a="Senir Weißbart ist ein zwergischer Späher, der vor der Brauerei Donnerbräu in Kharanos stationiert ist. Er verfolgt Bedrohungen in ganz Dun Morogh und schreibt Berichte über die angriffslustigen Frostmanetrolle.",al={"senir weißbart","wer vergibt die quest","questgeber kharanos"}},{q="Warum hat Senir die Festung nicht selbst erkundet?",a="Senir kundschaftete den Eingang aus und fand den Stamm dort versammelt vor, doch bewaffnete Trolle füllten die Höhle, und er fürchtete sich davor, allein hineinzugehen. Aus Sorge um seine Sicherheit und weil er mit seinen Erkundungsaufträgen in Verzug ist, überlässt er die gefährliche Erkundung fähigen Abenteurern.",al={"warum hat senir angst","warum ging senir nicht"}},{q="Wer sind die Frostmanetrolle?",a="Die Frostmane sind ein Eistrollstamm, der in den verschneiten Felsklüften von Dun Morogh beheimatet ist. Als erbitterte Feinde der Zwerge und Gnome von Eisenschmiede überfallen sie oft Handelswege, Lager und Siedlungen von versteckten Lagern in der ganzen Region aus.",al={"frostmane","trolle dun morogh","dun morogh trolle"}},{q="Was geschieht nach der Erkundung der Festung?",a="Wenn Ihr mit Nachrichten über den Aufbau der Höhle und die getöteten Kopfjäger zurückkehrt, stellt Senir seinen Bericht fertig. Er bittet Euch, die dringenden Schriftstücke seinen Vorgesetzten in Dun Morogh zu überbringen.",al={"nächste quest","was folgt nach der höhle der frostmähnen","the reports quest"}},{q="Wie tief müsst Ihr in die Höhle vordringen?",a="Dringt über den Eingang hinaus vor, erkundet die inneren Kammern und tötet fünf Frostmaneheadhunter. Ihr Tod bestätigt, dass die Tiefen der Höhle gründlich erkundet wurden.",al={"höhle der frostmähnen vollständig erkunden","auslöser für höhlenerkundung"}}},fx={["889a57f0"]={q="Warum möchte Senir Weißbart, dass die Höhle der Frostmähnen erkundet wird?",a="Senir Weißbart ist ein Agent, der an Geheimdienstberichten über die zunehmenden Bedrohungen in Dun Morogh arbeitet. Er ist bei seinen Späherpflichten in Verzug geraten und benötigt Informationen aus erster Hand über das Lager der Frostmähnentrolle, um seine Bewertung für das Kommando in Eisenschmiede abzuschließen, bevor seine Vorgesetzten davon Notiz nehmen.",al={"warum will senir das erledigt haben","senir weißbart motiv","warum höhle der frostmähnen erkunden"}},["860fac70"]={q="Warum werdet Ihr gegen die Frostmähnen-Kopfjäger ausgesandt?",a="Die Frostmähnen-Kopfjäger bilden die militante Verteidigung der Höhle der Frostmähnen, den tiefen Höhlen südwestlich von Bräuhall, wo sich die vertriebenen Trolle massiv versammelt haben. Sie zu töten, dezimiert ihre Patrouillen und ebnet den Weg, um die Tiefen der Höhle angemessen auszukundschaften.",al={"wer sind frostmähnen-kopfjäger","warum kopfjäger töten","frostmähnen-kopfjäger zweck"}}},fp="14,214,23.234.0,20.334.0,32.263.0,24.184.0,42.249.0,29.225.0,52.176.1,41.175.0"}
P.entries["quest:2870"] = {n="Gegen Lord Shalzaru",s="In der Mondfederfeste bittet Latronicus Moonspear Euch, Lord Shalzaru aufzuhalten und das Relikt zu bergen, das er gefunden hat.",h="In der Mondfederfeste bittet Latronicus Moonspear Euch, Lord Shalzaru aufzuhalten und das Relikt zu bergen...",kw={"mondfederfeste","feralas","hatecrest","die insel des schreckens","latronicus moonspear","lord shalzaru","geheimnisvolles relikt","naga","shalzaru"},sec={{t="Die Befehlskette der Naga",b="Latronicus Moonspear hat neue Berichte über die Befehlskette der Naga. Adlige erteilen in ihren Reihen die Befehle. Lord Shalzaru ist einer der grausameren Adligen."},{t="Ein seltsames Relikt",b="Späher berichten, dass Lord Shalzaru ein seltsames Relikt freigelegt hat, als die Naga in einer Höhle auf der Insel des Schreckens gruben. Die Höhle liegt jenseits des Wassers, südlich der Hauptruinen. Latronicus möchte, dass Ihr Shalzaru aufhaltet und die Grabungen beendet. Bringt dann das Geheimnisvolle Relikt zur Untersuchung in die Mondfederfeste."},{t="Wenn es vollbracht ist",b="Lord Shalzarus Fall könnte die Naga für eine Weile in Verwirrung stürzen, glaubt Latronicus, vielleicht sogar für immer. Er meint, die Bedrohung sei nun besser unter Kontrolle als je zuvor. Er hat noch eine weitere Bitte an Euch."}},faq={{q="Wer ist Lord Shalzaru?",a="Lord Shalzaru ist einer der grausameren Naga-Adligen. Adlige erteilen in den Reihen der Naga die Befehle.",al={"shalzaru","wer ist shalzaru","lord shalzaru geschichte"}},{q="Wo befindet sich Lord Shalzaru?",a="Spähern zufolge liegt Lord Shalzarus Grabungsstätte in einer Höhle auf der Insel des Schreckens, jenseits des Wassers und südlich der Hauptruinen.",al={"wo ist shalzaru","shalzaru höhle standort","shalzaru finden"}},{q="Was ist das Relikt?",a="Das Geheimnisvolle Relikt ist ein seltsamer Gegenstand, den Lord Shalzaru bei den Grabungen der Naga freigelegt hat. Latronicus möchte, dass Ihr es ihm zur Untersuchung bringt.",al={"geheimnisvolles relikt feralas","was ist das relikt","shalzaru relikt"}},{q="Wo gebe ich das Relikt ab?",a="Bringt das Relikt zu Latronicus Moonspear in der Mondfederfeste.",al={"wer bekommt das relikt","shalzaru abgeben"}}},fp="21,110,25.150.0,12.277.0,15.198.1,21.93.0,31.108.0,18.141.0,29.66.0"}
P.entries["quest:2871"] = {n="Überbringung des Relikts",s="In der Mondfederfeste schickt Latronicus Moonspear Euch mit dem Geheimnisvollen Relikt zu seiner Frau Vestia. Er wird nicht daraus schlau und hofft, dass sie sagen kann, was es ist.",h="In der Mondfederfeste schickt Latronicus Moonspear Euch mit dem Geheimnisvollen Relikt zu seiner Frau Vestia.",kw={"überbringung des relikts","mondfederfeste","feralas","latronicus moonspear","geheimnisvolles relikt","vestia moonspear"},sec={{t="Der Blick einer Gelehrten",b="Latronicus Moonspear wird aus dem Apparat nicht schlau, Wette hin oder her. Er sagt, seine Frau Vestia sei eine hervorragende Priesterin ihrer Gemeinschaft und eine der gebildetsten Gelehrten weit und breit. Wenn jemand herausfinden kann, was das Relikt ist, dann sie. Sie müssen es wissen. Vestia ist nur einen kurzen Spaziergang entfernt, auch wenn sie gewiss mit ihren Studien beschäftigt ist."},{t="Vestias erster Blick",b="Vestia Moonspear weiß, dass Ihr General Feathermoon und Latro gegen die Naga geholfen habt. Auf den ersten Blick scheint das Relikt weder aus den Ruinen zu stammen, in denen es gefunden wurde, noch Merkmale der Naga aufzuweisen. Es ist etwas weitaus Fremdartigeres. Seine Erforschung wird Zeit brauchen. Wenn sie damit fertig ist, wird sie vielleicht auf Eure Talente zurückgreifen, falls Ihr in der Nähe seid."}},faq={{q="Wer ist Vestia Moonspear?",a="Vestia Moonspear ist die Frau von Latronicus Moonspear. Er nennt sie eine hervorragende Priesterin ihrer Gemeinschaft und eine der gebildetsten Gelehrten weit und breit. Sie befindet sich in der Mondfederfeste.",al={"vestia moonspear","wer ist vestia","latros frau"}},{q="Woher stammt das Geheimnisvolle Relikt?",a="Das Geheimnisvolle Relikt ist das Relikt, das Lord Shalzaru freilegte, als die Naga in einer Höhle auf der Insel des Schreckens gruben.",al={"woher stammt das relikt","herkunft des relikts","ursprung des geheimnisvollen relikts"}},{q="Was weiß Latronicus Moonspear über das Relikt?",a="Latronicus Moonspear weiß wenig über das Relikt. Er wird aus dem Apparat nicht schlau und möchte deshalb, dass seine Frau ihn untersucht.",al={"was weiß latronicus","latros apparat"}},{q="Wohin bringe ich das Relikt?",a="Bringt das Geheimnisvolle Relikt zu Vestia Moonspear in der Mondfederfeste. Latronicus sagt, sie sei gleich um die Ecke.",al={"wer bekommt das relikt","überbringung des relikts ziel"}}},fp="20,166,15.322.0,19.325.1,24.178.0,42.116.0,52.131.0,26.117.0"}
P.entries["quest:2872"] = {n="Stoleys Schuld",s="Am Dampfdruckpier will Seewolf MacKinley den Rum, den Stoley bei ihrer Wette eingesetzt hat. Er bittet Euch, mit dem Schankwirt darüber zu sprechen.",h="Am Dampfdruckpier will Seewolf MacKinley den Rum, den Stoley bei ihrer Wette eingesetzt hat.",kw={"bilgenrum","beutebucht","mackinley","rum","dampfdruckpier","stoley","tanaris","wette"},sec={{t="Rum und Münzen",b="Seewolf MacKinley sagt, Stoley schulde ihm eine besondere Flasche Rum. Stoley prahlte damit, dass der Rum vom Dampfdruckpier stärker sei als alles in Beutebucht. Er versprach, seine Schulden bei MacKinley zu verdoppeln, falls MacKinley ihn probieren und anderer Meinung sein sollte.\n\nNun glaubt MacKinley, Stoley habe der Mut verlassen, die Flasche herauszurücken. Doch MacKinley schreckt niemals vor einer Wette zurück, also bittet er Euch, mit Stoley an der Bar am Dampfdruckpier zu sprechen."},{t="Stoleys Antwort",b="Stoley sagt, er habe keine Angst davor, den Dampfdruckbilgenrum herauszurücken. Doch es ist kein Rum mehr übrig, den er hergeben könnte."}},faq={{q="Wer ist Seewolf MacKinley?",a="Seewolf MacKinley ist Stoleys alter Freund. Sie haben eine Wette darüber abgeschlossen, wessen Rum stärker ist.",al={"wer ist mackinley","seewolf mackinley","wer vergibt stoleys schuld"}},{q="Wo befindet sich Stoley?",a="Stoley führt die Bar am Dampfdruckpier in Tanaris.",al={"wo ist stoley","stoley aufenthaltsort","stoley finden"}},{q="Welche Wette hat Stoley mit MacKinley abgeschlossen?",a="Dass der Rum vom Dampfdruckpier alles in Beutebucht übertrifft. Stoley schwor, er sei stärker, und versprach MacKinley das Doppelte seiner Schulden, falls MacKinley ihn probieren und anderer Meinung sein sollte.",al={"worum geht die wette","welche wette","stoleys wette"}}},fp="13,133,24.434.0,15.99.1,28.96.0,24.53.0,40.171.0"}
P.entries["quest:2873"] = {n="Stoleys Lieferung",s="Stoley hat keinen Rum mehr und bittet Euch, seine gestohlene Lieferung zurückzuholen. Captain Cuergo bewahrt sie in der Mast- und Schotbucht auf, der ummauerten Piratenstadt im Süden.",h="Stoley hat keinen Rum mehr und bittet Euch, seine gestohlene Lieferung zurückzuholen.",kw={"cuergo","mast- und schotbucht","mackinley","rum","lieferung","dampfdruckpier","stoley","tanaris"},sec={{t="Eine gestohlene Lieferung",b="Stoley schuldet Seewolf MacKinley aus Beutebucht wegen ihrer Wette Rum, doch sein Vorrat ist aufgebraucht. Captain Cuergo hat die letzte Lieferung genommen und bewahrt sie in der Mast- und Schotbucht auf, der ummauerten Piratenstadt im Süden. Stoley möchte, dass Ihr den Rum zurückbringt, damit er beweisen kann, dass Kalimdors Tropfen besser ist als alles, was Beutebucht einschenkt."},{t="Der Aufbewahrungsort",b="Die Piraten bewahren den Rum in Kisten im oberen Stockwerk des Hauses im Nordwesten auf."}},faq={{q="Wer ist Stoley?",a="Stoley ist am Dampfdruckpier in Tanaris. Er schuldet Seewolf MacKinley in Beutebucht Rum, um ihre Wette zu begleichen.",al={"stoley","wer vergibt stoleys lieferung","stoley tanaris"}},{q="Warum will Stoley seine Lieferung zurück?",a="Captain Cuergo hat Stoleys letzte Rumlieferung gestohlen. Stoley braucht sie, um seine Wette mit MacKinley zu begleichen und zu beweisen, dass Kalimdors Schnaps besser ist als der aus Beutebucht.",al={"warum rum","stoleys beweggründe","was ist stoleys lieferung"}},{q="Wo haben die Piraten den Rum versteckt?",a="Die Piraten bewahren den Rum in Kisten im oberen Stockwerk des nordwestlichen Hauses in der Mast- und Schotbucht auf, der ummauerten Piratenstadt im Süden.",al={"stoley rum fundort","wo ist die lieferung","mast- und schotbucht rum"}},{q="Wer ist Captain Cuergo?",a="Captain Cuergo hat Stoleys letzte Rumlieferung gestohlen und bewahrt sie in der ummauerten Piratenstadt im Süden auf.",al={"cuergo","captain cuergo"}},{q="Wo gehört dieser Schritt in die Questreihe?",a="Er folgt auf Stoley’s Debt.",al={"stoleys lieferung questreihe","was folgt auf stoleys debt"}},{q="Wer ist Seewolf MacKinley?",a="Seewolf MacKinley ist in Beutebucht. Er hat mit Stoley gewettet, wessen Rum besser ist.",al={"seewolf mackinley","mackinley beutebucht"}}},fp="17,147,17.318.0,16.84.0,14.113.0,39.149.0,35.137.0,22.102.0,38.27.0,28.90.0"}
P.entries["quest:2874"] = {n="Lieferung für MacKinley",s="Am Dampfdruckpier gibt Stoley Euch Kielwasser-Rum für MacKinley in Beutebucht. Der Seewolf kann beurteilen, ob das Getränk seine Ansichten über den Alkohol in Beutebucht ausräumt.",h="Am Dampfdruckpier gibt Stoley Euch Kielwasser-Rum für MacKinley in Beutebucht.",kw={"beutebucht","mackinley","seewolf mackinley","steamwheedle-kielwasser-rum","stoley","stoley's debt","stoley's shipment","tanaris"},sec={{t="Eine Flasche zum Mitnehmen",b="Nachdem Ihr bei der Lieferung geholfen habt, gibt Stoley Euch eine Flasche Steamwheedle-Kielwasser-Rum. Ihr bringt sie zu MacKinley in Beutebucht, wo er seine Ansichten über den dortigen Alkohol endlich ablegen kann."},{t="MacKinleys Urteil",b="MacKinley kostet den Rum und ist von dessen Scheußlichkeit begeistert. Stoley hat sein Wort bezüglich des Kielwasser-Rums gehalten, also muss MacKinley das Geld, das er schuldet, nicht bezahlen. Er nennt ihn dickflüssig wie Kies und brennend wie Lava."}},faq={{q="Wer gibt Euch die Flasche?",a="Stoley gibt Euch die Flasche am Dampfdruckpier.",al={"wer startet lieferung für mackinley","lieferung für mackinley questgeber"}},{q="Wer erhält die Flasche Rum?",a="Die Flasche geht an „Seewolf“ MacKinley in Beutebucht.",al={"wohin die flasche bringen","wer bekommt den rum","mackinley aufenthaltsort"}},{q="Welche Art von Alkohol wird geliefert?",a="Eine Flasche Steamwheedle-Kielwasser-Rum.",al={"welcher rum ist es","welchen alkohol gibt stoley"}},{q="Wo gehört dieser Schritt in die Questreihe?",a="Dieser Schritt folgt auf Stoley's Debt und Stoley's Shipment.",al={"was kommt vor lieferung für mackinley","lieferung für mackinley questreihe"}}},fp="20,160,17.192.0,19.193.1,25.49.0,31.57.0,40.35.0,38.49.0"}
P.entries["quest:2875"] = {n="GESUCHT: Andre Feuerbart",s="In Gadgetzan und am Dampfdruckpier nennt ein Steckbrief Andre Feuerbart und beschuldigt ihn der Verbrechen gegen beide Orte. Liefert seinen Kopf bei Sicherheitchef Bilgewhizzle am Dampfdruckpier ab, und er gilt als bindender Vertrag.",h="In Gadgetzan und am Dampfdruckpier nennt ein Steckbrief Andre Feuerbart und beschuldigt ihn der Verbrechen...",kw={"andre feuerbart","bilgewhizzle","gadgetzan","piratenenklave","dampfdruckpier","tanaris","steckbrief"},sec={{t="Das Dekret",b="Ein Aushang verurteilt Andre Feuerbart als niederträchtigen Piraten, dem Verbrechen gegen Steamwheedle und Gadgetzan vorgeworfen werden. Der Regierungsrat erlaubt jedem, der ihn liest, bei der Gefangennahme von Andre und seinen Helfern tödliche Gewalt anzuwenden. Er ist in der Piratenenklave südlich entlang der Küste vom Dampfdruckpier zu finden und steht dort an einem Lagerfeuer innerhalb der Mauern."},{t="Der Kopf als Stellvertreter",b="Ein weiteres Dekret besagt, dass Andres Kopf für ihn sprechen darf, falls er tot ist oder aus anderen Gründen nicht zu seiner Anhörung erscheinen kann. Bei Sicherheitchef Bilgewhizzle am Dampfdruckpier abgeliefert, gilt er als bindender Vertrag."},{t="Die Zahlungsbedingungen",b="Bilgewhizzle freut sich, dass Andre es nun doch noch zu seiner Verhandlung schaffen wird. Die Bezahlung erfolgt, sobald Ihr unterschreibt. Er tut das Kleingedruckte als harmlos ab und erklärt, es sei zu klein, um mit irgendeiner Lupe gelesen zu werden."}},faq={{q="Wer ist Andre Feuerbart?",a="Andre Feuerbart ist ein Pirat, dem Verbrechen gegen Steamwheedle und Gadgetzan vorgeworfen werden.",al={"andre feuerbart","wer ist andre","feuerbart tanaris"}},{q="Wo ist der Steckbrief zu finden?",a="Der Steckbrief hängt in Gadgetzan und am Dampfdruckpier aus.",al={"wo quest annehmen","steckbrief fundort","gesucht andre feuerbart steckbrief"}},{q="Wo befindet sich Andre Feuerbart?",a="Andre Feuerbart befindet sich an einem Lagerfeuer innerhalb der Mauern der Piratenenklave südlich entlang der Küste vom Dampfdruckpier.",al={"feuerbart aufenthaltsort","wo ist feuerbart","andre feuerbart finden"}},{q="Wer erhält den Kopf, sobald Andre erledigt ist?",a="Sicherheitchef Bilgewhizzle nimmt den Kopf am Dampfdruckpier entgegen.",al={"bei wem feuerbart abgeben","bilgewhizzle aufenthaltsort","wo feuerbarts kopf abgeben"}},{q="Warum wird sein Kopf benötigt?",a="Ein Dekret erlaubt seinem Kopf, Andre zu vertreten, falls er tot ist oder aus anderen Gründen nicht zu seiner Anhörung erscheinen kann.",al={"warum sein kopf","kopf als stellvertreter","stellvertreter bei der verhandlung"}}},fp="23,227,10.338.0,17.205.0,16.193.1,23.81.0,37.66.0,33.117.0,47.67.0,25.100.0"}
P.entries["quest:2876"] = {n="Schiffzeitpläne",s="Am Dampfdruckpier tragen einige Fahrten im Schiffsfahrplan Markierungen. Er gehört in die Hände einer Autoritätsperson dort.",h="Am Dampfdruckpier tragen einige Fahrten im Schiffsfahrplan Markierungen.",kw={"bilgewhizzle","beutebucht","piraten","schiffzeitpläne","dampfdruckpier","tanaris"},sec={{t="Die Schriftrolle",b="Schiffe verkehren zwischen dem Dampfdruckpier und Beutebucht, und die Schriftrolle nennt sie alle. Sie verzeichnet bereits unternommene und noch bevorstehende Fahrten. Große X-Zeichen durchkreuzen einige Fahrten. Notizen neben anderen warnen vor Plünderungen oder einem harten Kampf. Eine Autoritätsperson am Dampfdruckpier braucht den Fahrplan."},{t="Die Reaktion des Hafens",b="Sicherheitchef Bilgewhizzle prüft den Fahrplan und stellt fest, dass seine Daten und Uhrzeiten stimmen. Er fürchtet, was ein Piratenkapitän mit diesem Wissen anstellen könnte. Als Ihr ihm erzählt, dass Ihr ihn einem Piraten abgenommen habt, nennt Bilgewhizzle die Nachricht beunruhigend und dankt Euch. Er ist froh, dass der Pirat tot ist."}},faq={{q="Was steht auf dem Fahrplan?",a="Der Fahrplan nennt Schiffe und verzeichnet vergangene und künftige Fahrten zwischen dem Dampfdruckpier und Beutebucht. Große X-Zeichen durchkreuzen einige Fahrten, und andere Notizen erwähnen Beute oder einen harten Kampf.",al={"was steht im schiffsfahrplan","schiffsfahrplan text","lieferungsnotizen"}},{q="Wer muss dieses Dokument sehen?",a="Eine Autoritätsperson am Dampfdruckpier braucht den Fahrplan. Sicherheitchef Bilgewhizzle nimmt ihn entgegen.",al={"wem den fahrplan geben","schiffzeitpläne abgeben","wohin gehört der fahrplan"}}},fp="14,111,10.289.0,19.279.1,32.185.0,31.99.0"}
P.entries["quest:2877"] = {n="Skulk Rock-Aufräumen",s="Schlämme und Schleime überrennen die alten Stellungen der Horde um Skulk Rock. Fraggar Thundermantle am Nistgipfel will sie beseitigen lassen, denn die Wildhämmer haben Pläne für das Gelände.",h="Schlämme und Schleime überrennen die alten Stellungen der Horde um Skulk Rock.",kw={"nistgipfel","fraggar thundermantle","grüner schlamm","hinterland","jadeschleim","skulk rock","wildhammer"},sec={{t="Eine Frage des Territoriums",b="Die Wildhämmer erinnern sich stärker an die Vergangenheit als ihre Brüder in Eisenschmiede. Fraggar Thundermantle sagt, hier gewinnt man Freunde, indem man sich die Hände schmutzig macht. Die Horde hat ihre Stellungen um Skulk Rock im Hinterland aufgegeben, und Schlämme und Schleime haben sie überrannt. Die Wildhämmer haben Pläne für dieses Gelände, doch zuerst muss der Befall eingedämmt werden."},{t="Das Gelände säubern",b="Tötet zehn grüne Schlämme und zehn Jadeschleime. Kehrt dann zu Fraggar am Nistgipfel zurück und erstattet ihm Bericht."}},faq={{q="Wer ist Fraggar Thundermantle?",a="Fraggar Thundermantle ist ein Wildhammer am Nistgipfel im Hinterland. Er will Skulk Rock säubern lassen.",al={"wer vergibt skulk rock-aufräumen","fraggar thundermantle"}},{q="Warum wollen die Wildhämmer Skulk Rock säubern lassen?",a="Die Horde hat ihre Stellungen um Skulk Rock aufgegeben, und Schlämme und Schleime haben sie überrannt. Die Wildhämmer haben Pläne für das Gebiet, doch zuerst muss der Befall eingedämmt werden.",al={"warum die schleime töten","wildhammer pläne skulk rock"}},{q="Welche Kreaturen leben bei Skulk Rock?",a="Grüne Schlämme und Jadeschleime haben die alten Stellungen der Horde bei Skulk Rock überrannt.",al={"skulk rock gegner","was ist bei skulk rock"}},{q="Warum erwähnt Fraggar Eisenschmiede?",a="Fraggar sagt, die Wildhämmer erinnern sich stärker an die Vergangenheit als ihre Brüder in Eisenschmiede. Er sagt, hier gewinnt man Freunde, indem man sich die Hände schmutzig macht.",al={"wildhammer eisenschmiede unterschied","fraggar eisenschmiede"}}},fp="19,173,21.348.0,19.97.0,29.100.0,47.172.0,35.80.0,36.147.0"}
P.entries["quest:2879"] = {n="Der Stock von Equinex",s="In den Ruinen von Rabenwind prüft Troyas Moonbreeze, ob sein Stock den Equinex Monolith öffnen kann. Ihr sammelt die Essenzen von vier Flammen, die noch immer zwischen den Ruinen brennen.",h="In den Ruinen von Rabenwind prüft Troyas Moonbreeze, ob sein Stock den Equinex Monolith öffnen kann.",kw={"byltan","traum-geäst","equinex monolith","feralas","imbel","lahassa","ruinen von rabenwind","samha","stock von equinex","troyas moonbreeze"},sec={{t="Ein Schlüssel zum Monolithen",b="Troyas Moonbreeze glaubt, sein Stock könnte der Stock von Equinex sein, ein Schlüssel zum Equinex Monolith in den Ruinen von Rabenwind. Dort brennen noch immer vier Flammen: Samha, Imbel, Byltan und Lahassa. Jede liefert eine Essenz. Ihr nutzt alle vier am Monolithen, um den Stock mit Energie zu erfüllen. Ist er wirklich der Schlüssel, wird sich der Monolith öffnen und ein heiliges Artefakt enthüllen."},{t="Am Stein",b="Der mit Energie erfüllte Stock ist kaum zu halten, während seine Macht Euch mit einem Grollen durchströmt. Ihr greift nach der kalten Oberfläche des Monolithen, und eine kleine Tür öffnet sich. Lichtstrahlen ergießen sich rings um den Stein, als Ihr nehmt, was darin liegt."}},faq={{q="Wo befindet sich der Equinex Monolith?",a="Der Equinex Monolith steht in den Ruinen von Rabenwind, westlich des Traum-Geästs auf dem Festland.",al={"standort des equinex monolith","wo ist der monolith","equinex monolith finden"}},{q="Welche vier Flammen brauche ich?",a="Die vier Flammen heißen Samha, Imbel, Byltan und Lahassa. Sie brennen noch immer in den Ruinen von Rabenwind, und Ihr sammelt die Essenz jeder einzelnen.",al={"vier flammen","flammennamen feralas","flammen von rabenwind"}},{q="Wozu dient der Stock von Equinex?",a="Troyas Moonbreeze sagt, der Stock von Equinex könnte ein Schlüssel zum Equinex Monolith sein, der ein heiliges Artefakt birgt.",al={"was bewirkt der stock","zweck des stocks von equinex","warum den stock mit energie erfüllen"}},{q="Wo erfülle ich den Stock mit Energie?",a="Ihr erfüllt den Stock neben dem Equinex Monolith mit Energie, indem Ihr die Essenzen aller vier Flammen nutzt.",al={"wo essenzen verwenden","wo den stock mit energie erfüllen"}}},fp="20,169,22.341.0,12.217.1,38.95.0,32.132.0,33.112.0,30.90.0"}
P.entries["quest:288"] = {n="Die Dritte Flotte",s="Vor der Tiefenwassertaverne trinkt Erster Maat Fitzsimmons gegen die Erinnerungen an die Dritte Flotte an. Er allein überlebte ihren Brand vor dem Sumpfland während des Zweiten Krieges.",h="Vor der Tiefenwassertaverne trinkt Erster Maat Fitzsimmons gegen die Erinnerungen an die Dritte Flotte an.",kw={"tiefenwassertaverne","doomed fleet","dragonmaw","fitzsimmons","kul tiras","hafen von menethil","rote drachen","dritte flotte","wave mistress","sumpfland"},ang={["faction:Alliance"]="Als Verteidiger der Allianz hört Ihr in Fitzsimmons' Bericht über die Wave Mistress, welche Narben die Drachenreiter der Horde in ganz Khaz Modan hinterließen.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass Grim Batol einen Schatten über Khaz Modan warf. In seinen Tiefen gezüchtete Drachen verwüsteten Zwergenlande und menschliche Verbündete gleichermaßen.",["race:Human"]="Als Mensch könnt Ihr Euch an die Vernichtung der Dritten Flotte als bitteres Zeugnis der Seeschlachten erinnern, die Kul Tiras und die Allianz gegen die Dragonmaw führten."},sec={{t="Die Trauer eines Seemanns",b="Erster Maat Fitzsimmons verbringt seine Tage vor der Tiefenwassertaverne im Hafen von Menethil. Ihn plagen ein Kater und Erinnerungen, die ihn nicht loslassen. Einst diente er an Bord der Wave Mistress, eines Linienschiffs unter dem Seefahrtsbanner von Kul Tiras. Nun greift er zu Zwergenmet, und ein weiterer Trunk mag ihn dazu bringen, von einem schrecklichen Gemetzel auf See zu erzählen."},{t="Feuer über den Wellen",b="Während des Zweiten Krieges segelte die Dritte Flotte an den Küsten von Khaz Modan entlang, als Feuer vom Himmel fiel. Der Clan der Dragonmaw hatte den roten Drachenschwarm bei Grim Batol unterjocht und entfesselte Drachenfeuer auf die ahnungslosen Kriegsschiffe. Fitzsimmons erinnert sich an hölzerne Rümpfe, die unter gewaltigen Flammen brannten, während ihre Besatzungen in die Tiefe gerissen wurden. Er allein überlebte und wurde an Land gespült. Seine gefallenen Brüder liegen in dem nassen Grab, das als Doomed Fleet bekannt ist."}},faq={{q="Wer ist Erster Maat Fitzsimmons?",a="Erster Maat Fitzsimmons ist ein alter Seemann, der vor der Tiefenwassertaverne im Hafen von Menethil trinkt, um seine seelischen Wunden zu betäuben. Einst diente er an Bord der Wave Mistress, eines Kriegsschiffs von Kul Tiras, und ist der einzige bekannte Überlebende der Vernichtung der Dritten Flotte.",al={"fitzsimmons","wer ist der betrunkene seemann","fitzsimmons taverne"}},{q="Was geschah mit der Dritten Flotte?",a="Während des Zweiten Krieges überfiel der Clan der Dragonmaw die Dritte Flotte von Kul Tiras vor der Küste des Sumpflands und verbrannte sie. Auf Drachen reitende Orcs ließen Feuer von oben herabregnen und schickten Schiffe und Seeleute auf den Meeresgrund.",al={"schicksal der dritten flotte","wie sank die flotte","kul tiras schiffe versenkt"}},{q="Warum griffen Drachen menschliche Schiffe an?",a="Während des Zweiten Krieges versklavte der Clan der Dragonmaw den roten Drachen Alexstrasza mit der Demon Soul im nahe gelegenen Grim Batol. Durch dunkle Zauberei gebunden, wurden die roten Drachen gezwungen, der Horde als Reittiere und Belagerungswaffen zu dienen.",al={"dragonmaw drachen","rote drachen sumpfland","warum orcs auf drachen"}},{q="Wo genau sanken die Schiffe?",a="Die verkohlten Wracks liegen auf dem Meeresgrund vor der Westküste des Sumpflands, nördlich vom Hafen von Menethil. Das Gebiet ist als Doomed Fleet in Erinnerung geblieben.",al={"wo ist die doomed fleet","schiffswracks fundort sumpfland","wracks der dritten flotte"}},{q="Welches Getränk möchte Fitzsimmons?",a="Fitzsimmons möchte einen Krug Zwergenmet, um seinen mörderischen Kater zu lindern und seine Zunge zu lösen. Der Gastwirt in der Tiefenwassertaverne verkauft ihn.",al={"fitzsimmons met","was will fitzsimmons","krug met"}},{q="Welchem Reich diente die Dritte Flotte?",a="Die Dritte Flotte diente Kul Tiras, einem Inselkönigreich, dessen mächtige Marine während des Zweiten Krieges das Rückgrat der Seestreitkräfte der Allianz bildete.",al={"gehört die dritte flotte zu stormwind","kul tiras flotte","wem gehörte die wave mistress"}}},fx={["03818f34"]={q="Warum möchte Erster Maat Fitzsimmons etwas zu trinken?",a="Fitzsimmons ist der einzige Überlebende eines schrecklichen Massakers, verfolgt von der Erinnerung an das Verbrennen seiner Flotte und leidet unter einem heftigen Kater. Sein Kopf hämmert so stark, dass er es nicht ertragen kann, ohne einen starken Drink, um den Schmerz zu dämpfen und seine Zunge zu lockern, von der Tragödie von The Third Fleet zu berichten. Ein Krug Met ist alles, was ihn zum Reden bringen wird.",al={"fitzsimmons motiv","warum will fitzsimmons met","warum fitzsimmons helfen"}},["53fbd504"]={q="Warum braucht Fitzsimmons Euch, um den Met zu holen?",a="Fitzsimmons ist ein gebrochener, mittelloser Überlebender, der vor der Taverne in Selbstmitleid und Qualen schwelgt. Geplagt von einem pochenden Kater und da er wahrscheinlich seinen letzten Kupfer ausgegeben hat, hat er weder die Mittel noch die Kraft, selbst zur Bar zu gehen, weshalb er vorbeiziehende Abenteurer um Wohltätigkeit anbetteln muss.",al={"warum kann fitzsimmons sein getränk nicht selbst kaufen","warum nach met fragen","fitzsimmons warum ich"}}},fp="15,166,16.342.0,19.450.0,30.241.0,33.197.0,39.218.0,34.141.0,33.148.0,38.147.0"}
P.entries["quest:2880"] = {n="Kopfgeld für Trollhalsketten",s="Am Nistgipfel bittet Euch Fraggar Thundermantle, ihm fünf Halsketten von Trollen aus dem Hinterland zu bringen.",h="Am Nistgipfel bittet Euch Fraggar Thundermantle, ihm fünf Halsketten von Trollen aus dem Hinterland zu...",kw={"nistgipfel","kopfgeld","fraggar thundermantle","hinterland","stammeshalskette von trollen","trolle","wildhammer"},sec={{t="Ansehen bei den Wildhämmern gewinnen",b="Fraggar Thundermantle vertraut Taten mehr als Worten. Die Wildhämmer unterstehen keiner Allianz, und wer ihre Freundschaft sucht, muss zuerst seinen Wert beweisen. Trolle, die durch die Hügel des Hinterlands streifen, tragen manchmal Stammeshalsketten. Bringt Fraggar am Nistgipfel fünf davon, und Ihr habt einen Anfang gemacht."}},faq={{q="Warum will Fraggar Thundermantle Trollhalsketten?",a="Fraggar beurteilt Leute nach ihren Taten, nicht nach ihren Worten. Fünf Trollhalsketten sind ein guter Anfang für alle, die die Freundschaft der Wildhämmer suchen.",al={"warum trollhalsketten","zweck des kopfgelds für trollhalsketten","warum will fraggar halsketten"}},{q="Sind die Wildhämmer Teil der Allianz?",a="Fraggar sagt, die Wildhämmer seien unabhängig und unterstünden keiner Allianz. Sie beurteilen Leute nach ihren Taten.",al={"gehören wildhämmer zur allianz","gehört nistgipfel zur allianz","zugehörigkeit der wildhämmer"}},{q="Wo sind Stammeshalsketten von Trollen zu finden?",a="Trolle, die durch die Hügel des Hinterlands streifen, tragen manchmal Stammeshalsketten bei sich.",al={"wo stammeshalskette von trollen bekommen","trollhalsketten fundort","wie trollhalsketten bekommen"}},{q="Zu wem bringe ich die Halsketten zurück?",a="Bringt die fünf Halsketten zu Fraggar Thundermantle am Nistgipfel.",al={"wer bekommt trollhalsketten","bei fraggar thundermantle abgeben","wo ist fraggar thundermantle"}}},fp="21,105,25.294.0,52.139.0,41.105.0,42.74.0,33.64.0"}
P.entries["quest:2881"] = {n="Kopfgeld für Trollhalsketten",s="Für Fraggar Thundermantle zählen Trollstammeshalsketten weiterhin in Fünfergruppen. Der Wildhammer hat bereits eine Lieferung von Euch angenommen, und das Angebot gilt weiterhin.",h="Für Fraggar Thundermantle zählen Trollstammeshalsketten weiterhin in Fünfergruppen.",kw={"fraggar thundermantle","hinterlands","stammeshalskette","kopfgeld für trollhalsketten","trolle","wildhammer"},sec={{t="Ein dauerhaftes Angebot",b="Fraggar Thundermantle nimmt weitere Trollstammeshalsketten gern entgegen, wann immer Ihr welche findet und Euch entscheidet, sie abzugeben. Er sagt, die Wildhammer werden für diejenigen kämpfen, die für sie kämpfen. Jede Lieferung muss fünf Halsketten umfassen."},{t="Fraggars Anerkennung",b="Fraggar Thundermantle freut sich, wenn Ihr ihm die Halsketten bringt. Für ihn beweisen sie Eure Bereitschaft, Euch die Hände schmutzig zu machen, eine Eigenschaft, die die Wildhammer schätzen."}},faq={{q="Wer will die Trollstammeshalsketten haben?",a="Fraggar Thundermantle spricht für die Wildhammer.",al={"wer vergibt dieses kopfgeld","fraggar thundermantles rolle","wer nimmt die halsketten"}},{q="Wie viele Trollstammeshalsketten werden benötigt?",a="Jeweils fünf. Fraggar zählt eine Lieferung erst, wenn sie fünf Halsketten umfasst.",al={"anzahl der halsketten","wie viele halsketten","voraussetzung für das kopfgeld"}},{q="Warum sammelt Fraggar Thundermantle diese Halsketten?",a="Fraggar betrachtet die Halsketten als Beweis dafür, dass Ihr bereit seid, für die Wildhammer zu kämpfen. Er sagt, sie werden für diejenigen kämpfen, die das tun.",al={"warum trollhalsketten","beweggrund der wildhammer","zweck des kopfgelds"}},{q="Was ging diesem Kopfgeld voraus?",a="Ihr habt das erste Kopfgeld für Trollhalsketten für Fraggar Thundermantle bereits abgeschlossen.",al={"vorausgesetzte quest","vorheriger schritt","vorheriges kopfgeld"}}},fp="21,164,16.213.0,18.159.1,37.49.0,43.73.0,55.130.0,29.80.0"}
P.entries["quest:289"] = {n="Die verfluchte Crew",s="Vor der Küste des Sumpflands sucht die verfluchte Crew die Schiffe heim, mit denen die Third Fleet von Kul Tiras sank. Erster Maat Fitzsimmons, der einzige Überlebende der Flotte, bittet Reisende, seine verlorenen Brüder zu befreien. Ein dunkles Relikt an Bord eines Wracks bindet die ertrunkenen Matrosen und Seesoldaten als rastlose Untote an ihre Schiffe.",h="Vor der Küste des Sumpflands sucht die verfluchte Crew die Schiffe heim, mit denen die Third Fleet von Kul...",kw={"verfluchte crew","verfluchter seesoldat","verfluchter matrose","fitzsimmons","kul tiras","menethil","snellig","schnupftabakdose","third fleet","sumpfland"},ang={["class:Paladin"]="Als Paladin könnt Ihr die unschuldigen Matrosen zur Ruhe betten und die frevelhafte Schändung tilgen, die ihnen angetan wurde. Bringt Licht in diese dunklen Gewässer.",["faction:Alliance"]="Als Reisender der Allianz teilt Ihr die ernste Pflicht, diese gequälten Kul Tiraner Matrosen zur Ruhe zu betten. Kul Tiras stellt der Großen Allianz seit Langem seine besten Matrosen zur Verfügung.",["race:Human"]="Als menschlicher Reisender fühlt Ihr Euch diesen gefallenen Matrosen vielleicht durch die gemeinsamen Seefahrtstraditionen mit Kul Tiras verbunden."},sec={{t="Eine rastlose Flotte",b="Die Third Fleet von Kul Tiras zerschellte an den zerklüfteten Ufern nördlich vom Hafen von Menethil. Allein Erster Maat Fitzsimmons erreichte lebend das Land. Seine Matrosenkameraden fanden unter den Wellen keinen Frieden. Als sie starben, band die Zauberei eines geheimnisvollen Schatzes tief in einem Schiffsrumpf ihre Seelen an die zerschlagenen Planken und verwehrte ihnen Ruhe."},{t="Gnade durch die Klinge",b="Erster Maat Fitzsimmons hört noch immer nachts in den Tavernen des Hafens von Menethil das Stöhnen und Weinen seiner einstigen Schiffskameraden. Er glaubt, dass er sie von ihren Qualen befreien kann, indem er ihre belebten Leichen niederstrecken lässt. Deshalb schickt er Reisende in die verrottenden, versunkenen Schiffskolosse, um die verfluchten Matrosen, erfahrenen Seesoldaten und seinen früheren Maatkameraden, Ersten Maat Snellig, zu töten. Er bittet sie, Snelligs persönliche Schnupftabakdose als Beweis dafür zurückzubringen, dass sein Freund zur Ruhe gebettet wurde."}},faq={{q="Wer war Erster Maat Snellig?",a="Erster Maat Snellig diente mit Erstem Maat Fitzsimmons an Bord der Third Fleet von Kul Tiras. Snellig ertrank mit der Besatzung, als die Flotte vor der nördlichen Küste des Sumpflands zerschellte. Ein bösartiges Relikt an Bord der Schiffe erweckte ihn als untoten Schrecken, und nun sucht er einen überfluteten Laderaum in einem Wrack heim.",al={"snellig","erster maat snellig","wer ist snellig"}},{q="Warum sind die Matrosen und Seesoldaten verflucht?",a="Fitzsimmons zufolge befand sich ein verborgener, bösartiger Schatz an Bord eines der Flottenschiffe. Als die Schiffe an der Küste zerschellten, banden die dunklen Energien des Artefakts die Geister der ertrunkenen Besatzung an ihre verrottenden Schiffsrümpfe. Sie können nicht ins Jenseits eingehen und leiden als Untote.",al={"warum sind sie untot","fluch der third fleet","ursache der verfluchten matrosen"}},{q="Wo liegen die gesunkenen Schiffe?",a="Die zerstörten Schiffe der Third Fleet liegen unter Wasser vor der nördlichen Küste des Sumpflands, nördlich vom Hafen von Menethil. Die verfluchte Crew streift über die Decks und durch die umliegenden Gewässer, während Snellig den geborstenen Rumpf des südlichen Schiffs heimsucht.",al={"wo sind die schiffe","lage der wracks","wo ist snellig"}},{q="Warum will Fitzsimmons Snelligs Schnupftabakdose?",a="Erster Maat Snellig bewahrte die Schnupftabakdose zu Lebzeiten als persönliches Andenken auf. Wer sie Fitzsimmons zurückbringt, beweist damit, dass sein verfluchter Kamerad aus seinem verrottenden Gefängnis unter den Wellen befreit wurde.",al={"snelligs schnupftabakdose","schnupftabakdose","warum schnupftabakdose"}},{q="Wer ist Erster Maat Fitzsimmons?",a="Erster Maat Fitzsimmons ist ein Kul Tiraner Matrose und der einzige bekannte lebende Überlebende der Third Fleet. Trauer und Schuldgefühle halten ihn im Hafen von Menethil fest, wo ihn Albträume von seinen ertrunkenen Brüdern heimsuchen, während er Reisende sucht, die ihr Leiden beenden.",al={"fitzsimmons","erster maat fitzsimmons"}},{q="Bricht das Töten der Besatzung tatsächlich den Fluch?",a="Die Matrosen und Seesoldaten niederzustrecken, verschafft ihren rastlosen Geistern vorübergehend Ruhe, bricht aber nicht den Zauber. Das geheimnisvolle Relikt, das zwischen den Wrackteilen verborgen liegt, bleibt die Ursache des Fluchs.",al={"ist der fluch aufgehoben","beendet das den fluch"}}},fx={["8e82e35b"]={q="Warum möchte Erster Maat Fitzsimmons, dass die The Cursed Crew getötet wird?",a="Fitzsimmons ist davon verfolgt, der einzige lebende Überlebende von The Third Fleet zu sein. Im Schlaf wird er von den todgeweihten Stöhnen seiner ertrunkenen Kameraden gequält, deren Seelen durch einen dunklen Schatz an die verrottenden Rümpfe gebunden bleiben. Er hofft, dass das Zur-Ruhe-Bringen ihrer wandelnden Leichen ihre Schreie verstummen lässt und der schreckliche Fluch, der auf ihnen lastet, gebrochen wird.",al={"warum die crew töten","fitzsimmons motiv","warum will fitzsimmons das"}},["7d36941a"]={q="Warum braucht Fitzsimmons Euch, anstatt selbst zu gehen?",a="Fitzsimmons ist ein alter, gebrochener Seemann, der vom Trauma des Überlebens des Schiffbruchs gezeichnet ist, der seine gesamte Flotte forderte. Er ertränkt seine Sorgen in der Taverne und hat weder die Kraft noch das Herz, sich selbst den wiederbelebten Leichen seiner früheren Kameraden zu stellen, und verlässt sich stattdessen auf fähige Abenteurer, um sich zu den Wracks zu begeben.",al={"warum braucht mich fitzsimmons","warum kann fitzsimmons nicht gehen","warum nicht die wachen von menethil"}}},fp="15,293,16.325.0,18.439.1,27.291.0,39.259.0,35.231.0,45.180.0,30.236.0,47.205.1"}
P.entries["quest:29"] = {n="Prüfung des Sees",s="In der Mondlichtung stellt sich ein Initiand der Prüfung des Sees, einer zeitlich begrenzten Prüfung von Schnelligkeit und Geschicklichkeit. Ihr taucht in den See von Elune'ara, um ein instabiles Schrein-Schmuckstück zu bergen, und eilt dann zum Schrein von Remulos, bevor es zerfällt. Ein Erfolg bringt Euch Tajarris Anerkennung ein und würdigt die Hingabe des Zirkels des Cenarius an das Gleichgewicht.",h="In der Mondlichtung stellt sich ein Initiand der Prüfung des Sees, einer zeitlich begrenzten Prüfung von...",kw={"zirkel des cenarius","see von elune'ara","mondlichtung","remulos","schrein-schmuckstück","schrein von remulos","tajarri","prüfung des sees"},ang={["class:Druid"]="Als Druide stellt Ihr Euch in der Mondlichtung einer Prüfung Eurer Schnelligkeit und Anpassungsfähigkeit. Der Übergangsritus ehrt Hüter Remulos."},sec={{t="Eine Prüfung der Geschicklichkeit",b="Die Beschützer der Mondlichtung beaufsichtigen diesen Ritus für Initianden. Ihr taucht in den See von Elune'ara, um ein empfindliches Schrein-Schmuckstück auf dem versunkenen Seegrund zu finden. Es beginnt zu zerfallen, sobald Ihr es bewegt, also braucht Ihr eine sichere Hand, scharfe Sinne und schnelle Schritte, um es über Land zu tragen, bevor seine Magie schwindet."},{t="Tribut an den Hüter",b="Sobald Ihr das Schmuckstück habt, müsst Ihr zum Schrein von Remulos im Nordwesten der Mondlichtung eilen. Das Monument ehrt Hüter Remulos, der den Zirkel des Cenarius bei der Bewahrung der Natur und des Gleichgewichts der Welt leitet. Das Schmuckstück dort zu aktivieren, würdigt die Bedeutung des Schreins für den Zirkel. Wächterin Tajarri begrüßt Initianden, die das Zeitlimit einhalten und die Konkurrenz hinter sich lassen."}},faq={{q="Was ist die Prüfung des Sees?",a="Die Prüfung des Sees stellt die Gewandtheit und Konzentration eines Initianden in der Mondlichtung auf die Probe. Ihr taucht in die kalten Tiefen des Sees von Elune'ara, um ein rasch zerfallendes Schrein-Schmuckstück zu bergen, und eilt dann durch den Zufluchtsort zum Schrein von Remulos, bevor seine Energie schwindet.",al={"was ist die prüfung des sees","zweck der prüfung des sees","was ist diese quest"}},{q="Wo liegt der Schrein von Remulos?",a="Der Schrein von Remulos steht im Nordwesten der Mondlichtung. Er ehrt Hüter Remulos, der den Zirkel des Cenarius leitet, und Wächterin Tajarri bewacht und pflegt ihn.",al={"wo ist der schrein von remulos","standort des schreins","remulos schrein mondlichtung"}},{q="Wer ist Tajarri?",a="Tajarri ist eine vertrauenswürdige Wächterin der Mondlichtung, die den Schrein von Remulos betreut. Sie beaufsichtigt die Prüfung des Sees und heißt Initianden willkommen, die das Schmuckstück bringen, um den Schrein zu ehren.",al={"wer ist tajarri","tajarri mondlichtung","schreinwächterin tajarri"}},{q="Was ist ein Schrein-Schmuckstück?",a="Ein Schrein-Schmuckstück ist eine Reliquie, die auf dem Grund des Sees von Elune'ara zu finden ist. Sobald es aus dem Wasser genommen wird, zerfällt es rasch, also muss sein Träger eilen, um es als Tribut am Schrein von Remulos zu aktivieren, bevor seine Energie schwindet.",al={"was ist ein schrein-schmuckstück","warum zerfällt das schmuckstück","zweck des schrein-schmuckstücks"}},{q="Warum wird Hüter Remulos an diesem Schrein geehrt?",a="Hüter Remulos ist ein verehrter Hüter des Hains, der den Zirkel des Cenarius bei der Bewahrung der Natur und der Wahrung des Gleichgewichts leitet. Der Schrein im Nordwesten der Mondlichtung ehrt seine Führung und seine Grundsätze.",al={"wer ist hüter remulos","remulos geschichte","warum remulos ehren"}},{q="Was bedeutet es, das Schmuckstück am Schrein darzubringen?",a="Das Schmuckstück am Schrein von Remulos zu aktivieren, würdigt das heilige Gleichgewicht, das der Zirkel des Cenarius wahrt, und erkennt die bleibende spirituelle Bedeutung des Schreins in der Mondlichtung an.",al={"was bewirkt die benutzung des schmuckstücks","warum das schmuckstück am schrein aktivieren"}}},fp="17,295,19.299.0,21.340.0,30.252.0,39.157.0,15.173.0,24.216.0,45.199.0,52.184.0"}
P.entries["quest:290"] = {n="Brechen des Fluchs",s="Erster Maat Fitzsimmons bittet Euch, seine gefallenen Kameraden von einem ruhelosen Fluch zu befreien. Er glaubt, ein Artefakt an Bord der zerstörten Intrepid binde sie, und der Geist von Kapitän Halyndor bewacht den Schlüssel zur Schatulle.",h="Erster Maat Fitzsimmons bittet Euch, seine gefallenen Kameraden von einem ruhelosen Fluch zu befreien.",kw={"kapitän halyndor","fitzsimmons","glorin stahlbraue","intrepid","brechen des fluchs","hafen von menethil","schatulle","third fleet","sumpfland"},ang={["class:Priest"]="Als Priester habt Ihr die geistliche Autorität, Leiden zu lindern und befleckte Relikte zu reinigen. Fitzsimmons vertraut den Inhalt der Schatulle der Priesterschaft zur Reinigung an.",["faction:Alliance"]="Als Streiter der Allianz ehrt Ihr die Seeleute, die der Allianz zu Lebzeiten dienten. Helft ihren gequälten Seelen, Ruhe zu finden, während Ihr durch den Hafen von Menethil reist."},sec={{t="Die Bürde eines Kapitäns",b="Erster Maat Fitzsimmons überlebte das Schicksal der Third Fleet, doch die Erinnerungen an seine Kameraden verfolgen ihn Tag und Nacht. Er glaubt, ein böser Gegenstand in der verschlossenen Schatulle der Intrepid hänge mit dem Untod zusammen, der seine Schiffskameraden gefangen hält. Der Geist von Kapitän Halyndor wacht über das Wrack und bewacht den Schlüssel zur Schatulle."},{t="Zugang zur Tiefe",b="Die zerbrochenen Schiffe der Third Fleet liegen vor der nördlichen Küste des Sumpflandes. Im gefluteten Rumpf der Intrepid befinden sich eine verschlossene Schatulle und das Relikt, das den Kern des Leids der Mannschaft bildet. An Deck bewacht Halyndors Geist den verrosteten Schlüssel. Nehmt ihn, betretet den gefluteten Rumpf und bergt das Artefakt, damit heilige Hände es reinigen können."}},faq={{q="Welches Schiff durchsucht Ihr während dieser Quest?",a="Ihr durchsucht die Intrepid, ein versunkenes Schiff der Third Fleet vor der nordwestlichen Küste des Sumpflandes.",al={"welches schiff","intrepid schiffswrack","wo ist die schatulle"}},{q="Wer ist Kapitän Halyndor?",a="Kapitän Halyndor befehligte die Intrepid. Sein ruheloser Geist spukt auf dem Deck des zerstörten Schiffes und bewacht den Schlüssel zu dessen Schatulle.",al={"wer ist halyndor","kapitän halyndor geschichte"}},{q="Warum will Erster Maat Fitzsimmons die Schatulle öffnen lassen?",a="Fitzsimmons glaubt, dass ein verfluchter Gegenstand in der Schatulle die Geister seiner Seefahrerkameraden in Qualen gefangen hält. Er will sie öffnen lassen, damit das Artefakt geborgen und gereinigt werden kann.",al={"fitzsimmons ziel","warum schatulle öffnen","zweck der quest"}},{q="Wo befindet sich die Schatulle der Intrepid?",a="Die Schatulle der Intrepid liegt unter Wasser im unteren Teil des Rumpfes. Ihr erreicht sie durch ein Loch in der Seite des Wracks unter den Wellen.",al={"standort der schatulle","wo ist die truhe","wie schatulle finden"}},{q="Wer kann den verfluchten Gegenstand reinigen, sobald er geborgen ist?",a="Fitzsimmons weist Euch an, den geborgenen Gegenstand zur Reinigung zu Glorin Stahlbraue zu bringen, einem zwergischen Priester im Hafen von Menethil.",al={"wer reinigt das relikt","wer ist glorin stahlbraue","wohin mit dem verfluchten gegenstand"}},{q="Was hat den Schiffbruch ursprünglich verursacht?",a="Während des Zweiten Krieges griffen rote Drachen unter der Kontrolle von Orcs die Third Fleet an und verbrannten und versenkten ihre Schiffe vor der Küste des Sumpflandes. Ein verfluchter Schatz an Bord verwehrt den ertrunkenen Mannschaften nun die Ruhe.",al={"wie sank die third fleet","ursache des untergangs der third fleet"}}},fx={["336b08f7"]={q="Wofür ist der Geldkassettenschlüssel der INTREPID?",a="Der Schlüssel gehörte Kapitän Halyndor und wird benötigt, um die Geldkassette der INTREPID im Wrack aufzuschließen. Darin befindet sich der verfluchte Gegenstand, der für die Verderbnis der Seeleute von The Third Fleet verantwortlich ist, und der geborgen werden muss, bevor er jemals gereinigt werden kann.",al={"geldkassettenschlüssel der intrepid","was öffnet der schlüssel","warum brauche ich den schlüssel"}},["1f8e42a3"]={q="Warum schickt Euch Erster Maat Fitzsimmons, anstatt selbst zu gehen?",a="Fitzsimmons ist tief traumatisiert und wird von Träumen seiner toten Crew und seines früheren Kommandanten heimgesucht. Von Schuldgefühlen und Angst erfüllt, kann er sich dem todgeweihten Wrack der INTREPID oder dem rachsüchtigen Geist von Kapitän Halyndor nicht selbst stellen.",al={"warum ich fitzsimmons","warum kann fitzsimmons das nicht tun","warum fitzsimmons euch braucht"}}},fp="17,204,18.297.0,20.314.1,46.101.0,24.128.0,58.167.0,42.131.0,55.126.0,45.193.0"}
P.entries["quest:2902"] = {n="Waldpfotennachforschung",s="In Camp Mojache vermutet Hadoken Swiftstrider, dass die Woodpaw-Gnolle schriftlichen Plänen folgen. Er schickt Euch nach Süden, um ihre Lager nach Schlachtplänen zu durchsuchen.",h="In Camp Mojache vermutet Hadoken Swiftstrider, dass die Woodpaw-Gnolle schriftlichen Plänen folgen.",kw={"schlachtkarte","schlachtpläne","camp mojache","feralas","gnolle","hadoken swiftstrider","woodpaw"},sec={{t="Die Suche nach Plänen",b="Nach Alpha Strike schickt Hadoken Swiftstrider Euch zurück zu den Woodpaw. Er bezweifelt, dass die Gnolle klug sind, doch ihre jüngsten Angriffe waren zu gut koordiniert, um Zufall zu sein. Er vermutet, dass sie ihre Strategie schriftlich festhalten. Wenn Ihr diese Aufzeichnungen findet, könnte er erfahren, was sie aufgestachelt hat. Deshalb bittet er Euch, die Lager zu durchsuchen und alles mitzubringen, was wie Schlachtpläne aussieht."},{t="Was die Karte zeigt",b="Die Karte liefert Hadoken die gesuchten Pläne. Pfeile durchziehen sie und könnten Truppenbewegungen kennzeichnen, doch die meisten weisen nach Süden, weg vom nördlich gelegenen Camp Mojache. An anderer Stelle ähnelt eine Zeichnung einem großen Insekt. Die Striche darunter könnten die Verluste der Gnolle durch unbekannte Käfer zählen."}},faq={{q="Wer schickt Euch los, um die Woodpaw-Gnolle zu untersuchen?",a="Hadoken Swiftstrider in Camp Mojache schickt Euch los, um die Woodpaw-Gnolle zu untersuchen.",al={"wer vergibt waldpfotennachforschung","questgeber waldpfotennachforschung"}},{q="Warum glaubt Hadoken, dass die Gnolle Schlachtpläne haben?",a="Die jüngsten Angriffe der Woodpaw waren zu gut koordiniert, um improvisiert zu sein. Hadoken erwartet eine schriftlich festgehaltene Strategie, die zeigen könnte, was sie aufgestachelt hat.",al={"warum haben gnolle pläne","strategie der woodpaw"}},{q="Wo befinden sich die Schlachtpläne?",a="Die Schlachtpläne befinden sich in den Lagern der Woodpaw südlich von Camp Mojache.",al={"wo sind die pläne der woodpaw","wo ist die schlachtkarte der woodpaw"}},{q="Was kam vor Waldpfotennachforschung?",a="Alpha Strike kommt unmittelbar vor dieser Suche.",al={"vorherige quest waldpfotennachforschung","voraussetzung der woodpaw-questreihe"}}},fp="21,153,18.373.0,18.259.1,48.81.0,54.151.0,35.64.0,39.44.0"}
P.entries["quest:2903"] = {n="Die Schlachtpläne",s="Ihr tragt die Woodpaw-Schlachtpläne nach Camp Mojache, wo Hadoken Swiftstrider herauszufinden hofft, was die Gnolle vorhaben.",h="Ihr tragt die Woodpaw-Schlachtpläne nach Camp Mojache, wo Hadoken Swiftstrider herauszufinden hofft, was die...",kw={"schlachtpläne","camp mojache","feralas","gnolle","hadoken swiftstrider","woodpaw"},sec={{t="Zurück nach Camp Mojache",b="Nach Woodpaw Investigation bringt Ihr die Woodpaw-Schlachtpläne zu Hadoken Swiftstrider in Camp Mojache zurück. Er braucht stichhaltige Beweise für die Absichten der Gnolle."},{t="Hadokens Deutung",b="Hadoken Swiftstrider sagt, die Pläne seien genau das, was sie gebraucht haben. Das meiste Gekritzel versteht er nicht, doch er hat genug Schlachtpläne gelesen, um zu erkennen, dass die Gnolle an zwei Fronten kämpfen. Eine Front ist Camp Mojache. Der Großteil ihrer Streitkräfte richtet sich gegen einen Feind im Süden. Hadoken spürt etwas Größeres hinter den Kämpfen und glaubt, dass sie herausfinden müssen, wer dieser zweite Feind ist."}},faq={{q="Wohin müssen diese Schlachtpläne gebracht werden?",a="Bringt die Pläne zu Hadoken Swiftstrider in Camp Mojache.",al={"wer bekommt die pläne","wo die schlachtpläne abgeben","schlachtpläne abgeben"}},{q="Was kam vor diesem Schritt?",a="Davor kam Woodpaw Investigation, als Ihr nach den Plänen der Gnolle gesucht habt.",al={"vorherige quest","was führt zu den schlachtplänen","voraussetzung für die schlachtpläne"}},{q="Woher stammen die Schlachtpläne?",a="Die Pläne gehören den Gnollen. Ihr habt sie während Woodpaw Investigation in Gnolllagern südlich von Camp Mojache gefunden.",al={"wer hat die karte erstellt","welche gnolle haben die pläne erstellt","herkunft der woodpaw-pläne"}}},fp="16,121,20.159.0,17.372.1,39.55.0,27.80.0,37.113.0"}
P.entries["quest:2904"] = {n="Eine schöne Bescherung",s="In Gnomeregan findet Ihr Kernobee nach einem Überfall der Dunkeleisenzwerge übel zugerichtet unter den Troggs. Seine Rettung bringt Nachricht von einer Bohrmaschine unter Dun Morogh, die nach Beutebucht überbracht werden muss.",h="In Gnomeregan findet Ihr Kernobee nach einem Überfall der Dunkeleisenzwerge übel zugerichtet unter den Troggs.",kw={"beutebucht","clockwerk run","dunkeleisen","gnomeregan","kernobee","scooty","super-bohrmaschine","tinkerwiz","troggs"},ang={["faction:Alliance"]="Als Mitglied der Allianz erfahrt Ihr, dass die Agenten von Emperor Thaurissan die Bemühungen der Allianz sabotieren, Gnomeregan zurückzugewinnen.",["profession:Engineering"]="Als Ingenieur mag es Euch beunruhigen, zu erfahren, dass Dunkeleisenmaschinisten unter der Erde eine gewaltige Super-Bohrmaschine bauen.",["race:Gnome"]="Als Gnom ist es Eure Ehrenpflicht, einen Überlebenden aus Gnomeregans verseuchten Tiefen zu retten. Dunkeleiseninfiltratoren und wilde Troggs bedrohen ihn."},sec={{t="Ein geschundener Überlebender",b="Ihr findet Kernobee in Gnomeregans Wohnbereich, verprügelt und benommen. Dunkeleisenzwerge haben den Goblin überfallen und ihn unter den wilden Troggs zurückgelassen. Ihr führt ihn durch die verseuchten Korridore in Richtung Sicherheit."},{t="Unterirdische Machenschaften",b="Kernobee bringt Nachricht von der Arbeit des Dunkeleisenclans an einer gewaltigen Super-Bohrmaschine unter Dun Morogh. Er flieht über das Meer nach Ratschet, um den Gobliningenieur Tinkerwiz zu warnen. Dann schickt er Euch nach Süden nach Beutebucht mit Neuigkeiten für den Gobliningenieur Scooty."}},faq={{q="Wer ist Kernobee?",a="Kernobee ist ein Goblin, den Ihr in Gnomeregan beinahe zu Tode geprügelt vorfindet. Dunkeleisenzwerge haben ihn überfallen und vor seiner Rettung unter den Troggs zurückgelassen.",al={"kernobee","wer ist kernobee"}},{q="Wohin muss Kernobee eskortiert werden?",a="Ihr führt Kernobee durch Gnomeregans feindselige Hallen zum Ausgang von Clockwerk Run und zu den oberen Eingangskorridoren.",al={"wohin muss kernobee","eskortziel","ausgang von clockwerk run"}},{q="Warum waren die Dunkeleisenzwerge beteiligt?",a="Die Dunkeleisenzwerge halfen dabei, eine gewaltige unterirdische Super-Bohrmaschine zu entwerfen und zu bauen. Kernobee entdeckte ihren Plan, bevor sie ihn überfielen.",al={"warum dunkeleisen","dunkeleisen super-bohrmaschine","dunkeleisen in gnomeregan"}},{q="Wohin geht Kernobee nach seiner Flucht?",a="Nachdem er sich in Sicherheit gebracht hat, reist Kernobee über das Meer nach Ratschet im Brachland, um Tinkerwiz vor der Beteiligung der Dunkeleisenzwerge an der unterirdischen Bohrmaschine zu warnen.",al={"wohin ging kernobee","kernobee ratschet","warnung an tinkerwiz"}},{q="Warum müsst Ihr Scooty in Beutebucht Bericht erstatten?",a="Scooty ist ein Gobliningenieur in Beutebucht, der mit Tinkerwiz an hochtechnischer Ausrüstung für den Untergrund und an Transpondernetzwerken arbeitet.",al={"warum scooty","abgabe in beutebucht","verbindung zu scooty"}},{q="Was hat das mit Robogenieur Thermaplugg zu tun?",a="Scooty weiß um die Bedrohung, die Robogenieur Thermaplugg in Gnomeregan darstellt. Wenn Ihr Kernobee helft, erhalten Abenteurer Unterstützung und Vorräte, um zurückzukehren und sich dem verräterischen Robogenieur zu stellen.",al={"verbindung zu thermaplugg","thermaplugg bekämpfen"}}},fx={["73352f2e"]={q="Warum muss Kernobee herauseskortiert werden?",a="Kernobee wurde von Dunkeleisenzwergen in einen Hinterhalt gelockt, fast zu Tode geprügelt und in einem Wohnbereich zurückgelassen, der von feindseligen Troggs überrannt wurde. Verletzt und tief in den zerstörten Hallen von Gnomeregan gefangen, kann er die Reise zum Ausgang nicht allein überleben. Entscheidend ist auch, dass er dringende Geheimdienstinformationen bei sich trägt: Er entdeckte, dass der Dunkeleisenzlan direkt an der Konstruktion einer riesigen Bohranlage beteiligt ist. Mit dem Leben davonzukommen ist seine einzige Chance, nach Ratschet zu reisen und seinen Partner Tinkerwiz zu warnen, bevor diese Maschinerie weiteres Unheil anrichtet.",al={"warum kernobee helfen","kernobee motiv","warum braucht kernobee hilfe"}},["9976ada5"]={q="Warum kann Kernobee Gnomeregan nicht alleine entkommen?",a="Kernobee ist kaum bei Bewusstsein, als Ihr ihn findet, nachdem er von seinen Dunkeleisenentführern schwer misshandelt wurde, bevor sie ihn in eine Grube voller Troggs warfen. Prellungen, unbewaffnet und bis aufs Äußerste geschwächt, hat er keine Hoffnung, sich an den verstrahlten Mutanten, den Konstrukten der Schurken und den wilden Troggs vorbeizukämpfen, die Clockwerk Run patrouillieren, ohne einen fähigen Abenteurer, der ihn beschützt.",al={"warum braucht kernobee euch","warum kann kernobee nicht kämpfen","warum ich kernobee"}}},fp="11,166,19.204.0,20.250.1,16.147.0,32.119.0,40.149.0,38.164.1,43.127.0,46.191.0"}
P.entries["quest:291"] = {n="Die Berichte",s="Von Kharanos aus berichtet Senir Weißbart Senator Barin Redstone in Eisenschmiede über die Bedrohung Dun Moroghs durch die Frostmanetrolle. Er bittet Euch, seinen Späher nicht namentlich zu nennen.",h="Von Kharanos aus berichtet Senir Weißbart Senator Barin Redstone in Eisenschmiede über die Bedrohung Dun...",kw={"barin redstone","zwergensenat","frostmane","high seat","eisenschmiede","kharanos","magni bronzebart","senir weißbart","die berichte"},ang={["faction:Alliance"]="Als Mitglied der Allianz lernt Ihr den Aufbau der Stadtverwaltung von Eisenschmiede und die Bürokratie kennen, die die Innenpolitik der Allianz prägt.",["race:Dwarf"]="Als Zwerg erlebt Ihr das Gleichgewicht zwischen König Magnis Krone und der parlamentarischen Macht des Zwergensenats, wenn Ihr die Depesche im High Seat überbringt."},sec={{t="Eine Depesche an die Hauptstadt",b="Der Bericht enthält Nachrichten aus dem Innersten der Höhle der Frostmähnen, wo die Trolle Dun Morogh bedrohen. Senir möchte, dass Ihr ihn direkt zu Barin Redstone bringt und den Späher aus den verschneiten Felsen nicht namentlich nennt."},{t="Spannungen im High Seat",b="Senator Barin Redstone wird zornig, als Senirs Bericht den königlichen Hof von Eisenschmiede erreicht. Ihn erzürnt, dass Senir sich auf König Magnis Autorität beruft, um seine Einsätze zu rechtfertigen. Sein Zorn offenbart den Unmut des Senats über die Erlasse des Königs und die in seinem Namen durchgeführten Feldeinsätze."}},faq={{q="Wer ist Senir Weißbart?",a="Senir Weißbart ist ein zwergischer Gebirgsjäger, der nahe Kharanos in Dun Morogh stationiert ist. Er leitet Erkundungen und militärische Aufklärung gegen Frostmanetrolle, die auf zwergische Siedlungen vorrücken.",al={"senir weißbart","wer vergibt die berichte","weißbart kharanos"}},{q="Wer ist Senator Barin Redstone?",a="Barin Redstone ist ein griesgrämiger, aristokratischer Zwergensenator, der im Thronsaal von Eisenschmiede nahe König Magni Bronzebart lebt. Einfache Bittsteller gehen ihm schnell auf die Nerven.",al={"barin redstone","wer ist der senator","redstone eisenschmiede"}},{q="Warum ist Senator Redstone wegen des Berichts zornig?",a="Senir warnt Euch, dass Senator Redstone griesgrämig ist. Warum der Senator zornig ist, erfahrt Ihr, wenn Ihr den Bericht überbringt.",al={"warum ist redstone wütend","warum schreit der senator","senat gegen magni"}},{q="Warum bittet Senir Weißbart darum, Eure Hilfe geheim zu halten?",a="Senir Weißbart bittet Euch, Eure Hilfe geheim zu halten, damit seine Vorgesetzten glauben, er habe die beschwerliche Erkundung selbst erledigt. Er will nicht zugeben, dass ein Abenteurer die Arbeit ausgeführt hat.",al={"warum beansprucht senir die anerkennung","weißbart hat die anerkennung gestohlen","senirs geheimnis"}},{q="Wo wird der Bericht abgegeben?",a="Ihr überbringt den Bericht Senator Barin Redstone im High Seat von Eisenschmiede, der großen Halle, in der König Magni Bronzebart Hof hält.",al={"wo die berichte abgeben","barin redstone standort","die berichte abgeben"}},{q="Was verrät diese Quest über die Politik von Eisenschmiede?",a="Bei der Übergabe des Berichts lernt Ihr den Senat von Eisenschmiede und die Beamten kennen, die Berichte aus den Grenzgebieten entgegennehmen. Redstones Reaktion gewährt einen Einblick in die Politik von Eisenschmiede.",al={"eisenschmiede regierung hintergrundgeschichte","zwergensenat hintergrundgeschichte","magni gegen senat"}}},fx={bde96c47={q="Warum braucht Senir Weißbart Euch, um den Bericht abzuliefern, anstatt es selbst zu tun?",a="Senir Weißbart bleibt in Dun Morogh stationiert, um die Feldoperationen gegen lokale Bedrohungen wie die Frostmähnentrolle zu beaufsichtigen. Noch wichtiger ist, dass er möchte, dass der Senat und seine Vorgesetzten glauben, er arbeite unermüdlich an der Front, wobei er Kurieraufgaben und die unangenehme Aufgabe, einem mürrischen Senator gegenüberzutreten, einem entbehrlichen Reisenden überlässt.",al={"warum mich mit bericht senden","warum liefert senir den bericht nicht ab","warum ich berichte"}}},fp="11,163,25.197.0,25.281.1,24.190.0,30.157.0,47.110.1,55.190.0,30.139.0,53.163.1"}
P.entries["quest:292"] = {n="Das Auge von Paleth",s="Fitzsimmons bittet Euch, das Auge von Paleth aus der gesunkenen Intrepid zu bergen. Bringt den verfluchten Edelstein dann zu Glorin Stahlbraue im Hafen von Menethil, wo der Zwergenpriester einen Weg sucht, seine Verderbnis zu tilgen.",h="Fitzsimmons bittet Euch, das Auge von Paleth aus der gesunkenen Intrepid zu bergen.",kw={"verfluchtes auge von paleth","auge von paleth","fitzsimmons","glorin stahlbraue","intrepid","hafen von menethil","third fleet","sumpfland"},ang={["class:Priest"]="Als Priester habt Ihr Grund zur Sorge, wenn ein heiliges Artefakt wie das Auge von Paleth entweiht wird. Seine Verderbnis berührt Euren Glauben an das Heilige Licht.",["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass die Vernichtung der Third Fleet den Hafen von Menethil schutzlos zurückließ. Ihre Überreste zu bergen, kann helfen, von verlorenen Kameraden Abschied zu nehmen.",["race:Dwarf"]="Als Zwerg teilt Ihr die Hingabe, mit der verlorene Relikte vor Khaz Modans Küsten zurückgewonnen werden. Geistliche aus Eisenschmiede wie Glorin Stahlbraue können Euch helfen."},sec={{t="Ein verderbtes Relikt",b="Unter den Wassern der Baradinbucht birgt die verschlossene Kassette der Intrepid eine geschwärzte Kugel. Das Auge von Paleth pulsiert unter Wasser, von heiligem Licht zu einer Quelle des Leids verzerrt. Seine Verderbnis verbindet es mit den ruhelosen Geistern und dem Unheil, das die Seeleute der Third Fleet ereilte."},{t="Die Priesterschaft aufsuchen",b="Glorin Stahlbraue untersucht das Relikt im Hafen von Menethil. Der Zwergenpriester des Heiligen Lichts ist fassungslos, dass ein so heiliger Gegenstand der Third Fleet gehörte. Er erkennt dessen unnatürliche Verderbnis und beginnt, Rituale vorzubereiten, um seinen dunklen Einfluss zu bannen."}},faq={{q="Was ist das Auge von Paleth?",a="Das Auge von Paleth ist ein uralter und mächtiger heiliger Edelstein, der gewöhnlich mit heiligen Energien verbunden ist. An Bord der Intrepid, eines gesunkenen Schiffs der Third Fleet, wurde es entstellt und verflucht und strahlt nun dunkle Magie aus.",al={"auge von paleth hintergrund","was ist paleth","verfluchtes auge von paleth"}},{q="Wo wurde das Auge geborgen?",a="Ihr bergt das Auge aus einer verschlossenen Kassette im überfluteten Wrack der Intrepid, direkt vor der Küste des Sumpflands.",al={"wo ist das auge zu finden","auge von paleth fundort","intrepid kassette"}},{q="Warum interessiert sich Glorin Stahlbraue für das Artefakt?",a="Glorin Stahlbraue ist ein Zwergenpriester, der im Hafen von Menethil stationiert ist. Sein Wissen um das Heilige Licht lässt ihn uralte Relikte erkennen und Rituale einleiten, um finstere Flüche zu brechen.",al={"wer ist glorin stahlbraue","warum stahlbraue"}},{q="Woher weiß Fitzsimmons vom Auge?",a="Fitzsimmons hat die Tragödie der Third Fleet überlebt, und sie lässt ihn noch immer nicht los. Er suchte Zuflucht in Menethils Taverne und wusste, dass ein dunkles Relikt im Wrack verborgen lag und seine gefallenen Schiffskameraden quälte.",al={"fitzsimmons verbindung","warum hat fitzsimmons mich geschickt"}},{q="Warum ist das Auge verflucht?",a="Die Verderbnis des Auges ist mit den übernatürlichen Todesfällen und den ruhelosen Untoten verbunden, die in den Schiffswracks der Third Fleet spuken. Es nahm während oder nach der Katastrophe, die die Flotte auf den Meeresgrund schickte, dunkle Energien auf.",al={"warum ist es verflucht","auge fluch ursprung"}},{q="Was geschieht, nachdem Ihr Glorin das Auge gegeben habt?",a="Glorin untersucht den verfluchten Edelstein und erkennt, dass er nicht verderbt bleiben darf. Er weist Euch an, das Relikt von seinem verderblichen Einfluss zu reinigen.",al={"nächste quest","was mit dem auge tun"}}},fp="17,199,16.272.0,22.247.1,26.191.0,28.110.0,50.174.0,40.197.0,22.215.0,44.131.1"}
P.entries["quest:2922"] = {n="Rettet Techbots Hirn!",s="Tinkmaster Overspark schickt Euch für „Rettet Techbots Hirn!“ nach Gnomeregan, um Techbots Speicherkern zu bergen. Die Maschine half einst Forschern, doch Strahlung erfüllte die Stadt, und ein Stromstoß bei ihrem Fall polarisierte ihr Gehirn und machte sie gewalttätig. Overspark hofft, mithilfe des Kerns den Schaden rückgängig machen und seine Schöpfung wiederherstellen zu können.",h="Tinkmaster Overspark schickt Euch für „Rettet Techbots Hirn!“ nach Gnomeregan, um Techbots Speicherkern zu...",kw={"gnomeregan","speicherkern","negatronisch","overspark","positronisch","techbot","tüftlerstadt"},ang={["faction:Alliance"]="Als Mitglied der Allianz unterstützt Ihr die gnomischen Flüchtlinge, die in Eisenschmiede Zuflucht gefunden haben, indem Ihr verlorene Technologie aus Gnomeregans verseuchtem Randgebiet bergt.",["profession:Engineering"]="Als Ingenieur erkennt Ihr an Techbots Wechsel vom positronischen zum negatronischen Zustand, wie eine Katastrophe komplexe Rechenmatrizen verzerren kann.",["race:Gnome"]="Als Gnom wisst Ihr, dass Gnomeregan Eure Heimatstadt war. Techbot zeigt, wie ihr Verlust selbst die herausragendsten geistigen Schöpfungen der Stadt beschädigt hat."},sec={{t="Ein umgekehrter Verstand",b="Bevor Gnomeregan fiel, unterstützte Techbot Forscher mit seinen Geräten und seinem umfassenden technischen Wissen. Tinkmaster Overspark entwarf den mechanischen Assistenten, dessen eingebaute Gerätschaften ihn zu einem Wunderwerk gnomischen Erfindungsreichtums machten. Dann brachte die Trogg-Invasion Chaos, und giftige Strahlung erfüllte die Stadt. Ein unkontrollierter Stromstoß erschütterte Techbots empfindliches Innenleben und polarisierte sein positronisches Gehirn in einen instabilen negatronischen Zustand."},{t="Bergungsaktion",b="Tinkmaster Overspark braucht Euch, um Techbots Kern zu bergen, denn die Maschine irrt nun rasend durch Gnomeregans verseuchte Hallen und greift jeden in Sichtweite an. Overspark weigert sich, seinen geschätzten Assistenten als Schrott aufzugeben. Er bittet Euch, die Maschine zu finden, ihren Speicherkern aus dem Metallgehäuse zu entfernen und ihn nach Eisenschmiede zu bringen. Mithilfe des Kerns hofft er, die Polarisierung zu verstehen und Techbots Verstand zu reparieren."}},faq={{q="Wer ist Techbot?",a="Techbot ist ein mechanischer Assistent, den Tinkmaster Overspark entworfen hat. Bevor Gnomeregan fiel, half er dem Tinkmaster und dessen Mitarbeitern mit seinem umfassenden Wissen und seinen eingebauten Gerätschaften.",al={"was ist techbot","techbots geschichte","overspark techbot"}},{q="Warum wurde Techbot feindselig?",a="Ein verirrter elektrischer Funke erschütterte Techbots positronisches Gehirn beim Fall von Gnomeregan. Der Schlag kehrte seine neuronale Ausrichtung in einen negatronischen Zustand um und verwandelte seine Hilfsbereitschaft in Gewalttätigkeit.",al={"warum ist techbot wahnsinnig","was ist mit techbot passiert","techbots polarisierung"}},{q="Wo ist Techbot zu finden?",a="Techbot durchstreift Gnomeregans äußere Korridore und Aufmarschhallen, jenseits des Randgebiets, in dem verbannte Gnome und zwergische Expeditionstruppen operieren.",al={"wo ist techbot","techbots standort","techbot finden"}},{q="Wer vergibt diese Quest?",a="Tinkmaster Overspark erteilt Euch den Auftrag in der Tüftlerstadt in Eisenschmiede. Dort beaufsichtigt er Bergungsarbeiten und Forschung für High Tinker Gelbin Mekkadrill.",al={"wer startet rettet techbots hirn","oversparks standort"}},{q="Kann Techbot wirklich repariert werden?",a="Tinkmaster Overspark glaubt, dass Techbots Speicherkern ihm helfen wird, die Ursache der negatronischen Polarisierung zu finden und die Maschine wieder funktionsfähig zu machen.",al={"ist techbot repariert","lässt sich techbot reparieren","überlebt techbot"}},{q="Was geschieht nach der Rückgabe des Speicherkerns?",a="Sobald Overspark den Kern erhält, beginnt er mit den Vorbereitungen, die umgekehrten Schaltkreise zu zerlegen und neu zu konfigurieren. Die richtigen Werkzeuge in seiner vollgestellten Werkstatt zu finden, ist eine Herausforderung für sich.",al={"techbot questabschluss","techbots kern abgeben"}}},fx={e9c625cc={q="Warum möchte Tinkmaster Overspark, dass Techbots Gehirn gerettet wird?",a="Techbot ist Tinkmaster Oversparks wertvollste Schöpfung, die ihm und seinen Mit-Erfindern einst mit einem riesigen Archiv an Wissen und praktischen Gizmos diente. Als Gnomeregan fiel, polarisierte ein irrender elektrischer Schlag das positronische Gehirn des Automaten in einen negatronischen Zustand, was ihn in den Wahnsinn trieb. Overspark weigert sich, seine Schöpfung aufzugeben und hofft, dass das Studium des Kerns es ihm ermöglichen wird, den Schaden rückgängig zu machen und seinen Assistenten wiederherzustellen.",al={"overspark motiv","warum techbot retten","warum will overspark techbot"}},["6f8a4042"]={q="Wofür ist Techbots Speicherkern?",a="Der Speicherkern beherbergt Techbots digitalisierten Geist und sein angesammeltes Wissen. Da sich das positronische Gehirn des Automaten während des Falls von Gnomeregan umkehrte, ist das Extrahieren dieser Komponente der einzige Weg, die Polaritätsverschiebung zu untersuchen und zu versuchen, den mechanischen Assistenten umzuprogrammieren oder wieder aufzubauen.",al={"techbots speicherkern","wofür ist der speicherkern"}}},fp="21,341,15.420.0,17.407.0,15.180.0,31.187.0,27.146.0,21.136.0,30.153.0,45.182.1"}
P.entries["quest:2923"] = {n="Tüftlermeister Oberfunks",s="In Sturmwind hört Bruder Sarno, dass Techbot ausgefallen ist und Tüftlermeister Oberfunks in Eisenschmiede trauert. Er schickt Abenteurer der Allianz nach Tüftlerstadt, wo Oberfunks um Hilfe bittet, Techbots Speicherkern aus Gnomeregan zu bergen.",h="In Sturmwind hört Bruder Sarno, dass Techbot ausgefallen ist und Tüftlermeister Oberfunks in Eisenschmiede...",kw={"gnomeregan","eisenschmiede","oberfunks","sarno","techbot","tüftlerstadt","tüftlermeister"},ang={["faction:Alliance"]="Als Mitglied der Allianz stärkt Ihr die Bande zwischen Sturmwind und den Königreichen der Zwerge und Gnome, indem Ihr den vertriebenen Gnomen in Tüftlerstadt helft.",["profession:Engineering"]="Als Ingenieur könnt Ihr die neuesten Errungenschaften gnomischen Erfindergeists kennenlernen, indem Ihr Oberfunks' außer Kontrolle geratene Schöpfungen untersucht.",["race:Gnome"]="Als Gnom bewahrt Ihr mit jeder geretteten Schöpfung und jedem geborgenen Speicherkern ein Stück Eurer gefallenen Heimat vor Strahlung und Troggs."},sec={{t="Ein Hilferuf aus der Kathedrale",b="Bruder Sarno kümmert sich in Sturmwind um Reisende und berichtet von Schwierigkeiten unter den gnomischen Flüchtlingen. Tüftlermeister Oberfunks, einer der Köpfe hinter Gnomeregans Wundern, trauert über Techbots Verderbnis. Der mechanische Diener half den Tüftlern einst treu. Dann verfiel die Stadt zu Ruinen."},{t="Nach Tüftlerstadt",b="Ihr nehmt die Tiefenbahn von Sturmwind nach Tüftlerstadt in Eisenschmiede. Dort sucht Oberfunks Abenteurer, die bereit sind, in Gnomeregans verstrahlten Hallen zu helfen. Er bittet sie, die Überreste von Techbots Fähigkeiten zu retten, bevor das Konstrukt irreparablen Schaden anrichtet."}},faq={{q="Wer ist Tüftlermeister Oberfunks?",a="Tüftlermeister Oberfunks ist ein gnomischer Ingenieur, der gnomische Ingenieurskunst lehrt. Er ist in Tüftlerstadt in Eisenschmiede und koordiniert die Bemühungen, Gnomeregan zurückzuerobern und versprengte gnomische Technologie aus der zerstörten Hauptstadt zu retten.",al={"oberfunks","wer ist oberfunks","tüftlermeister oberfunks"}},{q="Wer vergibt diese Quest?",a="Bruder Sarno, ein menschlicher Kleriker in Sturmwind, schickt Euch, den Gnomen in Eisenschmiede zu helfen.",al={"questgeber","wo beginnt die quest tüftlermeister oberfunks"}},{q="Was ist Techbot?",a="Techbot ist eine mechanische Schöpfung von Tüftlermeister Oberfunks. Einst diente er gnomischen Ingenieuren als hilfreiches Werkzeug, doch nach Gnomeregans Fall hatte er eine Fehlfunktion und geriet in der verstrahlten Stadt außer Kontrolle.",al={"techbot","was ist mit techbot passiert"}},{q="Wo ist Tüftlermeister Oberfunks zu finden?",a="Tüftlermeister Oberfunks ist in Tüftlerstadt, dem gnomischen Viertel im Osten von Eisenschmiede, zwischen anderen geflüchteten Tüftlern und experimentellen Maschinen.",al={"oberfunks standort","wo ist oberfunks"}},{q="Was folgt nach dem Gespräch mit Oberfunks?",a="Nachdem Ihr mit Oberfunks gesprochen habt, bittet er Euch, Gnomeregan zu betreten, Techbot zu deaktivieren und seinen Speicherkern zu bergen, damit er wiederhergestellt werden kann.",al={"nächste quest","techbots gehirn retten"}},{q="Warum interessiert sich die Allianz für die defekte Maschine eines Erfinders?",a="Die Allianz kümmert sich um die vertriebenen Gnome, und außer Kontrolle geratene Automaten in Gnomeregan bedrohen Expeditionen zur Rückeroberung der unterirdischen Hauptstadt oder zur Bewachung von Dun Moroghs Grenzen.",al={"warum sich um techbot kümmern","techbots bedeutung"}}},fx={["9c70ad2e"]={q="Warum schickt Euch Bruder Sarno zu Tinkmaster Overspark?",a="Bruder Sarno erinnert sich an Techbot als einen hilfreichen, sanften Automaten, der den Gnomen treu diente, bevor Gnomeregan in Chaos versank. Dass Overspark über die Fehlfunktion seiner Schöpfung verstört ist, beunruhigt den heiligen Mann. In der Hoffnung, dass die Maschine noch gerettet werden kann, anstatt verrotten oder zerstört zu werden, leitet Sarno mitfühlende Abenteurer zur Tüftlerstadt weiter, damit der verzweifelte Tinkmaster die Hilfe bekommt, die er dringend benötigt.",al={"warum kümmert sich bruder sarno","bruder sarno motiv","warum zu overspark senden"}}},fp="20,235,25.293.0,14.259.0,28.211.0,22.91.0,16.197.0,40.151.0,41.136.0,63.172.0"}
P.entries["quest:2924"] = {n="Grundlegende Artifixe",s="In Eisenschmiede fehlen Klockmort Spannerspan die Bauteile für seine Experimente. Die Gnome im Exil flohen während der Trogginvasion und der Strahlenkatastrophe aus Gnomeregan und ließen Grundlegende Artifixe in den unteren Hallen zurück.",h="In Eisenschmiede fehlen Klockmort Spannerspan die Bauteile für seine Experimente.",kw={"artifix-extrapolator","grundlegende artifixe","gnomeregan","gnomische ingenieurskunst","eisenschmiede","klockmort spannerspan","tüftlerstadt"},ang={["faction:Alliance"]="Als Mitglied der Allianz stärkt Ihr die Ingenieurskunst der Allianz in Eisenschmiede, indem Ihr den verbannten Gnomen helft, ihre verlorene Technologie zurückzugewinnen.",["profession:Engineering"]="Als Ingenieur wisst Ihr, wie viel Arbeit wegen eines einzigen fehlenden Bauteils stillstehen kann. Diese Bauteile zeugen vom Können der Ingenieure Gnomeregans vor dem Fall der Stadt.",["race:Gnome"]="Als Gnom helft Ihr durch die Bergung dieser Bauteile, die Handwerkskunst und den Erfindergeist Eures Volkes im Exil in Eisenschmiede zu bewahren."},sec={{t="Beim Exodus vergessen",b="Als Troggs Gnomeregan überrannten und Strahlung seine Korridore erfüllte, flohen die Gnome mit dem, was sie gerade noch erreichen konnten. Grundlegende Artifixe blieben zurück. Diese spezialisierten mechanischen Bauteile funktionieren in nahezu jedem Gerät und sind bei Tüftlern und Handwerkern begehrt. Meistertüftler Klockmort Spannerspan lebt nun in Tüftlerstadt in Eisenschmiede und kann seine neuen Experimente ohne einen Vorrat davon nicht fortsetzen."},{t="Die Extrapolatoren erkunden",b="Tief in Gnomeregan liegen die Bauteile in schweren, dampfbetriebenen Behältern, den sogenannten Artifix-Extrapolatoren. Um sie zu erreichen, durchquert Ihr verstrahlte Hallen, in denen mutierte Lepragnome, fehlfunktionierende Verteidigungsautomaten und wilde Troggs umherstreifen. Klockmort braucht zwölf Bauteile, um seine Arbeit fortzusetzen und den gnomischen Erfindergeist auch im Exil voranzutreiben."}},faq={{q="Was ist ein Grundlegendes Artifix?",a="Ein Grundlegendes Artifix ist ein von gnomischen Ingenieuren gefertigtes mechanisches Bauteil, das in nahezu jedem Gerät funktioniert. Tüftler und Schmiede schätzen diese Teile als Bausteine für komplexe Apparaturen und experimentelle Maschinen.",al={"was sind grundlegende artifixe","grundlegendes artifix","was ist das"}},{q="Wer vergibt die Quest Grundlegende Artifixe?",a="Klockmort Spannerspan, ein gnomischer Ingenieur in Tüftlerstadt in Eisenschmiede, bittet um die Bauteile.",al={"questgeber","wer vergibt die quest","wo gibt es grundlegende artifixe"}},{q="Wo findet man die Grundlegenden Artifixe in Gnomeregan?",a="Die Grundlegenden Artifixe lagern tief in Gnomeregan in Artifix-Extrapolatoren, die über die unteren Hallen verteilt sind. Das sind hohe, dampfbetriebene Lagerschränke.",al={"wo sind sie","fundort der extrapolatoren","wie findet man artifixe"}},{q="Warum wurden sie in Gnomeregan zurückgelassen?",a="Troggs drangen in Gnomeregan ein, und Strahlung erfüllte die Stadt. Bei der plötzlichen Evakuierung ließen die Gnome Vorräte an Grundlegenden Artifixen in den unteren Werkstätten zurück.",al={"warum zurückgelassen","warum sind sie in gnomeregan","geschichte der artifixe"}},{q="Wofür braucht Klockmort sie?",a="Klockmort Spannerspan braucht die Bauteile für komplexe Experimente, die er in seiner Werkstatt in Eisenschmiede vorbereitet.",al={"warum will klockmort sie","klockmorts plan"}},{q="Ist Klockmort's Essentials eine Voraussetzung für diese Quest?",a="Klockmort's Essentials macht Euch mit Klockmort bekannt und weist Euch den Weg zu seiner Werkstatt. Ihr könnt diesen Auftrag annehmen, ohne diese Quest abzuschließen.",al={"voraussetzung","klockmort's essentials erforderlich"}}},fx={["41f0ee2b"]={q="Warum braucht Klockmort externe Abenteurer, um Gnomeregan zu betreten?",a="Gnomeregan ist keine funktionierende Stadt mehr – es ist ein tödliches, verstrahltes Kriegsgebiet, das von Troggs und wahnsinnigen Lepragnomen überrannt wird. Gnomische Tüftler wie Klockmort Spannerspan sind Forscher, keine Frontsoldaten, und die überlebenden Gnome in der Tüftlerstadt sind Flüchtlinge, die von der Gastfreundschaft der Zwerge leben, anstatt eine Invasionsarmee zu sein. Das Vorstoßen in die tiefsten, gefährlichsten Sektoren der zerstörten Stadt erfordert erfahrene Abenteurer, die in der Lage sind, sich durch Wellen feindseliger Mutanten zu kämpfen, um die Lagercontainer zu erreichen.",al={"warum mich senden","warum abenteurer","warum kann klockmort sie nicht holen"}}},fp="21,215,23.375.0,25.343.0,32.217.0,42.94.0,56.169.0,40.160.0,34.109.0,60.136.0"}
P.entries["quest:2925"] = {n="Klockmorts Grundlagen",s="In Darnassus trägt Mathiel Klockmort Spannerspans dringende Bitte über das Meer. An seinen Posten gebunden, bittet er Reisende der Allianz, seinen Gnomenfreund in Eisenschmiede aufzusuchen.",h="In Darnassus trägt Mathiel Klockmort Spannerspans dringende Bitte über das Meer.",kw={"grundlegende artifixe","gnomeregan","eisenschmiede","klockmort spannerspan","klockmorts grundlagen","lepragnome","mathiel","tinkertown"},ang={["faction:Alliance"]="Als Reisender der Allianz tragt Ihr Mathiels Bitte von Darnassus zu Klockmort in Eisenschmiede. Nachtelfenlande und Zwergenhallen vereinen sich zur gemeinsamen Verteidigung.",["race:Gnome"]="Als Gnom wisst Ihr, dass jeder Ruf nach Tinkertown den anhaltenden Kampf unterstützt, Eure verlorene Heimat Gnomeregan zurückzuerobern."},sec={{t="Ein Ruf über Kontinente",b="Von der Terrasse der Krieger in Darnassus schickt Mathiel Nachricht nach Dun Morogh. Klockmort Spannerspan braucht mutige Verbündete für ein Unterfangen in Gnomeregan, doch Mathiel kann seinen Posten nicht verlassen, um dorthin zu reisen. Also bittet er fähige Reisende der Allianz, die durch Darnassus kommen, die Reise an seiner statt anzutreten."},{t="Der Weg nach Tinkertown",b="Klockmort Spannerspan arbeitet in Tinkertown, dem Viertel von Eisenschmiede für Gnome, die aus ihrer unterirdischen Stadt vertrieben wurden. Er plant, lebenswichtige Maschinen aus den verseuchten Korridoren von Gnomeregan zu bergen. Mathiels Empfehlung führt Euch zu Klockmorts Werkstatt, wo er Hilfe braucht, um das Zurückgelassene zurückzuholen."}},faq={{q="Wer vergibt die Quest Klockmorts Grundlagen?",a="Der Aufruf kommt von Mathiel. Der Nachtelf kann seinen Posten nicht verlassen, um nach Eisenschmiede zu reisen, und bittet daher vertrauenswürdige Reisende der Allianz, dem Hilferuf seines langjährigen Freundes Klockmort Spannerspan zu folgen.",al={"questgeber","wer startet klockmorts grundlagen","mathiels quest"}},{q="Wo finde ich Klockmort Spannerspan?",a="Ihr findet Klockmort Spannerspan in Tinkertown, dem Gnomenviertel von Eisenschmiede. Gnome, die aus ihrer verlorenen Heimat vertrieben wurden, haben dort Werkstätten und Gerätschaften eingerichtet.",al={"wo ist klockmort","klockmorts standort","klockmort spannerspan eisenschmiede"}},{q="Warum braucht Klockmort Hilfe in Gnomeregan?",a="Klockmort braucht Hilfe dabei, unverzichtbare mechanische Bauteile aus Gnomeregan zu bergen. Giftiger Niederschlag hat die Stadt verseucht, und in ihren Ruinen hausen Troggs, wahnsinnige Lepragnome und außer Kontrolle geratene Automaten.",al={"was will klockmort","warum die mission nach gnomeregan","klockmorts absicht"}},{q="Ist diese Quest erforderlich, um Gnomeregan zu betreten?",a="Nein. Mathiels Aufruf führt Euch zu Klockmort Spannerspan, doch Ihr könnt ihn auch ohne diese Empfehlung in Eisenschmiede ansprechen und seine Aufträge annehmen.",al={"ist diese quest pflicht","voraussetzung für gnomeregan","klockmorts grundlagen überspringen"}},{q="Welche Quest folgt auf Klockmorts Grundlagen?",a="Nachdem Ihr mit Klockmort Spannerspan gesprochen habt, verweist er Euch auf „Grundlegende Artifixe“. Diese Quest führt Euch tief nach Gnomeregan hinein.",al={"nächste quest","folgequest","grundlegende artifixe folgequest"}},{q="Warum möchte Mathiel einem Gnom in Eisenschmiede helfen?",a="Mathiel und Klockmort sind seit Langem persönlich befreundet. Obwohl Mathiel weit entfernt stationiert ist und seinen Posten nicht verlassen kann, sucht er jemanden Vertrauenswürdigen, der seinem Freund hilft.",al={"mathiels verbindung","warum kümmert sich mathiel darum","mathiel und klockmort"}}},fx={b4ad922f={q="Warum bittet Euch Mathiel darum, zu gehen, anstatt selbst zu reisen?",a="Mathiel ist durch seine Pflicht an seinen Posten in Darnassus gebunden und kann nicht über das Meer nach Dun Morogh reisen. Obwohl es ihm das Herz bricht, seinem Freund Klockmort nicht direkt helfen zu können, muss er sich auf einen fähigen Abenteurer verlassen, der in Richtung Eisenschmiede reist, um den Ruf stattdessen zu beantworten.",al={"warum kann mathiel nicht","warum mathiel sendet mich","warum hilft mathiel nicht klockmort"}}},fp="22,166,24.294.0,22.296.0,43.175.0,38.152.0,43.184.0,43.150.0,42.121.0,58.162.0"}
P.entries["quest:2926"] = {n="Gnogaine",s="In Kharanos schickt Ozzie Wechselvolt Abenteurer nach Gnomeregan, um radioaktiven Niederschlag zu sammeln. Er hofft, ein Heilmittel für die lepragestrickten Gnome herzustellen, doch das Gebräu könnte auch ein starkes Getränk werden.",h="In Kharanos schickt Ozzie Wechselvolt Abenteurer nach Gnomeregan, um radioaktiven Niederschlag zu sammeln.",kw={"gnoarn","gnogaine","gnomeregan","grünes leuchten","verstrahlter trogg","kharanos","lepragestrickter gnom","ozzie wechselvolt","phiole","strahlung"},ang={["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass die Verseuchung Gnomeregans ganz Dun Morogh bedroht. Den radioaktiven Niederschlag zu verstehen oder einzudämmen, ist für die Sicherheit der Region von Bedeutung.",["profession:Engineering"]="Als Ingenieur erlebt Ihr gnomische Feldforschung in Aktion: Unbehandelte radioaktive Abwässer werden in abschirmenden bleiernen Phiolen gesammelt.",["race:Gnome"]="Als verbannter Gnom wisst Ihr, wie verzweifelt Euer Volk nach einem Heilmittel für seine verstrahlten Brüder sucht. Selbst Ozzies wilde Experimente sind einen Versuch wert."},sec={{t="Heilmittel oder Cocktail",b="Seit dem Fall von Gnomeregan versuchen Flüchtlinge wie Gnoarn, die eindringenden Troggs zu töten und die Krankheit rückgängig zu machen, die ihre Verwandten verändert hat. Ozzie Wechselvolt und sein Partner Razzle Flinkspross verfolgen in ihrer Werkstatt in Kharanos einen anderen Weg. Ozzie sagt, sie versuchen, ein Heilmittel für die lepragestrickten Gnome herzustellen. Ihre Rezeptur könnte stattdessen zu sehr starkem Rum werden."},{t="Das Leuchten ernten",b="Ozzie und Razzle brauchen giftige Rückstände aus dem Herzen der Katastrophe. Ozzie gibt Abenteurern eine bleierne Sammelphiole und schickt sie zu den aufgebrochenen Tunneln von Gnomeregan. Dort streifen verstrahlte Invasoren und verstrahlte Plünderer umher, Troggs, die von ausgetretenen Abfällen durchtränkt sind. Die Phiole braucht ihr grünes Leuchten."},{t="Haare und große Hoffnungen",b="Mit einer vollen Phiole grünen Leuchtens bereitet Ozzie einen Versuch am lebenden Testobjekt vor. Er hofft, das Gebräu werde einem gefangenen lepragestrickten Gnom Gesundheit und Verstand zurückgeben. Außerdem hofft er, die Mischung aus radioaktivem Niederschlag könnte seine Kahlköpfigkeit heilen."}},faq={{q="Wer bietet die Quest Gnogaine an?",a="Ozzie Wechselvolt, ein gnomischer Tüftler in Kharanos, bietet diese Arbeit an.",al={"wer vergibt gnogaine","gnogaine questgeber","ozzie wechselvolt quest"}},{q="Was muss ich für diese Quest sammeln?",a="Benutzt eine Leere bleierne Sammelphiole bei leuchtenden verstrahlten Invasoren oder verstrahlten Plünderern, um radioaktiven Niederschlag zu sammeln, bis die Phiole voll ist.",al={"gnogaine questziel","was für gnogaine sammeln","volle bleierne sammelphiole"}},{q="Wo finde ich die verstrahlten Troggs?",a="Ihr findet die verstrahlten Troggs in den äußeren Eingangshöhlen und verwinkelten Hallen, die zum Instanzportal von Gnomeregan führen. Ihr könnt sie erreichen, ohne den Dungeon zu betreten.",al={"wo sind verstrahlte troggs","gnogaine troggs fundort","verstrahlter invasor fundort"}},{q="Muss ich vor der Annahme dieser Quest „The Day After“ abschließen?",a="Nein. Ozzie bietet diese Quest unabhängig von The Day After an, auch wenn jene Geschichte mit der Lage in Kharanos verbunden ist und darauf hinführt.",al={"ist the day after erforderlich","gnogaine voraussetzung"}},{q="Was will Ozzie mit dem radioaktiven Niederschlag erreichen?",a="Ozzie und Razzle versuchen, ein Heilmittel für lepragestrickte Gnome herzustellen, doch Ozzie gibt zu, dass aus dem Gebräu hochprozentiger Rum werden könnte.",al={"warum will ozzie strahlung","wozu dient gnogaine"}},{q="Welche Quest folgt auf Gnogaine?",a="Eine volle Phiole führt zu The Only Cure is More Green Glow, einer Quest, die Euch tiefer nach Gnomeregan schickt.",al={"gnogaine folgequest","was folgt auf gnogaine"}}},fx={["28ada800"]={q="Wofür ist die Volle bleierne Sammelphiole?",a="Die Phiole ist mit Blei abgeschirmt, um den gefährlichen, leuchtenden radioaktiven Niederschlag, der von Troggs aus der Umgebung von Gnomeregan extrahiert wurde, sicher zu lagern und zu transportieren. Ozzie Wechselvolt und Razzle Flinkspross benötigen diese konzentrierte radioaktive Materie als lebenswichtige Zutat für ihre experimentelle Mixtur, von der sie hoffen, dass sie entweder ihren befallenen, gefangenen Lepragnom heilt, einen außergewöhnlich starken Rum braut oder vielleicht Ozzies Haarwuchs wieder anregt.",al={"nutzung der vollen bleiernen sammelphiole","warum bleierne phiole","zweck der bleiernen sammelphiole"}},dfd2dab8={q="Was sind die verstrahlten Troggs in Gnomeregan?",a="Die Troggs brachen ursprünglich tief unter Gnomeregan hervor und überrannten das technische Wunderwerk einer Stadt. In einem verzweifelten Versuch, die Invasion auszurotten, fluteten Hochtüftler Mekkatorque und seine Berater die unteren Korridore mit giftiger Strahlung. Anstatt auszusterben, überlebten viele Troggs und mutierten zu bösartigen, verstrahlten Invasoren und Plünderern, die nun vor einem kränklichen grünen, radioaktiven Leuchten strotzen.",al={"verstrahlte invasoren","verstrahlte plünderer","warum sind troggs verstrahlt"}}},fp="8,183,20.360.0,19.298.0,19.200.1,30.65.0,41.146.0,39.164.0,63.128.0,64.118.0,28.95.0"}
P.entries["quest:2927"] = {n="Der Tag danach",s="In Eisenschmiede und Kharanos suchen Gnomeregans Überlebende nach einer Antwort auf den Untergang ihrer Stadt. Gnoarn schickt Reisende zu Ozzie Wechselvolt, der die Verseuchung untersucht und hofft, eine Lösung zu finden.",h="In Eisenschmiede und Kharanos suchen Gnomeregans Überlebende nach einer Antwort auf den Untergang ihrer Stadt.",kw={"gnoarn","gnomefro","gnomeregan","kharanos","ozzie wechselvolt","strahlungsleck","der tag danach","troggs"},ang={["faction:Alliance"]="Als Held der Allianz helft Ihr den gnomischen Denkern Dun Moroghs, die bizarre biochemische Katastrophe einzudämmen, die das Bergreich bedroht.",["profession:Engineering"]="Als Ingenieur seht Ihr, wie Ozzie Wechselvolt Ideen erprobt, während gnomische Tüftler einer außer Kontrolle geratenen technischen Katastrophe entgegentreten.",["race:Gnome"]="Als Gnom kennt Ihr Gnoarns Klage. In ihr klingen die Tragik, der eigenwillige Stolz und die bittere Rachsucht von Flüchtlingen mit, die aus ihrer Hauptstadt vertrieben wurden."},sec={{t="Ein tragischer Verlust",b="In Eisenschmiedes Tüftlerstadt trauert Gnoarn um Gnomeregan und den Verlust seines Gnomefros. Eindringende Troggs eroberten die mechanische Stadt, und giftiger Niederschlag raubte ihm seine geliebte Mähne. Wut auf die Troggs und die Hoffnung, die Stadt zurückzuerobern, bewegen ihn dazu, mitfühlende Reisende zu Kollegen zu schicken, die retten können, was übrig ist."},{t="Der Weg nach Kharanos",b="In Kharanos haben erfinderische Gnome begonnen, sich dem radioaktiven Niederschlag zu stellen. Gnoarn schickt Reisende zu Ozzie Wechselvolt, der mit seinem Partner Razzle Flinkspross zusammenarbeitet. Ozzie erinnert sich an die Katastrophe, als Gnoarns Haare büschelweise ausfielen und Wahnsinn und Rachedurst die Oberhand gewannen. Nun untersucht Ozzie die Verseuchung in der verschneiten Stadt und setzt seine Ingenieurskunst ein, um ein Gegenmittel zu finden."}},faq={{q="Wer ist Gnoarn?",a="Gnoarn ist ein gnomischer Flüchtling in Tüftlerstadt in Eisenschmiede. Die eindringenden Troggs und die Katastrophe durch das Ablassen radioaktiver Abfälle haben ihn verbittert, und besonders der plötzliche Verlust seines einst stolzen Gnomefros erschüttert ihn.",al={"gnoarn","kahler gnom","wer vergibt der tag danach"}},{q="Warum schickt Gnoarn Euch zu Ozzie Wechselvolt?",a="Gnoarn hofft, dass Gnomeregan noch gerettet werden kann. Ozzie Wechselvolt und sein Partner Razzle Flinkspross sind in Kharanos, untersuchen die giftige Strahlung, die der Stadt anhaftet, und versuchen, ein Heilmittel zu entwickeln.",al={"warum zu ozzie gehen","ozzie wechselvolt quest","kharanos ingenieur"}},{q="Was ist Gnomeregan widerfahren, dass es dazu kam?",a="Während einer gewaltigen Trogginvasion unter der Stadt wurde Hochtüftler Gelbin Mekkadrill überredet, radioaktiven Giftmüll in die unteren Hallen abzulassen, um die Troggs zu vernichten. Der Plan scheiterte. Unzählige Gnome wurden getötet oder mutierten, Gnomeregan wurde unbewohnbar, und die Troggs überlebten.",al={"was ist mit gnomeregan passiert","warum ist gnomeregan verstrahlt","trogginvasion"}},{q="Wohin führt diese Questreihe nach der Ankunft bei Ozzie?",a="Nachdem Ihr Euch bei Ozzie gemeldet habt, bittet er Euch, radioaktiven Niederschlag von verstrahlten Troggs vor Gnomeregan zu sammeln. Er wird experimentelle Mischungen testen, die ihn neutralisieren sollen.",al={"der tag danach folgequest","was kommt nach der tag danach","nächste quest"}}},fx={b3abdd6a={q="Warum möchte Gnoarn, dass dies getan wird?",a="Gnoarn wird von persönlicher Wut und hartnäckiger Hoffnung angetrieben. Der radioaktive Niederschlag, der Gnomeregan ruinierte, raubte ihm auch seinen ganzen Stolz und seine Freude: das einzige Gnomfro in ganz Azeroth. Verbittert über seine Glatze und brennend vor Rache gegen die einfallenden Troggs, weigert er sich, seine Heimat aufzugeben. Er glaubt, dass es noch eine Chance gibt, das Desaster rückgängig zu machen und die Stadt zurückzuerobern, wenn er fähige Abenteurer zu Ozzie Wechselvolt schickt.",al={"gnoarns motiv","warum gnoarn helfen","warum kümmert sich gnoarn"}}},fp="13,196,13.310.0,20.381.0,14.200.0,45.194.0,42.273.0,54.170.0"}
P.entries["quest:2928"] = {n="Gyrobohrmatische Exkavation",s="Im Zwergendistrikt von Sturmwind macht Shoni die Schtille Tunnelbohrmaschinen für Dun Morogh bereit. Ihr fehlen Teile, deshalb schickt sie Euch nach Gnomeregan, um sie aus abtrünnigen Automaten zu bergen.",h="Im Zwergendistrikt von Sturmwind macht Shoni die Schtille Tunnelbohrmaschinen für Dun Morogh bereit.",kw={"dun morogh","der zwergendistrikt","maschinen der exkavation","gnomeregan","gnomische ingenieurskunst","gyrobohrmatisch","robomechanische gedärme","shoni die schtille"},ang={["faction:Alliance"]="Wenn Ihr als Mitglied der Allianz den Gnomen in Sturmwind beim Vorbereiten ihrer Grabmaschinen helft, stärkt Ihr die Bande zwischen ihren menschlichen Gastgebern und den im Exil lebenden Überlebenden, die ihr Erbe zurückgewinnen wollen.",["profession:Engineering"]="Wenn Ihr als Ingenieur präzise Uhrwerkinnereien aus Gnomeregans gefallenen Dienern ausbaut, erhaltet Ihr eine praktische Lektion in gnomischer Konstruktion und der Reparatur schwerer Maschinen.",["race:Gnome"]="Als Gnom bringt Ihr mit jedem geborgenen Bauteil Shonis unterirdische Flotte näher an die Einsatzbereitschaft. Von Sturmwind aus lebt der Traum von Rückeroberung und industriellem Wiederaufbau weiter."},sec={{t="Eine Flotte braucht Gedärme",b="Hunderte Maschinen der gyrobohrmatischen Exkavation warten im Zwergendistrikt darauf, einsatzbereit gemacht zu werden. Gnomische Ingenieure helfen dort ihren vertriebenen Verwandten. Die Maschinen sollen Menschen und Vorräte unterirdisch befördern, doch diese gewaltigen Geräte können ohne die mechanischen Teile, die Shoni fehlen, nicht arbeiten."},{t="Bergung in der gefallenen Stadt",b="Gnomeregan lieferte einst gnomische Spitzentechnologie. In den zerstörten Hallen und nahen Tunneln stehen noch immer Maschinen, deren Bergung sich lohnt, obwohl fehlerhafte Verteidigungsbots, mechanische Wachen und Uhrwerk-Arbeiter unkontrolliert umherstreifen. Shoni schickt Euch in die gefallene Stadt, um zwei Dutzend Bündel robomechanische Gedärme zu beschaffen und in die Länder der Menschen zurückzubringen."},{t="Ein gewaltiges Unterfangen",b="Zwei Dutzend Bündel mechanischer Gedärme liefern genug Schrott, um eine Maschine der Exkavation zu reparieren. Shoni muss noch immer fast vierhundert Maschinen vorbereiten, deshalb bleibt der unterirdische Massentransport ein langsames Unterfangen. Jede funktionierende Maschine ist ein kleiner Schritt, um den Boden zurückzugewinnen, der beim Fall von Gnomeregan verloren ging."}},faq={{q="Was ist eine Maschine der gyrobohrmatischen Exkavation?",a="Eine Maschine der gyrobohrmatischen Exkavation ist ein schweres gnomisches Tunnelbohrgerät, auch Maulwurfmaschine genannt, das graben und Menschen oder Vorräte unterirdisch befördern soll. Shoni die Schtille bereitet eine Flotte für den Einsatz in Dun Morogh vor.",al={"gyrobohrmatische exkavation","was ist eine maschine der exkavation","gnomenbohrer"}},{q="Wer ist Shoni die Schtille?",a="Shoni die Schtille ist eine gnomische Ingenieurin im Zwergendistrikt von Sturmwind. Sie ist unverblümt und fordernd und bereitet Hunderte mechanische Grabmaschinen vor.",al={"shoni die schtille","shoni","wer ist shoni"}},{q="Warum braucht Shoni ausgerechnet Teile aus Gnomeregan?",a="Gnomeregan lieferte einst gnomische Spitzentechnologie, und in seinen verfallenen Hallen stehen außer Kontrolle geratene Automaten, Uhrwerkdiener und Verteidigungsmaschinen. Die Versorgungslinien der städtischen Fertigung sind unterbrochen, deshalb bieten diese abtrünnigen Maschinen passende gnomische Ersatzteile.",al={"warum teile aus gnomeregan","warum robotergedärme","bergung in gnomeregan"}},{q="Wo findet man robomechanische Gedärme?",a="Robomechanische Gedärme lassen sich aus mechanischen Wachen, Uhrwerkkonstrukten und anderen feindlichen Maschinen in Gnomeregans zerstörter Anlage und den oberen Tunnelzugängen bergen.",al={"robomechanische gedärme","wo gedärme beschaffen","mechanische gedärme gnomeregan"}},{q="Ist Shonis Flotte mit der Reparatur einer Maschine fertig?",a="Nein. Zwei Dutzend Bündel mechanischer Gedärme reichen aus, um eine Bohrmaschine zu reparieren. Shoni sagt, dass sie noch dreihundertachtundneunzig Maschinen der Exkavation vor sich hat.",al={"wie viele maschinen der exkavation","shonis flottengröße","wie viele bohrmaschinen"}},{q="Warum wird eine Flotte von Grabmaschinen für Dun Morogh vorbereitet?",a="Dun Morogh ist die angestammte Heimat der Gnome und der Standort ihrer gefallenen Hauptstadt. Schwere Tunnelbohrgeräte können beim Graben und Wegräumen von Trümmern helfen und Arbeiten in den schneebedeckten Bergregionen unterstützen.",al={"flotte nach dun morogh","warum dun morogh","zweck der grabmaschinen"}}},fx={b2dc5b24={q="Wofür werden die Robo-Mechanical Guts verwendet?",a="Shoni die Schtille benötigt sie als geborgene interne Komponenten, um ihre Flotte von Gyrodrillmatic Excavationators zu reparieren. Die komplexe Mechanik dieser unterirdischen Tunnelbohrfahrzeuge erfordert Präzisionszahnräder, Verkabelung und Aktuatoren, die in Sturmwind nur schwer von Grund auf neu geschmiedet werden können. Indem sie die funktionierenden Innereien aus den autonomen Uhrwerkmaschinen entfernt, die in Gnomeregan umherstreifen, kann sie die wichtigen Ersatzteile bergen, die benötigt werden, um ihre stillgelegten Bohranlagen wieder in Betrieb zu nehmen.",al={"wofür sind robo-mechanical guts","nutzung von robo-mechanical guts","shonis nutzung von guts"}},["1cb24930"]={q="Wogegen kämpft Ihr in Gnomeregan für Shoni?",a="Ihr werdet ausgesandt, um die abtrünnigen Bots und Mechs zu demontieren, die durch die verstrahlten Hallen und Außenbezirke von Gnomeregan wandern. Als die unterirdische Hauptstadt der Gnome der Trogg-Invasion und dem radioaktiven Niederschlag zum Opfer fiel, funktionierten zahllose automatisierte Verteidigungssysteme und Versorgungsapparaturen nicht mehr und wurden gegenüber Außenstehenden feindselig. Shoni sieht in diesen verlassenen, umherstreifenden Automaten nicht nur Gefahren, sondern ein offenes Feld an Schrott, das nur darauf wartet, geplündert zu werden.",al={"gegen wen kämpfe ich für shoni","gnomeregan ziele guts","welche maschinen haben guts"}},["33a01105"]={q="Warum muss Shoni, dass Ihr die Teile sammelt, anstatt selbst zu gehen?",a="Shoni ist eine Ingenieurin, die im Zwergendistrikt von Sturmwind stationiert ist und damit beschäftigt ist, Maschinen zu warten und die Montage einer riesigen Ausgrabungsflotte zu beaufsichtigen. Tief in eine verstrahlte, von Troggs verseuchte Ruine vorzudringen, die von tödlichen Uhrwerk-Wächtern überrannt wurde, erfordert einen bewaffneten Abenteurer, der bereit ist, sich durch gefährliche Korridore zu kämpfen. Sie bleibt zurück, um die Bergung zu inspizieren und die Anlagen zu reparieren, sobald Komponenten eintreffen.",al={"warum schickt sie mich für guts","warum geht shoni nicht selbst","warum ich shoni quest"}}},fp="30,178,23.272.0,26.332.0,24.290.0,40.208.0,25.146.0,55.250.0,41.172.0,45.115.0,57.182.0"}
P.entries["quest:2929"] = {n="The Grand Betrayal",s="Hochschrauber Mekkatorque bittet Euch, Robogenieur Thermaplugg anzugreifen, der ihn und das Volk der Gnome verraten hat. Thermapluggs Herrschaft hält die Gnome davon ab, Gnomeregan zurückzuerobern.",h="Hochschrauber Mekkatorque bittet Euch, Robogenieur Thermaplugg anzugreifen, der ihn und das Volk der Gnome...",kw={"verrat","gnomeregan","gnome","hochschrauber mekkatorque","robogenieur thermaplugg","gnomeregan zurückerobern","der große verrat"},ang={["race:Gnome"]="Als Gnom betrifft Euch Mekkatorques Ruf: Euer Volk hat seine Heimat verloren und kämpft darum, Gnomeregan zurückzuerobern."},sec={{t="Mekkatorques Bitte",b="Hochschrauber Mekkatorque sucht Eure Hilfe im Kampf darum, Gnomeregan wieder unter die Kontrolle der Gnome zu bringen. Er vertraute Robogenieur Thermaplugg, doch Thermaplugg verriet ihn und das Volk der Gnome. Nun sind die Gnome vertrieben, und Thermaplugg herrscht über ihre Heimat. Mekkatorque bittet Euch, den Verräter zu Fall zu bringen, damit ihre Pläne zur Rückeroberung der Stadt vorankommen."},{t="Der Anspruch auf die Stadt",b="Robogenieur Thermaplugg ist tot. Mekkatorque sagt, die Gnome seien der Rückeroberung Gnomeregans damit einen Schritt näher."}},faq={{q="Wer hat die Gnome verraten?",a="Robogenieur Thermaplugg verriet Hochschrauber Mekkatorque und das Volk der Gnome.",al={"thermapluggs verrat","wer verriet die gnome"}},{q="Warum sind die Gnome vertrieben?",a="Mekkatorque sagt, Thermapluggs Verrat habe die Gnome aus Gnomeregan vertrieben und Thermaplugg die Herrschaft übertragen.",al={"vertriebene gnome","warum gnomeregan verlassen"}},{q="Wer bittet um Hilfe gegen Thermaplugg?",a="Hochschrauber Mekkatorque bittet Euch, Robogenieur Thermaplugg zu töten.",al={"mekkatorque bittet","wer will thermaplugg tot sehen"}},{q="Was will Mekkatorque für Gnomeregan?",a="Mekkatorque und die Gnome wollen Gnomeregan wieder unter ihre Kontrolle bringen.",al={"gnomeregan zurückerobern","pläne für die gnomenstadt"}}},fp="18,173,20.349.0,18.102.1,24.78.0,29.110.0,38.63.0,42.69.0"}
P.entries["quest:293"] = {n="Die Reinigung des Auges",s="Im Sumpfland schickt Die Reinigung des Auges Abenteurer mit einer verfluchten Kugel nach Süden nach Sturmwind, wo sie Hilfe suchen. Nachdem sie das Auge von Paleth geborgen haben, suchen sie Erzbischof Benedictus auf, um seinen anhaltenden Makel zu tilgen.",h="Im Sumpfland schickt Die Reinigung des Auges Abenteurer mit einer verfluchten Kugel nach Süden nach...",kw={"erzbischof benedictus","kathedrale des lichts","die reinigung des auges","verfluchtes auge von paleth","auge von paleth","glorin stahlbraue","sturmwind","sumpfland"},ang={["class:Paladin"]="Paladine betrachten es als feierliche Pflicht, heilige Relikte aus dunklen Sümpfen zurückzuholen. Die Verderbnis des Auges ist ein Frevel, der in Sturmwinds geweihten Hallen getilgt werden muss.",["class:Priest"]="Für Priester des Heiligen Lichts zeigt das Verfluchte Auge von Paleth, wie Verzweiflung heilige Schöpfungen verderben kann. Es bedarf der Läuterung durch Erzbischof Benedictus, um es zu reinigen.",["faction:Alliance"]="Die zwergischen Außenposten des Sumpflands und Sturmwinds geistliche Anführer arbeiten durch ihren gemeinsamen Glauben zusammen und verbinden so die Königreiche der Allianz."},sec={{t="Ein beflecktes Relikt",b="Das aus den Marschen geborgene Auge von Paleth birgt kein heiliges Licht. Schatten haften daran, ebenso wie die Trauer und das Trauma jener Tragödie, bei der es verloren ging. Glorin Stahlbraue, ein Zwerg, erkennt die Macht der Kugel. Doch ihm fehlt die göttliche Kunst, einen so schweren Fluch aufzuheben."},{t="Reise zur Kathedrale",b="Menschliche Priester des Heiligen Lichts schufen einst die Augen von Paleth, daher weiß allein ihr höchster Orden, wie sich die Entweihung rückgängig machen lässt. Glorin schickt Abenteurer mit der verdunkelten Kugel nach Süden nach Sturmwind, zu Erzbischof Benedictus, dem Anführer der Kirche des Heiligen Lichts. Benedictus weiß, welche Gefahr es birgt, ein solches Relikt ungereinigt zu lassen. Er nimmt sich der Aufgabe an, sein heiliges Licht wiederherzustellen."}},faq={{q="Was ist das Auge von Paleth?",a="Die Augen von Paleth sind heilige Kugeln, die menschliche Priester schufen, damit sie in heiligem Glanz erstrahlen. Unbefleckt steht ihre Macht im Einklang mit dem Heiligen Licht. Verderbt werden ihre Energien unberechenbar und gefährlich.",al={"auge von paleth hintergrund","was ist diese kugel","was ist das auge von paleth"}},{q="Warum kann Glorin Stahlbraue das Auge nicht selbst reinigen?",a="Glorin Stahlbraue kann das Auge nicht reinigen, weil ihm die liturgische Kunst fehlt, sein dunkles Leiden zu bannen. Menschliche Priester des Heiligen Lichts schufen das Relikt, daher erfordert die Reinigung seiner Verderbnis die Autorität dieser Tradition.",al={"warum nach sturmwind geschickt","glorin reinigung","warum benedictus"}},{q="Wer ist Erzbischof Benedictus?",a="Erzbischof Benedictus ist der ehrwürdige Anführer der Kirche des Heiligen Lichts. Er lebt in Sturmwinds Kathedrale des Lichts und leitet die Allianz in Glaubensfragen.",al={"wer ist benedictus","erzbischof benedictus","sturmwind erzbischof"}},{q="Warum wird das Auge als befleckt oder trauervoll beschrieben?",a="Erzbischof Benedictus sagt, die Kugel sei Zeuge einer großen Tragödie im Sumpfland gewesen. Mit der Zeit nahm sie diese Qual auf, und ihre anhaltende Trauer wurde zu einem Fluch, der ihre Macht verzerrte.",al={"warum ist es verflucht","auge von paleth tragödie","verfluchtes auge von paleth"}},{q="Was geschieht, sobald Benedictus die Kugel erhält?",a="Benedictus erklärt sich bereit, die Kugel zu reinigen. Die Augen von Paleth sollen hell erstrahlen, und ihr Makel bringt allen in ihrer Nähe schwere geistige und körperliche Gefahr.",al={"reinigt benedictus es","auge von paleth ausgang"}},{q="Wo befindet sich die Kathedrale des Lichts?",a="Die Kathedrale des Lichts steht am Kathedralenplatz im nördlichen Bezirk von Sturmwind. Erzbischof Benedictus steht am Hauptaltar im Herzen des Heiligtums.",al={"wo ist die kathedrale des lichts","kathedrale des lichts standort","benedictus finden"}}},fx={["6f168d84"]={q="Warum möchte Glorin Stahlbraue das Auge von Paleth gereinigt haben?",a="Glorin erkennt, dass das verfluchte Auge von Paleth ein äußerst gefährliches heiliges Relikt ist. Von menschlichen Priestern des das Heilige Licht geschaffen, um hell zu leuchten, wird seine Magie gefährlich und verdirbt, wenn sie durch Tragödien und dunkle Macht befleckt wird. Da Zwergenhandwerk und seine eigenen Fähigkeiten ein solches spirituelles Leiden nicht aufheben können, besteht er darauf, dass es nach Sturmwind gebracht wird, bevor seine Verderbnis Euch oder dem umliegenden Land weiteren Schaden zufügt.",al={"warum auge von paleth reinigen","glorin stahlbraues motiv","warum auge nach sturmwind senden"}}},fp="17,203,15.267.0,24.379.0,26.194.0,51.224.0,29.168.0,48.180.0,46.160.0,40.167.0"}
P.entries["quest:2930"] = {n="Datenrettung",s="Mechanikermeister Castpipe schickt Euch nach Gnomeregan, um die Aufzeichnungen der Stadt zu bergen. Troggs und Strahlung vertrieben die Gnome aus der Stadt, doch die Lochograph-Terminals bewachen ihre Archive noch immer hinter mehreren Freigabestufen.",h="Mechanikermeister Castpipe schickt Euch nach Gnomeregan, um die Aufzeichnungen der Stadt zu bergen.",kw={"castpipe","datenrettung","engineering labs","gnomeregan","matrix-lochograph","prismalochkarte","lochkarte","tüftlerstadt","train depot"},ang={["faction:Alliance"]="Als Mitglied der Allianz unterstützt Ihr die vertriebene gnomische Regierung in Eisenschmiede, indem Ihr Castpipe helft. Eure Hilfe stärkt den Zusammenhalt und die technologischen Fähigkeiten der Großen Allianz.",["profession:Engineering"]="Als Ingenieur könnt Ihr untersuchen, wie das Matrix-Lochograph-Netzwerk Daten speichert und ausgeklügelte Freigabemechanismen nutzt, die vom Tinkers' Court entwickelt wurden.",["race:Gnome"]="Als Gnom helft Ihr, das Erbe Eures Volkes zurückzugewinnen, indem Ihr Gnomeregans Daten bergt. Jede geborgene Lochkarte bewahrt den Erfindergeist Eurer Stadt vor Troggs und Strahlung."},sec={{t="Verlorene Archive im Untergrund",b="Troggs und Strahlung vertrieben Gnomeregans Bewohner aus der Stadt, und Jahrhunderte an Forschung, Bauplänen und städtischen Aufzeichnungen blieben zurück. Matrix-Lochograph-Terminals säumen noch immer ihre technologischen Korridore. Sie verwalten Sicherheitsfreigaben und speichern Dateien. Mechanikermeister Castpipe in Eisenschmiedes Tüftlerstadt möchte, dass Ihr diese lochcodierten Archive aus den Tiefen der Stadt bergt."},{t="Eine Hierarchie der Lochungen",b="Gnomische Großrechner verlangen stufenweise Freigaben. Sucht zunächst eine Weiße Lochkarte in den Trümmern außerhalb der inneren Tore. Führt sie in den Matrix-Lochographen 3005-A im Train Depot ein, um eine gelbe Karte zu erhalten. Bringt diese dann zum Terminal 3005-B im Dormitory, um eine blaue Karte zu erhalten. Modell 3005-C wertet sie zu einer roten Karte auf. Das letzte Terminal, 3005-D, wartet in den Engineering Labs, wo aus der roten Karte eine Prismalochkarte wird."},{t="Gnomischer Humor in Binärform",b="Gnomeregans Lochkarten enthalten technische Aufzeichnungen und mehr. Ihre binären Muster bergen auch humorvolle Sprüche, Beschwerden über den Arbeitsplatz und derbe Witze über Hochtüftler Gelbin Mekkadrill in Nachtelfen-Unterwäsche. Selbst die Rechengilden der Stadt konnten einem Streich nicht widerstehen."}},faq={{q="Was ist die Prismalochkarte?",a="Die Prismalochkarte entspricht der höchsten Sicherheitsstufe, die Gnomeregans automatisierte Großrechner anerkennen. Der Matrix-Lochograph 3005-D in den Engineering Labs erstellt sie aus einer Roten Lochkarte.",al={"prismalochkarte","was ist eine lochkarte","gnomeregan lochkarte"}},{q="Wo beginnt die Abfolge der Lochkarten?",a="Die Abfolge beginnt mit einer Weißen Lochkarte, die bei Troggs und mechanischen Wracks außerhalb des Haupteingangs nahe dem Train Depot geborgen wird.",al={"wo weiße lochkarte finden","wie beginnt die lochkartenfolge","erste lochkarte"}},{q="Wo befinden sich die Matrix-Lochograph-Terminals?",a="Der Matrix-Lochograph 3005-A steht im Train Depot außerhalb des Eingangs. Modell 3005-B befindet sich im Dormitory hinter der Clean Zone, und 3005-C steht auf den Laufstegplattformen dahinter. Modell 3005-D steht auf der unteren Ebene der Engineering Labs.",al={"terminalstandorte","wo sind die lochographen","lochkartenmaschinen"}},{q="Wer ist Mechanikermeister Castpipe?",a="Mechanikermeister Castpipe ist ein ranghoher gnomischer Ingenieur unter den Flüchtlingen in Eisenschmiedes Tüftlerstadt. Er koordiniert die Bemühungen, Gnomeregans geistiges Erbe aus der gefallenen Hauptstadt zu bergen.",al={"castpipe","wer vergibt datenrettung","castpipes geschichte"}},{q="Welche Daten sind tatsächlich auf den Karten?",a="Die Karten enthalten wichtige Rechendaten, gnomische Ingenieurswitzeleien, unbeschwerte Scherze über regionale Anführer wie Thrall und Mekkadrill sowie eigenwillige Notizen.",al={"kartentext","binärübersetzung","was steht im binärcode"}},{q="Können Spieler der Horde diese Terminals nutzen?",a="Mechanikermeister Castpipe bietet diese Arbeit in Eisenschmiede nur der Allianz an. Jeder, der die erforderlichen Karten bei sich trägt, kann die Lochograph-Terminals im Dungeon benutzen.",al={"horde datenrettung","horde lochkarten","kann die horde terminals nutzen"}}},fx={["0f0753b5"]={q="Warum möchte Mechanikermeister Castpipe, dass die Lochkarte geborgen wird?",a="Als die Gnome Gnomeregan während seines Falls evakuierten, blieben im Chaos Berge von lebenswichtigen betrieblichen und technischen Daten zurück. Mechanikermeister Castpipe betrachtet die Informationen, die in den hochsicheren Matrix-Lochkarten-Terminals gespeichert sind, als entscheidend für das Überleben und die Wiederaufbaubemühungen der Gnome und besteht darauf, dass sie es sich nicht leisten können, sie dauerhaft zu verlieren.",al={"castpipes motiv","warum braucht castpipe lochkarte","warum datenrettung"}}},fp="11,210,32.373.0,27.423.0,24.288.1,33.186.0,45.138.0,51.234.0,32.192.0,35.163.0,41.165.0"}
P.entries["quest:2931"] = {n="Gussmuffs Auftrag",s="In Eisenschmiede ruft Mechanikermeister Castpipe Reisende auf, Gnomeregans Aufzeichnungen zu bergen. Die verfallenen Hallen bergen noch immer lebenswichtiges mechanisches und technisches Wissen.",h="In Eisenschmiede ruft Mechanikermeister Castpipe Reisende auf, Gnomeregans Aufzeichnungen zu bergen.",kw={"versammlung","castpipe","data rescue","gaxim","gnomeregan","eisenschmiede","rostknirsch","tinkertown"},ang={["faction:Alliance"]="Als Verbündeter der Allianz unterstützt Ihr vertriebene Gnome dabei, ihre verlorenen Archive zu sichern. Diese Arbeit stärkt Tinkertown und die technologische Stellung der Allianz.",["profession:Engineering"]="Als Ingenieur wisst Ihr, dass Gnomeregans Datenkerne Wunder der Rechenkunst und fortschrittliche Baupläne bergen, die anderswo auf Azeroth ihresgleichen suchen.",["race:Gnome"]="Als Gnom helft Ihr mit jedem Bergungseinsatz, ein Stück Eurer gefallenen Heimat vor Strahlung und Zerstörung zu bewahren. Castpipes Arbeit berührt das Überleben Eures Volkes."},sec={{t="Ein Ruf nach Tinkertown",b="Nachdem Gnomeregan gefallen und unter radioaktiver Quarantäne abgeriegelt worden war, fanden die überlebenden Gnome Zuflucht in Tinkertown in Eisenschmiede. Troggs und verstrahlte Konstrukte überrennen noch immer ihre alte Heimat. Tief in der Stadt bewahren Rechenanlagen Betriebsaufzeichnungen und mechanische Baupläne auf. Castpipe sucht Außenstehende, die bereit sind, den giftigen Hallen zu trotzen und Dateien zu bergen, die das Unglück erklären oder den Gnomen die Rückkehr ermöglichen könnten."},{t="Rückhalt der Versammlung",b="Gaxim Rostknirsch von der Erleuchteten Versammlung der Arkanologie, Alchemie und Ingenieurswissenschaften verbreitet die Nachricht von Castpipes Vorhaben. Castpipe gehört keiner akademischen Vereinigung an, doch seine gnomischen Gefährten achten sein Können und unterstützen seine Arbeit. Rostknirsch beziffert die Wahrscheinlichkeit, dass das Unternehmen strategischen Wert hat, auf vierundachtzig Prozent. Reisende können sich in Tinkertown melden, um Befehle zu erhalten."}},faq={{q="Wer ist Mechanikermeister Castpipe?",a="Mechanikermeister Castpipe ist ein angesehener gnomischer Ingenieur in Tinkertown in Eisenschmiede. Er stellt Bergungstrupps zusammen, um Daten aus den unterirdischen Ruinen von Gnomeregan zu bergen.",al={"castpipe","wer ist castpipe","mechanikermeister castpipe"}},{q="Warum will Castpipe Daten aus Gnomeregan?",a="Als Gnomeregan verseucht und evakuiert wurde, blieben entscheidendes technisches Wissen, Baupläne und interne Systemprotokolle im Speicher des Großrechners zurück. Die vertriebenen Gnome brauchen diese Informationen, denn sie hoffen auf den Wiederaufbau.",al={"gnomeregan daten","warum daten bergen","gnomeregan aufzeichnungen"}},{q="Wer ist Gaxim Rostknirsch?",a="Gaxim Rostknirsch ist ein gnomischer Gelehrter der Erleuchteten Versammlung der Arkanologie, Alchemie und Ingenieurswissenschaften. Er unterstützt Castpipes Bergungsvorhaben und verweist fähige Reisende dorthin.",al={"gaxim","rostknirsch"}},{q="Wo ist Castpipe zu finden?",a="Mechanikermeister Castpipe ist in Tinkertown zu finden, dem von Gnomen besiedelten Bezirk im östlichen Viertel von Eisenschmiede.",al={"castpipe standort","wo ist castpipe"}},{q="Was geschieht nach der Meldung bei Castpipe?",a="Wer sich bei Mechanikermeister Castpipe meldet, gelangt zu Data Rescue in der gefallenen Stadt. Reisende betreten das verseuchte Innere von Gnomeregan, um Computerlochkarten und Speichermedien zu bergen.",al={"nächste quest","what comes next","nach castpipe"}},{q="Was ist die Erleuchtete Versammlung der Arkanologie, Alchemie und Ingenieurswissenschaften?",a="Die Erleuchtete Versammlung der Arkanologie, Alchemie und Ingenieurswissenschaften ist eine angesehene gnomische Gesellschaft, die sich wissenschaftlicher, magischer und mechanischer Forschung widmet. Mitglieder wie Gaxim Rostknirsch nutzen Wahrscheinlichkeiten, um wichtige Vorhaben zu beurteilen.",al={"die versammlung","erleuchtete versammlung"}}},fx={["0652d792"]={q="Warum schickt Euch Gaxim Rostknirsch zu Mechanikermeister Castpipe?",a="Gaxim Rostknirsch respektiert den Intellekt von Mechanikermeister Castpipe, auch wenn Castpipe keine Mitgliedschaft in der Erleuchteten Versammlung für Arkanologie, Alchemie und Ingenieurwissenschaften besitzt. Nach Gaxims Berechnungen besteht eine Wahrscheinlichkeit von vierundachtzig Prozent, dass die Datenbeschaffungsoperation, die Castpipe in Gnomeregan vorbereitet, für die Gnome von entscheidender Bedeutung ist. Angesichts dieser günstigen Quoten ist Gaxim bestrebt, fähige Abenteurer in Richtung Eisenschmiede zu lenken, um die Rückeroberungsbemühungen zu unterstützen.",al={"warum schickt euch gaxim","gaxim rostknirschs motiv","warum mit castpipe sprechen"}}},fp="15,157,20.417.0,20.356.0,32.167.0,44.217.0,24.190.0,28.111.0,41.184.0,81.231.0"}
P.entries["quest:2932"] = {n="Grausige Botschaft",s="Im Schlingendorntal schickt Nimboya Euch nach Norden, um die Witherbark-Trolle für ihren Verrat an Thrall zu bestrafen. Er gibt Euch eine Pike, auf der Ihr ihre Schädel aufspießen und die Ihr in einem ihrer Dörfer im Hinterland aufstellen sollt.",h="Im Schlingendorntal schickt Nimboya Euch nach Norden, um die Witherbark-Trolle für ihren Verrat an Thrall zu...",kw={"grausige botschaft","hinterland","hiri'watha","nimboya","tarrens mühle","thrall","witherbark","zun'watha"},sec={{t="Eine Warnung in Blut",b="Nimboya schickt Euch aus dem Schlingendorntal ins Hinterland, weit nach Norden und nordöstlich von Tarrens Mühle, einem Dorf der Verlassenen. Die Witherbark-Trolle standen einst an der Seite der Horde, verrieten jedoch Thrall. Jagt sie, um ihre Schädel zu sammeln, und stellt dann Nimboyas Pike in Hiri'watha oder Zun'watha auf, zwei ihrer kleineren Dörfer. Die Warnung wird ihnen zeigen, was ihre Taten kosten. Nimboya wartet im Schlingendorntal."}},faq={{q="Warum will Nimboya die Witherbark-Trolle bestrafen?",a="Die Witherbark-Trolle waren einst mit der Horde verbündet, wandten sich dann aber gegen Thrall. Nimboya sagt, ihr Verrat dürfe nicht ungestraft bleiben.",al={"warum witherbark angreifen","verrat der witherbark","grausige botschaft grund"}},{q="Wohin schickt Nimboya Euch, um die Pike aufzustellen?",a="Stellt die Pike in Hiri'watha oder Zun'watha auf, zwei kleineren Dörfern der Witherbark im Hinterland.",al={"wo pike aufstellen","nimboya pike ort","grausige botschaft ort"}},{q="Wo liegt das Hinterland von Tarrens Mühle aus gesehen?",a="Das Hinterland liegt nordöstlich von Tarrens Mühle, dem Dorf der Verlassenen. Es liegt weit nördlich von Nimboya im Schlingendorntal.",al={"hinterland lage","wo ist das hinterland"}},{q="Wer vergibt „Grausige Botschaft“?",a="Nimboya gibt Euch die Pike im Schlingendorntal und wartet dort auf Nachricht.",al={"grausige botschaft questgeber","wer ist nimboya"}}},fp="12,184,18.400.0,54.127.0,46.93.0,43.127.0,23.69.0"}
P.entries["quest:2933"] = {n="Giftflaschen",s="Im Hinterland füllen Giftflaschen ein Witherbark-Dorf. Ihre große Zahl deutet darauf hin, dass die Witherbark das widerwärtige grüne Gift schätzen, und ein Apotheker im nahegelegenen Tarrens Mühle könnte eine Probe wollen.",h="Im Hinterland füllen Giftflaschen ein Witherbark-Dorf.",kw={"apotheker lydon","arachnoid","hinterland","tarrens mühle","trollgift","giftflasche","witherbark"},sec={{t="Eine giftige Entdeckung",b="Widerwärtiges grünes Gift füllt Flaschen im gesamten Witherbark-Dorf. Es gibt viele davon, was darauf hindeutet, dass die Witherbark das Gift für wichtig halten. Ein Apotheker in Tarrens Mühle könnte eine Probe zur Untersuchung wollen."},{t="Lydons Urteil",b="Apotheker Lydon hat an jenem Tag mit seinen Experimenten keinen Erfolg gehabt. Er erkennt den Inhalt als Gift, das einer arachnoiden Kreatur entnommen wurde, und fragt dann, woher das Gift stammt."}},faq={{q="Wo sind die Giftflaschen zu finden?",a="Die Flaschen sind in großer Zahl in einem Witherbark-Dorf im Hinterland zu finden.",al={"giftflaschen fundort","wo giftflaschen finden","witherbark gift"}},{q="Wer interessiert sich für die Giftflaschen?",a="Ein Apotheker in Tarrens Mühle könnte eine Probe wollen. Apotheker Lydon ist der richtige Ansprechpartner.",al={"wer will das gift","wo giftflasche abgeben","tarrens mühle apotheker"}},{q="Was ist in den Flaschen?",a="Die Flaschen enthalten widerwärtiges grünes Gift. Ihre große Zahl deutet darauf hin, dass die Witherbark es sehr schätzen.",al={"was ist das gift","was ist in den flaschen"}}},fp="13,191,17.205.0,15.175.1,34.82.0,39.83.0,23.95.0"}
P.entries["quest:2934"] = {n="Unbeschädigter Giftbeutel",s="In Tarrens Mühle braucht Apotheker Lydon eine frische Giftprobe. Ihr durchsucht das Hinterland nach den Spinnen, die es liefern, und der Beutel muss ihn frisch erreichen.",h="In Tarrens Mühle braucht Apotheker Lydon eine frische Giftprobe.",kw={"apotheker lydon","hinterland","shadra'alor","spinnengift","tarrens mühle","giftbeutel"},sec={{t="Eine frische Probe",b="Nach Giftflaschen bittet Euch Apotheker Lydon um eine frischere Probe. Die Spinnen, die das Gift liefern, leben im Hinterland, viele nahe der Trollstadt Shadra'Alor. Lydon will einen unbeschädigten Giftbeutel, der noch frisch abgeliefert wird. Er brennt darauf, damit zu experimentieren, und hat mehrere kleine, schrecklich niedliche Tiere für Versuche bestellt."}},faq={{q="Wer verlangt den unbeschädigten Giftbeutel?",a="Apotheker Lydon in Tarrens Mühle bittet Euch um den Beutel und wartet dort auf dessen Ankunft.",al={"wer vergibt unbeschädigter giftbeutel","wer startet unbeschädigter giftbeutel","unbeschädigter giftbeutel questgeber"}},{q="Wo sind die Spinnen zu finden?",a="Viele der Spinnen leben im Hinterland nahe der Trollstadt Shadra'Alor.",al={"fundort der spinnen","wo sind die spinnen","wo unbeschädigten giftbeutel finden"}},{q="Warum sagt Apotheker Lydon, dass Ihr nicht trödeln sollt?",a="Der Beutel muss frisch ankommen, deshalb will Lydon, dass Ihr ihn unverzüglich bringt.",al={"warum gibt es ein zeitlimit","warum verdirbt der beutel","unbeschädigter giftbeutel zeitlimit"}},{q="Was kam vor diesem Schritt?",a="Dies folgt auf Giftflaschen, als Ihr Lydon eine Giftprobe aus einem Dorf der Witherbark gebracht habt.",al={"vorherige quest","welche quest kommt vor unbeschädigter giftbeutel","unbeschädigter giftbeutel voraussetzung"}}},fp="19,155,14.332.0,37.85.0,31.79.0,43.72.0,27.95.0"}
P.entries["quest:2935"] = {n="Konsultiert Meister Gadrin",s="In Sen'jin sucht Apotheker Lydon eine stärkere Giftprobe. Das Gift der Brutwachen, das Ihr gebracht habt, war schwächer als Eure erste Probe, also könnte eine andere Spinnenart die Quelle sein.",h="In Sen'jin sucht Apotheker Lydon eine stärkere Giftprobe.",kw={"apotheker lydon","meister gadrin konsultieren","durotar","hinterland","meister gadrin","sen'jin","gift","witherbark"},sec={{t="Die Suche nach stärkerem Gift",b="Apotheker Lydon braucht eine frische Probe des stärkeren Giftes. Das Gift der Brutwachen, das Ihr gebracht habt, war schwächer als Eure erste Probe, also muss es von einer anderen Spinnenart stammen.\n\nLydon schickt Euch zu Meister Gadrin in Sen'jin in Durotar. Gadrin ist ein Troll, der mit den Witherbark bestens vertraut ist und vielleicht weiß, woher das Gift stammt."}},faq={{q="Warum schickt Apotheker Lydon Euch zu Meister Gadrin?",a="Das Gift der Brutwachen war schwächer als Eure erste Probe, was auf eine andere Spinnenart hindeutet. Meister Gadrin kennt die Witherbark und kann vielleicht die Quelle des Giftes nennen.",al={"warum gadrin konsultieren","warum nach sen'jin gehen","lydon gadrin"}},{q="Wo befindet sich Meister Gadrin?",a="Meister Gadrin befindet sich in Sen'jin in Durotar.",al={"wo ist gadrin","meister gadrin aufenthaltsort","meister gadrin finden"}},{q="Was geschah vor dieser Reise?",a="Vor dieser Reise habt Ihr Apotheker Lydon einen unbeschädigten Giftbeutel aus dem Hinterland gebracht.",al={"voraussetzung","was war davor","vorherige quest"}}},fp="21,180,20.335.0,52.163.0,31.48.0,30.94.0"}
P.entries["quest:2937"] = {n="Die Beschwörung von Shadra",s="In Shadra'Alor lest Ihr Meister Gadrins Pergament und ruft Shadra aus dem Witherbark-Reich herbei.",h="In Shadra'Alor lest Ihr Meister Gadrins Pergament und ruft Shadra aus dem Witherbark-Reich herbei.",kw={"apotheker lydon","hinterland","meister gadrin","shadra","shadra'alor","spinnengöttin","tarrens mühle","witherbark"},sec={{t="Ruf der Spinnengöttin",b="Meister Gadrin schickt Euch tief ins Witherbark-Reich im Hinterland. In Shadra'Alor lest Ihr sein Pergament am Altar, und Shadra, die Spinnengöttin, antwortet. Besiegt sie dort und bringt dann ihr Gift zu Apotheker Lydon in Tarrens Mühle."}},faq={{q="Wer stellt das Pergament zur Beschwörung von Shadra bereit?",a="Meister Gadrin gibt Euch das Pergament.",al={"wer vergibt die beschwörung von shadra","beschwörung von shadra questgeber"}},{q="Wo wird Shadra beschworen?",a="Ihr beschwört Shadra am Altar von Shadra'Alor, tief im Witherbark-Reich im Hinterland.",al={"wo shadra beschwören","altar von shadra'alor standort","shadra standort"}},{q="Wer erhält das Gift, nachdem Shadra besiegt wurde?",a="Nachdem Shadra besiegt wurde, bringt Ihr ihr Gift zu Apotheker Lydon in Tarrens Mühle.",al={"bei wem das gift abgeben","beschwörung von shadra abgeben","apotheker lydon standort"}}},fp="16,93,22.237.0,44.38.0,25.95.0,47.80.0"}
P.entries["quest:2938"] = {n="Gift für Unterstadt",s="Apotheker Lydon schickt das Gift eines Spinnengottes nach Unterstadt. Seine Stärke begeistert Lydon, der Euch ein Paket für Faranell anvertraut, einen Vorgesetzten im Apothekarium.",h="Apotheker Lydon schickt das Gift eines Spinnengottes nach Unterstadt.",kw={"das apothekarium","apotheker lydon","faranells paket","apothekermeister faranell","shadra","gift für unterstadt"},sec={{t="Ein starker Fund",b="Apotheker Lydon hat mit einer Dosis des Gifts fast zwei Dutzend Kaninchen getötet. Einige waren winzig, sodass ihre Widerstandskraft gewiss gering war. Dennoch ist das Gift stark. Lydon ist sicher, dass Faranell es persönlich testen möchte, und gibt Euch ein Paket für das Apothekarium in Unterstadt."}},faq={{q="Wer schickt das Paket nach Unterstadt?",a="Apotheker Lydon schickt das Paket, nachdem er das Gift getestet hat, das dem Spinnengott der Witherbark entnommen wurde.",al={"wer gibt gift für unterstadt","questgeber gift für unterstadt","wer startet gift für unterstadt"}},{q="Wer soll das Gift in Unterstadt erhalten?",a="Apothekermeister Faranell, Lydons Vorgesetzter, soll das Gift im Apothekarium in Unterstadt erhalten.",al={"wer bekommt das paket","wohin geht das gift in unterstadt","wer ist faranell"}},{q="Wie stark war das Gift bei den Versuchen?",a="Eine Dosis tötete fast zwei Dutzend Kaninchen, obwohl einige sehr jung und winzig waren.",al={"wie stark ist shadras gift","lydons kaninchenversuche"}},{q="Was kommt vor dieser Lieferung?",a="Die Lieferung folgt auf Summoning Shadra, als das Gift dem Spinnengott entnommen wurde.",al={"vorherige quest gift für unterstadt","voraussetzung gift für unterstadt"}}},fp="22,163,13.286.0,43.93.0,54.107.0,40.79.0,32.84.0"}
P.entries["quest:2939"] = {n="Auf der Suche nach Wissen",s="Troyas Moonbreeze schickt Euch zu Daryn Lightwind nach Rut'theran. Er hat in den Trümmern von Feralas einen Stab gefunden und will herausfinden, was es damit auf sich hat.",h="Troyas Moonbreeze schickt Euch zu Daryn Lightwind nach Rut'theran.",kw={"angelas","darnassus","daryn lightwind","feralas","ruinen","rut'theran","stab","troyas moonbreeze"},sec={{t="Ein gewöhnlicher Stab",b="Troyas Moonbreeze sagt, die Ruinen von Feralas seien gefährlich, hätten aber viel darüber zu erzählen, was dort geschehen ist. Vor einigen Tagen durchsuchte er die Trümmer im Süden und fand einen Stab, der gewöhnlich wirkte. Dennoch hat er das Gefühl, dass mehr dahintersteckt. Er und Angelas durchsuchten ihre Bücher, fanden aber kein Wort über den Stab."},{t="Eine Kollegin in Darnassus",b="Troyas hat eine Kollegin in Darnassus, die vielleicht weiß, was es mit dem Stab auf sich hat. Er bittet Euch, mit Daryn Lightwind in Rut'theran zu sprechen."},{t="Daryns Antwort",b="Daryn Lightwind murrt, dass Troyas sie ständig mit wilden Vorstellungen darüber belästigt, etwas Bedeutendes gefunden zu haben. Sie glaubt, die Oger oder Harpyien, die jetzt in den Ruinen leben, hätten alles wirklich Wertvolle wahrscheinlich schon vor langer Zeit weggeschleppt. Ihr könnt Euch gerne umsehen, sagt sie, auch wenn sie bezweifelt, dass die Bücher dort helfen werden."}},faq={{q="Wer schickt Euch zu Daryn Lightwind?",a="Troyas Moonbreeze schickt Euch zu Daryn, weil er herausfinden will, was es mit dem Stab aus den Ruinen von Feralas wirklich auf sich hat.",al={"wer startet auf der suche nach wissen","questgeber"}},{q="Was hat Troyas gefunden?",a="Troyas hat einen Stab in den Trümmern südlich seines Arbeitsortes gefunden. Er wirkt gewöhnlich, doch Troyas hat das Gefühl, dass mehr dahintersteckt.",al={"was hat troyas gefunden","feralas stab"}},{q="Wo ist Daryn Lightwind?",a="Daryn Lightwind ist in Rut'theran. Troyas beschreibt sie als eine Kollegin in Darnassus.",al={"daryn lightwind aufenthaltsort","wo ist daryn"}},{q="Warum schickt Troyas Euch zu Daryn?",a="Troyas und Angelas haben in ihren Büchern nichts über den Stab gefunden. Daryn kann ihnen vielleicht sagen, was es damit auf sich hat.",al={"warum daryn lightwind besuchen","warum darnassus"}}},fp="22,147,17.307.0,24.132.0,13.307.1,33.118.0,21.119.0,25.91.0,34.107.0"}
P.entries["quest:294"] = {n="Ormers Rache",s="An Whelgars Ausgrabungsstätte harren Ormer Eisenzopf und seine beiden Gefährten auf einer Klippe über der von Raptoren überrannten Grabung aus. Unter dem Sumpfland legten die Zwerge gewaltige prähistorische Knochen frei. Gesprenkelte Raptoren kamen in Rudeln und töteten die meisten Mitglieder des Grabungsteams.",h="An Whelgars Ausgrabungsstätte harren Ormer Eisenzopf und seine beiden Gefährten auf einer Klippe über der von...",kw={"gesprenkelter raptor","gesprenkelter kreischer","ormer eisenzopf","ormers rache","ausgrabungsleiter whelgar","sumpfland","whelgars ausgrabungsstätte"},ang={["class:Hunter"]="Als Jäger könnt Ihr beobachten, wie gefährliche gesprenkelte Raptoren an den Hängen außerhalb der Stätte durch sumpfiges Gelände streifen.",["race:Dwarf"]="Als Zwerg kann der Anblick Eurer bei einer Grabung der Explorers' League erschlagenen Verwandten die Säuberung des raptorenverseuchten Steinbruchs zu einem Akt der Ahnenverehrung und gerechten Vergeltung machen."},sec={{t="Freigelegte Schrecken",b="Die Zwerge kamen zu Whelgars Ausgrabungsstätte, um gewaltige prähistorische Überreste unter dem Schlamm des Sumpflands freizulegen. Ihre Entdeckung lockte die einheimischen Raptoren des Sumpfes zur Grabung. Rudel gesprenkelter Raubtiere überrannten die Stätte, überraschten die Ausgräber und rissen ihre Reihen auseinander."},{t="Bitteres Ausharren",b="Nur eine Handvoll Zwerge überlebte. Ormer Eisenzopf, Merrin Felsweber und Ausgrabungsleiter Whelgar kletterten hastig auf eine Klippe über der Grube, doch aggressive Rudel halten sie dort noch immer fest. Ormer trauert um seine gefallenen Kameraden und brennt vor Zorn, bleibt aber, um Merrin und den Ausgrabungsleiter zu beschützen. Er bittet Reisende, die gesprenkelten Raptoren und gesprenkelten Kreischer unterhalb der Klippe auszudünnen. Dies ist der erste Schlag seines Rachefeldzugs."}},faq={{q="Was ist den Ausgräbern hier widerfahren?",a="Die Raptoren überrannten die Grabung, nachdem die zwergischen Archäologen riesige Knochen im Becken freigelegt hatten. Die Störung lockte die örtlichen Rudel aus dem Sumpf an. Sie töteten die meisten Mitglieder des Grabungsteams und kesselten drei Überlebende auf der hohen Klippe ein.",al={"warum sind hier raptoren","massaker bei whelgars ausgrabung","was hat die zwerge getötet"}},{q="Wer ist Ormer Eisenzopf?",a="Ormer Eisenzopf ist ein zwergischer Ausgräber, der an Whelgars Ausgrabungsstätte festsitzt. Er bleibt, um den erschütterten Ausgrabungsleiter Whelgar und Merrin Felsweber zu beschützen, während er nach blutiger Vergeltung an den Raptoren strebt, die seine Kameraden töteten.",al={"wer ist ormer","ormer eisenzopf vorgeschichte"}},{q="Woher kommen diese Raptoren?",a="Gesprenkelte Raptoren und gesprenkelte Kreischer sind im Sumpfland heimische Raubtiere. Sie lauern an den schlammigen Hängen und im Sumpfgebiet westlich der Ausgrabungsklippe sowie entlang der Pfade, die zu den Höhlen der Grabungsstätte führen.",al={"wo sind gesprenkelte raptoren","raptoren fundorte sumpfland"}},{q="Warum jagt Ormer die Raptoren nicht selbst?",a="Ormer brennt darauf, selbst Raptoren zu töten, doch er muss Ausgrabungsleiter Whelgar und Merrin Felsweber beschützen. Er hält Wache, damit die Zuflucht der verängstigten Zwerge auf der Klippe nicht überrannt wird.",al={"warum kämpft ormer nicht","warum sitzt ormer fest"}},{q="Endet Ormers Groll, wenn diese Raptoren dezimiert sind?",a="Nein. Die gewöhnlichen gesprenkelten Raptoren und Kreischer zu töten, ist nur der erste Schritt in Ormers Plan, seine gefallenen Freunde zu rächen. Härtere Schläge gegen die Raptorenbrut werden folgen.",al={"ist dies das ende von ormers rache","wie geht es mit ormer weiter"}},{q="Warum lockte das Freilegen der Knochen die Raptoren an?",a="Die Raptoren des Sumpflands sind aggressive Aasfresser, die ihr Revier erbittert verteidigen. Das Ausgraben der uralten riesenhaften Überreste störte die Ruhe im Becken und lockte neugierige, hungrige Raubtiere mitten ins Grabungslager.",al={"warum lockten die knochen raptoren an","dinosaurierknochen raptoren"}}},fx={["87324e21"]={q="Warum möchte Ormer Eisenzopf, dass die Raptoren getötet werden?",a="Als das Zwergenteam an der Ausgrabungsstätte alte Knochen ausgrub, schwärmten gefräßige Raptoren über das Gelände und schlachteten Ormers Kollegen ab. Ormer, Merrin Felsweber und Ausgrabungsleiter Whelgar überlebten den Ansturm nur knapp und sind weiterhin oben auf den Klippen gefangen. Brennend vor Trauer und Wut möchte Ormer seine gefallenen Brüder rächen und beginnen, die bösartigen Bestien von der Ausgrabung zu vertreiben.",al={"ormer eisenzopfs motiv","warum gefleckte raptoren töten","warum ormer rache"}},["79eca2c5"]={q="Was sind die Gefleckten Raptoren und Kreischer, hinter denen Ihr hergeschickt werdet?",a="Ihr werdet gegen die Gefleckten Raptoren und Gefleckten Kreischer ausgesandt, die direkt westlich der Ausgrabungsklippe umherstreifen. Diese aggressiven Reptilien, die im Sumpfland beheimatet sind, schwärmten über das Gelände, sobald die Ausgräber massive alte Knochen freilegten, massakrierten die Ausgräber und beanspruchten das umliegende Gelände als ihr Futterrevier.",al={"gegen wen kämpft ihr","ziel gefleckte kreischer","gefleckte raptoren sumpfland"}}},fp="15,243,17.279.0,14.398.0,37.221.0,23.229.0,33.196.0,43.176.0,46.176.0,49.197.0"}
P.entries["quest:2940"] = {n="Feralas: Ein historischer Abriss",s="In Feralas findet Ihr Feralas: Ein historischer Abriss, ein Buch, das Troyas brauchen könnte. Es sieht aus, als hätte es seit Ewigkeiten niemand geöffnet. Das Buch gehört Daryn Lightwind, daher müsst Ihr fragen, ob Ihr es Euch ausleihen dürft.",h="In Feralas findet Ihr Feralas: Ein historischer Abriss, ein Buch, das Troyas brauchen könnte.",kw={"buch","daryn lightwind","feralas","geschichte","in search of knowledge","hintergrundgeschichte","troyas"},sec={{t="Ein vernachlässigtes Buch",b="Die Buchdeckel sind stark abgenutzt, und die Seiten sind vergilbt. Nachdem Ihr es durchgesehen habt, vermutet Ihr, dass es das sein könnte, wonach Troyas sucht. Ihr hebt es auf, besinnt Euch dann aber eines Besseren, als es ungefragt auszuleihen. Es gehört Daryn Lightwind, also fragt sie zuerst."},{t="Daryns Antwort",b="Daryn Lightwind denkt einen Moment über Eure Bitte nach. Sie wird Euch Feralas: Ein historischer Abriss ausleihen, aber erst, nachdem Ihr ihr einen Gefallen getan habt."}},faq={{q="Was ist das Buch Feralas: Ein historischer Abriss?",a="Feralas: Ein historischer Abriss hat abgenutzte Buchdeckel und vergilbte Seiten. Es sieht aus, als hätte es seit Ewigkeiten niemand geöffnet, und könnte genau das sein, wonach Troyas sucht.",al={"was ist das buch","feralas ein historischer abriss buch","troyas buch"}},{q="Wem gehört das Buch?",a="Das Buch gehört Daryn Lightwind. Fragt sie, bevor Ihr es ausleiht.",al={"wem gehört feralas ein historischer abriss","wer hat das buch","wer ist daryn lightwind"}},{q="Was kommt davor?",a="Davor kommt In Search of Knowledge, als Troyas Moonbreeze Euch losschickte, um mit Daryn Lightwind über seinen Stab zu sprechen.",al={"vorherige quest","was war die letzte quest","questreihe davor"}}},fp="18,192,16.252.0,14.142.1,36.148.0,18.59.0,23.117.0"}
P.entries["quest:2941"] = {n="Der Borger",s="Am Strand im Hinterland sehnt sich Daryn Lightwind danach, Gammerita zu sehen, einen riesigen Schnappkiefer. Ihre Forschung hält sie davon ab, also schickt sie Euch mit einem Brief für Curgle Cranklehop nach Tanaris.",h="Am Strand im Hinterland sehnt sich Daryn Lightwind danach, Gammerita zu sehen, einen riesigen Schnappkiefer.",kw={"curgle cranklehop","daryn lightwind","gammerita","schnappkiefer","schnappschuss","superschnapper fx","tanaris","der borger"},sec={{t="Ein Bild von Gammerita",b="Daryn Lightwind hat viele Themen erforscht. Nun gilt ihre Aufmerksamkeit den Schnappkiefern am Strand im Hinterland, besonders Gammerita, einem riesigen Schnappkiefer. Ihre Forschung bindet sie an diesen Ort, also bittet sie Euch, ein Bild von Gammerita mitzubringen."},{t="Der Brief nach Tanaris",b="Daryn gibt Euch einen Brief für Curgle Cranklehop in Tanaris. Curgle hat eine Erfindung gebaut, die ein Bild aufnehmen kann. Daryn glaubt, dass Curgle es einen Schnappschuss nennt."},{t="Curgles Reaktion",b="Curgle hält Euch für einen von Daryns Praktikanten und lobt Daryn als sachkundige Historikerin. Dann geht Curgle den Superschnapper FX holen. Curgle ist sich sicher, dass Ihr ihn lieben werdet."}},faq={{q="Wer schickt Euch nach Tanaris?",a="Daryn Lightwind schickt Euch mit einem Brief nach Tanaris. Ihre Forschung hindert sie daran, selbst zu gehen.",al={"questgeber","wer vergibt der borger","daryn lightwind"}},{q="Wer ist Curgle Cranklehop?",a="Curgle Cranklehop ist in Tanaris und hat für Daryn eine Erfindung gebaut, die ein Bild aufnehmen kann. Daryn glaubt, dass Curgle es einen Schnappschuss nennt.",al={"wer ist curgle","curgle cranklehop standort","curgle tanaris"}},{q="Warum möchte Daryn ein Bild von Gammerita?",a="Daryn ist von den Schnappkiefern am Strand im Hinterland fasziniert und möchte besonders gern Gammerita sehen. Ihre Forschung hält sie davon ab, also ist ein Bild die nächstbeste Lösung.",al={"gammerita schnappkiefer","warum gammerita","riesiger schnappkiefer"}},{q="Was ist Gammerita?",a="Gammerita ist ein riesiger Schnappkiefer am Strand im Hinterland.",al={"wer ist gammerita","gammerita"}}},fp="12,176,22.237.0,21.154.0,17.178.1,25.94.0,25.134.0,43.168.0,18.61.0"}
P.entries["quest:2942"] = {n="Der Morgenstein",s="Am Equinex-Monolithen beginnt die Energie des Stocks von Equinex zu schwinden, sobald Ihr das Artefakt nehmt. Ihr bringt den Funkelnden Stein und den Stock zurück zu Troyas Moonbreeze in der Mondfederfeste.",h="Am Equinex-Monolithen beginnt die Energie des Stocks von Equinex zu schwinden, sobald Ihr das Artefakt nehmt.",kw={"equinex-monolith","mondfederfeste","feralas","morgenstein","funkelnder stein","stock von equinex","troyas moonbreeze"},sec={{t="Zurück zur Mondfederfeste",b="Der Stock von Equinex beginnt Energie zu verlieren, wenn Ihr das Artefakt aus dem Monolithen nehmt. Troyas Moonbreeze in der Mondfederfeste wartet auf Nachricht über Euren Fund. Bringt ihm den Funkelnden Stein und den Stock."},{t="Troyas' Erkenntnisse",b="Nach Eurer Abreise untersucht Troyas den Stein und nennt ihn den Morgenstein. Er kennt seinen Zweck noch nicht, glaubt aber, dass alles, was auf diese Weise im Monolithen verborgen war, von großer Bedeutung sein muss. Er wird seine Studien fortsetzen und hofft, dass Ihr ihm zur Seite steht."}},faq={{q="Wo beginnt das?",a="Es beginnt am Equinex-Monolithen, wenn Ihr das Artefakt daraus nehmt.",al={"wo gibt es diese quest","wo beginnt der morgenstein","equinex-monolith start"}},{q="Wem bringe ich den Stein?",a="Bringt den Stein zusammen mit dem Stock von Equinex zu Troyas Moonbreeze in der Mondfederfeste.",al={"wer nimmt den morgenstein entgegen","wo ist troyas moonbreeze","wer bekommt den funkelnden stein"}},{q="Was geschieht mit dem Stock von Equinex?",a="Die Energie des Stocks beginnt zu schwinden, sobald Ihr das Artefakt aus dem Monolithen nehmt.",al={"stock von equinex energie","was geschieht mit dem stock","warum hat der stock seine kraft verloren"}},{q="Was kommt davor?",a="Davor kommt der Stock von Equinex, bei dem Ihr den Stock neben dem Monolithen mit Energie aufgeladen habt.",al={"vorherige quest","welche quest kommt vor dem morgenstein","vorausgesetzte quest"}}},fp="16,179,30.208.0,17.259.1,22.70.0,28.96.0,37.85.0,23.83.0"}
P.entries["quest:2943"] = {n="Rückkehr zu Troyas",s="Daryn Lightwind schickt Euch mit ihrem Buch Feralas: A History zur Mondfederfeste. Troyas Moonbreeze erwartet ungeduldig Eure Rückkehr.",h="Daryn Lightwind schickt Euch mit ihrem Buch Feralas: A History zur Mondfederfeste.",kw={"darnassus","daryn lightwind","mondfederfeste","feralas","feralas: a history","troyas moonbreeze"},sec={{t="Ein geliehenes Buch",b="Nach dem Superschnapper FX vertraut Euch Daryn Lightwind ihr Buch Feralas: A History an. Sie drängt Euch zur Eile, denn Troyas Moonbreeze erwartet ungeduldig Eure Rückkehr. Das Buch ist für Troyas in der Mondfederfeste bestimmt."},{t="Troyas liest",b="Troyas Moonbreeze ist froh, dass Ihr das Buch gebracht habt. Er sieht es sich an und überfliegt die Seiten. Dann ruft er aus, dass er glaubt, es gefunden zu haben."}},faq={{q="Was überbringe ich?",a="Ihr überbringt Daryn Lightwinds Buch Feralas: A History.",al={"was ist das für ein buch","was bringe ich troyas","feralas a history buch"}},{q="Wo ist Troyas Moonbreeze?",a="Troyas Moonbreeze ist in der Mondfederfeste.",al={"troyas aufenthaltsort","wo ist troyas moonbreeze","wohin muss ich"}},{q="Wer gibt Euch das Buch?",a="Daryn Lightwind gibt Euch das Buch und bittet Euch, darauf aufzupassen.",al={"wer gibt die quest","questgeber","daryn lightwind"}},{q="Was kam davor?",a="Davor kommt der Superschnapper FX.",al={"vorherige quest","was habe ich gerade getan","questreihe davor"}}},fp="16,130,15.222.0,12.134.1,21.62.0,27.47.0,23.65.0,22.39.0"}
P.entries["quest:2944"] = {n="Der Superschnapper FX",s="Curgle Cranklehop hat ein neues Gerät für Euch zum Ausprobieren: den Superschnapper FX. Richtet ihn auf Gammerita, eine Kreatur aus dem Hinterland, und bringt dann das Bild und das Gerät zu Daryn Lightwind in Rut'theran. Dies folgt auf The Borrower.",h="Curgle Cranklehop hat ein neues Gerät für Euch zum Ausprobieren: den Superschnapper FX.",kw={"curgle cranklehop","daryn lightwind","gammerita","rut'theran","schnappschuss","superschnapper fx","hinterland"},sec={{t="Ein Gerät zum Ausprobieren",b="Nach The Borrower legt Curgle Cranklehop Euch eine neue Erfindung in die Hände: den Superschnapper FX. Richtet ihn auf das, was Ihr abbilden möchtet, und drückt dann den Knopf. Curgle gibt ihn Euch zum Ausprobieren."},{t="Das Motiv",b="Gammerita, eine Kreatur aus dem Hinterland, ist das Motiv, das Ihr Curgle gegenüber erwähnt habt. Er wünscht Euch viel Glück bei der Suche nach ihr und erwartet, dass Daryn Lightwind sich über den Schnappschuss freuen wird. Sobald Ihr das Bild habt, bringt es zusammen mit dem Gerät zu Daryn in Rut'theran."}},faq={{q="Wer gibt Euch den Superschnapper FX?",a="Curgle Cranklehop gibt Euch den Superschnapper FX zum Ausprobieren.",al={"wer gibt den superschnapper","curgle questgeber","wo gibt es den superschnapper fx"}},{q="Was fotografiere ich mit dem Superschnapper FX?",a="Fotografiert Gammerita, eine Kreatur aus dem Hinterland. Curgle wünscht Euch viel Glück bei der Suche nach ihr.",al={"gammerita aufenthaltsort","wo ist gammerita","gammerita schnappschuss"}},{q="Wer erhält den Schnappschuss?",a="Daryn Lightwind in Rut'theran erhält sowohl den Schnappschuss als auch das Gerät.",al={"superschnapper fx abgeben","wohin geht das bild","wer ist daryn lightwind"}},{q="Was kommt als Nächstes in der Questreihe?",a="Die Questreihe geht mit Return to Troyas weiter.",al={"nächste quest nach dem superschnapper","was folgt auf den superschnapper fx"}}},fp="20,229,16.183.0,11.261.0,31.56.0,47.90.0,26.80.0,29.42.0"}
P.entries["quest:2945"] = {n="Schmutzverkrusteter Ring",s="Ein Dunkeleisenzwerg in Gnomeregan trägt einen Ring, verkrustet mit giftigem Unrat und hartem Schlamm. Der Sparklematic 5200 im Wohnheim der Clean Zone kann ihn sauber scheuern und seine Markierungen freilegen.",h="Ein Dunkeleisenzwerg in Gnomeregan trägt einen Ring, verkrustet mit giftigem Unrat und hartem Schlamm.",kw={"clean zone","dunkeleisen","wohnheim","gnomeregan","schmutzverkrusteter ring","return of the ring","sparklematic 5200"},ang={["profession:Engineering"]="Der Sparklematic 5200 zeigt gnomische Ingenieurskunst in Aktion und verbindet industrielles Scheuern mit Lösungsmitteln mit einem automatischen Geschenkverpacker.",["race:Dwarf"]="Als Zwerg könnt Ihr erkennen, dass ein eingedrungener Dunkeleisenzwerg den Ring aus Eisenschmiede oder von gnomischen Opfern während Gnomeregans Fall erbeutet haben könnte.",["race:Gnome"]="Als Gnom wisst Ihr, dass Eure Erfinder selbst beim Fall Eurer Stadt Reinigungsmaschinen bauten, die gefährliche Waschgänge mit fröhlichem Glockenklang und einer Schleife beenden."},sec={{t="Ein Relikt unter dem Schlamm",b="Die Kämpfe überziehen Gnomeregans Korridore mit giftigem Schlick, Öl und radioaktivem Niederschlag. Dunkeleisenzwerge, die in die Stadt eindringen, tragen Schmuckstücke bei sich, die von diesem Unrat verschmutzt sind. Ein Ring trägt eine Kruste, die sich durch gewöhnliches Waschen nicht entfernen lässt. Darunter mag das Metall Kupfer, Gold oder Schrott sein."},{t="Der Sparklematic 5200",b="Der Sparklematic 5200 im Wohnheim der Clean Zone nimmt Münzen an, scheuert verschmutzte Gegenstände sauber und gibt sie poliert und mit einer Schleife verpackt zurück. Die Reinigung des Rings legt das Siegel einer Stadt und eingravierte Initialen auf der Innenseite des Reifs frei. Diese Markierungen beginnen Return of the Ring, eine Reise zur Rückgabe."}},faq={{q="Wo findet Ihr den Schmutzverkrusteten Ring?",a="Dunkeleisenzwerge in Gnomeregan tragen den Ring bei sich.",al={"ring beute","wo fällt der schmutzring","wer lässt den schmutzverkrusteten ring fallen"}},{q="Wie reinigt Ihr den Ring?",a="Bringt den Ring zum Sparklematic 5200 im Wohnheim der Clean Zone in Gnomeregan. Zahlt die erforderliche Münzgebühr, und die Maschine scheuert den verhärteten Schlamm ab.",al={"ring reinigen","wie den schmutzverkrusteten ring reinigen","wo den ring waschen"}},{q="Was geschieht nach der Reinigung des Rings?",a="Der Sparklematic gibt den wiederhergestellten Ring in einer ordentlich verpackten Schachtel zurück, wobei seine persönlichen Gravuren nun sichtbar sind. Damit beginnt Return of the Ring, das Euch auf die Suche nach dem ursprünglichen Besitzer des Rings führt.",al={"folgequest schmutzring","was mit sauberem ring tun","sparklematic ring ergebnis"}},{q="Können Spieler der Horde diese Quest abschließen?",a="Ja. Abenteurer der Horde können den Ring mit dem Sparklematic 5200 reinigen. Spätere Schritte schicken Spieler der Horde zu einem Ingenieur in Orgrimmar statt zurück nach Eisenschmiede.",al={"schmutzring nur für allianz","horde schmutzverkrusteter ring","kann die horde den ring reinigen"}},{q="Warum wird der Ring nach der Reinigung in einer Geschenkschachtel verpackt?",a="Der Sparklematic 5200 scheuert Schlick und Schmutz ab, verpackt dann jeden gereinigten Gegenstand und bindet eine Zierschleife darum, alles mit gnomischem Spielwitz.",al={"ring als geschenk verpackt","warum geschenkschachtel beim sparklematic"}},{q="Gibt es mehrere Sparklematic-Maschinen?",a="Mehrere Sparklematic-Geräte stehen entlang der Wand im Wohnheim der Clean Zone. Nur das Gerät links vom Treppeneingang, nahe den freundlichen Gnomen, funktioniert für den Ring.",al={"welcher sparklematic","sparklematic 5200 standorte"}}},fx={["5abd59ba"]={q="Warum müsst Ihr den Grime-Encrusted Ring reinigen?",a="Wenn Ihr den Ring von dem gefallenen Dunkeleisenzwerg wegnehmt, ist er mit einer dicken, verhärteten Kruste aus radioaktivem Schlamm und Höhlendreck überzogen. Ihr könnt das schwache Schimmern von Edelmetall und einem Edelstein unter dem Schmutz erkennen, aber die verkrusteten Rückstände machen ihn untragbar und unmöglich zu inspizieren. Ihn zu reinigen ist die einzige Möglichkeit, seine wahre Handwerkskunst zu enthüllen und zu sehen, ob er irgendeinen wirklichen Wert oder Zweck hat.",al={"warum ring reinigen","zweck grime-encrusted ring","warum grime-encrusted ring waschen"}},c5a1096d={q="Was ist der Grime-Encrusted Ring?",a="Es scheint ein wertvolles Schmuckstück zu sein, das von einem der einfallenden Dunkeleisenzwerge nach Gnomeregan gebracht wurde. Völlig erstickt in verstrahltem Industrieschmutz sind seine feine Metallarbeit und der eingebettete Stein vollständig verborgen, bis er durch Gnomeregans automatischen Reinigungsapparat, den Sparklematic 5200, geführt wird.",al={"was ist grime-encrusted ring","grime-encrusted ring hintergrund","was für ein ring ist das"}}},fp="20,180,24.283.0,21.283.1,43.51.0,26.150.0,39.190.0,38.158.0,53.138.0,41.168.0"}
P.entries["quest:2947"] = {n="Die Rückkehr des Rings",s="In Gnomeregan trägt ein goldener Ring eine Herstellermarke, die Euch nach Eisenschmiede führt.",h="In Gnomeregan trägt ein goldener Ring eine Herstellermarke, die Euch nach Eisenschmiede führt.",kw={"blitzender goldring","dunkeleisenzwerge","siegel von eisenschmiede","mystic ward","funkelmat","talvash del kissel","tdk"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr an Artefakten mit Eisenschmiedes Siegel im Besitz von Dunkeleisenzwergen die wachsende Bedrohung erkennen, die Agenten von Emperor Thaurissan für die Bergheimat der Allianz darstellen.",["race:Gnome"]="Als Gnom gewährt Euch der Fund verlorener Handwerkskunst in Gnomeregan einen seltenen Einblick in die friedlichen Handwerke, die Euer Volk vor Thermapluggs Katastrophe ausübte."},sec={{t="Ein schlammverkrusteter Schatz",b="Ihr legt ein schmutzverkrustetes Schmuckstück in Gnomeregans Funkelmat 5200. Die Maschine entfernt jahrelang angesammelten, verstrahlten Schmutz und enthüllt einen polierten Blitzenden Goldring, der noch immer vor arkaner Macht summt. Auf der Innenseite des Rings stehen drei Initialen, „TdK“, neben dem Gütesiegel von Eisenschmiede."},{t="Der Handwerker im Mystic Ward",b="Talvash del Kissel, ein Gnomenjuwelier im Mystic Ward von Eisenschmiede, erkennt den Ring als eines seiner Standardmodelle aus der Zeit vor Gnomeregans Fall. Bei der Arbeit wehrt er oft eingebildete Schuldeneintreiber ab. Dass eingeschleuste Dunkeleisenzwerge den Ring bei sich trugen, beunruhigt ihn und wirft Fragen darüber auf, was sich unter der verlorenen Stadt regte."}},faq={{q="Wer hat den in Gnomeregan gefundenen Ring gefertigt?",a="Die Initialen „TdK“ gehören Talvash del Kissel, einem Gnomenjuwelier im Mystic Ward von Eisenschmiede. Vor Gnomeregans Fall betrieb er dort ein Juweliergeschäft und fertigte mehrere einfache magische Ringe nach diesem Entwurf.",al={"wer hat den ring gefertigt","ring initialen tdk","wer ist tdk"}},{q="Woher stammte der Ring ursprünglich?",a="Der Ring stammte aus den Tiefen Gnomeregans, wo er als schmutzverkrustetes Schmuckstück im Besitz feindlicher Eindringlinge wie der Dunkeleisenzwerge gefunden wurde. Der Funkelmat 5200 brachte seinen goldenen Glanz und seine Herstellermarken wieder zum Vorschein.",al={"wo wurde der ring gefunden","woher stammt der ring"}},{q="Warum trugen Dunkeleisenzwerge Talvashs Ring bei sich?",a="Talvash weiß nicht genau, warum eingeschleuste Dunkeleisenzwerge sein altes Werk bei sich trugen. Der Ring könnte aus seiner verlassenen Werkstatt stammen oder jemandem abgenommen worden sein, der bei der Invasion Gnomeregans nicht entkommen konnte.",al={"warum haben dunkeleisenzwerge ihn","geschichte des rings der dunkeleisenzwerge"}},{q="Warum hält Talvash del Kissel Euch für seinen Vermieter?",a="Talvash ist nervös und exzentrisch und oft mit seiner Miete in Eisenschmiede im Rückstand. Wenn Fremde sich seinem Laden auf aggressive Weise nähern, vermutet er Gerichtsvollzieher oder Vermieter, die seine überfälligen Schulden eintreiben wollen.",al={"warum ist talvash paranoid","talvash miete"}},{q="Stellt Talvash verfluchten Schmuck her?",a="Talvash versichert möglichen Kunden nachdrücklich, dass er keine verfluchten Gegenstände herstellt. Seine nervösen Beteuerungen werfen meist mehr Fragen auf, als sie beantworten.",al={"ist talvash verflucht","verfluchter schmuck eisenschmiede"}},{q="Kann ich den Ring einfach behalten, statt ihn zurückzugeben?",a="Der Ring hat magische Eigenschaften, doch sein Schöpfer kann ihn untersuchen und anbieten, seine Verzauberung durch weitere Arbeit zu verfeinern.",al={"den ring behalten","den ring zurückgeben"}}},fx={["8e194cce"]={q="Warum möchte der Sparklematic 5200, dass der Ring zurückgegeben wird?",a="Das will er nicht. Der Sparklematic 5200 ist ein automatisiertes Reinigungsgerät, das entwickelt wurde, um aus den Tiefen von Gnomeregan geborgenen Schrott zu verarbeiten. Er reinigt alles, was Ihr hineinlegt, und spuckt das restaurierte Objekt wieder aus. Sobald die Maschine den polierten Blitzender Goldring ausgibt, ist die Rückgabe ganz Eure Entscheidung, nachdem Ihr das Herstellersiegel und das Siegel von Eisenschmiede im Band entdeckt habt.",al={"warum ring zurückgeben","motiv sparklematic 5200","warum will die maschine den ring zurück"}}},fp="18,80,24.278.0,30.338.1,38.204.0,40.217.0,51.190.0,55.197.0,33.143.0,49.121.0"}
P.entries["quest:2948"] = {n="Gnomenverbesserungen",s="In Eisenschmiede bietet Talvash del Kissel an, einen Ring zu verbessern, den er in Gnomeregan gefertigt hat. Er braucht Silber und Moosachat für ein filigranes Gitterwerk über dessen altem Reif.",h="In Eisenschmiede bietet Talvash del Kissel an, einen Ring zu verbessern, den er in Gnomeregan gefertigt hat.",kw={"blitzender goldring","gnomenverbesserungen","gnomeregan","eisenschmiede","moosachat","silberbarren","talvash"},ang={["faction:Alliance"]="Als Abenteurer der Allianz könnt Ihr durch die Verbindungen zwischen der gefallenen Hauptstadt und Eisenschmiede Flüchtlingen aus Gnomeregan helfen.",["profession:Mining"]="Als Bergarbeiter könnt Ihr das Silber und den Moosachat beschaffen, die Talvash für seine Schmuckarbeiten braucht.",["race:Gnome"]="Als Gnom könnt Ihr Talvashs Stolz auf sein Handwerk erkennen, selbst nach der Verbannung aus seiner Heimat und dem Verlust seiner Materialien."},sec={{t="Ein Gnomenhandwerker im Exil",b="Talvash del Kissel floh aus Gnomeregan, nachdem die Trogg-Invasion und die Verstrahlung die Stadt zu Fall gebracht hatten. Nun lebt der Gnomenflüchtling im Mystic Ward von Eisenschmiede. Dem Juwelier und Tüftler fehlen Geld und Vorräte, doch er will unbedingt beweisen, dass sein Können im Exil ungebrochen ist."},{t="Den alten Reif aufwerten",b="Talvash freut sich, seinen schlichten Ringentwurf wiederzusehen, gereinigt vom Glitzer-o-Mat 5200. Doch er hält den alten Reif für veraltet. Er bietet an, ihn mit Gitterwerk aus Silber und Moosachat zu verbessern und damit sein Geschick im Umgang mit Metall und Edelsteinen zu zeigen."}},faq={{q="Wer ist Talvash del Kissel?",a="Talvash del Kissel ist ein Gnomenjuwelier und Handwerker, der im Exil in Eisenschmiede lebt. Vor dem Fall Gnomeregans betrieb er dort einen kleinen Schmuckladen. Einer seiner Ringe kann geborgen und zu ihm in den Mystic Ward gebracht werden.",al={"talvash","talvash del kissel","gnomenjuwelier eisenschmiede"}},{q="Welche Geschichte steckt hinter dem Ring, der aufgewertet wird?",a="Talvash fertigte den Ring als einen von mehreren schlichten Reifen in seinem Laden in Gnomeregan. Ein Zwerg der Dark Iron trug einen davon in die Ruinen, wo Abenteurer ihn bergen und im Glitzer-o-Mat 5200 reinigen können. Talvash bietet an, ihn mit Gitterwerk aus Silber und Moosachat zu verbessern.",al={"woher kommt der ring","grime-encrusted ring herkunft"}},{q="Warum bittet Talvash den Spieler, die Reagenzien zu beschaffen?",a="Nach seiner Flucht aus Gnomeregan sind Talvash die Materialien ausgegangen, und ihm fehlt das Geld. Er bittet um Silber und Moosachat, um das Gitterwerk anzufertigen.",al={"warum werden silber und moosachat benötigt","warum hat talvash keine materialien"}},{q="Wo beginnt diese Questreihe?",a="Die Spur beginnt in Gnomeregan, wo bei Gegnern ein Grime-Encrusted Ring gefunden werden kann. Reinigt ihn im Glitzer-o-Mat 5200 und folgt dann den Initialen 'TdK' zu Talvash in Eisenschmiede.",al={"gnomenverbesserungen beginnen","ring questreihe beginn"}},{q="Ist Talvash wegen seiner Lage in Eisenschmiede verbittert?",a="Talvash beklagt seine unverschuldete Geldnot, bewahrt sich aber seine Zuversicht und seinen Berufsstolz. Er glaubt, dass er in ganz Azeroth für die Fertigung der feinsten Schmuckstücke berühmt sein wird, sobald er wieder auf den Beinen ist.",al={"talvash vorgeschichte","talvash persönlichkeit"}},{q="Hat die Horde Zugang zu dieser Quest?",a="Nein. Abenteurer der Horde, die schmutzverkrustete Gegenstände in Gnomeregan reinigen, werden zu Nogg in Orgrimmar geschickt statt zu Talvash in Eisenschmiede.",al={"kann die horde gnomenverbesserungen abschließen","horde ringaufwertung"}}},fx={["2e3e2066"]={q="Wofür ist der Silberbarren?",a="Talvash braucht das veredelte Metall, um Euren ursprünglichen Ring in ein komplizierteres Schmuckstück umzuformen. Er verwendet den Silberbarren, um direkt auf das Band eine detaillierte Gitterarbeit zu schmieden, die dem einfachen Design weit mehr Eleganz und Haltbarkeit verleiht, als seine frühe Handwerksarbeit besaß.",al={"warum silberbarren","talvash silberbarren","wofür braucht er silber"}},a02fa77a={q="Wofür ist der Moosachat?",a="Der Moosachat dient als dekoratives Herzstück für die Aufwertung des Rings. Indem er den polierten grünen Edelstein in das neu geschmiedete Silbergeflecht einsetzt, beabsichtigt Talvash, Flair hinzuzufügen und seine wahre Expertise als Kunsthandwerker zu präsentieren, wodurch ein rudimentäres Schmuckstück in ein weitaus beeindruckenderes Werk verwandelt wird.",al={"warum moosachat","talvash moosachat","wofür braucht er achat"}}},fp="17,153,26.270.0,22.232.0,26.213.0,51.266.0,56.136.0,34.176.0,51.197.0,41.132.0"}
P.entries["quest:2949"] = {n="Die Rückkehr des Rings",s="Ein Ring aus Gnomeregan trägt Orgrimmars Siegel und die Buchstaben NOG. Seine Spur führt zu Nogg, einem Gobliningenieur mit einer Theorie über die Ruinen.",h="Ein Ring aus Gnomeregan trägt Orgrimmars Siegel und die Buchstaben NOG.",kw={"blitzender goldring","dunkeleisen","gnomeregan","nogg","orgrimmar","die rückkehr des rings","funkelmat 5200","tal der ehre"},ang={["faction:Horde"]="Als Mitglied der Horde findet Ihr ihre Symbole nur selten tief im führenden Technologiezentrum der Östlichen Königreiche. Der Ring führt Euch von Khaz Modan ins Tal der Ehre.",["profession:Engineering"]="Als Ingenieur wisst Ihr, dass sich die Goblinerfinder in Orgrimmar an gnomischer Erfindungskunst messen. Nogg brennt darauf, alles zu untersuchen, was aus ihrem zerstörten technologischen Wunderwerk geborgen wird."},sec={{t="Ein rätselhafter Fund",b="Ihr reinigt einen Ring aus Gnomeregan im Funkelmat 5200. Die Maschine entfernt den Schmutz und enthüllt Orgrimmars offizielles Siegel, einen Schwall magischer Kraft und die teilweise lesbaren Buchstaben NOG. Gnomeregan liegt tief in Khaz Modan, eine Stadt der Allianz fern der Hauptstadt der Horde. Der Ring könnte in Kalimdor gefertigt oder auf einer gescheiterten Expedition dorthin gebracht worden sein, doch sein Siegel weist zurück nach Orgrimmar."},{t="Gnomische Rivalitäten und Dunkeleisenintrigen",b="Ihr bringt den Ring zu Nogg ins Tal der Ehre in Orgrimmar. Der Gobliningenieur sagt, dass er ihm nicht gehört, doch seine Herkunft wirft Fragen auf. Goblins betrachten gnomische Erfinder seit Langem als exzentrische Rivalen. Nogg vermutet, dass die Gnome die Golementwürfe der Dunkeleisenzwerge gestohlen und verändert haben. Da Dunkeleisenzwerge den Ring in Gnomeregan besaßen, glaubt er, dass sie Vergeltung suchen könnten, eine Spur, der nachzugehen sich lohnt."}},faq={{q="Warum trägt ein in Gnomeregan gefundener Ring das Siegel von Orgrimmar?",a="Niemand weiß genau, wie der Ring nach Gnomeregan gelangte. Dunkeleisenzwerge trugen ihn tief in die Ruinen, wo er geborgen wurde. Sein Siegel von Orgrimmar verbindet ihn mit Metallarbeitern und Handwerkern der Horde in Durotar.",al={"warum orgrimmars siegel","ring der horde in gnomeregan","wie kam der ring dorthin"}},{q="Wer ist Nogg?",a="Nogg ist ein Gobliningenieur im Tal der Ehre in Orgrimmar. Er betreut Ingenieursbedarf und Maschinen, und sein Name passt zu den abgenutzten Buchstaben auf dem gereinigten Ring.",al={"wer ist nogg","nogg orgrimmar","nog buchstaben ring"}},{q="Was ist der Funkelmat 5200?",a="Der Funkelmat 5200 ist eine automatische industrielle Waschanlage in der Clean Zone von Gnomeregan. Er entfernt dicke Schichten giftigen Schlamms und radioaktive Verstrahlung von Gegenständen, die aus den zerstörten Gängen geborgen werden.",al={"was ist der funkelmat","funkelmat 5200","cleanomatic"}},{q="Gehört der Ring Nogg?",a="Nein. Nogg untersucht den gereinigten Ring und sagt, dass er ihm nicht gehört. Er erkennt die Handwerkskunst und nutzt sein Ingenieursgeschick, um ihn für Euch weiter zu verändern.",al={"ist es noggs ring","hat nogg seinen ring verloren","wem gehört der ring"}},{q="Was glaubt Nogg, was in Gnomeregan geschehen ist?",a="Nogg vermutet, dass die Gnome fortschrittliche Golembaupläne vom Dunkeleisenklan gestohlen haben. Er glaubt, dass die Dunkeleisenzwerge Vergeltung wollen, und hält es für lohnend, dieser Spur nachzugehen.",al={"noggs theorie zu gnomeregan","was geschah mit gnomeregan","warum dunkeleisenzwerge"}},{q="Kann ich den Ring behalten, statt ihn Nogg zurückzubringen?",a="Ihr könnt den Ring sofort tragen oder ihn nach Orgrimmar bringen. Bringt Ihr ihn zu Nogg, kann der Gobliningenieur seine Handwerkskunst untersuchen und weitere Verbesserungen anbieten.",al={"blitzenden goldring behalten","ring zurückbringen oder behalten","ring zwingend nogg geben"}}},fx={["9392e9ce"]={q="Warum möchte der Sparklematic 5200, dass der Ring zurückgegeben wird?",a="Der Sparklematic 5200 hat keinen eigenen Willen oder Motiv – es ist lediglich ein automatischer Reinigungsapparat in Gnomeregan, der dazu gedacht ist, Schmutz von geborgenen Objekten zu schrubben und auszugeben, was auch immer herauskommt. Sobald er Euren Grime-Encrusted Ring reinigt und ihn in einer verpackten Schachtel ausgibt, ist seine Funktion beendet. Die Entscheidung, die im Band eingravierten Initialen aufzuspüren, entspringt rein Eurer eigenen Neugier, nachdem Ihr das Orgrimmar-Siegel und die teilweise geätzten Buchstaben entdeckt habt.",al={"sparklematic motiv","warum ring sparklematic zurückgeben","ziel sparklematic 5200"}}},fp="18,140,19.394.0,37.391.1,63.203.0,12.163.0,30.193.0,23.151.1,44.169.0,52.157.0"}
P.entries["quest:295"] = {n="Ormers Rache",s="An der zerstörten Ausgrabungsstätte von Whelgar schickt Euch Ormer Eisenzopf gegen die Raptoren, die seine Expedition vertrieben haben. Ihre kleineren Jungtiere sind bereits dezimiert, und nun will er die gesprenkelten Sensenklauen und Rasiermesser töten lassen.",h="An der zerstörten Ausgrabungsstätte von Whelgar schickt Euch Ormer Eisenzopf gegen die Raptoren, die seine...",kw={"zwerg","ausgrabung","explorers' league","gesprenkeltes rasiermesser","gesprenkelte sensenklaue","ormer eisenzopf","raptoren","sumpfland","ausgrabungsstätte von whelgar"},ang={["class:Hunter"]="Als Jäger steht Ihr den gesprenkelten Raptoren des Sumpflands gegenüber, territorialen Rudeljägern, die die Fährtensuche in den engen, schlammigen Gräben tödlich machen.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, die Ausgrabungsstätte von Whelgar zurückzugewinnen und sichere Arbeiten entlang der östlichen Straße zwischen dem Sumpfland und dem Arathihochland zu gewährleisten.",["race:Dwarf"]="Als Zwerg teilt Ihr den ausgeprägten Stolz der Explorers' League und ihre Weigerung, die Suche nach der Vergangenheit Eurer Vorfahren von wilden Bestien aufhalten zu lassen."},sec={{t="Die Jagd verschärft sich",b="Ormer Eisenzopf schickt Euch gegen die ausgewachsenen Raptoren im unteren Ausgrabungsbereich. Ihr habt bereits die Jungtiere dezimiert, die das obere Lager überrannt haben, doch gesprenkelte Sensenklauen und Rasiermesser bedrohen weiterhin jede Hoffnung, die Ausgrabungsstätte zurückzugewinnen. Sie zerfleischen zwergische Prospektoren und hinterlassen Gräben voller zerschlagener Kisten und zurückgelassener Spitzhacken."},{t="Blut in den Gräben",b="Raptoren haben in den Ausgrabungsgruben Nester angelegt. Vom Bergrücken über der Ausgrabung schickt Ormer Euch in den Schlamm, um die ausgewachsenen Bestien anzugreifen. Ausgrabungsleiter Whelgar und seine Mannschaft hoffen, uralte Relikte zu bergen, doch Ormer ist von Rache zerfressen. Er verlangt einen hohen Blutzoll an toten Sensenklauen und Rasiermessern, bevor er sich dem größten Schrecken der Stätte zuwendet."}},faq={{q="Warum ist Ormer so wütend auf diese Raptoren?",a="Die gesprenkelten Raptoren überrannten die Ausgrabungsstätte von Whelgar, vertrieben das Zwergenteam und schlachteten alle ab, die nicht entkommen konnten. Ormer Eisenzopf wurde vertrieben und blieb verbittert zurück, und er wird den Bestien die Ausgrabung nicht überlassen, ohne sie mit Blut bezahlen zu lassen.",al={"warum ist ormer wütend","ormers rache grund","warum raptoren im sumpfland töten"}},{q="Wo sind die gesprenkelten Sensenklauen und Rasiermesser zu finden?",a="Gesprenkelte Sensenklauen und Rasiermesser durchstreifen die unteren Ausgrabungsgräben und die umliegenden Erdwälle an der Ausgrabungsstätte von Whelgar, östlich vom Hafen von Menethil und südwestlich von Dun Modr im Sumpfland.",al={"gesprenkelte sensenklaue fundort","gesprenkeltes rasiermesser fundort","wo raptoren für ormer finden"}},{q="Wer ist Ormer Eisenzopf?",a="Ormer Eisenzopf ist ein zwergisches Mitglied der Explorers' League, das an der Ausgrabungsstätte von Whelgar stationiert ist. Nachdem die Ausgrabung überrannt wurde, machte er es zu seiner persönlichen Aufgabe, das Raptorenrudel auszurotten, das ihre Arbeit heimsucht.",al={"wer ist ormer","ormer eisenzopf geschichte"}},{q="Was geschieht nach der Dezimierung dieser Raptoren?",a="Nachdem Ihr die Sensenklauen und Rasiermesser dezimiert habt, wendet Ormer seine Aufmerksamkeit Sarltooth zu, dem großen Raptor, den er für den Anführer des örtlichen Rudels hält. Er schickt Euch los, um die Ursache der Raptorenplage zu beseitigen.",al={"was kommt nach ormers rache","ormers rache fortsetzung","nächste quest nach sensenklauen"}},{q="Hängt diese Quest mit anderen Aufgaben an der Ausgrabungsstätte zusammen?",a="Ja. Während Ihr für Ormer im unteren Ausgrabungsbereich Raptoren jagt, könnt Ihr auch Ausgrabungsleiter Whelgar und seinem Team bei „Uncovering the Past“ helfen, indem Ihr irdene Artefaktfragmente sammelt, die in denselben Gräben verstreut liegen.",al={"ausgrabungsstätte von whelgar quests","uncovering the past zusammenhang"}},{q="Warum haben die Zwerge hier überhaupt gegraben?",a="Die Explorers' League aus Eisenschmiede gründete die Ausgrabungsstätte von Whelgar, um nach Titanenrelikten zu suchen und die uralte Geschichte des Zwergenvolkes aufzudecken. Aggressive Wildtiere brachten ihre Arbeit zum Erliegen, als sie die Ausgrabung überrannten.",al={"warum im sumpfland graben","ausgrabungsstätte von whelgar zweck"}}},fx={["2ccf3294"]={q="Was sind Gefleckte Sensenklauen und Gefleckte Reißmäuler?",a="Diese bösartigen Raptorarten durchstreifen die unteren Ebenen der Whelgar-Ausgrabungsstätte. Bekannt für ihre Blutgier und messerscharfen Krallen, überrannten sie die Zwergenausgräber und vertrieben sie aus ihren Arbeitsgruben. Ormer weist Euch nun an, ihre tödlichsten Varietäten zu jagen, um ihre Vorherrschaft über die Ruinen zu brechen.",al={"was sind sensenklauen und reißmäuler","gefleckte sensenklauen","gefleckte reißmäuler","sumpfland raptoren"}},f1520877={q="Warum benötigt Ormer, dass Ihr die Raptoren jagt, anstatt sich selbst darum zu kümmern?",a="Ormer und die überlebenden Ausgrabungsleiter wurden auf den Grat oberhalb der Ausgrabungsstätte vertrieben. Da ihr Ausgrabungsteam verstreut oder getötet wurde, fehlt ihnen das Personal, um allein einen aggressiven Gegenangriff zu starten, und sie benötigen fähige Abenteurer, die bereit sind, in ihrem Namen tief in die verseuchten Gruben hinabzusteigen.",al={"warum braucht ormer hilfe","warum tötet ormer raptoren nicht","warum ich ormer"}}},fp="15,217,19.338.0,21.341.0,39.256.0,54.188.0,23.214.0,41.196.1,62.208.0,53.217.0"}
P.entries["quest:2950"] = {n="Noggs Ringerneuerung",s="In Orgrimmar will Nogg einen Ring aus Gnomeregan verbessern. Er verlangt seltene Materialien und Nachrichten über die Dunkeleisenzwerge und hofft zu beweisen, dass Goblinhandwerk gnomischer Baukunst überlegen ist.",h="In Orgrimmar will Nogg einen Ring aus Gnomeregan verbessern.",kw={"blitzender goldring","dunkeleisen","gnomeregan","gobliningenieurskunst","moosachat","nogg","orgrimmar","silberbarren"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr Technologie aus Hallen, die der Allianz verbunden sind, etwa Gnomeregan, zu Orgrimmars Tüftlern bringen. Das gibt der Horde Einblick in die Fähigkeiten ihrer Feinde.",["profession:Engineering"]="Als Ingenieur erlebt Ihr die Rivalität zwischen goblinischem Erfindergeist und gnomischen Apparaturen. Goblins verändern bestehende Geräte kühn, um das Beste aus ihnen herauszuholen.",["profession:Mining"]="Als Bergarbeiter könnt Ihr helfen, Nogg mit einem verhütteten Silberbarren und einem Moosachat zu versorgen, die Ihr durch Bergbau und Edelsteinschleifen gewinnt."},sec={{t="Goblinische Überlegenheit",b="Ihr bringt einen gereinigten Goldring aus Gnomeregan zu Noggs Werkstatt im Tal der Ehre. Der Gobliningenieur begutachtet die schlichte gnomische Arbeit und bietet Euch einen Handel an. Bringt ihm Rohmaterialien und eine kleine Gebühr, und er wird den Reif mit Silber und Moosachat einfassen. Das Gitter soll die darin ruhende Magie verstärken."},{t="Eine zwergische Spur",b="Noggs Angebot geht über den Handel hinaus. Er hat gehört, dass sich Dunkeleisenzwerge in der belagerten Gnomenstadt aufhalten. Ihre Anwesenheit könnte die plötzlichen Fortschritte der Gnome im Maschinenbau erklären, einem Handwerk, das Goblins für sich beanspruchen. Eure Informationen bringen Euch einen verbesserten Ring und Noggs widerwilligen Respekt ein."}},faq={{q="Wer ist Nogg?",a="Nogg ist ein Gobliningenieur im Tal der Ehre in Orgrimmar. Er arbeitet mit anderen Tüftlern im Drag und im Tal der Ehre und untersucht ungewöhnliche mechanische Artefakte und Baupläne von gefährlichen Expeditionen.",al={"wer ist nogg","nogg orgrimmar","nogg npc"}},{q="Welche Materialien werden benötigt, um den Ring neu zu schmieden?",a="Nogg verlangt den ursprünglichen Blitzenden Goldring, einen Silberbarren, einen Moosachat und dreißig Silbermünzen, um seine Arbeit und die Werkstattkosten zu decken.",al={"ringmaterialien","nogg materialien","was braucht nogg"}},{q="Warum interessiert sich Nogg für Gnomeregan?",a="Gnomeregan ist von großem technologischem Wert. Goblins stehen auf technischen Gebieten in erbittertem Wettstreit mit Gnomen, und Nogg fragt sich, ob Dunkeleisenzwerge an den technologischen Anomalien in der gefallenen Technostadt beteiligt waren.",al={"warum interessiert sich nogg für gnomeregan","gnomeregan interesse der goblins"}},{q="Was genau macht Nogg mit dem Ring?",a="Nogg fertigt ein Gitter aus Silber und Moosachat um den Goldreif an. Dieses Gerüst lenkt und stabilisiert die Verzauberungen des Rings und macht ihn stärker als die ursprüngliche gnomische Konstruktion.",al={"hintergrund der ringverbesserung","was ändert sich am ring"}},{q="Wo beginnt diese Questreihe?",a="Die Reihe beginnt tief in Gnomeregan. Ihr findet einen Grime-Encrusted Ring bei einem Dunkeleisenzwerg und reinigt ihn dann mit der Maschine Sparklematic 5200.",al={"beginn der questreihe","wie beginnt noggs quest","beginn der ringquestreihe"}},{q="Warum verdächtigt Nogg die Dunkeleisenzwerge?",a="Gobliningenieure misstrauen gnomischen Neuerungen. Nogg vermutet hinter jedem plötzlichen Fortschritt der Gnome im Maschinenbau eine Einmischung von außen, besonders durch den intriganten Clan der Dunkeleisenzwerge.",al={"warum dunkeleisenzwerge","verbindung zu dunkeleisenzwergen"}}},fx={e11b7fb8={q="Warum will Nogg den Ring umschmieden?",a="Nogg beansprucht den Ring nicht für sich, ist Euch aber aufrichtig dankbar für die Informationen, die Ihr bezüglich der Dunkeleisenzwerge in Gnomeregan zurückgebracht habt. Als Gobliningenieur kann er es sich zudem nicht verkneifen, sein überlegenes Handwerk zur Schau zu stellen: Er möchte unbedingt beweisen, dass er die plumpe Arbeit der Gnomtüftler übertreffen kann, indem er ihr Design mit einem weitaus mächtigeren magischen Gitter verbessert.",al={"warum bietet nogg an, den ring umzuschmieden","warum ring umschmieden","noggs motiv ring umschmieden"}},["63dec8fa"]={q="Wofür wird der Silberbarren in 'Nogg's Ring Redo' verwendet?",a="Nogg verwendet den Silberbarren, um ein verfeinertes strukturelles Gitter um den Ring zu schmieden. Dieses filigrane Metallgerüst dient als physische Hülle, die benötigt wird, um zusätzliche magische Verzauberungen zu binden, ohne den bestehenden Kern des Rings zu stören.",al={"wofür ist der silberbarren","silberbarren nogg","warum silberbarren ring umschmieden"}},c138af81={q="Wofür wird der Moosachat in 'Nogg's Ring Redo' verwendet?",a="Der Moosachat wird in das neue Silbergeflecht eingearbeitet, das Nogg für Euren Ring erschafft. Seine inhärenten mineralischen Eigenschaften helfen dabei, die latente magische Energie, die in dem Stück enthalten ist, zu kanalisieren und zu verstärken, wodurch aus einem einfachen Gnomenschmuckstück ein weitaus mächtigeres Artefakt wird.",al={"wofür ist der moosachat","moosachat nogg","warum moosachat ring umschmieden"}}},fp="16,182,18.310.0,15.290.1,12.216.0,46.144.0,37.215.0,39.182.0,34.140.0,40.171.0"}
P.entries["quest:2951"] = {n="Der Funkelmat 5200!",s="In Gnomeregan reinigt der Funkelmat 5200! weiterhin geborgene Wertsachen für drei Silbermünzen. Gnomischer Erfindungsgeist hält ihn im Chaos der zerstörten Stadt am Laufen.",h="In Gnomeregan reinigt der Funkelmat 5200!",kw={"reiniger","gnom","gnomeregan","schmutzverkrustet","maschine","bergung","funkelmat","funkelmat 5200","trogg"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr mit dem Funkelmat geborgene Relikte in Gnomeregan reinigen, bevor Ihr sie nach Eisenschmiede zurückbringt.",["profession:Engineering"]="Als Ingenieur könnt Ihr den Motor und den Sortiermechanismus würdigen, die unbekannten Schutt reinigen und verarbeiten, ohne zu klemmen oder zu explodieren.",["race:Gnome"]="Als Gnom könnt Ihr die Widerstandskraft Eures Volkes in einer Reinigungsmaschine erkennen, die inmitten der Verwüstung seiner Heimat weiterarbeitet."},sec={{t="Ein Licht im Schmutz",b="Eine kleine Gruppe überlebender Gnome hält einen gesicherten Bereich beim Funkelmat 5200! in Gnomeregan. Die Maschine schrubbt hartnäckigen Schmutz aus den unterirdischen Tiefen von geborgenen Wertsachen. Troggs und andere unterirdische Kreaturen hämmern gegen die Schotten, doch sie bleibt bereit für alles, was Ihr bringt."},{t="Rasender Betrieb",b="Legt ein schmutzverkrustetes Relikt und drei Silbermünzen in den Funkelmat, und die Reinigung beginnt. Die eiserne Maschine ächzt, vibriert und ruckt, während sie giftigen Schlamm, verstrahltes Fett und Gesteinsstaub abträgt. Augenblicke später spuckt sie aus, was unter dem Dreck lag, von kostbaren Mineralien bis hin zu mechanischen Bauteilen."}},faq={{q="Was ist der Funkelmat 5200?",a="Der Funkelmat 5200! ist eine automatische gnomische Reinigungsmaschine in einem geschützten Bereich von Gnomeregan. Er entfernt radioaktives Fett, Schlamm und Schmutz von verkrusteten Gegenständen, die in der gefallenen Stadt geborgen wurden.",al={"was macht der funkelmat 5200","funkelmat maschine","reinigungsmaschine gnomeregan"}},{q="Was benötigt die Maschine zum Betrieb?",a="Der Funkelmat benötigt ein Schmutzverkrustetes Objekt, das unter Gnomeregans Monstern und Trümmern zu finden ist, sowie drei Silbermünzen in seinem Münzschlitz.",al={"wie benutzt man den funkelmat","funkelmat kosten","was kommt in den funkelmat"}},{q="Warum steht mitten in einem Kriegsgebiet eine betriebsbereite Maschine?",a="Überlebende Gnome zogen sich in befestigte Werkstätten zurück, nachdem die Trogg-Invasion und giftige Ausströmungen Gnomeregan verwüstet hatten. Maschinen wie der Funkelmat blieben dort unversehrt und mit Energie versorgt, sodass der Komfort automatischer gnomischer Werkzeuge erhalten blieb.",al={"warum steht der funkelmat hier","wer hat den funkelmat in gnomeregan aufgestellt"}},{q="Was kommt nach der Reinigung eines schmutzverkrusteten Gegenstands heraus?",a="Der Funkelmat gibt den geborgenen Gegenstand gereinigt zurück und enthüllt, was unter dem Dreck lag. Das können Handelswaren, Steine fürs Handwerk, Edelsteine oder Ersatzteile für Ingenieurskunst sein.",al={"was bekommt man vom funkelmat","funkelmat beute","schmutzverkrustetes objekt belohnungen"}},{q="Kann ich den Funkelmat 5200 mehr als einmal benutzen?",a="Ja. Ihr könnt den Funkelmat wiederholt benutzen, indem Ihr weitere schmutzverkrustete Objekte und für jede Reinigung drei Silbermünzen mitbringt.",al={"ist der funkelmat wiederholbar","mehrere schmutzverkrustete gegenstände reinigen","mehr funkelmat"}},{q="Warum rüttelt die Maschine während der Reinigung so heftig?",a="Gnomeregans verkrusteter Schmutz ist dicht, giftig und verhärtet. Die Rüttelbewegungen und inneren Schrubber des Funkelmats tragen ihn ab, sodass das Gehäuse ruckt und ächzt.",al={"funkelmat rütteln","ist der funkelmat kaputt"}}},fx={["3b5f4e4c"]={q="Warum führt der Sparklematic 5200 dies aus?",a="Der Sparklematic 5200 ist kein empfindungsfähiges Wesen, sondern ein automatisiertes Gnomengerät, das für einen einzigen kommerziellen Zweck gebaut wurde: das Reinigen von schmutzigen, verkrusteten Wertgegenständen für zahlende Kunden. Wie auf seiner Messingplakette beworben, ist er darauf ausgelegt, ruinierte, schlammbedeckte Relikte, die aus den verseuchten Hallen von Gnomeregan geborgen wurden, für drei Silbermünzen zu reinigen. Er verfolgt keine persönlichen Ziele, abgesehen davon, seine Programmierung zu erfüllen, wann immer er mit dem richtigen Brennstoff und Münzen gefüttert wird.",al={"warum will sparklematic gegenstände","sparklematic 5200 zweck","warum sparklematic füttern"}},["757f94ef"]={q="Wozu dient das Schmutzverkrustetes Objekt?",a="Ein Schmutzverkrustetes Objekt ist ein nicht identifizierbares Stück geborgener Gnomentechnologie, Mineralerz oder persönlicher Schmuck, das mit dem giftigen Schlamm und der Strahlung, die Gnomeregan überfluten, bedeckt ist. In seinem verschmutzten Zustand ist der Gegenstand völlig nutzlos und seine wahre Natur bleibt verborgen. Wenn Ihr es in den Sparklematic 5200 gebt, schrubbt er den radioaktiven Schlamm und die ätzenden Ablagerungen ab und enthüllt, welche wertvolle Ausrüstung, Edelsteine oder Metallschrott darunter liegen.",al={"was ist schmutzverkrustetes objekt","schmutzverkrustetes objekt zweck","warum schmutzverkrustetes objekt behalten"}}},fp="22,160,21.270.0,18.308.0,30.198.0,41.141.0,64.236.0,53.167.0,47.125.0,56.162.0"}
P.entries["quest:2952"] = {n="Der Funkelmat 5200!",s="In Gnomeregan nimmt der Funkelmat 5200! verschmutzte Fundstücke auf und reinigt sie. Seine Reinigungszyklen scheuern giftigen Schmutz ab und verpacken dann alles, was übrig bleibt, in einer Geschenkbox.",h="In Gnomeregan nimmt der Funkelmat 5200!",kw={"reinigung","apparatur","dekontamination","gnomeregan","schmutz","maschine","funkelmat"},ang={["profession:Engineering"]="Als Ingenieur könnt Ihr untersuchen, wie der Funkelmat selbst bei starker Strahlung automatisch Partikel entfernt und Gegenstände schnell verpackt.",["race:Gnome"]="Als Gnom erinnert Euch der Funkelmat an Eure Heimat vor dem Fall. Selbst eine industrielle Reinigungseinheit klingelte fröhlich und verpackte ihr fertiges Werk wie ein Geburtstagsgeschenk."},sec={{t="Automatische Reinigung",b="Füllt giftigen und verseuchten Abfall in den Funkelmaten 5200!, und seine Reinigungszyklen scheuern Schmutz und ätzende Rückstände ab. Sobald die Maschine beladen und bezahlt ist, rattert sie durch ihr Programm. Ein fröhliches Klingeln ertönt, dann enthält ein mit einer Schleife verschnürtes Geschenk alles, was übrig bleibt."},{t="Schätze im Schlamm",b="Als Gnomeregan an die Troggs fiel, begruben Strahlung und industrieller Morast persönliche Gegenstände und technische Überreste unter sich. Füllt Schmutzverkrustete Objekte in die Maschine, und sie birgt womöglich Edelsteine, Roherze und andere Wertsachen, die bei der Entlüftung der Stadt verschlungen wurden."}},faq={{q="Was macht der Funkelmat 5200?",a="Der Funkelmat 5200! reinigt Gegenstände in Gnomeregan. Gebt ein Schmutzverkrustetes Objekt hinein und entrichtet eine Münzgebühr, und er scheuert Schlamm, Schmutz und radioaktiven Dreck ab. Was übrig bleibt, kommt in einer kleinen Geschenkbox zurück.",al={"was ist der funkelmat 5200","wie funktioniert der funkelmat","funktion des funkelmaten"}},{q="Wo steht der Funkelmat 5200?",a="Der Funkelmat 5200! steht in den Gängen des gefallenen Gnomeregan, nahe der Clean Zone, wo einst Überlebende und automatische Dekontaminationssysteme tätig waren.",al={"standort des funkelmaten","wo ist die reinigungsmaschine","funkelmat finden"}},{q="Warum verpackt die Maschine Gegenstände mit einer Schleife?",a="Gnomischer Spieltrieb bescherte dem Funkelmaten 5200! seine abschließende Schleifenverzierung. Nachdem er radioaktiven Niederschlag und giftigen Schmutz von einem Gegenstand entfernt hat, verpackt er ihn wiederhergestellt als ordentlich verschnürtes Geschenk.",al={"warum geschenkbox","funkelmat verpacktes geschenk","mit schleife verpackt"}},{q="Können Abenteurer der Horde den Funkelmaten 5200 benutzen?",a="Ja. Der Funkelmat 5200! arbeitet automatisch und beachtet keine Fraktionszugehörigkeit. Werft Münzen und verschmutzte Gegenstände ein, und er startet seinen Reinigungszyklus.",al={"horde funkelmat","kann die horde schmutz entfernen","ist der funkelmat neutral"}},{q="Kann ich den Funkelmaten mehrfach benutzen?",a="Ja. Nach seinem ersten Einsatz kann der Funkelmat 5200! erneut Gegenstände reinigen. Bringt Schmutzverkrustete Objekte, die Ihr überall im Dungeon findet, um sie einem weiteren Reinigungszyklus zu unterziehen.",al={"ist der funkelmat wiederholbar","more sparklematic action","schmutzverkrustete objekte farmen"}},{q="Was geschieht nach dieser Quest?",a="Nach der ersten Reinigung könnt Ihr den wiederholbaren Reinigungszyklus More Sparklematic Action nutzen, um weitere schmutzverkrustete Fundstücke zu reinigen, die Ihr bei Euch tragt.",al={"nächste quest nach dem funkelmaten","was folgt auf den funkelmaten 5200"}}},fx={["1a7da75f"]={q="Warum benötigt der Sparklematic 5200 Schmutzverkrustete Objekte?",a="Der Sparklematic 5200 besitzt keine persönlichen Ambitionen – er ist ein automatisiertes Wunderwerk gnomischer Ingenieurskunst, das darauf ausgelegt ist, geborgene Waren zu reinigen und wiederherzustellen. Vor dem Fall von Gnomeregan erbaut, besteht seine programmierte Funktion darin, dicke Schichten radioaktiven Schlamms und Trümmer abzuwaschen und alles, was übrig bleibt, in einem ordentlichen, verpackten Päckchen für seinen Benutzer bereitzustellen.",al={"warum will der sparklematic dies","sparklematic 5200 zweck","warum schmutzverkrustete objekte reinigen"}}},fp="22,164,19.252.0,22.257.0,35.204.0,39.157.0,41.174.0,48.134.0,42.171.0,30.140.0"}
P.entries["quest:2953"] = {n="Funkelmatastisch",s="In Gnomeregan reinigt der Sparklematic 5200 noch immer alles, was sich retten lässt. Bei der Evakuierung der Stadt zurückgelassen, schrubbt er gegen eine geringe Silbergebühr Schmutz und radioaktiven Schlamm von Kuriositäten.",h="In Gnomeregan reinigt der Sparklematic 5200 noch immer alles, was sich retten lässt.",kw={"automatisierung","reinigungsmaschine","reinigung","gnomeregan","schmutzverkrustet","sparklematic"},ang={["profession:Engineering"]="Als Ingenieur könnt Ihr die robusten gnomischen Reinigungszyklen mit Lösungsmitteln und die münzbetriebenen Mechanismen des Geräts aus nächster Nähe studieren.",["race:Gnome"]="Als Gnom könnt Ihr im Sparklematic die mechanische Ausdauer Eures Volkes erkennen, während er inmitten der giftigen Ruinen Eurer Heimat weiterarbeitet."},sec={{t="Automatisierte Wiederherstellung",b="Vor der Trogg-Invasion und dem darauffolgenden radioaktiven Niederschlag installierten Gnomeregans Ingenieure überall in der Stadt automatisierte Geräte. Giftiger Abfall und feindselige Automaten füllen heute ihre Korridore. Doch der Sparklematic 5200 folgt genau seiner Programmierung: Er benötigt drei Silbermünzen und ein schmutzverkrustetes Artefakt, um zu beginnen."},{t="Wunder aus dem Schlamm",b="Der Sparklematic ruckelt, während er ein eingelegtes Relikt mit starken gnomischen Lösungsmitteln besprüht und sauber schrubbt. Ein fröhliches Klingeln verkündet das Ende des Durchlaufs, und die Maschine gibt eine ordentlich verpackte Schachtel aus. Darin liegt alles Verwertbare, was unter ätzendem Trogg-Schleim und giftigem Unrat erhalten geblieben ist."}},faq={{q="Was ist der Sparklematic 5200?",a="Der Sparklematic 5200 ist ein automatisiertes gnomisches Reinigungsgerät in Gnomeregan. Er entfernt ätzenden Schlamm, Schmutz und radioaktive Rückstände von geborgenen Gegenständen und hinterlässt verwertbare Fundstücke, die sich bestimmen lassen.",al={"sparklematic 5200","was macht die maschine","gnomeregan reinigungsgerät"}},{q="Warum verlangt die Maschine Münzen?",a="Der Sparklematic benötigt drei Silbermünzen, um einen Reinigungsdurchlauf zu beginnen. Ein Grund für die Gebühr wird nicht genannt.",al={"warum silber bezahlen","sparklematic kosten"}},{q="Welche Gegenstände lassen sich hineinlegen?",a="Die Maschine reinigt schmutzverkrustete Gegenstände, darunter Relikte, die von gefallenen Troggs, verderbten Wachposten und verstrahlten Schrecken in Gnomeregans Tunneln geborgen wurden.",al={"schmutzverkrustetes objekt","welche gegenstände lassen sich reinigen"}},{q="Ist der Sparklematic vor Strahlung sicher?",a="Radioaktiver Abfall füllt Gnomeregans äußere Tunnel, doch der Sparklematic 5200 funktioniert noch immer. Seine speziellen gnomischen Reinigungsmittel entfernen gefährliche Rückstände von eingelegten Gegenständen.",al={"sparklematic verstrahlt","sparklematic verseuchung"}},{q="Können beide Fraktionen den Sparklematic 5200 benutzen?",a="Ja. Der Sparklematic 5200 ist eine automatisierte mechanische Anlage, die Zahlungen und schmutzverkrustete Gegenstände von Besuchern beider Fraktionen annimmt.",al={"horde sparklematic","wer kann ihn benutzen"}},{q="Wer hat den Sparklematic entworfen?",a="Der Schöpfer des Sparklematic wird nicht namentlich genannt. Die gnomische Reinigungsmaschine funktioniert noch immer in Gnomeregan.",al={"sparklematic schöpfer","wer hat den sparklematic gebaut"}}},fx={["9d072b2b"]={q="Warum muss der Sparklematic 5200 betrieben werden?",a="Der Sparklematic 5200 ist ein automatisiertes Gnomengerät, das für einen einzigen Zweck entwickelt wurde: das Abschrubben von schwerem, unterirdischem Schlamm und industriellen Ablagerungen von kontaminierter Ausrüstung. Als Maschine hegt er keine großen Ambitionen oder versteckten Absichten; er wartet einfach auf die angemessene Gebühr und Schmutzverkrustete Objekte, um seine Reinigungszyklen zu aktivieren und restaurierte Waren auszugeben.",al={"warum sparklematic betreiben","sparklematic motiv","warum sparklematic 5200 benutzen"}}},fp="24,191,21.313.0,21.282.0,30.201.0,34.103.0,40.158.0,40.180.0,44.149.0,30.100.0"}
P.entries["quest:2954"] = {n="Der Steinbehüter",s="Am Podest von Uldum bewacht der Steinbehüter den Zugang zur Anlage. Ihr habt die Platinscheiben durch Tanaris getragen, und nun fordert er Euch auf, seine Geschichte zu erfahren, bevor Ihr weitergeht.",h="Am Podest von Uldum bewacht der Steinbehüter den Zugang zur Anlage.",kw={"schöpfer","tafeln von uldum","platinscheiben","steinbehüter von norgannon","tanaris","uldaman","uldum","podest von uldum"},sec={{t="Ein Wächter am Podest",b="Am Podest von Uldum versperrt der Steinbehüter den Weg in die Anlage von Uldum. Ihr habt die Platinscheiben durch Tanaris gebracht. Der Wächter erklärt, dass der Einlass nur gestattet ist, wenn die Tafeln von Uldum zu Eurem Scheibensatz gehören. Erfahrt die Geschichte des Behüters und benutzt dann das Podest."},{t="Was der Behüter erklärt",b="Der Steinbehüter kontrolliert im Namen der Schöpfer den Zugang zur Anlage von Uldum. Er gewährt nur jenen Einlass, die die richtigen Sequenzierungsscheiben besitzen. Die Tafeln von Uldum werden von den Schöpfern hergestellt und zeichnen ihre Arbeit in Uldum auf. Sie sind fast so groß wie Eure eigenen Scheiben, doch ihre Markierungen betreffen Uldum statt Uldaman.\n\nUldum ist eine Forschungseinrichtung, in der die Schöpfer daran arbeiten, Azeroths Biosphäre zu verbessern. Nur wer die Tafeln besitzt, kann die Einzelheiten dieser Arbeit erfahren. Der Behüter verspricht, Euch Eure Scheiben zurückzugeben, sobald Ihr das Podest benutzt. Er wird Euch die Anlage betreten lassen, wenn die Tafeln zu Eurem Scheibensatz gehören."},{t="Mehr vom Behüter",b="Der Steinbehüter erklärt, dass die Schöpfer die Verteilung der Scheiben für jede Anlage auf dieser Welt kontrollieren. Azeroth wurde für eine Heimsuchung neu eingeplant. Die Schöpfer nutzen Heimsuchungen, um die Kontrolle über besiedelte Welten wiederherzustellen, wenn Kräfte von außen oder innen das Gleichgewicht ihrer Matrixdynamik stören. Der Behüter warnt, dass eine Heimsuchung nicht auf die leichte Schulter zu nehmen ist."}},faq={{q="Wer ist der Steinbehüter von Norgannon?",a="Am Podest von Uldum in Tanaris bewacht der Steinbehüter den Zugang zur Anlage von Uldum und entscheidet, wer eintreten darf.",al={"was ist der steinbehüter","wer ist der behüter bei uldum","identität des steinbehüters"}},{q="Warum verweigert der Steinbehüter den Einlass?",a="Der Steinbehüter gewährt nur jenen Einlass, deren Scheibensatz die Tafeln von Uldum enthält. Euer Scheibensatz enthält sie noch nicht.",al={"warum ist uldum nicht zugänglich","tafeln von uldum fehlen","einlass nach uldum verweigert"}}},fp="17,183,26.264.0,25.593.1,21.356.2,38.113.0,38.116.0"}
P.entries["quest:296"] = {n="Ormers Rache",s="Ormer Eisenzopf sinnt an der Whelgar Excavation Site auf Rache. Er glaubt, dass Sarltooth den Raptorenangriff anführte, bei dem zwergische Ausgräber abgeschlachtet wurden, und bittet Euch, eine seiner Klauen als Beweis zurückzubringen.",h="Ormer Eisenzopf sinnt an der Whelgar Excavation Site auf Rache.",kw={"explorer's league","ormer eisenzopf","raptoren","sarltooth","klaue","sumpfland","whelgar excavation site"},ang={["class:Hunter"]="Als Jäger steht Ihr einem der Spitzenprädatoren des Sumpflands gegenüber. Eure ausgeprägte Fährtenkunst führt Euch den Felsgrat hinauf zum Rudelführer.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, zwergische Expeditionen in den Marschen zu sichern und die Stützpunkte der Allianz zwischen Eisenschmiede und den nördlichen Landen zu erhalten.",["race:Dwarf"]="Als Zwerg ehrt Ihr die gefallenen Untertanen von König Magni, indem Ihr die an der Whelgar Excavation Site abgeschlachtete Mannschaft der Explorer's League rächt."},sec={{t="Ein Schlag gegen den Rudelführer",b="Nachdem die Ausgräber der Explorer's League an der Whelgar Excavation Site abgeschlachtet worden waren, beobachtete Ormer Eisenzopf die Raptoren von seinem Felsgrat aus. Eine Bestie überragte die anderen. Sarltooth thronte über den Ausgrabungen, wo Ormer sah, wie er das Rudel anführte, das die Zwerge vertrieb. Für Ormer war Sarltooth mehr als eine wilde Bestie. Er glaubte, dass er den Angriff auf die Untertanen von König Magni Bronzebart angeführt hatte."},{t="Gerechtigkeit im Sumpfland",b="Ormer fordert den Tod als Vergeltung für das Massaker. Er schickt Euch die hoch gelegenen Pfade entlang der Ausgrabungswände hinauf, um Sarltooth zu töten. Bringt eine der furchterregenden Klauen des Raptors zurück, und die gefallenen Arbeiter werden gerächt sein. Ormer will die Marschen wissen lassen, dass Angriffe auf zwergische Expeditionen nicht unbeantwortet bleiben."}},faq={{q="Wer ist Sarltooth?",a="Sarltooth ist ein großer Raptor, der das Rudel an der Whelgar Excavation Site im Sumpfland anführt. Ormer Eisenzopf glaubt, dass Sarltooth den Angriff lenkte, bei dem die zwergischen Ausgräber massakriert wurden.",al={"was ist sarltooth","wer ist der raptorenboss","sarltooth hintergrundgeschichte"}},{q="Wo befindet sich Sarltooth?",a="Sarltooth streift auf einem erhöhten Pfad entlang der westlichen Wand in der nordwestlichen Ecke der Whelgar Excavation Site umher.",al={"sarltooth finden","wo erscheint sarltooth","sarltooths pfad"}},{q="Warum will Ormer Sarltooth töten, statt ihn nur zu vertreiben?",a="Ormer betrachtet den Raptorenangriff als Verbrechen gegen die Untertanen von König Magni. Zwergische Arbeiter starben bei ihrer Arbeit, und Ormer glaubt, dass nur Sarltooths Tod das Andenken der Gefallenen wieder zu Ehren bringen kann.",al={"grund für ormers rache","warum sarltooth töten"}},{q="Welchen Beweis verlangt Ormer?",a="Ormer verlangt eine von Sarltooths Klauen als Beweis dafür, dass das gewaltige Raubtier getötet wurde.",al={"sarltooth beweis","sarltooths klaue"}},{q="Wer waren die Opfer an der Ausgrabungsstätte?",a="Die Opfer waren zwergische Archäologen und Arbeiter, die von der Explorer's League entsandt worden waren, um Titanenartefakte freizulegen. Raptorenrudel überraschten sie und schlachteten sie ab, als sie die Ausgrabungsstätte überrannten.",al={"wer starb bei whelgar","opfer der ausgrabungsstätte"}},{q="Ist die Ausgrabungsstätte sicher, wenn Sarltooth getötet wird?",a="Sarltooths Tod beseitigt die tödlichste Bedrohung des Rudels und bringt Vergeltung für die Gefallenen. Noch immer wimmeln die Gräben von Raptoren, und die Stätte bleibt gefährlich und weitgehend verlassen.",al={"ist whelgar jetzt sicher","hat ormer gewonnen"}}},fp="15,195,27.390.0,23.296.0,17.180.0,27.109.0,68.194.0,30.90.0,44.193.0,50.181.0"}
P.entries["quest:2962"] = {n="Das einzige Heilmittel ist mehr grünes Leuchten",s="In Kharanos sucht Ozzie Wechselvolt ein Heilmittel für die leprösen Gnome. Er braucht eine reine Falloutprobe aus den Tiefen Gnomeregans.",h="In Kharanos sucht Ozzie Wechselvolt ein Heilmittel für die leprösen Gnome.",kw={"gnogaine","gnomeregan","hall of gears","kharanos","lepröser gnom","ozzie wechselvolt","strahlung","radioaktiver fallout"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr helfen, Dun Morogh zu sichern und Gnomeregan zurückzuerobern, indem Ihr lernt, den tödlichen Gefahren vor Eisenschmiedes Toren zu begegnen.",["profession:Engineering"]="Als Ingenieur wisst Ihr, dass Strahlung eine robuste Bleiabschirmung und präzise Instrumente erfordert. Gnomeregan zeigt den Preis technischen Versagens.",["race:Gnome"]="Als Gnom tragt Ihr die Trauer um Eure verlorene Heimat in Euch. Ozzie dabei zu helfen, herauszufinden, ob sich die Mutationen rückgängig machen lassen, bietet Hoffnung auf Rettung für Eure gefallenen Artgenossen."},sec={{t="Eine reine Probe",b="Ozzie Wechselvolts erste Versuche außerhalb von Gnomeregan lieferten ihm keine Antworten. Die Troggs in Dun Morogh trugen zu wenige Rückstände in sich, und diese waren unrein. Nun sucht Ozzie von seinem Labor in Kharanos aus eine frische, konzentrierte Probe aus den Tiefen der Stadt. Er hofft, damit ein Heilmittel für die leprösen Gnome zu finden."},{t="Direkt von der Quelle",b="Ihr müsst hochwirksamen Fallout aus dem Inneren Gnomeregans sammeln. Verstrahlte Schrecken, Lauerer und Schleime bevölkern die unteren Tiefen rund um Hall of Gears und Clean Zone. Ihr instabiler Glibber muss in einer schweren Bleiphiole transportiert werden, und die Arbeit ist gefährlich. Der Fallout verliert rasch seine Wirksamkeit, also müsst Ihr ihn rechtzeitig zu Ozzies Labor in Kharanos bringen."}},faq={{q="Warum braucht Ozzie radioaktiven Fallout?",a="Ozzie Wechselvolt sucht ein Heilmittel für die leprösen Gnome, deren Geist und Körper durch den beim Fall Gnomeregans freigesetzten Fallout zerstört wurden. Er glaubt, dass eine reine Probe des Giftes helfen könnte, seine Auswirkungen rückgängig zu machen.",al={"ozzie wechselvolt heilmittel","warum grünes leuchten sammeln","heilmittel für lepröse gnome"}},{q="Wo findet der Spieler den Fallout?",a="Ihr könnt Fallout von lebenden verstrahlten Schrecken, Lauerern und Schleimen in Gnomeregans Tiefen sammeln, besonders rund um Hall of Gears und jenseits der Clean Zone.",al={"wo ist hochwirksame radioaktive ablagerung","fallout fundort gnomeregan"}},{q="Warum wurden die Proben der Troggs an der Oberfläche verworfen?",a="Die Troggs außerhalb von Gnomeregan waren zu wenig verseucht, und ihre Proben waren unrein. Sie konnten Ozzie kein verlässliches Material für seine Forschungen an einem Heilmittel liefern.",al={"warum keine troggs","was stimmte mit gnogaine nicht"}},{q="Warum gibt es für den Fallout ein Zeitlimit?",a="Der Fallout ist instabil und verliert selbst in einer Bleiphiole rasch seine Wirksamkeit. Er muss Ozzies Labor in Kharanos erreichen, bevor er zerfällt.",al={"warum verfällt fallout","fallout haltbarkeit"}},{q="Wer sind die leprösen Gnome, denen Ozzie helfen will?",a="Die leprösen Gnome waren Bürger Gnomeregans, die in der Stadt eingeschlossen waren, als die Strahlungsventile zur Bekämpfung der Troggs geöffnet wurden. Sie überlebten, wurden jedoch krank und wahnsinnig und begegnen ihren einstigen Artgenossen nun feindselig.",al={"geschichte der leprösen gnome","was sind lepröse gnome"}},{q="Wer erteilt diese Aufgabe?",a="Ozzie Wechselvolt ist ein gnomischer Forscher in Kharanos in Dun Morogh. Er bittet Euch, Fallout zu sammeln, während er daran arbeitet, die durch Gnomeregans Katastrophe verursachten Schäden zu heilen.",al={"wer vergibt die quest","ozzie wechselvolt standort"}}},fx={a4e93100={q="Wofür wird die Hochwirksame radioaktive Ablagerung verwendet?",a="Ozzie Wechselvolt benötigt die konzentrierte Ablagerung, um die intensive Strahlung zu untersuchen, die Gnomeregan verschlang. Sein ultimatives Ziel ist es, ein Heilmittel für die Lepragnome zu finden, seine verwandten Brüder, deren Geist und Körper durch die Katastrophe verzerrt wurden. Da frühere Oberflächenproben von umherwandernden Troggs sich als zu schwach und kontaminiert erwiesen, um verwertbare wissenschaftliche Ergebnisse zu liefern, benötigt er wirksame, unverdünnte Strahlung direkt von den Kreaturen im Inneren der zerstörten Stadt.",al={"wofür ist radioaktive ablagerung","nutzen hochwirksame ablagerung","zweck ablagerung ozzie"}},["089f8395"]={q="Welche Kreaturen jagt Ihr im Inneren von Gnomeregan?",a="Ihr werdet ausgesandt, um Proben von den verstrahlten Schlämmen, Lurkern und Schrecken zu sammeln, die in Gnomeregan vor sich hin faulen. Diese elenden Schlicke und mutierten Wesen bildeten sich direkt infolge des toxischen Ausstoßes, der während des Falls der Stadt freigesetzt wurde, und absorbierten massive Konzentrationen an rohem radioaktivem Abfall. Da sie die Ablagerungen in ihrem reinsten, aktivsten Zustand verkörpern, liefert das Extrahieren von Rückständen direkt aus ihnen die unverdünnte Wirksamkeit, die Ozzie für seine Forschung benötigt.",al={"was sind verstrahlte schlämme","wen töte ich für ablagerungen","gnomeregan ablagerung kreaturen"}}},fp="32,127,13.315.0,21.345.0,40.206.0,39.159.0,44.164.0,35.135.0,45.188.0,22.168.0"}
P.entries["quest:2969"] = {n="Freiheit für alle Kreaturen",s="Im Lager der Grimmtotem bittet Kindal Mondweber Euch, die gefangenen Feendrachen zu befreien. Weder Kindal noch Jer'kai weiß, was der Grimmtotemklan vorhat. Kindal begleitet Euch, während Jer'kai zurückbleibt.",h="Im Lager der Grimmtotem bittet Kindal Mondweber Euch, die gefangenen Feendrachen zu befreien.",kw={"bambuskäfig","elune","feendrache","feralas","truppenlager der grimmtotem","jer'kai","kindal mondweber","grimmlingflitzer"},sec={{t="Drachen im Gehege",b="Kindal Mondweber nennt den Grimmtotemklan abscheulich, weil er Feendrachen gefangen nimmt. Weder Kindal noch Jer'kai weiß, was der Klan vorhat, nur, dass er nichts Gutes im Schilde führt. Sie sind nicht stark genug, um sich ins Lager zu kämpfen, also bittet Kindal Euch, bei der Befreiung der Grimmlingflitzer zu helfen. Der Bambuskäfigschlüssel öffnet ihr Gehege, und Kindal möchte, dass sie lebend entkommen. Bringt starke Freunde mit, die Euch zur Seite stehen."},{t="Kindals Ausguck",b="Kindal wartet auf einem Felsvorsprung hinter dem Truppenlager der Grimmtotem, über dem Wasser. Ein Pfad führt die Felswand hinauf zu ihm. Kindal kämpft sich an Eurer Seite durch das Lager. Jer'kai bleibt zurück."},{t="Danach",b="Sobald die Darters frei sind, dankt Kindal Elune. Die befreiten Drachen bleiben womöglich nicht frei, daher wollen Kindal und Jer'kai den Kampf zu den Grimmtotem tragen. Kindal schickt Euch zu Jer'kai, um mit ihm zu sprechen."}},faq={{q="Wer nimmt die Feendrachen gefangen?",a="Kindal Mondweber sagt, dass der Grimmtotemklan die Feendrachen gefangen nimmt. Kindal und Jer'kai wissen nicht, was der Klan mit ihnen vorhat.",al={"wer hat die feendrachen gefangen","wer hat die sprite darters","käfige der grimmtotem"}},{q="Wo ist Kindal Mondweber?",a="Kindal Mondweber wartet auf einem Felsvorsprung hinter dem Truppenlager der Grimmtotem, über dem Wasser. Geht links am Truppenlager entlang, um hinter einem Baum einen Pfad zu finden, der die Felswand hinaufführt.",al={"wo ist kindal","kindal mondweber standort","wie kommt man zu kindal mondweber"}},{q="Kommt Jer'kai mit?",a="Nein. Jer'kai bleibt zurück, während Kindal Euch begleitet.",al={"hilft jerkai","jerkais beteiligung"}},{q="Was brauche ich, um die Grimmlingflitzer zu befreien?",a="Der Bambuskäfigschlüssel, den Kindal Euch gibt, öffnet das Gehege im Lager der Grimmtotem. Kindal bittet Euch, starke Freunde mitzubringen.",al={"bambuskäfigschlüssel","wie befreit man sprite darters"}},{q="Was folgt auf diese Quest?",a="Doling Justice folgt als Nächstes in der Questreihe.",al={"nächste quest nach freiheit für alle kreaturen","was folgt nach der rettung der sprite darters"}}},fp="25,205,18.379.0,16.179.0,9.200.1,36.136.0,27.163.0,24.53.0,42.122.0,24.39.0"}
P.entries["quest:297"] = {n="Götzen sammeln",s="An einer Ausgrabungsstätte umklammern Troggs die geschnitzten Idole, die Magmar Fellhew sucht. Die Relikte haben sie in gewalttätige Raserei versetzt.",h="An einer Ausgrabungsstätte umklammern Troggs die geschnitzten Idole, die Magmar Fellhew sucht.",kw={"raserei","geschnitzte steinidole","ausgrabung","götzen sammeln","magmar fellhew","ruinen","troggs"},ang={["faction:Alliance"]="Als Abenteurer der Allianz helft Ihr zwergischen Expeditionen, gefährliche Relikte zu sichern, bevor wilde Troggs noch mehr Unheil anrichten.",["race:Dwarf"]="Als Zwerg schließt Ihr Euch Ausgräbern an, die in troggverseuchten Ruinen nach uralten Artefakten und ihren Geheimnissen suchen."},sec={{t="Die freigelegten Relikte",b="Forscher entdeckten einen großen Vorrat seltsamer, geschnitzter Steinidole, kurz bevor wilde Troggs an die Oberfläche drangen und die Ausgrabungsstätte überrannten. Der Angriff vertrieb die Expedition aus den Ruinen, noch bevor eine eingehende Untersuchung beginnen konnte. Nun umklammern die Troggs die Relikte und durchstreifen die Stätte, wodurch sie eine friedliche Rückkehr verhindern."},{t="Wilde Raserei",b="Die Troggs scheinen zutiefst von den Idolen beeinflusst zu sein, statt sie bloß an sich zu nehmen. Ihre seltsamen Schnitzereien üben eine beunruhigende Macht aus, die die Kreaturen in unkontrollierbare Wut versetzt. Magmar Fellhew will die Idole gefahrlos untersuchen und die Raserei eindämmen, die das Gebiet erfasst hat, weshalb er sie den Troggs entreißen will."}},faq={{q="Wer ist Magmar Fellhew?",a="Magmar Fellhew ist ein Ausgräber, der geschnitzte Steinidole aus einer von Troggs überrannten Ausgrabungsstätte bergen will.",al={"wer ist magmar fellhew","questgeber","magmar"}},{q="Was sind die geschnitzten Steinidole?",a="Die Idole sind geheimnisvolle geschnitzte Steinrelikte, die an einer Ausgrabungsstätte freigelegt wurden. Ihre beunruhigende Macht versetzt Troggs in der Nähe in blinde Raserei.",al={"was sind geschnitzte steinidole","seltsame idole","ausgegrabene idole"}},{q="Warum lassen die Idole die Troggs durchdrehen?",a="Die Idole üben einen seltsamen, unerklärlichen Einfluss auf Troggs aus. Wenn die Kreaturen sie besitzen, lässt wilde Wut sie durchdrehen.",al={"warum troggs durchdrehen","idole machen troggs verrückt","troggwut"}},{q="Warum will Magmar Fellhew die Idole sammeln lassen?",a="Magmar Fellhew will die Idole sicher bergen lassen, um ihren Ursprung und ihre Eigenschaften zu untersuchen und die unberechenbaren Relikte den Troggs zu entreißen.",al={"warum idole holen","zweck des götzen sammelns","magmars untersuchung"}},{q="Was geschah an der Ausgrabungsstätte?",a="Kurz nach der Entdeckung der Idole drangen Troggs an der Ausgrabungsstätte unvermittelt an die Oberfläche. Sie vertrieben die Ausgräber aus den Ruinen.",al={"wer kam an der stätte an die oberfläche","trogginvasion","ausgrabung überrannt"}},{q="Wo sind die Idole zu finden?",a="Troggs tragen die geschnitzten Steinidole an der Ausgrabungsstätte bei sich, an der die Relikte erstmals freigelegt wurden.",al={"wo idole finden","wer hat die idole","fundort geschnitzter steinidole"}}},fp="15,126,20.301.0,15.306.0,22.108.0,32.144.0,44.124.0,49.142.0,37.132.0,26.97.0"}
P.entries["quest:2970"] = {n="Gerechtigkeit üben",s="In Feralas sind Jer'kai Moonweaver und Kindal nach der Rettung der Grimmlingflitzer bereit, zurückzuschlagen. Jer'kai bittet Euch, die Reihen der Grimtotem zu lichten und dann zu ihm zurückzukehren.",h="In Feralas sind Jer'kai Moonweaver und Kindal nach der Rettung der Grimmlingflitzer bereit, zurückzuschlagen.",kw={"gerechtigkeit üben","feralas","grimtotem","jer'kai moonweaver","kindal mondweber","naturkundler","räuber","schamane"},sec={{t="Den Kampf zu den Grimtotem tragen",b="Nach der Rettung der Grimmlingflitzer sind Jer'kai Moonweaver und Kindal bereit, gegen die Grimtotem vorzugehen. Gemeinsam können sie die Reihen der Tauren ohne großes Risiko lichten und heißen Eure Hilfe willkommen.\n\nIhr habt das Lager unten gesehen, und weiter östlich liegen weitere. Wählt Eure eigene Taktik gegen Grimtotem Naturalists, Raiders und Shamans und kehrt dann zu Jer'kai zurück."}},faq={{q="Wer vergibt Gerechtigkeit üben?",a="In Feralas bittet Jer'kai Moonweaver Euch um Hilfe, nachdem Kindal erklärt hat, was sie nach der Rettung der Grimmlingflitzer vorhaben.",al={"wer vergibt gerechtigkeit üben","questgeber gerechtigkeit üben","jer'kai moonweaver"}},{q="Welche Grimtotem sind die Ziele?",a="Die Ziele sind Grimtotem Naturalists, Grimtotem Raiders und Grimtotem Shamans aus dem Grimtotem-Klan.",al={"welche gegner töten","gerechtigkeit üben ziele","grimtotem töten"}},{q="Wo liegen die Lager der Grimtotem?",a="Ein Lager der Grimtotem liegt unterhalb von Jer'kai in Sichtweite, und sie sagt, dass weiter östlich weitere Lager liegen.",al={"wo sind die grimtotem","grimtotem lager standort","wohin gehen"}},{q="Was kommt vor Gerechtigkeit üben?",a="Freedom for All Creatures kommt zuerst. Dort habt Ihr die Grimmlingflitzer aus dem Lager der Grimtotem befreit.",al={"vorherige quest","gerechtigkeit üben voraussetzung","vorheriger schritt"}}},fp="14,166,33.338.0,25.127.0,29.104.0,30.89.0,33.99.0"}
P.entries["quest:2972"] = {n="Gerechtigkeit üben",s="In Feralas schickt Jer'kai Moonweaver Euch mit einem Ring für Hohepriesterin Tyrande Wisperwind nach Darnassus. Er soll zeigen, dass es Jer'kai und Kindal gut geht, und Euren Bericht bekräftigen.",h="In Feralas schickt Jer'kai Moonweaver Euch mit einem Ring für Hohepriesterin Tyrande Wisperwind nach...",kw={"darnassus","feralas","jer'kai moonweaver","kindal mondweber","siegelring","teldrassil","tempel des mondes","tyrande wisperwind"},sec={{t="Ein Ring für die Hohepriesterin",b="Jer'kai Moonweaver und Kindal können Euch in Feralas wenig bieten, doch sie möchten Euch ihre Dankbarkeit zeigen. Jer'kai gibt Euch einen Siegelring für Hohepriesterin Tyrande Wisperwind im Tempel des Mondes in Darnassus. Der Ring zeigt Tyrande, dass es den beiden gut geht, und verleiht Eurem Bericht Gewicht."},{t="Tyrandes Antwort",b="Hohepriesterin Tyrande Wisperwind freut sich, dass Ihr den Drachen und einer ihrer Priesterinnen geholfen habt. Sie sagt, Jer'kai habe Euch zu Recht geschickt, und verspricht, dass Jer'kai den Ring zurückerhalten wird. Bald sollen Späher nach Feralas aufbrechen, und der Ring gehört zu den Angelegenheiten, denen sie nachgehen werden."}},faq={{q="Wer überreicht den Siegelring?",a="Jer'kai Moonweaver überreicht Euch den Siegelring in Feralas, auch mit Kindals Dank.",al={"wer startet diese quest","questgeber"}},{q="Wohin soll der Siegelring gebracht werden?",a="Der Ring soll zu Hohepriesterin Tyrande Wisperwind im Tempel des Mondes in Darnassus gebracht werden.",al={"wohin den ring bringen","abgabeort","wer bekommt jerkais siegelring"}},{q="Warum gibt Jer'kai Euch den Ring?",a="Jer'kai und Kindal können Euch in der Wildnis wenig geben. Der Ring zeigt Tyrande, dass es ihnen gut geht, und bekräftigt Euren Bericht.",al={"zweck des siegelrings","warum jerkais siegelring"}},{q="Wie geht die Questreihe weiter?",a="Die Questreihe geht mit An Orphan Looking For a Home weiter.",al={"nächste quest","wohin als nächstes"}}},fp="14,177,29.298.0,16.283.1,26.89.0,30.91.0,35.121.0,29.54.0"}
P.entries["quest:2973"] = {n="Schimmer für einen neuen Umhang",s="In Camp Mojache bittet Krueg Skullsplitter Euch, Flügel für Korrins Umhang zu sammeln. Er kam mit Gefährten nach Feralas, die von ihren Meistern in Orgrimmar entsandt wurden.",h="In Camp Mojache bittet Krueg Skullsplitter Euch, Flügel für Korrins Umhang zu sammeln.",kw={"camp mojache","umhang","feendrache","feralas","schillernde flügel","korrin","krueg skullsplitter","grimmlingflitzer"},sec={{t="Ein Umhang für Korrin",b="Krueg Skullsplitter kam mit Gefährten nach Feralas, die von ihren Meistern in Orgrimmar entsandt wurden. Seine Lebensgefährtin Korrin liebt neue Kleidung, also plant er einen Umhang, der mit zarten Feendrachenflügeln verziert ist. Die Grimmlingflitzer, die er sucht, leben westlich von Camp Mojache. Bringt Krueg zehn Iridescent Sprite Darter Wings."},{t="Kruegs Warnung",b="Krueg warnt, dass Grimmlingflitzer gefährlich sind, wenn sie gereizt werden. Die Nachtelfen in der Nähe verkriechen sich gern in den Wäldern, also seid in ihrer Nähe noch vorsichtiger."}},faq={{q="Wer ist Krueg Skullsplitter?",a="Krueg Skullsplitter ist in Camp Mojache. Er kam mit Gefährten nach Feralas, die von ihren Meistern in Orgrimmar entsandt wurden.",al={"wer ist krueg","krueg skullsplitter hintergrund","krueg in feralas"}},{q="Warum will Krueg Grimmlingflitzerflügel?",a="Krueg plant einen mit Feendrachenflügeln verzierten Umhang für seine Lebensgefährtin Korrin, die neue Kleidung liebt.",al={"warum werden grimmlingflitzerflügel benötigt","grimmlingflitzerflügel verwendung","was stellt krueg her"}},{q="Wo leben die Grimmlingflitzer?",a="Die Grimmlingflitzer leben westlich von Camp Mojache.",al={"wo sind grimmlingflitzer zu finden","grimmlingflitzer fundort","wo sind feendrachen in feralas"}},{q="Vor welchen Gefahren warnt Krueg?",a="Vor Grimmlingflitzern, die gefährlich werden, wenn sie gereizt werden, und den Nachtelfen in der Nähe, die sich gern in den Wäldern verkriechen und noch größere Vorsicht erfordern.",al={"kruegs warnungen","gefahren im wald von feralas"}}},fp="19,154,18.293.0,15.145.0,27.110.0,40.101.0,37.45.0,35.146.0"}
P.entries["quest:2974"] = {n="Eine grausige Entdeckung",s="In Camp Mojache hört Krueg Skullsplitter, dass Ihr Tauren in Feralas getroffen habt, und nennt sie Grimtotem. Belgrom hat ein Kopfgeld auf sie ausgesetzt, und Krueg verlangt zwanzig Hörner.",h="In Camp Mojache hört Krueg Skullsplitter, dass Ihr Tauren in Feralas getroffen habt, und nennt sie Grimtotem.",kw={"belgrom","camp mojache","feralas","grimtotem","hörner","krueg skullsplitter"},sec={{t="Kunde von den Grimtotem",b="Ihr erzählt Krueg Skullsplitter von den Tauren, die Ihr in Feralas getroffen habt. Er bezeichnet sie als den Clan der Grimtotem. Belgrom, einer von Kruegs Meistern, hat ein Kopfgeld auf sie ausgesetzt und hegt großes Interesse an ihrer Art. Krueg warnt Euch, dass die Grimtotem böse sind und nicht unterschätzt werden dürfen. Er möchte zwanzig Hörner zurückgebracht bekommen, bevor sie Dörfer niederbrennen oder Land rauben können."},{t="Die Hörner sind überbracht",b="Krueg befindet die Hörner für gut und sagt, dass Ihr ihm zweimal geholfen habt. Belgrom wird davon erfahren, sobald Krueg nach Orgrimmar zurückkehrt."}},faq={{q="Wer vergibt Eine grausige Entdeckung?",a="Krueg Skullsplitter gibt Euch die Quest in Camp Mojache, nachdem Ihr ihm erzählt habt, dass Ihr Tauren in Feralas getroffen habt.",al={"wer vergibt eine grausige entdeckung","krueg skullsplitter quest","questgeber eine grausige entdeckung"}},{q="Warum will Krueg Grimtotem-Hörner?",a="Krueg nennt die Grimtotem böse und will gegen sie vorgehen, bevor sie Dörfer niederbrennen oder Land rauben können. Belgrom, einer von Kruegs Meistern in Orgrimmar, hat ebenfalls ein Kopfgeld auf sie ausgesetzt.",al={"warum grimtotem töten","grimtotem bedrohung feralas","warum grimtotem-hörner"}},{q="Wer ist Belgrom?",a="Krueg bezeichnet Belgrom als einen seiner Meister. Belgrom interessiert sich für die Grimtotem und hat ein Kopfgeld auf sie ausgesetzt.",al={"belgrom orgrimmar","wer ist belgrom"}},{q="Wie viele Hörner will Krueg?",a="Krueg möchte zwanzig Grimtotem-Hörner nach Camp Mojache gebracht bekommen. Am liebsten hätte er ganze Haufen davon, wenn Ihr das schafft.",al={"grimtotem-hörner anzahl","wie viele grimtotem-hörner"}},{q="Was folgt auf Eine grausige Entdeckung?",a="Die Questreihe geht mit Eine grausige Entdeckung, Teil zwei, weiter.",al={"nächste quest eine grausige entdeckung","eine grausige entdeckung questreihe"}}},fp="16,170,21.358.0,19.126.1,27.97.0,36.175.0,15.108.0,31.113.0,30.52.0"}
P.entries["quest:2975"] = {n="Die Oger von Feralas",s="In Camp Mojache fordert Rok Orhan, die Gordunni zurückzudrängen. Ihr Außenposten liegt flussaufwärts im Norden.",h="In Camp Mojache fordert Rok Orhan, die Gordunni zurückzudrängen.",kw={"schläger","camp mojache","feralas","gordunni","oger","ogermagier","rok orhan"},sec={{t="Das Zeichen der Gordunni",b="Rok Orhan sagt, die Oger der Gordunni zeichnen das Land um Camp Mojache. Drängt den Stamm zurück, bevor er tiefer nach Feralas vordringt. Folgt dem Fluss nach Norden, um ihren Außenposten zu finden. Erschlagt dort zehn Gordunni Ogres, zehn Gordunni Ogre-Magi und fünf Gordunni Brutes, um dem Stamm zu zeigen, dass er unerwünscht ist."}},faq={{q="Wer will die Oger der Gordunni zurückdrängen lassen?",a="Rok Orhan in Camp Mojache will die Oger der Gordunni zurückdrängen lassen.",al={"wer vergibt die quest","questgeber","rok orhan"}},{q="Warum will Rok Orhan die Gordunni zurückdrängen lassen?",a="Rok Orhan sagt, die Gordunni zeichnen das Land und müssen aufgehalten werden, bevor sie sich weiter in Feralas ausbreiten.",al={"warum die oger töten","gordunni beweggrund","warum gordunni bekämpfen"}},{q="Wo liegt der Außenposten der Gordunni?",a="Folgt dem Fluss nach Norden, um den Außenposten der Gordunni zu finden.",al={"standort des ogeraußenpostens","wo sind die oger","gordunni standort feralas"}},{q="Welche Gordunni müssen erschlagen werden?",a="Erschlagt zehn Gordunni Ogres, zehn Gordunni Ogre-Magi und fünf Gordunni Brutes.",al={"wie viele oger","gordunni anzahl tötungen"}},{q="Was folgt auf diese Quest?",a="Die Questreihe geht mit „Die Oger von Feralas zwei“ weiter.",al={"nächste quest die oger von feralas","die oger von feralas questreihe"}}},fp="20,114,24.292.0,41.63.0,49.102.0,30.52.0,29.73.0,24.50.0"}
P.entries["quest:2976"] = {n="Eine grausige Entdeckung",s="In Orgrimmar erwartet Belgrom Rockmaul die Hörner der Grimtotem und Euren Bericht aus Feralas. Krueg Schädelspalter sagt, Ihr habt die Arbeit getan und verdient den besten Teil des Kopfgelds. Dies folgt auf das erste Eine grausige Entdeckung.",h="In Orgrimmar erwartet Belgrom Rockmaul die Hörner der Grimtotem und Euren Bericht aus Feralas.",kw={"belgrom rockmaul","kopfgeld","feralas","grimtotem","hörner","krueg skullsplitter","orgrimmar","tal der ehre"},sec={{t="Die Kiste mit Hörnern",b="Krueg Skullsplitter gibt zu, nach dem ersten Eine grausige Entdeckung von einem Kopfgeld gesprochen zu haben. Ihr habt die Arbeit getan, also verdient Ihr seiner Meinung nach den besten Teil der Belohnung. Er packt die Hörner in eine Kiste, die Ihr zu Belgrom Rockmaul im Tal der Ehre bringen sollt. Belgrom möchte hören, was Ihr gesehen habt, und Krueg sagt, er werde Eure harte Arbeit belohnen."},{t="Belgroms Interesse",b="Belgrom Rockmaul ist von den Neuigkeiten über die Grimtotem erschüttert. Er fragt, ob Ihr ihnen wirklich bei der Jagd in Feralas begegnet seid. Seine Gefährten werden die Geschichte hören wollen, also bittet er Euch, mehr zu erzählen, während die Münzen abgezählt werden. Belgrom dankt Euch für die Informationen."}},faq={{q="Wer vergibt diesen Teil von Eine grausige Entdeckung?",a="Krueg Skullsplitter gibt Euch die Hörner in einer Kiste, die Ihr zu Belgrom Rockmaul bringen sollt.",al={"wer vergibt eine grausige entdeckung","krueg skullsplitter quest","questgeber eine grausige entdeckung 2"}},{q="Wohin soll die Kiste mit den Hörnern der Grimtotem?",a="Die Kiste mit den Hörnern der Grimtotem soll zu Belgrom Rockmaul im Tal der Ehre in Orgrimmar.",al={"wohin die hörner bringen","belgrom rockmaul standort","eine grausige entdeckung 2 abgeben"}},{q="Warum steht Euch das Kopfgeld zu?",a="Krueg sagt, Ihr habt die Arbeit getan und verdient daher den besten Teil der Belohnung.",al={"warum hörner der grimtotem","kopfgeld eine grausige entdeckung"}},{q="Was möchte Belgrom von Euch?",a="Euren Bericht darüber, was Ihr gesehen habt. Krueg verspricht, dass sich Eure harte Arbeit lohnen wird.",al={"belgrom rockmaul grimtotem","warum interesse an grimtotem in feralas"}},{q="Was kommt vor diesem Schritt?",a="Das erste Eine grausige Entdeckung kommt vor diesem Teil. Ihr habt Krueg Hörner der Grimtotem gebracht.",al={"questreihe eine grausige entdeckung","voraussetzung für eine grausige entdeckung 2","vorherige quests"}}},fp="16,205,18.332.0,18.252.1,40.80.0,43.90.0,24.67.0,32.81.0,28.85.0"}
P.entries["quest:2978"] = {n="Die Gordunnischriftrolle",s="Am Außenposten der Gordunni zeigt die Gordunnischriftrolle womöglich eine Versammlung oder Zeremonie. Rok Orhan in Camp Mojache will sie sehen und erfahren, was sie für die Gordunni bedeutet.",h="Am Außenposten der Gordunni zeigt die Gordunnischriftrolle womöglich eine Versammlung oder Zeremonie.",kw={"camp mojache","zeremonie","feralas","außenposten der gordunni","gordunnischriftrolle","oger","rok orhan"},sec={{t="Die verschmutzte Schriftrolle",b="Ihr findet eine verschmutzte Schriftrolle am Außenposten der Gordunni. Ihre Abbildung scheint eine Versammlung oder Zeremonie zu zeigen. Rok Orhan in Camp Mojache will sie sehen und erfahren, was sie für die Gordunni bedeuten könnte."}},faq={{q="Was zeigt die Gordunnischriftrolle?",a="Die Gordunnischriftrolle scheint eine Zusammenkunft oder Zeremonie zu zeigen.",al={"was zeigt die schriftrolle","gordunnischriftrolle inhalt","schriftrolle zeichnung"}},{q="Wer will die Gordunnischriftrolle haben?",a="Rok Orhan in Camp Mojache will die Gordunnischriftrolle sehen.",al={"wer will die schriftrolle haben","wohin die schriftrolle bringen","gordunnischriftrolle abgeben"}},{q="Wo wird die Gordunnischriftrolle gefunden?",a="Ihr findet die Gordunnischriftrolle am Außenposten der Gordunni.",al={"wo ist die gordunnischriftrolle","gordunnischriftrolle fundort"}},{q="Was folgt auf die Gordunnischriftrolle?",a="Dark Ceremony folgt auf die Gordunnischriftrolle.",al={"was ist die nächste quest","nach der gordunnischriftrolle","gordunnischriftrolle questreihe"}}},fp="19,164,17.187.0,35.56.0,30.59.0,35.53.0,33.42.0"}
P.entries["quest:2979"] = {n="Dunkle Zeremonie",s="In Camp Mojache studiert Rok Orhan die Gordunnischriftrolle und sucht eine Kugel von einem Gordunni-Mage-Lord. Er hofft, dass sie mehr über die Zeremonie und die Magie der Gordunni enthüllt.",h="In Camp Mojache studiert Rok Orhan die Gordunnischriftrolle und sucht eine Kugel von einem Gordunni-Mage-Lord.",kw={"camp mojache","dunkle zeremonie","feralas","gordunni","gordunnikugel","mage-lord","rok orhan"},sec={{t="Pläne für eine dunkle Zeremonie",b="Rok Orhan deutet die Gordunnischriftrolle als Pläne für eine dunkle Zeremonie. Er glaubt, dass die Gordunni-Mage-Lords sie durchführen. Findet einen von ihnen und nehmt ihm seine Kugel ab. Die Kugel eines Magiers birgt große Macht, und Rok hofft, dadurch mehr über die Zeremonie und die Magie der Gordunni zu erfahren."},{t="Wenn die Kugel eintrifft",b="Rok Orhan erwartet, durch die Kugel mehr über die Gordunni zu erfahren. Er wird dieses Wissen nutzen, um ihren Untergang zu planen."}},faq={{q="Wer vergibt Dunkle Zeremonie?",a="Rok Orhan in Camp Mojache vergibt sie, nachdem er die von Euch gebrachte Gordunnischriftrolle gelesen hat.",al={"wer vergibt dunkle zeremonie","dunkle zeremonie questgeber"}},{q="Wer führt die dunkle Zeremonie durch?",a="Rok Orhan deutet die Pläne so, dass die Gordunni-Mage-Lords die Zeremonie durchführen.",al={"wer führt die dunkle zeremonie durch","gordunni ritualleiter"}},{q="Welche Kugel sucht Rok Orhan?",a="Rok Orhan möchte eine Kugel, die einem der Gordunni-Mage-Lords abgenommen wird. Die Kugel eines Magiers birgt große Macht, und sie erwartet, dadurch mehr über die Zeremonie und die Magie der Gordunni zu erfahren.",al={"warum gordunnikugel beschaffen","zweck der gordunnikugel"}},{q="Was folgt auf Dunkle Zeremonie?",a="Die Questreihe geht mit der Gordunnikugel weiter.",al={"nächste quest nach dunkle zeremonie","dunkle zeremonie questreihe"}}},fp="13,172,25.270.0,25.114.1,24.81.0,34.87.0,28.179.0,27.42.0"}
P.entries["quest:298"] = {n="Bericht über den Fortschritt der Ausgrabungen",s="An Eisenbands Ausgrabungsstätte sollt Ihr für Ausgrabungsleiter Eisenband Berichte und Pulverbestellungen zu Jern Hornhelm in Thelsamar bringen.",h="An Eisenbands Ausgrabungsstätte sollt Ihr für Ausgrabungsleiter Eisenband Berichte und Pulverbestellungen zu...",kw={"sprengpulver","bericht über den fortschritt der ausgrabungen","explorers' league","jern hornhelm","loch modan","ausgrabungsleiter eisenband","thelsamar","trogg"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, die Versorgungswege zwischen Thelsamar und entlegenen Außenposten in den Bergen von Loch Modan offen zu halten.",["profession:Mining"]="Als Bergmann wisst Ihr, dass zuverlässiges Sprengpulver nötig ist, um dichtes Grundgestein zu brechen und Stollen in uralte Schichten zu treiben.",["race:Dwarf"]="Als Zwerg helft Ihr Eisenband, die historische Arbeit der Explorers' League voranzutreiben und Eure Verwandten vor Troggangriffen zu schützen."},sec={{t="Eine Botschaft nach Thelsamar",b="Eisenbands Berichte schildern seine Ausgrabungen und erneuern seine Nachschubanforderungen. Die Arbeit erfordert Spitzhacken, Arbeiter und Sprengpulver, um das Grundgestein zu durchbrechen. Eisenband verlässt sich auf Boten, um Jern Hornhelm auf dem Laufenden zu halten."},{t="Vermisste Munition",b="Die Botschaft offenbart, dass aggressive Troggs die Ausgrabung bedrängen. Pulver könnte Stein brechen oder Troggs sprengen. Doch Eisenbands erneute Anforderung lässt Jern Hornhelm stutzen: Er hat vor Wochen eine große Lieferung geschickt und fragt sich, was auf den zerklüfteten Bergpfaden damit geschehen ist."}},faq={{q="Wer gibt Euch diesen Bericht?",a="Ausgrabungsleiter Eisenband gibt Euch den Bericht an Eisenbands Ausgrabungsstätte in den südöstlichen Hügeln von Loch Modan. Er beaufsichtigt dort die archäologische Ausgrabung.",al={"questgeber","wer startet bericht über den fortschritt der ausgrabungen","eisenbands standort"}},{q="Wer ist Jern Hornhelm?",a="Jern Hornhelm ist ein zwergischer Ansprechpartner der Explorers' League in Thelsamar. Er koordiniert Nachschub und örtliche Logistik für archäologische Expeditionen in ganz Loch Modan.",al={"wo ist jern hornhelm","wer ist der empfänger","ansprechpartner in thelsamar"}},{q="Warum braucht Ausgrabungsleiter Eisenband mehr Sprengpulver?",a="Eisenband braucht Sprengpulver, um für seine Ausgrabung massiven Fels zu beseitigen. An der Ausgrabungsstätte wimmelt es außerdem von feindseligen Troggs, weshalb Sprengstoff auch für die Verteidigung wichtig ist.",al={"warum sprengpulver","wofür will eisenband pulver"}},{q="Was ist mit der vorherigen Pulverlieferung geschehen?",a="Jern Hornhelm hat vor Wochen Sprengpulver geschickt, doch es hat die Ausgrabung nie erreicht. Sein Verschwinden deutet auf Schwierigkeiten entlang der Wege zwischen Thelsamar und den abgelegenen Stätten hin.",al={"wo ist das pulver geblieben","vermisstes sprengpulver"}},{q="Was folgt nach der Überbringung des Fortschrittsberichts?",a="Nachdem Hornhelm Eisenbands Lage und das vermisste Pulver geprüft hat, schickt er Euch zu seinen Vorgesetzten in Eisenschmiede, um über den Stand der Expedition zu berichten.",al={"nächste quest","was kommt danach","report to ironforge"}},{q="Warum greifen Troggs die Ausgrabungsstätte an?",a="Zwergische Ausgrabungen können unterirdische Kammern freilegen und Troggbaue stören. Troggs betrachten Bergleute als Eindringlinge und fallen über jene her, die sich in die Erde graben.",al={"grund für troggangriffe","warum hassen troggs eisenband"}}},fx={["0b7d15ff"]={q="Warum benötigt Ausgrabungsleiter Eisenband Euch, um den Bericht zu überbringen?",a="Ausgrabungsleiter Eisenband und seine Grabungshelfer sind an der Ausgrabungsstätte durch unerbittliche Angriffe der Troggs festgesetzt. Da seine Crew vollauf damit beschäftigt ist, ihre archäologische Arbeit zu verteidigen und ums Überleben zu kämpfen, kann Eisenband niemanden entbehren, um den weiten Weg zurück nach Thelsamar zurückzulegen. Ein außenstehender Reisender wie Ihr bietet einen schnellen, zuverlässigen Boten, um seine Worte durch die gefährliche Wildnis zu tragen.",al={"warum schickt er mich","warum geht er nicht selbst","warum bericht überbringen"}}},fp="26,133,23.204.0,17.267.1,29.150.0,21.160.0,51.159.0,49.173.0,50.144.0,45.147.0"}
P.entries["quest:2980"] = {n="Die Oger von Feralas",s="In Feralas schickt Rok Orhan Euch südwestlich von Camp Mojache, um die Gordunni-Oger zurückzudrängen. Ihr habt Euch als wahrer Kämpfer erwiesen, und er vertraut Euch diese Arbeit in der oberen Wildnis an.",h="In Feralas schickt Rok Orhan Euch südwestlich von Camp Mojache, um die Gordunni-Oger zurückzudrängen.",kw={"camp mojache","feralas","gordunni","die obere wildnis","maulers","rok orhan","schamanen","hexenmeister"},sec={{t="In die obere Wildnis",b="Rok Orhan vertraut Euch diese Arbeit an, weil Ihr Euch als wahrer Kämpfer erwiesen habt. Südwestlich von Camp Mojache stehen in der oberen Wildnis verlassene, zerstörte Bauten auf Land, das einst den Nachtelfen gehörte.\n\nVerdorrte Bäume und entweihter Boden kennzeichnen das Gebiet der Gordunni. Rok warnt, dass diese Oger weitaus zäher sind als die früheren. Zehn Gordunni Shamans, zehn Gordunni Warlocks und fünf Gordunni Maulers sollen fallen."}},faq={{q="Wer schickt Euch in die obere Wildnis?",a="Rok Orhan schickt Euch von Camp Mojache aus dorthin.",al={"questgeber","rok orhan","wer beginnt dies"}},{q="Wo sind diese Gordunni?",a="Die Gordunni sind in der oberen Wildnis, südwestlich von Camp Mojache, bei zerstörten Bauten auf Land, das einst den Nachtelfen gehörte. Verdorrte Bäume und entweihter Boden kennzeichnen den Ort.",al={"wo sind die oger","obere wildnis lage","ruinen lage"}},{q="Welche Oger müssen getötet werden?",a="Zehn Gordunni Shamans, zehn Gordunni Warlocks und fünf Gordunni Maulers müssen fallen.",al={"wer muss getötet werden","ogerziele","gordunni-arten"}},{q="Was kommt vor diesem Schritt?",a="Vor diesem Schritt hat Rok Orhan Euch gegen die Oger bei ihrem Außenposten im Norden geschickt.",al={"voraussetzung","vorherige quest","questreihenfolge"}}},fp="20,189,24.423.0,37.38.0,25.183.0,27.80.0,28.85.0"}
P.entries["quest:2982"] = {n="Die Obere Wildnis",s="In Feralas sorgt sich Angelas Moonbreeze, als Troyas allein die obere Wildnis betritt. Oger der Gordunni halten das Gebiet besetzt, und sie hofft, dass Ihr die Ruinen südöstlich von hier sicherer macht, indem Ihr ihre Zahl dezimiert.",h="In Feralas sorgt sich Angelas Moonbreeze, als Troyas allein die obere Wildnis betritt.",kw={"angelas moonbreeze","feralas","gordunni","gordunni brute","gordunni-schamane","gordunni-hexenmeister","die obere wildnis","oger","troyas"},sec={{t="Sorge um Troyas",b="Angelas Moonbreeze und Troyas erkunden die verstreuten Ruinen von Feralas, obwohl die Arbeit gefährlich ist. In letzter Zeit geht Troyas allein in die obere Wildnis, und Angelas fürchtet um ihn. Oger der Gordunni halten das Gebiet besetzt und heißen niemanden in ihrem Territorium willkommen. Deshalb bittet Angelas Euch, die Ruinen südöstlich von hier für Troyas sicherer zu machen, indem Ihr acht Gordunni-Hexenmeister, acht Gordunni-Schamanen und acht Gordunni Brutes tötet."},{t="Danach",b="Nachdem Ihr die Arbeit erledigt habt, dankt Angelas Euch herzlich. Sie bittet Euch, Troyas nichts davon zu erzählen."}},faq={{q="Wer bittet Euch, die obere Wildnis zu säubern?",a="Angelas Moonbreeze bittet Euch, die obere Wildnis zu säubern. Sie erkundet mit Troyas die Ruinen von Feralas.",al={"wer ist angelas","angelas moonbreeze","wer vergibt die quest zur oberen wildnis"}},{q="Warum will Angelas die Zahl der Oger der Gordunni verringern?",a="Troyas begibt sich seit einiger Zeit allein in die obere Wildnis, und Angelas sorgt sich um ihn. Oger der Gordunni halten das Gebiet besetzt und heißen keine Besucher willkommen.",al={"warum gordunni töten","warum oger in der oberen wildnis töten","angelas grund"}},{q="Wo liegt die Ruine in der oberen Wildnis?",a="Angelas verweist Euch auf die Ruinen südöstlich von hier.",al={"wo ist die obere wildnis","lage der oberen wildnis","ruinen im südosten"}},{q="Welche Gordunni müssen getötet werden?",a="Ihr werdet gebeten, acht Gordunni-Hexenmeister, acht Gordunni-Schamanen und acht Gordunni Brutes zu töten.",al={"wen in der oberen wildnis töten","gordunni-ziele in der oberen wildnis"}},{q="Was wird über die Magie der Gordunni gesagt?",a="Angelas warnt, dass die Magie der Gordunni den Boden unter ihnen zu verwüsten scheint. Sie mahnt Euch, in der Nähe der Oger wachsam zu bleiben.",al={"magie der gordunni","ogerzauber","welche magie richtet verwüstungen an"}}},fp="19,193,16.408.0,9.90.1,46.99.0,53.134.0,34.50.0,29.96.0,40.119.0"}
P.entries["quest:2985"] = {n="Ruf des Wassers",s="Swart schickt einen Initianden von Klingenhügel zu Islen Wasserdeuter an der Küste des Brachlands. Erde und Feuer haben den Schamanen geprüft; Wasser verlangt eine andere Art des Verständnisses.",h="Swart schickt einen Initianden von Klingenhügel zu Islen Wasserdeuter an der Küste des Brachlands.",kw={"ruf des wassers","islen wasserdeuter","ratschet","klingenhügel","schamane","der südstrom","swart","brachland","wassertotem"},ang={["class:Shaman"]="Als Schamane wendet Ihr Euch von Erde und Feuer der heilenden Kraft des Wassers zu und eröffnet einen spirituellen Weg zu heilenden Totems.",["faction:Horde"]="Als Schamane der Horde werdet Ihr zu Islen Wasserdeuter an der Küste des Brachlands geschickt, um Eure Zwiesprache mit dem Wasser zu beginnen."},sec={{t="Ein Wandel der Elemente",b="Swart, der Schamanenlehrer in Klingenhügel, führt Initianden durch die Elemente. Erde lehrt Ausdauer, und Feuer prüft ihre Beherrschung. Sobald ein Initiand die Flamme beherrschen kann, ohne von ihr verzehrt zu werden, hält Swart ihn für bereit, die Lehren des Wassers zu suchen."},{t="Die Einsiedlerin der Händlerküste",b="Islen Wasserdeuter lebt an der Küste des Brachlands jenseits von Ratschet. Reist am Südstrom entlang nach Süden ins Brachland, dann nach Osten zum Ufer nahe dem Kadaver eines riesigen Hais. Islen wohnt dort, wo die Wellen auf das Land treffen, fernab der Lehrer in Durotars Städten. Sie führt die Horde in der Zwiesprache mit dem Wasser."}},faq={{q="Wer vergibt diese Quest?",a="Swart, der Orcschamanenlehrer in Klingenhügel, schickt Euch weiter, nachdem Ihr Eure Beherrschung von Erde und Feuer bewiesen habt.",al={"questgeber","wer startet ruf des wassers","swart"}},{q="Wo kann ich Islen Wasserdeuter finden?",a="Islen Wasserdeuter lebt an der Ostküste des Brachlands, unmittelbar südlich von Ratschet. Folgt dem Südstrom von Durotar aus nach Süden, zieht dann zum Ufer und sucht ihr Lager neben einem großen gestrandeten Hai.",al={"wo ist islen","islens standort","wie islen wasserdeuter finden"}},{q="Warum muss ein Schamane die Elemente in einer bestimmten Reihenfolge erlernen?",a="Die schamanische Tradition verlangt von einem Initianden, Schritt für Schritt ein spirituelles Gleichgewicht aufzubauen. Erde gibt der Seele Halt, und Feuer stählt sie für die wandelbare Natur des Wassers.",al={"reihenfolge der elemente","warum wasser nach feuer","schamanenausbildung"}},{q="Ist diese Quest auch für andere Klassen verfügbar?",a="Nein. Nur Schamanen suchen die Gunst der Wassergeister und streben danach, ihr Wassertotem zu manifestieren.",al={"auch für andere klassen möglich","ruf des wassers nur für schamanen"}},{q="Nach welcher Landmarke sollte ich bei der Suche nach Islen Ausschau halten?",a="Haltet am Ufer südlich von Ratschet nach einem riesigen gestrandeten Hai Ausschau. Islen lebt daneben.",al={"hai als landmarke","woran islens lager erkennen","islen küste"}},{q="Was geschieht, nachdem ich Islen Wasserdeuter erreicht habe?",a="Ein Gespräch mit Islen leitet die Prüfungen des Wassers ein. Der Schamane muss Kalimdor und Lordaeron bereisen, reine Wassertropfen sammeln und sich Geistern stellen, bevor er sich das Totem verdient.",al={"nächster schritt","was macht islen","nach ruf des wassers"}}},fx={["80a0e7c7"]={q="Warum schickt Swart Euch zu Islen Wasserdeuter?",a="Swart erkennt Eure Meisterschaft über die Flamme an und sieht, dass Eure spirituelle Reise als Schamane weitergehen muss. Er selbst kann Euch die Wege des Wassers nicht lehren – das flüssige, reine Element zu meistern, erfordert die Führung von Islen Wasserdeuter, einer hingebungsvollen Ältesten, die an der Küste des Brachlands weilt. Swart schickt Euch weiter, damit Ihr mit dem Wasser Zwiesprache halten und Eure Verbindung zu den Elementen vertiefen könnt.",al={"warum swart dies verlangt","swart beweggrund","warum mich zu islen schicken"}}},fp="13,169,23.247.0,33.304.0,21.109.0,33.204.0,57.149.0,41.93.0,57.86.0,44.176.1"}
P.entries["quest:2987"] = {n="Gordunnikobalt",s="Orwin Gizzmick ist nach Feralas gekommen, um nach Kobalt zu suchen, das die Oger der Gordunni vergraben haben. Er bittet Euch, am Außenposten der Gordunni nördlich von Camp Mojache nach zwölf Proben zu suchen.",h="Orwin Gizzmick ist nach Feralas gekommen, um nach Kobalt zu suchen, das die Oger der Gordunni vergraben haben.",kw={"camp mojache","kobalt","feralas","gizzmick","gordunni","außenposten der gordunni","oger","orwin","schaufel"},sec={{t="Vergrabene Mineralien",b="Orwin Gizzmick ist neu in Feralas und hat gehört, dass die Oger der Gordunni interessante Mineralien vergraben. Sie bewachen die Mineralien erbittert und halten sie von Leuten wie Orwin fern. Er weiß nicht, wofür sie sie brauchen.\n\nOrwin gibt Euch eine Schaufel und schickt Euch nördlich von Camp Mojache zum Außenposten der Gordunni. Folgt dem blauen Leuchten und grabt zwölf Proben Gordunnikobalt aus."},{t="Wenn das Kobalt eintrifft",b="Orwin will das Kobalt auf seinen weiteren Reisen mitnehmen. Er ist sich sicher, dass jemand ein hübsches Sümmchen dafür bezahlen wird. Er gibt Euch etwas für Eure Mühen."}},faq={{q="Wer will Gordunnikobalt?",a="Orwin Gizzmick will Gordunnikobalt. Er ist gerade erst in Feralas angekommen und hält sich in Camp Mojache auf.",al={"wer startet gordunnikobalt","orwin gizzmick quest","wer will kobalt"}},{q="Wo ist das Gordunnikobalt?",a="Das Gordunnikobalt liegt am Außenposten der Gordunni nördlich von Camp Mojache vergraben.",al={"gordunnikobalt fundort","wo kobalt in feralas finden","wo ist der außenposten der gordunni"}},{q="Wie erkennt Ihr das vergrabene Kobalt?",a="Ein blaues Leuchten zeigt an, wo das Kobalt vergraben liegt. Grabt dort, um es zu finden.",al={"wie kobalt erkennen","kobalt in feralas finden","blaues leuchten oger erde"}},{q="Warum vergraben die Oger ihr Kobalt?",a="Orwin sagt, die Oger vergraben ihr Kobalt und bewachen es erbittert, damit Leute wie er nicht daran gelangen. Er weiß nicht, wofür sie es brauchen.",al={"warum ist kobalt vergraben","warum vergraben gordunni kobalt","oger kobalt vergraben"}},{q="Wie viel Kobalt will Orwin?",a="Orwin will zwölf Proben, die mit seiner Schaufel ausgegraben werden.",al={"kobalt anzahl","wie viel gordunnikobalt"}}},fp="15,166,15.357.0,28.150.1,26.92.0,29.79.0,34.67.0,35.147.0,32.51.0"}
P.entries["quest:2988"] = {n="Käfige der Witherbark",s="Bei den Käfigen der Witherbark sucht Ihr nach Sharpbeak, dem Erben von Swiftwing, den Talonaxe den mächtigsten Greifen nennt. Greifenmeister Talonaxe glaubt, dass die Trolle den jungen Greifen entführt haben.",h="Bei den Käfigen der Witherbark sucht Ihr nach Sharpbeak, dem Erben von Swiftwing, den Talonaxe den...",kw={"käfige","greif","hinterlands","sharpbeak","swiftwing","talonaxe","trolle","witherbark"},sec={{t="Ein vermisster Erbe",b="Greifenmeister Talonaxe bittet Euch, Sharpbeak zu finden, der vor ein paar Tagen bei der Jagd mit seinen Eltern verschwand. Talonaxe und die anderen glauben, dass die Trolle ihn entführt haben. Drei Käfige in den beiden Trolldörfern der Witherbark müssen noch durchsucht werden. Talonaxe erwartet Eure Ergebnisse."},{t="Nachricht aus den Dörfern",b="Sharpbeak ist nicht in den Dörfern der Witherbark. Talonaxe nimmt die Nachricht mit schwerem Herzen auf. Der junge Greif soll die nächste Generation anführen. Ohne ihn würde die Flotte viel von ihrer Stärke und ihrem Kampfgeist verlieren."}},faq={{q="Wer ist Sharpbeak?",a="Sharpbeak ist der Erbe von Swiftwing, und Talonaxe nennt Swiftwing den mächtigsten Greifen. Sharpbeak verschwand vor ein paar Tagen bei der Jagd mit seinen Eltern.",al={"sharpbeak","wer ist der greif","swiftwings erbe"}},{q="Warum werden die Trolle der Witherbark verdächtigt?",a="Talonaxe und die anderen glauben, dass die Trolle der Witherbark Sharpbeak entführt haben. Die Käfige in ihren beiden Dörfern sind die ersten Orte, an denen gesucht werden soll.",al={"warum trolle","beteiligung der witherbark","wer hat sharpbeak entführt"}},{q="Wo suche ich nach Sharpbeak?",a="Durchsucht die Käfige in den beiden Trolldörfern der Witherbark. Kehrt dann zu Greifenmeister Talonaxe zurück und berichtet ihm, was Ihr gefunden habt.",al={"wo sind die käfige","standort der käfige der witherbark","wo nach sharpbeak suchen"}}},fp="16,176,14.270.0,22.200.1,17.152.0,40.133.0,32.122.0"}
P.entries["quest:2989"] = {n="Der Altar von Zul",s="Am Altar von Zul führt Talonaxes Suche nach Sharpbeak in die Ländereien der Vilebranch. Bei den Witherbark fehlt jede Spur des jungen Greifen, und Talonaxe fürchtet, dass die Vilebranch ihn gefangen halten.",h="Am Altar von Zul führt Talonaxes Suche nach Sharpbeak in die Ländereien der Vilebranch.",kw={"altar von zul","gryphon master talonaxe","hinterland","sharpbeak","vilebranch","witherbark"},sec={{t="Ein anderer Stamm, eine weitere Suche",b="Da sich in den Käfigen der Witherbark keine Spur von Sharpbeak findet, vermutet Greifenmeister Talonaxe, dass die Vilebranch-Trolle ihn entführt haben. Deshalb schickt er Euch los, um die Spitze des Altars von Zul am westlichen Rand ihrer Ländereien zu durchsuchen. Falls sie das Greifenkind gefangen halten, fürchtet Talonaxe, was sie ihm womöglich antun."},{t="Nachricht vom Altar",b="Sharpbeak ist nicht am Altar. Talonaxe nennt das eine schlechte, aber zugleich auch eine gute Nachricht. Die Vilebranch sind dafür bekannt, Opfer darzubringen, und er ist erleichtert, dass der Greif dort nicht gefunden wurde. Er dankt Euch für Eure Hilfe und sagt, dass ein größeres Unterfangen bevorsteht."}},faq={{q="Warum schickt Greifenmeister Talonaxe Euch zum Altar von Zul?",a="Die Witherbark-Trolle haben Sharpbeak nicht, deshalb vermutet Talonaxe, dass die Vilebranch ihn entführt haben könnten.",al={"warum altar von zul","altar von zul grund","warum zum altar von zul gehen"}},{q="Wo liegt der Altar von Zul?",a="Der Altar von Zul liegt am westlichen Rand der Ländereien der Vilebranch im Hinterland. Ihr sollt seine Spitze durchsuchen.",al={"altar von zul lage","wo ist der altar von zul"}},{q="Wer ist Sharpbeak?",a="Sharpbeak ist Swiftwings Erbe, das Greifenkind, nach dem Talonaxe seit dessen Verschwinden sucht.",al={"wer ist sharpbeak","sharpbeak geschichte"}},{q="Warum ist Talonaxe wegen der Vilebranch-Trolle besorgt?",a="Talonaxe fürchtet, was die Vilebranch-Trolle Sharpbeak womöglich antun, falls sie ihn gefangen halten.",al={"warum sind vilebranch gefährlich","was tun vilebranch"}}},fp="16,175,29.284.0,19.250.1,62.100.0,34.108.0,17.97.0,52.85.0"}
P.entries["quest:299"] = {n="Enthüllung der Vergangenheit",s="Ausgrabungsleiter Whelgar braucht die vier fehlenden Stücke des Goazsteins aus seiner überrannten Ausgrabung im Sumpfland. Seine Inschriften warten auf ihre Übersetzung.",h="Ausgrabungsleiter Whelgar braucht die vier fehlenden Stücke des Goazsteins aus seiner überrannten Ausgrabung...",kw={"ados","goazstein","golm","modr","neru","alte götter","ausgrabungsleiter whelgar","titanen","enthüllung der vergangenheit","sumpfland","whelgars ausgrabungsstätte"},ang={["faction:Alliance"]="Als Mitglied der Allianz unterstützt Ihr Ausgrabungen der League im ganzen Sumpfland. Sie stärken die Präsenz der Allianz und bewahren wertvolles Wissen vor wilden oder feindlichen Händen.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Explorers' League jedes Relikt dafür schätzt, was es über die Herkunft der Zwerge enthüllen kann. Die Inschriften der Titanen auf dem Goazstein berühren dieses uralte Erbe."},sec={{t="Der zerbrochene Stein",b="Bevor Raptoren die Ausgrabung im Sumpfland überrannten, legte Ausgrabungsleiter Whelgar den Goazstein frei. Seine ersten Versuche, dessen uralte Schrift zu lesen, ergaben bruchstückhafte Hinweise auf einen göttlichen Plan und eine verhängnisvolle Prophezeiung. Vier Stücke waren abgebrochen, wodurch Passagen über das Ausgrabungsgelände verstreut lagen."},{t="Ins Ausgrabungsgelände",b="Um den Stein wiederherzustellen, durchsucht Ihr die von Raptoren bewachte Ausgrabung nach vier Fragmenten: Ados, Modr, Golm und Neru. Die Stücke liegen zwischen lockerem Erdreich und halb ausgegrabenen Relikten, bewacht von aggressiven Razormaws und Scytheclaws. Um sie zu erreichen, müsst Ihr Euch den wildesten Raubtieren des Sumpfes stellen."},{t="Unter der Erde angekettet",b="Der wieder zusammengesetzte Goazstein trägt die Sprache der Titanen. Als Whelgar seine Glyphen übersetzt, liest er einen schaurigen Satz: „Alte Götter... Unter der Erde angekettet.“ Die Tafel erzählt von Kämpfen aus der Frühzeit der Welt und von Übeln, die unter Azeroth begraben liegen."}},faq={{q="Was ist der Goazstein?",a="Der Goazstein ist ein uraltes Relikt der Titanen, das Ausgrabungsleiter Whelgar bei seiner Ausgrabung im Sumpfland fand. Seine rätselhaften Inschriften erzählen von einem göttlichen Plan und uralten Wesen, die tief unter der Erde gefesselt sind.",al={"geschichte des goazsteins","was ist die goaztafel","tafelfragmente sumpfland"}},{q="Wer vergibt die Quest Enthüllung der Vergangenheit?",a="Ausgrabungsleiter Whelgar bietet sie von einem Aussichtspunkt über Whelgars Ausgrabungsstätte an, östlich vom Hafen von Menethil im Sumpfland. Wilde Raptoren haben ihn aus seiner Ausgrabung vertrieben.",al={"wer startet enthüllung der vergangenheit","wo gibt es enthüllung der vergangenheit"}},{q="Welche Fragmente werden benötigt, um die Tafel zu vervollständigen?",a="Die vier Fragmente heißen Ados, Modr, Golm und Neru. Sie liegen zwischen lockeren Erdhügeln und uralten Urnen über den Boden des von Raptoren überrannten Steinbruchs verstreut.",al={"welche fragmente","namen der tafelstücke","ados modr golm neru"}},{q="Warum kann Ausgrabungsleiter Whelgar die Fragmente nicht selbst bergen?",a="Ausgrabungsleiter Whelgar ist ein betagter zwergischer Gelehrter. Als bösartige Raptoren in den Steinbruch eindrangen und ihn besetzten, musste er sich zurückziehen und konnte sich nicht allein durch ihre Rudel kämpfen.",al={"warum holt whelgar die steine nicht selbst","warum whelgar um hilfe bittet"}},{q="Was enthüllen die übersetzten Glyphen der Titanen?",a="Sobald die vier Stücke zusammengefügt sind, übersetzt Whelgar die Schrift der Titanen mit „Alte Götter... Unter der Erde angekettet.“ Die Worte deuten auf uralte kosmische Wesen hin, die während der Formung Azeroths eingekerkert wurden.",al={"was steht auf dem goazstein","übersetzung der titanenschrift sumpfland","alte götter unter der erde angekettet"}},{q="Hängt diese Quest mit anderen Expeditionen in der Nähe zusammen?",a="Ja. Ormer Eisenzopfs Quest Ormer's Revenge schickt Abenteurer los, um die Zahl der Raptoren im selben Ausgrabungssteinbruch zu verringern.",al={"quests nahe der ausgrabungsstätte","verbindung zu ormer eisenzopf","verbindung zu ormer's revenge"}}},fx={["2fe7ef8c"]={q="Warum möchte Ausgrabungsleiter Whelgar, dass die Tafelfragmente geborgen werden?",a="Ausgrabungsleiter Whelgar entdeckte ein massives Relikt, bekannt als Goazstein, kurz bevor Raptoren die Ausgrabungsstätte überrannten. Die übersetzten Teile seiner Titanenschrift sprechen düster von einem 'göttlichen Plan' und einer 'verhängnisvollen Prophezeiung', doch die Inschrift bricht abrupt in vier fehlenden Abschnitten ab. In der Befürchtung, dass die Zeit knapp wird, ist Whelgar verzweifelt darauf bedacht, die gesamte Tafel wieder zusammenzusetzen, damit er den Rest der Nachricht entziffern und die Geheimnisse aufdecken kann, die unter der Ausgrabung begraben liegen.",al={"whelgar motiv","warum fragmente finden","warum braucht whelgar fragmente"}},f38df7d0={q="Was sind die Ados-, Modr-, Golm- und Neru-Fragmente?",a="Die Ados-, Modr-, Golm- und Neru-Fragmente sind die vier fehlenden Stücke, die vom Goazstein abgebrochen sind. Jedes Fragment enthält einen Abschnitt alter Titanenschrift, der benötigt wird, um die Inschrift zu vervollständigen. Sobald sie wieder in den Hauptstein eingepasst sind, ermöglichen sie es Ausgrabungsleiter Whelgar, den Text fertig zu übersetzen und offenbaren bedrohliche Passagen über uralte Wesen, die unter der Erde angekettet sind.",al={"was sind die fragmente","ados modr golm neru","bedeutung tafelfragmente"}}},fp="19,135,16.274.0,20.277.0,24.249.1,23.184.1,40.167.0,49.150.0,59.169.0,43.188.1,54.107.0"}
P.entries["quest:2990"] = {n="Thadius Grimmschatten",s="Auf Burg Nethergarde schickt Talonaxe Euch mit einer Feder aus Scharfkralles Nest zu Thadius Grimmschatten.",h="Auf Burg Nethergarde schickt Talonaxe Euch mit einer Feder aus Scharfkralles Nest zu Thadius Grimmschatten.",kw={"nistgipfel","verwüstete lande","wahrsagerei","greif","burg nethergarde","scharfkralle","talonaxe","thadius grimmschatten"},sec={{t="Eine Bitte an einen Wahrsager",b="Vor Jahren verließ Thadius Grimmschatten den Nistgipfel, um dunkleres Wissen zu suchen. Doch Talonaxe sagt, im Herzen sei er ein Wildhammer geblieben. Er hofft, dass Thadius mit Wahrsagemagie und Scharfkralles Feder das Greifenjunge finden kann. Thadius lebt im Magierturm von Burg Nethergarde in den Verwüsteten Landen."},{t="Der Empfang des Wahrsagers",b="Thadius Grimmschatten begrüßt Euch als Überbringer eines Geschenks. Er erkennt die Feder als die eines prächtigen Greifen, dem Großes bestimmt ist, wenn er unversehrt heranwächst. Dann bittet Thadius Euch, genau zuzuhören."}},faq={{q="Wer ist Thadius Grimmschatten?",a="Thadius Grimmschatten verließ vor Jahren den Nistgipfel, um dunkleres Wissen zu suchen. Talonaxe sagt, im Herzen sei er ein Wildhammer geblieben.",al={"thadius grimmschatten hintergrund","wer ist thadius"}},{q="Warum braucht Ihr Scharfkralles Feder?",a="Scharfkralles Feder stammt aus dem Nest, in dem er schläft. Talonaxe hofft, dass Thadius mit Wahrsagemagie an der Feder den jungen Greifen finden kann.",al={"warum scharfkralles feder","zweck der feder"}},{q="Wo befindet sich Thadius Grimmschatten?",a="Thadius Grimmschatten lebt im Magierturm von Burg Nethergarde in den Verwüsteten Landen.",al={"thadius grimmschatten aufenthaltsort","wo ist thadius"}}},fp="17,98,19.288.0,21.208.1,25.117.0,36.134.0,35.84.0"}
P.entries["quest:2992"] = {n="Der Rutengang",s="Thadius Grimmschatten wendet sich Sharpbeaks Feder zu und sucht den Greifen anhand ihrer Spur. Er bittet Euch, ihm Platz zu machen, während er der Verbindung zu ihrem Besitzer folgt.",h="Thadius Grimmschatten wendet sich Sharpbeaks Feder zu und sucht den Greifen anhand ihrer Spur.",kw={"feder","greif","ritual","sharpbeak","thadius grimmschatten","der rutengang"},sec={{t="Ein Ritual der Weissagung",b="Thadius Grimmschatten folgt der Verbindung zwischen Sharpbeaks Feder und dem Greifen, dem sie gehört. Er hofft, Sharpbeak selbst zu erreichen, und bittet Euch um Ruhe und Platz zum Arbeiten. Das Ritual verläuft womöglich nicht nach Plan. Falls es misslingt, warnt er, solltet Ihr besser die Augen schließen."},{t="Wenn das Ritual endet",b="Thadius Grimmschatten erreicht Sharpbeak durch das Ritual. Er erhascht einen Blick auf den Greifen und kann Euch sagen, wo Ihr suchen müsst."}},faq={{q="Was tut Thadius Grimmschatten bei diesem Ritual?",a="Thadius Grimmschatten führt ein Ritual durch, um der Verbindung zwischen der von Euch mitgebrachten Feder und Sharpbeak zu folgen. Er hofft, den Greifen selbst zu erreichen.",al={"was ist der rutengang","grimmschattens ritual","wie findet grimmschatten sharpbeak"}},{q="Wer ist Sharpbeak?",a="Sharpbeak ist das Greifenkind, dessen Feder Ihr zu Thadius Grimmschatten gebracht habt. Greifenmeister Talonaxe versucht schon seit einiger Zeit, ihn zu finden.",al={"sharpbeak","wer ist sharpbeak"}},{q="Ist das Ritual gefährlich?",a="Thadius Grimmschatten warnt Euch, dass Ihr besser die Augen schließen solltet, falls das Ritual schiefgeht. Er bittet Euch, ihm Platz zu machen, während er arbeitet.",al={"ist der rutengang gefährlich","warum die augen schließen","risiko beim rutengang"}}},fp="14,154,22.265.0,20.111.1,47.140.0,17.131.0,24.131.0"}
P.entries["quest:2993"] = {n="Rückkehr ins Hinterland",s="Ihr überbringt Greifenmeister Talonaxe Thadius Grimmschattens Nachricht über Sharpbeak.",h="Ihr überbringt Greifenmeister Talonaxe Thadius Grimmschattens Nachricht über Sharpbeak.",kw={"gryphon master talonaxe","hinterland","jintha'alor","scharfkrall","thadius grimmschatten","vile priestess hexx","vilebranch"},sec={{t="Wo Scharfkrall gefangen gehalten wird",b="Thadius Grimmschatten hat erfahren, wo Sharpbeak gefangen gehalten wird. Der Greif sitzt in einem Käfig auf einer hohen Klippe auf dem Gipfel von Jintha'Alor im Hinterland. Vile Priestess Hexx, Hohepriesterin der Vilebranch-Trolle, hat den Schlüssel. Ihr überbringt Greifenmeister Talonaxe die Nachricht."},{t="Talonaxes Antwort",b="Greifenmeister Talonaxe kann die Nachricht nicht ertragen, dass die Vilebranch-Trolle Sharpbeak gefangen halten. Er erklärt, dass ein Trupp zusammengestellt werden muss, um den Greifen zurückzuholen."}},faq={{q="Wer enthüllt den Aufenthaltsort von Scharfkrall?",a="Thadius Grimmschatten enthüllt nach einem Weissagungsritual, wo Sharpbeak gefangen gehalten wird.",al={"wer euch sagt wo scharfkrall ist","scharfkrall aufenthaltsort quelle","wer scharfkrall findet"}},{q="Wo wird Scharfkrall gefangen gehalten?",a="Sharpbeak sitzt in einem Käfig auf einer hohen Klippe auf dem Gipfel von Jintha'Alor im Hinterland.",al={"wo ist scharfkrall","scharfkrall kaefig aufenthaltsort","scharfkrall klippe"}},{q="Wer besitzt den Schlüssel zu Scharfkralls Käfig?",a="Vile Priestess Hexx, Hohepriesterin der Vilebranch-Trolle, hat den Schlüssel zu Sharpbeaks Käfig.",al={"scharfkrall schluessel","wer hat kaefigschluessel","vile priestess hexx schluessel"}},{q="Wohin überbringt Ihr diese Nachricht?",a="Ihr überbringt Greifenmeister Talonaxe im Hinterland die Nachricht.",al={"zu wem kehre ich zurueck","wo rueckkehr ins hinterland abgeben","gryphon master talonaxe aufenthaltsort"}},{q="Was ging dieser Reise voraus?",a="Thadius Grimmschatten hatte gerade das Ritual der Wahrsagung vollzogen, um Scharfkrall zu finden.",al={"vorherige quest","was fuehrte zu rueckkehr ins hinterland","vorheriger schritt"}}},fp="25,75,23.252.0,17.157.1,38.90.0,30.71.0,38.96.0,31.67.0,30.80.0"}
P.entries["quest:2994"] = {n="Scharfschnabels Rettung",s="In Jintha'Alor wartet Sharpbeak in einem Käfig tief im Gebiet der Vilebranch. Greifenmeister Talonaxe schickt Euch, um ihn zu befreien, und Vile Priestess Hexx hat den Schlüssel.",h="In Jintha'Alor wartet Sharpbeak in einem Käfig tief im Gebiet der Vilebranch.",kw={"nistgipfel","gryphon master talonaxe","hinterland","jintha'alor","scharfschnabels rettung","sharpbeak","vile priestess hexx","vilebranch"},sec={{t="Hinauf nach Jintha'Alor",b="Nach Thadius Grimmschattens Wahrsagung erstattet Ihr Talonaxe Bericht. Nun ist der Weg zu Sharpbeak frei. Jintha'Alor liegt im Herzen des Gebiets der Vilebranch, und Ihr kämpft Euch den Weg zum Gipfel frei. Vile Priestess Hexx hat den Schlüssel zu Sharpbeaks Käfig. Nehmt ihn ihr ab, findet dann den Käfig und befreit den Greifen."},{t="Talonaxes Dank",b="Swiftwind und Keenclaw haben ihr Kind nach Hause gebracht und können gar nicht aufhören, es zu umsorgen. Der Anblick treibt Talonaxe Tränen in die Augen. Er sagt, die Schuld könne niemals beglichen werden. Die Greifen und Reiter des Nistgipfels werden Euren Namen noch lange besingen."}},faq={{q="Wer schickt Euch los, um Sharpbeak zu retten?",a="Greifenmeister Talonaxe schickt Euch los, um Sharpbeak zu retten, nachdem Thadius Grimmschattens Wahrsagung enthüllt hat, wo der Greif gefangen gehalten wird.",al={"wer vergibt scharfschnabels rettung","sharpbeak questgeber","wo beginnt scharfschnabels rettung"}},{q="Wo wird Sharpbeak gefangen gehalten?",a="Sharpbeak sitzt in einem Käfig auf dem Gipfel von Jintha'Alor, im Gebiet der Vilebranch im Hinterland.",al={"wo ist sharpbeak","sharpbeak fundort","wo ist sharpbeaks käfig"}},{q="Wer hat den Schlüssel zu Sharpbeaks Käfig?",a="Vile Priestess Hexx hat ihn.",al={"wer lässt sharpbeaks schlüssel fallen","wo ist hexx' schlüssel","vile priestess hexx schlüssel"}}},fp="16,157,14.304.0,17.235.1,34.125.0,30.92.0,38.27.0"}
P.entries["quest:2996"] = {n="Die Suche nach Strahad",s="In Orgrimmar schickt Gan'rul Blutauge Hexenmeister für schwierigere Lektionen nach Süden, nach Ratschet. Ein menschlicher Beschwörer dort lehrt Künste jenseits der grundlegenden Beschwörung.",h="In Orgrimmar schickt Gan'rul Blutauge Hexenmeister für schwierigere Lektionen nach Süden, nach Ratschet.",kw={"brachland","die kluft der schatten","teufelsjäger quest","gan'rul blutauge","ratschet","die suche nach strahad","strahad farsan","tome of the cabal"},ang={["class:Warlock"]="Als Hexenmeister steht Ihr kurz davor, dämonische Wesen mittleren Ranges zu beherrschen. Strahad prüft, ob Ihr den magieverschlingenden Teufelsjäger unterwerfen könnt.",["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie Hexenmeisterzirkel jenseits der förmlichen Diplomatie des Kriegshäuptlings wirken. Ihre Meister schicken Lehrlinge zu einem allein lebenden Menschen."},sec={{t="Die Schatten Orgrimmars verlassen",b="Gan'rul Blutauge unterrichtet junge Hexenmeister in der Kluft der Schatten. Dort lernen sie, den Nether zu befehligen. Wenn ein Lehrling diesen Lektionen entwächst, weist Gan'rul über die Stadtmauern hinaus. Unberechenbarere Wesen verlangen nach einem Lehrmeister mit tieferer Beherrschung der dunklen Arkana."},{t="Eine ungewöhnliche Allianz",b="Gan'rul schickt Lehrlinge zu Strahad Farsan, einem menschlichen Zauberer in einem Turm über Ratschets Goblinhafen. Die Horde und die Menschen mögen Feinde sein, doch Hexenmeister blicken über gewöhnliche Fraktionstreue hinaus. Macht, Disziplin und Ritualwissen zählen mehr als Abstammung. Strahad beurteilt einen Lehrling nach seinem inneren Hass und seiner Fähigkeit zur Unterwerfung, nicht nach seiner Hautfarbe."}},faq={{q="Warum schickt mich ein Orc-Hexenmeister zu einem Menschen?",a="Hexenmeister schätzen dunkles Wissen höher als die Treue zum eigenen Volk. Gan'rul Blutauge weiß um Strahad Farsans seltenes Können in der höheren Dämonologie, und bei gefährlichen Beschwörungen zählt das Wissen eines Lehrmeisters mehr als Fraktionsgrenzen.",al={"warum von einem menschen lernen","strahad menschlicher hexenmeister","warum strahad"}},{q="Wo kann ich Strahad Farsan finden?",a="Strahad Farsan lebt auf den hohen Klippen über Ratschet im Brachland. Sein Turm überblickt den Goblinhafen.",al={"strahad aufenthaltsort","wo ist strahad","strahad turm ratschet"}},{q="Welche Macht lehrt Strahad?",a="Strahad lehrt die Rituale zur Bindung eines Teufelsjägers, eines magieverschlingenden Dämons aus dem Twisting Nether. Er studiert mit Hexenmeistern okkulte Schriften und prüft dann, ob sie die Bestie versklaven können.",al={"was schaltet strahad frei","was bekomme ich von strahad","die suche nach strahad belohnung"}},{q="Wer ist Gan'rul Blutauge?",a="Gan'rul Blutauge ist ein angesehener Orc-Hexenmeisterlehrer in der Kluft der Schatten unter Orgrimmar. Er lehrt angehende Hexenmeister der Horde die Grundlagen der Teufelsmagie und der Beschwörung niederer Diener.",al={"wer ist ganrul","ganrul blutauge","orgrimmar hexenmeisterlehrer"}},{q="Gibt es einen anderen Weg, diese Quest zu beginnen?",a="Hexenmeister der Verlassenen erhalten einen ähnlichen Ruf aus dem Magieviertel in Unterstadt. Er verweist sie an denselben menschlichen Lehrmeister oberhalb von Ratschet.",al={"die suche nach strahad unterstadt","verlassene die suche nach strahad","unterstadt variante"}},{q="Birgt Ratschet Gefahren für Hexenmeister der Horde?",a="Ratschet wird vom Steamwheedle Cartel geführt und bleibt ein neutraler Hafen. Wahrt den Frieden und greift innerhalb der Stadt keine Reisenden an, dann lassen Euch die Goblinraufbolde in Ruhe.",al={"ist ratschet sicher","ratschet wachen feindselig","neutraler hafen"}}},fx={d843591e={q="Warum schickt Gan'rul Blutauge Euch zu Strahad?",a="Gan'rul Blutauge erkennt, dass Eure dunklen Talente seinem eigenen Unterricht in Orgrimmar entwachsen sind. Um auf dem Pfad der Dämonologie weiter voranzuschreiten und mächtigere Beschwörungen zu meistern, benötigt Ihr esoterisches Wissen, das nur Strahad Farsan besitzt. Gan'rul legt rassistische Vorurteile beiseite, um sicherzustellen, dass Eure Meisterschaft vertieft wird.",al={"warum zu strahad schicken","gan'rul blutauge motiv","warum strahad aufsuchen"}}},fp="15,142,32.257.0,22.346.0,44.221.0,32.106.0,30.188.1,24.181.0,41.140.0,47.166.0"}
P.entries["quest:2997"] = {n="Foliant der Offenbarung",s="Azar Hammerkraft schickt vielversprechende Zwergenpaladine aus Dun Morogh zur vertieften Unterweisung nach Eisenschmiede. Dort wartet Tiza Kriegshammer in der Hall of Mysteries, wo die Prüfungen im Dienste des Heiligen Lichts beginnen.",h="Azar Hammerkraft schickt vielversprechende Zwergenpaladine aus Dun Morogh zur vertieften Unterweisung nach...",kw={"azar hammerkraft","dun morogh","hall of mysteries","heiliges licht","eisenschmiede","mystic ward","paladin","erlösung","tiza kriegshammer","foliant der offenbarung"},ang={["class:Paladin"]="Als Paladin verbindet Ihr den praktischen Kriegsdienst im Schnee mit der tiefen geistlichen Disziplin, die von einem heiligen Krieger erwartet wird.",["faction:Alliance"]="Als Mitglied der Allianz teilt Ihr die Ehrfurcht vor dem Licht mit den zwergischen Verteidigern von Khaz Modan und Euren menschlichen Verbündeten in Lordaeron und Sturmwind.",["race:Dwarf"]="Als Zwerg verbindet Ihr die Ausdauer Eures Volkes mit den Lehren des Heiligen Lichts in Eisenschmiedes Hall of Mysteries."},sec={{t="Ein Ruf zum High Seat",b="Zwergische Initianten bewachen die verschneiten Dörfer und Straßen von Dun Morogh. Wenn Azar erkennt, dass ein Verteidiger für eine tiefere geistliche Unterweisung bereit ist, schickt er diesen Anwärter vom Felddienst nach Eisenschmiede. Dort können ihn die heiligen Ältesten der Stadt anleiten."},{t="Die Hall of Mysteries",b="Die Vorladung führt Euch durch den Mystic Ward zur Hall of Mysteries. Heilige Relikte und andächtiges Studium erfüllen ihre Hallen. Tiza Kriegshammer prüft Eure Bereitschaft zur Selbstaufopferung, zur Barmherzigkeit und zu den moralischen Pflichten Eurer Berufung."}},faq={{q="Welchen Zweck hat diese Quest?",a="Azar Hammerkraft ruft einen vielversprechenden Zwergenpaladin vom Felddienst in Dun Morogh ab und schickt Euch zu Tiza Kriegshammer in Eisenschmiede. Die Prüfungen unterweisen Euch im Heiligen Licht und sind erforderlich, um die Macht der Auferstehung zu erlangen.",al={"warum ist diese quest nötig","wozu dient der foliant der offenbarung","foliant der offenbarung zweck"}},{q="Wer ist Tiza Kriegshammer?",a="Tiza Kriegshammer ist eine erfahrene Zwergenpaladinin und angesehene Mentorin in Eisenschmiedes Hall of Mysteries. Sie führt junge Paladine durch die geistliche Unterweisung und die heiligen Prüfungen des Folianten der Offenbarung.",al={"wer ist tiza","tiza kriegshammer hintergrundgeschichte","wer ist kriegshammer"}},{q="Wo befindet sich die Hall of Mysteries?",a="Die Hall of Mysteries liegt im Mystic Ward im Westen von Eisenschmiede. Priester, Paladine und Magier versammeln sich dort, im geistlichen und arkanen Zentrum der zwergischen Hauptstadt.",al={"wo ist die hall of mysteries","hall of mysteries finden","hall of mysteries eisenschmiede"}},{q="Wer schickt den Paladin auf diesen Botengang?",a="Azar Hammerkraft, ein Paladinlehrer in Dun Morogh, schickt vielversprechende Initianten nach Eisenschmiede, nachdem sie ihre Hingabe bei der Verteidigung der örtlichen Zwergensiedlungen bewiesen haben.",al={"wer startet foliant der offenbarung","questgeber foliant der offenbarung","azar hammerkraft"}},{q="Warum müssen Zwergenpaladine in Eisenschmiede studieren?",a="Azar lehrt grundlegende Kampffertigkeiten im Feld, während die Hall of Mysteries die förmlichen Lehren, heiligen Schriften und Ältesten des Heiligen Lichts beherbergt. Erfahrene Mentoren wie Tiza Kriegshammer leiten das Studium fortgeschrittener Riten und geistlicher Lehren.",al={"warum nach eisenschmiede gehen","warum in eisenschmiede ausbilden lassen"}},{q="Was folgt nach dem Gespräch mit Tiza Kriegshammer?",a="Mit dem Gespräch mit Tiza beginnen die zwergischen Prüfungen des Folianten der Offenbarung. Sie fordern Euch auf, Hingabe, Mitgefühl und Opferbereitschaft im Dienste des Lichts zu zeigen.",al={"what comes next","nächste quest nach foliant der offenbarung","was gibt tiza"}}},fx={d775d5e6={q="Warum möchte Azar Hammerkraft, dass Ihr Eisenschmiede besucht?",a="Azar Hammerkraft erkennt, dass Eure Zeit als Lehrling, der Dun Morogh unterstützt, sich dem Ende zuneigt. Um wahrhaftig als Champion des Heiligen Lichts zu dienen, benötigt Ihr tiefergehenden Unterricht in seinen Mysterien, Prinzipien und Verpflichtungen. Er schickt Euch nach Eisenschmiede, weil Tiza Kriegshammer damit betraut ist, vielversprechende junge Paladine zu prüfen und zu ihrer wahren Berufung zu führen.",al={"warum schickt azar","azar hammerkraft motiv","warum tiza kriegshammer aufsuchen"}},a7a63213={q="Warum schickt Azar Hammerkraft Euch persönlich?",a="Diese Reise ist kein Botengang, den ein Stadtwache oder ein etablierter Veteran für Euch erledigen könnte. Sie markiert Eure persönliche Entwicklung als Paladin. Azar schickt Euch zu Tiza Kriegshammer, weil Ihr allein dem Ruf des Lichts folgen, Eure Hingabe an seine Tugenden beweisen und die Bürden akzeptieren müsst, die von einem heiligen Krieger erwartet werden.",al={"warum schickt er mich","warum azar schickt","warum paladin"}}},fp="16,213,23.242.0,21.221.0,34.225.0,24.203.0,39.169.0,37.164.0,45.238.0,50.157.0"}
P.entries["quest:2998"] = {n="Foliant der Offenbarung",s="Eine Vorladung ruft nun vielversprechende Paladine aus Elwynn nach Sturmwind. Bruder Wilhelm lässt sie rufen, und der Foliant der Offenbarung eröffnet die heiligen Prüfungen, die lehren, die Auferweckung durch das Heilige Licht zu meistern.",h="Eine Vorladung ruft nun vielversprechende Paladine aus Elwynn nach Sturmwind.",kw={"bruder wilhelm","kathedrale des lichts","duthorian rall","goldhain","paladin","erlösung","sturmwind","foliant der offenbarung"},ang={["class:Paladin"]="Als Paladin erkennen Eure Mentoren Eure Taten an und schicken Euch vor die hohen Befehlshaber der Silbernen Hand. Dies ist ein Übergangsritus für Paladine.",["faction:Alliance"]="Indem Sturmwind heilige Krieger anwirbt und prüft, hilft es der Allianz, in unruhigen Zeiten auf hingebungsvolle Heiler und Kämpfer an vorderster Front zählen zu können.",["race:Human"]="Als Mensch verbindet Euch Eure Reise vom ländlichen Wald von Elwynn zur prächtigen Kathedrale des Lichts mit den tief verwurzelten geistlichen und militärischen Institutionen des Königreichs."},sec={{t="Eine Vorladung in die Hauptstadt",b="Im Wald von Elwynn verbringen Paladinnovizen ihre ersten Tage damit, Einheimischen zu helfen und ihre Stärke gegen Wölfe, Defias-Banditen und Kobolde zu erproben. Wenn ein Initiand Disziplin im Kampf und Hingabe an das Heilige Licht zeigt, schicken Mentoren wie Bruder Wilhelm eine persönliche Vorladung. Die Anführer der Paladine werden auf vielversprechende Schüler aufmerksam und weisen sie an, die örtlichen Kapellen hinter sich zu lassen. Sie sollen sich im geistlichen Herzen des Königreichs melden."},{t="Die Kathedrale des Lichts",b="Am Kathedralenplatz ist Sturmwinds Kathedrale des Lichts das bedeutendste Heiligtum des Königreichs für seine Priesterschaft und die Ritter der Silbernen Hand. Duthorian Rall lebt dort und beaufsichtigt jene, die dem Orden die Treue geschworen haben. Unter ihren Gewölbedecken stellen hochrangige Paladine jedem Initianden die förmlichen Prüfungen des Folianten der Offenbarung. Die Prüfungen erproben Mitgefühl, Standhaftigkeit und Opferbereitschaft."}},faq={{q="Wer schickt mich für diese Quest nach Sturmwind?",a="Bruder Wilhelm, der Paladinlehrer nahe dem Gasthaus \"Zur Höhle des Löwen\" in Goldhain, schickt Euch nach Sturmwind, nachdem Ihr draußen Euer Potenzial und Eure Stärke bewiesen habt.",al={"questgeber","wer vergibt die quest","bruder wilhelm"}},{q="Wo finde ich Duthorian Rall?",a="Duthorian Rall hält sich in der Kathedrale des Lichts am Kathedralenplatz im Nordwesten von Sturmwind auf. Die meiste Zeit bildet er in ihren prächtigen Hallen Paladine aus.",al={"duthorian rall standort","wo ist duthorian rall","paladinmeister standort"}},{q="Warum ist diese Vorladung für Paladine so wichtig?",a="Sich bei Duthorian Rall zu melden, kennzeichnet den Übergang von der grundlegenden Kampfausbildung zur tiefen Zwiesprache mit dem Heiligen Licht. Dort beginnen die Prüfungen des Folianten der Offenbarung, die schließlich die heilige Macht verleihen, gefallene Verbündete durch das Licht aus dem Tod zurückzurufen.",al={"warum diese quest machen","bedeutung der quest","paladinprüfung"}},{q="Erhalten nichtmenschliche Paladine genau diese Quest?",a="Bruder Wilhelms Vorladung aus dem Wald von Elwynn richtet sich an menschliche Paladine. Zwergische Paladine erhalten von ihren Lehrern in Dun Morogh einen entsprechenden Ruf, Eisenschmiede aufzusuchen.",al={"zwergenpaladin","können zwerge das machen","ist diese quest nur für menschen"}},{q="Was geschieht, nachdem ich mich bei Duthorian Rall gemeldet habe?",a="Wenn Ihr Duthorian Rall begrüßt, heißt er Euch in Sturmwind willkommen und stellt Euch die Prüfungen des Folianten der Offenbarung vor. Sie stellen Euer Mitgefühl und Eure Hingabe an den Schutz der Schwachen auf die Probe.",al={"nächste quest","was passiert als nächstes","foliant der offenbarung nächster schritt"}},{q="Wer ist Duthorian Rall?",a="Duthorian Rall zählt zu den einflussreichsten Paladinen in Sturmwind und unter den Rittern der Silbernen Hand. Er unterweist neue Generationen heiliger Krieger in der Hauptstadt.",al={"wer ist duthorian","duthorian rall hintergrundgeschichte"}}},fx={["69ec335a"]={q="Warum schickt Bruder Wilhelm Euch zu Duthorian Rall?",a="Bruder Wilhelm hegt großen Respekt für Duthorian Rall, einen der einflussreichsten Paladine des Ordens. Nachdem er gehört hat, wie Duthorian voller Anerkennung von Eurem Dienst sprach und erwähnte, dass Ihr bereit seid, auf die Probe gestellt zu werden, möchte Wilhelm einfach sicherstellen, dass Ihr die Gelegenheit ergreift. Vielversprechende Novizen zu fortgeschrittener Unterweisung zu führen, ist seine Pflicht und sein Stolz als Mentor in Goldhain.",al={"warum schickt wilhelm","bruder wilhelm motiv","warum mit duthorian rall sprechen"}}},fp="16,205,24.425.0,22.397.0,41.155.0,32.168.0,46.251.0,47.171.0,47.177.0,22.164.0"}
P.entries["quest:2999"] = {n="Foliant der Offenbarung",s="In Eisenschmiede werden junge Zwergenpaladine zu Tiza Kriegshammer geschickt, um die tieferen Pflichten des Heiligen Lichts kennenzulernen. Ihr Übergangsritus führt über die Kampfausbildung hinaus zu heiligen Gelübden.",h="In Eisenschmiede werden junge Zwergenpaladine zu Tiza Kriegshammer geschickt, um die tieferen Pflichten des...",kw={"brandur eisenhammer","hall of mystics","eisenschmiede","paladin","redemption","tiza kriegshammer","foliant der offenbarung"},ang={["class:Paladin"]="Als Paladin führt Euer Weg von Kampfübungen zu den spirituellen Pflichten des Heiligen Lichts. Die Prüfungen führen Euch zur Macht von Redemption.",["race:Dwarf"]="Als Zwerg verbindet Ihr die Hingabe an das Heilige Licht mit Khaz Modans Traditionen der Pflicht und Brüderlichkeit. Ihr folgt dem Ruf in Eisenschmiedes Berghallen."},sec={{t="Der Ruf zum High Seat",b="Ihr habt Ambossar und Kharanos gegen Troggs und Frosttrolle verteidigt und Eure Disziplin im Kampf bewiesen. Nun schickt Euch Euer Lehrer Brandur Eisenhammer in der Hall of Mysteries nach oben. Dort bereiten ranghöhere Paladine Initianten auf die spirituellen Pflichten des Ordens vor."},{t="Führung durch Tiza Kriegshammer",b="Tiza Kriegshammer lehrt, dass das Licht mehr verlangt als Schwertkunst und Hammerschläge. Es verlangt Mitgefühl, Gerechtigkeit und Selbstaufopferung. Sie aufzusuchen beginnt Euer förmliches Studium des Folianten der Offenbarung, eines heiligen Weges zur Macht, die Gefallenen wiederzubeleben."}},faq={{q="Welchen Zweck hat diese Quest?",a="Brandur Eisenhammer schickt junge Zwergenpaladine von ihrem Lehrer zur ranghöheren Paladinin Tiza Kriegshammer in Eisenschmiede. Damit beginnen die Prüfungen, um den Folianten der Offenbarung zu studieren und die Macht der spirituellen Auferstehung zu erlangen.",al={"was bewirkt diese quest","foliant der offenbarung beginn","warum diese quest machen"}},{q="Wer ist Brandur Eisenhammer?",a="Brandur Eisenhammer bildet Zwergenpaladine in der Hall of Mysteries im Mystic Ward von Eisenschmiede aus. Er wacht über junge Paladine und schickt vielversprechende Initianten nach oben zu Tiza Kriegshammer, sobald sie für größere heilige Pflichten bereit sind.",al={"wer vergibt diese quest","brandurs rolle","brandur eisenhammer hintergrundgeschichte"}},{q="Wer ist Tiza Kriegshammer?",a="Tiza Kriegshammer ist eine angesehene, kampferfahrene Paladinin im oberen Stockwerk der Hall of Mysteries in Eisenschmiede. Sie lehrt jüngere Paladine, was das Heilige Licht über das Kampfgeschick hinaus verlangt.",al={"wo ist tiza","tiza kriegshammers rolle","wer ist tiza"}},{q="Wohin führt diese Quest als Nächstes?",a="Mit einem Gespräch mit Tiza Kriegshammer beginnen die Prüfungen des Folianten der Offenbarung. Sie prüfen die Hingabe, Barmherzigkeit und Bereitschaft eines Paladins, im Dienste des Lichts Leben zu schützen und wiederherzustellen.",al={"nächste quest","was kommt danach","foliant der offenbarung questreihe"}},{q="Warum müssen Zwergenpaladine den Folianten der Offenbarung aufsuchen?",a="Ein Paladin muss Selbstlosigkeit und spirituelle Pflichterfüllung erlernen, um einen gefallenen Verbündeten ins Leben zurückzuholen. Der Foliant der Offenbarung führt Initianten durch förmliche Lektionen und Glaubensprüfungen, die nötig sind, um solch mächtige heilige Kraft zu kanalisieren.",al={"warum foliant der offenbarung","paladin wiederbelebungsquest hintergrundgeschichte","redemption zwerg"}},{q="Erhalten Menschen dieselbe Unterweisung in Eisenschmiede?",a="Menschliche Paladine folgen einem ähnlichen Weg durch die Kathedrale des Lichts in Sturmwind. Brandur Eisenhammers Aufforderung, Tiza Kriegshammer aufzusuchen, richtet sich an Zwerge, die in Eisenschmiede ausgebildet werden.",al={"können menschen das machen","ist das nur für zwerge","mensch foliant der offenbarung"}}},fx={["1a85ab42"]={q="Warum schickt Brandur Eisenhammer Euch zu Tiza Kriegshammer?",a="Brandur Eisenhammer erkennt, dass Eure Ausbildungszeit in Dun Morogh Euch auf tiefergehende Verantwortungen innerhalb des Ordens vorbereitet hat. Anstatt Euch an lokale Probleme zu binden, möchte er, dass Ihr in Eurer Berufung voranschreitet. Tiza Kriegshammer wird unter zwergischen Paladinen als eine Mentorin verehrt, die jüngere Novizen anleitet, wenn sie bereit sind zu lernen, was das Heilige Licht wirklich von ihnen verlangt.",al={"warum schickt brandur","brandur eisenhammer motiv","warum mit tiza kriegshammer sprechen"}},["264c72ef"]={q="Warum müsst Ihr selbst mit Tiza sprechen, anstatt dass Brandur das erledigt?",a="Der Pfad eines Paladins ist zutiefst persönlich und kann nicht durch Stellvertreter beschritten werden. Brandur Eisenhammer kann Euer frühes kämpferisches Training leiten, aber spirituelle Weiterentwicklung erfordert, dass Ihr Euch persönlich vor Euren Ältesten präsentiert. Tiza Kriegshammer muss Eure Hingabe und Entschlossenheit aus erster Hand beurteilen, bevor sie Euch heilige Lehren wie die 'The Tome of Divinity' anvertrauen kann.",al={"warum tome of divinity","warum muss ich zu tiza","warum geht brandur nicht selbst"}}},fp="16,184,25.261.0,30.253.0,34.221.0,26.233.0,24.169.0,32.174.0,56.207.0,53.169.0"}
P.entries["quest:30"] = {n="Prüfung des Seelöwen",s="Tajarri bittet Euch, in der Mondlichtung zwei Anhängerhälften zu suchen und den zusammengefügten Anhänger des Seelöwen zu Dendrite Sternenschauer zu bringen. Hinweise der Bewohner führen zu den Hälften, und am Schrein von Remulos können sie zusammengefügt werden.",h="Tajarri bittet Euch, in der Mondlichtung zwei Anhängerhälften zu suchen und den zusammengefügten Anhänger des...",kw={"wasser-beweglichkeit","wasser-belastbarkeit","dendrite sternenschauer","mondlichtung","nachthafen","anhänger","seelöwe","schrein von remulos","trial of the sea lion"},sec={{t="Tajarris Bitte",b="Tajarri am Schrein von Remulos bittet Euch, zwei Hälften eines Anhängers in der Mondlichtung zu finden. Die Bewohner wissen vielleicht, wo der Halbe Anhänger der Wasser-Beweglichkeit und der Halbe Anhänger der Wasser-Belastbarkeit zu finden sind. Bringt den zusammengefügten Anhänger des Seelöwen zu Dendrite Sternenschauer in Nachthafen."},{t="Am Schrein",b="Die beiden Anhängerhälften lassen sich in der Nähe des Schreins von Remulos zusammenfügen. Sobald der Anhänger des Seelöwen zusammengesetzt ist, soll er zu Dendrite Sternenschauer in Nachthafen gebracht werden."}},faq={{q="Was möchte Dendrite Sternenschauer?",a="Dendrite Sternenschauer wartet in Nachthafen auf den zusammengefügten Anhänger des Seelöwen. Tajarri schickt Euch los, die beiden Anhängerhälften in der Mondlichtung zu finden und sie nahe dem Schrein von Remulos zusammenzufügen.",al={"dendrites bitte","was braucht dendrite"}},{q="Wo finde ich Hinweise zu den Anhängerhälften?",a="Die Bewohner der Mondlichtung haben vielleicht Hinweise darauf, wo sich der Halbe Anhänger der Wasser-Beweglichkeit und der Halbe Anhänger der Wasser-Belastbarkeit befinden.",al={"anhänger hinweise","wo sind die hälften"}},{q="Wo füge ich die beiden Hälften zusammen?",a="Die beiden Anhängerhälften lassen sich in der Nähe des Schreins von Remulos zusammenfügen.",al={"anhänger zusammenfügen","schrein anhänger"}},{q="Wo wartet Dendrite Sternenschauer?",a="Dendrite Sternenschauer befindet sich im Dorf Nachthafen in der Mondlichtung.",al={"dendrites standort","wo ist dendrite"}}},fp="21,229,17.286.0,13.159.0,34.182.0,48.144.0,31.75.0,36.64.0"}
P.entries["quest:3000"] = {n="Foliant der Offenbarung",s="In Eisenschmiede kehren zwergische Paladine zurück, um ihre Ausbildung im Heiligen Licht zu vertiefen. Lord Grayson Schattenbruch schickt sie heim, und Tiza Kriegshammer führt sie zu den heiligen Prüfungen des Folianten der Offenbarung.",h="In Eisenschmiede kehren zwergische Paladine zurück, um ihre Ausbildung im Heiligen Licht zu vertiefen.",kw={"zwergenpaladin","hall of mysteries","eisenschmiede","lord grayson schattenbruch","mystic ward","erlösung","tiza kriegshammer","foliant der offenbarung"},ang={["class:Paladin"]="Als Paladin beginnt Ihr einen bedeutenden Übergangsritus, indem Ihr den Folianten der Offenbarung studiert und die Gabe der Auferstehung meistert.",["faction:Alliance"]="Als Mitglied der Allianz erkennt Ihr die engen geistigen Bande zwischen Zwergen und Menschen an der gemeinsamen Ausbildung und dem gegenseitigen Respekt zwischen Sturmwinds Paladinen und Eisenschmiedes Mentoren.",["race:Dwarf"]="Als Zwerg kehrt Ihr aus menschlichen Landen nach Eisenschmiede zurück, Eurer angestammten Heimat in Khaz Modan, um bei Euren eigenen Ältesten zu lernen."},sec={{t="Ein Ruf in die Heimat",b="Zwergische Paladine bewahren ihre geistigen und kriegerischen Wurzeln in Khaz Modan, selbst wenn sie Sturmwind dienen oder durch menschliche Lande reisen. Sobald Lord Grayson Schattenbruch urteilt, dass ein Zwerg genug Erfahrung im Felde gesammelt hat, schickt er ihn heim. Dort lernt er die Pflichten kennen, die von einem vollwertigen Ritter der Silbernen Hand erwartet werden."},{t="Die Hall of Mysteries",b="In Eisenschmiede werdet Ihr zum Mystic Ward und zur Hall of Mysteries geschickt. Tiza Kriegshammer wartet im Obergeschoss, wo sie junge zwergische Paladine anleitet. Sie bereitet sie darauf vor, durch heilige Prüfungen, die im Folianten der Offenbarung festgehalten sind, die Bürde des Heiligen Lichts zu tragen."}},faq={{q="Warum schickt mich Lord Grayson Schattenbruch nach Eisenschmiede zurück?",a="Lord Grayson Schattenbruch schickt Euch zurück, weil zwergische Paladine die tieferen Lehren und Prüfungen des Heiligen Lichts bei ihrem eigenen Volk erlernen. Tiza Kriegshammer leitet diese Ausbildung.",al={"warum nach eisenschmiede","warum grayson mich wegschickt","warum tiza besuchen"}},{q="Wer ist Tiza Kriegshammer?",a="Tiza Kriegshammer ist eine der angesehensten zwergischen Paladininnen von Eisenschmiede. Sie leitet junge Paladine im Obergeschoss der Hall of Mysteries an und wacht über ihre Prüfungen.",al={"tiza kriegshammer","wer ist tiza","paladinausbilderin tiza"}},{q="Wo kann ich Tiza Kriegshammer finden?",a="Ihr findet Tiza Kriegshammer im Obergeschoss der Hall of Mysteries, im Mystic Ward von Eisenschmiede.",al={"wo ist tiza","tiza kriegshammer fundort","wie tiza finden"}},{q="Was ist der Foliant der Offenbarung?",a="Der Foliant der Offenbarung hält die heiligen Lehren und Prüfungen fest, durch die Paladine das Heilige Licht meistern, besonders Auferstehung und Hingabe an gefallene Verbündete.",al={"foliant der offenbarung bedeutung","was ist der foliant","paladinbuch"}},{q="Können menschliche Paladine diese Variante der Quest absolvieren?",a="Nein. Dieser Ruf führt zwergische Paladine zu den Ausbildern ihrer Heimat. Menschliche Paladine durchlaufen ihre Prüfungen bei Lord Grayson Schattenbruch und Duthorian Rall in Sturmwind.",al={"können menschen das machen","ist diese quest nur für zwerge"}},{q="Was geschieht, nachdem ich mich bei Tiza Kriegshammer gemeldet habe?",a="Nachdem Ihr Euch Tiza Kriegshammer vorgestellt habt, trägt sie Euch die förmlichen zwergischen Prüfungen aus dem Folianten der Offenbarung auf. Sie prüfen, ob Ihr bereit seid, die erlösende Macht des Lichts einzusetzen.",al={"what comes next","nächste quest nach foliant der offenbarung","nach dem gespräch mit tiza"}}},fx={c5356bb5={q="Warum wählt Lord Grayson Schattenbruch mich dafür aus?",a="Lord Grayson erkennt Euer wachsendes Potenzial als Paladin, respektiert aber die ausgeprägten Traditionen Eures Volkes. Anstatt Euch vollständig innerhalb der Kathedrale des Lichts in Sturmwind zu unterrichten, weiß er, dass junge zwergische Paladine in den Lehren ihrer eigenen Ältesten verwurzelt sein müssen. Er schickt Euch nach Hause, weil es Zeit für Euren nächsten heiligen Ritus ist, und Tiza Kriegshammer ist die verehrte Mentorin, die Zwerge durch diesen spirituellen Meilenstein führt.",al={"warum tome of divinity","warum schickt grayson","warum zwerg paladin"}}},fp="16,201,14.310.0,21.262.0,62.178.0,24.159.0,34.92.0,29.156.0,48.174.0,49.176.0"}
P.entries["quest:3001"] = {n="Die Suche nach Strahad",s="Carendin Halgar schickt Hexenmeister der Horde über das große Meer, um Strahad Farsan aufzusuchen. Oberhalb von Ratschet bietet ihnen ein menschlicher Zauberer einen Weg über die Grundlagen hinaus zur schwierigen Kunst, einen Teufelsjäger zu beschwören.",h="Carendin Halgar schickt Hexenmeister der Horde über das große Meer, um Strahad Farsan aufzusuchen.",kw={"brachland","carendin halgar","teufelsjäger","ratschet","die suche nach strahad","strahad farsan","tome of the cabal","unterstadt","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister durchlauft Ihr damit um Euren dreißigsten Kreis der Macht einen Übergangsritus. Ihr lasst die Bindung niederer Wichtel und Leerwandler hinter Euch und wendet Euch der Beherrschung des räuberischen Teufelsjägers zu.",["faction:Horde"]="Als Hexenmeister der Horde legt Ihr Eure übliche Feindseligkeit gegenüber Menschen ab und reist ins neutrale Ratschet, um von einem lebenden Zauberer zu lernen.",["race:Undead"]="Als Untoter gehört Ihr zu den Schülern der Verlassenen, die Carendin Halgar aus Unterstadt entsendet. Seine Wahl zeigt, dass selbst Sylvanas' Getreue lebende Meister nutzen, um ihr Arsenal zu erweitern."},sec={{t="Ein Meister jenseits des Meeres",b="Carendin Halgar bildet im Magieviertel von Unterstadt Hexenmeister aus. Wenn ein Initiant den Grundlagen entwachsen ist, schickt er ihn über die Ruinen von Lordaeron hinaus, um Strahad Farsan zu finden. Halgar warnt, dass Strahad ein lebender Mensch, aber kein Schwächling ist, und mahnt, ihn nicht als Feind zu behandeln. Das Streben nach dämonischer Meisterschaft kann die Grenzen von Volk und Fraktion überschreiten."},{t="Der Rundblick bei Ratschet",b="Strahad wirkt auf den Klippen oberhalb von Ratschet, dem Goblinhafen im Brachland. Nahe einem steinernen Wachturm blickt er auf die Seeleute, Söldner und Händler hinab, amüsiert über ihre selige Unwissenheit über den Wirbelnden Nether. Hexenmeister der Horde mögen mit Misstrauen und schwelendem Hass in den Augen zu ihm kommen. Strahad nimmt diese rohe Bosheit als Treibstoff an, den er zu dunkler Autorität formen kann."}},faq={{q="Warum schickt mich ein Hexenmeister aus Unterstadt zu einem Menschen?",a="Hexenmeister lassen Fraktionsgrenzen oft hinter sich, um seltenem und mächtigem dunklem Wissen nachzuspüren. Carendin Halgar sagt, Strahad Farsan verfüge über besondere Kenntnisse in der Beschwörung größerer Dämonen, die Halgar nicht vermitteln kann. Beim Streben nach dämonischer Macht zählt das Wissen eines Lehrers mehr als seine Abstammung.",al={"warum menschlicher lehrer","warum zu einem menschen schicken","carendin schickt zu strahad"}},{q="Wo genau befindet sich Strahad Farsan?",a="Strahad Farsan befindet sich im Brachland, auf den hohen Klippen oberhalb des Goblinhafens Ratschet. Er steht nahe einem steinernen Turm mit Blick auf die Bucht und die geschäftigen Hafenkais.",al={"strahads standort","wo ist strahad","wie strahad finden"}},{q="Welche Art von Macht lehrt Strahad?",a="Strahad führt erfahrene Hexenmeister durch komplexe Rituale zur Bindung größerer Dämonen aus dem Wirbelnden Nether. Seine Unterweisung führt zu den gefährlichen Prüfungen, einen Teufelsjäger zu beschwören und zu befehligen.",al={"was lehrt strahad","wozu dient diese quest","teufelsjägerquest"}},{q="Ist Strahad mit der Allianz verbündet?",a="Obwohl Strahad ein Mensch ist, wirkt er im neutralen Goblingebiet in Ratschet und gehört nicht der Großen Allianz an. Er ist ein unabhängiger Zauberkundiger, der gleichermaßen mit Hexenmeistern der Horde und der Allianz verkehrt, sofern sie seiner Unterweisung standhalten.",al={"gehört strahad zur allianz","strahads fraktion","ist strahad freundlich"}},{q="Was geschieht nach der Ankunft bei Strahad?",a="Bei Eurer Ankunft prüft Strahad Eure Entschlossenheit und beauftragt Euch, die verstreuten Fragmente und Bestandteile des Tome of the Cabal zu bergen. Die Suche führt Euch weit umher, während Ihr dem Ritual zur Beschwörung eines Teufelsjägers nachspürt.",al={"was kommt nach strahad","tome of the cabal","nächste quest"}},{q="Warum begrüßt Strahad den Hass seiner Schüler?",a="Dämonische Magie nährt sich von starken Gefühlen, Dominanz und Willenskraft. Hass lässt sich bündeln und disziplinieren und hilft einem Beschwörer, chaotische Wesen aus dem Nether zu binden, bevor sie jemanden ohne Disziplin verschlingen.",al={"warum mag strahad hass","hass in den augen"}}},fx={c0e56201={q="Warum schickt Euch Carendin, anstatt selbst zu gehen?",a="Carendin Halgar dient als Hexenmeister-Ausbilder in der Unterstadt und unterweist Novizen, soweit es seine Lehren erlauben. Ihr seid über die grundlegenden Künste hinausgewachsen, die er Anfängern vermittelt, und habt bewiesen, dass Ihr bereit für größere Beschwörungen seid. Dies ist keine diplomatische Mission, sondern eine Prüfung für Euer eigenes Vorankommen. Er schickt Euch los, um Strahad Farsan zu suchen, da Eure eigene Meisterschaft der dunklen Künste getestet und erweitert werden muss.",al={"warum soll ich strahad suchen","warum geht carendin nicht selbst","warum braucht carendin mich"}}},fp="15,212,23.343.0,23.373.0,50.293.0,40.154.0,38.203.0,36.229.0,36.207.0,48.209.0"}
P.entries["quest:3002"] = {n="Die Gordunnikugel",s="Nach Dark Ceremony schickt Euch Rok Orhan mit der Gordunnikugel nach Orgrimmar. Uthel'nay in der Darkbriar Lodge kann ihre Macht beurteilen.",h="Nach Dark Ceremony schickt Euch Rok Orhan mit der Gordunnikugel nach Orgrimmar.",kw={"darkbriar lodge","feralas","gordunni","gordunnikugel","orgrimmar","rok orhan","uthel'nay"},sec={{t="Jenseits des Wissens eines Kriegers",b="Nach Dark Ceremony hält Rok Orhan die Gordunnikugel in Händen. Er kennt die Gordunni gut, doch ein Krieger kann die Macht der Kugel nicht beurteilen. Deshalb schickt er Euch damit nach Orgrimmar. Dort kann Euch Uthel'nay in der Darkbriar Lodge mehr erzählen."},{t="Uthel'nays Urteil",b="Uthel'nay findet die Gordunnikugel faszinierend. Der Magier sagt, sie sei sehr mächtig und sehr gefährlich."}},faq={{q="Wer schickt Euch zu Uthel'nay?",a="Nachdem Ihr die Kugel aus Dark Ceremony zurückgebracht habt, schickt Euch Rok Orhan zu Uthel'nay.",al={"gordunnikugel questreihe","folgequest von dark ceremony","voraussetzungen für die gordunnikugel"}},{q="Warum untersucht Rok Orhan die Kugel nicht?",a="Rok Orhan kennt die Gordunni gut, doch als Kriegerin kann sie die Macht der Kugel nicht beurteilen. Sie kennt einen Magier in Orgrimmar, der Euch mehr erzählen kann.",al={"warum die kugel nach orgrimmar schicken","warum rok orhan die kugel weggibt","warum uthel'nay"}},{q="Wo ist Uthel'nay?",a="Uthel'nay ist in der Darkbriar Lodge in Orgrimmar.",al={"uthel'nay standort","wo ist uthelnay","darkbriar lodge standort"}},{q="Was kommt vor der Gordunnikugel?",a="Dark Ceremony kommt zuerst. Rok Orhan hat Euch losgeschickt, um einem Magierlord der Gordunni eine Kugel abzunehmen.",al={"gordunnikugel voraussetzung","gordunnikugel vorherige quest"}}},fp="16,126,28.219.0,19.99.1,27.82.0,39.138.0,19.45.0,35.87.0"}
P.entries["quest:301"] = {n="Meldung in Eisenschmiede",s="Jern Hornhelm schickt Eisenbands Bericht zu Ausgrabungsleiter Sturmlanze in Eisenschmiede. Der Ausgrabung im südlichen Loch Modan fehlt es an Sprengstoff, und die Forscherliga muss sich darum kümmern.",h="Jern Hornhelm schickt Eisenbands Bericht zu Ausgrabungsleiter Sturmlanze in Eisenschmiede.",kw={"sprengpulver","forscherliga","eisenbands truppenlager","jern hornhelm","loch modan","ausgrabungsleiter sturmlanze","meldung in eisenschmiede","thelsamar"},ang={["faction:Alliance"]="Als Mitglied der Allianz erlebt Ihr, wie die Allianz abgelegene Forschungslager in Bergtälern mit der militärischen und gelehrten Führung Eisenschmiedes verbindet.",["race:Dwarf"]="Als Zwerg kennt Ihr die Abläufe der Forscherliga und das legendäre Temperament des Clans Stormpike aus dem Leben in den Hallen Eurer Hauptstadt."},sec={{t="Ein Bote für die Liga",b="Die Forscherliga finanziert und beaufsichtigt archäologische Expeditionen in ganz Khaz Modan und versorgt sie mit Vorräten. Eisenbands Ausgrabung im südlichen Loch Modan fehlt es an Sprengstoff. Ihre Aufseher können nicht einfach in der Nähe Nachschub anfordern.\n\nIm Gasthof von Thelsamar vertraut Jern Hornhelm Euch Eisenbands schriftlichen Bericht an. Ihr bringt ihn über die Bergpässe zu Ausgrabungsleiter Sturmlanze im Hauptquartier der Liga in Eisenschmiede."},{t="Sturmlanzes Temperament",b="Ausgrabungsleiter Sturmlanze bringt die unbändige Entschlossenheit seines Clans in seine Arbeit für die Liga ein. In der großen Library und der Hall of Explorers von Eisenschmiede erwartet er rasche Ergebnisse von den Ausgrabungen.\n\nEisenbands Bericht empört ihn. Darin steht kein Wort über eine gewaltige Ladung Sprengpulver, die vor Wochen verschickt wurde. Diese fehlende Angabe deutet auf eine gefährliche Unterbrechung der Nachschublinien in Loch Modan hin."}},faq={{q="Warum muss dieser Bericht den weiten Weg nach Eisenschmiede nehmen?",a="Die Forscherliga kontrolliert die Verteilung wertvoller Vorräte wie Sprengpulver. Ausgrabungsstätten brauchen die Genehmigung leitender Ausgrabungsleiter in der Hall of Explorers, bevor sie Sprengstoff bestellen können.",al={"warum nach eisenschmiede","warum bericht zu sturmlanze bringen","grund für bericht nach eisenschmiede"}},{q="Wer ist Ausgrabungsleiter Sturmlanze?",a="Ausgrabungsleiter Sturmlanze ist ein hochrangiger Vertreter der Forscherliga mit Sitz in Eisenschmiede. Er gehört dem stolzen Clan Stormpike an und ist für sein aufbrausendes Temperament und seine Ungeduld bei stockenden Ausgrabungen und fehlenden Vorräten bekannt.",al={"wer ist sturmlanze","geschichte von ausgrabungsleiter sturmlanze"}},{q="Wo ist Eisenbands ursprüngliches Sprengpulver geblieben?",a="Vor Wochen wurde eine Ladung Sprengpulver verschickt, doch Eisenbands Bericht erwähnt nicht, dass er sie erhalten hat. Vielleicht haben Troggs oder Banditen den Wagen auf den Straßen von Loch Modan überfallen.",al={"was geschah mit dem sprengpulver","verschwundenes sprengpulver","wo ist das pulver"}},{q="Wo findet Ihr Ausgrabungsleiter Sturmlanze in Eisenschmiede?",a="Ihr findet Ausgrabungsleiter Sturmlanze in der Versammlung der Forscher in Eisenschmiede, auch Library oder Hall of Explorers genannt, im nordöstlichen Flügel der Stadt.",al={"sturmlanzes standort","wo ist sturmlanze","standort der versammlung der forscher"}},{q="Wer gibt Euch den Bericht in Thelsamar?",a="Jern Hornhelm gibt Euch den Bericht im Gasthof Zum Starkbier-Lager in Thelsamar. Er koordiniert Berichte und Nachrichten zwischen Eisenbands abgelegenem Lager und der Stadtführung.",al={"wer startet meldung in eisenschmiede","jern hornhelms rolle"}},{q="Was geschieht, nachdem Sturmlanze den Bericht gelesen hat?",a="Nach dem Lesen des Berichts ist Sturmlanze wütend über die verschwundene Munition und die stockenden Fortschritte. Er befiehlt Euch, eine neue Lieferung Sprengpulver zu organisieren und sie direkt zu Ausgrabungsleiter Eisenband zurückzubringen.",al={"what comes next","nächste quest nach meldung in eisenschmiede"}}},fx={["601d3943"]={q="Warum möchte Jern Hornhelm, dass dieser Bericht nach Eisenschmiede geschickt wird?",a="Die Ausgrabung von Ausgrabungsleiter Eisenband im Loch Modan ist zum Stillstand gekommen, da der Mannschaft das Sprengpulver ausgegangen ist. Jern Hornhelm kann in eigener Vollmacht keine weiteren Vorräte anfordern; er benötigt die formelle Genehmigung der Forscherliga aus Eisenschmiede. Die Zustellung des Fortschrittsberichts an Ausgrabungsleiter Sturmlanze ist der einzige verwaltungstechnische Weg, um eine neue Ladung Pulver zu sichern und die Grabungen fortzusetzen.",al={"warum den bericht senden","jern hornhelm motiv","warum will jern sprengpulver"}},["499fe615"]={q="Warum schickt Euch Jern Hornhelm, anstatt selbst zu gehen?",a="Jern Hornhelm hat alle Hände voll damit zu tun, die Logistik in Thelsamar zu verwalten und die örtlichen Ausgrabungsarbeiten zu unterstützen. Zudem ist Ausgrabungsleiter Sturmlanze dafür bekannt, ein kurzes, feuriges Temperament zu haben, wenn es um Verzögerungen und Rückschläge geht. Wenn er einen entbehrlichen Kurier losschickt, der dem Zorn von Sturmlanze trotzt, erspart sich Jern den direkten Zorn seiner Vorgesetzten und kann sich weiterhin auf die lokalen Abläufe konzentrieren.",al={"warum schickt er mich","warum geht er nicht selbst","warum braucht hornhelm mich"}}},fp="19,191,24.427.0,20.376.1,57.193.0,28.209.0,45.173.0,52.154.0,38.164.0,46.201.1"}
P.entries["quest:302"] = {n="Pulver für Eisenband",s="In Eisenschmiede schickt die Forscherliga Sprengpulver nach Süden zu Ausgrabungsleiter Eisenbands Grabung in Loch Modan. Ausgrabungsleiter Sturmlanze genehmigt die Anforderung, und die Lieferung gelangt über Thelsamar weiter nach Ironband's Excavation.",h="In Eisenschmiede schickt die Forscherliga Sprengpulver nach Süden zu Ausgrabungsleiter Eisenbands Grabung in...",kw={"forscherliga","huldar","eisenschmiede","jern hornhelm","loch modan","pulver für eisenband","ausgrabungsleiter sturmlanze","thelsamar"},ang={["faction:Alliance"]="Als Reisender der Allianz stärkt Ihr die Verbindungen zwischen Eisenschmiede und den östlichen Grenzgebieten, indem Ihr helft, die Straßen von Loch Modan zu sichern.",["profession:Mining"]="Als Bergmann wisst Ihr, dass Sprengpulver Bergleuten und Ausgräbern hilft, tief liegendes Grundgestein zu durchbrechen.",["race:Dwarf"]="Als Zwerg unterstützt Ihr die heilige Arbeit, die rätselhaften Ursprünge Eures Volkes aufzudecken, indem Ihr helft, Pulver für eine Grabung zu sichern."},sec={{t="Bürokratie und Sprengpulver",b="Die Forscherliga schickt Sprengpulver aus Eisenschmiede zu Ausgrabungsleiter Eisenbands Expedition im südlichen Loch Modan. Wenn der Grabung das Pulver ausgeht, erreicht die Nachricht die Führung der Liga. Ausgrabungsleiter Sturmlanze genehmigt die Anforderung und schickt den Boten zu Jern Hornhelm in Thelsamar, dem wichtigsten Versorgungsknotenpunkt des Tals."},{t="Eine verpasste Abfahrt",b="Frühere Wagen auf dem Weg durch Loch Modan sind verschwunden oder wurden von einheimischen Troggs bedrängt. Sturmlanze befiehlt Euch, den Pulverwagen persönlich zu bewachen. Doch als Ihr den Gasthof Zum Starkbier-Lager in Thelsamar erreicht, hat Jern Hornhelm ihn bereits mit Huldar und zwei zwergischen Trägern nach Süden geschickt. Ihr eilt die Straße entlang, um sie einzuholen."}},faq={{q="Warum wird Sprengpulver zu Eisenband geschickt?",a="Ausgrabungsleiter Eisenband leitet eine archäologische Grabung der Zwerge im südlichen Loch Modan. Sein Team hat sein Sprengpulver beim Graben durch dichtes Gestein aufgebraucht, während die Troggs immer angriffslustiger werden.",al={"warum pulver nötig","eisenband sprengpulver","wofür ist das pulver"}},{q="Wer ist Ausgrabungsleiter Sturmlanze?",a="Ausgrabungsleiter Sturmlanze ist ein hochrangiger Offizier der zwergischen Forscherliga in der Hall of Explorers in Eisenschmiede. Er prüft Anforderungen aus dem Feld, genehmigt dringend benötigte Ausrüstung und verwaltet den Nachschub für große Grabungsstätten in ganz Khaz Modan.",al={"sturmlanzes rolle","wer gab die quest"}},{q="Wer ist Jern Hornhelm?",a="Jern Hornhelm ist ein Kontaktmann der Forscherliga in Thelsamar in Loch Modan. Er stellt Vorräte zusammen und organisiert Transporttrupps, die zu den gefährlicheren Grenzgebieten des Tals aufbrechen.",al={"jern hornhelm standort","wo ist jern hornhelm"}},{q="Warum wurde für diese Lieferung persönliche Begleitung angefordert?",a="Frühere Lieferungen für Eisenbands Grabung kamen nicht an. Troggs, die aus den Hügeln und Grabungsstätten strömen, machen die Hauptstraße von Loch Modan zunehmend gefährlich.",al={"warum pulver eskortieren","troggangriffe auf wagen"}},{q="Was geschieht, wenn Ihr in Thelsamar ankommt?",a="Jern Hornhelm hat den Wagen bereits mit Huldar und den Trägern Miran und Saean losgeschickt. Ihr folgt der Straße nach Süden, um sie einzuholen, bevor es Ärger gibt.",al={"wagen verpasst","wo ist die lieferung"}},{q="Wie fügt sich diese Quest in die Geschichte der Forscherliga ein?",a="Diese Lieferung führt die Anforderung der Grabungsstätte durch die zuständigen Stellen der Liga in Eisenschmiede und über Thelsamar zurück ins Feld. Die Expedition kann dann weitergraben.",al={"eisenband questreihe","ausgrabung questreihe"}}},fx={["8773e6dd"]={q="Warum schickt Ausgrabungsleiter Sturmlanze einen Abenteurer und keine offiziellen Wachen?",a="Ausgrabungsleiter Sturmlanze arbeitet von der Hall of Explorers in Eisenschmiede aus und konzentriert sich eher auf verwaltungstechnische Angelegenheiten und das Einholen von Genehmigungen, anstatt Truppen ins Feld zu schicken. Da frühere Lieferungen von Sprengpulver auf den Straßen von Loch Modan bereits Gefahren zum Opfer gefallen sind, vertraut er auf einen fähigen Reisenden, der ohnehin in diese Gegend unterwegs ist, um persönlich sicherzustellen, dass Jern Hornhelms Versorgungskonvoi den Ausgrabungsort sicher erreicht.",al={"warum schickt er mich","warum keine wachen zu eisenband","warum ein abenteurer"}}},fp="18,229,31.302.0,18.311.1,46.177.0,28.223.0,21.171.0,52.164.0,42.152.1,61.174.0"}
P.entries["quest:3022"] = {n="Vorsichtig behandeln",s="Curgle Cranklehop schickt eine Kiste mit Eiern zu einem Druiden in Rut'theran. Das Dorf liegt in Teldrassil.",h="Curgle Cranklehop schickt eine Kiste mit Eiern zu einem Druiden in Rut'theran.",kw={"curgle cranklehop","erelas ambersky","hippogrypheneier","rut'theran","tanaris","teldrassil"},sec={{t="Eine Kiste mit Eiern",b="Curgle Cranklehop vertraut Euch eine sorgfältig verpackte Kiste für Erelas Ambersky an. Darin liegen Hippogrypheneier, die für den Druiden bestimmt sind."},{t="Der Druide von Rut'theran",b="Erelas Ambersky kümmert sich in Rut'theran um Hippogrypheneier. Er hilft ihnen beim Schlüpfen und bildet die jungen Hippogryphen aus. Rut'theran ist ein kleines Dorf im Süden von Teldrassil."}},faq={{q="Was ist in der Kiste von Curgle Cranklehop?",a="Curgle Cranklehops sorgfältig verpackte Kiste enthält Hippogrypheneier.",al={"was ist in der kiste","inhalt der sorgfältig verpackten kiste","was trage ich"}},{q="Wohin muss die Kiste gebracht werden?",a="Bringt die Kiste zu Erelas Ambersky, einem Druiden in Rut'theran, einem kleinen Dorf in Teldrassil.",al={"wohin bringe ich die kiste","erelas ambersky standort","wo liegt rut'theran"}},{q="Wer ist Erelas Ambersky?",a="Erelas Ambersky ist ein Druide in Rut'theran. Er kümmert sich um Hippogrypheneier und bildet die jungen Hippogryphen aus, nachdem sie geschlüpft sind.",al={"wer ist erelas","ambersky geschichte","wer erhält die eier"}}},fp="16,97,15.130.0,23.172.0,48.65.0,32.89.0,23.129.0"}
P.entries["quest:303"] = {n="Der Dunkeleisenkrieg",s="In Dun Modr führt Motley Garmason eine verzweifelte Verteidigung am Nordrand des Sumpflands an. Der Dunkeleisenclan hält die Stadt, nachdem Saboteure den Thandol-Übergang zerstört haben. Die Bergsteiger der Eisenschmiede halten mühsam die Stellung und warten auf Verstärkung, die womöglich nie eintrifft.",h="In Dun Modr führt Motley Garmason eine verzweifelte Verteidigung am Nordrand des Sumpflands an.",kw={"bronzebeard","dunkeleisen","sprengmeister","dun modr","eisenschmiede","motley garmason","saboteure","thandol-übergang","sumpfland"},ang={["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass die Zerstörung des Thandol-Übergangs und der Fall von Dun Modr die Landverbindung zwischen Sturmwinds nördlichen Verbündeten und den südlichen Königreichen kappen.",["profession:Engineering"]="Als Ingenieur erkennt Ihr, dass die speziellen Sprengladungen der Dunkeleisensaboteure eine erschreckende Meisterschaft im Sprengen von Bauwerken offenbaren.",["race:Dwarf"]="Als Zwerg des Bronzebeard-Clans wisst Ihr, dass der Verlust von Dun Modr eine bittere Demütigung und eine unmittelbare Bedrohung für Khaz Modans Souveränität ist. Rache an den uralten Feinden ist geboten."},sec={{t="Eine Front am Nordtor",b="Dun Modr bewachte das südliche Ende des gewaltigen Thandol-Übergangs, der Brücke zwischen Khaz Modan und Lordaeron. Saboteure und Sprengmeister des Dunkeleisenclans zerstörten ihren Brückenbogen und unterbrachen den Reiseverkehr der Allianz, bevor sie die Festung überrannten. Motley Garmason und eine Handvoll überlebender Verteidiger zogen sich in ein Beobachtungslager unmittelbar vor der Stadt zurück. Ohne einen Gegenangriff könnte das nördliche Tor unter der Herrschaft des Dunkeleisenclans bleiben."},{t="Zeit für die Reserven",b="Zwergenregimenter kämpfen auf fernen Schlachtfeldern der Allianz, sodass Motleys kleine Einheit weitgehend auf sich allein gestellt ist. Seine Kundschafter versuchen, Eisenschmiede um Entsatz zu bitten, doch die Verbindung stockt und von den versprochenen Reserven fehlt jede Spur. Um Zeit zu gewinnen und die feindliche Verteidigung zu stören, befiehlt Motley gezielte Angriffe in den Ruinen von Dun Modr. Er will die Reihen der Ingenieure, Tunnelgräber und Frontsoldaten des Dunkeleisenclans lichten, bevor sie weiter nach Süden ins Sumpfland vorstoßen."}},faq={{q="Wer ist Motley Garmason?",a="Motley Garmason ist ein Offizier der Bergsteiger der Eisenschmiede und befehligt die überlebende Garnison von Dun Modr. Von einem Lager unmittelbar vor der besetzten Stadt aus leitet er Erkundungseinsätze und Guerillaangriffe gegen die Truppen des Dunkeleisenclans.",al={"motley garmason","wer ist motley","kommandant von dun modr"}},{q="Warum ist Dun Modr für Eisenschmiede so wichtig?",a="Dun Modr bewacht den südlichen Brückenkopf des Thandol-Übergangs. Der Übergang ist die einzige Landstraße, die Khaz Modan mit dem Arathihochland und dem nördlichen Lordaeron verbindet. Wer Dun Modr beherrscht, kontrolliert daher den Landverkehr und den Nachschub zwischen diesen Regionen.",al={"warum dun modr wichtig ist","bedeutung von dun modr","geschichte von dun modr"}},{q="Warum kämpfen Dunkeleisenzwerge im Sumpfland?",a="Der Dunkeleisenclan versucht schon lange, seine Vettern vom Bronzebeard-Clan zu untergraben und die Allianz zu schwächen. Indem sie ins Sumpfland einfallen und den Thandol-Übergang zerstören, kappen sie Eisenschmiedes Nachschublinien nach Norden und eröffnen eine feindliche zweite Front hinter den Grenzen der Allianz.",al={"warum sind die dunkeleisenzwerge hier","dunkeleisen sumpfland","grund für den dunkeleisenkrieg"}},{q="Was ist mit dem Thandol-Übergang geschehen?",a="Tunnelgräber und Sprengmeister des Dunkeleisenclans brachten konzentrierte Sprengladungen an den tragenden Bögen des Thandol-Übergangs an und beschädigten die Brücke schwer. Sie wollten Eisenschmiede von Verstärkung aus Lordaeron abschneiden, bevor sie Dun Modr überrannten.",al={"thandol-übergang zerstört","wer hat die brücke gesprengt","explosion am thandol-übergang"}},{q="Wo sind Eisenschmiedes Reservetruppen?",a="Eisenschmiedes Streitkräfte sind durch Feldzüge in der Ferne und die Verteidigung der Heimat stark beansprucht. Garmasons Kundschafter Roggo hat Schwierigkeiten, das Oberkommando zuverlässig zu erreichen, sodass der Außenposten von Dun Modr mit allen verfügbaren örtlichen Verbündeten die Stellung halten muss.",al={"reserven von eisenschmiede","wo ist die verstärkung","roggo reserve"}},{q="Was geschieht, nachdem die Dunkeleisenzwerge in Dun Modr zurückgedrängt wurden?",a="Die Fußsoldaten und Pioniere auszuschalten verschafft entscheidende Zeit. Roggos Erkenntnisse enthüllen, dass Kam Tiefenzorn, der im Verlies von Sturmwind gefangen gehalten wird, den Angriff auf den Thandol-Übergang mitgeplant hat. Motley bittet Euch, ihm Tiefenzorns Kopf zu bringen.",al={"nächste quest nach dem dunkeleisenkrieg","the fury runs deep quest","was folgt auf den dunkeleisenkrieg"}}},fx={["07a4003e"]={q="Warum möchte Motley Garmason, dass dies erledigt wird?",a="Motley ist verzweifelt bemüht, Dun Modr zurückzuerobern und den Vormarsch der Dunkeleisenzwerge ins Sumpfland zu stoppen, bevor das Gebiet von Eisenschmiede vollständig in Gefahr gerät. Die Dunkeleisenzwerge haben bereits The Thandol Span gesprengt und die Stadt überrannt, wodurch lebenswichtige Verbindungen in den Norden gekappt wurden. Motley hofft, durch unmittelbaren offensiven Druck auf deren Linien die Front lange genug halten zu können, bis Verstärkung aus Eisenschmiede eintrifft, um sie endgültig zurückzuschlagen.",al={"motley garmason motiv","warum die dunkeleisenzwerge bekämpfen","warum dun modr säubern"}},b2f42bee={q="Warum benötigt Motley Garmason Eure Hilfe anstatt der eigenen Truppen?",a="Das stehende Heer von Eisenschmiede ist bis an die Belastungsgrenze beansprucht, da es weit weg von der Heimat in fremden Ländern im Namen der Allianz kämpft. Nachdem The Thandol Span und Dun Modr gefallen waren, blieb er nur mit einer Handvoll Verteidiger zurück und verfügt über keine frischen Soldaten. Seine Späher schaffen es nicht, Reserven zu mobilisieren, weshalb ihm keine andere Wahl bleibt, als sich auf fähige Reisende wie Euch zu verlassen, um den Kampf zu führen.",al={"warum braucht motley mich","warum kämpfen die wachen nicht","wo sind die truppen von eisenschmiede"}}},fp="17,264,28.416.0,28.480.0,23.209.0,42.249.0,51.260.0,34.234.0,39.232.0,59.227.1"}
P.entries["quest:304"] = {n="Eine grausige Aufgabe",s="Im Sumpfland sinnt Langzopf der Grimmige auf Rache für Dun Modr. Der Angriff der Dunkeleisenzwerge zerstörte den Thandol-Übergang und tötete seinen Bruder und viele Soldaten. Nun will er Balgaras the Foul tot sehen, mit dem Ohr des Hexenmeisters als Beweis.",h="Im Sumpfland sinnt Langzopf der Grimmige auf Rache für Dun Modr.",kw={"eine grausige aufgabe","balgaras the foul","dunkeleisen","dun modr","langzopf der grimmige","roggo","thandol-übergang","sumpfland"},ang={["class:Warlock"]="Als Hexenmeister wisst Ihr, zu welch gefährlichen Zwecken die Dunkeleisenzwerge ihre Kunst einsetzen. Balgaras the Foul nutzt Teufelsmagie, um das Gemetzel unter den Verteidigern von Dun Modr zu lenken.",["faction:Alliance"]="Als Reisender der Allianz wisst Ihr, dass der Thandol-Übergang der wichtigste Landweg zwischen Khaz Modan und Lordaeron ist. Die Dunkeleisensaboteure auszuschalten, ist für die gesamte Allianz von Bedeutung.",["race:Dwarf"]="Als Zwerg aus Eisenschmiede ist die Gewalt des Dunkeleisenclans in Dun Modr für Euch eine persönliche Kränkung und eine frische Wunde im langen Bürgerzwist der Clans."},sec={{t="Die Ruinen von Dun Modr",b="Kämpfe zwischen Gebirgsjägern von Eisenschmiede und Infiltratoren des Dunkeleisenclans haben das nördliche Sumpfland gezeichnet. Dun Modr fiel während der Belagerung, und die westliche Brücke des Thandol-Übergangs wurde zerstört. Langzopf der Grimmige verlor bei dem Angriff seinen Bruder und viele treue Soldaten. Er will den Dunkeleisenclan für diese Toten bezahlen lassen."},{t="Ein feiger Befehlshaber",b="Späher wie Roggo haben herausgefunden, dass Balgaras the Foul die Dunkeleisenstreitmacht befehligt, die Dun Modr besetzt hält. Der Hexenmeister versteckt sich, während seine Soldaten seine finsteren Pläne ausführen. Langzopf hofft, dass Balgaras' Tod ihren Kampfeswillen bricht. Dann könnten die Überlebenden aus Eisenschmiede den Durchgang nach Norden sichern."}},faq={{q="Wer ist Balgaras the Foul?",a="Balgaras the Foul ist ein Dunkeleisenhexenmeister, der die Besatzungstruppen in Dun Modr im nördlichen Sumpfland befehligt. Langzopf der Grimmige nennt ihn einen Feigling, der den direkten Kampf meidet und Dunkeleisentruppen entsendet, um die Region zu halten.",al={"balgaras","wer ist balgaras","dunkeleisenanführer dun modr"}},{q="Wer ist Langzopf der Grimmige?",a="Langzopf der Grimmige ist ein zwergischer Befehlshaber, der vor den Ruinen von Dun Modr lagert. Dunkeleisentruppen nahmen die Siedlung ein und zerstörten den westlichen Übergang des Thandol-Übergangs, wobei sein Bruder und viele seiner Soldaten starben.",al={"langzopf","langzopf der grimmige","questgeber dun modr"}},{q="Warum will Langzopf Balgaras' Ohr?",a="Langzopf will Balgaras' Ohr als Beweis dafür, dass der Hexenmeister tot ist. Balgaras ist schwer zu fassen und versteckt sich oft vor offenen Kämpfen.",al={"warum das ohr","balgaras' ohr"}},{q="Was geschah mit dem Thandol-Übergang?",a="Dunkeleisenzwerge zerstörten bei ihrem Überraschungsangriff auf Dun Modr die westliche Brücke des Thandol-Übergangs. Die Verbindung zwischen dem Sumpfland und dem Arathihochland ist unterbrochen.",al={"thandol-übergang brücke zerstört","warum ist der thandol-übergang zerstört"}},{q="Wo versteckt sich Balgaras?",a="Balgaras versteckt sich zwischen den eroberten Befestigungen und Ruinen rund um Dun Modr, hinter seinen Soldaten statt draußen im Sumpfland.",al={"wo ist balgaras","balgaras finden"}},{q="Was geschieht nach Balgaras' Tod?",a="Langzopf glaubt, dass die übrigen Dunkeleisentruppen nach Balgaras' Tod leichter zu besiegen sind, bevor ein weiterer Befehlshaber eintrifft, um sie zu verstärken.",al={"nach eine grausige aufgabe","wie weiter in dun modr"}}},fx={["7a4e9943"]={q="Warum möchte Langzopf der Grimmige, dass Balgaras getötet wird?",a="Langzopf verlor während der Schlacht um Dun Modr viele Soldaten, darunter seinen eigenen Bruder, der ums Leben kam, als die Dunkeleisenzwerge die westliche Brücke von The Thandol Span zerstörten. Balgaras befehligt die feindlichen Dunkeleisentruppen im Sumpfland und dirigiert die Angriffe, während er sich sicher hinter seinen Schergen versteckt. Durch die Hinrichtung des Hexenmeisters sucht Langzopf Vergeltung für seine gefallenen Verwandten und Soldaten und hofft, die Befehlsstruktur der Dunkeleisenbande zu brechen und den Überlebenden Seelenfrieden zu verschaffen.",al={"warum balgaras töten","langzopf motiv","warum will langzopf das erledigt haben"}}},fp="11,227,21.320.0,20.284.0,25.216.0,26.215.0,39.119.0,34.174.0,25.130.0,37.145.0"}
P.entries["quest:305"] = {n="Auf der Suche nach dem Ausgrabungstrupp",s="Tarrel Felsweber wartet im Sumpfland auf Nachricht von Merrin an der Whelgar Excavation Site. Zwei Wochen sind ohne einen Brief vergangen, und er fürchtet um die Ausgrabung im Osten.",h="Tarrel Felsweber wartet im Sumpfland auf Nachricht von Merrin an der Whelgar Excavation Site.",kw={"explorers' league","auf der suche nach dem ausgrabungstrupp","longbraid","merrin felsweber","tarrel felsweber","sumpfland","whelgar excavation"},ang={["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass zwergische Außenposten und Forschung in den Sümpfen helfen, das Sumpfland vor den Gefahren der Wildnis zu schützen.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Explorers' League stolz darauf ist, uralte Geschichte aufzudecken. Eure Verwandten bei der Whelgar Excavation sind in Bedrängnis, und ihre Not verlangt nach Eurer Aufmerksamkeit."},sec={{t="Die Angst eines Ehemanns",b="Seit zwei Wochen hat Tarrel Felsweber nichts von seiner Frau Merrin gehört. Von der Whelgar Excavation Site schickte sie einst wöchentlich Briefe über die Arbeit. Nun fürchtet Tarrel, dass das Lager ein Unglück ereilt hat. Da die zwergischen Behörden überlastet sind, wendet er sich an vorbeikommende Kundschafter, um zu erfahren, ob die Ausgräber noch leben."},{t="Die Whelgar Dig",b="Im Osten des Sumpflands suchen Zwerge an der Whelgar Excavation Site nach uralten Titanenrelikten und Spuren der Geschichte. Die Trupps arbeiten in der Wildnis, wo wilde Tiere und Bedrohungen aus der Tiefe sie aufspüren können. Die Stätte liegt weit abseits der Hauptstraßen. Was auch immer die Briefe aufgehalten hat, hat die Ausgräber nur schwer erreichbar gemacht."}},faq={{q="Wer ist Tarrel Felsweber?",a="Tarrel Felsweber ist ein Zwerg im Sumpfland, der sich sorgt, weil seine Frau Merrin keine Briefe mehr von der Ausgrabungsstätte im Osten schreibt. Er hält vorbeikommende Abenteurer für Kundschafter, die geschickt wurden, um herauszufinden, was geschehen ist.",al={"tarrel felsweber","questgeber","wer vergibt auf der suche nach dem ausgrabungstrupp"}},{q="Wer ist Merrin Felsweber?",a="Merrin Felsweber ist eine zwergische Archäologin, die mit dem Team der Whelgar Excavation östlich vom Hafen von Menethil im Sumpfland arbeitet. Sie schrieb ihrem Mann regelmäßig, bis etwas die Briefe aufhielt.",al={"merrin felsweber","tarrels frau","wer ist merrin"}},{q="Wo liegt die Whelgar Excavation Site?",a="Die Whelgar Excavation Site liegt östlich vom Hafen von Menethil und südwestlich von Dun Modr im Sumpfland. Felsige Höhenzüge umgeben sie, weit abseits der Hauptstraße.",al={"lage der ausgrabungsstätte","wo ist merrin zu finden","wo liegt whelgar excavation"}},{q="Warum schickte Merrin keine Briefe mehr?",a="Eine Bedrohung an der Ausgrabungsstätte schnitt die Forscher von den üblichen Kurierwegen und dem Lageralltag ab, wodurch Merrins Briefe ausblieben.",al={"warum blieben die briefe aus","was geschah mit dem ausgrabungstrupp","warum keine post"}},{q="Wer ist der von Tarrel erwähnte „Longbraid“?",a="Longbraid ist ein zwergischer Amtsträger, der versprach, bei einem Kontaktabbruch Kundschafter zu schicken, um nach dem Team der Whelgar Excavation zu sehen. Tarrel nimmt an, dass jeder fähige Abenteurer, der helfen kommt, von Longbraid geschickt wurde.",al={"wer ist longbraid","longbraids kundschafter"}},{q="Kann man sich der Ausgrabungsstätte gefahrlos nähern?",a="Nein. Die Whelgar Excavation Site liegt in der gefährlichen Wildnis des Sumpflands, und was die wöchentlichen Briefe des Teams aufhielt, bedroht jeden, der die Ausgrabung erreicht.",al={"ist die ausgrabung sicher","whelgar gefährlich"}}},fx={d2e8931d={q="Warum benötigt Tarrel Felsweber einen Abenteurer, um das Ausgrabungsteam zu finden?",a="Tarrel ist im Hafen von Menethil voller Sorge, aber er ist kein bewaffneter Forscher oder Soldat, der allein durch das gefährliche Marschland reisen könnte. Örtliche Offizielle wie Langzopf versprachen, einen erfahrenen Späher zu entsenden, um die Stille vom Ausgrabungsort zu untersuchen. Als Ihr ankommt, betrachtet Tarrel Euch als die fähige Hilfe, die ihm versprochen wurde, um der Wildnis zu trotzen und nach seiner Frau zu sehen.",al={"warum schickt er mich","warum keine wachen","warum kann tarrel nicht gehen"}}},fp="32,164,17.305.0,15.286.0,25.200.0,25.196.0,37.149.0,36.112.0,43.198.0,40.155.0"}
P.entries["quest:306"] = {n="Auf der Suche nach dem Ausgrabungstrupp",s="In Whelgars Ausgrabungsstätte schickt Merrin Felsweber Nachricht, nachdem Buntraptoren die Ausgrabung überrannt haben. Ihr Brief berichtet Tarrel Felsweber, dass sie überlebt hat, die meisten Expeditionsteilnehmer jedoch nicht.",h="In Whelgars Ausgrabungsstätte schickt Merrin Felsweber Nachricht, nachdem Buntraptoren die Ausgrabung...",kw={"ausgrabung","hafen von menethil","merrin felsweber","buntraptoren","ormer","tarrel felsweber","sumpfland","whelgar"},ang={["faction:Alliance"]="Als Reisender der Allianz wisst Ihr, dass wilde Tiere im gesamten Sumpfland die Siedlungen und die Arbeit bedrohen.",["race:Dwarf"]="Als Zwerg kennt Ihr die Gefahren, denen König Magnis Forscher fern von Eisenschmiede gegenüberstehen. Die Katastrophe trifft die Hoffnungen der Zwerge, die Vergangenheit zu erforschen."},sec={{t="Eine Nachricht aus den Ruinen",b="Merrin Felsweber hat auf dem Bergrücken über Whelgars Ausgrabungsstätte Neuigkeiten für Euch. Ihr Team legte seltene Artefakte und gewaltige prähistorische Fossilien frei, als Rudel von Buntraptoren über die Ausgrabung herfielen. Die meisten Teammitglieder starben bei dem Angriff. Merrin und die anderen Überlebenden sind weiterhin vom Hafen von Menethil abgeschnitten."},{t="Eine bittere Erleichterung",b="Im Hafen von Menethil erfährt Tarrel Felsweber, dass seine Frau mit mindestens zwei Gefährten überlebt hat. Ormers Mut half ihnen bei der Flucht, und Tarrels Angst lässt nach. Doch der Tod so vieler Kollegen lastet noch immer auf der Stadt und ihrem Pioniergeist."}},faq={{q="Was ist mit dem Ausgrabungsteam im Sumpfland geschehen?",a="Rudel von Buntraptoren überrannten die Zwergenexpedition, als sie seltene Artefakte und gewaltige uralte Knochen freilegte. Die meisten Ausgräber wurden getötet, während eine Handvoll auf den Anhöhen über der Ausgrabungsstätte überlebte.",al={"was geschah an der ausgrabungsstätte","ausgrabungskatastrophe im sumpfland","warum scheiterte die ausgrabung"}},{q="Wer hat Merrin Felsweber gerettet?",a="Merrin Felsweber schreibt es Ormer zu, dass er die Raptoren abwehrte und sie und den Schürfer auf dem Bergrücken in Sicherheit brachte.",al={"wer rettete merrin","ormer felsweber","wer ist ormer"}},{q="Wer ist Tarrel Felsweber?",a="Tarrel Felsweber ist Merrins Ehemann und wartet im Hafen von Menethil. Besorgt über das Schweigen von der Ausgrabungsstätte suchte er Reisende, um zu erfahren, was mit ihr geschehen war.",al={"wer ist tarrel","tarrel felsweber aufenthaltsort"}},{q="Wo liegt die Ausgrabungsstätte?",a="Die Ausgrabungsstätte liegt im Landesinneren des Sumpflands, östlich vom Hafen von Menethil und südwestlich von Dun Modr.",al={"wo ist die ausgrabung","whelgars ausgrabung lage"}},{q="Wonach grub die Expedition?",a="Das Team grub unter der Leitung zwergischer Schürfer nach seltenen unterirdischen Artefakten und großen prähistorischen Fossilien, die in den Sümpfen begraben lagen.",al={"wonach gruben sie","ausgrabungsartefakte"}},{q="Gibt es neben Merrin weitere Überlebende?",a="Ja. Merrin sagt, dass Ormer und der leitende Schürfer mit ihr entkamen, womit es drei bekannte Überlebende gibt.",al={"wer hat noch überlebt","überlebende der ausgrabung"}}},fx={["2f0bde8f"]={q="Warum möchte Merrin Felsweber, dass Ihr ihren Brief überbringt?",a="Merrin möchte ihren Ehemann Tarrel beruhigen, dass sie den brutalen Angriff auf den Ausgrabungsort überlebt hat. Die Raptoren haben ihr Lager überrannt und viele der Archäologen getötet, wodurch Merrin, Ausgrabungsleiter Whelgar und Ormer in einem provisorischen Unterschlupf gefangen sind. Da sie selbst nicht durch die Bestien durchbrechen können, vertraut sie Euch ihren Brief an, damit Tarrel erfährt, dass sie am Leben sind, und das schreckliche Schicksal der Expedition versteht.",al={"warum merrins brief überbringen","merrin felsweber motiv","warum die notiz an tarrel liefern"}},f4e86a28={q="Warum kann Merrin Felsweber die Notiz nicht selbst überbringen?",a="Merrin und ihre Mitüberlebenden sind abgeschnitten und werden von aggressiven gesprenkelten Raptoren bedrängt. Wenn sie ihren Unterschlupf verlassen würden, wären sie den wilden Bestien ausgesetzt, die bereits den Rest des Ausgrabungsteams zerfleischt haben. Als ein körperlich fähiger Reisender, der in der Lage ist, sich durch die Sümpfe und Raptorrudel zu schlagen, könnt Ihr die Nachricht sicher zurück zum Hafen von Menethil tragen, wenn sie es nicht können.",al={"warum braucht merrin mich","warum kann merrin nicht vom ausgrabungsort weg","warum braucht merrin hilfe"}}},fp="32,185,24.311.0,15.239.0,53.200.0,28.122.0,25.163.0,30.99.0,36.141.0,40.95.0"}
P.entries["quest:3062"] = {n="Dunkles Herz",s="In Camp Mojache sucht Talo Thornhoof Edana Hatetalons Herz, um dem Hass ein Ende zu setzen, den sie verbreitet.",h="In Camp Mojache sucht Talo Thornhoof Edana Hatetalons Herz, um dem Hass ein Ende zu setzen, den sie...",kw={"camp mojache","dunkles herz","edana hatetalon","feralas","harpyie","hatetalon-steine","northspring","talo thornhoof"},sec={{t="Die Harpyienkönigin",b="Edana Hatetalon herrscht über die Northspring-Brut in den Ruinen im Westen. Talo nennt sie das reine Böse und sagt, sie empfinde nichts als Hass auf alle. Er hat gehört, ihr Herz bestehe aus Kristall. Er bittet Euch, Euch ihr zu stellen und ihr dunkles Herz zurückzubringen, damit ihrem Hass Einhalt geboten werden kann."},{t="Ein Ruf",b="Talo hat gehört, dass Harpyien ein Horn bei sich tragen. Blast es nahe den Hatetalon-Steinen im nördlichen Teil der Ruinen, und es soll Edana hervorlocken. Talo weidet sich an dem Gedanken, dass der Tod statt ihrer Artgenossen ihrem Ruf folgen wird."},{t="Bei Eurer Rückkehr",b="Talo Thornhoof ist sicher, dass Edana Hatetalon für immer fort ist. Er wird ihr Herz zur Erinnerung an Eure Tat aufbewahren."}},faq={{q="Wer ist Edana Hatetalon?",a="Edana Hatetalon herrscht über die Harpyien von Northspring in den westlichen Ruinen. Talo nennt sie das reine Böse und sagt, sie empfinde nur Hass. Er hat gehört, ihr Herz bestehe aus Kristall.",al={"edana hatetalon","harpyienkönigin feralas","wer ist die harpyienkönigin"}},{q="Wie lässt sich Edana Hatetalon herbeirufen?",a="Talo hat gehört, dass Harpyien ein Horn bei sich tragen. Blast es nahe den Hatetalon-Steinen im nördlichen Teil der Ruinen, und es soll die Königin herbeirufen.",al={"wie edana herbeirufen","horn blasen feralas","hatetalon-steine"}},{q="Wer erteilt den Auftrag zur Jagd auf Edana Hatetalon?",a="Talo Thornhoof in Camp Mojache erteilt den Auftrag zur Jagd auf Edana Hatetalon.",al={"wer vergibt dunkles herz","talo thornhoof","wo dunkles herz erhalten"}},{q="Warum will Talo Thornhoof Edanas Herz?",a="Talo will dem Hass Einhalt gebieten, den Edana über das Land verbreitet. Er bittet Euch, ihr dunkles Herz zurückzubringen.",al={"warum dunkles herz","talo thornhoofs beweggrund"}}},fp="10,94,15.270.0,9.226.0,14.109.1,23.159.0,36.145.0,39.66.0,43.100.0"}
P.entries["quest:3063"] = {n="Rache an den Nordschwingen",s="Talo Thornhoof sinnt auf Rache an den Northspring-Harpyien im Westen. Einst war Talo ein Jäger, der kein Wesen fürchtete, doch seit ihrem Hinterhalt im Wald hasst Talo sie.",h="Talo Thornhoof sinnt auf Rache an den Northspring-Harpyien im Westen.",kw={"feralas","harpyien","northspring","rache","roguefeather","slayer","talo thornhoof","windcaller"},sec={{t="Der Groll eines alten Jägers",b="Talo Thornhoof jagte einst ohne Furcht in der Wildnis. Nach einem harten Kampf blieb Talo im Wald, um eine Waffe zu schärfen. Dann rückten Harpyien näher, und Talo konnte sich gerade noch in Sicherheit bringen. Ihre Schreie hallen noch immer in Talos Erinnerung wider. Talos Leben war nie wieder wie zuvor, und der Hass blieb. Jetzt will Talo Rache."},{t="Die Northspring-Harpyien",b="Die Northspring-Harpyien leben im Westen. Talo bittet Euch, vier Northspring Harpies, vier Northspring Roguefeathers, vier Northspring Windcallers und vier Northspring Slayers zu töten. Ihre Schwingen sind schwarz wie die Nacht, warnt Talo. Sie können in der Dunkelheit verschwinden."},{t="Nach der Jagd",b="Talo Thornhoof, ein alter Tauren, dankt Euch für die Jagd. Eure Arbeit hat einem aufgewühlten Geist Frieden gebracht."}},faq={{q="Wer ist Talo Thornhoof?",a="Talo Thornhoof jagte einst ohne Furcht in der Wildnis. Harpyien lauerten Talo im Wald auf, und danach war Talo nie wieder wie zuvor.",al={"talo thornhoof hintergrundgeschichte","wer vergibt rache an den nordschwingen","talo feralas"}},{q="Wo leben die Northspring-Harpyien?",a="Die Northspring-Harpyien leben westlich von Talo Thornhoof.",al={"northspring-harpyien fundort","wo sind northspring-harpyien","harpyien fundort feralas"}},{q="Warum will Talo Rache an den Harpyien?",a="Nach einem harten Kampf blieb Talo Thornhoof im Wald, um eine Waffe zu schärfen. Harpyien umzingelten Talo, der nur knapp entkam. Talo war nie wieder wie zuvor und trägt seither Hass in sich.",al={"warum northspring-harpyien töten","talo thornhoof vorgeschichte","warum talo harpyien hasst"}},{q="Welche Harpyien will Talo tot sehen?",a="Talo will jeweils vier der Northspring Harpies, Northspring Roguefeathers, Northspring Windcallers und Northspring Slayers tot sehen.",al={"rache an den nordschwingen ziele","welche harpyien töten","northspring-harpyien arten"}},{q="Wie sehen die Northspring-Harpyien aus?",a="Talo sagt, die Northspring-Harpyien haben Schwingen so schwarz wie die Nacht und können in der Dunkelheit verschwinden.",al={"harpyien aussehen","northspring-harpyien schwingen"}}},fp="28,168,22.297.0,23.259.0,14.103.1,22.125.0,42.59.0,47.177.0,36.131.0,42.93.0"}
P.entries["quest:3065"] = {n="Einfache Schrifttafel",s="Im Tal der Prüfungen schickt Euch ein markiertes Pergament zu Frang, nachdem Ihr Euch gegen einheimische Bestien bewiesen habt. Der Kriegerlehrer wartet vor dem Den.",h="Im Tal der Prüfungen schickt Euch ein markiertes Pergament zu Frang, nachdem Ihr Euch gegen einheimische...",kw={"durotar","frang","gornek","einfache schrifttafel","the den","das tal der prüfungen","krieger"},ang={["class:Warrior"]="Als Krieger macht Ihr mit diesem Ruf Euren ersten Schritt auf Durotars Kriegerpfad. Frang lehrt Euch grundlegende Haltungen und Schläge.",["faction:Horde"]="Als Mitglied der Horde reiht Ihr Euch in ihren stetigen Strom abgehärteter Frontkämpfer ein. Sie werden ausgesandt, um Durotars gefährdete Grenzen gegen Zentauren, Stacheleber und menschliche Eindringlinge zu sichern.",["race:Troll"]="Als Dunkelspeertroll, der im Tal ausgebildet wird, hört Ihr vielleicht Frangs schroffe Bemerkungen über Eure Vorliebe für Speere gegenüber orkischen Äxten. Er respektiert alles, was tötet."},sec={{t="Ein Ruf zu den Waffen",b="Nachdem Ihr Euch gegen die gescheckten Eber bewiesen habt, gibt Gornek Euch ein Pergament, das allein für Euch bestimmt ist. Durotar ist rau, deshalb gibt die Horde ihren Kämpfern rasch Anleitung. Das Pergament schickt Euch zu Frang, dem erfahrenen Kriegerlehrer vor dem Den."},{t="Im Schatten des Den",b="Frang sucht Schutz im Schatten vor dem Den und beobachtet, wie Rekruten aus dem roten Buschland kommen. Er mustert jeden Neuankömmling mit erfahrenem Blick und lehrt dann die Grundlagen im Umgang mit einer schweren Axt oder einem Speer. Er bereitet jeden Rekruten darauf vor, die verwundbaren Siedlungen der jungen Horde zu verteidigen."}},faq={{q="Was ist die Einfache Schrifttafel?",a="Die Einfache Schrifttafel führt junge Krieger im Tal der Prüfungen zu Frang, dem dortigen Kriegerlehrer.",al={"einfache schrifttafel","was ist diese schrifttafel","kriegernotiz"}},{q="Wer schickt die Schrifttafel?",a="Frang schickt die Nachricht. Der erfahrene Kriegerlehrer wartet vor dem Den auf angehende Kämpfer.",al={"wer hat die schrifttafel geschrieben","wer hat die einfache schrifttafel geschickt"}},{q="Wo kann ich Frang finden?",a="Frang wartet vor dem Den im Tal der Prüfungen, unter Felsvorsprüngen vor der Wüstensonne geschützt.",al={"frang standort","wo ist frang","kriegerlehrer finden"}},{q="Warum erwähnt Frang Speere und Äxte?",a="Frang weiß, dass die Rekruten der Horde auf unterschiedliche Weise kämpfen. Orcs bevorzugen schwere Hiebwaffen wie Großäxte, während Trolle und andere Kämpfer oft Speere und leichtere Stangenwaffen wählen. Beide leisten im Kampf gute Dienste.",al={"frang speerzitat","warum speere"}},{q="Erhalten andere Klassen diese Quest?",a="Nein. Krieger erhalten die Einfache Schrifttafel, während andere Klassen keine solche Nachricht erhalten und durch ein Pergament, eine Rune oder eine Schriftrolle zu ihren eigenen Lehrmeistern geschickt werden.",al={"einfache schrifttafel nur für krieger","klassenquests im tal der prüfungen"}},{q="Welchen Zweck erfüllt der Den?",a="Der Den ist ein geschützter Höhlenkomplex im Tal der Prüfungen. Dort sammeln sich Ausbilder, Vorräte und rastende Rekruten, fern von sengender Hitze und umherstreifenden Bestien.",al={"was ist der den","den durotar"}}},fp="13,152,17.249.0,26.270.0,26.103.0,21.97.0,23.106.0,39.207.0,32.154.0,31.166.0"}
P.entries["quest:307"] = {n="Schmutzige Pfoten",s="In der Silberbachmine sind die Vorräte für Schmutzige Pfoten in Gefahr. Die Miners' League lagerte dort ihre Ausrüstung, nachdem das Erz erschöpft war, doch nun bevölkern Kobolde die Tunnel. Gebirgsjäger Sturmlanze will die Werkzeuge bergen lassen, bevor seine Krieger angreifen.",h="In der Silberbachmine sind die Vorräte für Schmutzige Pfoten in Gefahr.",kw={"schmutzige pfoten","kobold","loch modan","bergarbeiterausrüstung","miners' league","gebirgsjäger sturmlanze","silberbachmine","thelsamar"},ang={["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass die Räumung von Vorratsdepots wichtige Infrastruktur zugänglich hält, während die zwergischen Verteidigungskräfte in ganz Khaz Modan überlastet sind.",["profession:Mining"]="Als Bergarbeiter kennt Ihr den Wert hochwertiger zwergischer Ausrüstung und wisst, was verloren geht, wenn nützliche Werkzeuge in den Pfoten von Höhlenungeziefer verrosten.",["race:Dwarf"]="Als Zwerg empfindet Ihr es vielleicht als Beleidigung, wenn Kobolde die Handwerkskunst der Miners' League besudeln, und fordert rasche Rückeroberung und scharfen Stahl."},sec={{t="Ein erschöpftes Depot",b="Die Silberbachmine liegt im nördlichen Loch Modan, östlich der Station Algaz. Ihr Silber war schon vor langer Zeit erschöpft, also machte die zwergische Miners' League die leeren Schächte zum Depot für Ersatzausgrabungsgerät, Spitzhacken und Bereitstellungsmaterial. Überall in Khaz Modan eignen sich stabile Tunnel gut als Lager, sofern sie bewacht und gegen die Wildnis abgeriegelt bleiben."},{t="Pfoten im Depot",b="Seit die Wachsamkeit der Zwerge in ganz Loch Modan nachgelassen hat, sind Kobolde in die Mine geschlüpft. Dunkle Schächte und glänzende Eisenwerkzeuge lockten die Aasgeier an, und bald wurde das Depot zu ihrem Bau. Gebirgsjäger Sturmlanze ist bereit, Krieger hineinzuführen und sie zu vertreiben, doch deren schwere Stiefel und weit ausholende Hiebe könnten die Kisten zertrümmern. Ihr könnt Euch hineinschleichen oder hineinkämpfen, um die Vorräte der Miners' League zu bergen, bevor der Angriff beginnt."}},faq={{q="Warum wurde Ausrüstung in der Mine zurückgelassen, obwohl sie bereits erschöpft war?",a="Nachdem das Erz erschöpft war, machte die Miners' League die Silberbachmine zu einem zentralen Depot. Ihre trockenen, stabilen Tunnel schützten sperrige Werkzeuge und Vorräte, bis sie anderswo gebraucht wurden.",al={"warum ausrüstung in der silberbachmine","warum werkzeuge in der mine","depot der miners' league"}},{q="Warum räumt Gebirgsjäger Sturmlanze die Mine nicht selbst?",a="Sturmlanze hat Befehl zu warten. Auch die Miners' League will zuerst ihre Ausrüstung bergen lassen, denn durch enge, dunkle Schächte stürmende Krieger könnten die verpackten Werkzeuge im Kampf zertrümmern.",al={"warum geht sturmlanze nicht","warum warten die gebirgsjäger","grund für sturmlanzes aufgabe"}},{q="Wo liegt die Silberbachmine?",a="Die Silberbachmine liegt im nördlichen Loch Modan, östlich der Station Algaz und südwestlich des Steinwerkdamms.",al={"lage der silberbachmine","wo ist die silberbachmine","wo spielt schmutzige pfoten"}},{q="Was macht zwergische Werkzeuge für Kobolde so interessant?",a="Kobolde sammeln unter der Erde Verwertbares und begehren metallene Spitzhacken, Schaufeln, Kerzen und fertige Eisenwaren. Ein Lager voller zwergischer Werkzeuge erleichtert das Graben und ist für sie kaum zu widerstehen.",al={"warum wollen kobolde ausrüstung","werkzeugdiebstahl durch kobolde","kobolde silberbachmine"}},{q="Ist es gefährlich, die Silberbachmine allein zu erkunden?",a="Enge Gänge und dicht gedrängte Gruppen von Kobolden machen die Mine gefährlich. Gebirgsjäger Sturmlanze warnt, dass Ihr vielleicht Gefährten mitnehmen solltet.",al={"ist schmutzige pfoten schwer","schwierigkeit der silberbachmine","schmutzige pfoten allein schaffen"}},{q="Wem gehören die in der Mine gelagerten Vorräte?",a="Die Vorräte gehören der Miners' League von Eisenschmiede, der Handelsgilde, die Steinbrüche, Bergbau und unterirdische Ressourcen im gesamten Zwergenreich beaufsichtigt.",al={"wem gehört die ausrüstung","kisten der miners' league","wer leitet die miners' league"}}},fx={c638d192={q="Warum möchte Gebirgsjäger Sturmlanze, dass die Minenarbeiterausstattung geborgen wird?",a="Die Bergarbeiterliga baute die erschöpfte Silberbachmine in ein Lagerhaus um, aber Kobolde haben die Tunnel befallen und die Ausrüstung beschlagnahmt. Während die Gebirgsjäger planen, das Ungeziefer bald zu vertreiben, besteht die Liga darauf, dass ihre wertvollen Werkzeuge zuerst geborgen werden. Sturmlanze schickt Euch vor der militärischen Säuberung hinein, damit die groben Zwergenkrieger beim anstehenden Angriff nicht die empfindliche Ausrüstung zertrümmern.",al={"warum will sturmlanze die ausrüstung","sturmlanze filthy paws motiv","warum minenarbeiterausstattung bergen"}},e40e35ce={q="Wofür wird die Minenarbeiterausstattung verwendet?",a="Die Ausrüstung besteht aus hochwertigen zwergischen Werkzeugen und Vorräten, die der Bergarbeiterliga gehören. Nachdem die Silberbachmine kein Erz mehr förderte, nutzte die Liga ihre Kammern als sicheres Depot, um Arbeitsausrüstung zu lagern. Die Liga muss diese wertvollen Gerätschaften intakt zurückerhalten, bevor der Kampf sie ruiniert.",al={"was ist minenarbeiterausstattung","zweck der minenarbeiterausstattung","wozu die zwergischen werkzeuge"}},["31be8455"]={q="Wer hat die Silberbachmine übernommen?",a="Ein Rudel Kobolde hat die alten Minentunnel überrannt. Von Natur aus von unterirdischen Behausungen und glänzendem Metall angezogen, zogen diese Plagegeister in die erschöpften Schächte und begannen, die gelagerte Ausrüstung zu durchsuchen und zwergische Werkzeuge mit ihren Pfoten zu beschmutzen.",al={"wer ist in der silberbachmine","filthy paws feinde","wer hat die mine übernommen"}}},fp="11,238,16.342.0,17.421.0,56.174.0,57.184.0,40.108.0,50.183.0,53.137.0,41.153.0"}
P.entries["quest:308"] = {n="Jarvens Ablenkung",s="In der Brauerei Donnerbräu in Kharanos bewacht Jarven Donnerbräu die Kellervorräte. Seine Familie verbietet ihm, im Dienst aus den Fässern zu trinken, also bittet er Euch, ihm Donnerbier von oben zu bringen. Er hofft, ein Krug werde seinen Verstand schärfen.",h="In der Brauerei Donnerbräu in Kharanos bewacht Jarven Donnerbräu die Kellervorräte.",kw={"keller","brauerei","jarvens ablenkung","dun morogh","jarven donnerbräu","kharanos","donnerbier"},ang={["class:Rogue"]="Als Schurke wisst Ihr, dass starker Alkohol eine Wache ablenken kann. Jarven bittet selbst um diese Ablenkung.",["race:Dwarf"]="Als Zwerg kennt Ihr die Qual, neben Fässern mit legendärem Bier Wache zu stehen, ohne einen einzigen Schluck trinken zu dürfen."},sec={{t="Eine durstige Wache im Dienst",b="Jarven bewacht die tiefen Vorratslager, umgeben vom feinsten Starkbier Dun Moroghs. Seine Familie verbietet ihm, sich während der Wache an den Vorräten zu bedienen. Doch die Versuchung siegt, und er bittet Euch, ihm einen Krug kräftiges Donnerbier von den Zapfhähnen oben zu holen."},{t="Ein zweifelhafter Wachmacher",b="Jarven sagt, ein guter Trunk werde seine Sinne schärfen und seine Wachsamkeit stärken. Ob eine Wache im Dienst trinken sollte, ist eine andere Frage. Dennoch können nur wenige hartgesottene Zwerge einem Thunderbrew verübeln, das Bier seiner eigenen Sippe kosten zu wollen."}},faq={{q="Wer ist Jarven Donnerbräu?",a="Jarven Donnerbräu gehört zur angesehenen Familie Thunderbrew. Er bewacht die gelagerten Fässer im Keller der Brauerei Donnerbräu in Kharanos.",al={"wer ist jarven","jarvens geschichte","wache im keller"}},{q="Warum braucht Jarven jemanden, der ihm Bier bringt?",a="Jarvens Familie verbietet ihm, sich während der Wache an den Kellervorräten zu bedienen. Also bittet er einen Außenstehenden, ihm einen frischen Krug von oben zu bringen, wodurch die versiegelten Fässer unberührt bleiben.",al={"warum darf jarven nicht trinken","jarvens bierquest","warum alkohol holen"}},{q="Wo gibt es Donnerbier?",a="Der Gastwirt und die Schankwirte schenken Donnerbier oben im Hauptschankraum der Brauerei Donnerbräu in Kharanos aus.",al={"donnerbier besorgen","wo gibt es donnerbier","donnerbier kaufen"}},{q="Wo liegt die Brauerei Donnerbräu?",a="Die Brauerei Donnerbräu ist das zentrale Gasthaus in Kharanos, im verschneiten Herzen von Dun Morogh. Sie liegt ein Stück den Berg hinab von Eisenschmiede.",al={"brauerei kharanos","lage des thunderbrew-kellers","wo ist jarven"}},{q="Warum ist das Bier der Thunderbrew so berühmt?",a="Das Starkbier und die anderen Biere des Thunderbrew-Clans sind in ganz Khaz Modan und darüber hinaus berühmt. Ihre kräftige Wirkung, ihr Geschmack und ihre zwergische Wucht sind weithin bekannt.",al={"ruf der thunderbrew","was ist donnerbier"}},{q="Gibt es Ärger, wenn Jarven betrunken ist?",a="Jarven sagt, das Bier schärfe seinen Verstand, statt ihn zu trüben. Doch es lenkt ihn von jedem ab, der in den unteren Lagerräumen herumschnüffelt.",al={"jarven betrunken folgen","was passiert nach jarvens ablenkung"}}},fx={a200e5d8={q="Warum möchte Jarven Donnerbräu ein Fass Donnerbier?",a="Jarven ist damit beauftragt, die Keller zu bewachen, die von Fässern mit zwergischem Spirituosen umgeben sind, aber strenge Befehle untersagen es ihm, die Bestände in seiner Obhut anzurühren. Da er sich nach einem Drink sehnt, um seinen Verstand zu schärfen und die lange Wache zu überstehen, braucht er jemanden Diskreten, der ihm ein wenig von Thunderbrews feinstem Gebräu zusteckt, damit er nachgeben kann, ohne offen gegen die Disziplin zu verstoßen.",al={"warum will jarven bier","jarven motiv","warum trinkt jarven"}},["8c39bfa0"]={q="Wofür wird das Donnerbier verwendet?",a="Das Fass mit Donnerbier dient als starke persönliche Erfrischung, um den Durst von Jarven Donnerbräu zu stillen. Während er tief in den Kellern der Brennerei Wache schiebt, verlässt er sich darauf, dass Ihr es von den Zapfhähnen oben holt, damit er trinken kann, ohne seinen Posten aufzugeben oder die gelagerten Vorräte zu manipulieren.",al={"wofür ist das donnerbier","verwendung donnerbier","warum donnerbier besorgen"}}},fp="18,241,23.266.0,19.230.0,26.143.0,46.179.0,27.114.0,44.135.0,33.147.0,44.134.0"}
P.entries["quest:3082"] = {n="Geätzte Schrifttafel",s="Im Tal der Prüfungen schickt Gornek jungen Jägern eine gemeißelte Tafel. Jen'shans Zeichen ruft sie zur Ausbildung in die Wildnis.",h="Im Tal der Prüfungen schickt Gornek jungen Jägern eine gemeißelte Tafel.",kw={"dunkelspeer","durotar","geätzte schrifttafel","gornek","jäger","jen'shan","das tal der prüfungen"},ang={["class:Hunter"]="Als Jäger findet Ihr Euren ersten Platz unter den Jägern der Horde und beginnt, bei Eurem örtlichen Ausbilder in der Wildnis zu lernen.",["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie Orcs und Trolls ihre jeweiligen Stärken teilen, um beiden Völkern beim Überleben zu helfen.",["race:Orc"]="Als Orc lernt Ihr von Euren Dunkelspeerverbündeten verfeinerte Methoden des Anschleichens und Fährtenlesens und ergänzt damit die Kriegertraditionen Eures Volkes.",["race:Troll"]="Als Troll könnt Ihr sehen, wie das Jagdwissen der Dunkelspeer der Horde half, auf Kalimdor zu überleben und ihre Verbündeten zu unterstützen."},sec={{t="Ein Ruf zur Jagd",b="Nachdem junge Jäger sich gegen die Eber nahe dem Den bewährt haben, bringt Gornek ihnen eine gemeißelte Tafel. Jen'shans Zeichen ist in den Stein geritzt. Sie ist eine fähige Trolljägerin, die in der Nähe stationiert ist, und ihre Nachricht zeigt, dass erfahrene Jäger den Schneid des Rekruten bemerkt haben. Nun geht es vom Überleben örtlicher Gefahren zur disziplinierten Ausbildung in der Wildnis über."},{t="Geteiltes Wissen zum Überleben",b="Jen'shan lehrt, dass Orcs und Trolls innerhalb der Horde eine lange gemeinsame Geschichte haben. Die Orcs brachten ruhmreiche Traditionen der Krieger und Schamanen mit. Die Dunkelspeertrolle brachten uralte Fertigkeiten im Anschleichen, Fährtenlesen und Überleben mit, die den Orcs halfen, das Leben auf Azeroth zu meistern. Während Jen'shan neue Jäger ausbildet, teilen die beiden Völker ihr Wissen, verbunden durch den Respekt vor der Jagd."}},faq={{q="Wer schickt die Geätzte Schrifttafel?",a="Jen'shan schickt den beschrifteten Stein, und Gornek überbringt ihn, nachdem Ihr Euch im Tal der Prüfungen bewährt habt.",al={"wer schrieb die geätzte schrifttafel","absender der tafel","wer gab mir diese tafel"}},{q="Wo ist Jen'shan zu finden?",a="Jen'shan befindet sich im Tal der Prüfungen im Norden Durotars, bei den anderen Klassenlehrern nahe dem Den.",al={"jen'shans standort","wo ist jenshan","jenshan finden"}},{q="Warum unterrichten Trollausbilder hier Orcjäger?",a="Jen'shan sagt, die Horde habe sich wegen des Jagdwissens an die Trolls gewandt, als sie auf Azeroth ums Überleben kämpfte. Die Orcs kannten bereits die Wege der Krieger und Schamanen, und die beiden Völker teilen ihre Fertigkeiten noch immer.",al={"warum troll als jägerausbilder","troll unterrichtet orc","dunkelspeerjäger"}},{q="Was geschieht nach der Abgabe dieser Tafel?",a="Jen'shan nimmt Euch als ihren Schüler an und bietet an, Euch die grundlegenden Techniken, Schüsse und Überlebenspraktiken der Hordenjäger beizubringen, während Ihr Erfahrung sammelt.",al={"was kommt nach der tafel","geätzte schrifttafel belohnung hintergrund","jenshan folgequest"}},{q="Welche Voraussetzung muss erfüllt sein, bevor man diese Tafel erhält?",a="Ihr müsst zuerst Gorneks erste Aufgabe, Cutting Teeth, abschließen, indem Ihr scheckige Eber erlegt, um Eure Ausdauer zu beweisen.",al={"voraussetzung für die tafel","geätzte schrifttafel freischalten","voraussetzungen für die geätzte schrifttafel"}},{q="Kann jede Klasse diese Quest abschließen?",a="Nur angehende Jäger können diesen Ruf zur Ausbildung im Tal der Prüfungen erhalten. Gornek gibt anderen Klassen andere Aufforderungen.",al={"wer kann die geätzte schrifttafel erhalten","geätzte schrifttafel klassenvoraussetzung","ist das nur für jäger"}}},fp="13,120,21.359.0,23.357.0,28.108.0,28.99.0,45.195.0,42.152.0,62.109.0,34.124.0"}
P.entries["quest:3083"] = {n="Verschlüsselte Schrifttafel",s="Im Tal der Prüfungen schickt Gornek neue Schurken mit einer verschlüsselten Botschaft zu Rwag. Die Vorladung führt sie in den Den, wo die Schurkenausbildung mit der Shattered Hand verbunden ist.",h="Im Tal der Prüfungen schickt Gornek neue Schurken mit einer verschlüsselten Botschaft zu Rwag.",kw={"durotar","verschlüsselte schrifttafel","gornek","schurkenausbilder","rwag","shattered hand","the den","das tal der prüfungen"},ang={["class:Rogue"]="Als Schurke lernt Ihr durch die Schrifttafel Euren ersten Mentor Rwag kennen und erlebt den Einfluss der Shattered Hand in Durotar.",["race:Orc"]="Als Orc entstammt Ihr einer Kultur, die den offenen Kampf auf dem Schlachtfeld ehrt. Orcschurken dienen der heutigen Horde als Späher und Infiltratoren.",["race:Troll"]="Als Troll verbindet Ihr Euren Instinkt für die Fährtensuche im Dschungel mit der Klingenkunst, die Mentoren im Den lehren. So leistet Ihr unter Euren Orcverbündeten unauffällige Dienste."},sec={{t="Eine verschlüsselte Vorladung",b="Gornek gibt die Verschlüsselte Schrifttafel an Initianten, die sich gegen die einheimische Tierwelt bewähren. Ihre Botschaft ist in Geheimschrift verfasst, als Prüfung und Schutzmaßnahme für jene, die in Heimlichkeit, Gift und Täuschung ausgebildet werden. Die Vorladung schickt jeden Rekruten in den Den zu Rwag, dem Ausbilder der Schurken, Diebe und Beutelschneider der Horde."},{t="Der Schatten der Hand",b="Im Den bildet Rwag als ein mit der Shattered Hand verbündeter Agent neue Schurken aus. Er sagt, die Gilde werde nicht jeden Atemzug vorschreiben, doch die Hand zieht ihn zur Rechenschaft, wenn ein Lehrling versagt. Die junge Horde ist von Feinden umgeben, daher braucht sie lautlose Späher und flinke Beutelschneider, um Informationen zu sammeln und aus den Schatten zuzuschlagen."}},faq={{q="Welchem Zweck dient die Verschlüsselte Schrifttafel?",a="Die Verschlüsselte Schrifttafel ruft unerfahrene Schurken aus dem Tal der Prüfungen zu ihrem Ausbilder Rwag im Den.",al={"was bewirkt die schrifttafel","verschlüsselte schrifttafel zweck","warum verschlüsselte schrifttafel"}},{q="Wer überreicht dem Spieler die Schrifttafel?",a="Gornek, der die Prüfungen im Tal beaufsichtigt, gibt Euch die Schrifttafel, nachdem Ihr Euch in Eurer ersten Kampfprüfung durch das Töten von Mottled Boars bewährt habt.",al={"wer gibt die verschlüsselte schrifttafel","schrifttafel questgeber","gornek schrifttafel"}},{q="Wo ist Rwag zu finden?",a="Rwag ist tief im Den zu finden, dem Höhlenkomplex entlang der nördlichen Felswand des Tals der Prüfungen.",al={"rwag standort","wo ist rwag","rwag finden"}},{q="Was ist „die Hand“, die Rwag erwähnt?",a="Rwag meint die Shattered Hand, ein geheimes Netzwerk und eine Gilde von Assassinen, Spionen und Schurken im Dienst der Horde von Kriegshäuptling Thrall.",al={"was ist die hand","shattered hand rwag","wer ist die hand"}},{q="Warum ist die Schrifttafel in Geheimschrift verfasst?",a="Die Geheimschrift verbirgt vertrauliche Schurkenangelegenheiten und die Identitäten ihrer Kontaktleute vor neugierigen Blicken. Sie prüft auch, ob ein Initiant mit vertraulichen Botschaften umgehen kann.",al={"warum verschlüsselt","warum geheimschrift","schurken schrifttafel code"}},{q="Kann jede Klasse diese Quest annehmen?",a="Nein. Nur Trollschurken, die ihre Reise im Tal der Prüfungen beginnen, erhalten die Verschlüsselte Schrifttafel.",al={"verschlüsselte schrifttafel nur für schurken","können krieger verschlüsselte schrifttafel annehmen","schrifttafel klassenbeschränkung"}}},fp="16,168,15.321.0,22.347.0,44.113.0,38.141.0,24.107.0,37.124.0,49.150.0,35.99.0"}
P.entries["quest:3084"] = {n="Mit Runen beschriftete Schrifttafel",s="Im Tal der Prüfungen ruft Shikrik vielversprechende Initianden zur formellen Schamanenausbildung. Die Runen der Tafel rufen dazu auf, die Geister und die Elemente zu studieren: Erde, Feuer, Wasser und Luft.",h="Im Tal der Prüfungen ruft Shikrik vielversprechende Initianden zur formellen Schamanenausbildung.",kw={"durotar","elemente","gornek","schamane","shikrik","schrifttafel","thrall","das tal der prüfungen"},ang={["class:Shaman"]="Als Schamane erhaltet Ihr diese Tafel als Eure formelle Einweihung in diesen Pfad. Sie trägt Euch auf, die Elementarkräfte im Gleichgewicht zu halten und andere durch die Weisheit der Ahnen zu führen.",["faction:Horde"]="Als Mitglied der Horde teilt Ihr eine schamanische Tradition, die im rauen Grenzland Ehre und Gleichgewicht bietet.",["race:Orc"]="Als Orc seht Ihr in dieser Tafel die von Thrall vorangetriebene Rückkehr zum Schamanismus der Ahnen, die das Hexenmeistererbe der dämonischen Vergangenheit hinter sich lässt.",["race:Troll"]="Als Troll findet Ihr im Schamanismus Gemeinsamkeiten mit orcischen Mentoren wie Shikrik. Ihr verbindet Eure Zwiesprache mit den Ahnen mit den gemeinsamen elementaren Traditionen der Horde."},sec={{t="Ein Ruf zu den Geistern",b="Nachdem angehende Schamanen auf den staubigen Übungsplätzen im Tal der Prüfungen erste Disziplin bewiesen haben, erhalten sie von Gornek eine behauene Steintafel. Ihre Runen übermitteln eine Einladung von Shikrik, der örtlichen Schamanenlehrerin. Die Aufforderung besagt, dass jeder Initiand bereit ist, über den körperlichen Kampf hinauszublicken und auf die tieferen Strömungen der natürlichen Welt zu hören."},{t="Spirituelle Führung in der New Horde",b="Der Schamanismus nimmt in der wiedererstarkten Horde einen heiligen Platz ein. Shikrik lehrt, dass Schamanen ihre Macht aus den vier Elementen und ihre Stärke aus den Geistern der Ahnen schöpfen. Sie folgen dem Vorbild von Kriegshäuptling Thrall als spirituelle Führer und Quellen der Weisheit für ihre Gemeinschaften. In ganz Durotar beschützen sie die Siedlungen, die dort Wurzeln schlagen."}},faq={{q="Was ist die Mit Runen beschriftete Schrifttafel?",a="Gornek gibt Schamanenneulingen im Tal der Prüfungen eine beschriftete Steintafel, die eine Aufforderung von Shikrik trägt. Ihre Runen rufen den jungen Abenteurer zur formellen Ausbildung in den spirituellen und elementaren Künsten.",al={"mit runen beschriftete schrifttafel","schrifttafel gegenstand","schamanenschrifttafel"}},{q="Wer ist Shikrik?",a="Shikrik ist die Schamanenlehrerin nahe dem Eingang von Den im Tal der Prüfungen. Sie hilft angehenden Schamanen der Orcs und Trolle, die Elemente zu meistern und ihre Pflicht als spirituelle Führer innerhalb der Horde kennenzulernen.",al={"shikrik","wer ist shikrik","schamanenlehrer tal der prüfungen"}},{q="Warum beruft sich Shikrik auf Thrall, wenn sie mit angehenden Schamanen spricht?",a="Kriegshäuptling Thrall führte die Wiederbelebung des überlieferten Schamanismus an, nachdem dämonische Verderbnis die Old Horde verschlungen hatte. Shikrik nennt ihn als Vorbild für die Pflicht eines Schamanen, die Harmonie der Elemente zu wahren und sein Volk zu führen und zu beschützen.",al={"warum thrall","shikrik erwähnt thrall"}},{q="Wo befindet sich Shikrik?",a="Shikrik steht direkt vor dem Eingang von Den auf der Ostseite des Tals der Prüfungen, bereit, Schamanenneulingen ihre ersten Techniken beizubringen.",al={"wo ist shikrik","shikrik finden"}},{q="Wer händigt die Tafel aus?",a="Gornek beaufsichtigt die ersten Prüfungen der Neuankömmlinge im Tal der Prüfungen. Er gibt die Tafel einem Initianden, der seine grundlegende Befähigung bewiesen hat.",al={"wer gibt die schrifttafel","gornek schrifttafel"}},{q="Welche grundlegende Philosophie lehrt Shikrik?",a="Shikrik lehrt, dass ein Schamane seine Macht aus Feuer, Erde, Wasser und Luft schöpft und seine Ausdauer und Entschlossenheit aus den Geistern der Ahnen. Von Schamanen wird erwartet, den Städten oder Kriegerbanden, denen sie sich anschließen, Weisheit und Schutz zu bieten.",al={"shikriks philosophie","schamanische lehren"}}},fp="21,190,21.323.0,37.317.0,34.197.0,15.206.0,60.227.0,25.141.0,25.149.0,40.210.0"}
P.entries["quest:3085"] = {n="Geheiligte Schrifttafel",s="Im Tal der Prüfungen trägt die Geheiligte Schrifttafel Ken'jais Ruf an junge Priester nach ihrer ersten Prüfung. Sie weist ihnen den Weg der Dunkelspeere zur Zwiesprache mit den Geistern.",h="Im Tal der Prüfungen trägt die Geheiligte Schrifttafel Ken'jais Ruf an junge Priester nach ihrer ersten...",kw={"dunkelspeer","durotar","gornek","geheiligte schrifttafel","ken'jai","priester","geister","the den","das tal der prüfungen"},ang={["class:Priest"]="Als Priester lasst Ihr die gewöhnlichen Prüfungen des Tals hinter Euch und beginnt Eure förmliche spirituelle Ausbildung bei Ken'jai vor The Den.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, spirituelle Riten und den Willen der Geister im Mittelpunkt zu halten, während Euer Volk Durotar besiedelt.",["race:Troll"]="Als Troll folgt Ihr den Traditionen der Dunkelspeere, die Ahnengeister und Loa ehren, statt den dogmatischen Wegen fremder Priester."},sec={{t="Eine Botschaft von Ken'jai",b="Nachdem Ihr Euch unter Gorneks Aufsicht gegen die Eber bewiesen habt, gibt er Euch einen beschrifteten Stein: die Geheiligte Schrifttafel. Ken'jais Zeichen steht auf ihrer Botschaft. Der Mystiker der Dunkelspeere wartet vor The Den, wo er über Neuankömmlinge wacht, die sich zum Glauben und zur spirituellen Magie hingezogen fühlen."},{t="Zwiesprache mit den Geistern",b="Die Priester der Dunkelspeere unter der Horde suchen Zwiesprache mit Geistern und Loa. Jenseits des Meeres folgen menschliche und zwergische Priester dem Heiligen Licht. Ken'jai heißt Euch in Durotar willkommen und lehrt, dass spirituelle Disziplin Eure Macht wachsen lässt. Er wird Euch in höhere Riten einführen, während Euer Band zu den Geistern reift."}},faq={{q="Was ist die Geheiligte Schrifttafel?",a="Die Geheiligte Schrifttafel trägt eine Botschaft von Ken'jai, dem Troll-Priesterlehrer, an junge Priester im Tal der Prüfungen. Gornek bewahrt sie auf, bis Ihr Eure grundlegenden Fähigkeiten im Tal bewiesen habt.",al={"was ist die geheiligte schrifttafel","geheiligte schrifttafel gegenstand","schrifttafel hintergrundgeschichte"}},{q="Wer ist Ken'jai?",a="Ken'jai ist ein Priesterlehrer der Dunkelspeertrolle vor The Den im Tal der Prüfungen. Er lehrt junge Initianden, mit Geistern Zwiesprache zu halten und die spirituellen Künste der Heilung und des Schattens zu erlernen.",al={"kenjai","wer ist kenjai","ken'jai lehrer"}},{q="Warum kämpft ein Priester anfangs gegen scheckige Eber?",a="Ihr beweist grundlegende Selbstständigkeit und Überlebensfähigkeiten, bevor ein spezialisierter Lehrer Zeit in Eure Ausbildung investiert. Jeder Initiand im Tal der Prüfungen stellt sich dieser Prüfung, ungeachtet seiner Berufung.",al={"warum eber töten","cutting teeth zusammenhang"}},{q="Wie unterscheidet sich Ken'jais Priestertum vom Heiligen Licht?",a="Die Priester der Dunkelspeere rufen Geister und Loa an, während die Kirchen der Menschen und Zwerge das Heilige Licht verehren. Ken'jai lehrt Euch, die Gunst dieser unsichtbaren Mächte zu bewahren und im Einklang mit ihnen zu leben.",al={"trollpriester hintergrundgeschichte","priester der horde","geister gegen licht"}},{q="Wo liegt The Den?",a="The Den ist eine Siedlung in einer ausgehöhlten Höhle im Tal der Prüfungen im Süden Durotars. Lehrer und Prüfungsmeister nutzen sie als Anlaufstelle für neue Rekruten der Horde.",al={"the den durotar","wo liegt the den","kenjai standort"}},{q="Können Orcs durch diese Quest Priester werden?",a="Nein. Nur die Dunkelspeertrolle im Tal der Prüfungen besitzen die spirituellen Traditionen, um sich unter Ken'jai zu Priestern ausbilden zu lassen. Die Kultur der Orcs folgt stattdessen dem Schamanismus und der Hexenmeistermagie.",al={"orcpriester","können orcs priester sein","orc geheiligte schrifttafel"}}},fp="15,175,22.264.0,26.302.0,28.188.0,15.181.0,51.186.0,57.189.0,17.149.0,43.174.0"}
P.entries["quest:3086"] = {n="Glyphenschrifttafel",s="Im Tal der Prüfungen ruft eine Glyphenschrifttafel junge Magier der Horde zu Mai'ah. Gornek übergibt sie ihnen, nachdem sie ihre Stärke bewiesen haben, und die Trolllehrerin wartet vor der Den.",h="Im Tal der Prüfungen ruft eine Glyphenschrifttafel junge Magier der Horde zu Mai'ah.",kw={"arkan","durotar","glyphenschrifttafel","gornek","magier","mai'ah","the den","das tal der prüfungen"},ang={["class:Mage"]="Als Magier werdet Ihr von der Lehrerin des Tals förmlich unter den Zauberwirkern der Horde willkommen geheißen. Mai'ah lehrt Euch die Disziplin, die Ihr braucht, um rohe Magie zu kontrollieren.",["race:Orc"]="Als Ork beschreitet Ihr unter Mai'ah einen seltenen Pfad. Die orkische Kultur ist seit Langem von Schamanen und Kriegern geprägt, und nur wenige Eures Volkes haben sich an der arkanen Magie versucht.",["race:Troll"]="Als Dunkelspeertroll spiegelt Eure Ausbildung bei Mai'ah wider, dass Euer Stamm neben seinen traditionellen spirituellen Riten zunehmend auch formelle Zauberkunst praktiziert."},sec={{t="Eine Botschaft in Stein",b="Ihr habt Eure Stärke gegen die Tierwelt im Tal der Prüfungen bewiesen. Gornek gibt Euch eine beschriftete Tafel von Mai'ah, der Magierlehrerin des Tals. Sobald Ihr bereit seid, Eure arkanen Studien zu beginnen, bittet sie Euch, sie am Eingang der Den aufzusuchen."},{t="Die Gefahren des Unsichtbaren",b="Mai'ah spricht offen über die Macht eines Magiers und ihre Gefahren. Der unsichtbare Sog der Magie zur Verderbnis, so warnt sie, ist eine größere Bedrohung als rivalisierende Krieger oder feindliche Völker. Demut und Geduld sind wichtig. Ohne sie kann ungezügelte Zauberei einen Magier glauben lassen, mehr zu beherrschen, als es tatsächlich der Fall ist."}},faq={{q="Wer übergibt dem Spieler die Glyphenschrifttafel?",a="Gornek gibt Euch die Tafel, nachdem Ihr die scheckigen Eber im Tal der Prüfungen beseitigt habt.",al={"wer gibt die glyphenschrifttafel","wo gibt es die glyphenschrifttafel","glyphenschrifttafel start"}},{q="Wer ist Mai'ah?",a="Mai'ah ist eine Magierlehrerin der Dunkelspeertrolle vor der Den im Tal der Prüfungen. Sie lehrt angehende Magier der Horde ihre ersten Zauber und warnt sie vor arkaner Verderbnis.",al={"wer ist maiah","mai'ah hintergrundgeschichte","troll magierlehrerin"}},{q="Wo befindet sich Mai'ah?",a="Mai'ah wartet direkt vor dem Eingang der Den, rechts von der Tunnelöffnung im nördlichen Tal der Prüfungen.",al={"wo ist maiah","maiah standort","maiah finden"}},{q="Welche Warnung spricht Mai'ah über Magie aus?",a="Mai'ah warnt davor, dass Magie jene verderben kann, die sie wirken. Sie sagt, Magier sollten ihre unsichtbaren Versuchungen und Machtfantasien mehr fürchten als körperliche Feinde wie Orks, Elfen oder Zwerge.",al={"maiah warnung","magische verderbnis hintergrundgeschichte","was sagt maiah"}},{q="Erhalten andere Klassen die Glyphenschrifttafel?",a="Nein. Die Glyphenschrifttafel ist für angehende Magier bestimmt. Andere Klassen erhalten andere einführende Aufforderungen, etwa Runen, Schriftrollen oder Siegel, die zu ihren Lehrern passen.",al={"können andere klassen die glyphenschrifttafel erhalten","glyphenschrifttafel nur für magier"}},{q="Welche Voraussetzung muss erfüllt sein, um diese Tafel zu erhalten?",a="Ihr müsst zuerst Gorneks Einstiegsaufgabe abschließen, indem Ihr scheckige Eber auf den roten Erdebenen im Tal der Prüfungen tötet.",al={"glyphenschrifttafel voraussetzungen","voraussetzung für die glyphenschrifttafel"}}},fp="14,178,28.246.0,25.290.0,46.86.0,14.168.0,24.112.0,42.188.0,44.158.0,53.121.0"}
P.entries["quest:3087"] = {n="Geätztes Pergament",s="Im Tal der Prüfungen überbringt Gornek einem jungen Jäger Jen'shans Ruf. Er folgt auf die erste blutige Bewährungsprobe des Neulings und eröffnet ihm die Wildnisausbildung in Durotar.",h="Im Tal der Prüfungen überbringt Gornek einem jungen Jäger Jen'shans Ruf.",kw={"dunkelspeer","durotar","geätztes pergament","gornek","jägerlehrer","jen'shan","das tal der prüfungen"},ang={["class:Hunter"]="Als Jäger führt Euch dieser Ruf zu Jen'shan, um Eure Treffsicherheit zu verbessern und die Wildnis zu verstehen.",["faction:Horde"]="Als Jäger der Horde erkundet Ihr die Grenzen und versorgt die Lager mit Nahrung. Die frühe Ausbildung hilft, Durotars Versorgung und Schutz zu sichern.",["race:Orc"]="Als Orc verlasst Ihr Euch auf Mentoren wie Jen'shan, um die Jagdmethoden Eures Clans an Durotars karge Felsen und tödliche Bestien anzupassen.",["race:Troll"]="Als Rekrut der Dunkelspeere haltet Ihr durch die Ausbildung bei Jen'shan die uralten Traditionen des Fährtenlesens im Dschungel lebendig, die von den Echoinseln stammen."},sec={{t="Ein Ruf aus der Wildnis",b="Nachdem sie sich gegen Borsteneber bewährt haben, erhalten Jäger im Tal der Prüfungen ein Pergament von Gornek. Jen'shan, eine geschickte Jägerin der Dunkelspeere, hat es geschickt, nachdem sie die Neuankömmlinge vom Rand des Lagers aus beobachtet hatte. Ihre Nachricht heißt den Neuling zur förmlichen Ausbildung willkommen und würdigt die nötigen Instinkte, um Durotars ungezähmte Bestien und sein raues Land zu meistern."},{t="Der Weg des Jägers",b="Sich bei Jen'shan zu melden, markiert den Übergang vom Rekruten zum entschlossenen Pirscher. Sie warnt, dass die Jagd keineswegs leichter ist als die arkanen Künste oder der überlieferte Schamanismus. Durotars Raubtiere zu meistern, Fernkampfwaffen instand zu halten und in einem unbarmherzigen Land zu überleben, erfordert Disziplin.\n\nJen'shan schickt ihre Lehrlinge los, um den anderen Bewohnern des Tals zu helfen und ihre Fähigkeiten zu erproben. Danach kehren sie zurück, um fortgeschrittene Überlebenstechniken zu erlernen."}},faq={{q="Was ist das Geätzte Pergament?",a="Das Pergament ist eine schriftliche Aufforderung von Gornek im Namen der Jägerlehrerin Jen'shan. Es ruft vielversprechende Rekruten zu ihr, damit sie im Tal der Prüfungen eine spezialisierte Kampf- und Wildnisausbildung erhalten.",al={"was ist dieses pergament","geätztes pergament nachricht","jägerpergament"}},{q="Wer überbringt dem Spieler diese Aufforderung?",a="Gornek gibt Euch das Pergament nach Eurer ersten Prüfung, bei der Ihr Borsteneber im Tal der Prüfungen erlegt.",al={"wer gibt geätztes pergament","wo gibt es die quest"}},{q="Wer ist Jen'shan?",a="Jen'shan ist eine Trolljägerin der Dunkelspeere, die im Tal der Prüfungen stationiert ist. Sie beurteilt neue Jäger der Orcs und Trolle und lehrt Fernkampf, Fährtenlesen und den Umgang mit Wildtieren.",al={"jen'shan hintergrundgeschichte","wer ist jenshan"}},{q="Warum vergleicht Jen'shan Jäger mit Magiern und Schamanen?",a="Jen'shan warnt, dass viele die Jagd irrtümlich für einen leichteren Weg halten als den Umgang mit Ahnengeistern oder arkaner Magie. Tödliche Treffsicherheit und die Beherrschung wilder Bestien verlangen ebenso viel Hingabe und bergen ebenso große Gefahren.",al={"warum jagen nicht leicht ist","jen'shan dialog bedeutung"}},{q="Was geschieht, nachdem Ihr Euch bei Jen'shan gemeldet habt?",a="Jen'shan führt Euch in fortgeschrittene Jagdtechniken ein und schickt Euch los, um den anderen Bewohnern des Tals der Prüfungen zu helfen. Ihr übt Eure neu erworbenen Fähigkeiten, indem Ihr Euch im Überleben bewährt.",al={"was folgt nach geätztem pergament","jägerquest fortsetzung"}},{q="Wer kann diese Quest erhalten?",a="Nur neu erstellte Orcjäger, die im Tal der Prüfungen ausgebildet werden, können sie erhalten.",al={"wer erhält geätztes pergament","ist das nur für jäger"}}},fp="16,176,23.357.0,16.431.0,29.200.0,40.107.0,16.165.0,55.194.0,41.183.0,27.79.0"}
P.entries["quest:3088"] = {n="Verschlüsseltes Pergament",s="Im Tal der Prüfungen ruft Verschlüsseltes Pergament bewährte Orcschurkennovizen zum Den. Seine Geheimschrift führt sie zu Rwag, einem Agenten der Shattered Hand.",h="Im Tal der Prüfungen ruft Verschlüsseltes Pergament bewährte Orcschurkennovizen zum Den.",kw={"durotar","verschlüsseltes pergament","gornek","orcschurke","rwag","shattered hand","the den","das tal der prüfungen"},ang={["class:Rogue"]="Als Schurke markiert dieses Pergament Eure Aufnahme in die geheimen Reihen der Horde. Es macht Euch mit Rwag bekannt und führt Euch zu Eurer ersten fachlichen Ausbildung.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass selbst ein ehrenhafter Kriegshäuptling wie Thrall Spione und Späher braucht, um Durotars junge Lande vor verborgenen Bedrohungen zu schützen.",["race:Orc"]="Als Orc bringt Ihr die Disziplin Eurer Ahnen mit der stillen Gerissenheit in Einklang, die die Shattered Hand verlangt. Krieger hingegen suchen offenen, blutdürstigen Ruhm."},sec={{t="Eine verschlüsselte Vorladung",b="Gornek gibt das verschlüsselte Pergament an Orcnovizen, die sich gegen die einheimischen Wildtiere bewährt haben. Andere Ausbilder werben auf der Lichtung offen Schüler an, doch Schurkenlehrer Rwag verschickt seine Vorladung in Geheimschrift. Die Nachricht führt Euch am sonnenbeschienenen Lager vorbei und tief in die Höhle namens Den."},{t="Augen in den Schatten",b="Ihr findet Rwag, der zwischen den Felsen im Den Wache hält. Tiefer in der Höhle lauern Hexenmeister, und Rwag erzählt Euch, dass er Rekruten für die Shattered Hand beobachtet. Die orcische Gesellschaft schätzt offen gezeigte Ehre und Ruhm im Kampf. Die Shattered Hand arbeitet im Verborgenen als Netzwerk der Horde aus Spionen, Halsabschneidern und Informationsbeschaffern."}},faq={{q="Wer verschickt das Verschlüsselte Pergament?",a="Rwag, der Schurkenlehrer im Tal der Prüfungen, verfasst das Pergament. Er lässt Gornek die verschlüsselte Nachricht nach ihren ersten Prüfungen an vielversprechende junge Orcs überbringen.",al={"wer hat das pergament geschrieben","wer gab mir verschlüsseltes pergament","wer hat die nachricht geschickt"}},{q="Welchen Zweck hat diese Quest?",a="Das Pergament führt Orcschurken zu Rwag im Den, wo ihre eigentliche Ausbildung beginnt. Er lehrt sie Schleichen, Schlösserknacken und Täuschung im Kampf.",al={"warum brauche ich verschlüsseltes pergament","was bewirkt diese quest"}},{q="Wo befindet sich Rwag?",a="Rwag versteckt sich im Den, einer dunklen Höhle im Norden des Tals der Prüfungen. Er hält sich nahe dem Eingang auf und ist den Hexenmeistern tiefer im Inneren gegenüber misstrauisch.",al={"wo ist rwag","rwag finden","rwags standort"}},{q="Warum ist das Pergament verschlüsselt?",a="Die Geheimschrift hindert umherstreifende Grobiane und neugierige Außenstehende daran, die Vorladung zu lesen. Sie prüft auch, ob ein Anwärter eine geheime Nachricht entschlüsseln kann.",al={"warum geheimschrift","warum ist die nachricht verschlüsselt"}},{q="Wer ist die Shattered Hand?",a="Die Shattered Hand begann als berüchtigter Orcclan, der für Selbstverstümmelung bekannt war. In Thralls Horde ist sie eine Organisation aus Spähern, Assassinen und Geheimagenten, die aus den Schatten heraus die Interessen der Horde schützt.",al={"shattered hand horde","was ist die shattered hand"}},{q="Warum misstraut Rwag Nartok?",a="Nartok ist ein Hexenmeisterlehrer tiefer im Den. Rwag misstraut den dunklen Zauberwirkern, die in den tiefsten Winkeln der Höhle offen Teufelsrituale abhalten.",al={"rwag nartok","warum hasst rwag hexenmeister"}}},fp="19,154,15.295.0,19.316.0,34.160.0,34.144.0,22.150.0,31.144.0,27.212.0,30.145.0"}
P.entries["quest:3089"] = {n="Mit Runen beschriftetes Pergament",s="Im Tal der Prüfungen gibt Gornek neuen Schamanen Mit Runen beschriftetes Pergament, eine Aufforderung von Shikrik. Damit beginnt ihre Ausbildung in der Zwiesprache mit Geistern und Elementen.",h="Im Tal der Prüfungen gibt Gornek neuen Schamanen Mit Runen beschriftetes Pergament, eine Aufforderung von...",kw={"ahnen","durotar","elemente","gornek","mit runen beschriftetes pergament","schamane","shikrik","das tal der prüfungen"},ang={["class:Shaman"]="Für Euch als Schamanen markiert dieses Pergament den ersten Schritt auf einem spirituellen Pfad. Es bindet Euch an die Geister und Durotars ungezähmte Elemente.",["race:Orc"]="Als Orc ehrt Eure Rückkehr zum Schamanismus die überlieferten Traditionen der Ahnen Draenors. Die dämonische Verderbnis der Old Horde hätte sie beinahe ausgelöscht.",["race:Troll"]="Als Dunkelspeertroll bringt Ihr Eure natürliche Verbundenheit mit Geistern und Eure Ahnenverehrung in die gemeinsamen schamanischen Traditionen der Horde ein."},sec={{t="Ein Ruf der Geister",b="Neue Orcschamanen beweisen, dass sie gegen die örtliche Tierwelt bestehen können. Dann gibt Gornek, der über das Tal der Prüfungen wacht, ihnen eine mit Runen beschriftete Aufforderung. Shikrik, die Schamanenausbilderin des Tals, hat die mystische Botschaft verfasst und bittet jeden neu eingetroffenen Initianden, sie aufzusuchen."},{t="Der Pfad des Schamanen",b="Mit der Begegnung mit Shikrik beginnt die heilige Pflicht eines Schamanen gegenüber der Horde. Sie lehrt, dass Schamanen als Mittler für die Ahnengeister dienen und den Zorn der Elemente entfesseln. Unter ihrer Anleitung lernen neue Schamanen, spirituelle Energien zu kanalisieren, Wunden zu heilen und Kalimdors Naturkräfte anzurufen."}},faq={{q="Was ist Mit Runen beschriftetes Pergament?",a="Gornek gibt neuen Schamanen im Tal der Prüfungen eine schriftliche Aufforderung, ihre formelle Ausbildung bei ihrer Ausbilderin Shikrik zu beginnen.",al={"was ist diese quest","pergamentquest","schamanenstartbrief"}},{q="Wer schickt das Pergament?",a="Shikrik hat die Botschaft verfasst. Sie bildet Schamanen nahe den Höhlen im Tal der Prüfungen aus und erwartet jene, die auserwählt sind, ihr Volk spirituell zu führen.",al={"wer schrieb das pergament","shikriks brief","wer ist shikrik"}},{q="Wohin bringe ich das Pergament?",a="Ihr bringt das Pergament nach einem kurzen Fußweg innerhalb des Tals der Prüfungen zu Shikrik. Sie wartet unterhalb der roten Felsen, um Orc- und Trollschamanen auszubilden.",al={"wohin gehen","wo ist shikrik","abgabeort"}},{q="Warum wurde mein Charakter dafür auserwählt?",a="Shikrik sagt, wer sich zum Schamanismus hingezogen fühlt, sei auserwählt, als Mittler für die Ahnen zu dienen und mit den Elementarkräften der Welt zu sprechen.",al={"warum schamane","warum auserwählt","hintergrund der schamanenberufung"}},{q="Was geschieht nach der Übergabe des Pergaments?",a="Shikrik nimmt Euch als ihren Schüler an. Sie führt Euch in die Elementarmagie, die Zwiesprache mit den Ahnen und die Grundlagen der Heilung und des Kampfes ein.",al={"nächster schritt","was macht shikrik","nach dem pergament"}},{q="Kann jede Klasse diese Quest abschließen?",a="Nur neue Schamanen erhalten Mit Runen beschriftetes Pergament. Andere Klassen erhalten eigene Aufforderungen, ihre jeweiligen Ausbilder aufzusuchen.",al={"nur für schamanen","wer erhält dieses pergament","pergament für krieger"}}},fp="24,168,26.258.0,22.282.0,37.122.0,24.142.0,30.132.0,42.132.0,44.138.0,34.116.0"}
P.entries["quest:309"] = {n="Beschützen der Fracht",s="Im südlichen Loch Modan bringt Miran Sprengpulver zu Eisenbands Ausgrabungsstätte. Ausgrabungsleiter Eisenband braucht es für seine Ausgrabung, doch unterbrochene Nachschublinien und Bedrohungen für die Kurierwagen haben Miran zum Stillstand gezwungen.",h="Im südlichen Loch Modan bringt Miran Sprengpulver zu Eisenbands Ausgrabungsstätte.",kw={"sprengpulver","hinterhalt der dunkeleisenzwerge","eisenbands ausgrabungsstätte","loch modan eskorte","miran","ausgrabungsleiter eisenband"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, die Kuriere von Loch Modan vor unterirdischen Plünderern zu schützen und die Verbindung zwischen Eisenschmiede und den östlichen Grenzgebieten aufrechtzuerhalten.",["profession:Mining"]="Als Bergarbeiter kennt Ihr den Wert und die Gefahren von Sprengpulver, wenn Ihr das hartnäckige Grundgestein von Khaz Modan aufbrecht.",["race:Dwarf"]="Als Zwerg aus Eisenschmiede verteidigt Ihr Eisenbands Vorräte und schützt Entdeckungen aus dem Erbe Eurer Ahnen vor Sabotage durch Eure erbitterten Verwandten, die Dunkeleisenzwerge."},sec={{t="Pulvertransport in Gefahr",b="Ausgrabungsleiter Eisenband braucht Sprengpulver, um bei seiner Ausgrabung Stein zu durchbrechen. Miran sitzt mit einer schweren Ladung auf der Straße fest und wird bedroht. Ihr geleitet ihn über die unebenen Straßen zur Ausgrabungsstätte, damit das Pulver die Ausgrabung erreicht."},{t="Sympathisanten der Dunkeleisenzwerge",b="Infiltratoren der Dunkeleisenzwerge lauern nahe der Ausgrabungsstätte, um die explosive Fracht an sich zu reißen. Ihr Hinterhalt zeigt, dass Streitkräfte der Dunkeleisenzwerge illegale Materialien beschaffen und Zwietracht in Loch Modan säen. Die Lieferung hält die Ausgrabung am Laufen, doch Eisenband weiß nun, dass feindliche Sabotage bis ins Gebiet der Allianz reicht."}},faq={{q="Wer ist Miran?",a="Miran ist ein Kurier der Allianz, der lebenswichtigen Nachschub, darunter Sprengpulver, über die gefährlichen Nebenstraßen von Loch Modan zu Eisenbands Ausgrabungsstätte bringt.",al={"wer ist miran","miran loch modan","kurier miran"}},{q="Warum braucht Ausgrabungsleiter Eisenband das Pulver?",a="Ausgrabungsleiter Eisenband leitet eine archäologische Ausgrabung im südlichen Loch Modan. Sein Team braucht Sprengpulver, um Fels zu beseitigen, verschüttete Relikte freizulegen und die Arbeit fortzusetzen.",al={"warum eisenband pulver braucht","zweck des pulvers","eisenband sprengpulver"}},{q="Wer greift während der Eskorte an?",a="Saboteure der Dunkeleisenzwerge überfallen Miran nahe der Ausgrabungsstätte, um den Sprengstoff zu erbeuten und Eisenschmiedes Unternehmungen in der Region zu vereiteln.",al={"wer überfällt miran","angreifer im hinterhalt","angreifer der eskorte"}},{q="Wohin führt die Eskorte?",a="Die Eskorte folgt einer Straße im südlichen Loch Modan und endet bei Eisenbands Ausgrabungsstätte in den Hügeln südöstlich des Sees.",al={"ziel der eskorte","wohin geht miran","wo ist eisenband"}},{q="Warum sind Dunkeleisenzwerge in Loch Modan?",a="Der Klan der Dunkeleisenzwerge unterhält geheime Enklaven und Spione in ganz Khaz Modan. Sie überfallen Nachschublinien, sabotieren Ausgrabungen der Explorers' League und versuchen, Eisenschmiedes Verteidigung zu schwächen.",al={"dunkeleisenzwerge loch modan","warum sind dunkeleisenzwerge hier","anwesenheit der dunkeleisenzwerge"}},{q="Was geschieht nach der Ankunft der Fracht?",a="Ausgrabungsleiter Eisenband erhält das Pulver und dankt dem Licht für dessen Ankunft, obwohl Sympathisanten der Dunkeleisenzwerge in der Nähe operieren.",al={"questfortsetzung","was kommt nach beschützen der fracht","nächste quest"}}},fx={a48eefd2={q="Warum möchte Miran, dass dies erledigt wird?",a="Miran ist damit beauftragt, lebenswichtiges Sprengpulver durch feindliches Gebiet zum Ausgrabungsort von Ausgrabungsleiter Eisenband zu transportieren. Die Lieferung ist schwer und die Straße ist tückisch, was durch die lauernde Gefahr von Hinterhalten der Dunkeleisenzwerge noch schlimmer wird. Er kann nicht gleichzeitig die instabile Fracht tragen und sich auf dem gefährlichen Weg verteidigen.",al={"miran motiv","warum miran eskortieren","warum pulver liefern"}},bdc08a2b={q="Warum benötigt Miran Eure Hilfe anstatt der örtlichen Wachen?",a="Die Gebirgsjäger von Loch Modan sind bis zum Äußersten beansprucht, da sie Trogg-Einfälle abwehren und wichtige Siedlungen in der gesamten Region sichern müssen. Da keine offiziellen Patrouillen zur Verfügung stehen, um einen Versorgungstransport zu schützen, ist Miran auf fähige Abenteurer wie Euch angewiesen, um die in den Hügeln lauernden Dunkeleisenzwerge abzuwehren.",al={"warum ich miran","warum braucht miran hilfe","warum keine gebirgsjäger miran"}}},fp="23,214,21.234.0,22.293.1,13.155.0,45.165.0,30.146.0,27.123.0,33.171.0,40.129.0"}
P.entries["quest:3090"] = {n="Besudeltes Pergament",s="Ein besudeltes Pergament erwartet Euch nach Eurer Abwesenheit, und Euer Lehrer Nartok möchte mit Euch sprechen. Seine Worte stellen Thralls Herrschaft infrage und warnen vor den Gefahren, denen Hexenmeister ausgesetzt sind.",h="Ein besudeltes Pergament erwartet Euch nach Eurer Abwesenheit, und Euer Lehrer Nartok möchte mit Euch...",kw={"den","nartok","orgrimmar","zauberwirken","besudeltes pergament","thrall","das tal der prüfungen","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister seid Ihr der Gefahr ausgesetzt, vor der Nartok warnt: Eure Macht leichtsinnig einzusetzen, kann tödlich enden."},sec={{t="Eine Nachricht wartet",b="Das besudelte Pergament soll von Nartok stammen, Eurem neuen Lehrer. Lest es und sprecht dann mit ihm in The Den im Tal der Prüfungen. Er nennt die Orcs ein stolzes Volk und sagt, Thrall wende sich von einer Macht ab, die ihnen das Land sichern könnte."},{t="Ein Platz unter ihnen",b="Nartok sagt, Ihr hättet Euch ihren Reihen angeschlossen, doch die Macht der Hexenmeister wird Euch nicht willkommen machen. Thrall lässt Hexenmeister nach Orgrimmar, weil sie weiterhin Orcs sind. Nartok warnt, dass Leichtsinn tödlich sein kann. Er ist weiterhin bereit, Euch im Zauberwirken zu unterrichten, wenn Ihr Unterweisung braucht."}},faq={{q="Wer hat das Pergament geschickt?",a="Das Pergament soll von Nartok stammen, Eurem neuen Lehrer.",al={"wer hat das geschickt","von wem stammt das pergament"}},{q="Wo kann ich mit Nartok sprechen?",a="Nartok ist in The Den im Tal der Prüfungen.",al={"wo ist nartok","nartoks standort"}},{q="Was hält Nartok von Thrall?",a="Nartok sagt, Thrall wende sich von einer Macht ab, die ihnen das Land sichern könnte.",al={"meinung über thrall","warum thrall kritisieren"}},{q="Warum lässt Thrall Hexenmeister nach Orgrimmar?",a="Nartok sagt, Thrall lasse Hexenmeister nach Orgrimmar, weil sie noch immer Orcs sind.",al={"hexenmeister in orgrimmar","warum thrall hexenmeister duldet"}},{q="Welche Warnung spricht Nartok aus?",a="Nartok warnt, dass die Macht der Hexenmeister keine Akzeptanz garantiert und Leichtsinn tödlich sein kann.",al={"nartoks warnung","gefahr für hexenmeister"}},{q="Kann Nartok mir Zauber beibringen?",a="Nartok steht Euch weiterhin zur Verfügung, wenn Ihr Unterweisung im Zauberwirken braucht.",al={"zauberunterricht","hexenmeisterausbildung"}}},fp="17,176,15.241.0,18.262.1,23.64.0,30.45.0,33.73.0,46.78.0,30.90.0,27.65.0"}
P.entries["quest:3091"] = {n="Einfache Notiz",s="In Camp Narache ruft Harutt Thunderhorn junge Taurenkrieger dazu auf, ihr Volk zu verteidigen. Sein Aufruf erinnert sie daran, dass Krieger an der Seite von Druiden und Schamanen die Stammesgrenzen vor Zentauren schützen.",h="In Camp Narache ruft Harutt Thunderhorn junge Taurenkrieger dazu auf, ihr Volk zu verteidigen.",kw={"camp narache","zentauren","harutt thunderhorn","mulgore","die hochwolkenebene","einfache notiz","tauren","krieger"},ang={["class:Warrior"]="Harutt Thunderhorn lehrt angehende Taurenkrieger, ihren Stolz zu zügeln und Camp Narache gegen Zentauren zu verteidigen.",["race:Tauren"]="Jungen Tauren, die auf der Hochwolkenebene beginnen, zeigt die Notiz, dass der Schutz des Stammes ebenso viel zählt wie spirituelle Berufungen wie Schamanismus und Druidentum."},sec={{t="Ein Ruf zum Kampf",b="In Camp Narache überbringt ein Bote jungen Kriegern einen Aufruf von Harutt Thunderhorn. Der erfahrene Ausbilder fordert jeden Kämpfer auf, sich zu melden und die Ausbildung zur Verteidigung des Stammes zu beginnen."},{t="Die Bürde des Verteidigers",b="Die Shu'halo verehren ihre spirituellen Anführer, doch Harutt lehrt, dass Krieger eine ebenso große Bürde tragen. Sie patrouillieren an den Stammesgrenzen und jagen räuberische Zentaurenrudel, um ihre friedlichen Stammesangehörigen vor Angriffen zu schützen. Der Kampf mag Ruhm bringen, doch Krieger bleiben demütig und vollziehen dieselben traditionellen Riten wie Schamanen und Druiden."}},faq={{q="Wer hat die Einfache Notiz geschrieben?",a="Harutt Thunderhorn verfasste den Aufruf und ließ ihn durch einen Boten jungen Tauren überbringen, die für die Kampfausbildung bereit waren.",al={"wer hat die einfache notiz geschickt","wer hat die notiz geschrieben","absender der einfachen notiz"}},{q="Wer ist Harutt Thunderhorn?",a="Harutt Thunderhorn ist ein Kriegerausbilder der Tauren in Camp Narache in Mulgore. Er unterweist neue Krieger im Kampf und in den überlieferten Wegen der Stammeskriegführung.",al={"wer ist harutt","harutt thunderhorn","wo ist harutt"}},{q="Welchen Zweck hat die Einfache Notiz?",a="Die Notiz ruft frisch erwachte Krieger dazu auf, ihren Ausbilder aufzusuchen. Sie erinnert sie daran, dass Verteidiger und Jäger für den Stamm ebenso wichtig sind wie Druiden und Schamanen.",al={"warum ist die notiz wichtig","was steht in der notiz"}},{q="Warum werden Krieger zur Jagd auf Zentauren aufgerufen?",a="Feindselige Zentaurenrudel bedrohen die Grenzen Mulg ores. Harutt bildet Krieger darin aus, sie zu jagen und das Lager zu schützen.",al={"warum gegen zentauren kämpfen","konflikt zwischen tauren und zentauren"}},{q="Wo liegt Camp Narache?",a="Camp Narache liegt am Rand der Hochwolkenebene in Mulgore. Es ist das angestammte Ausbildungslager und die Ausgangssiedlung der jungen Tauren des Hawkwind-Stammes.",al={"lage von camp narache","wo ist camp narache"}},{q="Welche Stammesriten erwähnt Harutt?",a="Der Text nennt die Riten nicht beim Namen. Er besagt, dass jedes Stammesmitglied, von Kriegern und Jägern bis hin zu Schamanen und Druiden, sie durchlaufen muss, um Stärke, Demut und Hingabe an sein Volk zu beweisen.",al={"übergangsriten der tauren","welche riten durchlaufen tauren"}}},fp="11,203,19.174.0,21.316.0,26.112.0,26.149.0,39.153.0,45.107.0,30.160.0,42.190.0"}
P.entries["quest:3092"] = {n="Geätzte Notiz",s="In Camp Narache ruft die Geätzte Notiz einen jungen Taurenjäger zur Ausbildung bei Lanka Weitschuss. Die Nachricht leitet sein Studium der Wildnis ein.",h="In Camp Narache ruft die Geätzte Notiz einen jungen Taurenjäger zur Ausbildung bei Lanka Weitschuss.",kw={"camp narache","geätzte notiz","lanka weitschuss","mulgore","die hochwolkenebene","taurenjäger"},ang={["class:Hunter"]="Als Jäger beginnt Ihr, Treffsicherheit, das Überleben in der Wildnis und das Leben mit tierischen Gefährten zu erlernen.",["race:Tauren"]="Als Shu'halo ehrt Ihr die Earth Mother, indem Ihr die Tiere achtet, die Euren Stamm in Mulg ores Ebenen ernähren."},sec={{t="Ein Ruf zur Jagd",b="Grull Falkenwind übergibt die geätzte Nachricht einem jungen Tauren, der sich auf Treffsicherheit und Fährtenlesen versteht. Der Neuling hat zwischen den Klippen der Hochwolkenebene trainiert. Lanka Weitschuss ist auf die Abstammung und die ungeschliffene Begabung des jungen Tauren aufmerksam geworden und ruft ihn zur Ausbildung unter seinem wachsamen Auge."},{t="Tradition der Ebenen",b="Unter den Shu'halo kundschaften und kämpfen Jäger, doch sie dienen den Stämmen auch auf andere Weise. Sie liefern mit ihrer Beute Nahrung, bewachen nomadische Lager und halten engen Kontakt zu Kalimdors Wildtieren. Lanka beginnt mit Waffen und den Kreaturen Mulg ores. Mit der Zeit kann der Neuling die uralte Kunst erlernen, wilde Gefährten zu zähmen."}},faq={{q="Welchen Zweck hat die Geätzte Notiz?",a="Die Geätzte Notiz ruft einen unerfahrenen Taurenjäger zur Ausbildung bei Lanka Weitschuss in Camp Narache.",al={"was bewirkt die geätzte notiz","geätzte notiz zweck","warum habe ich die geätzte notiz erhalten"}},{q="Wer überbringt die Notiz?",a="Grull Falkenwind reicht die Notiz weiter. Er sagt, ein Bote des Jägerlehrers habe kurz zuvor nach dem jungen Jäger gesucht.",al={"wer gibt die geätzte notiz","geätzte notiz questgeber","rohaku notiz"}},{q="Wo befindet sich Lanka Weitschuss?",a="Lanka Weitschuss ist in Camp Narache auf der Hochwolkenebene, nahe dem Übungsgelände der Jäger, und steht bereit, neue Jäger zu unterweisen.",al={"wo ist lanka weitschuss","lanka weitschuss finden","lanka standort"}},{q="Warum werden Jäger unter den Tauren so verehrt?",a="Jäger ernähren die Tauren, lesen die Zeichen der Wildnis und wahren den Einklang mit den Geistern der Ebenen.",al={"taurenjäger hintergrundgeschichte","warum sind taurenjäger wichtig"}},{q="Welche Fertigkeiten vermittelt diese Ausbildung?",a="Lanka lehrt die Grundlagen der Jagd, den Umgang mit Fernkampfwaffen und Wissen über wilde Tiere. Mit der Zeit lehrt er womöglich die Rituale zum Zähmen tierischer Gefährten.",al={"was lehrt lanka","jägergrundlagen tauren"}},{q="Was ist der nächste Schritt nach dem Lesen der Notiz?",a="Ihr könnt Euch bei Lanka Weitschuss in Camp Narache melden, um Eure Ausbildung zu beginnen. Er lehrt Euch, Euer Gewehr abzufeuern, einen Begleiter zu zähmen und mit wachsender Erfahrung noch mehr.",al={"nächste quest nach geätzte notiz","geätzte notiz folgequest"}}},fx={["69749d8d"]={q="Warum gibt Euch Grull Falkenwind die Geätzte Notiz?",a="Grull Falkenwind gibt lediglich eine Nachricht im Auftrag eines Boten weiter, der durch Camp Narache geschickt wurde. Lanka Weitschuss, die Ausbilderin für Jäger im Lager, schickte den Boten speziell aus, um Euch zu suchen, da Ihr nun erwachsen werdet. Grull stellt einfach sicher, dass die Vorladung Eure Hände ohne Verzögerung erreicht, damit Ihr die ordnungsgemäße Ausbildung unter Eurem Volk beginnen könnt.",al={"warum gibt rohaku eine notiz","rohaku steinhuf motiv","warum gab mir rohaku das"}}},fp="11,129,21.260.0,23.308.0,39.85.0,22.126.0,31.116.0,44.94.0,41.136.0,45.135.0"}
P.entries["quest:3094"] = {n="Tiefgrüne Notiz",s="In Camp Narache ruft die Tiefgrüne Notiz junge Tauren dazu auf, Gart Nebelläufer aufzusuchen. Grull Falkenwind überbringt den Ruf in Garts Namen.",h="In Camp Narache ruft die Tiefgrüne Notiz junge Tauren dazu auf, Gart Nebelläufer aufzusuchen.",kw={"camp narache","druide","erdenmutter","gart nebelläufer","grull falkenwind","mulgore","die hochwolkenebene","tiefgrüne notiz"},ang={["class:Druid"]="Als Druide beginnt Ihr zu lernen, Azeroths wilde Energien und rastlose Geister zu kanalisieren.",["faction:Horde"]="Als Mitglied der Horde schließt Ihr Euch den Taurendruiden an. Sie verbinden die Fraktion mit Kalimdors Naturmysterien und schaffen zugleich einen Ausgleich zu ihrer kriegerischen Stärke.",["race:Tauren"]="Als Tauren erbt Ihr das Druidentum als heiligen Bund, der in der Hingabe an die Erdenmutter wurzelt."},sec={{t="Ein Ruf auf den Pfad",b="Auf der Hochwolkenebene übergibt Grull Falkenwind jungen Tauren eine Nachricht von einem Boten, den Gart Nebelläufer entsandt hat. Der Ruf fordert jene mit natürlichen Gaben auf, ihre Verantwortung anzunehmen. Er lädt sie ein, die uralte Druidenkunst der Tauren zu erlernen und einfache Dorferledigungen hinter sich zu lassen, um das Gleichgewicht der Ebenen zu wahren."},{t="Stimmen der Erdenmutter",b="Gart Nebelläufer warnt, dass Ahnen- und Naturgeister überall in Mulgore unruhig geworden sind. Taurendruiden wirken als lebende Avatare der Natur und wahren trotz ferner Rivalitäten den Einklang mit dem Willen der Erdenmutter. Auch Nachtelfen praktizieren druidische Künste, doch Gart sagt, ihr Stolz mache sie blind für die tiefe Verbindung der Tauren mit dem Reich der Natur."}},faq={{q="Was ist die Tiefgrüne Notiz?",a="Die Tiefgrüne Notiz ruft junge Taurendruiden dazu auf, Gart Nebelläufer in Camp Narache aufzusuchen und mit dem Erlernen der druidischen Künste zu beginnen.",al={"tiefgrüne notiz","druidenbrief","mulgore druidenquest notiz"}},{q="Wer übergibt dem Spieler die Notiz?",a="Grull Falkenwind gibt dem jungen Druiden die Notiz und sagt, ein von Gart Nebelläufer entsandter Bote habe nach ihm gesucht.",al={"wer gibt die tiefgrüne notiz","tiefgrüne notiz questbeginn"}},{q="Wo ist Gart Nebelläufer zu finden?",a="Gart Nebelläufer befindet sich in Camp Narache, im Schutz der natürlichen Felsklippen, wo er angehende Taurendruiden ausbildet.",al={"gart nebelläufer aufenthaltsort","wo ist gart"}},{q="Warum warnt Gart Nebelläufer vor den Nachtelfen?",a="Gart Nebelläufer sagt, der Stolz der Nachtelfen mache sie blind für die tiefe Verbindung der Tauren mit der Natur. Er mahnt seinen Schüler, auf die Weisheit der Erdenmutter zu hören.",al={"tauren- und nachtelfendruiden","nachtelfen stolz druide"}},{q="Warum sind die Geister in Mulgore unruhig?",a="Gart Nebelläufer spürt, wie sich Ahnen- und Naturgeister überall in Mulgore regen. Ihre Unruhe kennzeichnet die lebenslange Pflicht des neuen Druiden, das Gleichgewicht in der Wildnis zu wahren.",al={"mulgore geister unruhig","warum sind naturgeister zornig"}},{q="Welche Fähigkeit lehrt Gart nach Abschluss dieser Quest als Nächstes?",a="Wenn sich der junge Druide bei Gart Nebelläufer meldet, wird dieser sein Lehrer und verspricht, ihm mit wachsender Weisheit die Gaben der Erdenmutter zu vermitteln.",al={"was kommt nach der tiefgrünen notiz","druidenquest folgequest"}}},fx={["92e5d696"]={q="Warum gibt Euch Grull Falkenwind die Tiefgrüne Notiz?",a="Ein Bote hat speziell nach Euch gesucht im Auftrag von Gart Nebelläufer, dem Druiden-Ausbilder des Lagers. Grull Falkenwind leitet nur die dringende Nachricht weiter, damit Ihr nicht zögert, Eure formelle spirituelle Ausbildung unter Garts Führung zu beginnen.",al={"warum gibt rohaku eine notiz","rohaku steinhuf motiv","warum will rohaku das erledigt haben"}}},fp="12,132,21.330.0,25.343.0,25.119.0,36.115.0,35.116.0,54.146.0,40.157.0,62.150.0"}
P.entries["quest:3095"] = {n="Einfache Rolle",s="Eine versiegelte Schriftrolle mit Dannal Sterns Zeichen erreicht Euch, während Ihr gegen die Geißel kämpft. Sie ruft Euch nach Todesend, wo Dannal von Eurer Freiheit spricht und anbietet, Euch zu unterrichten.",h="Eine versiegelte Schriftrolle mit Dannal Sterns Zeichen erreicht Euch, während Ihr gegen die Geißel kämpft.",kw={"dannal stern","todesend","verlassene","geißel","einfache rolle","sylvanas","ausbildung"},sec={{t="Eine versiegelte Nachricht",b="Während Ihr fort wart und die hirnlose Geißel bekämpftet, traf eine Schriftrolle für Euch ein. Ihr Siegel trägt Dannal Sterns Zeichen. Er ist der Kriegerausbilder in Todesend, und die Nachricht bittet Euch, sie zu lesen und mit ihm zu sprechen, bevor Ihr wieder aufbrecht."},{t="Freiheit und Ausbildung",b="Dannal sagt, andere seien dem Tod entkommen und in die Stadt geflohen. Er sieht Potenzial in ihrer Widerstandskraft. Er schreibt Sylvanas zu, Euch an Leib und Seele befreit zu haben, obwohl die Seuche Euch noch immer befällt. Er bietet an, Euch zu unterrichten, während Ihr Erfahrung sammelt. Sylvanas wird Leute Eurer Klasse brauchen, die helfen, die Verlassenen zu retten."}},faq={{q="Wer hat mir die Schriftrolle geschickt?",a="Die Schriftrolle trägt Dannal Sterns Siegel. Er ist der Kriegerausbilder in Todesend.",al={"absender der schriftrolle","wer hat das geschickt","dannals schriftrolle"}},{q="Warum ist die Schriftrolle angekommen?",a="Die Schriftrolle bittet Euch, sie zu lesen und mit Dannal Stern in Todesend zu sprechen.",al={"warum die schriftrolle","wozu dient diese schriftrolle","einfache rolle"}},{q="Was sagt Dannal über Sylvanas?",a="Dannal schreibt Sylvanas zu, Euch an Leib und Seele befreit zu haben, obwohl die Seuche Euch noch immer befällt.",al={"sylvanas freiheit","was hat sylvanas getan","sylvanas und ich"}},{q="Was bietet Dannal an?",a="Dannal bietet an, Euch zu unterrichten, während Ihr Erfahrung sammelt, und lädt Euch ein, ihn aufzusuchen.",al={"dannals unterricht","kann dannal mich ausbilden","kriegerausbilder"}},{q="Was braucht Sylvanas von mir?",a="Dannal sagt, Sylvanas werde Leute Eurer Klasse brauchen, die helfen, die Verlassenen zu retten.",al={"was sylvanas braucht","rolle meiner klasse","zukunft der verlassenen"}}},fp="13,177,16.240.0,20.296.0,23.80.0,26.73.0,36.98.0,23.82.0,32.78.0"}
P.entries["quest:3096"] = {n="Verschlüsselte Rolle",s="In Todesend erreicht eine versiegelte Nachricht einen frisch erwachten Schurken der Verlassenen. Schattenpriester Sarvis schickt den Rekruten zu David Trias, sobald dieser seine Bereitschaft bewiesen hat.",h="In Todesend erreicht eine versiegelte Nachricht einen frisch erwachten Schurken der Verlassenen.",kw={"david trias","todesend","verschlüsselte rolle","schurke der verlassenen","schattenpriester sarvis","shadowstalkers","tirisfal"},ang={["class:Rogue"]="Als Schurke erhaltet Ihr eine vertrauliche Vorladung in das verdeckte Netzwerk der Verlassenen. Eure ersten Schritte unter den frisch Erweckten könnten Euch in den Geheimdienst führen.",["race:Undead"]="Als frisch erweckter Verlassener helft Ihr, Tirisfal gegen die Geißel und die verbliebenen Lebenden zu sichern. Späher und verdeckte Agenten sind für die Überlebensstrategie der Dunklen Fürstin unerlässlich."},sec={{t="Eine stille Vorladung",b="Frisch erweckte Verlassene kämpfen auf dem Friedhof gegen geistlose Zombies, während Todesends Anführer nach jenen Ausschau halten, die zu Heimlichkeit und Täuschung neigen. Sobald Ihr Eure Bereitschaft bewiesen habt, übergibt Euch Schattenpriester Sarvis ein versiegeltes Pergament. Das diskrete Siegel von David Trias kennzeichnet eine frühe Verbindung zum verdeckten Netzwerk unter der Führung der Verlassenen."},{t="Augen in den Schatten",b="David Trias beobachtet die Wegkreuzung und das Gasthaus von Todesend und sucht nach Anwärtern für künftige verdeckte Einsätze. Die Verlassenen brauchen disziplinierte Agenten für ihr junges Königreich, keine gewöhnlichen Diebe oder leichtsinnigen Beutelschneider. Trias sagt, fähige Schurken könnten die Aufmerksamkeit der Shadowstalkers erregen, eines Kaders der Verlassenen, der Scharfsinn, Präzision und absolute Treue zur Dunklen Fürstin schätzt."}},faq={{q="Welchen Zweck hat die Verschlüsselte Rolle?",a="Die Rolle lädt einen frisch erwachten Schurken der Verlassenen vertraulich ein, David Trias für eine besondere Ausbildung aufzusuchen. Schattenpriester Sarvis übergibt sie Euch, sobald Ihr Euer Können bewiesen habt.",al={"was ist die verschlüsselte rolle","was bewirkt die rolle","warum verschlüsselte rolle"}},{q="Wer ist David Trias?",a="David Trias ist der Schurkenmentor im Gasthaus von Todesend. Er beurteilt neue Rekruten und sucht nach Anwärtern für größere Geheimdiensteinsätze der Verlassenen.",al={"david trias","wer ist trias","schurkenlehrer todesend"}},{q="Wer sind die Shadowstalkers, die Trias erwähnt?",a="Die Shadowstalkers sind verdeckt operierende Agenten und Assassinen der Verlassenen. Sie suchen begabte, disziplinierte Agenten statt ungeschickter Taschendiebe.",al={"wer sind die shadowstalkers","shadowstalkers verlassene","shadowstalkers"}},{q="Warum ist die Nachricht verschlüsselt?",a="Die Verschlüsselung schützt vertrauliche Nachrichten im verwundbaren Todesend vor unbedachten Blicken. Für Schurken der Verlassenen schützt sie die Kommunikation und trägt zur Sicherheit ihrer Einsätze bei.",al={"warum verschlüsselt","warum eine chiffre"}},{q="Wo findet Ihr Schattenpriester Sarvis?",a="Schattenpriester Sarvis beaufsichtigt die Aufnahme frisch erwachter Verlassener im zentralen Gruft- und Kapellenkomplex von Todesend in Tirisfal.",al={"wo ist sarvis","sarvis standort","schattenpriester sarvis finden"}},{q="Wo befindet sich David Trias?",a="David Trias befindet sich im beschädigten Gasthaus von Todesend, nur ein kurzes Stück den Weg von der zentralen Kapelle hinunter.",al={"wo ist trias","david trias standort","todesend gasthaus lehrer"}}},fp="16,150,15.308.0,19.359.0,44.167.0,19.145.0,46.136.0,29.171.0,39.136.0,29.91.0"}
P.entries["quest:3097"] = {n="Geheiligte Rolle",s="In Todesend ruft Schattenpriester Sarvis neu auferstandene Priester der Verlassenen in die Kapelle. Er schickt jeden Novizen zum Dunklen Kleriker Duesten, um zu lernen, wie die Verlassenen nach dem Tod ihren Glauben ausüben.",h="In Todesend ruft Schattenpriester Sarvis neu auferstandene Priester der Verlassenen in die Kapelle.",kw={"dunkler kleriker duesten","todesend","priester der verlassenen","geheiligte rolle","priesterquest","schattenpriester sarvis","tirisfal"},ang={["class:Priest"]="Als Priester findet Ihr durch das Vertrauen auf Euch selbst, Leiden und Shadow Magic Zugang zum Glauben der Verlassenen statt durch herkömmliche Frömmigkeit.",["race:Undead"]="Als Untoter wisst Ihr, dass die Verlassenen die Bande zu ihren alten menschlichen Glaubensrichtungen gekappt haben und durch eisernen Willen und gegenseitige Abhängigkeit überleben."},sec={{t="Eine Vorladung in Todesend",b="Neu erwachte Untote taumeln aus den Gräbern von Todesend, ihr Geist erschüttert von Seuche, Tod und der Befreiung aus dem Griff des Lichkönigs. Wer im Leben dem Heiligen Licht folgte, kann den Tod nur schwer begreifen. Während unerfahrene Untote am Rand der Siedlung gegen die geistlose Geißel kämpfen, erhält Schattenpriester Sarvis eine Nachricht vom Dunklen Kleriker Duesten. Sie ruft neu auferstandene Priester dazu auf, ihr Umherirren zu beenden und die entweihte Stadtkapelle aufzusuchen."},{t="Glaube neu bestimmt",b="In der Kapelle lehrt der Dunkle Kleriker Duesten einen harten Glauben. Er sagt, das Heilige Licht habe die Verlassenen im Tod verlassen, Ahnengeister seien leere Geschichten und Dämonen kümmerten sich nicht um ihre Not. Die Geistlichen der Verlassenen lehren, dass Willenskraft und das Vertrauen auf sich selbst ihre einzigen Quellen der Erlösung sind. Unter Duestens Anleitung erlernen neu auferstandene Priester göttliche Disziplin und Schatten durch den Glauben an ihr eigenes Überleben, nicht durch Hingabe an ferne Götter."}},faq={{q="Was ist die Geheiligte Rolle?",a="Schattenpriester Sarvis gibt neu auferstandenen Priestern der Verlassenen in Todesend ein versiegeltes Dokument. Es schickt sie zur Priesterausbildung zum Dunklen Kleriker Duesten in der Stadtkapelle.",al={"geheiligte rolle","rolle gegenstand","priesterrolle"}},{q="Wer schickt dem Spieler die Rolle?",a="Der Dunkle Kleriker Duesten versieht die Rolle mit seinem Siegel, und Schattenpriester Sarvis überreicht sie Euch in Todesend.",al={"wer hat die rolle geschickt","duestens rolle","sarvis brief"}},{q="Können Verlassene noch das Heilige Licht wirken?",a="Der Dunkle Kleriker Duesten sagt neuen Priestern, dass das Heilige Licht sie nichts mehr angeht. Priester der Verlassenen wenden sich von der Hingabe an das Licht ab und verlassen sich auf sich selbst und ihre Beherrschung der Schatten.",al={"untote nutzen licht","verlassene heiliges licht","können untote licht wirken"}},{q="Wo befindet sich der Dunkle Kleriker Duesten?",a="Der Dunkle Kleriker Duesten befindet sich in der verfallenen Kirche im Zentrum von Todesend im Westen von Tirisfal, nahe anderen Lehrern der Verlassenen.",al={"duesten finden","duestens standort","wo ist kleriker duesten"}},{q="Warum weist Duesten Ahnen und Dämonen zurück?",a="Duesten will, dass neu erweckte Untote ihre Illusionen ablegen. Er sagt, das Licht gehe sie nichts mehr an, die Geister ihrer Vorfahren seien Märchen und die Geschöpfe des Nether wollten sie nicht. Die Verlassenen haben allein durch ihren Willen überlebt.",al={"duestens rede","märchen","nether will sie nicht"}},{q="Was geschieht nach dem Lesen der Rolle?",a="Ihr lest das Pergament und stellt Euch dem Dunklen Kleriker Duesten in der Kapelle von Todesend vor. Er wird dort Euer Lehrer und bringt Euch Eure ersten Priesterfähigkeiten bei.",al={"geheiligte rolle ziel","rolle abgeben"}}},fp="15,180,23.439.0,15.434.0,28.167.0,35.107.0,40.183.0,37.133.0,46.241.0,38.163.0"}
P.entries["quest:3098"] = {n="Glyphenrolle",s="In Todesend ruft Isabella frisch erwachte Magier der Verlassenen in die Kirchenruine. Ihre versiegelte Rolle fordert sie auf, ihre unberechenbaren arkanen Kräfte zu schulen.",h="In Todesend ruft Isabella frisch erwachte Magier der Verlassenen in die Kirchenruine.",kw={"arkan","todesend","magier der verlassenen","glyphenrolle","isabella","magierlehrer","tirisfal"},ang={["class:Mage"]="Als Magier erhaltet Ihr diese Rolle als Aufforderung, Euch bei Isabella zu melden. Eure Magie hilft Eurem frisch befreiten Volk, zu überleben und sich erneut zu erheben.",["race:Undead"]="Als Untoter nutzt Ihr das Arkane, um Eure geraubte Heimat zurückzuerobern. Für die Verlassenen ist Magie eine Waffe, kein gelehrtes Spiel Dalarans."},sec={{t="Ein Ruf zur Arkanmagie",b="Isabella ruft frisch erwachte Magier der Verlassenen in die Kirchenruine von Todesend. In der Nähe zeigt Ihr beim Kampf gegen die geistlose Geißel eine Begabung für Arkanmagie. Dann fordert Euch eine Rolle mit ihrem arkanen Siegel auf, Euch bei ihr zu melden. Isabella bildet die örtlichen Magier aus und weiß, dass ungeschulte Magie die Verlassenen ebenso gefährden kann wie ihre Feinde."},{t="Magie im Untod",b="In Todesends verfallener Kapelle lehrt Isabella neue Magier der Verlassenen, dass der Untod die Gefahren der Arkanmagie nicht gebannt hat. Ihre Körper haben die Schwächen des Lebens verloren, doch Magie bleibt unberechenbar und verderblich. Die Beherrschung des Arkanen erfordert mehr als nur Studium. Sie kann den Verlassenen helfen, zu überleben, Rache zu nehmen, ihr Schicksal zurückzugewinnen und jene zu vernichten, die ihre zerbrechliche Rückkehr nach Lordaeron bedrohen."}},faq={{q="Was ist die Glyphenrolle?",a="Die Glyphenrolle trägt Isabellas persönliches Siegel und fordert frisch erwachte Magier der Verlassenen auf, sich bei ihr in Todesends Kirchenruine zu melden, um ihre arkanen Studien zu vertiefen.",al={"glyphenrolle quest","was ist diese rolle","todesend rolle"}},{q="Wer schickt Euch die Glyphenrolle?",a="Isabella, die Magierlehrerin in Todesend, schickt Euch die Rolle, nachdem Ihr Euch um die geistlose Geißel in der Nähe gekümmert habt.",al={"wer hat die rolle geschickt","wer hat die glyphenrolle geschrieben","absender der glyphenrolle"}},{q="Wo befindet sich Isabella?",a="Isabella befindet sich in der verfallenen Dorfkirche im Zentrum von Todesend, neben anderen Lehrern, die frisch auferstandene Verlassene anleiten.",al={"wo ist isabella","isabella finden","todesend magierlehrer standort"}},{q="Warum warnt Euch Isabella vor magischer Verderbnis?",a="Isabella warnt Euch, dass Arkanmagie unberechenbar bleibt und die Verlassenen verderben oder verzehren kann. Ihre Beherrschung erfordert Disziplin und Willenskraft.",al={"magische verderbnis untote","arkane verderbnis hintergrundgeschichte","warum ist magie für untote gefährlich"}},{q="Warum ist Arkanmagie für die Verlassenen in Todesend wichtig?",a="Magier der Verlassenen nutzen arkane Macht, um Lordaeron zurückzuerobern und ihre Freiheit gegen die geistlose Geißel, feindselige lebende Sterbliche und den Scharlachroten Kreuzzug zu verteidigen.",al={"warum nutzen verlassene magie","untote magier hintergrundgeschichte"}},{q="Kann jede Klasse der Verlassenen diese Rolle erhalten?",a="Nein. Nur Magier der Verlassenen erhalten die Glyphenrolle, die sie zu ihrer Lehrerin in Todesend ruft.",al={"ist die glyphenrolle nur für magier","können hexenmeister die glyphenrolle erhalten","wer erhält die glyphenrolle"}}},fp="14,147,23.335.0,25.393.0,27.186.0,36.114.0,26.130.0,52.134.0,60.153.0,43.102.0"}
P.entries["quest:3099"] = {n="Besudelte Rolle",s="In Todesend erhalten neu erwachte Hexenmeister der Verlassenen einen Ruf, der Maximillions Namen trägt. Er ruft sie in die zerstörte Siedlung zurück, um Freiheit, Macht und Knechtschaft gegeneinander abzuwägen.",h="In Todesend erhalten neu erwachte Hexenmeister der Verlassenen einen Ruf, der Maximillions Namen trägt.",kw={"todesend","verlassene","maximillion","geißel","sylvanas","besudelte rolle","tirisfal","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister begegnet Ihr Maximillion in Todesend. Er stellt Dämonologie und die Befehlsgewalt über Diener als Weg dar, Herrschaft und Freiheit zu erlangen.",["race:Undead"]="Als Verlassene teilt Ihr eine dunkle Parallele: Euch von der Geißel zu befreien und dämonische Diener für Euer eigenes Überleben zu befehligen."},sec={{t="Ein dunkler Ruf",b="Neu auferstandene Verlassene beseitigen geistlose Überreste der Geißel rund um Todesend, als eine versiegelte Schriftrolle eintrifft. Sie trägt das Zeichen von Maximillion, dem örtlichen Hexenmeisterlehrer. Die Nachricht bittet ihren Empfänger, über Knechtschaft und Freiheit nachzudenken, dann in die zerstörte Siedlung zurückzukehren und mit ihm zu sprechen."},{t="Die Philosophie der Kontrolle",b="Maximillion lehrt, dass die Flucht aus dem geistlosen Griff des Lichkönigs die Sklaverei nicht beendet, wenn ein anderer Herr die Zügel hält. Ein Sklave bleibt ein Sklave, bis er wahre Herrschaft erlangt. Er sagt, die Beherrschung dämonischer Diener sei kein Verrat an Sylvanas. Für Maximillion ist sie das natürliche Ziel des Kampfes der Verlassenen um Selbstbestimmung und Respekt."}},faq={{q="Wer hat die Besudelte Rolle geschickt?",a="Die Schriftrolle trägt Maximillions persönliches Siegel. Er ist der Hexenmeisterlehrer in Todesend und sucht neu erwachte Anwender der dunklen Künste.",al={"wer schickt die besudelte rolle","wer gab mir die besudelte rolle","absender der besudelten rolle"}},{q="Wer ist Maximillion?",a="Maximillion bildet neu auferstandene Verlassene in Todesend aus. Er lehrt sie, dämonische Wesen zu beschwören und zu kontrollieren.",al={"wer ist maximillion","maximillion todesend","hexenmeisterlehrer todesend"}},{q="Was steht auf der Besudelten Rolle?",a="Die Schriftrolle fordert neu erwachte Hexenmeister auf, über Freiheit, Macht und Knechtschaft nachzudenken. Sie drängt sie, Maximillion aufzusuchen, um tiefergehende Unterweisung zu erhalten.",al={"was ist die besudelte rolle","was steht auf der schriftrolle","nachricht der schriftrolle"}},{q="Ist Maximillion ein Verräter an Lady Sylvanas?",a="Maximillion sagt, er sei kein Verräter an Lady Sylvanas. Er glaubt, die Banshee Queen würde seine Sichtweise verstehen, da auch sie nach Freiheit von der Geißel strebte.",al={"ist maximillion ein verräter","verrät maximillion sylvanas","maximillions loyalität"}},{q="Wo kann ich Maximillion finden?",a="Ihr findet Maximillion in Todesend, der zerstörten Siedlung in Tirisfal, wo neu auferstandene Verlassene zum ersten Mal ihren Gräbern entsteigen.",al={"wo ist maximillion zu finden","maximillions standort"}},{q="Welchen Zweck hat diese Quest?",a="Der Ruf fordert neu auferstandene Hexenmeister der Verlassenen auf, ihre Ausbildung bei ihrem örtlichen Mentor in Todesend zu beginnen.",al={"warum hexenmeisterquest besudelte rolle","zweck der besudelten rolle"}}},fp="14,177,14.291.0,25.337.1,28.142.0,19.111.0,38.142.0,42.156.0,29.139.0,34.105.0"}
P.entries["quest:31"] = {n="Wassergestalt",s="In Donnerfels kehrt ein junger Druide der Horde zurück, um unter den Hütern der Natur anerkannt zu werden. Der Druide hat sich in Mondlichtung als würdig erwiesen und den Aspekt des Seelöwen angenommen; nun verleiht ihm die formelle Anerkennung die Wassergestalt.",h="In Donnerfels kehrt ein junger Druide der Horde zurück, um unter den Hütern der Natur anerkannt zu werden.",kw={"wassergestalt","dendrite sternenschauer","druide","mondlichtung","anhänger des seelöwen","seelöwe","donnerfels","turak runentotem"},ang={["class:Druid"]="Als Druide hilft Euch die Wassergestalt, Gewässer mühelos zu durchqueren und Raubtieren in der Tiefe zu entkommen.",["faction:Horde"]="Als Mitglied der Horde teilt Ihr die spirituelle Verbindung der Tauren-Druiden zum Zirkel des Cenarius und wandelt zwischen neutralen Zufluchtsorten und Stammeshauptstädten.",["race:Tauren"]="Als Tauren ehrt Ihr durch die Beherrschung der Meeresbestien Eure Ahnen und stärkt die Rückkehr Eures Volkes zu den druidischen Wegen."},sec={{t="Rückkehr des Seelöwen",b="Dendrite Sternenschauer schickt Euch nach Euren Prüfungen in Mondlichtung zurück nach Mulgore. Der Anhänger des Seelöwen bezeugt Euer Gleichgewicht und Eure Hingabe in den Gewässern Kalimdors. Indem Ihr ihn heimbringt, zeigt Ihr, dass Ihr die uralten Traditionen geehrt habt, die nötig sind, um einen Wasseraspekt anzunehmen."},{t="Zwiesprache mit den Gewässern",b="Auf den Höhen von Donnerfels bringt Ihr den Anhänger zu Turak Runentotem, Eurem Mentor. Er freut sich, dass Ihr Eure Ahnen geehrt und die Natur im Gleichgewicht gehalten habt. Dann lehrt Euch Turak das Geheimnis der Wassergestalt. Ihr könnt unter der Oberfläche von Flüssen und Meeren schwimmen, frei atmen und Euch als Meeresgeschöpf in den Tiefen zurechtfinden."}},faq={{q="Welchen Zweck hat diese Quest?",a="Dieser Ritus vollendet den Übergang eines jungen Druiden der Horde. In Donnerfels legt Ihr den Anhänger des Seelöwen vor und erlernt die Wassergestalt.",al={"warum diese quest machen","wassergestalt zweck","was bewirkt diese quest"}},{q="Wem bringe ich den Anhänger des Seelöwen?",a="Bringt den Anhänger des Seelöwen zu Turak Runentotem, dem Druidenlehrer auf den oberen Anhöhen von Donnerfels in Mulgore.",al={"bei wem abgeben","wo wassergestalt abgeben","turak runentotem standort"}},{q="Wer schickt Euch zurück nach Donnerfels?",a="Dendrite Sternenschauer schickt Euch zurück, nachdem Ihr Eure Wasserprüfungen in Mondlichtung abgeschlossen habt.",al={"wer vergibt wassergestalt quest","dendrite sternenschauer quest"}},{q="Können auch Nichtdruiden diese Quest abschließen?",a="Nein. Nur Druiden können diesen Ritus abschließen und auf ihrem spirituellen und magischen Weg zu Tiergestalten voranschreiten.",al={"nur für druiden","können andere klassen wassergestalt machen"}},{q="Warum hilft ein Nachtelf in Mondlichtung einem Druiden der Horde?",a="Mondlichtung ist eine neutrale Zuflucht unter der Aufsicht des Zirkels des Cenarius. Nachtelfische Mentoren unterweisen Tauren-Druiden in den uralten Cenarion-Künsten und streben ohne politische Feindseligkeit nach Gleichgewicht in der Natur.",al={"warum hilft dendrite der horde","mondlichtung horde allianz","neutralität der druiden"}},{q="Welche Fähigkeit gewährt der Abschluss dieser Quest?",a="Turak Runentotem lehrt Euch die Wassergestalt. In dieser Gestalt schwimmt Ihr schneller und atmet unter Wasser.",al={"welche gestalt bekomme ich","wassergestalt zauber","wassergestalt"}}},fx={["269933c9"]={q="Warum schickt Euch Dendrite Sternenschauer zurück nach Donnerfels?",a="Dendrite Sternenschauer beaufsichtigt Eure Prüfungen in der Mondlichtung im Auftrag vom Zirkel des Cenarius, aber die Mondlichtung ist ein Heiligtum der Lehre und nicht Euer persönliches Zuhause. Nachdem er Eure Ausdauer und Ehrerbietung gegenüber dem Wasser getestet hat, ist Dendrites Pflicht erfüllt. Er schickt Euch zurück zu Eurem örtlichen Ausbilder, Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels, um den Beweis Eurer Riten vorzulegen und den endgültigen Segen zu empfangen, der Euch die Aquatic Form gewährt.",al={"warum zu turak schicken","dendrite sternenschauer motiv","warum zurück nach donnerfels"}}},fp="12,210,22.282.0,25.324.0,34.132.0,46.114.0,36.86.0,35.110.0,53.188.0,46.96.0"}
P.entries["quest:310"] = {n="Bittere Rivalen",s="Marleth Gerstenbräu bittet Euch, in der Brauerei Donnerbräu in Kharanos ein Fass Donnerbier durch das Gebräu ihrer Familie zu ersetzen.",h="Marleth Gerstenbräu bittet Euch, in der Brauerei Donnerbräu in Kharanos ein Fass Donnerbier durch das Gebräu...",kw={"barleybrew scalder","bittere rivalen","dun morogh","kharanos","marleth gerstenbräu","donnerbier","brauerei donnerbräu"},ang={["class:Rogue"]="Als Schurke wisst Ihr, wie man in einen bewachten Keller schleicht, einen Wachposten ablenkt und Schmuggelware austauscht. Hier ist der Preis Bier statt Gold.",["faction:Alliance"]="Als Reisender der Allianz kommt Ihr durch Kharanos, den kulturellen und logistischen Mittelpunkt von Dun Morogh. Örtliche Streitigkeiten im Gasthaus ziehen oft Rekruten mit hinein.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass Braukunst ebenso viel Ansehen genießt wie Schmiedekunst. Eine Fehde um konkurrierende Biere passt zum Schnee von Dun Morogh."},sec={{t="Ein Hauch von Wettbewerb",b="Die Barleybrews neiden den Thunderbrews schon lange den Ruhm ihrer Brauerei. Marleth schätzt deren Bier, doch sie kann nicht ertragen, dass Dun Morogh nur Thunderbrew kennt. Mit dem feurigen Barleybrew Scalder ihrer Familie will sie den örtlichen Geschmack verändern."},{t="Heimlichkeiten im Keller",b="Unter der Brauerei Donnerbräu in Kharanos füllen reifende Bierfässer einen Lagerraum im Keller. Ein Wachmann steht nahe der kostbaren Reserve der Thunderbrews. Lockt ihn fort und tauscht dann heimlich die Fässer aus."}},faq={{q="Wer vergibt die Quest Bittere Rivalen?",a="Marleth Gerstenbräu gibt Euch den Auftrag. Sie will, dass die Braukunst ihrer Familie dem berühmten Bier der Brauerei Donnerbräu Konkurrenz macht.",al={"wer startet bittere rivalen","marleth questgeberin"}},{q="Wo befindet sich der Keller von Thunderbrew?",a="Der Keller liegt unter der Brauerei Donnerbräu in Kharanos. Seine Treppe befindet sich hinter einem Tisch in der Küche.",al={"wo ist der keller von thunderbrew","zugang zum brauereikeller"}},{q="Was ist Barleybrew Scalder?",a="Barleybrew Scalder ist Marleth Gerstenbräus starkes Hausbier. Sie hofft, dass die Gäste in Kharanos ihr Können erkennen, wenn sie es anstelle von Donnerbier kosten.",al={"barleybrew scalder","welches gebräu austauschen"}},{q="Wie kommt Ihr an dem Wachmann vorbei, der die Fässer bewacht?",a="Der Wachmann von Thunderbrew im Keller deutet an, was seine Aufmerksamkeit erregen könnte. Lenkt ihn ab und nutzt dann die Gelegenheit, die Fässer auszutauschen.",al={"kellerwache ablenken","unbewachtes donnerbierfass","wache fass"}},{q="Warum liegen die Barleybrews und die Thunderbrews in Fehde?",a="Die Fehde entspringt dem Stolz der Zwerge auf ihr Handwerk. Die Thunderbrews beherrschen die Schenken von Kharanos, und die Barleybrews wollen beweisen, dass ihre Rezepte genauso gut oder besser sind.",al={"brauerfehde","warum hassen die barleybrews die thunderbrews"}},{q="Welche Quest folgt auf Bittere Rivalen?",a="Nachdem Ihr das Fass Barleybrew Scalder aufgestellt habt, kehrt Ihr zu Marleth zurück und berichtet von Eurem Erfolg.",al={"nächste quest nach bittere rivalen","was kommt nach bittere rivalen"}}},fx={["6a423fcc"]={q="Warum will Marleth Gerstenbräu die Bierfässer austauschen?",a="Marleth Gerstenbräu steckt in einem erbitterten, langjährigen Wettbewerb mit dem Thunderbrew-Clan darüber, wer das beste Bier in ganz Dun Morogh braut. Obwohl sie widerwillig zugibt, dass die Thunderbrews ein ordentliches Getränk herstellen, kann sie ihr Prahlen nicht ausstehen und will beweisen, dass ihr eigener Gerstenbräu-Aufwiegler überlegen ist. Indem sie ihr Fass in den Keller der Brauerei Donnerbräu schmuggelt, hofft sie, dass deren treue Kunden es trinken, merken, wie gut es ist, und die Thunderbrews damit ein wenig herabstufen.",al={"warum fässer tauschen","marleths motiv","warum das bier austauschen"}},["41e8c9ba"]={q="Warum braucht Marleth Gerstenbräu Euch, statt es selbst zu tun?",a="Marleth ist in Kharanos viel zu bekannt, um unbemerkt in den Keller ihres Rivalen zu gelangen. Die Brauerei Donnerbräu behält ihren Keller genau im Auge, und das Auftauchen einer bekannten Angehörigen der Familie Barleybrew würde sofort Alarm auslösen. Als unbekannter Reisender könnt Ihr Euch in die Brauerei schleichen, einen Weg an der Kellerwache vorbei finden und die Fässer vertauschen, ohne den ganzen Plan sofort auffliegen zu lassen.",al={"warum kann marleth es nicht selbst tun","warum ich bitter rivals","warum einen außenstehenden anwerben"}}},fp="13,126,22.243.0,17.190.0,34.129.0,40.109.0,27.156.0,49.134.0,49.172.0,33.94.0"}
P.entries["quest:3100"] = {n="Einfacher Brief",s="In der Abtei von Nordhain werden neue Krieger zur Ausbildung zu Llane Beshere geschickt. Ihr Brief ruft sie dazu auf, den bedrängten Bewohnern des Tals zu helfen.",h="In der Abtei von Nordhain werden neue Krieger zur Ausbildung zu Llane Beshere geschickt.",kw={"wald von elwynn","ritter der silbernen hand","llane beshere","abtei von nordhain","nordhaintal","einfacher brief","kriegerlehrer"},ang={["class:Warrior"]="In der Abtei von Nordhain bildet Llane Beshere Krieger aus. Der Brief ruft neu angekommene Kämpfer dazu auf, ihre kriegerische Ausbildung zu beginnen.",["faction:Alliance"]="Als Rekrut der Allianz seid Ihr aufgerufen, bedrängten Bewohnern außerhalb des Schutzes der Silbernen Hand bei der Abtei von Nordhain zu helfen.",["race:Human"]="Als Mensch erhaltet Ihr in der Abtei von Nordhain Eure erste Anleitung, bevor Ihr in den Wald von Elwynn aufbrecht."},sec={{t="Ein Ruf zu den Waffen",b="Neue Krieger, die im Nordhaintal eintreffen, werden per Brief zu Llane Beshere geschickt, dem Lehrer in der Abtei von Nordhain. Sie sollen ihren Ausbilder aufsuchen und sich mit dem umliegenden Land vertraut machen. Dann können sie sich auf die Anforderungen des Kriegerlebens vorbereiten."},{t="Die Sicherung des Tals",b="Die Ritter der Silbernen Hand bewachen die Abtei von Nordhain, doch jenseits ihres Schutzes geraten die Menschen in Bedrängnis. Llane Beshere erklärt neuen Kriegern, dass die Bewohner des Tals fähige Beschützer brauchen. Er fordert sie auf, ihre Waffen zu meistern und die dort lebenden Menschen zu verteidigen."}},faq={{q="Was ist der Einfache Brief?",a="Krieger, die aus den Koboldlagern zurückkehren, erhalten im Nordhaintal den Einfachen Brief. Er schickt sie zu Llane Beshere, dem örtlichen Lehrer, um ihre kriegerische Ausbildung zu beginnen.",al={"was ist der einfache brief","einfacher brief quest","einstiegsbrief mensch krieger"}},{q="Wer ist Llane Beshere?",a="Llane Beshere bildet in der Abtei von Nordhain Krieger aus. Er lehrt Anfänger den Kampf und heißt Rekruten willkommen, die mit Befehlen oder Empfehlungen zu ihm geschickt werden.",al={"wer ist llane beshere","beshere standort","wo ist der kriegerlehrer in nordhain"}},{q="Wo gebe ich den Einfachen Brief ab?",a="Bringt den Brief zu Llane Beshere in der Abtei von Nordhain im Nordhaintal. Der heilige Orden schützt das Gelände der Abtei.",al={"wo den einfachen brief abgeben","einfachen brief abgeben","llane beshere standort"}},{q="Welche Rolle spielen die Ritter der Silbernen Hand in Nordhain?",a="Die Ritter der Silbernen Hand bewachen das Nordhaintal. Ihr Schutz hält die Abtei und ihr unmittelbares Umfeld vergleichsweise sicher, während Rekruten, Bauern und Geistliche inmitten wachsender örtlicher Spannungen ihrem Alltag nachgehen.",al={"was machen paladine in nordhain","silberne hand abtei von nordhain","paladine elwynn"}},{q="Warum brauchen die Bürger vor Ort Unterstützung?",a="Die Bewohner vor Ort sind mit Übergriffen und Versorgungsengpässen konfrontiert, obwohl die Abtei selbst recht gut verteidigt ist. Llane Beshere fordert Neuankömmlinge auf, das umliegende Land zu erkunden und Bedürftigen mit ihrer Stärke beizustehen.",al={"warum will beshere dass ich den bürgern helfe","nordhain probleme","wer braucht hilfe in nordhain"}},{q="Wann sollte ich nach der Abgabe des Briefes zu Llane Beshere zurückkehren?",a="Llane Beshere ist Tag und Nacht in der Abtei und bildet Krieger aus, wenn sie Kampferfahrung sammeln und fortgeschrittenere Kampffertigkeiten benötigen.",al={"wann zu llane beshere zurückkehren","weitere kriegerausbildung nordhain","beshere ausbildung"}}},fp="13,137,14.248.0,19.252.0,26.169.0,21.142.0,37.118.0,63.206.0,49.199.0,66.132.0"}
P.entries["quest:3101"] = {n="Geweihter Brief",s="In der Abtei von Nordhain ruft der Geweihte Brief neue Initianden des Heiligen Lichts zur Ausbildung. Er schickt jeden Überbringer zu einem Klassenlehrer und erinnert ihn daran, dass sein Verhalten seinen Glauben widerspiegelt.",h="In der Abtei von Nordhain ruft der Geweihte Brief neue Initianden des Heiligen Lichts zur Ausbildung.",kw={"brother sammuel","geweihter brief","wald von elwynn","heiliges licht","nordhain","abtei von nordhain","paladin","lehrer"},ang={["class:Paladin"]="Als Paladin führt Ihr das Heilige Licht und verkörpert seine Tugenden. In Nordhain und darüber hinaus sehen Eure Verbündeten in Euch ein Leuchtfeuer der Hoffnung.",["faction:Alliance"]="Als Vertreter des Heiligen Lichts in der Allianz wird von Euch erwartet, ehrenhaft zu handeln und die moralische Integrität sowie die Verteidigung der Allianz zu wahren.",["race:Human"]="Als Mensch, der seinen Dienst in der Abtei von Nordhain beginnt, sollt Ihr in einem von jüngsten Prüfungen geplagten Königreich als ehrenhaftes Symbol wirken."},sec={{t="Eine heilige Berufung",b="Im Nordhaintal beginnt mit dem Geweihten Brief der Weg eines Initianden im Heiligen Licht. Er ruft Neuankömmlinge dazu auf, ihren Lehrer in der Abtei von Nordhain aufzusuchen. Dort können sie ihre Unterweisung förmlich beginnen und ihre Pflichten im Königreich Sturmwind aufnehmen."},{t="Das Licht tragen",b="Der Brief erinnert jeden Initianden an das Gewicht seiner Berufung. Wer das Heilige Licht kanalisiert, strahlt vor aller Augen, als Symbol der Hoffnung für Verbündete und als klares Ziel für Widersacher. Sein Lehrer vermittelt ihm, dass solche Macht Disziplin verlangt. Andere werden den Glauben an seinem Verhalten messen."},{t="Führung und Disziplin",b="Der Brief begründet ein dauerhaftes Band zwischen Schüler und Mentor. Während der Initiand sich gegen Bedrohungen rund um Nordhain bewährt, wird von ihm erwartet, häufig auf das Gelände der Abtei zurückzukehren. Dort führt ihn sein Lehrer zu einem tieferen Verständnis des Kampfes und der göttlichen Gnade."}},faq={{q="Was ist der Geweihte Brief?",a="Der Geweihte Brief ruft einen Initianden des Heiligen Lichts im Nordhaintal dazu auf, seine Ausbildung zu beginnen. Er weist den Überbringer zu einem Klassenlehrer in der Abtei von Nordhain und erinnert ihn an seine heiligen Pflichten.",al={"was ist der geweihte brief","geweihter brief quest"}},{q="Woher stammt der Geweihte Brief?",a="Nachdem ein neuer Paladin aus den Koboldlagern zurückkehrt, überreicht ihm jemand in der Abtei von Nordhain den Brief. Mit dem Siegel von Brother Sammuel versehen, fordert er den Paladin auf, ihn aufzusuchen.",al={"wer gibt den geweihten brief","wer schickt den geweihten brief"}},{q="Wer empfängt den Geweihten Brief?",a="Brother Sammuel, der Paladinlehrer nahe dem Eingang der Abtei von Nordhain im Wald von Elwynn, empfängt den Brief.",al={"wer gibt den geweihten brief ab","wer liest den geweihten brief"}},{q="Welche Rolle spielt der Lehrer nach dem Lesen des Briefes?",a="Der Lehrer unterweist den Initianden in den Wegen des Heiligen Lichts. Er lehrt Kampftechniken, schützende Segen und heilige Zauber, während der Initiand im Tal praktische Kampferfahrung sammelt.",al={"was lehrt der lehrer","warum beim lehrer trainieren"}},{q="Warum erwähnt der Brief die Rolle als Symbol?",a="Wer das Heilige Licht kanalisiert, ist ein sichtbares Vorbild des Glaubens und der Tugend. Freund und Feind erkennen seine Macht gleichermaßen, daher fällt das Verhalten dieser Vorbilder auf den Glauben selbst zurück.",al={"warum bin ich ein symbol","heiliges licht symbol"}},{q="Wo findet diese Ausbildung statt?",a="Die Abtei von Nordhain liegt im friedlichen nördlichen Tal des Waldes von Elwynn. Sie ist eine Zuflucht des Glaubens und der wichtigste Ort zur Anwerbung von Verteidigern des Königreichs Sturmwind.",al={"wo ist die abtei von nordhain","wohin den brief bringen"}}},fp="18,192,16.264.0,18.279.0,23.275.0,31.192.0,44.181.0,36.113.0,57.198.0,43.167.0,36.171.0"}
P.entries["quest:3102"] = {n="Verschlüsselter Brief",s="In der Abtei von Nordhain ruft Jorik Kerridan vielversprechende Schurken zu einem geheimen Treffen. Sein Brief weist ihnen den Weg zu einem ruhigen Stall und zu Rat für die bevorstehenden Gefahren.",h="In der Abtei von Nordhain ruft Jorik Kerridan vielversprechende Schurken zu einem geheimen Treffen.",kw={"bruderschaft der defias","verschlüsselter brief","jorik kerridan","abtei von nordhain","nordhaintal","schurkenlehrer","si:7"},ang={["class:Rogue"]="Als Schurke trefft Ihr Jorik Kerridan und hört seinen Rat zum Umgang mit dem SI:7 und der Bruderschaft der Defias, während Ihr Eure Unabhängigkeit bewahrt.",["faction:Alliance"]="Selbst innerhalb der Abtei von Nordhain werben Sturmwinds Schattenagenten vielversprechende Agenten an und bilden sie für die bevorstehenden Konflikte aus."},sec={{t="Eine diskrete Vorladung",b="Die Abtei von Nordhain wirkt friedlich, doch innerhalb ihrer Mauern werden Talente für verdeckte Aufgaben angeworben. Nachdem sie sich um die Kobolde gekümmert haben, erhalten vielversprechende Neulinge einen Brief mit Jorik Kerridans Siegel. Er ist diskret adressiert, abseits der Priester und Paladine. Der Überbringer wird zu einem abgeschiedenen Treffen in den Ställen hinter der Abtei geschickt."},{t="Schatten in Nordhain",b="Jorik Kerridan hält sich in den Ställen auf, weil sie ruhig sind und wenig Aufmerksamkeit erregen. Wenn Neuankömmlinge ungesehen eintreffen, spricht er offen über die weite Welt. Sturmwinds SI:7 und die Bruderschaft der Defias suchen beide nach Agenten, die sich unbemerkt bewegen können. Jorik drängt jeden Neuling, seine Freiheit zu bewahren und sich mächtigen Gruppen zu widersetzen, die ihn herumschubsen wollen. Ein kluger Schurke hält die Trümpfe in der Hand."}},faq={{q="Wer hat den Verschlüsselten Brief geschickt?",a="Jorik Kerridan hat den Brief geschickt, der seine persönlichen Insignien trägt. Vielversprechende Neulinge erhalten ihn, nachdem sie nahe gelegene Koboldlager ausgekundschaftet haben.",al={"wer schickte den verschlüsselten brief","wer gab mir den verschlüsselten brief","wer schrieb den verschlüsselten brief"}},{q="Wo befindet sich Jorik Kerridan?",a="Jorik Kerridan hält sich im ruhigen Stall hinter der Abtei von Nordhain auf. Er bleibt außer Sicht, während er seiner verdeckten Arbeit nachgeht.",al={"wo ist jorik","wo jorik kerridan finden","joriks aufenthaltsort"}},{q="Welchen Zweck hat der Verschlüsselte Brief?",a="Der Brief lädt aufstrebende Schurken diskret zu einem Treffen mit ihrem örtlichen Lehrer ein. Seine verschlüsselten Worte schützen Ausbildungsangelegenheiten vor neugierigen Blicken im Umfeld der Abtei.",al={"warum verschlüsselter brief","wozu dient der verschlüsselte brief","warum ist der brief verschlüsselt"}},{q="Welche Organisationen wollen Schurken anwerben?",a="Jorik Kerridan sagt, dass viele Fraktionen fähige Schurken suchen, darunter Sturmwinds Geheimdienst SI:7 und die Bruderschaft der Defias. Die Defias suchen Spione innerhalb Sturmwinds.",al={"wer sucht schurken","an schurken interessierte fraktionen","wer begehrt schurkenfähigkeiten"}},{q="Welchen Rat gibt Jorik Kerridan?",a="Jorik legt Euch nahe, unabhängig zu bleiben und Euch nicht zu Arbeit gegen Euren Willen drängen zu lassen. Schurken halten die Trümpfe in der Hand, bevor das Spiel vorbei ist.",al={"joriks rat","was sagt jorik","schurkenrat von jorik"}},{q="Warum bleibt Jorik Kerridan im Stall?",a="Jorik Kerridan bleibt im ruhigen Stall hinter der Abtei von Nordhain, weil dieser wenig Aufmerksamkeit erregt. Dort können sich Lehrer und Agenten treffen, ohne dass die Geistlichen und Wachen der Abtei es bemerken.",al={"warum in den ställen verstecken","warum ist jorik hinter der abtei","warum ist es in den ställen ruhig"}}},fp="16,163,18.319.0,21.362.0,30.131.0,32.121.0,44.149.0,50.163.0,37.142.0,43.191.0"}
P.entries["quest:3103"] = {n="Geheiligter Brief",s="In Nordhain überreicht Marschall McBride vielversprechenden jungen Priestern einen Brief von Priesterin Anetta. Er ruft sie dazu auf, ihre formelle Ausbildung im Heiligen Licht in der Abtei von Nordhain zu beginnen, während noch immer Unheil über dem Reich liegt.",h="In Nordhain überreicht Marschall McBride vielversprechenden jungen Priestern einen Brief von Priesterin...",kw={"elwynn","geheiligter brief","heiliges licht","marschall mcbride","abtei von nordhain","priester","priesterin anetta"},ang={["class:Priest"]="Als Priester beginnt Ihr unter Priesterin Anetta Euer formelles Studium des Heiligen Lichts. Eure Magie bringt die Pflicht mit sich, eine zerrüttete Welt zu heilen.",["race:Human"]="Als Mensch findet Ihr in der Abtei von Nordhain einen Zufluchtsort des Glaubens und der Genesung für das Königreich Sturmwind. Sie bewahrt ihre Traditionen inmitten der Unruhen rund um Elwynn."},sec={{t="Ein Ruf zum Priesteramt",b="Nachdem sie sich gegen die Koboldlager rund um Nordhain bewährt haben, erhalten angehende Priester einen von Priesterin Anetta versiegelten Brief. Marschall McBride überbringt ihn als Einladung, das Heilige Licht in den stillen Hallen der Abtei zu studieren."},{t="Eine Welt in Not",b="Wenn Ihr den Brief überbringt, erzählt Euch Priesterin Anetta, dass das Reich weiterhin von Unheil geplagt wird. Die anhaltenden Bedrohungen durch die Brennende Legion werfen noch immer Schatten über Azeroth, und die Kontinente tragen frische Wunden und sind voller Unruhe. Für Anetta bedeutet der Weg zum Priester mehr als nur das Studium. Er bringt die Pflicht mit sich, einer leidenden Welt Heilung und Trost zu spenden."}},faq={{q="Was ist der Geheiligte Brief?",a="Es ist ein versiegelter Brief mit dem Wappen von Priesterin Anetta, den Marschall McBride neu eingetroffenen menschlichen Priestern im Nordhaintal überreicht. Er weist den Novizen an, seine formelle Ausbildung in der Abtei von Nordhain fortzusetzen.",al={"geheiligter brief","einführungsquest priester nordhain","anetta brief"}},{q="Wer schickt den Geheiligten Brief?",a="Priesterin Anetta, die Priesterlehrerin in der Abtei von Nordhain, schreibt und versiegelt den Brief. Sie bittet Marschall McBride, ihn zu überreichen, sobald der Novize von der Erkundung des Koboldbefalls zurückkehrt.",al={"wer schrieb den geheiligten brief","wer schickte den brief"}},{q="Warum ruft Priesterin Anetta neue Priester zu sich?",a="Anetta erkennt Eure Berufung zum Heiligen Licht und möchte Eure Ausbildung begleiten. Da Gefahren wie die Überreste der Brennenden Legion noch immer die Welt bedrohen, werden ihrer Ansicht nach disziplinierte Heiler und Wegweiser dringend gebraucht.",al={"warum ruft anetta nach mir","zweck des briefes"}},{q="Wo ist Priesterin Anetta zu finden?",a="Priesterin Anetta lebt in der Haupthalle der Abtei von Nordhain. Dort lehrt sie menschliche Priester ihre ersten Gebete und Rituale.",al={"wo ist anetta","priesterin anetta standort"}},{q="Was geschieht, nachdem Ihr Priesterin Anetta den Brief vorgelegt habt?",a="Nachdem Ihr den Brief gelesen und Anetta begrüßt habt, nimmt sie Euch als ihren Schüler an. Sie vermittelt Euch grundlegende Weisheiten und lädt Euch ein, für weitere Ausbildung zurückzukehren, sobald Ihr mehr Erfahrung gesammelt habt.",al={"nächste quest nach geheiligter brief","was folgt auf den geheiligten brief"}},{q="Warum wird die Brennende Legion in Nordhain erwähnt?",a="Obwohl der Dritte Krieg vorüber ist, suchen dämonische Überreste der Brennenden Legion Azeroth noch immer heim. Anetta erwähnt diese weitreichende Bedrohung, um zu zeigen, welche Gefahren jeden erwarten, der das Tal verlässt.",al={"brennende legion nordhain","warum spricht anetta über dämonen"}}},fp="15,209,22.225.0,15.307.0,28.212.0,30.191.0,45.214.0,36.128.0,61.169.0,50.184.0"}
P.entries["quest:3104"] = {n="Glyphenbrief",s="Ein Ruf von Marschall McBride erreicht angehende menschliche Magier im Nordhaintal. Khelden Bremen ruft vielversprechende Zauberwirker zur Abtei von Nordhain, um ihre arkane Unterweisung zu beginnen.",h="Ein Ruf von Marschall McBride erreicht angehende menschliche Magier im Nordhaintal.",kw={"arkan","wald von elwynn","glyphenbrief","khelden bremen","magier","marschall mcbride","abtei von nordhain"},ang={["class:Mage"]="Als Magier beginnt Ihr unter Khelden Bremen Eure anerkannte Lehrzeit in den arkanen Künsten Sturmwinds.",["race:Human"]="Als Mensch tragt Ihr das Erbe der arkanen Magie Nordhains weiter. Es reicht bis zu den ersten menschlichen Arkanisten Dalarans und den Kirin Tor zurück und besteht im Königreich Sturmwind fort."},sec={{t="Ein Ruf zu den arkanen Künsten",b="Marschall McBride überreicht den runenverzierten Brief einem angehenden Lehrling, der sein Können bewiesen hat, indem er ihm gegen das örtliche Ungeziefer half. Khelden Bremen, der Magierlehrer in Nordhain, hat ihn geschrieben. Er beobachtet die neuen Rekruten, die an der Abtei eintreffen, und sucht nach magischer Disziplin und Begabung."},{t="Die Bürde der Zauberkunst",b="Die Abtei von Nordhain bietet dem Heiligen Licht seit Langem Zuflucht. Doch die Gefahren für Sturmwind verlangen nach Vertretern jeder Disziplin. Der Brief führt Euch nach oben zu Khelden Bremen, der nicht leichtfertig Lob verteilt. Er warnt, dass die Beherrschung arkaner Macht bedeutet, sich über die Grenzen der Natur hinwegzusetzen. Solche Macht weckt bei gewöhnlichen Leuten großen Respekt und tiefe Furcht."}},faq={{q="Wer überreicht den Glyphenbrief?",a="Marschall McBride überreicht den Brief neu eingetroffenen Magiern vor der Abtei von Nordhain, nachdem sie geholfen haben, das Koboldengeziefer in der Nähe zu beseitigen.",al={"wer gibt den glyphenbrief","glyphenbrief questgeber"}},{q="Wer hat den Glyphenbrief geschrieben?",a="Khelden Bremen, der Magierlehrer in den oberen Gemächern der Abtei von Nordhain, hat den Brief geschrieben und versiegelt.",al={"verfasser des glyphenbriefs","wer hat den glyphenbrief geschickt"}},{q="Wo finde ich Khelden Bremen?",a="Betretet die Abtei von Nordhain hinter Marschall McBride. Nehmt den linken Gang und steigt dann die Treppe hinauf. Khelden wartet in den hinteren Gemächern, um Euch zu unterrichten.",al={"khelden bremen standort","wo ist khelden"}},{q="Warum befindet sich der Magierlehrer in einer Abtei?",a="Die Abtei von Nordhain ist ein heiliger Zufluchtsort, doch Sturmwind nutzt das Tal, um Verteidiger in jeder Disziplin auszubilden. Arkane Lehrmeister arbeiten dort Seite an Seite mit Klerikern und Marschällen.",al={"warum sind magier in der abtei von nordhain","magierlehrer in heiliger abtei"}},{q="Was geschieht nach der Abgabe des Briefes?",a="Khelden Bremen nimmt Euch als seinen Schüler an. Er begrüßt Eure Entschlossenheit, trotz ihrer Gefahren arkane Macht zu wirken, und bietet Euch direkten Zugang zur Ausbildung in grundlegenden Zaubern.",al={"was kommt nach dem glyphenbrief","nächste quest nach dem glyphenbrief"}},{q="Warum warnt Khelden davor, dass Magier gefürchtet werden?",a="Arkane Magie kann die Wirklichkeit beugen und ist unberechenbar. Khelden warnt, dass das Streben nach höchstem Wissen Grenzen überschreitet, die gewöhnliche Leute zutiefst beunruhigen.",al={"warum werden magier gefürchtet","khelden bremen dialog"}}},fp="14,175,23.276.0,22.332.0,32.124.0,29.99.0,31.137.0,44.164.0,41.157.0,48.155.0"}
P.entries["quest:3105"] = {n="Besudelter Brief",s="In Nordhain führt der Besudelte Brief junge menschliche Hexenmeister abseits der Abteiwachen zu den Teufelskünsten. Drusilla La Salle übergibt ihn Marschall McBride, der ihn ihren Rekruten überbringt.",h="In Nordhain führt der Besudelte Brief junge menschliche Hexenmeister abseits der Abteiwachen zu den...",kw={"verderbnis","drusilla la salle","wald von elwynn","marschall mcbride","abtei von nordhain","besudelter brief","wirbelnder nether","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister erhaltet Ihr in Nordhain eine formelle Unterweisung, während Ihr Euch dem Urteil der Wachen entzieht. Dort lernt Ihr, gefährliche Nethermagie zu beherrschen.",["race:Human"]="Als Mensch lebt Ihr in einer Kultur, die das Heilige Licht und die disziplinierte Arkankunst der Kirin Tor verehrt. Hexenmeister üben ihre Beschwörungen im Stillen am Rand von Siedlungen wie Nordhain aus."},sec={{t="Eine diskrete Vorladung",b="Nachdem sie sich gegen die Kobolde bewährt haben, erhalten angehende Hexenmeister einen Brief von Marschall McBride. Priester und Paladine lernen offen in der Abtei von Nordhain, doch Hexenmeister müssen sich auf stilleren Pfaden bewegen. Drusilla La Salles Insignien kennzeichnen den Brief. Er weist jeden jungen Zauberwirker an, ihren abgelegenen Posten außerhalb der Hauptmauern der Abtei aufzusuchen, bevor er andere Pflichten übernimmt."},{t="Versuchung und Ehrgeiz",b="Drusilla warnt, dass die Wachen von Sturmwind Hexenmeister genau beobachten. Sie nennt sie ‚armselige Gewöhnliche‘. Macht aus dem Wirbelnden Nether zu schöpfen und mit Dämonen zu verkehren birgt jeweils die Gefahr der Verderbnis. Daher mahnt sie beim Umgang mit diesen dunklen Energien zu Geduld, Umsicht und unerschütterlicher Selbstbeherrschung. Vorsicht, sagt sie, darf den Ehrgeiz eines Hexenmeisters nicht ersticken."}},faq={{q="Wer schickt den Besudelten Brief?",a="Drusilla La Salle schreibt und versiegelt den Brief an ihrem Posten unmittelbar außerhalb der Abtei von Nordhain. Sie bittet Marschall McBride, ihn Euch zu übergeben, wenn Ihr von der Säuberung der nahen Koboldlager zurückkehrt.",al={"wer schrieb den besudelten brief","verfasser des besudelten briefs","wer übergibt den besudelten brief"}},{q="Warum überbringt Marschall McBride einen Hexenmeisterbrief?",a="Marschall McBride überbringt vielversprechenden Rekruten im Tal Nachrichten. Er erkennt Drusillas Siegel und sagt, ihr Brief habe Vorrang. Sein Hauptaugenmerk gilt weiterhin der Verteidigung und Verwaltung von Nordhain, nicht der Überwachung der magischen Praktiken seiner Verteidiger.",al={"warum hat mcbride ihn","weiß mcbride was der brief ist","mcbride hexenmeisterbrief"}},{q="Wo finde ich Drusilla La Salle?",a="Drusilla La Salle wartet vor dem Haupteingang der Abtei von Nordhain, nahe den Außenmauern und Zelten. Sie hält sich von den Klerikern im Inneren fern.",al={"drusillas standort","wo ist drusilla la salle","drusilla finden"}},{q="Warum werden Hexenmeister in der Abtei von Nordhain geduldet?",a="Hexenmeister begegnen im Gebiet der Allianz großem Misstrauen und halten sich daher bedeckt. Drusilla bildet Rekruten in Nordhain im Freien abseits des Heiligtums aus, um eine direkte Konfrontation mit den Klerikern und Paladinen des Holy Order of Northshire zu vermeiden.",al={"hexenmeister in nordhain","ist teufelsmagie in nordhain erlaubt","warum werden hexenmeister geduldet"}},{q="Welche Lehre vermittelt Drusilla, wenn sie den Brief erhält?",a="Drusilla warnt, dass das Schöpfen von Macht aus dem Wirbelnden Nether ohne Disziplin die Gefahr der Verderbnis birgt. Sie mahnt zu Selbstbeherrschung und Umsicht, sagt aber, die Furcht vor Verderbnis dürfe den Ehrgeiz eines Hexenmeisters nicht erdrücken.",al={"drusillas rat","was sagt drusilla","lehre aus dem besudelten brief"}},{q="Was folgt auf die Übergabe des Besudelten Briefs?",a="Das Gespräch mit Drusilla schließt die Vorladung ab und macht sie zu Eurer Lehrerin. Sie lädt Euch ein, zurückzukehren, wenn Ihr mächtiger werdet und mehr über die Wege der Hexenmeister lernt.",al={"nächste quest nach dem besudelten brief","folgequest des besudelten briefs"}}},fp="14,186,18.364.0,23.336.0,29.182.0,50.249.0,35.137.0,45.240.0,58.189.0,47.162.0"}
P.entries["quest:3106"] = {n="Einfache Rune",s="In Ambossar überbringt Sten Starkarm neuen Zwergenkriegern eine Vorladung von Thran Khorman. Die Rune ruft sie von den verschneiten Pfaden des Coldridgetals zur Ausbildung.",h="In Ambossar überbringt Sten Starkarm neuen Zwergenkriegern eine Vorladung von Thran Khorman.",kw={"ambossar","das coldridgetal","dun morogh","eisenschmiede","einfache rune","sten starkarm","thran khorman","troggs","krieger"},ang={["class:Warrior"]="Als Krieger markiert die Rune Euren formellen Eintritt in die kriegerische Disziplin und schickt Euch zu Thran Khorman in Ambossar.",["faction:Alliance"]="Als Mitglied der Allianz werdet Ihr im Coldridgetal ausgebildet, wo Gebirgstruppen die südlichen Zugänge nach Khaz Modan verteidigen.",["race:Dwarf"]="Als Zwerg könnt Ihr von Thran Khorman die althergebrachte Zähigkeit lernen. Er lehrt Rekruten, an ihrer Kultur aus Stahl und Eisen festzuhalten, während sich die Welt wandelt.",["race:Gnome"]="Als Gnom, den Troggs und Strahlung aus Gnomeregan vertrieben haben, erlernt Ihr im Coldridgetal an der Seite zwergischer Lehrmeister den Frontkampf, um im Exil zu überleben."},sec={{t="Ein Ruf zum Amboss",b="Erfahrene Kundschafter beobachten Rekruten beim Beseitigen von Ungeziefer im Coldridgetal und halten nach vielversprechenden Kämpfern Ausschau. Sten bringt einen beschrifteten Stein von Thran Khorman. Seine einfache Rune ruft sie von den verschneiten Pfaden in die warme Schmiedehalle von Ambossar, wo sie sich dem Kriegerhandwerk verschreiben können."},{t="Dun Morogh im Wandel",b="Thran spricht offen über die Schwierigkeiten in Dun Morogh. Gnome, die durch die Explosionen vertrieben wurden, die Gnomeregan zerstörten, suchen Zuflucht, während manche Zwerge fremde arkane Künste erlernen oder dem menschlichen Glauben an das Heilige Licht folgen. Troggs kratzen an den Grenzen des Gebirges, nachdem sie tief unter der Erde aufgestört wurden. Thran glaubt, dass strenge kriegerische Disziplin nötig ist, um diesen Bedrohungen standzuhalten."}},faq={{q="Was ist die Einfache Rune?",a="Sten Starkarm trägt im Auftrag von Thran Khorman eine beschriftete Schiefertafel bei sich. Sie fordert neue Krieger auf, sich zur Ausbildung im Inneren zu melden.",al={"einfache rune gegenstand","was bewirkt die rune","einfache rune hintergrund"}},{q="Wer ist Thran Khorman?",a="Thran Khorman bildet im Inneren von Ambossar im Coldridgetal Krieger aus. Er lehrt junge zwergische und gnomische Krieger Nahkampf, Disziplin und zwergische Zähigkeit.",al={"wer ist thran","thran khorman hintergrund","kriegerlehrer coldridgetal"}},{q="Warum leben Gnome in Dun Morogh und Eisenschmiede?",a="Gnome flohen aus Gnomeregan, nachdem sie in einem verzweifelten Versuch, eine Trogginvasion abzuwehren, verheerende Strahlungssprengsätze gezündet hatten. Die Überlebenden suchten bei ihren zwergischen Verbündeten in Eisenschmiede Zuflucht.",al={"warum sind gnome hier","gnome in eisenschmiede","flüchtlinge aus gnomeregan"}},{q="Warum erwähnt Thran die Troggs?",a="Troggs sind primitive, bösartige Kreaturen, die tief unter der Erde aufgestört wurden. Sie sind vor Kurzem in die oberflächennahen Höhlen im Coldridgetal und in Dun Morogh vorgedrungen und bedrohen Siedlungen und Handelswege. Die Verteidiger von Ambossar müssen bewaffnet und wachsam bleiben.",al={"bedrohung durch troggs","warum sind troggs hier","troggs im coldridgetal"}},{q="Was meint Thran damit, dass Zwerge das Heilige Licht verehren?",a="Einige Zwerge wandten sich durch enge Verbindungen zu Menschenkönigreichen wie Lordaeron und Sturmwind dem Heiligen Licht zu. Sie bilden inzwischen ihre eigenen Paladine und Priester aus.",al={"zwerge und heiliges licht","zwergenpaladine hintergrund","zwergenpriester"}},{q="Wohin bringe ich die Einfache Rune?",a="Bringt die Rune zu Thran Khorman auf dem Übungsplatz in Ambossars großer Bunkerhalle, gleich den Pfad im Coldridgetal hinauf.",al={"wo einfache rune abgeben","wo ist thran khorman","thran finden"}}},fp="11,159,22.283.0,21.368.0,24.123.0,21.160.0,50.192.0,30.242.0,62.154.0,32.129.0"}
P.entries["quest:3107"] = {n="Geweihte Rune",s="In Ambossar ruft Bromos Grummler angehende Zwergenpaladine dazu auf, sich den Rittern der Silbernen Hand anzuschließen. Sten Starkarm ruft sie dorthin.",h="In Ambossar ruft Bromos Grummler angehende Zwergenpaladine dazu auf, sich den Rittern der Silbernen Hand...",kw={"ambossar","bromos grummler","das coldridgetal","geweihte rune","heiliges licht","paladinlehrer","silberne hand","sten starkarm"},ang={["class:Paladin"]="Als Paladin markiert diese Rune Euren ersten förmlichen Schritt in die Reihen der Ritter der Silbernen Hand. Eure Pflicht ist es, das Licht zur Verteidigung von Eisenschmiede zu kanalisieren.",["race:Dwarf"]="Als Zwerg vereint Ihr traditionelle zwergische Zähigkeit mit der von Menschen gelehrten Theologie. Zwergenpaladine bringen unerschütterliche Entschlossenheit in die Lehren des Heiligen Lichts ein."},sec={{t="Ein Ruf nach Ambossar",b="Eure Rune markiert den Beginn einer förmlichen Aufnahme, bei der rohes Potenzial auf Disziplin treffen muss. Rund um das Coldridgetal halten die örtlichen Anführer nach jenen Ausschau, die eine Gabe für göttliche Kampfkunst besitzen. Bromos Grummler wartet in Ambossar, um neue Initianden anzuleiten."},{t="Zwerge und das Heilige Licht",b="Die Ritter der Silbernen Hand entstanden unter den Menschen von Lordaeron, doch die Zwerge von Eisenschmiede nahmen das Heilige Licht mit glühender Hingabe an. Bromos heißt Euch in der Bruderschaft willkommen und erinnert Euch daran, dass Zwergenpaladine die feierliche Pflicht teilen, Azeroth zu beschützen. Der Orden gründet auf Aufopferung, Tradition und kriegerischer Tugend und fordert Rekruten auf, Hammer und Glauben gleichermaßen zu ergreifen."}},faq={{q="Was ist die Geweihte Rune?",a="Die Geweihte Rune ist ein beschriftetes Zeichen, das Sten Starkarm angehenden Zwergenpaladinen im Coldridgetal überreicht. Sie verweist Euch zur förmlichen Ausbildung an Bromos Grummler in Ambossar.",al={"geweihte rune gegenstand","was bewirkt die rune","paladin rune coldridge"}},{q="Wer ist Bromos Grummler?",a="Bromos Grummler ist der Paladinlehrer in Ambossar. Er unterweist neue zwergische Mitglieder der Ritter der Silbernen Hand und bereitet sie auf Gefahren vor, die Dun Morogh bedrohen.",al={"wer ist bromos","paladinlehrer ambossar","bromos grummler hintergrund"}},{q="Warum gehören Zwerge den Rittern der Silbernen Hand an?",a="Während des Zweiten Krieges und in der Zeit danach brachten menschliche Priester und Paladine den Zwergen von Eisenschmiede die Lehren des Heiligen Lichts. Zwerge achten die kriegerische Disziplin des Ordens und seine Bereitschaft, für die Verteidigung Azeroths Opfer zu bringen.",al={"zwergenpaladin hintergrund","warum haben zwerge paladine","silberne hand zwerge"}},{q="Wer gibt Euch die Geweihte Rune?",a="Sten Starkarm gibt Euch die Rune vor Ambossar, nachdem Ihr ihm bei örtlichen Aufgaben geholfen habt. Er sagt, Bromos Grummler habe ihn gebeten, sie zu überbringen.",al={"wo gibt es die rune","wer überreicht die rune"}},{q="Wo befindet sich Bromos Grummler?",a="Bromos Grummler befindet sich neben den anderen Klassenlehrern in der großen Halle von Ambossar im Coldridgetal.",al={"bromos aufenthaltsort","wo ist bromos","bromos grummler finden"}},{q="Was geschieht, nachdem Ihr Bromos die Rune vorgelegt habt?",a="Nachdem Ihr die Rune vorgelegt habt, bestätigt Bromos Eure Aufnahme in die Silberne Hand und bietet Euch die erste förmliche Ausbildung im Kampf und im Heiligen an. Dann schickt er Euch zurück nach Dun Morogh.",al={"what comes next","nach geweihte rune"}}},fp="16,135,21.242.0,26.390.0,29.178.0,23.176.0,55.228.0,35.135.0,33.103.0,49.179.0"}
P.entries["quest:3108"] = {n="Geätzte Rune",s="Im Coldridgetal erhalten unerfahrene Zwergenjäger eine gemeißelte Aufforderung von Sten Starkarm. Sie schickt sie zu Thorgas Grimson in Ambossar, um die Jagd zu erlernen.",h="Im Coldridgetal erhalten unerfahrene Zwergenjäger eine gemeißelte Aufforderung von Sten Starkarm.",kw={"ambossar","das coldridgetal","dun morogh","zwerg","geätzte rune","jäger","sten starkarm","thorgas grimson"},ang={["class:Hunter"]="Für Euch als Jäger beginnt mit der Geätzten Rune Eure Reise in Dun Morogh, und Ihr lernt Thorgas Grimson sowie die zwergischen Traditionen des Fährtenlesens, der Waffenpflege und des Überlebens in der Wildnis kennen.",["race:Dwarf"]="Als Zwerg erkennt Ihr an den gemeißelten Runen für formelle Botschaften, welchen Wert Steinmetzkunst, Tradition und beständiges Handwerk haben."},sec={{t="Eine Aufforderung in Stein",b="Während Ihr Sten Starkarm helft, den Bedrohungen rund um das Coldridgetal zu begegnen, gibt er Euch die Geätzte Rune. Zwergische Lehrmeister bevorzugen gemeißelte Runen für formelle Botschaften statt mündlicher Befehle oder einfachen Pergaments. Der Stein fordert Euch auf, Eure ersten Leistungen zu überdenken und Euch dann in Ambossar zu melden, um eingehender in der Jagd unterwiesen zu werden."},{t="Traditionen der Jäger Dun Moroghs",b="In Ambossar markiert die Geätzte Rune den Beginn der geregelten Ausbildung eines Jägers. Thorgas Grimson lehrt, dass Bergsteigen und Überleben in Khaz Modan Respekt vor dem rauen Land verlangen. Ihr lernt, Spuren in eisigen Schneewehen zu lesen, Eure Waffen und Munition zu pflegen und die wilden Tiere zu verstehen, die durch die Felsen streifen. Die Rune markiert Euren ersten Schritt vom einsamen Wanderer mit einem Gewehr zum Lehrling unter den erfahrenen Pfadfindern von Ambossar."}},faq={{q="Was ist die Geätzte Rune?",a="Die Geätzte Rune ist eine beschriftete Steintafel, die unerfahrene Jäger im Coldridgetal auffordert, eine geregelte Ausbildung bei Thorgas Grimson in Ambossar zu beginnen.",al={"was ist die geätzte rune","geätzte rune gegenstand","bedeutung der rune"}},{q="Wer schickt die Geätzte Rune?",a="Thorgas Grimson schickt die Geätzte Rune. Sten Starkarm, ein Gebirgsjäger, überreicht sie Euch, nachdem Ihr außerhalb von Ambossar Euer grundlegendes Können bewiesen habt.",al={"wer hat die geätzte rune übergeben","absender der geätzten rune"}},{q="Wohin bringe ich die Geätzte Rune?",a="Bringt die Geätzte Rune zu Thorgas Grimson in der großen Halle von Ambossar im Coldridgetal.",al={"wohin gehen","bei wem abgeben","thorgas standort"}},{q="Warum verwenden Zwerge Runen statt Briefe?",a="Die zwergische Kultur schätzt Steinmetzkunst, Tradition und beständiges Handwerk. Gemeißelte Runen lassen Botschaften und heilige Anweisungen den eisigen Winden und rauen Naturgewalten Dun Moroghs besser standhalten als zerbrechliches Pergament.",al={"warum eine geätzte rune","hintergrund der zwergenrunen"}},{q="Was geschieht, nachdem ich Thorgas Grimson die Rune vorgelegt habe?",a="Thorgas nimmt Euch in die Reihen der zwergischen Fährtenleser auf. Er erklärt, wie Ihr in den vereisten Felsen überlebt, Eure Ausrüstung pflegt und wilde Tiere respektiert, bevor er Euch in grundlegenden Jagdtechniken ausbildet.",al={"was lehrt thorgas","geätzte rune abgeben"}},{q="Kann jede Klasse die Geätzte Rune erhalten?",a="Nur Zwergenjäger, die ihre Reise im Coldridgetal beginnen, erhalten die Geätzte Rune. Andere Klassen erhalten jeweils eigene Zeichen, die sie zu ihren Lehrmeistern in Ambossar weisen.",al={"geätzte rune nur für jäger","können krieger die geätzte rune erhalten"}}},fp="11,154,18.308.0,35.434.0,24.154.0,26.140.0,32.96.0,44.197.0,58.201.0,38.174.0"}
P.entries["quest:3109"] = {n="Verschlüsselte Rune",s="Im Coldridgetal gibt Sten Starkarm jungen Schurken eine verschlüsselte Rune und ruft sie nach Ambossar, um Solm Hargrin zu treffen.",h="Im Coldridgetal gibt Sten Starkarm jungen Schurken eine verschlüsselte Rune und ruft sie nach Ambossar, um...",kw={"ambossar","das coldridgetal","dun morogh","verschlüsselte rune","gnomeregan","schurkenlehrer","solm hargrin","sten starkarm"},ang={["class:Rogue"]="Als Schurke führt Euch die Rune zu Solm Hargrin. Er bietet an, Euch Verstohlenheit, Kampftricks und Überlebensfertigkeiten in Dun Morogh beizubringen.",["race:Dwarf"]="Als Zwerg des Klans von Eisenschmiede heißt Solm Euch in den Schatten willkommen. Eine kalte Klinge und Dunkelheit helfen Euch, in Dun Morogh am Leben zu bleiben.",["race:Gnome"]="Als Gnom hört Ihr, wie Solm seine Schüler auffordert, den Gnomen beizustehen, die nach dem tragischen Verlust ihrer Heimat in Gnomeregan im Coldridgetal Zuflucht suchen."},sec={{t="Eine verschlüsselte Botschaft",b="Sten sagt, jemand habe ihm den gravierten Stein zugesteckt, damit er ihn überbringt. Er vermutet, dass Solm Hargrin ihn geschickt hat. Die Rune prüft, ob ein Neuling ein Geheimnis bewahren kann, und ruft ihn hinein, ohne dass Solm seinen Bedarf an Spähern und Halunken über den Hof ruft."},{t="Unter Ambossars Dachbalken",b="In Ambossar heißt Solm Hargrin die neuen Schurken in ihrem Handwerk willkommen. Er bietet an, ihnen die Manöver, Schläge und subtilen Künste beizubringen, die sie am Leben halten und ihnen Münzen einbringen. Außerdem erinnert er zwergische Schurken daran, sich um ihre vertriebenen gnomischen Verbündeten zu kümmern, die sich noch immer von Gnomeregans katastrophalem Fall erholen."}},faq={{q="Wer schickt die Verschlüsselte Rune?",a="Solm Hargrin, der Schurkenlehrer in Ambossars großer Halle, verfasst die Rune und lässt Sten Starkarm sie diskret an vielversprechende Rekruten im Schnee weitergeben.",al={"wer hat die rune verfasst","absender verschlüsselte rune","wer gab sten die rune"}},{q="Wo finde ich Solm Hargrin?",a="Solm Hargrin befindet sich in Ambossars Haupthalle, der steinernen Bastion im Herzen des Coldridgetals in Dun Morogh.",al={"wo ist solm","solm hargrin standort","solm finden"}},{q="Welchen Zweck hat diese Rune?",a="Die Rune fordert angehende Schurken auf, ihre Botschaft zu entschlüsseln und sich bei ihrem Lehrer zu melden. Er bietet an, ihnen Kampftechniken und Überlebensmanöver beizubringen.",al={"was bewirkt die rune","zweck verschlüsselte rune","warum verschlüsselte rune"}},{q="Warum erwähnt Solm die Gnome?",a="Gnomeregan wurde vor Kurzem von einer Katastrophe heimgesucht, und gnomische Flüchtlinge teilen sich das Coldridgetal und Ambossar mit den Zwergen. Solm erinnert seine Schüler daran, sie zu unterstützen, während sie sich in ihrer vorläufigen Heimat einleben.",al={"warum gnomen helfen","solms bemerkung zu gnomeregan"}},{q="Wer gibt dem Spieler die Rune?",a="Sten Starkarm gibt Schurkenabenteurern im Coldridgetal den Stein, nachdem sie ihm bei örtlichen Angelegenheiten im Tal geholfen haben.",al={"wer startet verschlüsselte rune","questgeber verschlüsselte rune"}},{q="Können andere Klassen diese Rune erhalten?",a="Nein. Die Rune ist für angehende Schurken bestimmt, die ihre Reise im Coldridgetal beginnen.",al={"ist diese quest nur für schurken","können krieger verschlüsselte rune erhalten"}}},fp="14,117,17.248.0,24.298.0,29.149.0,29.111.0,33.147.0,33.202.0,33.117.0,36.81.0"}
P.entries["quest:311"] = {n="Rückkehr zu Marleth",s="Marleth wartet in Bräuhall auf das Donnerbier, das Ihr aus Kharanos bringt. Das Fass wird beweisen, dass ihr Scalder den Keller der Thunderbrews erreicht hat.",h="Marleth wartet in Bräuhall auf das Donnerbier, das Ihr aus Kharanos bringt.",kw={"bräuhall","dun morogh","kharanos","marleth gerstenbräu","scalder","donnerbier","thunderbrew"},ang={["class:Rogue"]="Als Schurke könnt Ihr Eure Heimlichkeit und Fingerfertigkeit erproben, indem Ihr in den verschneiten Hügeln in einen bewachten Keller schleicht und Fässer austauscht.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass Brauen sowohl eine Kunst als auch ein Wettstreit um die Ehre sein kann. Selbst Kellerspionage kann den örtlichen Stolz wecken."},sec={{t="Die Beute der Sabotage",b="Das Fass stammt aus dem Keller der Thunderbrews und wurde direkt vor den Nasen der Brennmeister entwendet. Es beweist, dass der Austausch geklappt hat, und gibt Marleth eine Trophäe von ihrem Rivalen."},{t="Ein bitterer Braustreit beigelegt",b="Ihr tragt das schwere Fass über verschneite Bergrücken nach Bräuhall. Marleth freut sich diebisch darüber, die Wachen und Kellermeister von Kharanos überlistet zu haben. Ihr Streich zeigt, wie leidenschaftlich Zwergenfamilien ihre ureigenen Rezepte hüten."}},faq={{q="Was ist das Ziel dieser Quest?",a="Ihr bringt das gestohlene Fass mit Donnerbier zu Marleth Gerstenbräu in Bräuhall. Es beweist, dass Ihr ihren Scalder im Keller von Kharanos untergeschoben habt.",al={"was ist zu tun","rückkehr zu marleth ziel","fass abgeben"}},{q="Wer ist Marleth Gerstenbräu?",a="Marleth ist eine zwergische Brauerin in Bräuhall. Sie ist stolz auf die Starkbierrezepte ihrer Familie und wetteifert mit den Brennmeistern der Thunderbrews in Kharanos.",al={"wer ist marleth","marleth hintergrund","gerstenbräu"}},{q="Woher stammt das Fass?",a="Ihr holt das Fass aus dem Keller der Brauerei Donnerbräu in Kharanos, nachdem Ihr Marleths Scalder in ihre Vorräte eingeschleust habt.",al={"woher stammt das fass","kharanos keller","donnerbier fundort"}},{q="Wo liegt Bräuhall?",a="Bräuhall liegt am gefrorenen Ufer des Eiswellensees im Westen von Dun Morogh, nordwestlich von Kharanos.",al={"bräuhall lage","wo liegt bräuhall","marleth finden"}},{q="Warum liegt Marleth mit Kharanos im Streit?",a="Marleth will beweisen, dass ihr Scalder das gefeierte Donnerbier der Thunderbrews übertreffen oder bloßstellen kann. Zwergische Braumeister wetteifern erbittert um ihre Rezepte.",al={"warum rivalen","marleth gegen thunderbrew","braufehde"}},{q="Was macht Marleth mit dem Fass?",a="Das Fass beweist, dass der Austausch direkt vor den Nasen der Wachen von Kharanos gelungen ist. Marleth freut sich diebisch darüber, den Vorrat ihres Rivalen zu behalten.",al={"warum donnerbier stehlen","was geschieht mit dem bier"}}},fp="17,144,22.153.0,21.211.0,34.143.0,26.145.0,33.122.0,26.103.0,37.166.0,37.125.0"}
P.entries["quest:3110"] = {n="Geheiligte Rune",s="Im Coldridgetal ruft Sten Starkarm einen jungen Zwergenpriester nach Ambossar. Er überbringt dem Neuling Branstock Khalders niedergeschriebene Gebete und Weisungen, die ihn hineinrufen, um seine Verbindung zum Heiligen Licht zu vertiefen.",h="Im Coldridgetal ruft Sten Starkarm einen jungen Zwergenpriester nach Ambossar.",kw={"ambossar","branstock khalder","das coldridgetal","dun morogh","zwergenpriester","geheiligte rune","sten starkarm"},ang={["class:Priest"]="Als Priester werdet Ihr durch diese Rune in Dun Morogh förmlich als Diener des Heiligen Lichts anerkannt und zu Branstock Khalder geschickt, um Eure ersten Zauberkünste zu erlernen.",["race:Dwarf"]="Als Zwerg verbindet Ihr die Hingabe an das Licht mit der Zähigkeit der Berge und helft, das Coldridgetal gegen eindringende Troggs zu halten."},sec={{t="Die Berufung zum Priester",b="Ein junger Priester erregt Sten Starkarms Aufmerksamkeit, als er hilft, Bedrohungen außerhalb von Ambossar zu beseitigen. Branstock Khalder, der geistliche Führer der Siedlung, gibt Sten eine Rune mit Gebeten und Weisungen für den Neuling. Dann wird der junge Priester in die wehrhaften Hallen von Ambossar gerufen, um seine heiligen Studien zu beginnen."},{t="Verteidiger von Coldridge",b="Die Zwerge schätzen kriegerische Stärke und schwere Plattenrüstung, doch das Heilige Licht bleibt ein zentraler Bestandteil der Gesellschaft von Eisenschmiede. Im Coldridgetal stehen heilige Zauberwirker an der Seite von Kriegern und Jägern, um die Enklave vor Troggangriffen und gefährlichen Wildtieren zu schützen, die durch den Schnee streifen."}},faq={{q="Was ist die Geheiligte Rune?",a="Sten Starkarm übergibt die beschriftete Priesterrune im Namen von Branstock Khalder. Ihre Gebete führen junge Priester in den Glauben ein und weisen ihnen den Weg zu einer förmlichen Ausbildung.",al={"was ist die geheiligte rune","zweck der rune"}},{q="Wer ist Branstock Khalder?",a="Branstock Khalder bildet in Ambossar Zwergenpriester aus. Sein trockener Humor und sein unerschütterlicher Glaube leiten neue Akolythen, während er ihnen die grundlegenden heiligen Zauber zur Verteidigung des Coldridgetals beibringt.",al={"branstock","priesterlehrer coldridge"}},{q="Wo finde ich Branstock Khalder?",a="Branstock Khalder befindet sich im steinernen Hauptgebäude von Ambossar, auf der zentralen Lichtung des Coldridgetals in Dun Morogh.",al={"branstocks standort","wo ist branstock"}},{q="Warum brauchen Zwerge im Coldridgetal Priester?",a="Troggs haben Teile des Tals überrannt. Die Wachen verlassen sich darauf, dass Priester die Verwundeten heilen und das Licht gegen ihre Feinde einsetzen, während sie ihre Stellungen halten.",al={"warum zwergenpriester","priester in ambossar"}},{q="Kann jede Klasse diese Quest annehmen?",a="Nein. Nur junge Zwergenpriester, die ihre Reise im Coldridgetal beginnen, erhalten die Geheiligte Rune.",al={"wer kann die geheiligte rune erhalten","ist diese quest nur für priester"}},{q="Wer überbringt dem Spieler die Rune?",a="Sten Starkarm überbringt die Rune. Er ist ein Gebirgsjäger aus Ambossar, der die Prüfungen außerhalb des Hauptgebäudes beaufsichtigt und sie Euch gibt, nachdem Ihr zu Beginn bei der Verteidigung des Tals geholfen habt.",al={"wer startet geheiligte rune","sten starkarms rolle"}}},fp="13,225,22.306.0,22.269.0,26.168.0,25.186.0,34.117.0,48.148.0,30.99.0,36.160.0"}
P.entries["quest:3112"] = {n="Einfaches Memorandum",s="Im Coldridgetal erhalten Gnomkrieger einen Ruf nach Ambossar. Sten Starkarm überbringt Thran Khormans Ruf an ausgebildete Kämpfer, die eingeladen werden, die Kriegskunst zu erlernen und sich auf die Rückeroberung Gnomeregans vorzubereiten.",h="Im Coldridgetal erhalten Gnomkrieger einen Ruf nach Ambossar.",kw={"ambossar","das coldridgetal","dun morogh","gnomeregan","einfaches memorandum","sten starkarm","thran khorman","kriegerlehrer"},ang={["class:Warrior"]="Als Gnomkrieger beginnt Ihr Eure Kampfausbildung unter den erfahrenen Waffenmeistern von Eisenschmiede.",["race:Dwarf"]="Als Zwerg seht Ihr, wie Thran Khorman die Notlage der Gnome ebenso ernst nimmt wie zwergische Fehden und vertriebenen Verbündeten Solidarität zeigt.",["race:Gnome"]="Als Gnom tragt Ihr die Erinnerung an die Verbannung aus Gnomeregan in Euch und die Entschlossenheit, Soldaten auszubilden, die Eure verstrahlte Stadt zurückerobern können."},sec={{t="Ein Ruf nach Ambossar",b="Ihr helft Sten Starkarm, Troggs und Eber im Coldridgetal zu vertreiben. Thran Khorman, ein erfahrener Ausbilder in Ambossar, erkennt das Potenzial des geflüchteten Rekruten. Er ruft den Rekruten zur Unterweisung in der Kriegskunst in die zentrale Halle."},{t="Ein Versprechen der Solidarität",b="Zwergische Ausbilder mögen Gnomkrieger wegen ihrer Größe necken, doch Thran Khorman nimmt ihren Verlust ernst. Er bittet sie, sich vorzustellen, wie Zwerge sich fühlen würden, wenn Eisenschmiede an die Dunkeleisenzwerge fiele. Thran hat versprochen, den verbannten Gnomen zu helfen. Er lehrt sie die Kriegskunst, bis sie bereit sind, ihre Heimat zurückzuerobern."}},faq={{q="Was ist das Einfache Memorandum?",a="Im Coldridgetal gibt Sten Starkarm Gnomkriegern eine Nachricht, die sie zu Thran Khorman führt, dem Kriegerlehrer in Ambossars großer Halle.",al={"einfaches memorandum","was ist diese nachricht","memorandum quest"}},{q="Wer schickt das Memorandum?",a="Thran Khorman schickt das Memorandum über Sten Starkarm an vielversprechende Kämpfer, die den Gebirgsjägern helfen.",al={"wer schrieb das memorandum","wer schickte das einfache memorandum"}},{q="Warum bildet Thran Khorman Gnomkrieger aus?",a="Thran Khorman hat versprochen, den verbannten Gnomen zu helfen. Er achtet ihre Entschlossenheit und versteht ihren Verlust. Er vergleicht Gnomeregans Fall mit einer Eroberung Eisenschmiedes durch die Dunkeleisenzwerge.",al={"warum bildet thran gnome aus","geschichte der gnomkrieger"}},{q="Wo finde ich Thran Khorman?",a="Ihr findet Thran Khorman in Ambossars Haupthalle im Coldridgetal in Dun Morogh.",al={"wo ist thran khorman","thran khorman standort"}},{q="Wer ist Sten Starkarm?",a="Sten Starkarm ist ein zwergischer Gebirgsjäger vor Ambossar im Coldridgetal. Er koordiniert die Verteidigung gegen aggressive Eber und eindringende Troggs.",al={"sten starkarm","wer ist sten"}},{q="Warum beginnen Gnome im Coldridgetal?",a="Nachdem Gnomeregan gefallen und verstrahlt worden war, flohen die überlebenden Gnome als Flüchtlinge in die Lande der Zwerge. Ambossar und Eisenschmiede haben ihre Tore geöffnet, um ihnen Zuflucht zu gewähren, während sie ihre Streitkräfte wieder aufbauen.",al={"warum sind gnome hier","gnome im coldridgetal"}}},fp="17,208,21.219.0,22.310.0,30.143.0,25.104.0,44.182.0,30.90.0,21.149.0,44.191.0"}
P.entries["quest:3113"] = {n="Verschlüsseltes Memorandum",s="Im Coldridgetal gibt Sten Starkarm neuen gnomischen Schurken eine gefaltete Notiz für Solm Hargrin in Ambossar.",h="Im Coldridgetal gibt Sten Starkarm neuen gnomischen Schurken eine gefaltete Notiz für Solm Hargrin in...",kw={"ambossar","das coldridgetal","dun morogh","verschlüsseltes memorandum","gnomeregan","schurkenlehrer","solm hargrin","sten starkarm"},ang={["class:Rogue"]="Als Schurke erhaltet Ihr Eure erste Aufforderung, Solm Hargrin aufzusuchen. Seine Nachricht führt Euch den gegenseitigen Schutz vor Augen, den Ihr braucht, um Euer heimliches Handwerk in zwergischen Landen auszuüben.",["race:Dwarf"]="Als Zwerg seht Ihr, wie Bergsteiger wie Sten Starkarm Nachrichten zwischen Eisenschmiede und den vertriebenen Gnomen im Coldridgetal überbringen.",["race:Gnome"]="Als Gnom seht Ihr die Not, mit der Flüchtlinge nach Gnomeregans Fall konfrontiert sind. Die Überlebenden halten als Gäste unter den Zwergen zusammen."},sec={{t="Eine diskrete Vorstellung",b="Während Ihr den Bergsteigern helft, der Bedrohung durch Troggs zu begegnen, gibt Sten Euch ein Pergament, das ihm anvertraut wurde. Es sieht wie ein offizielles Memorandum aus. Die Notiz lädt Euch ein, Solm Hargrin zu treffen, den Schurkenlehrer, der in Ambossar stationiert ist."},{t="Gemeinsame Not im Schnee",b="Gnomische Überlebende leben auf engem Raum mit ihren zwergischen Gastgebern, nachdem Gnomeregans plötzlicher Fall sie aus ihrer unterirdischen Heimat vertrieben hat. Solm Hargrin weiß, dass Schurken unter Verdacht geraten, wenn Gegenstände verschwinden. Deshalb drängt er sie, im Stillen zusammenzuhalten und einander beim Überleben zu helfen."}},faq={{q="Wer hat das Verschlüsselte Memorandum geschrieben?",a="Solm Hargrin, der Schurkenlehrer in Ambossar, hat die Notiz geschrieben. Er tarnte sie als offizielle Anweisung von höherer Stelle, damit Sten Starkarm sie ohne Argwohn weitergeben würde.",al={"wer schickte das memorandum","wer schrieb die notiz","solms notiz"}},{q="Warum ist das Memorandum getarnt?",a="Solm Hargrin tarnt die Notiz, um Euch in Ambossar, einer zwergischen Feste, diskret anzusprechen. Er hält sich bedeckt, um Gerüchte oder Anschuldigungen zu vermeiden, wenn Ausrüstung verschwindet, und nutzt verschlüsselte Grüße, um andere Schurken zu erreichen.",al={"warum getarnt","warum verschlüsselt"}},{q="Was verrät diese Notiz über die Lage in Dun Morogh?",a="Die Notiz beschreibt die Spannungen und den Zusammenhalt zwischen Gnomen und Zwergen nach dem Verlust von Gnomeregan. Das Zusammenleben in Eisenschmiede und Dun Morogh belastet die Vorräte, deshalb drängt Solm jene, die dem Schattenhandwerk nachgehen, aufeinander achtzugeben.",al={"beziehungen zwischen gnomen und zwergen","gnomeregan flüchtlinge dun morogh"}},{q="Wer überbringt dem Spieler das Memorandum?",a="Sten Starkarm überreicht Euch das Memorandum, nachdem Ihr ihm im Coldridgetal geholfen habt. Er nimmt an, dass Solm Hargrin es für Eure Ausbildung geschickt hat.",al={"sten starkarm überbringung","wer überreicht die notiz"}},{q="Welche Aufgabe hat Solm Hargrin?",a="Solm Hargrin bildet Schurken in Ambossars Berghalle aus. Er lehrt neue Schurken Kampftechniken und Talente der Schatten.",al={"solm hargrins aufgabe","was macht solm"}},{q="Hat diese Quest mit Gnomeregans Fall zu tun?",a="Ja. Solm spricht davon, dass Gnomeregan überrannt wurde, und sagt, dass vertriebene gnomische Schurken dank ihrer Bruderschaft trotz des Verlusts ihrer mechanischen Heimat durchhalten können.",al={"gnomeregans fall hintergrund","lage gnomischer flüchtlinge"}}},fp="20,105,23.219.0,28.268.0,35.174.0,32.218.0,61.226.0,42.129.0,34.120.0,44.165.0"}
P.entries["quest:3114"] = {n="Glyphenmemorandum",s="In Ambossar gibt Euch Gebirgsjäger Sten Starkarm ein Memorandum von Magierlehrer Marryk Nurribit, der Euch zu sich einlädt.",h="In Ambossar gibt Euch Gebirgsjäger Sten Starkarm ein Memorandum von Magierlehrer Marryk Nurribit, der Euch zu...",kw={"ambossar","das coldridgetal","dun morogh","glyphenmemorandum","magierlehrer","marryk nurribit","sten starkarm"},ang={["class:Mage"]="Als Magier lernt Ihr durch dieses Memorandum Euren ersten Lehrer der arkanen Künste in Dun Morogh kennen.",["faction:Alliance"]="Als Mitglied der Allianz erlebt Ihr durch Sten Starkarm und Marryk Nurribit im Coldridgetal, wie Zwerge und Gnome zusammenarbeiten.",["race:Gnome"]="Als Gnom könnt Ihr von Marryk Nurribit lernen, einem der gnomischen Spezialisten, die nach dem Fall Gnomeregans in Zwergenlanden Zuflucht fanden."},sec={{t="Ein Schreiben für Magierneulinge",b="Die Einladung gilt Euch, einem Magierneuling, dem Sten im Coldridgetal hilft. Lest sie und geht dann nach Ambossar hinein, um den Gnom zu treffen, der sie verfasst hat. Dort beginnt Eure Ausbildung im Zauberwirken."},{t="Ausbildung bei Marryk Nurribit",b="In Ambossar gibt Euch der gnomische Magierlehrer Marryk Nurribit vor dem Unterricht klare Ratschläge. Haltet Euch aus ernstem Ärger heraus und spart Münzen für die Ausbildung und Getränke im Wirtshaus. Meidet das gefallene Gnomeregan und seine radioaktiven Gefahren. Marryk ist bereit, Euch die arkanen Künste zu lehren."}},faq={{q="Wer überbringt dieses Memorandum?",a="Nachdem Ihr Gebirgsjäger Sten Starkarm bei seinen ersten Pflichten im Coldridgetal geholfen habt, gibt er Euch das Memorandum.",al={"wer gibt das glyphenmemorandum","sten starkarm quest"}},{q="Wer ist Marryk Nurribit?",a="Marryk Nurribit ist ein gnomischer Magierlehrer in Ambossar im Coldridgetal. Er lehrt neue Magier ihre ersten Zauber und den sicheren Umgang mit den arkanen Künsten.",al={"wer ist marryk","ambossar magierlehrer"}},{q="Wo kann ich Marryk Nurribit finden?",a="Ihr findet Marryk Nurribit in der Haupthalle von Ambossar, am oberen Ende des Coldridgetals in Dun Morogh.",al={"marryk nurribit standort","wo ist der magierlehrer im coldridgetal"}},{q="Warum warnt Marryk vor einem Besuch in Gnomeregan?",a="Troggs überrannten Gnomeregan, und eine katastrophale Freisetzung radioaktiven Gases verseuchte die Stadt. Für einen Neuling, der durch Dun Morogh streift, ist sie gefährlich.",al={"marryk gnomeregan warnung","warum gnomeregan meiden"}},{q="Welche Klassen erhalten diese Aufgabe?",a="Neue Magier, die ihre Ausbildung im Coldridgetal beginnen, erhalten das Memorandum, um ihren Klassenlehrer aufzusuchen.",al={"wer erhält das glyphenmemorandum","ist diese quest nur für magier"}},{q="Was erwartet Marryk von seinen Schülern?",a="Marryk rät seinen Schülern, sich aus Ärger herauszuhalten, Silber für die Zauberausbildung und ein Bier für ihn zu sparen und Gnomeregan zu meiden.",al={"marryks erwartungen","was will der lehrer"}}},fp="18,125,26.173.0,29.272.0,29.112.0,23.160.0,33.103.0,49.145.0,31.105.0,42.133.0"}
P.entries["quest:3115"] = {n="Besudeltes Memorandum",s="Im Coldridgetal schickt Euch Sten Starkarm unauffällig zu Alamar Grimm in Ambossar. Grimm drängt Euch, dunkler Macht mehr zu vertrauen als Euren zwergischen Gastgebern.",h="Im Coldridgetal schickt Euch Sten Starkarm unauffällig zu Alamar Grimm in Ambossar.",kw={"alamar grimm","ambossar","das coldridgetal","dun morogh","gnomhexenmeister","gnomeregan exil","sten starkarm","besudeltes memorandum"},ang={["class:Warlock"]="Als Hexenmeister erhaltet Ihr ein Schreiben, das Euren förmlichen Eintritt in diese Kunst markiert. Es stellt dämonische Pakte als praktische Entscheidung dar, die aus Überlebenswillen entsteht, nicht aus Wahnsinn.",["race:Dwarf"]="Als Zwerg seht Ihr, wie Euer Volk diese Anwender dunkler Künste mit offenkundigem Widerwillen und äußerster Wachsamkeit unter seinem Dach duldet.",["race:Gnome"]="Als Gnom teilt Ihr vielleicht den Groll mancher Verbannter darüber, ihre Heimat verloren zu haben und von Eisenschmiede abhängig zu sein."},sec={{t="Ein diskreter Ruf",b="Hexenmeistern begegnet man im Coldridgetal mit tiefem Misstrauen. Während Ihr Sten Starkarm gegen örtliche Bedrohungen helft, steckt er Euch widerwillig eine Notiz zu. Seine Warnung zeigt deutlich, wie wenig man Euresgleichen hier vertraut, selbst unter dem brüchigen Waffenstillstand, der Hexenmeistern erlaubt, ihre Künste in den Gebieten der Allianz auszuüben."},{t="Gnomischer Groll im Exil",b="In Ambossar spricht Alamar Grimm von der Notlage der Gnome. Er glaubt, gewöhnliche Magie und Tüftelei hätten Gnomeregan im Stich gelassen, ihr Volk an den Rand der Auslöschung gebracht und sie als Flüchtlinge zweiter Klasse vom Wohlwollen der Zwerge abhängig gemacht. Er drängt Euch, weder dem Heiligen Licht noch zwergischer Politik zu vertrauen. Beschwört stattdessen Unholde und beherrscht sie, denn ihr Gehorsam ist bedingungslos."}},faq={{q="Was ist das Besudelte Memorandum?",a="Das Besudelte Memorandum ist eine schriftliche Nachricht, die Sten Starkarm angehenden Gnomhexenmeistern im Coldridgetal überreicht. Sie weist sie an, Alamar Grimm aufzusuchen, den Hexenmeisterlehrer in Ambossar.",al={"besudelte notiz","hexenmeisternotiz dun morogh","was ist das memorandum"}},{q="Warum misstraut man Hexenmeistern im Coldridgetal?",a="Zwerge und ihre Verbündeten in der Allianz schätzen kriegerische Ehre und das Heilige Licht. Sie betrachten Dämonologie und Shadow Magic als verderbt und gefährlich, weshalb Gnomhexenmeistern tiefes Misstrauen entgegenschlägt.",al={"warum mögen zwerge keine hexenmeister","vorurteile gegen hexenmeister ambossar"}},{q="Wer ist Alamar Grimm?",a="Alamar Grimm ist ein gnomischer Hexenmeisterlehrer in Ambossar. Verbittert über Gnomeregans Fall und die Abhängigkeit der Gnome von zwergischer Wohltätigkeit, lehrt er junge Gnome, dämonische Diener zu binden und selbst Macht zu erlangen.",al={"alamar grimm hintergrundgeschichte","wer ist alamar"}},{q="Warum kritisiert Grimm gewöhnliche Magie und Technik?",a="Grimm glaubt, herkömmliche Ingenieurskunst und anerkannte Magieschulen hätten die Gnome bei der Katastrophe in Gnomeregan im Stich gelassen. Seinen Worten nach wurden sie dadurch von zwergischen Gönnern abhängig, denen die Bindungen zu den Menschen wichtiger sind als die Rückeroberung der gnomischen Heimat.",al={"grimms ansicht zu gnomeregan","warum dunkle magie statt ingenieurskunst"}},{q="Können zwergische Hexenmeister diese Quest erhalten?",a="Nein. In Dun Morogh können nur Gnome den Pfad des Hexenmeisters beschreiten, daher richtet sich der Ruf an neu eingetroffene gnomische Anwender dieser Künste.",al={"zwergenhexenmeister besudeltes memorandum","können zwerge hexenmeister sein"}},{q="Wo spielt diese Quest?",a="Ihr beginnt bei Sten Starkarm im Coldridgetal und endet im Inneren von Ambossar, der zentralen Feste über dem Tal im Südwesten von Dun Morogh.",al={"wo ist alamar grimm","besudeltes memorandum abgeben"}}},fp="18,142,18.270.0,27.373.0,31.177.0,48.178.0,20.213.0,53.233.0,38.118.0,33.147.0"}
P.entries["quest:3116"] = {n="Einfaches Siegelzeichen",s="Im Laubschattental ruft Alyissia junge Nachtelfenkrieger zur Verteidigung ihres Volkes auf. Konservator Ilthalaine überbringt ihren Ruf, während die Kaldorei auf Teldrassil und darüber hinaus Veränderungen erleben.",h="Im Laubschattental ruft Alyissia junge Nachtelfenkrieger zur Verteidigung ihres Volkes auf.",kw={"aldrassil","alyissia","feralas","ilthalaine","laubschattental","einfaches siegelzeichen","teldrassil","krieger"},ang={["class:Warrior"]="Als Krieger der Kaldorei beginnt Ihr Eure Ausbildung bei Alyissia, Eurer ersten Lehrmeisterin im Waffenkampf.",["faction:Alliance"]="Alyissias Rat spiegelt die frühen Bemühungen der Nachtelfen wider, nach Jahrhunderten der Abgeschiedenheit andere Völker der Allianz in ihrem Geäst willkommen zu heißen.",["race:NightElf"]="Das Siegelzeichen verweist auf rasche Veränderungen im Umfeld der Kaldorei, vom Emporwachsen Teldrassils bis zur Öffnung ihrer abgeschiedenen Heimat für fremde Verbündete."},sec={{t="Ein Ruf zu den Waffen im Laubschattental",b="Ihr habt Euer Geschick bewiesen, inmitten der unruhigen Tierwelt des Laubschattentals zu überleben. Nun gibt Euch Konservator Ilthalaine ein beschriftetes Siegelzeichen von Alyissia, der Kriegerausbilderin bei Aldrassil. Es kennzeichnet den Beginn Eurer Kampfausbildung. Alyissia bittet Euch, Eure Kraft der Verteidigung Eures Volkes zu widmen."},{t="Eine neue Zeit voller Umbrüche",b="Alyissia beginnt Eure Ausbildung, während die Nachtelfen raschen Veränderungen und Gefahren gegenüberstehen. In nur wenigen Jahren haben sie den Weltbaum Teldrassil emporwachsen lassen, die Ausbreitung eines Verderbens unter Waldtieren nah und fern beobachtet und den Kontakt zu uralten, einst verloren geglaubten Gebieten wie Feralas wiederhergestellt. Die Kaldorei brauchen fähige Verteidiger gegen diese Gefahren."},{t="Das Geäst öffnet sich",b="Alyissia bereitet junge Kaldorei auf mehr als den Kampf vor. Sie bittet Euch, Besucher auf Teldrassil nicht nach ihrem Volk zu beurteilen. Manche handeln vielleicht nicht aus reiner Selbstlosigkeit, doch Verbündete sind für die Verteidigung der Kaldorei unerlässlich. Während Ihr die Aufgabe übernehmt, Euer Volk zu beschützen, bittet sie Euch, Besuchern ein angemessenes Maß an Vertrauen entgegenzubringen."}},faq={{q="Was ist das Einfache Siegelzeichen?",a="Alyissia, die Kriegerausbilderin im Laubschattental, schickt das beschriftete Siegelzeichen an angehende Nachtelfenkrieger, wenn sie ihre förmliche Kampfausbildung beginnen.",al={"einfaches siegelzeichen gegenstand","was ist dieses siegelzeichen","siegelzeichen des kriegers"}},{q="Wer schickt Euch zu Alyissia?",a="Konservator Ilthalaine überbringt das Siegelzeichen und verweist Euch an Alyissia, nachdem Ihr Eure ersten Aufgaben zur Wahrung des Gleichgewichts im Laubschattental erledigt habt.",al={"wer gibt das einfache siegelzeichen","questgeber einfaches siegelzeichen"}},{q="Wo ist Alyissia zu finden?",a="Alyissia bildet angehende Nachtelfenkrieger nahe dem gewaltigen Stamm von Aldrassil aus, im sicheren Zufluchtsort des Laubschattentals.",al={"alyissia standort","wo ist alyissia","kriegerausbilderin laubschattental"}},{q="Warum werden laut Alyissia gerade jetzt Krieger gebraucht?",a="Die Nachtelfen haben Teldrassil emporwachsen lassen, Verderbnis hat sich unter den örtlichen Wildtieren ausgebreitet, und die Kaldorei haben uralte Gebiete wie Feralas wiederentdeckt. Erfahrene Kämpfer werden gebraucht, um ihr Volk vor diesen Bedrohungen zu schützen.",al={"warum brauchen nachtelfen krieger","laubschattental krieger hintergrundgeschichte"}},{q="Was sagt Alyissia über Besucher anderer Völker auf Teldrassil?",a="Alyissia rät Euch, Besucher auf Teldrassil nicht nach ihrem Volk zu beurteilen. Obwohl nicht jeder Reisende aus reiner Selbstlosigkeit handelt, fordert sie Euch auf, ihnen etwas Vertrauen entgegenzubringen, damit sie bei der Verteidigung des Baumes helfen können.",al={"alyissia über andere völker","nachtelfen und außenstehende","allianz auf teldrassil"}},{q="Welche Bedeutung hat die Erwähnung von Feralas?",a="Feralas ist ein uraltes Gebiet der Nachtelfen, das nach der Great Sundering lange abgeschnitten war oder als verloren galt. Seine Wiederentdeckung zeigt, wie die Kaldorei nach Jahrtausenden der Abgeschiedenheit wieder Verbindungen zur weiteren Welt knüpfen.",al={"warum feralas erwähnen","verbindung zu feralas"}}},fp="12,177,28.294.0,20.336.0,18.305.0,25.137.0,31.143.0,28.110.0,52.222.0,61.197.0,47.200.0"}
P.entries["quest:3117"] = {n="Geätztes Siegelzeichen",s="In Laubschattental schickt das Geätzte Siegelzeichen junge Nachtelfenjäger nach Aldrassil. Über Konservator Ilthalaine ruft Ayanna Immerlauf sie zu ihrer Ausbilderin, um Bogenschießen und Tierkunde zu erlernen.",h="In Laubschattental schickt das Geätzte Siegelzeichen junge Nachtelfenjäger nach Aldrassil.",kw={"aldrassil","ayanna immerlauf","geätztes siegelzeichen","jäger","ilthalaine","laubschattental","teldrassil"},ang={["class:Hunter"]="Als Jäger beginnt Ihr Eure Ausbildung auf Teldrassil und erlernt Bogenschießen, Fährtenlesen und Tierherrschaft.",["race:NightElf"]="Als Kaldorei erbt Ihr eine Jagdtradition, die von Einklang mit der Natur und Ehrfurcht vor Elune geprägt ist, nicht von bloßem Zeitvertreib."},sec={{t="Ein Ruf ins Geäst",b="Nachdem junge Kaldoreijäger bei der Verteidigung von Laubschattental geholfen haben, überreicht Konservator Ilthalaine ihnen ein beschriftetes Zeichen. Ein Bote brachte es von ihrer Mentorin Ayanna Immerlauf. Das Siegelzeichen weist jeden Neuling hinauf in Aldrassils hohes Geäst, wo die Ausbilder über das Blätterdach wachen."},{t="Der Pfad des Jägers",b="Mit dem Treffen bei Ayanna beginnt die Ausbildung eines Jägers auf Teldrassil. Sie lehrt Neulinge Treffsicherheit und das Verständnis für Kalimdors wilde Kreaturen. Ein Jäger muss seine tierischen Gefährten respektieren und den unsichtbaren Gefahren der Welt mit Achtsamkeit und Demut begegnen."}},faq={{q="Was ist das Geätzte Siegelzeichen?",a="Das Geätzte Siegelzeichen ist Ayanna Immerlaufs eingeritzte Botschaft, die vielversprechende Nachtelfenneulinge zu ihrem Posten oben auf Aldrassil führt.",al={"geätztes siegelzeichen","was ist dieses siegelzeichen","siegelzeichen gegenstand"}},{q="Wo befindet sich Ayanna Immerlauf?",a="Ayanna Immerlauf befindet sich auf Aldrassils oberen Terrassen, in der großen Höhlung des Weltenbaums im Zentrum von Laubschattental.",al={"wo ist ayanna","ayanna immerlauf finden","ayanna immerlauf standort"}},{q="Wer überreicht das Geätzte Siegelzeichen?",a="Konservator Ilthalaine überreicht Nachtelfenjägern das Geätzte Siegelzeichen, wenn sie beginnen, sich bei der Verteidigung der umliegenden Wälder zu beweisen.",al={"wer gibt die quest","questgeber","wo gibt es das geätzte siegelzeichen"}},{q="Was lehrt Ayanna Immerlauf?",a="Ayanna lehrt Treffsicherheit, den Umgang mit Tieren und das Überleben in der Wildnis. Sie warnt Jäger davor, die Gefahren da draußen zu unterschätzen.",al={"jägerausbildung","was lehrt ayanna","warum mit ayanna sprechen"}},{q="Warum mahnt Ayanna Jäger zur Vorsicht im Umgang mit ihren Begleitern?",a="Ayanna mahnt Jäger, ihre tierischen Gefährten zu respektieren. Die Wildnis birgt weit größere Bedrohungen, als Neulinge erwarten mögen, weshalb sie die Fähigkeiten ihrer Gefährten niemals auf die leichte Schulter nehmen sollten.",al={"tiergefahr","warum tiere respektieren","vorsicht bei begleitern"}},{q="Ist diese Quest für andere Klassen verfügbar?",a="Nein. Das Geätzte Siegelzeichen ist eine erste Vorladung ausschließlich für Nachtelfenjäger.",al={"können druiden das machen","ist das nur für jäger","andere klassen"}}},fp="12,201,23.271.0,22.254.0,25.126.0,35.113.0,31.132.0,34.129.0,49.189.0,41.76.0"}
P.entries["quest:3118"] = {n="Verschlüsseltes Siegelzeichen",s="In Laubschattental ruft eine verschlüsselte Botschaft neue Nachtelfenschurken zu ihrem Ausbilder. Konservator Ilthalaine überbringt die Nachricht für Frahun Schattenflüsterer, der warnt, dass der Frieden in ganz Kalimdor brüchig bleibt.",h="In Laubschattental ruft eine verschlüsselte Botschaft neue Nachtelfenschurken zu ihrem Ausbilder.",kw={"aldrassil","konservator ilthalaine","verschlüsseltes siegelzeichen","frahun schattenflüsterer","schurkenausbilder","laubschattental","teldrassil"},ang={["class:Rogue"]="Als Schurke schließt Ihr Euch den Spähern, Assassinen und Informanten der Kaldorei an, die Teldrassil vor unsichtbaren Widersachern schützen.",["faction:Alliance"]="Als Mitglied der Allianz hört Ihr die Ausbilder von Laubschattental warnen, dass die Verträge zwischen den Fraktionen brüchig sind. Die Arbeit der Kundschafter hilft, Einfälle der Horde zu verhindern.",["race:NightElf"]="Als Nachtelf wacht Ihr mit Aldrassil über Kalimdors wechselnde Grenzen und verteidigt seine neu gepflanzten Äste."},sec={{t="Eine Botschaft im Schatten",b="Während junge Nachtelfen unter Konservator Ilthalaine das Gleichgewicht der Natur studieren, erhalten jene, die sich zur Heimlichkeit hingezogen fühlen, einen leiseren Ruf. Ein Bote bringt das Verschlüsselte Siegelzeichen von Frahun Schattenflüsterer, dem Schurkenmentor von Laubschattental. Seine Chiffren sind für Neulinge des Handwerks bestimmt. Sie sollen die Botschaft entschlüsseln und Frahun nahe den Wurzeln von Aldrassil aufsuchen, um ihre Ausbildung zu beginnen."},{t="Den Horizont im Blick",b="Frahuns Botschaft warnt, dass der Frieden in ganz Kalimdor ungewiss bleibt. Der Dritte Krieg ist beendet, doch der Waffenstillstand zwischen der Allianz und der aufstrebenden Horde ist brüchig. Deshalb werden Späher und Informanten unter den Schurken in Laubschattental angehalten, schon früh ihre Augen und Ohren zu schärfen. Sie halten nach Bedrohungen und verdeckten Provokationen Ausschau, die erneut einen Krieg über die Grenzen hinweg entfachen könnten."}},faq={{q="Was ist das Verschlüsselte Siegelzeichen?",a="Frahun Schattenflüsterer schickt neuen Schurken in Laubschattental ein verschlüsseltes Zeichen. Seine Botschaft weist sie an, ihn zur Ausbildung unter Aldrassil aufzusuchen.",al={"was ist dieses siegelzeichen","verschlüsseltes siegelzeichen quest","sieгelzeichen gegenstand"}},{q="Wer übergibt jungen Nachtelfen das Siegelzeichen?",a="Konservator Ilthalaine überbringt das Siegelzeichen für Frahun, nachdem ein Neuling grundlegendes Geschick im Umgang mit den Wildtieren rund um Laubschattentals Äste bewiesen hat.",al={"wer gibt die quest","questgeber","konservator ilthalaine"}},{q="Wo ist Frahun Schattenflüsterer zu finden?",a="Frahun Schattenflüsterer ist unter dem Great Tree Aldrassil in Laubschattental zu finden. Er steht bereit, um neu eingetroffene Nachtelfenschurken zu unterweisen.",al={"wo ist frahun","frahun schattenflüsterer finden","frahun standort"}},{q="Warum werden im friedlichen Teldrassil Schurken gebraucht?",a="Schurken werden gebraucht, weil der Waffenstillstand mit den Fraktionen außerhalb Teldrassils brüchig ist. Späher und Informanten halten nach verdeckten Machenschaften Ausschau, darunter Bewegungen der Horde und Bedrohungen innerhalb der Äste.",al={"warum brauchen nachtelfen schurken","schurken in laubschattental","aufgabe der schurken"}},{q="Was geschieht, nachdem das Siegelzeichen Frahun vorgelegt wurde?",a="Nachdem Ihr das Siegelzeichen vorgelegt habt, nimmt Frahun die Chiffre entgegen und erkennt Eure Bereitschaft an. Wenn Ihr an Erfahrung gewinnt, könnt Ihr zurückkehren, um Unterricht in Kampftechniken, im Umgang mit Waffen und in Heimlichkeit zu erhalten.",al={"what comes next","nach verschlüsseltem siegelzeichen","sieгelzeichen belohnung hintergrund"}},{q="Bedroht die Horde Laubschattental aktiv und unmittelbar?",a="Die Horde greift das abgeschiedene Teldrassil nicht offen an. Doch Gerüchte, dass Agenten der Horde in ganz Kalimdor Misstrauen säen, halten die Wachen und Agenten der Kaldorei wachsam.",al={"ist die horde in teldrassil","horde bedrohung laubschattental","horde sät misstrauen"}}},fp="15,198,24.364.0,20.343.0,28.137.0,41.144.0,39.136.0,45.169.0,50.190.0,53.166.0"}
P.entries["quest:3119"] = {n="Geheiligtes Siegelzeichen",s="Im Laubschattental überbringt das Geheiligte Siegelzeichen Shandas Ruf an junge Nachtelfenpriester, die ihre Ausbildung in Aldrassil beginnen. Konservator Ilthalaine übermittelt ihre Botschaft, während die Novizen lernen, Elune's Grace zu wirken.",h="Im Laubschattental überbringt das Geheiligte Siegelzeichen Shandas Ruf an junge Nachtelfenpriester, die ihre...",kw={"aldrassil","konservator ilthalaine","elune","geheiligtes siegelzeichen","priester","laubschattental","shanda","teldrassil"},ang={["class:Priest"]="Als Priester der Kaldorei beginnt Ihr bei Shanda Eure förmliche Ausbildung in Elunes Licht und Weisheit.",["faction:Alliance"]="Shandas Worte spiegeln die neuen Verbindungen zwischen den Kaldorei und der Allianz wider, die unbekannte Völker und Reisende auf Teldrassils Äste führen.",["race:NightElf"]="Als Nachtelf steht im Mittelpunkt Eurer Kultur das Priestertum mit seinen uralten Traditionen der Verehrung des Mondes, die Euer Volk seit Jahrtausenden leiten."},sec={{t="Berufung zum Dienst",b="Nachtelfenpriester dienen Elune als Mägde und Diener der Mondgöttin. Wenn ein junger Kaldorei im Laubschattental Hingabe und eine Verbundenheit mit dem göttlichen Licht zeigt, gibt Konservator Ilthalaine ihm ein geheiligtes Siegelzeichen. Shanda, die Priesterlehrerin, sandte das Zeichen durch einen Boten als Einladung, nach Aldrassil zu kommen und die spirituelle Ausbildung zu beginnen."},{t="Eine Welt im Wandel",b="Shanda erzählt dem jungen Akolythen, dass ungewöhnlicher Wandel die geschützte Zuflucht Teldrassils erreicht hat. Reisende bevölkern die Äste des Weltbaums, darunter auch Angehörige der übrigen Allianz, denen gestattet wurde, sich mit den Kaldorei zu treffen. Die weite Welt ruft, doch Shanda mahnt die Novizen, sich zunächst der Probleme im Laubschattental anzunehmen, bevor sie sich Konflikten jenseits seiner Grenzen zuwenden."}},faq={{q="Was ist das Geheiligte Siegelzeichen?",a="Das Geheiligte Siegelzeichen ist ein beschriftetes Zeichen, das Shanda durch einen Boten an Konservator Ilthalaine sandte, um einen Priesterneuling zur Unterweisung nach Aldrassil zu rufen.",al={"geheiligtes siegelzeichen gegenstand","was ist dieses siegelzeichen","sie gelzeichen von shanda"}},{q="Wer ist Shanda?",a="Shanda bildet in Aldrassil Priester aus und unterweist junge Nachtelfenpriester in den Riten, Disziplinen und Gebeten der Sisterhood of Elune.",al={"priesterlehrer aldrassil","wer ist shanda"}},{q="Wo befindet sich Shanda?",a="Shanda befindet sich im hohlen Fuß von Aldrassil, dem großen zentralen Baum im Herzen des Laubschattentals auf Teldrassil.",al={"shanda finden","wo geheiligtes siegelzeichen abgeben","shandas standort"}},{q="Warum besuchen Mitglieder der Allianz Teldrassil?",a="Mitglieder der Allianz besuchen Teldrassil, um sich mit den Kaldorei zu treffen und zu beraten. Die Nachtelfen knüpften nach dem Dritten Krieg Verbindungen zur Allianz, und Reisende anderer Völker treffen nun auf den Ästen des Weltbaums ein, während sich beide Seiten auf Azeroths Herausforderungen vorbereiten.",al={"allianz auf teldrassil","warum außenstehende auf dem weltbaum"}},{q="Was sollte ein Priester nach Abschluss dieser Aufgabe tun?",a="Shanda rät Priestern, den örtlichen Verteidigern und Hütern im gesamten Laubschattental zu helfen. Sie können zu ihr zurückkehren, um neue Gebete und Techniken zu erlernen.",al={"was kommt nach dem siegelzeichen","nach dem geheiligten siegelzeichen"}},{q="Warum vergibt Ilthalaine diese Quest?",a="Konservator Ilthalaine beaufsichtigt die ersten Prüfungen der Novizen im Laubschattental. Als Shandas Bote mit dem Siegelzeichen eintraf, bewahrte Ilthalaine es auf, bis der angehende Priester für die nächsten Schritte bereit war.",al={"konservator ilthalaine priester","warum mit ilthalaine sprechen"}}},fp="14,206,20.343.0,16.346.0,27.148.0,14.134.0,24.111.0,45.266.0,51.144.0,36.204.0"}
P.entries["quest:312"] = {n="Tundra MacGranns gestohlene Vorräte",s="Tundra MacGrann braucht seine Wintervorräte von Old Icebeard zurück. Der Yeti hat die thoriumverstärkte Fleischtruhe fortgeschleppt, und MacGranns verletztes Bein hält ihn davon ab, die Höhle zu erreichen.",h="Tundra MacGrann braucht seine Wintervorräte von Old Icebeard zurück.",kw={"trockenfleisch","dun morogh","fleischkiste","old icebeard","gestohlenes lager","thorium","tundra macgrann","yeti"},ang={["class:Hunter"]="Als Jäger wisst Ihr, wie viel Arbeit es kostet, Fleisch haltbar zu machen. MacGrann verlor seine Vorräte an ein Biest, während er Hirsche aufspürte.",["class:Rogue"]="Als Schurke könnt Ihr Euch in Old Icebeards Höhle schleichen, während er fort ist, und die Truhe holen, ohne die Klinge zu ziehen.",["race:Dwarf"]="Als Zwerg wisst Ihr, wie hart ein Bergwinter sein kann. Ohne haltbares Fleisch oder Schutz hält selbst ein erfahrener Bergsteiger der Kälte womöglich nicht stand."},sec={{t="Wintervorräte und gestohlene Kisten",b="Für die kalte Jahreszeit hatte MacGrann einen Monatsvorrat Trockenfleisch eingesalzen. Er schloss ihn in eine thoriumverstärkte Truhe, um hungrige Bären fernzuhalten. Old Icebeard schleppte gleich die ganze Truhe fort, statt zu versuchen, sie zu öffnen."},{t="Old Icebeards Höhle",b="Während MacGrann auf der Jagd nach Hirschen war, schleifte Old Icebeard die Truhe zu einer Höhle in den schroffen Hügeln. MacGrann glaubt, dass der Yeti massives Thorium nicht durchbrechen kann, doch sein verletztes Bein hält ihn davon ab, die Vorräte zurückzuholen. Ihr könnt Euch dem Biest stellen oder hineinschleichen, während es die Schneeverwehungen durchstreift."}},faq={{q="Wer ist Tundra MacGrann?",a="Tundra MacGrann ist ein Zwergenjäger, der in den verschneiten Gebieten von Dun Morogh lebt. Wegen seines verletzten Beins ist er im Winter auf seine gelagerten Vorräte angewiesen.",al={"tundra macgrann","macgrann","wer ist macgrann"}},{q="Wer hat MacGranns Fleischkiste gestohlen?",a="Old Icebeard, ein Yeti aus der Gegend, stahl MacGranns Fleischtruhe, während der Jäger auf der Jagd nach Hirschen war. Das Biest schleppte sie in seine Berghöhle.",al={"wer hat das lager gestohlen","wer hat das fleisch genommen","dieb des gestohlenen lagers"}},{q="Warum kann MacGrann sein Fleisch nicht selbst zurückholen?",a="MacGranns verletztes Bein hindert ihn daran, sich schnell oder leise genug zu bewegen, um in Old Icebeards Höhle einzudringen und sicher wieder zu entkommen.",al={"warum macgrann es nicht holen kann","macgranns bein","lahmes bein"}},{q="Hat der Yeti das Essen gefressen?",a="Nein. Das Trockenfleisch ist weiterhin in einer massiven Thoriumtruhe eingeschlossen. Old Icebeard hat sie fortgeschleppt, kann das Metall aber nicht durchbrechen.",al={"ist das essen gefressen","kann icebeard die kiste öffnen"}},{q="Muss man gegen Old Icebeard kämpfen, um die Fleischkiste zu bekommen?",a="Ihr könnt Euch in die Höhle schleichen, während Old Icebeard auf Beutezug ist, und die Truhe zurückholen, ohne gegen ihn zu kämpfen.",al={"an icebeard vorbeischleichen","muss icebeard getötet werden"}},{q="Wo befindet sich das gestohlene Versteck?",a="Die gestohlene Fleischtruhe befindet sich tief in Old Icebeards Berghöhle, in den Hügeln nahe MacGranns Lager in Dun Morogh.",al={"wo ist die höhle","icebeard höhle standort"}}},fx={ceb049bb={q="Warum muss Tundra MacGrann seinen Fleischschrank zurückerhalten?",a="MacGrann hat lange Tage damit verbracht, einen ganzen Monat an Rationen zu jagen und einzupökeln, um die harte kalte Jahreszeit in Dun Morogh zu überleben. Ohne dieses konservierte Fleisch droht ihm in seinem abgelegenen Lager in den Bergen der Hungertod, sobald die Winterstürme aufziehen, da sein verletztes Bein ihn daran hindert, genug Wild zu jagen, um seine Wintervorräte rechtzeitig aufzustocken.",al={"warum tundra macgrann helfen","macgranns motiv","warum den fleischschrank bergen"}},["9ce729b1"]={q="Was ist MacGranns Trockenfleisch?",a="Es ist ein umfangreicher Vorrat an gepökeltem Wildbret und Fleisch, den Tundra MacGrann speziell dafür konserviert hat, den Winter in den Bergen zu überdauern. Er hat das Fleisch in einem verstärkten Thoriumschrank eingeschlossen, damit aasfressende Bären es nicht wittern können, was sich glücklicherweise als robust genug erwies, um auch den Alten Eisbart davon abzuhalten, sich darüber herzumachen.",al={"macgranns trockenfleisch","was ist macgranns trockenfleisch","inhalt macgranns fleischschrank"}}},fp="30,181,32.217.0,18.290.0,23.153.0,33.141.0,46.118.0,26.128.0,57.107.0,34.116.0"}
P.entries["quest:3120"] = {n="Tiefgrünes Siegelzeichen",s="In Laubschattental erhalten neu erwachte Nachtelfendruiden eine Aufforderung, ihre Ausbildung zu beginnen. Konservator Ilthalaine gibt ihnen das Tiefgrüne Siegelzeichen für Mardant Starkeiche in Aldrassil, wo ihre Studien der Natur und des Smaragdgrünen Traums beginnen.",h="In Laubschattental erhalten neu erwachte Nachtelfendruiden eine Aufforderung, ihre Ausbildung zu beginnen.",kw={"aldrassil","druidenlehrer","smaragdgrüner traum","ilthalaine","mardant starkeiche","laubschattental","tiefgrünes siegelzeichen"},ang={["class:Druid"]="Als Druide beginnt Ihr unter Mardant Starkeiche das förmliche Studium der Lehren des Zirkels des Cenarius. Der lange Weg zum Verständnis des Smaragdgrünen Traums liegt noch vor Euch.",["race:NightElf"]="Als Nachtelf tretet Ihr in eine uralte Tradition ein. Die Übergabe des Siegelzeichens in Aldrassil ist Euer erster Schritt auf dem Weg des Druidentums, das tief mit Eurer Kultur verwoben ist."},sec={{t="Ein Ruf ins Geäst",b="Wenn ein junger Nachtelf Talent darin zeigt, das Gleichgewicht von Laubschattental zu bewahren, verlangt der Orden eine förmliche Vorstellung. Ein Bote bringt Konservator Ilthalaine das Tiefgrüne Siegelzeichen. Sie vertraut es dem Initianden an und zeigt damit, dass der Zirkel in Aldrassil aufmerksam geworden ist und den jungen Druiden zur förmlichen Ausbildung einlädt."},{t="Zwiesprache und Traum",b="Legt Mardant Starkeiche in Aldrassil das Siegelzeichen vor, und der Initiand wird in der Gemeinschaft willkommen geheißen. Tiefere Zwiesprache mit dem Smaragdgrünen Traum und die Beherrschung von Tiergestalten liegen noch vor ihm. Vorerst wird Mardant sein erster Wegweiser und lehrt ihn, die Geister der Natur zu deuten und die ungezähmte Kraft der Wälder zu kanalisieren."}},faq={{q="Was ist das Tiefgrüne Siegelzeichen?",a="Das Tiefgrüne Siegelzeichen ist eine beschriftete Vorladung, die Konservator Ilthalaine im Auftrag von Mardant Starkeiche überbringt. Sie ruft einen Druidenneuling dazu auf, seine förmliche Ausbildung in Aldrassil zu beginnen.",al={"tiefgrünes siegelzeichen gegenstand","was ist dieses siegelzeichen","druidensiegelzeichen"}},{q="Wohin bringe ich das Tiefgrüne Siegelzeichen?",a="Bringt das Tiefgrüne Siegelzeichen zu Mardant Starkeiche, dem Druidenlehrer in Aldrassil. Der gewaltige Grabhügelbaum steht im Herzen von Laubschattental.",al={"wo ist mardant","tiefgrünes siegelzeichen abgeben","wohin gehen"}},{q="Warum erwähnt Mardant den Smaragdgrünen Traum?",a="Mardant erwähnt den Smaragdgrünen Traum, weil Druiden durch lange Schlaftrancen Kraft und Weisheit aus ihm schöpfen. Ein Neuling ist noch nicht bereit, den Traum frei zu durchwandern, wird aber mit der Zeit seine Geheimnisse ergründen.",al={"warum smaragdgrüner traum","mardant traumdialog","druidentrance"}},{q="Wer schickt Ilthalaine das Siegelzeichen?",a="Ein von Mardant Starkeiche entsandter Bote bringt Konservator Ilthalaine das Siegelzeichen. Dieser kann es dann einem vielversprechenden jungen Druiden in die Hände legen.",al={"wer hat das siegelzeichen geschickt","sie gelzeichen bote"}},{q="Was geschieht nach der Übergabe des Siegelzeichens?",a="Mardant Starkeiche wird Euer wichtigster Mentor in Laubschattental. Ihr erlernt Eure ersten druidischen Zauber und magischen Techniken, während Eure Macht wächst.",al={"was als nächstes lernen","nach dem tiefgrünen siegelzeichen"}},{q="Können auch Nichtdruiden diese Quest erhalten?",a="Nein. Das Tiefgrüne Siegelzeichen ist ausschließlich für Nachtelfendruiden bestimmt, die ihre Reise in Laubschattental beginnen. Andere Klassen erhalten eigene Vorladungen zu ihren Lehrern.",al={"nur für druiden","wer erhält das tiefgrüne siegelzeichen"}}},fp="13,239,20.315.0,23.302.0,26.176.0,34.138.0,43.198.0,34.143.0,40.144.0,34.154.0"}
P.entries["quest:3121"] = {n="Eine seltsame Anforderung",s="In Feralas schickt Euch Hexendoktor Uzer'i für ein Gebräu nach Orgrimmar.",h="In Feralas schickt Euch Hexendoktor Uzer'i für ein Gebräu nach Orgrimmar.",kw={"a strange request","die kluft der schatten","feralas","neeru fireblade","orgrimmar","schrumpfkopf","hexendoktor uzer'i"},sec={{t="Eine versprochene Bezahlung",b="Hexendoktor Uzer'i sagt, Neeru Feuerklinge in Orgrimmar habe ein Gebräu, das benötigt wird, um die Arbeit in Feralas zu beginnen. Uzer'i will noch nicht erklären, wofür es bestimmt ist. Ihr tragt einen Schrumpfkopf bei Euch, der Neeru im Tausch gegen die Kräuter versprochen wurde. Er gehörte einem armen Zwerg, dem Uzer'i im Wald begegnet ist. Neeru wartet in der Kluft der Schatten."},{t="Neerus Kräuter",b="Neeru Feuerklinge hat auf Uzer'is Lieferung gewartet. Im Gegenzug gibt Euch Neeru die Kräutermischung, die er für Uzer'is Experimente vorbereitet hat."}},faq={{q="Wer vergibt A Strange Request?",a="Hexendoktor Uzer'i schickt Euch mit einem Schrumpfkopf nach Orgrimmar.",al={"wer gibt a strange request","wer startet dies","questgeber a strange request"}},{q="Wo ist Neeru Feuerklinge?",a="Neeru Feuerklinge befindet sich in der Kluft der Schatten in Orgrimmar.",al={"wo ist neeru fireblade","wo muss ich hin","abgabeort für den schrumpfkopf"}},{q="Wessen Kopf ist der Schrumpfkopf?",a="Uzer'i sagt, der Kopf habe einem armen Zwerg gehört, den er im Wald gefunden hat.",al={"wessen kopf ist das","identität des schrumpfkopfs","wer war der zwerg"}},{q="Warum schickt Uzer'i Neeru einen Schrumpfkopf?",a="Uzer'i hat Neeru den Kopf im Tausch gegen die Kräuter versprochen und braucht das Gebräu, das Neeru zusammengemischt hat.",al={"warum will neeru den kopf","neeru fireblade handel"}},{q="Was folgt auf A Strange Request?",a="Die Questreihe geht mit Return to Hexendoktor Uzer'i weiter.",al={"was kommt als nächstes","folgequest nach a strange request"}}},fp="17,72,18.320.0,13.134.1,28.64.0,25.56.0,32.69.0,46.105.0,31.55.0"}
P.entries["quest:3122"] = {n="Kehrt zu Hexendoktor Uzer'i zurück",s="Neeru Feuerklinge schickt Euch mit Kräutern und der Nachricht, dass er mit dem Schrumpfkopf zufrieden ist, zu Hexendoktor Uzer'i in Feralas.",h="Neeru Feuerklinge schickt Euch mit Kräutern und der Nachricht, dass er mit dem Schrumpfkopf zufrieden ist, zu...",kw={"feralas","kräuterbeutel","muisek-gefäß","schrumpfkopf","hexendoktor uzer'i"},sec={{t="Die Kräuter kehren zurück",b="Nach „A Strange Request“ gibt Neeru Feuerklinge Euch Kräuter für Hexendoktor Uzer'i in Feralas. Bringt sie zu Uzer'i und sagt ihm, dass Neeru mit dem Schrumpfkopf zufrieden ist."},{t="Das Ritual beginnt",b="Hexendoktor Uzer'i sagt, die Kräuter seien genau das, was er zur Vorbereitung des Muisek-Gefäßes braucht. Er hofft, dass sich seine neuesten Beschwörungsformeln als so mächtig erweisen, wie er erwartet hat. Er bittet Euch zu warten, während er das Ritual durchführt und die Kräuter anwendet."}},faq={{q="Wer gibt die Kräuter für Hexendoktor Uzer'i?",a="Neeru Feuerklinge gibt Euch die Kräuter, nachdem Ihr ihm den Schrumpfkopf gebracht habt.",al={"wo beginnt diese quest","wer hat die kräuter gegeben"}},{q="Wohin werden die Kräuter gebracht?",a="Die Kräuter werden zu Hexendoktor Uzer'i in Feralas gebracht.",al={"was sind das für kräuter","wohin den kräuterbeutel bringen"}},{q="War Neeru mit dem Schrumpfkopf zufrieden?",a="Ja. Neeru ist mit dem Schrumpfkopf zufrieden und bittet Euch, Uzer'i das mitzuteilen.",al={"war neeru mit dem kopf zufrieden","neeru schrumpfkopf tausch"}}},fp="29,124,17.168.0,17.226.1,43.74.0,22.47.0,41.75.0"}
P.entries["quest:3123"] = {n="Das Gefäß wird getestet",s="Ihr kehrt zu Hexendoktor Uzer'i zurück, der das Ritual und Eure Fertigkeiten prüft. Nun müsst Ihr zehn Wildkin im Hinterland fangen und sie mit dem Gefäß nach Feralas zurückbringen.",h="Ihr kehrt zu Hexendoktor Uzer'i zurück, der das Ritual und Eure Fertigkeiten prüft.",kw={"elune","feralas","hinterland","muisek","eulenbestie","uzer'i","gefäß","wildkin"},sec={{t="Ein Gefäß fürs Hinterland",b="Hexendoktor Uzer'i prüft das gerade von Euch durchgeführte Ritual und Eure eigenen Fertigkeiten. Das Gefäß, das Uzer'i Euch gibt, kann eine Kreatur schrumpfen und darin einschließen. Ihr reist ins Hinterland, um Wildkin zu finden. Ihre Art gehörte einst Elune, der Göttin der Nachtelfen, als Haustiere. Uzer'i nennt die bösartigen, primitiven, wilden Eulenbestien als Eure Beute. Fangt zehn, bevor ihre Geister entgleiten, und kehrt dann mit ihnen und dem Gefäß zu Uzer'i nach Feralas zurück."},{t="Danach",b="Hexendoktor Uzer'i erklärt, was geschieht, wenn eine Kreatur eines gewaltsamen Todes stirbt. Ihr Muisek kann entkommen und nach Rache suchen. Eine gefallene Kreatur zu schrumpfen, wie Ihr es getan habt, hindert das Muisek daran zu entkommen. Uzer'i sagt nun, dass Ihr das Gefäß nach Belieben nutzen dürft."}},faq={{q="Wer vergibt „Das Gefäß wird getestet“?",a="Hexendoktor Uzer'i gibt Euch die Aufgabe und überreicht Euch das Gefäß.",al={"questgeber das gefäß wird getestet","wer vergibt das gefäß wird getestet"}},{q="Wo sind die Wildkin?",a="Uzer'i schickt Euch ins Hinterland, um Wildkin zu finden.",al={"wo wildkin finden","wildkin fundort"}},{q="Welche Kreaturen sind die Ziele?",a="Die Ziele sind Wildkin, bösartige, primitive oder wilde Eulenbestien. Uzer'i will zehn.",al={"welche wildkin töten","das gefäß wird getestet ziele"}},{q="Welche Verbindung besteht zwischen den Wildkin und Elune?",a="Uzer'i sagt, dass Wildkin einst Elune, der Göttin der Nachtelfen, als Haustiere gehörten.",al={"wildkin elune hintergrund","warum wildkin"}},{q="Was kann das Gefäß?",a="Das Gefäß schrumpft eine gefallene Kreatur und schließt sie darin ein, sodass ihr Geist nicht entkommen kann.",al={"wie funktioniert das muisekgefäß","kraft des gefäßes"}},{q="Was folgt auf „Das Gefäß wird getestet“?",a="Die Questreihe geht mit „Hippogryph Muisek“ weiter.",al={"folgequest das gefäß wird getestet","was kommt nach das gefäß wird getestet"}}},fp="18,171,28.432.0,9.242.1,29.61.0,22.52.0,32.82.0,47.75.0,23.95.0,32.43.0"}
P.entries["quest:3124"] = {n="Muisek von Hippogryphen",s="In der oberen Wildnis tragen Frayfeather-Hippogryphen Geister in sich, die Ihr für Uzer'i einfangen sollt. Ihr Muisek kann entkommen, wenn Ihr nicht schnell handelt.",h="In der oberen Wildnis tragen Frayfeather-Hippogryphen Geister in sich, die Ihr für Uzer'i einfangen sollt.",kw={"feralas","frayfeather","die obere wildnis","muisek von hippogryphen","muisek-gefäß","hexendoktor uzer'i"},sec={{t="Treue Gefährten",b="Hexendoktor Uzer'i vertraut Euch das Gefäß an und bittet Euch, den Geist einer anderen Kreatur einzufangen. Hippogryphen sind seit Langem Gefährten der Nachtelfen, und ihre Geister sind treu und standhaft. Ihr braucht zehn Frayfeather-Hippogryphen beliebiger Art. Tötet jeden einzelnen, schrumpft ihn dann schnell mit dem Gefäß und fangt ihn damit ein, um sein Muisek zu bewahren. Uzer'i verortet sie in der oberen Wildnis, südlich des Lagers."},{t="Uzer'is Warnung",b="Hexendoktor Uzer'i warnt, dass das Muisek eines erschlagenen Tieres entkommen und die Gestalt einer größeren Kreatur annehmen könnte. Dann ließe seine Rache keinen Frieden zu. Die Arbeit ist gefährlich, und Uzer'i sagt, Ihr habt sie erneut gut erledigt."}},faq={{q="Wer schickt Euch los, um Hippogryphen einzufangen?",a="Hexendoktor Uzer'i schickt Euch nach Testing the Vessel los, um Hippogryphen einzufangen.",al={"muisek von hippogryphen questgeber","wer vergibt muisek von hippogryphen","wo gibt es muisek von hippogryphen"}},{q="Wo sind die Frayfeather-Hippogryphen zu finden?",a="Uzer'i verortet die Frayfeather-Hippogryphen in der oberen Wildnis, südlich des Lagers.",al={"wo sind frayfeather-hippogryphen","hippogryphen fundort feralas","wo findet man hippogryphen in feralas"}},{q="Warum will Hexendoktor Uzer'i die Geister von Hippogryphen?",a="Hippogryphen sind alte Gefährten der Nachtelfen, und Uzer'i sagt, ihre Geister seien treu und standhaft. Er will ihr Muisek bewahren lassen.",al={"warum hippogryphen","warum muisek von hippogryphen einfangen","uzeri hippogryphen begründung"}},{q="Wie wird das Muisek eingefangen?",a="Tötet einen Frayfeather-Hippogryphen, schrumpft ihn dann schnell mit dem Muisek-Gefäß und fangt ihn damit ein. Zehn werden verlangt, gleich welcher Art.",al={"wie benutzt man das muisek-gefäß","wie erhält man muisek von hippogryphen","frayfeather-muisek einfangen"}},{q="Welcher Schritt kommt in dieser Reihe davor?",a="Testing the Vessel kommt davor. Dort habt Ihr bewiesen, dass Ihr vertrauenswürdig seid und mit dem Muisek-Gefäß umgehen könnt.",al={"muisek von hippogryphen voraussetzung","vorherige quest muisek von hippogryphen","voraussetzung für muisek von hippogryphen"}}},fp="17,138,16.400.0,16.214.1,37.78.0,44.84.0,53.138.0,27.118.0,41.102.0"}
P.entries["quest:3125"] = {n="Muisek von Feendrachen",s="Westlich von Hexendoktor Uzer'i sucht die Horde nach den Geistern von Feendrachen. Grimmlingflitzer und Feendrachen tragen die Stärke in sich, die Uzer'i einzufangen hofft.",h="Westlich von Hexendoktor Uzer'i sucht die Horde nach den Geistern von Feendrachen.",kw={"muisek von feendrachen","feralas","hippogryph muisek","horde","muisek-gefäß","grimmlingflitzer","feendrache","treant muisek","hexendoktor uzer'i"},sec={{t="Zarter Schein, starker Geist",b="Hexendoktor Uzer'i sieht Stärke in Feendrachen, auch wenn sie zart wirken. Sie sind seit Langem Verbündete der Nachtelfen, und Uzer'i möchte, dass die Horde an ihrer Macht teilhat. Uzer'i gibt Euch ein Muisek-Gefäß und schickt Euch nach Westen. Erschlagt acht Grimmlingflitzer oder Feendrachen und benutzt dann das Gefäß bei jedem gefallenen Feendrachen, um seinen Geist zu schrumpfen und einzufangen."},{t="Zurück an Uzer'is Seite",b="Wenn Ihr mit den eingefangenen Geistern zurückkehrt, dankt Euch Hexendoktor Uzer'i. Die Horde kann nun auf die spirituelle Macht der Feendrachen zurückgreifen. Uzer'i hofft, dass Ihr einer weiteren Aufgabe zustimmen werdet."}},faq={{q="Warum will Hexendoktor Uzer'i die Geister von Feendrachen?",a="Uzer'i sagt, dass Feendrachen zerbrechlich aussehen, aber einen mächtigen Geist in sich tragen. Sie sind seit Langem Verbündete der Nachtelfen, und Uzer'i möchte, dass auch die Horde von ihrer Stärke profitiert.",al={"warum feendrachen","muisek von feendrachen zweck","warum grimmlingflitzer töten"}},{q="Wo sind die Feendrachen zu finden?",a="Die Feendrachen befinden sich westlich von Hexendoktor Uzer'i.",al={"wo sind grimmlingflitzer","grimmlingflitzer fundort","feendrachen fundort feralas"}},{q="Welche Kreaturen liefern dieses Muisek?",a="Grimmlingflitzer und Feendrachen liefern das Muisek. Ihr müsst acht von ihnen töten und einfangen.",al={"welche gegner für muisek","was für muisek von feendrachen töten","muisek von feendrachen ziele"}},{q="Was muss mit den gefallenen Kreaturen geschehen?",a="Benutzt das Muisek-Gefäß bei jedem gefallenen Feendrachen, um ihn zu schrumpfen und sein Muisek einzufangen.",al={"wie muisek von feendrachen erhalten","wie funktioniert das muisek-gefäß","muisek einfangen"}},{q="Wo steht dieser Schritt in der Reihe von Uzer'is Aufträgen?",a="Dieser Schritt folgt auf Hippogryph Muisek. Danach folgt Treant Muisek.",al={"welche quest kommt davor","muisek questreihe reihenfolge","was folgt auf muisek von feendrachen"}}},fp="20,152,28.356.0,21.182.1,56.177.0,38.51.0,35.97.0,42.87.0,49.62.0"}
P.entries["quest:3126"] = {n="Muisek von Treants",s="In Feralas lenkt Hexendoktor Uzer'i Eure Suche auf die umherwandernden Treants. Nach den Feendrachen schickt er Euch los, um drei Waldläufer zu finden.",h="In Feralas lenkt Hexendoktor Uzer'i Eure Suche auf die umherwandernden Treants.",kw={"feralas","muisek-gefäß","muisek von treants","treants","uzer'i","umherwandernder waldläufer"},sec={{t="Langsame Beschützer",b="Die Nachtelfen haben die Treants zu ihren Verbündeten gegen die Horde gemacht. Uzer'i sagt, sie bewegen sich langsam, doch niemand kann ihre Stärke als Beschützer leugnen. Er will diese Stärke für die Horde nutzen."},{t="Drei Waldläufer",b="Uzer'i bittet Euch, drei umherwandernde Waldläufer zu finden und zu töten. Sobald ein Treant fällt, verwendet das Muisek-Gefäß, um ihn zu schrumpfen und einzufangen."},{t="Uzer'is Urteil",b="Bei Eurer Rückkehr dankt Euch Hexendoktor Uzer'i. Er sagt, die Sammlung von Muisek sei beinahe vollständig."}},faq={{q="Wer schickt Abenteurer auf die Jagd nach den Treants?",a="Hexendoktor Uzer'i schickt Euch nach den Feendrachen auf die Jagd nach den Treants.",al={"wer vergibt muisek von treants","muisek von treants questgeber","uzeri treantquest"}},{q="Warum will Hexendoktor Uzer'i Muisek von Treants?",a="Die Nachtelfen haben die Treants zu ihren Verbündeten gegen die Horde gemacht. Uzer'i will ihre schützende Kraft für die Horde nutzen.",al={"warum waldläufer töten","warum muisek von treants","uzeri treants beweggrund"}},{q="Welche Kreaturen müssen für Muisek von Treants gefunden werden?",a="Ihr müsst drei umherwandernde Waldläufer finden, die den Wald durchstreifen.",al={"welche treants töten","umherwandernde waldläufer","muisek von treants ziele"}},{q="Wie werden die Treants eingefangen?",a="Sobald ein umherwandernder Waldläufer fällt, verwendet das Muisek-Gefäß, um ihn zu schrumpfen und einzufangen.",al={"wie muisek-gefäß verwenden","waldläufer einfangen","treants schrumpfen"}},{q="Wo steht Muisek von Treants in der Reihenfolge von Uzer'is Aufträgen?",a="Muisek von Treants folgt auf Faerie Dragon Muisek. Mountain Giant Muisek kommt als Nächstes.",al={"muisek von treants questreihe","was kommt nach faerie dragon muisek","nächste quest nach muisek von treants"}}},fp="13,144,15.196.0,20.136.0,16.101.1,40.78.0,48.128.0,47.67.0,29.85.0,53.77.0"}
P.entries["quest:3127"] = {n="Muisek von Bergriesen",s="Im Nordwesten von Feralas begegnet Ihr den letzten Kreaturen, deren Macht Hexendoktor Uzer'i nutzen will: Bergriesen.",h="Im Nordwesten von Feralas begegnet Ihr den letzten Kreaturen, deren Macht Hexendoktor Uzer'i nutzen will...",kw={"brennende legion","klippenriese","feralas","landläufer","muisek von bergriesen","muisekgefäß","treant muisek","hexendoktor uzer'i"},sec={{t="Riesen auf felsigem Boden",b="Hexendoktor Uzer'i sagt, die Bergriesen seien aus den Bergen herabgestiegen, um den Nachtelfen zu helfen, als die Brennende Legion erstmals in die Welt kam. Ihre gewaltige Größe zeichnet sie aus, und felsiger Boden erzittert unter ihren Schritten. Uzer'i hofft, Macht von diesem Ausmaß nutzbar zu machen.\n\nSieben Landläufer oder Klippenriesen müssen fallen. Dann kann das Muisekgefäß sie schrumpfen und einfangen."},{t="Uzer'is Prahlerei",b="Wenn Ihr zurückkehrt, spricht Hexendoktor Uzer'i darüber, was die gesammelten Materialien ermöglichen. Uzer'i behauptet, damit die Geister der Kreaturen für immer in allem bannen zu können, was Uzer'i sich wünscht."}},faq={{q="Wer verlangt nach dem Muisek der Bergriesen?",a="Hexendoktor Uzer'i verlangt nach dem Muisek der Bergriesen. Uzer'i nennt es Eure letzte Bitte.",al={"questgeber","wer vergibt muisek von bergriesen","uzeri quest"}},{q="Wo befinden sich die Bergriesen?",a="Uzer'i schickt Euch nach Nordwesten durch Feralas, wo die Bergriesen durch felsiges Gelände streifen.",al={"bergriesen fundort","wo sind landläufer","klippenriesen fundort"}},{q="Warum sind Bergriesen hier?",a="Laut Uzer'i stiegen die Bergriesen aus den Bergen herab, um den Nachtelfen zu helfen, als die Brennende Legion erstmals in die Welt kam.",al={"warum sind riesen hier","bergriesen hintergrundgeschichte feralas"}},{q="Welche Kreaturen liefern das benötigte Muisek?",a="Landläufer und Klippenriesen liefern das Muisek. Sieben werden benötigt, und das Muisekgefäß schrumpft jeden gefallenen Riesen und fängt ihn ein.",al={"was für muisek töten","welche riesen zählen"}},{q="Was kommt in der Abfolge davor?",a="Treant Muisek kommt davor, und Weapons of Spirit ist danach aufgeführt.",al={"vorherige quest","muisek questreihenfolge"}}},fp="21,108,26.366.0,14.175.1,41.92.0,38.88.0,29.144.0,44.129.0,39.74.0"}
P.entries["quest:3128"] = {n="Natürliche Materialien",s="In Camp Mojache benötigt Hexendoktor Uzer'i natürliche Materialien für ein Vorhaben. Die Materialien stammen von Treants, Bergriesen, Feendrachen, Eulenbestien und Hippogryphen und werden neben den anderen Prüfungen gesammelt.",h="In Camp Mojache benötigt Hexendoktor Uzer'i natürliche Materialien für ein Vorhaben.",kw={"camp mojache","verkrustete mineralien","feralas","metallische fragmente","muisek","natürliche materialien","zähe sehnen","zersplitterter holzscheit","hinterland","hexendoktor uzer'i"},sec={{t="Sammeln für den Hexendoktor",b="Nachdem Ihr zu Hexendoktor Uzer'i zurückgekehrt seid, erwartet Euch neben den anderen Prüfungen eine weitere Materialliste. Bringt zwei zersplitterte Holzscheite von einem Treant in Feralas. Bergriesen und Feendrachen weiter westlich tragen sechs Stück verkrustete Mineralien bei sich. Eulenbestien im Hinterland oder Hippogryphen in Feralas liefern zwanzig Stück zähe Sehnen. Jede dieser Kreaturen kann die vierzig benötigten metallischen Fragmente liefern."},{t="Uzer'is Urteil",b="Hexendoktor Uzer'i ist erfreut, wenn Ihr die Materialien zurückbringt. Zusammen mit dem Muisek sollten sie die Ergebnisse bringen, die er sich gewünscht hat."}},faq={{q="Wer verlangt diese natürlichen Materialien?",a="Hexendoktor Uzer'i in Camp Mojache verlangt sie.",al={"wer vergibt natürliche materialien","questgeber natürliche materialien","wo beginnt natürliche materialien"}},{q="Welche Kreaturen haben die zersplitterten Holzscheite?",a="Ein Treant in Feralas liefert die zwei zersplitterten Holzscheite, die Ihr benötigt.",al={"woher zersplitterte holzscheite bekommen","wer lässt zersplitterte holzscheite fallen","quelle für zersplitterte holzscheite"}},{q="Wo lassen sich verkrustete Mineralien sammeln?",a="Bergriesen und Feendrachen weiter westlich tragen die sechs verkrusteten Mineralien bei sich, die Ihr benötigt.",al={"wie verkrustete mineralien bekommen","quelle für verkrustete mineralien","wer lässt verkrustete mineralien fallen"}},{q="Welche Tiere liefern die zähen Sehnen?",a="Eulenbestien im Hinterland oder Hippogryphen in Feralas liefern die zwanzig Stück zähe Sehnen, die Ihr benötigt.",al={"beute zähe sehnen","wo zähe sehnen finden","wer hat zähe sehnen"}},{q="Woher stammen die metallischen Fragmente?",a="Die vierzig metallischen Fragmente können von Treants, Bergriesen, Feendrachen, Eulenbestien oder Hippogryphen stammen.",al={"quelle für metallische fragmente","wie metallische fragmente bekommen","wer lässt metallische fragmente fallen"}},{q="Was ging dieser Bitte voraus?",a="Diese Bitte folgt auf „Return to Hexendoktor Uzer'i“.",al={"voraussetzung natürliche materialien","vorherige quest natürliche materialien","was führt zu natürliche materialien"}}},fp="17,206,30.401.0,16.134.1,37.50.0,40.59.0,41.86.0,41.109.0,38.110.0,30.51.0"}
P.entries["quest:3129"] = {n="Waffen des Geistes",s="Hexendoktor Uzer'i bereitet in Feralas Waffen für Euch vor. Die Arbeit braucht Zeit, also wartet Ihr, während die Geister gebunden werden.",h="Hexendoktor Uzer'i bereitet in Feralas Waffen für Euch vor.",kw={"feralas","muisek","geisterwaffen","waffen des geistes","hexendoktor uzer'i"},sec={{t="Ein Moment Geduld",b="Hexendoktor Uzer'i hat die Materialien und die Geister, die Ihr gefangen habt. Waffen mit Muisek zu erfüllen, ist harte Arbeit, also bittet Uzer'i Euch zu warten, während die Waffen vorbereitet werden."},{t="Wenn das Warten endet",b="Hexendoktor Uzer'i kehrt mit Waffen zurück, aus denen Ihr wählen könnt. Die Geister der gefangenen Kreaturen sind für immer darin eingeschlossen, und Ihr könnt ihre Energie wie Eure eigene nutzen."}},faq={{q="Wer steht hinter Waffen des Geistes?",a="Hexendoktor Uzer'i hat Euch ausgeschickt, um Muisek zu sammeln. Dies folgt auf Mountain Giant Muisek.",al={"wer vergibt waffen des geistes","waffen des geistes questgeber","uzeri quest"}},{q="Was tut Hexendoktor Uzer'i während dieses Schritts?",a="Uzer'i arbeitet daran, die gefangenen Muisek in Waffen zu binden. Die Arbeit ist schwierig, also bittet Uzer'i Euch zu warten, während die Waffen vorbereitet werden.",al={"was geschieht in waffen des geistes","was tut uzeri"}},{q="Was wird benötigt, bevor Uzer'i beginnen kann?",a="Uzer'i hat die benötigten Materialien und die Geister, die Ihr gefangen habt, also kann die Arbeit beginnen.",al={"anforderungen für waffen des geistes","voraussetzungen für waffen des geistes"}}},fp="17,122,19.171.0,18.168.1,32.82.0,50.136.0,39.84.0"}
P.entries["quest:313"] = {n="Zum Zusehen verdammt",s="In Stahlrosts Depot nahe Kharanos schickt Euch Pilot Steinsegel nach Westen, um im Graufelsbau Wendigos zu jagen. Ihre dicken Pelze sollen seine Belagerungsmaschine, den Trollpflüger, warm halten.",h="In Stahlrosts Depot nahe Kharanos schickt Euch Pilot Steinsegel nach Westen, um im Graufelsbau Wendigos zu...",kw={"dun morogh","der graufelsbau","kharanos","pilot steinsegel","trollpflüger","wendigo","wendigomähne"},ang={["profession:Engineering"]="Wenn Ihr zwergische Belagerungstechnik schätzt, wisst Ihr, dass schwere Maschinen bei Minusgraden ausgeklügelte Methoden brauchen, um warm zu bleiben.",["race:Dwarf"]="Als junger Mountaineer oder Abenteurer aus Eisenschmiede gehört es zur örtlichen Bewährungsprobe, sich den Wendigos im Graufelsbau zu stellen.",["race:Gnome"]="Wenn Ihr unter den Zwergen rund um Kharanos lebt, könnt Ihr helfen, Eisenschmiedes schwere gepanzerte Maschinen auszurüsten."},sec={{t="Eine Mutprobe",b="Steinsegel stellt Neulinge auf die Probe, bevor er ihnen die Arbeit anvertraut. Ein gewaltiger Belagerungspanzer lässt sich in eisiger Bergluft nur schwer bedienen. Dafür braucht es eiserne Nerven und eine robuste Konstitution. Stellt Euch den einheimischen Bestien in den gefrorenen Hügeln, um zu beweisen, dass Ihr beides besitzt."},{t="Behaglichkeit im Trollpflüger",b="Die bittere Kälte Dun Moroghs dringt durch die enge, eisenbeschlagene Kabine des Trollpflügers. Steinsegel will dicke Wendigomähnen für einen warmen, strapazierfähigen Teppich auf dem Deck der Maschine. Die Jagd hilft auch, die örtlichen Bestien in Schach zu halten."}},faq={{q="Wer ist Pilot Steinsegel?",a="Pilot Steinsegel ist ein zwergischer Belagerungsmaschinenfahrer, der vor Kharanos in Dun Morogh stationiert ist. Er steuert den Trollpflüger, eine gepanzerte Kriegsmaschine, und ist stolz auf seine eisernen Nerven und sein mechanisches Handwerk.",al={"pilot steinsegel","wer vergibt die quest","wer ist steinsegel"}},{q="Wo liegt der Graufelsbau?",a="Zum Zusehen verdammt liegt in den schneebedeckten Bergen direkt westlich von Kharanos. Seine Höhlen bieten den bösartigen Wendigos Dun Moroghs Unterschlupf.",al={"graufelsbau lage","wo ist die wendigohöhle","wie den graufelsbau finden"}},{q="Warum will Steinsegel Wendigomähnen?",a="Steinsegel will Wendigofell für einen warmen Teppich auf dem Innendeck des Trollpflügers. Das Sammeln der Pelze stellt zugleich den Mut eines Abenteurers auf die Probe.",al={"warum wendigomähnen","zweck der mähnen","wofür sind die mähnen"}},{q="Was ist der Trollpflüger?",a="Der Trollpflüger ist Pilot Steinsegels persönliche zwergische Belagerungsmaschine. Sein Name spiegelt den Konflikt zwischen den Zwergen aus Eisenschmiede und den feindseligen Frostmane-Trollen in den umliegenden Felsklippen wider.",al={"trollpflüger","steinsegels panzer","was ist der trollpflüger"}},{q="Welche Kreaturen bewohnen den Graufelsbau?",a="Wilde Wendigos bewohnen den Graufelsbau. Diese ungezähmten, affenartigen Bestien sind in Dun Moroghs verschneiten Höhen heimisch und verteidigen ihr Revier erbittert.",al={"monster im graufelsbau","was lebt im graufelsbau"}},{q="Sind die Wendigos eine Gefahr für Kharanos?",a="Wendigos organisieren nur selten Angriffe wie die Frostmane-Trolle. Doch ihre brutale Wildheit und die Nähe zu den Hauptstraßen gefährden Reisende und örtliche Handwerker.",al={"sind wendigos eine bedrohung","wendigo gefahr"}}},fx={["9edb896b"]={q="Wofür werden die Wendigomähnen verwendet?",a="Pilot Steinsegel will die dicken, zotteligen Mähnen der Wendigos aus The Grizzled Den für einen sehr praktischen Luxus für Zwerge: die Inneneinrichtung. Eine massive Belagerungsmaschine wie den Trollpflug bei der beißenden Kälte von Dun Morogh zu bedienen, lässt den Metalldeckboden unter den Füßen gefrieren. Steinsegel plant, die geernteten Mähnen zu einem warmen, schweren Teppich zusammenzunähen, um die Kabine des Trollpflugs während langer Patrouillen gemütlicher zu machen.",al={"nutzen wendigomähne","wofür ist wendigomähne","warum wendigomähnen"}},["72b90979"]={q="Warum schickt Pilot Steinsegel Euch anstatt die Mähnen selbst zu holen?",a="Steinsegel ist Pilot einer Belagerungsmaschine, und die Instandhaltung einer Eisenmaschine wie des Trollpflugs sowie deren Verteidigungsbereitschaft in Kharanos erfordern seine volle Aufmerksamkeit. Die Jagd auf wendige, wilde Wendigos in engen, zugefrorenen Höhlengängen ist keine Arbeit, die für eine massive Kriegsmaschine geeignet ist. Steinsegel betrachtet die Aufgabe auch als eine offene Herausforderung, um zu sehen, ob Ihr den Mut, das Rückgrat und die Nerven besitzt, die man von den Verteidigern von Dun Morogh verlangt.",al={"warum ich steinsegel","warum braucht steinsegel hilfe","warum mähnen nicht selbst holen"}}},fp="16,162,14.246.0,30.212.0,23.192.0,34.127.0,38.128.0,18.177.0,48.148.0,39.161.0"}
